def _lifecycle_sanitize_diagnostic(value: object) -> str:
    diagnostic = " ".join(str(value).split())[:512]
    diagnostic = re.sub(
        r"(?i)\b[A-Z]:[\\/][^\s;]+",
        "<redacted-path>",
        diagnostic,
    )
    return diagnostic


