class LifecycleOutcomeComposer:
    """Transport-neutral owner of one primary and the fixed cleanup slots."""

    def __init__(self):
        self._result: object | None = None
        self._primary: BaseException | None = None
        self._cleanup: dict[str, LifecycleCleanupFailure] = {}
        self._cleanup_occurrences: dict[str, list[tuple[LifecycleCleanupFailure, BaseException | None]]] = {}
        self._rollback = "not-needed"
        self._outward_failure: BaseException | None = None

    def propose_result(self, result: object) -> None:
        self._result = result

    def capture_primary(self, primary: BaseException) -> None:
        if self._primary is None:
            self._primary = primary

    def record_cleanup(
        self,
        *,
        phase: str,
        failure_id: str,
        resource: str | None,
        diagnostic: object,
        cause: BaseException | None = None,
    ) -> None:
        if phase not in LIFECYCLE_CLEANUP_PHASES:
            raise ValueError(f"unknown lifecycle cleanup phase: {phase}")
        if phase in LIFECYCLE_REPEATABLE_CLEANUP_PHASES:
            raise ValueError(f"occurrence-owned lifecycle cleanup phase: {phase}")
        if phase in self._cleanup:
            raise ValueError(f"lifecycle cleanup phase already recorded: {phase}")
        self._cleanup[phase] = LifecycleCleanupFailure(
            phase=phase,
            failure_id=failure_id,
            resource=resource,
            diagnostic=_lifecycle_sanitize_diagnostic(diagnostic),
            cause_type=type(cause).__name__ if cause is not None else None,
        )

    def record_write_cleanup(self, *, phase: str, failure_id: str, resource: str | None,
                             diagnostic: object, cause: BaseException | None = None) -> None:
        if phase not in LIFECYCLE_WRITE_CLEANUP_PHASES:
            raise ValueError(f"unknown write cleanup phase: {phase}")
        self._record_cleanup_occurrence(phase=phase, failure_id=failure_id, resource=resource,
            diagnostic=diagnostic, cause=cause)

    def record_rollback_action(self, *, failure_id: str, resource: str | None,
                               diagnostic: object, cause: BaseException | None = None) -> None:
        self._record_cleanup_occurrence(phase="rollback-action", failure_id=failure_id,
            resource=resource, diagnostic=diagnostic, cause=cause)

    def _record_cleanup_occurrence(self, *, phase, failure_id, resource, diagnostic, cause):
        record = LifecycleCleanupFailure(
            phase=phase, failure_id=failure_id, resource=resource,
            diagnostic=_lifecycle_sanitize_diagnostic(diagnostic),
            cause_type=type(cause).__name__ if cause is not None else None,
        )
        self._cleanup_occurrences.setdefault(phase, []).append((record, cause))

    def _cleanup_occurrence_entry(self, phase: str) -> LifecycleCleanupFailure:
        occurrences = self._cleanup_occurrences[phase]
        pieces = []
        for index, (record, cause) in enumerate(occurrences, 1):
            codes = " ".join(f"{name}={getattr(cause, name)}" for name in ("errno", "winerror")
                             if cause is not None and getattr(cause, name, None) is not None)
            pieces.append(_lifecycle_sanitize_diagnostic(
                f"[{index}] {record.failure_id} {record.resource} {record.cause_type} {codes}: {record.diagnostic}; {cause}"
            ))
        summary = f"occurrences={len(occurrences)}; "
        complete = summary + "; ".join(pieces)
        if len(complete) <= 512:
            diagnostic = complete
        else:
            omitted = len(occurrences)
            for index in range(len(pieces)):
                prefix = summary + "; ".join(pieces[:index + 1])
                suffix = f"; omitted-details={len(pieces) - index - 1}"
                if len(prefix) + len(suffix) > 512:
                    break
                omitted = len(pieces) - index - 1
            suffix = f"; omitted-details={omitted}"
            diagnostic = complete[:512 - len(suffix)] + suffix
        resources = {record.resource for record, _cause in occurrences}
        types = dict.fromkeys(record.cause_type for record, _cause in occurrences if record.cause_type is not None)
        return LifecycleCleanupFailure(
            phase=phase, failure_id=occurrences[0][0].failure_id,
            resource=occurrences[0][0].resource if len(resources) == 1 else f"{len(resources)} {'rollback' if phase == 'rollback-action' else 'write'} resources",
            diagnostic=diagnostic, cause_type="|".join(types) if types else None,
        )

    def set_rollback(self, rollback: str) -> None:
        if rollback not in {"not-needed", "completed", "incomplete"}:
            raise ValueError(f"invalid rollback state: {rollback}")
        self._rollback = rollback

    @property
    def rollback_actions(self):
        return tuple(self._cleanup_occurrences.get("rollback-action", ()))

    def rollback_message(self, start=0):
        return "; ".join(f"{record.diagnostic}: {cause}" if cause is not None else record.diagnostic
                         for record, cause in self.rollback_actions[start:])

    def designate_outward_failure(self, failure: BaseException) -> None:
        if (self._primary is None or self._rollback != "incomplete" or not self.rollback_actions
                or not isinstance(failure, LifecycleError)):
            raise ValueError("outward failure lacks its primary and actual incomplete rollback")
        if self._outward_failure is not None and self._outward_failure is not failure:
            raise ValueError("outward failure is already designated")
        self._outward_failure = failure

    def finalize(self) -> LifecycleOutcomeBundle:
        cleanup = tuple(
            self._cleanup_occurrence_entry(phase) if phase in self._cleanup_occurrences else self._cleanup[phase]
            for phase in LIFECYCLE_CLEANUP_PHASES
            if phase in self._cleanup or phase in self._cleanup_occurrences
        )
        return LifecycleOutcomeBundle(
            result=self._result,
            primary=self._primary,
            cleanup_failures=cleanup,
            rollback=self._rollback,
            outward_failure=self._outward_failure,
        )

    @staticmethod
    def top_level(bundle: LifecycleOutcomeBundle) -> BaseException | None:
        if bundle.outward_failure is not None:
            return bundle.outward_failure
        if bundle.primary is not None:
            return bundle.primary
        if bundle.cleanup_failures:
            cleanup = bundle.cleanup_failures[0]
            return LifecycleError(cleanup.failure_id, cleanup.diagnostic)
        return None


def _lifecycle_diagnostic_bundle(
    bundle: LifecycleOutcomeBundle,
) -> LifecycleDiagnosticBundle:
    primary = bundle.primary
    if primary is None:
        primary_kind = "none"
        primary_failure_id = None
        primary_type = None
    elif isinstance(primary, LifecycleError):
        primary_kind = "typed"
        primary_failure_id = primary.failure_id
        primary_type = type(primary).__name__
    elif isinstance(
        primary,
        (asyncio.CancelledError, KeyboardInterrupt, SystemExit, GeneratorExit),
    ):
        primary_kind = "control-flow"
        primary_failure_id = None
        primary_type = type(primary).__name__
    else:
        primary_kind = "unexpected"
        primary_failure_id = None
        primary_type = type(primary).__name__
    selected = LifecycleOutcomeComposer.top_level(bundle)
    if bundle.outward_failure is not None:
        top_level_kind = "typed-outward"
        top_level_failure_id = selected.failure_id
    elif selected is primary and primary is not None:
        top_level_kind = f"{primary_kind}-primary"
        top_level_failure_id = primary_failure_id
    elif selected is not None:
        top_level_kind = "cleanup-only"
        top_level_failure_id = selected.failure_id
    else:
        top_level_kind = "result"
        top_level_failure_id = None
    return LifecycleDiagnosticBundle(
        primaryKind=primary_kind,
        primaryFailureId=primary_failure_id,
        primaryType=primary_type,
        topLevelKind=top_level_kind,
        topLevelFailureId=top_level_failure_id,
        rollback=bundle.rollback,
        cleanupFailures=tuple(
            LifecycleDiagnosticCleanupFailure(
                phase=record.phase,
                failureId=record.failure_id,
                resource=record.resource,
                diagnostic=record.diagnostic,
                causeType=record.cause_type,
            )
            for record in bundle.cleanup_failures
        ),
    )


class LifecycleDiagnosticObserver:
    """Concrete invocation-scoped one-shot structured diagnostic mailbox."""

    def __init__(self, *, _reject_delivery: bool = False):
        self._mutex = threading.Lock()
        self._state = "empty"
        self._correlation = None
        self._snapshot = None
        self._delivery_failure = None
        self._delivery_attempts = 0
        self._reject_delivery = bool(_reject_delivery)

    @property
    def state(self) -> str:
        with self._mutex:
            return self._state

    @property
    def snapshot(self) -> LifecycleDiagnosticBundle | None:
        with self._mutex:
            return self._snapshot

    @property
    def delivery_failure(self) -> LifecycleDiagnosticDeliveryFailure | None:
        with self._mutex:
            return self._delivery_failure

    @property
    def delivery_attempts(self) -> int:
        with self._mutex:
            return self._delivery_attempts

    def _claim(self) -> object:
        with self._mutex:
            if self._state != "empty":
                raise TypeError("diagnostic_observer must be empty")
            correlation = object()
            self._correlation = correlation
            self._state = "claimed"
            return correlation

    def _deliver(
        self,
        correlation: object,
        bundle: LifecycleOutcomeBundle,
    ) -> bool:
        with self._mutex:
            if self._state != "claimed":
                return False
            self._delivery_attempts += 1
            if correlation is not self._correlation or self._reject_delivery:
                self._state = "delivery-failed"
                self._delivery_failure = LifecycleDiagnosticDeliveryFailure(
                    failure_id="WI-LIFECYCLE-DIAGNOSTIC-DELIVERY",
                    diagnostic="lifecycle diagnostic delivery was rejected",
                )
                self._correlation = None
                return False
            self._snapshot = _lifecycle_diagnostic_bundle(bundle)
            self._state = "delivered"
            self._correlation = None
            return True

    def _mark_not_needed(self, correlation: object) -> bool:
        with self._mutex:
            if self._state != "claimed" or correlation is not self._correlation:
                return False
            self._state = "not-needed"
            self._correlation = None
            return True


LIFECYCLE_LOCK_BYTES = b"work-items-lifecycle-owner-v1\n"
LIFECYCLE_LOCK_RELATIVE = Path(".scratch") / "work-items-lifecycle-owner.lock"


def _lifecycle_file_identity(info: os.stat_result) -> tuple[int, int]:
    return info.st_dev, info.st_ino


def _lifecycle_file_snapshot_key(info: os.stat_result) -> tuple[int, ...]:
    return (
        info.st_dev,
        info.st_ino,
        info.st_mode,
        info.st_nlink,
        info.st_size,
        info.st_mtime_ns,
        info.st_ctime_ns,
    )


def _lifecycle_path_has_reparse(path: Path) -> bool:
    try:
        info = path.lstat()
    except OSError:
        return False
    return path.is_symlink() or bool(
        getattr(info, "st_file_attributes", 0)
        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
    )


def _lifecycle_unresolved_absolute(path: Path) -> Path:
    path = Path(path)
    return path if path.is_absolute() else Path.cwd() / path


def _lifecycle_reject_unreduced_reparse(
    path: Path,
    *,
    failure_id: str,
    message: str,
) -> None:
    """Inspect every caller-supplied path participant without resolving links."""
    candidate = _lifecycle_unresolved_absolute(path)
    cursor = Path(candidate.anchor)
    for part in candidate.parts[1:]:
        if part in {"", "."}:
            continue
        if part == "..":
            cursor = cursor.parent
            continue
        cursor /= part
        try:
            info = cursor.lstat()
        except FileNotFoundError:
            continue
        except OSError as exc:
            raise LifecycleError(failure_id, message) from exc
        if stat.S_ISLNK(info.st_mode) or bool(
            getattr(info, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        ):
            raise LifecycleError(failure_id, message)


