@dataclass(frozen=True)
class CapturedDirectorySnapshotV1:
    """Complete native directory observation, minted by the capture owner."""

    path: Path
    parent_chain: CapturedPathParentChain
    metadata: os.stat_result
    members: tuple[tuple[str, os.stat_result], ...]
    capture_binding: tuple = field(default=(), repr=False, compare=False)


def _directory_capture_binding(snapshot):
    return (_DIRECTORY_CAPTURE_OWNER, snapshot.path, snapshot.parent_chain.participants,
            _lifecycle_file_snapshot_key(snapshot.metadata),
            tuple((name, _lifecycle_file_snapshot_key(metadata)) for name, metadata in snapshot.members))


def _captured_observations_equivalent(previous, current) -> bool:
    """Compare physical observations without changing their complete retained values."""
    if isinstance(previous, CapturedDirectorySnapshotV1) and isinstance(current, CapturedDirectorySnapshotV1):
        return _directory_capture_binding(previous) == _directory_capture_binding(current)
    if isinstance(previous, CapturedFileSnapshot) and isinstance(current, CapturedFileSnapshot):
        return replace(previous, require_single_link=current.require_single_link) == current
    return False


