ROOT_CONTRACT_FILE = "root-contract.json"
ROOT_CONTRACT_SCHEMA = "work-items-root-contract"
ROOT_CONTRACT_VERSION = 2
ROOT_CONTRACT_FAILURE = "WI-CATEGORY-ROOT-CONTRACT-INVALID"


def _root_contract_json_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    value: dict[str, object] = {}
    for key, item in pairs:
        if key in value:
            raise LifecycleError(
                ROOT_CONTRACT_FAILURE,
                f"root contract repeats JSON key: {key}",
            )
        value[key] = item
    return value


def _expanded_root_contract_auxiliary_roots(contract: dict[str, object]) -> dict[str, dict[str, str]]:
    """Validate the expanded v2 envelope without granting its metadata lifecycle authority."""

    def valid_path(value: object, *, direct: bool = False) -> bool:
        if not isinstance(value, str) or not value or "\\" in value or ":" in value:
            return False
        parts = value.split("/")
        if any(part in {"", ".", ".."} for part in parts):
            return False
        return not direct or len(parts) == 1

    def ordered_paths(
        value: object, field: str, *, direct: bool, kinds: set[str] | None = None
    ) -> list[str]:
        if not isinstance(value, list):
            raise LifecycleError(ROOT_CONTRACT_FAILURE, f"root contract {field} must be an array")
        paths: list[str] = []
        for entry in value:
            path = entry
            if kinds is not None:
                if (
                    not isinstance(entry, dict)
                    or set(entry) != {"path", "kind"}
                    or not isinstance(entry.get("kind"), str)
                    or entry["kind"] not in kinds
                ):
                    raise LifecycleError(ROOT_CONTRACT_FAILURE, f"root contract {field} entry is invalid")
                path = entry["path"]
            if not valid_path(path, direct=direct):
                raise LifecycleError(ROOT_CONTRACT_FAILURE, f"root contract {field} path is invalid")
            paths.append(path)
        try:
            encoded = [path.encode("utf-8") for path in paths]
        except UnicodeEncodeError as exc:
            raise LifecycleError(ROOT_CONTRACT_FAILURE, f"root contract {field} path is not UTF-8") from exc
        if encoded != sorted(set(encoded)):
            raise LifecycleError(
                ROOT_CONTRACT_FAILURE, f"root contract {field} paths must be ordered and unique"
            )
        return paths

    root_files = ordered_paths(contract["rootFiles"], "rootFiles", direct=True)
    if ROOT_CONTRACT_FILE not in root_files:
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract rootFiles omits the contract file")
    lifecycle = ordered_paths(
        contract["lifecycleRoots"], "lifecycleRoots", direct=True,
        kinds={"active-items", "archived-items"},
    )
    lifecycle_entries = contract["lifecycleRoots"]
    if lifecycle != ["active", "archive"] or [entry["kind"] for entry in lifecycle_entries] != [
        "active-items", "archived-items"
    ]:
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract lifecycle roots do not match local roots")
    registries = ordered_paths(
        contract["registries"], "registries", direct=True,
        kinds={"flat-markdown", "flat-markdown-with-month-archive"},
    )
    supported_registries = {"backlog"} | {
        category.current_root for category in CATEGORIES.values() if category.current_kind == "flat"
    }
    if set(registries) != supported_registries:
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract registries do not match local roots")
    auxiliary = ordered_paths(
        contract["auxiliaryRoots"], "auxiliaryRoots", direct=True, kinds={"flat-json"}
    )
    if len(set(lifecycle + registries + auxiliary)) != len(lifecycle + registries + auxiliary):
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract root path is declared twice")
    ordered_paths(contract["activeItemSubdirectories"], "activeItemSubdirectories", direct=True)
    ordered_paths(contract["archiveRootFiles"], "archiveRootFiles", direct=True)
    historical = ordered_paths(
        contract["historicalItemDirectoryExceptions"],
        "historicalItemDirectoryExceptions", direct=False,
    )
    if any(len(path.split("/")) < 4 or not path.startswith("archive/") for path in historical):
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract historical exception path is invalid")
    root_file_names = {name.casefold() for name in root_files}
    if any(name.casefold() in root_file_names for name in auxiliary):
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "auxiliary root collides with a declared root file")
    return {entry["path"]: {"kind": entry["kind"]} for entry in contract["auxiliaryRoots"]}


@dataclass(frozen=True)
class ProjectTopology:
    work_items: Path
    auxiliary_roots: frozenset[str]
    read_model_roots: frozenset[str] = frozenset()
    root_contract_present: bool = False

    @property
    def repository_root(self) -> Path:
        return self.work_items.parent

    @property
    def canonical_roots(self) -> frozenset[str]:
        roots = {"backlog", "active", "archive"}
        roots.update(
            category.current_root
            for category in CATEGORIES.values()
            if category.current_kind == "flat"
        )
        return frozenset(roots)

    @property
    def reserved_roots(self) -> frozenset[str]:
        return self.canonical_roots | self.read_model_roots

    @property
    def allowed_roots(self) -> frozenset[str]:
        roots = set(self.reserved_roots)
        roots.update(self.auxiliary_roots)
        return frozenset(roots)

    def assert_known_top_level_roots(self) -> None:
        if not self.work_items.is_dir():
            return
        unknown_roots = sorted(
            path.name
            for path in self.work_items.iterdir()
            if path.is_dir() and path.name not in self.allowed_roots
        )
        if unknown_roots:
            noun = "directory" if len(unknown_roots) == 1 else "directories"
            raise LifecycleError(
                "WI-CATEGORY-UNKNOWN-ROOT",
                f"unknown top-level work-items {noun}: " + ", ".join(unknown_roots)
                + ". Preserve these bytes; identify their creator/data owner and classify their format and lifecycle. "
                "The project-owned work-items/root-contract.json and work-items-root-contract documentation "
                "(shared/references/work-items-root-contract.md) define the existing Version 2 flat-json auxiliary rules. "
                "An eligible auxiliary may be declared by its owner under that contract; otherwise the owner must "
                "map or migrate it to a supported lifecycle category using admitted lifecycle semantics. "
                "This diagnostic authorizes no declaration, migration, move or deletion.",
            )

    def with_read_model_roots(self) -> ProjectTopology:
        if self.read_model_roots:
            return self
        try:
            validator = _load_agent_run_ledger().load_validator()
            historical_storage = validator.historical_artifact_disposition_storage_identity()
            historical_storage = validator.confine_legacy_projection_identifier(
                historical_storage,
                failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID",
            )
        except (FileNotFoundError, ImportError, OSError):
            # Standalone checker bundles intentionally omit the optional
            # lifecycle writer and retain their legacy category set.
            return self
        except (AttributeError, TypeError, ValueError) as exc:
            raise LifecycleError(
                "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
                "historical disposition storage identity is unavailable or invalid",
            ) from exc
        return ProjectTopology(
            work_items=self.work_items,
            auxiliary_roots=self.auxiliary_roots,
            read_model_roots=frozenset({historical_storage}),
            root_contract_present=self.root_contract_present,
        )


def _verify_project_binding_evidence(evidence: tuple, failure_id: str) -> None:
    for kind, value in evidence:
        if kind == "file":
            _verify_captured_file(value, failure_id)
        elif kind == "chain":
            _verify_captured_parent_chain(value, failure_id)
        elif kind == "archive":
            value.verify()
        elif kind == "node":
            _verify_structural_node(value, failure_id)
        elif kind == "intent":
            _verify_captured_file(value[1], failure_id)
        elif kind == "absent":
            _lifecycle_reject_unreduced_reparse(value, failure_id=failure_id,
                message="root acquisition absence became unsafe")
            if os.path.lexists(value):
                raise LifecycleError(failure_id, "root acquisition absence changed")
        elif kind == "integrity-failure":
            if not isinstance(value, tuple) or len(value) != 3 or not isinstance(value[1], BaseException):
                raise LifecycleError(failure_id, "invalid retained integrity failure")
            raise value[1]
        elif kind == "owned-effect":
            if (type(value) is not _PreparedLifecycleEffect or value.forward_evidence is None
                    or value.transaction is None or value.process is None or value.thread is None):
                raise LifecycleError(failure_id, "invalid completed native effect")
        elif kind == "membership":
            path, names = value
            try:
                actual = tuple(sorted(child.name for child in path.iterdir()))
            except OSError as exc:
                raise LifecycleError(failure_id, "root acquisition membership unavailable") from exc
            if actual != names:
                raise LifecycleError(failure_id, "root acquisition membership changed")
        else:
            raise LifecycleError(failure_id, "invalid root acquisition evidence")


def _record_project_absence_at(path: Path, evidence: list, failure_id: str) -> None:
    evidence.append(("absent", path))
    parent = path.parent
    while not os.path.lexists(parent):
        parent = parent.parent
    evidence.append(("chain", _capture_path_parent_chain(parent / ".identity-observation", failure_id)))


def _observe_project_path_at(path: Path, expected_kind: str, evidence: list,
    failure_id: str):
    _lifecycle_reject_unreduced_reparse(path, failure_id=failure_id,
        message="selected structural path is unsafe")
    try:
        info = path.lstat()
    except FileNotFoundError:
        _record_project_absence_at(path, evidence, failure_id)
        return None
    except OSError as exc:
        raise LifecycleError(failure_id, "selected structural path unavailable") from exc
    if (expected_kind == "file" and not stat.S_ISREG(info.st_mode)) or (expected_kind == "directory" and not stat.S_ISDIR(info.st_mode)):
        raise LifecycleError(failure_id, "selected structural path has an unsupported type")
    if expected_kind == "file":
        evidence.append(("node", _capture_structural_node(path, failure_id)))
    else:
        evidence.append(("chain", _capture_path_parent_chain(path / ".identity-observation", failure_id)))
    return info


def _project_identity_children_at(path: Path, evidence: list, failure_id: str) -> tuple[Path, ...]:
    _lifecycle_reject_unreduced_reparse(path, failure_id=failure_id,
        message="root acquisition namespace is unsafe")
    try:
        info = path.lstat()
    except FileNotFoundError:
        _record_project_absence_at(path, evidence, failure_id)
        return ()
    except OSError as exc:
        raise LifecycleError(failure_id, "root acquisition namespace unavailable") from exc
    if not stat.S_ISDIR(info.st_mode):
        raise LifecycleError(failure_id, "root acquisition namespace is not a directory")
    chain = _capture_path_parent_chain(path / ".project-identity-observation", failure_id)
    try:
        children = tuple(sorted(path.iterdir(), key=lambda child: child.name))
    except OSError as exc:
        raise LifecycleError(failure_id, "root acquisition namespace unavailable") from exc
    evidence.extend((("chain", chain), ("membership", (path, tuple(child.name for child in children)))))
    return children


def _read_project_namespace_identity_at(work_items: Path, *, failure_id: str) -> tuple[tuple[Path, ...], tuple]:
    topology = _read_project_topology_at(work_items, root_failure_id=failure_id)
    evidence = []
    subjects = []
    if topology.root_contract_present:
        evidence.append(("file", _capture_file_snapshot(work_items / ROOT_CONTRACT_FILE, failure_id=failure_id)))
        subjects.append(work_items / ROOT_CONTRACT_FILE)
    archive_rows, _directories, _absent, archive_evidence = _archive_entity_rows_at(work_items)
    evidence.extend(archive_evidence)
    work_item = CATEGORIES["work-item"]
    slugs = set()
    for directory, kind in ((work_items / "backlog", "file"), (work_items / "active", "directory")):
        for child in _project_identity_children_at(directory, evidence, failure_id):
            _lifecycle_reject_unreduced_reparse(child, failure_id=failure_id,
                message="root acquisition subject is unsafe")
            info = child.lstat()
            if kind == "file" and child.suffix == ".md" and stat.S_ISREG(info.st_mode):
                slugs.add(child.stem)
            elif kind == "directory" and stat.S_ISDIR(info.st_mode):
                slugs.add(child.name)
    slugs.update(path.name for path, _kind, reference, _leaves in archive_rows if reference is not None)
    for slug in sorted(slugs):
        subjects.extend(_category_locations_at(work_items, work_item, slug, archive_rows=archive_rows, binding_evidence=evidence))
    for category in CATEGORIES.values():
        if category.current_kind != "flat":
            continue
        root = work_items / category.current_root
        candidates = _project_identity_children_at(root, evidence, failure_id)
        flat_slugs = {path.stem for path in candidates if path.suffix == ".md"}
        for month in _project_identity_children_at(root / "archive", evidence, failure_id):
            _lifecycle_reject_unreduced_reparse(month, failure_id=failure_id,
                message="root acquisition category archive is unsafe")
            if month.is_dir():
                flat_slugs.update(path.stem for path in _project_identity_children_at(month, evidence, failure_id)
                                  if path.suffix == ".md")
        for slug in sorted(flat_slugs):
            subjects.extend(_category_locations_at(work_items, category, slug, binding_evidence=evidence))
    for subject in subjects:
        _lifecycle_reject_unreduced_reparse(subject, failure_id=failure_id,
            message="root acquisition logical subject is unsafe")
        chain_path = subject / ".project-identity-observation" if subject.is_dir() else subject
        evidence.append(("chain", _capture_path_parent_chain(chain_path, failure_id)))
    _verify_project_binding_evidence(tuple(evidence), failure_id)
    return tuple(sorted(set(subjects))), tuple(evidence)


def _read_projection_root_binding_at(repository: Path, locator: tuple[str, str], *, failure_id: str) -> tuple[Path | None, tuple]:
    validator = _load_agent_run_ledger().load_validator()
    try:
        item = validator.confine_legacy_projection_path(repository, locator[0], prefix=("work-items",), allow_missing_leaf=True, failure_id=failure_id)
        ledger = validator.confine_legacy_projection_path(repository, locator[1], prefix=("work-items",), allow_missing_leaf=True, failure_id=failure_id)
    except ValueError as exc:
        outcome = "unavailable" if isinstance(exc.__cause__, OSError) else "unsafe"
        raise LifecycleError(failure_id, f"project root acquisition {outcome}: {exc}") from exc
    try:
        item_info = item.lstat()
    except FileNotFoundError:
        missing_evidence = []
        _record_project_absence_at(item, missing_evidence, failure_id)
        return None, tuple(missing_evidence)
    except OSError as exc:
        raise LifecycleError(failure_id, "root acquisition selected subject unavailable") from exc
    if not stat.S_ISDIR(item_info.st_mode):
        raise LifecycleError(failure_id, "root acquisition selected subject is not a directory")
    errors = []
    target = validator.classify_legacy_projection_target(item, ledger, errors, require_ledger=False)
    if target is None or errors or target[0] != repository or target[1] != locator[0] or ledger != item / "agent-runs.jsonl":
        raise LifecycleError(failure_id, "root acquisition invalid target binding: " + "; ".join(errors))
    evidence = [("chain", _capture_path_parent_chain(item / ".project-identity-observation", failure_id))]
    try:
        ledger.lstat()
    except FileNotFoundError:
        _record_project_absence_at(ledger, evidence, failure_id)
    except OSError as exc:
        raise LifecycleError(failure_id, "root acquisition ledger unavailable") from exc
    else:
        evidence.append(("file", _capture_file_snapshot(ledger, failure_id=failure_id)))
    return target[0], tuple(evidence)


def _read_selected_reference_at(work_items: Path, selected_reference: tuple[str, str], failure_id: str) -> tuple[bool, tuple]:
    category_name, slug = selected_reference
    category = CATEGORIES.get(category_name)
    if category is None:
        raise LifecycleError("WI-REFERENCE-INVALID", "unknown selected category")
    _validate_slug(slug)
    evidence = []
    if category.current_kind == "work-item":
        rows, _directories, _absent, observed = _archive_entity_rows_at(work_items)
        evidence.extend(observed)
        locations = _category_locations_at(work_items, category, slug, archive_rows=rows, binding_evidence=evidence)
        legacy = _legacy_backlog_source_at(work_items, slug, binding_evidence=evidence)
    else:
        locations = _category_locations_at(work_items, category, slug, binding_evidence=evidence)
        legacy = None
    return bool(locations or legacy is not None), tuple(evidence)


def _resolve_project_root_identity(
    root: Path, *, input_role: str = "caller-root",
    failure_id: str = "WI-LIFECYCLE-LOCK-IDENTITY",
    selected_locator: tuple[str, str] | None = None,
    selected_reference: tuple[str, str] | None = None, selected_transition: str | None = None,
    binding_evidence_out: list | None = None,
    acquisition_purpose: str = "bound-acquisition",
    acquired_input=None,
) -> tuple[Path, Path]:
    """Acquire raw semantic identity once; normalize proved roles without guessing."""
    if acquisition_purpose not in ("bound-acquisition", "topology-observation"):
        raise LifecycleError(failure_id, "unknown project root acquisition purpose")
    if input_role not in ("caller-root", "repository-root", "work-items-root"):
        raise LifecycleError(failure_id, "unknown project root input role")
    if sum(value is not None for value in (selected_locator, selected_reference, selected_transition)) > 1:
        raise LifecycleError(failure_id, "multiple selected project subjects")
    if selected_reference is not None:
        if not isinstance(selected_reference, tuple) or len(selected_reference) != 2 or selected_reference[0] not in CATEGORIES:
            raise LifecycleError("WI-REFERENCE-INVALID", "invalid selected logical subject")
        _validate_slug(selected_reference[1])

    current = _CURRENT_LIFECYCLE_TRANSACTION.get()
    selected = selected_locator is not None or selected_reference is not None or selected_transition is not None
    if acquisition_purpose == "topology-observation":
        if current is not None or input_role != "caller-root" or selected or binding_evidence_out is not None:
            raise LifecycleError(failure_id, "incompatible project topology observation context")

    if acquired_input is not None:
        _call_acquired_input(acquired_input, "verify")
        repository = acquired_input.repository_root
        work_items = repository / "work-items"
        selected_root = _lifecycle_unresolved_absolute(root)
        expected = work_items if input_role == "work-items-root" else repository
        if (selected_root != expected or current is not None and
                (repository, work_items) != (current.repository_root, current.work_items_root)):
            raise LifecycleError(failure_id, "captured project protocol role differs from native original root")
        if current is not None:
            current.verify()
        return repository, work_items

    if acquisition_purpose != "topology-observation":
        _lifecycle_reject_unreduced_reparse(Path(root), failure_id=failure_id,
            message="project root or parent contains a link or reparse point")
    resolved = Path(root).resolve()
    if input_role in ("repository-root", "work-items-root"):
        if input_role == "work-items-root" and resolved.parent / "work-items" != resolved:
            raise LifecycleError(failure_id, "invalid work-items-root protocol role")
        pair = (resolved, resolved / "work-items") if input_role == "repository-root" else (resolved.parent, resolved)
        if current is not None and pair != (current.repository_root, current.work_items_root):
            raise LifecycleError(failure_id, "proved project role differs from held scope")
        return pair
    if current is not None:
        if resolved not in (current.repository_root, current.work_items_root):
            raise LifecycleError(failure_id, "caller project root differs from held scope")
        current.verify()
        return current.repository_root, current.work_items_root
    repositories = [resolved]
    if resolved.parent / "work-items" == resolved:
        repositories.append(resolved.parent)
    if len(repositories) == 1 and not selected:
        return resolved, resolved / "work-items"
    bindings = []
    evidence = []
    for repository in repositories:
        if selected_locator is not None:
            target, observed = _read_projection_root_binding_at(repository, selected_locator, failure_id=failure_id)
            matched = target is not None
        elif selected_reference is not None:
            matched, observed = _read_selected_reference_at(repository / "work-items", selected_reference, failure_id)
        elif selected_transition is not None:
            matched, observed = _read_selected_transition_at(repository, selected_transition)
        else:
            subjects, observed = _read_project_namespace_identity_at(repository / "work-items", failure_id=failure_id)
            matched = bool(subjects)
        evidence.extend(observed)
        if matched:
            bindings.append(repository)
    if selected and not bindings:
        for repository in repositories:
            subjects, observed = _read_project_namespace_identity_at(repository / "work-items", failure_id=failure_id)
            evidence.extend(observed)
            if subjects or len(repositories) == 1:
                bindings.append(repository)
    _verify_project_binding_evidence(tuple(evidence), failure_id)
    if len(bindings) != 1:
        outcome = "ambiguous" if bindings else "unbound"
        raise LifecycleError(failure_id, f"project root acquisition {outcome}")
    if binding_evidence_out is not None:
        binding_evidence_out.extend(evidence)
    repository = bindings[0]
    return repository, repository / "work-items"


def project_root_identity(root: Path, *, input_role: str = "caller-root",
    known_work_items_root: Path | None = None) -> tuple[Path, Path, tuple]:
    """Readonly base identity using caller-owned scope equations, never a rebase."""
    failure_id = "WI-LIFECYCLE-LOCK-IDENTITY"
    if input_role not in ("caller-root", "repository-root", "work-items-root"):
        raise LifecycleError(failure_id, "unknown project root input role")
    original = _lifecycle_unresolved_absolute(Path(root))
    _lifecycle_reject_unreduced_reparse(original, failure_id=failure_id,
        message="original project root is unsafe")
    role = input_role
    evidence = []
    if known_work_items_root is not None:
        selected = _lifecycle_unresolved_absolute(Path(known_work_items_root))
        _lifecycle_reject_unreduced_reparse(selected, failure_id=failure_id,
            message="selected work-items scope is unsafe")
        lexical_base = Path(os.path.abspath(original))
        lexical_selected = Path(os.path.abspath(selected))
        if lexical_selected.parent / "work-items" != lexical_selected:
            raise LifecycleError(failure_id, "invalid selected work-items protocol role")
        if role == "caller-root":
            if lexical_selected == lexical_base:
                role = "work-items-root"
            elif lexical_selected == lexical_base / "work-items":
                role = "repository-root"
        if role != input_role:
            canonical_selected = selected.resolve()
            try:
                info = canonical_selected.lstat()
            except FileNotFoundError:
                evidence.append(("absent", canonical_selected))
                parent = canonical_selected.parent
                while not os.path.lexists(parent):
                    parent = parent.parent
                evidence.append(("chain", _capture_path_parent_chain(parent / ".project-identity-observation", failure_id)))
            except OSError as exc:
                raise LifecycleError(failure_id, "selected work-items scope unavailable") from exc
            else:
                if not stat.S_ISDIR(info.st_mode):
                    raise LifecycleError(failure_id, "selected work-items scope is not a directory")
                evidence.append(("chain", _capture_path_parent_chain(canonical_selected / ".project-identity-observation", failure_id)))
    repository, work_items = _resolve_project_root_identity(original, input_role=role,
        failure_id=failure_id, binding_evidence_out=evidence)
    _verify_project_binding_evidence(tuple(evidence), failure_id)
    return repository, work_items, tuple(evidence)


def _read_project_topology_at(work_items: Path, *, root_failure_id: str = ROOT_CONTRACT_FAILURE,
    acquisition_purpose: str = "bound-acquisition", original_root: Path | None = None,
    acquired_input=None,
) -> ProjectTopology:
    unresolved = work_items.parent
    if unresolved / "work-items" != work_items:
        raise LifecycleError(root_failure_id, "invalid canonical work-items role")
    if acquisition_purpose != "topology-observation":
        _input_reject_reparse(work_items, failure_id=root_failure_id,
            message="canonical work-items root contains a link or reparse point", acquired_input=acquired_input)
    contract_path = work_items / ROOT_CONTRACT_FILE
    try:
        _input_metadata(contract_path, acquired_input)
    except FileNotFoundError:
        return ProjectTopology(work_items=work_items, auxiliary_roots=frozenset())
    except OSError as exc:
        raise LifecycleError(
            ROOT_CONTRACT_FAILURE, "root contract entry cannot be inspected"
        ) from exc
    if acquisition_purpose == "topology-observation" and original_root is not None:
        _input_reject_reparse(original_root, failure_id=root_failure_id,
            message="project root or parent contains a link or reparse point", acquired_input=acquired_input)
    _input_reject_reparse(
        unresolved,
        failure_id=root_failure_id,
        message="repository root or parent contains a link or reparse point",
     acquired_input=acquired_input)
    _input_reject_reparse(
        work_items,
        failure_id=root_failure_id,
        message="work-items root contains a link or reparse point",
     acquired_input=acquired_input)
    _input_reject_reparse(
        contract_path,
        failure_id=ROOT_CONTRACT_FAILURE,
        message="root contract contains a link or reparse point",
     acquired_input=acquired_input)
    if not _input_is_file(contract_path, acquired_input):
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract must be a regular file")
    try:
        contract = json.loads(
            _input_text(contract_path, acquired_input, encoding="utf-8"),
            object_pairs_hook=_root_contract_json_object,
        )
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract must be valid UTF-8 JSON") from exc
    if (
        not isinstance(contract, dict)
        or contract.get("schema") != ROOT_CONTRACT_SCHEMA
        or type(contract.get("version")) is not int
        or contract.get("version") != ROOT_CONTRACT_VERSION
    ):
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract schema is invalid")
    narrow_keys = {"schema", "version", "auxiliaryRoots"}
    expanded_keys = narrow_keys | {
        "rootFiles", "lifecycleRoots", "registries", "activeItemSubdirectories",
        "archiveRootFiles", "historicalItemDirectoryExceptions",
    }
    if set(contract) == narrow_keys and isinstance(contract["auxiliaryRoots"], dict):
        auxiliary_definitions = contract["auxiliaryRoots"]
    elif set(contract) == expanded_keys:
        auxiliary_definitions = _expanded_root_contract_auxiliary_roots(contract)
    else:
        raise LifecycleError(ROOT_CONTRACT_FAILURE, "root contract schema is invalid")
    topology = ProjectTopology(
        work_items=work_items,
        auxiliary_roots=frozenset(),
        root_contract_present=True,
    ).with_read_model_roots()
    auxiliary_roots: set[str] = set()
    for name, definition in auxiliary_definitions.items():
        if not isinstance(name, str) or SLUG_RE.fullmatch(name) is None:
            raise LifecycleError(ROOT_CONTRACT_FAILURE, "auxiliary root name is not a bare root")
        if name in topology.reserved_roots:
            raise LifecycleError(
                ROOT_CONTRACT_FAILURE,
                f"auxiliary root collides with a reserved root: {name}",
            )
        if name.casefold() == "README.md".casefold():
            raise LifecycleError(
                ROOT_CONTRACT_FAILURE,
                f"auxiliary root collides with generated README: {name}",
            )
        if not isinstance(definition, dict) or definition != {"kind": "flat-json"}:
            raise LifecycleError(ROOT_CONTRACT_FAILURE, f"auxiliary root definition is invalid: {name}")
        auxiliary_path = work_items / name
        _input_reject_reparse(
            auxiliary_path,
            failure_id=ROOT_CONTRACT_FAILURE,
            message=f"auxiliary root contains a link or reparse point: {name}",
         acquired_input=acquired_input)
        if (_input_exists(auxiliary_path, acquired_input) if acquired_input is not None else auxiliary_path.exists()) and not _input_is_dir(auxiliary_path, acquired_input):
            raise LifecycleError(ROOT_CONTRACT_FAILURE, f"auxiliary root is not a directory: {name}")
        auxiliary_roots.add(name)
    topology = ProjectTopology(
        work_items=topology.work_items,
        auxiliary_roots=frozenset(auxiliary_roots),
        read_model_roots=topology.read_model_roots,
        root_contract_present=True,
    )
    topology.assert_known_top_level_roots()
    return topology


def _resolve_project_topology(root: Path, *, root_failure_id: str = ROOT_CONTRACT_FAILURE,
    input_role: str = "caller-root",
    acquired_input=None,
) -> ProjectTopology:
    purpose = ("topology-observation" if input_role == "caller-root"
        and _CURRENT_LIFECYCLE_TRANSACTION.get() is None else "bound-acquisition")
    _repository, work_items = _resolve_project_root_identity(root, input_role=input_role,
        failure_id=root_failure_id, acquisition_purpose=purpose, acquired_input=acquired_input)
    return _read_project_topology_at(work_items, root_failure_id=root_failure_id,
        acquisition_purpose=purpose, original_root=Path(root), acquired_input=acquired_input)


def _work_items_root(
    root: Path,
    *,
    root_failure_id: str = ROOT_CONTRACT_FAILURE,
    input_role: str = "caller-root",
    acquired_input=None,
) -> Path:
    return _resolve_project_topology(root, root_failure_id=root_failure_id, input_role=input_role, acquired_input=acquired_input).work_items


def is_valid_slug(slug: str) -> bool:
    """Return whether *slug* satisfies the canonical lifecycle identity grammar."""
    return isinstance(slug, str) and SLUG_RE.fullmatch(slug) is not None


def _validate_slug(slug: str) -> None:
    if not is_valid_slug(slug):
        raise LifecycleError("WI-INVALID-SLUG", f"invalid bare slug: {slug!r}")


def _authoritative_markdown_lines(text: str) -> Iterable[tuple[int, str]]:
    """Yield positioned Markdown lines that can own lifecycle fields.

    Fenced code is evidence/content, not record metadata.  Reject an opened
    fence without a valid close so malformed Markdown cannot silently widen or
    shrink the authoritative field surface.
    """
    fence_char: str | None = None
    fence_length = 0
    for line_number, line in enumerate(text.splitlines(), start=1):
        if fence_char is not None:
            closing = re.fullmatch(
                rf" {{0,3}}{re.escape(fence_char)}{{{fence_length},}}[ \t]*",
                line,
            )
            if closing:
                fence_char = None
                fence_length = 0
            continue

        opening = FENCED_CODE_OPEN_RE.fullmatch(line)
        if opening:
            fence = opening.group("fence")
            info = opening.group("info")
            if fence[0] == "`" and "`" in info:
                yield line_number, line
                continue
            fence_char = fence[0]
            fence_length = len(fence)
            continue
        yield line_number, line

    if fence_char is not None:
        raise LifecycleError(
            "WI-CATEGORY-MARKDOWN-INVALID",
            "unterminated fenced code block in lifecycle record",
        )


def _authoritative_field_occurrences(
    text: str,
) -> tuple[tuple[int, str, str, str], ...]:
    occurrences: list[tuple[int, str, str, str]] = []
    for line_number, line in _authoritative_markdown_lines(text):
        match = FIELD_RE.fullmatch(line)
        if match:
            occurrences.append(
                (
                    line_number,
                    match.group(1).strip().casefold(),
                    match.group(2).strip(),
                    line,
                )
            )
    return tuple(occurrences)


def _parse_fields(
    text: str, *, occurrences_out: list[tuple[int, str, str, str]] | None = None,
) -> dict[str, str]:
    fields: dict[str, str] = {}
    for occurrence in _authoritative_field_occurrences(text):
        if occurrences_out is not None:
            occurrences_out.append(occurrence)
        _line_number, name, value, _line = occurrence
        fields[name] = value
    return fields


@dataclass(frozen=True)
class CurrentDecisionRecord:
    format: str
    fields: Mapping[str, str | tuple[str, ...]]
    raw_status: str
    admitted_current_status: str | None
    body_offset: int
    legacy_read_only: bool


@dataclass(frozen=True)
class DecisionCompatibilityProfile:
    label: str
    format: str
    manifest_name: str
    manifest_schema_version: int
    anchor_manifest_field: str
    anchor_baseline_field: str
    anchor_cutover_field: str
    manifest_missing_failure_id: str
    manifest_invalid_failure_id: str
    unadmitted_failure_id: str
    manifest_stale_failure_id: str
    hash_mismatch_failure_id: str
    retired_reappeared_failure_id: str
    validate_record: Callable[[Path, str, str], CurrentDecisionRecord]


def _read_current_decision_text(path: Path, slug: str,
    *,
    acquired_input=None,
) -> str:
    try:
        return _input_text(path, acquired_input, encoding="utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-DECISION-SCHEMA-INVALID",
            f"decision:{slug} must be UTF-8",
        ) from exc


def _current_decision_format(text: str, slug: str) -> str:
    lines = text.splitlines()
    first = lines[0] if lines else ""
    if first.startswith("- "):
        return DECISION_FORMAT_V1
    if first == "---":
        return DECISION_FORMAT_V0
    if first.startswith("# ") and first[2:].strip():
        return DECISION_FORMAT_H1
    raise LifecycleError(
        "WI-DECISION-FORMAT-UNSUPPORTED",
        f"decision:{slug} has an unsupported first-line format",
    )


def _decision_filename_date_suffix(slug: str) -> tuple[str, str]:
    match = re.fullmatch(r"(\d{4}-\d{2}-\d{2})-(.+)", slug)
    if match is None:
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} requires a dated filename with a non-empty suffix",
        )
    date_value, suffix = match.groups()
    try:
        parsed = datetime.strptime(date_value, "%Y-%m-%d")
    except ValueError as exc:
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} has an invalid filename date",
        ) from exc
    if parsed.strftime("%Y-%m-%d") != date_value:
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} has an invalid filename date",
        )
    return date_value, suffix


def _immutable_decision_fields(
    fields: dict[str, str | tuple[str, ...]],
) -> Mapping[str, str | tuple[str, ...]]:
    return MappingProxyType(dict(fields))


def _parse_decision_v1_record(text: str, slug: str) -> CurrentDecisionRecord:
    lines = text.splitlines()
    heading_index = next(
        (index for index, line in enumerate(lines) if line.startswith("#")),
        None,
    )
    if heading_index is None:
        raise LifecycleError(
            "WI-DECISION-SCHEMA-INVALID",
            f"decision:{slug} has no body heading",
        )
    first_heading = lines[heading_index]
    if not (
        re.match(r"^#\s+\S", first_heading)
        or first_heading == "## Decision"
    ):
        bounded_heading = (
            first_heading
            if len(first_heading) <= 160
            else first_heading[:157] + "..."
        )
        raise LifecycleError(
            "WI-DECISION-SCHEMA-INVALID",
            f"decision:{slug} has unsupported first body heading at line "
            f"{heading_index + 1}: {bounded_heading!r}",
        )

    leading_occurrences: dict[str, tuple[int, str]] = {}
    previous_field = False
    for line_number, line in enumerate(lines[:heading_index], start=1):
        if not line.strip():
            previous_field = False
            continue
        match = DECISION_LIST_FIELD_RE.fullmatch(line)
        if match:
            name = match.group(1).strip().casefold()
            if name in leading_occurrences:
                raise LifecycleError(
                    "WI-DECISION-FIELD-DUPLICATE",
                    f"decision:{slug} duplicates leading field '{name}'",
                )
            leading_occurrences[name] = (line_number, match.group(2).strip())
            previous_field = True
            continue
        if FIELD_RE.fullmatch(line):
            raise LifecycleError(
                "WI-DECISION-SCHEMA-INVALID",
                f"decision:{slug} has a non-list metadata field at line {line_number}",
            )
        if line[:1].isspace() and previous_field:
            continue
        previous_field = False

    occurrences = _authoritative_field_occurrences(text)
    for required in DECISION_REQUIRED_FIELDS:
        matches = [
            (line_number, value)
            for line_number, name, value, _line in occurrences
            if name == required
        ]
        if len(matches) > 1:
            raise LifecycleError(
                "WI-DECISION-FIELD-DUPLICATE",
                f"decision:{slug} duplicates required field '{required}'",
            )
        leading = leading_occurrences.get(required)
        if len(matches) != 1 or leading is None or matches[0][0] != leading[0] or not leading[1]:
            raise LifecycleError(
                "WI-DECISION-SCHEMA-INVALID",
                f"decision:{slug} requires one non-empty leading '{required}' field",
            )

    fields = {name: value for name, (_line_number, value) in leading_occurrences.items()}
    if fields["id"] != slug:
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} id does not match its filename",
        )
    date_value = fields["date"]
    try:
        parsed_date = datetime.strptime(date_value, "%Y-%m-%d")
    except ValueError as exc:
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} date must be a real YYYY-MM-DD value",
        ) from exc
    if (
        not DECISION_DATE_RE.fullmatch(date_value)
        or parsed_date.strftime("%Y-%m-%d") != date_value
        or not slug.startswith(f"{date_value}-")
    ):
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} date does not match its filename prefix",
        )
    raw_lines = text.splitlines(keepends=True)
    body_offset = len("".join(raw_lines[:heading_index]).encode("utf-8"))
    return CurrentDecisionRecord(
        format=DECISION_FORMAT_V1,
        fields=_immutable_decision_fields(fields),
        raw_status=fields["status"],
        admitted_current_status=(fields["status"] if fields["status"] in CATEGORIES["decision"].current_statuses else None),
        body_offset=body_offset,
        legacy_read_only=False,
    )


def _normalize_decision_v0_key(key: str) -> str:
    return re.sub(r"[ _-]+", "-", key.casefold())


def _reject_decision_v0_active_value(slug: str, line_number: int, value: str) -> None:
    if value.startswith(DECISION_V0_ACTIVE_VALUE_PREFIXES):
        raise LifecycleError(
            "WI-DECISION-V0-UNSUPPORTED-NESTING",
            f"decision:{slug} has an active YAML value at line {line_number}",
        )


def _validate_current_decision_v0(
    text: str,
    slug: str,
    *,
    v0_cutover_date: str | None,
) -> CurrentDecisionRecord:
    logical_lines = text.splitlines()
    closing_index = next(
        (index for index, line in enumerate(logical_lines[1:], start=1) if line == "---"),
        None,
    )
    if closing_index is None:
        raise LifecycleError(
            "WI-DECISION-V0-SCHEMA-INVALID",
            f"decision:{slug} has no exact closing frontmatter delimiter",
        )
    header = logical_lines[1:closing_index]
    if not header:
        raise LifecycleError(
            "WI-DECISION-V0-SCHEMA-INVALID",
            f"decision:{slug} has an empty V0 header",
        )
    body = "\n".join(logical_lines[closing_index + 1 :])
    if not body.strip():
        raise LifecycleError(
            "WI-DECISION-V0-SCHEMA-INVALID",
            f"decision:{slug} has an empty V0 body",
        )

    fields: dict[str, str | tuple[str, ...]] = {}
    normalized_keys: dict[str, str] = {}
    pending_sequence_key: str | None = None
    sequence_values: list[str] = []

    def finish_pending(line_number: int) -> None:
        nonlocal pending_sequence_key, sequence_values
        if pending_sequence_key is None:
            return
        if not sequence_values:
            raise LifecycleError(
                "WI-DECISION-V0-SCHEMA-INVALID",
                f"decision:{slug} has an empty sequence field before line {line_number}",
            )
        fields[pending_sequence_key] = tuple(sequence_values)
        pending_sequence_key = None
        sequence_values = []

    for line_number, line in enumerate(header, start=2):
        if not line or "\t" in line:
            raise LifecycleError(
                "WI-DECISION-V0-SCHEMA-INVALID",
                f"decision:{slug} has a blank or tab-bearing header line {line_number}",
            )
        if line.startswith("  - "):
            value = line[4:]
            if pending_sequence_key is None or not value:
                raise LifecycleError(
                    "WI-DECISION-V0-UNSUPPORTED-NESTING",
                    f"decision:{slug} has an unsupported sequence at line {line_number}",
                )
            _reject_decision_v0_active_value(slug, line_number, value)
            sequence_values.append(value)
            continue
        if line.startswith("- "):
            raise LifecycleError(
                "WI-DECISION-V0-SCHEMA-INVALID",
                f"decision:{slug} has a V1 list field inside V0 at line {line_number}",
            )
        if line[:1].isspace():
            raise LifecycleError(
                "WI-DECISION-V0-UNSUPPORTED-NESTING",
                f"decision:{slug} has unsupported indentation at line {line_number}",
            )
        finish_pending(line_number)
        match = DECISION_V0_KEY_RE.fullmatch(line)
        if match is None:
            raise LifecycleError(
                "WI-DECISION-V0-SCHEMA-INVALID",
                f"decision:{slug} has an invalid V0 field at line {line_number}",
            )
        key = match.group(1)
        if key != key.strip():
            raise LifecycleError(
                "WI-DECISION-V0-SCHEMA-INVALID",
                f"decision:{slug} has an invalid V0 key at line {line_number}",
            )
        normalized = _normalize_decision_v0_key(key)
        if normalized in normalized_keys:
            raise LifecycleError(
                "WI-DECISION-V0-FIELD-DUPLICATE",
                f"decision:{slug} duplicates V0 key '{key}' at line {line_number}",
            )
        normalized_keys[normalized] = key
        value = match.group(2)
        if value is None or value == "":
            pending_sequence_key = key
            sequence_values = []
            continue
        if value.startswith(" "):
            raise LifecycleError(
                "WI-DECISION-V0-SCHEMA-INVALID",
                f"decision:{slug} has an invalid scalar at line {line_number}",
            )
        _reject_decision_v0_active_value(slug, line_number, value)
        fields[key] = value
    finish_pending(closing_index + 1)

    raw_status = fields.get("status")
    if not isinstance(raw_status, str) or not raw_status:
        raise LifecycleError(
            "WI-DECISION-V0-SCHEMA-INVALID",
            f"decision:{slug} requires one non-empty exact status field",
        )
    filename_date, suffix = _decision_filename_date_suffix(slug)
    identity = fields.get("id")
    if identity is not None and identity != slug:
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} V0 id does not match its full filename stem",
        )
    legacy_slug = fields.get("slug")
    if legacy_slug is not None and legacy_slug != suffix:
        raise LifecycleError(
            "WI-DECISION-IDENTITY-MISMATCH",
            f"decision:{slug} V0 slug does not match its undated filename suffix",
        )
    date_value = fields.get("date")
    if date_value is not None and date_value != filename_date:
        raise LifecycleError(
            "WI-DECISION-DATE-MISMATCH",
            f"decision:{slug} V0 date does not match its filename",
        )
    if v0_cutover_date is not None:
        try:
            cutover = datetime.strptime(v0_cutover_date, "%Y-%m-%d")
        except ValueError as exc:
            raise LifecycleError(
                "WI-DECISION-V0-MANIFEST-INVALID",
                "decision V0 manifest has an invalid cutover date",
            ) from exc
        if cutover.strftime("%Y-%m-%d") != v0_cutover_date:
            raise LifecycleError(
                "WI-DECISION-V0-MANIFEST-INVALID",
                "decision V0 manifest has an invalid cutover date",
            )
        if filename_date >= v0_cutover_date:
            raise LifecycleError(
                "WI-DECISION-V0-CUTOVER-VIOLATION",
                f"decision:{slug} V0 date is on or after the cutover",
            )

    raw_lines = text.splitlines(keepends=True)
    body_offset = len("".join(raw_lines[: closing_index + 1]).encode("utf-8"))
    admitted = raw_status if raw_status in CATEGORIES["decision"].current_statuses else None
    return CurrentDecisionRecord(
        format=DECISION_FORMAT_V0,
        fields=_immutable_decision_fields(fields),
        raw_status=raw_status,
        admitted_current_status=admitted,
        body_offset=body_offset,
        legacy_read_only=True,
    )


def _normalize_decision_h1_key(key: str) -> str:
    return re.sub(r"[ _-]+", "-", key.casefold())


def _validate_current_decision_h1(
    text: str,
    slug: str,
    *,
    h1_cutover_date: str | None,
) -> CurrentDecisionRecord:
    logical_lines = text.splitlines()
    if len(logical_lines) < 4 or logical_lines[1] != "":
        raise LifecycleError(
            "WI-DECISION-H1-SCHEMA-INVALID",
            f"decision:{slug} requires an exact blank line 2",
        )
    if logical_lines[2] == "":
        raise LifecycleError(
            "WI-DECISION-H1-STATUS-UNSUPPORTED",
            f"decision:{slug} requires status as its first H1 prefix field",
        )
    prefix_end = next(
        (index for index, line in enumerate(logical_lines[3:], start=3) if line == ""),
        None,
    )
    if prefix_end is None:
        raise LifecycleError(
            "WI-DECISION-H1-SCHEMA-INVALID",
            f"decision:{slug} has no exact H1 prefix terminator",
        )
    body = "\n".join(logical_lines[prefix_end + 1 :])
    if not body.strip():
        raise LifecycleError(
            "WI-DECISION-H1-SCHEMA-INVALID",
            f"decision:{slug} has an empty H1 body",
        )

    first = logical_lines[2]
    list_metadata = DECISION_LIST_FIELD_RE.fullmatch(first) is not None
    if list_metadata:
        if h1_cutover_date is None:
            raise LifecycleError(
                "WI-DECISION-H1-MANIFEST-MISSING",
                f"decision:{slug} list metadata requires the H1 compatibility manifest",
            )
        field_re = DECISION_LIST_FIELD_RE
    elif DECISION_H1_PLAIN_FIELD_RE.fullmatch(first):
        field_re = DECISION_H1_PLAIN_FIELD_RE
    elif DECISION_H1_BOLD_FIELD_RE.fullmatch(first):
        field_re = DECISION_H1_BOLD_FIELD_RE
    else:
        raise LifecycleError(
            "WI-DECISION-H1-SCHEMA-INVALID",
            f"decision:{slug} has an invalid H1 status field at line 3",
        )

    fields: dict[str, str] = {}
    normalized_keys: dict[str, str] = {}
    field_order: list[str] = []
    raw_status: str | None = None
    for index, line in enumerate(logical_lines[2:prefix_end], start=3):
        if "\t" in line or not line or line[:1].isspace():
            raise LifecycleError(
                "WI-DECISION-H1-SCHEMA-INVALID",
                f"decision:{slug} has an invalid H1 prefix line {index}",
            )
        match = field_re.fullmatch(line)
        if match is None:
            raise LifecycleError(
                "WI-DECISION-H1-SCHEMA-INVALID",
                f"decision:{slug} mixes or malforms H1 prefix mode at line {index}",
            )
        key, value = match.groups()
        normalized = _normalize_decision_h1_key(key)
        if normalized in normalized_keys:
            failure_id = (
                "WI-DECISION-H1-STATUS-UNSUPPORTED"
                if normalized == "status"
                else "WI-DECISION-H1-FIELD-DUPLICATE"
            )
            raise LifecycleError(
                failure_id,
                f"decision:{slug} duplicates H1 key '{key}' at line {index}",
            )
        normalized_keys[normalized] = key
        fields[key] = value
        field_order.append(normalized)
        if list_metadata and not value:
            failure_id = (
                "WI-DECISION-H1-STATUS-UNSUPPORTED"
                if normalized == "status"
                else "WI-DECISION-H1-SCHEMA-INVALID"
            )
            raise LifecycleError(
                failure_id,
                f"decision:{slug} has an empty H1 list field '{key}' at line {index}",
            )
        if not list_metadata and index == 3:
            if normalized != "status":
                raise LifecycleError(
                    "WI-DECISION-H1-STATUS-UNSUPPORTED",
                    f"decision:{slug} requires status as its first H1 prefix field",
                )
            raw_status = value

    if list_metadata:
        if not field_order or field_order[0] != "id":
            raise LifecycleError(
                "WI-DECISION-H1-SCHEMA-INVALID",
                f"decision:{slug} requires id as its first H1 list field",
            )
        if len(field_order) < 2 or field_order[1] != "status":
            raise LifecycleError(
                "WI-DECISION-H1-STATUS-UNSUPPORTED",
                f"decision:{slug} requires status as its second H1 list field",
            )
        identity = fields[normalized_keys["id"]]
        if identity != slug:
            raise LifecycleError(
                "WI-DECISION-IDENTITY-MISMATCH",
                f"decision:{slug} id does not match its filename",
            )
        raw_status = fields[normalized_keys["status"]]
        admitted = raw_status
        if admitted not in {"accepted", "proposed"}:
            raise LifecycleError(
                "WI-DECISION-H1-STATUS-UNSUPPORTED",
                f"decision:{slug} has an unsupported H1 status value",
            )
    elif raw_status is None or len([key for key in normalized_keys if key == "status"]) != 1:
        raise LifecycleError(
            "WI-DECISION-H1-STATUS-UNSUPPORTED",
            f"decision:{slug} requires exactly one first H1 status field",
        )
    else:
        status_word = re.match(r"^([A-Za-z]+)(?:\s|$)", raw_status)
        admitted = status_word.group(1).casefold() if status_word else ""
        if admitted not in {"accepted", "proposed"}:
            raise LifecycleError(
                "WI-DECISION-H1-STATUS-UNSUPPORTED",
                f"decision:{slug} has an unsupported H1 status token",
            )

    filename_date, _suffix = _decision_filename_date_suffix(slug)
    if h1_cutover_date is not None:
        try:
            cutover = datetime.strptime(h1_cutover_date, "%Y-%m-%d")
        except ValueError as exc:
            raise LifecycleError(
                "WI-DECISION-H1-MANIFEST-INVALID",
                "decision H1 manifest has an invalid cutover date",
            ) from exc
        if cutover.strftime("%Y-%m-%d") != h1_cutover_date:
            raise LifecycleError(
                "WI-DECISION-H1-MANIFEST-INVALID",
                "decision H1 manifest has an invalid cutover date",
            )
        if filename_date >= h1_cutover_date:
            raise LifecycleError(
                "WI-DECISION-H1-CUTOVER-VIOLATION",
                f"decision:{slug} H1 date is on or after the cutover",
            )

    raw_lines = text.splitlines(keepends=True)
    body_offset = len("".join(raw_lines[: prefix_end + 1]).encode("utf-8"))
    return CurrentDecisionRecord(
        format=DECISION_FORMAT_H1,
        fields=_immutable_decision_fields(fields),
        raw_status=raw_status,
        admitted_current_status=admitted,
        body_offset=body_offset,
        legacy_read_only=True,
    )


def _parse_decision_record_text(
    text: str,
    slug: str,
    *,
    v0_cutover_date: str | None = None,
    h1_cutover_date: str | None = None,
) -> CurrentDecisionRecord:
    selected = _current_decision_format(text, slug)
    if selected == DECISION_FORMAT_V1:
        return _parse_decision_v1_record(text, slug)
    if selected == DECISION_FORMAT_V0:
        return _validate_current_decision_v0(
            text,
            slug,
            v0_cutover_date=v0_cutover_date,
        )
    return _validate_current_decision_h1(
        text,
        slug,
        h1_cutover_date=h1_cutover_date,
    )


def _validate_current_decision_record(
    path: Path,
    slug: str,
    *,
    v0_cutover_date: str | None = None,
    h1_cutover_date: str | None = None,
    acquired_input=None,
) -> CurrentDecisionRecord:
    text = _read_current_decision_text(path, slug, acquired_input=acquired_input)
    record = _parse_decision_record_text(
        text, slug, v0_cutover_date=v0_cutover_date, h1_cutover_date=h1_cutover_date,
    )
    if record.format == DECISION_FORMAT_V1 and record.admitted_current_status is None:
        raise LifecycleError(
            "WI-DECISION-SCHEMA-INVALID",
            f"decision:{slug} has unsupported current status '{record.raw_status}'",
        )
    return record


class _DecisionCompatibilityManifestDuplicateKey(ValueError):
    pass


def _decision_compatibility_json_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    result: dict[str, object] = {}
    for key, value in pairs:
        if key in result:
            raise _DecisionCompatibilityManifestDuplicateKey(key)
        result[key] = value
    return result


def _decision_compatibility_baseline_digest(entries: list[dict[str, str]]) -> str:
    payload = b"".join(
        entry["path"].encode("utf-8")
        + b"\0"
        + entry["sha256"].encode("ascii")
        + b"\n"
        for entry in entries
    )
    return hashlib.sha256(payload).hexdigest().upper()


def _validate_current_decision_v0_manifest_record(
    path: Path,
    slug: str,
    cutover_date: str,
    *,
    acquired_input=None,
) -> CurrentDecisionRecord:
    return _validate_current_decision_record(
        path,
        slug,
        v0_cutover_date=cutover_date,
     acquired_input=acquired_input)


def _validate_current_decision_h1_manifest_record(
    path: Path,
    slug: str,
    cutover_date: str,
    *,
    acquired_input=None,
) -> CurrentDecisionRecord:
    return _validate_current_decision_record(
        path,
        slug,
        h1_cutover_date=cutover_date,
     acquired_input=acquired_input)


def _verify_current_decision_compatibility_manifest(
    root: Path,
    profile: DecisionCompatibilityProfile,
    *,
    manifest_bytes: bytes | None = None,
    acquired_input=None,
) -> dict[str, CurrentDecisionRecord]:
    def manifest_invalid(message: str) -> LifecycleError:
        return LifecycleError(profile.manifest_invalid_failure_id, message)

    work_items = _work_items_root(root, acquired_input=acquired_input)
    decisions = work_items / CATEGORIES["decision"].current_root
    current_paths = sorted(_input_glob(decisions, "*.md", acquired_input), key=lambda path: path.name)
    formats: dict[str, str] = {}
    for path in current_paths:
        text = _read_current_decision_text(path, path.stem, acquired_input=acquired_input)
        try:
            formats[path.name] = _current_decision_format(text, path.stem)
        except LifecycleError as exc:
            if exc.failure_id != "WI-DECISION-FORMAT-UNSUPPORTED":
                raise
            formats[path.name] = "other"
    discovered = tuple(
        name for name, selected in formats.items() if selected == profile.format
    )
    manifest_path = work_items / profile.manifest_name
    if manifest_bytes is None and not _input_is_file(manifest_path, acquired_input):
        if discovered:
            raise LifecycleError(
                profile.manifest_missing_failure_id,
                f"current {profile.label} decision requires work-items/{profile.manifest_name}",
            )
        return {}
    try:
        encoded = (
            _input_bytes(manifest_path, acquired_input)
            if manifest_bytes is None
            else manifest_bytes
        )
        payload = json.loads(
            encoded.decode("utf-8"),
            object_pairs_hook=_decision_compatibility_json_object,
        )
    except (
        UnicodeDecodeError,
        json.JSONDecodeError,
        _DecisionCompatibilityManifestDuplicateKey,
    ) as exc:
        raise manifest_invalid(
            f"decision {profile.label} manifest is not strict UTF-8 JSON"
        ) from exc
    if not isinstance(payload, dict) or set(payload) != {
        "schemaVersion",
        "policyDecision",
        "cutoverDate",
        "baselineSha256",
        "entries",
    }:
        raise manifest_invalid(
            f"decision {profile.label} manifest has an invalid top-level shape"
        )
    schema_version = payload["schemaVersion"]
    if (
        type(schema_version) is not int
        or schema_version not in (
            (1, 2) if profile.label == "V0" else (profile.manifest_schema_version,)
        )
    ):
        raise manifest_invalid(
            f"decision {profile.label} manifest has an unsupported schemaVersion"
        )
    policy_slug = payload["policyDecision"]
    cutover_date = payload["cutoverDate"]
    baseline_sha256 = payload["baselineSha256"]
    raw_entries = payload["entries"]
    if (
        not isinstance(policy_slug, str)
        or not is_valid_slug(policy_slug)
        or not isinstance(cutover_date, str)
        or not DECISION_DATE_RE.fullmatch(cutover_date)
        or not isinstance(baseline_sha256, str)
        or not re.fullmatch(r"[0-9A-F]{64}", baseline_sha256)
        or not isinstance(raw_entries, list)
        or not raw_entries
    ):
        raise manifest_invalid(
            f"decision {profile.label} manifest has invalid scalar fields"
        )
    try:
        cutover = datetime.strptime(cutover_date, "%Y-%m-%d")
    except ValueError as exc:
        raise manifest_invalid(
            f"decision {profile.label} manifest cutoverDate is invalid"
        ) from exc
    if cutover.strftime("%Y-%m-%d") != cutover_date:
        raise manifest_invalid(
            f"decision {profile.label} manifest cutoverDate is invalid"
        )

    entries: list[dict[str, object]] = []
    for index, raw_entry in enumerate(raw_entries):
        if not isinstance(raw_entry, dict):
            raise manifest_invalid(
                f"decision {profile.label} manifest entry {index} has invalid shape"
            )
        state = raw_entry.get("state")
        expected_fields = {"path", "sha256", "state"}
        if schema_version == 2 and state == "retired":
            expected_fields.add("archiveEvidence")
        if set(raw_entry) != expected_fields:
            raise manifest_invalid(
                f"decision {profile.label} manifest entry {index} has invalid shape"
            )
        name = raw_entry["path"]
        digest = raw_entry["sha256"]
        if (
            not isinstance(name, str)
            or not name.endswith(".md")
            or Path(name).name != name
            or "/" in name
            or "\\" in name
            or not is_valid_slug(Path(name).stem)
            or not isinstance(digest, str)
            or not re.fullmatch(r"[0-9A-F]{64}", digest)
            or state not in {"admitted", "retired"}
        ):
            raise manifest_invalid(
                f"decision {profile.label} manifest entry {index} is invalid"
            )
        entry = {"path": name, "sha256": digest, "state": state}
        if schema_version == 2 and state == "retired":
            evidence = raw_entry["archiveEvidence"]
            if not isinstance(evidence, dict) or set(evidence) != {
                "archivePath", "archivedAt", "rationale", "evidence"
            }:
                raise manifest_invalid(f"decision V0 manifest entry {index} has invalid archive evidence")
            archived_at = evidence["archivedAt"]
            archive_path = evidence["archivePath"]
            if (
                not isinstance(archived_at, str)
                or not isinstance(archive_path, str)
                or archive_path != f"decisions/archive/{archived_at[:7]}/{name}"
                or any(
                    not isinstance(evidence[field], str) or not evidence[field].strip()
                    for field in ("rationale", "evidence")
                )
            ):
                raise manifest_invalid(f"decision V0 manifest entry {index} has invalid archive evidence")
            try:
                _strict_utc(archived_at)
            except LifecycleError as exc:
                raise manifest_invalid(f"decision V0 manifest entry {index} has invalid archive instant") from exc
            entry["archiveEvidence"] = evidence
        entries.append(entry)
    names = [entry["path"] for entry in entries]
    if names != sorted(names) or len(names) != len(set(names)):
        raise manifest_invalid(
            f"decision {profile.label} manifest entries must be sorted and unique"
        )
    if _decision_compatibility_baseline_digest(entries) != baseline_sha256:
        raise manifest_invalid(
            f"decision {profile.label} manifest baseline digest does not match its rows"
        )

    anchor_path = decisions / f"{policy_slug}.md"
    if not _input_is_file(anchor_path, acquired_input) or formats.get(anchor_path.name) != DECISION_FORMAT_V1:
        raise manifest_invalid(
            f"decision {profile.label} manifest policy anchor is not a current V1 record"
        )
    try:
        anchor = _validate_current_decision_record(anchor_path, policy_slug, acquired_input=acquired_input)
    except LifecycleError as exc:
        raise manifest_invalid(
            f"decision {profile.label} manifest policy anchor is invalid"
        ) from exc
    expected_manifest = f"work-items/{profile.manifest_name}"
    if (
        anchor.raw_status != "accepted"
        or anchor.fields.get(profile.anchor_manifest_field) != expected_manifest
        or anchor.fields.get(profile.anchor_baseline_field) != baseline_sha256
        or anchor.fields.get(profile.anchor_cutover_field) != cutover_date
    ):
        raise manifest_invalid(
            f"decision {profile.label} manifest policy anchor does not match"
        )

    by_name = {entry["path"]: entry for entry in entries}
    for name in discovered:
        entry = by_name.get(name)
        if entry is None:
            raise LifecycleError(
                profile.unadmitted_failure_id,
                f"decisions/{name} is not in the frozen {profile.label} manifest",
            )
        if entry["state"] == "retired":
            raise LifecycleError(
                profile.retired_reappeared_failure_id,
                f"retired decisions/{name} reappeared as {profile.label}",
            )

    admitted: dict[str, CurrentDecisionRecord] = {}
    for entry in entries:
        name = entry["path"]
        path = decisions / name
        selected = formats.get(name)
        if entry["state"] == "retired":
            if schema_version == 2:
                if selected is not None:
                    raise LifecycleError(
                        profile.retired_reappeared_failure_id,
                        f"retired decisions/{name} reappeared as current",
                    )
                archive_relative = entry["archiveEvidence"]["archivePath"]
                archive = work_items / Path(archive_relative)
                try:
                    archived = _capture_file_snapshot(
                        archive, failure_id=profile.manifest_stale_failure_id
                    , acquired_input=acquired_input).data
                except LifecycleError as exc:
                    raise LifecycleError(
                        profile.manifest_stale_failure_id,
                        f"retired decisions/{name} archive is missing or unsafe",
                    ) from exc
                if hashlib.sha256(archived).hexdigest().upper() != entry["sha256"]:
                    raise LifecycleError(
                        profile.hash_mismatch_failure_id,
                        f"retired decisions/{name} archive differs from its frozen SHA-256",
                    )
                continue
            if selected is None or selected == DECISION_FORMAT_V1:
                continue
            raise LifecycleError(
                profile.manifest_stale_failure_id,
                f"retired decisions/{name} is neither absent nor V1",
            )
        if selected is None or selected != profile.format:
            raise LifecycleError(
                profile.manifest_stale_failure_id,
                f"admitted decisions/{name} is missing or no longer {profile.label}",
            )
        actual_digest = hashlib.sha256(_input_bytes(path, acquired_input)).hexdigest().upper()
        if actual_digest != entry["sha256"]:
            raise LifecycleError(
                profile.hash_mismatch_failure_id,
                f"admitted decisions/{name} differs from its frozen SHA-256",
            )
        admitted[name] = (profile.validate_record(path, path.stem, cutover_date) if acquired_input is None
                          else profile.validate_record(path, path.stem, cutover_date, acquired_input=acquired_input))
    return admitted


def _preflight_current_decision_v0(root: Path, *, manifest_bytes: bytes | None = None) -> dict[str, CurrentDecisionRecord]:
    return _verify_current_decision_compatibility_manifest(
        root,
        DecisionCompatibilityProfile(
            label="V0",
            format=DECISION_FORMAT_V0,
            manifest_name=DECISION_V0_MANIFEST,
            manifest_schema_version=DECISION_V0_MANIFEST_SCHEMA_VERSION,
            anchor_manifest_field="v0-manifest",
            anchor_baseline_field="v0-baseline-sha256",
            anchor_cutover_field="v0-cutover-date",
            manifest_missing_failure_id="WI-DECISION-V0-MANIFEST-MISSING",
            manifest_invalid_failure_id="WI-DECISION-V0-MANIFEST-INVALID",
            unadmitted_failure_id="WI-DECISION-V0-UNADMITTED",
            manifest_stale_failure_id="WI-DECISION-V0-MANIFEST-STALE",
            hash_mismatch_failure_id="WI-DECISION-V0-HASH-MISMATCH",
            retired_reappeared_failure_id="WI-DECISION-V0-RETIRED-REAPPEARED",
            validate_record=_validate_current_decision_v0_manifest_record,
        ),
        manifest_bytes=manifest_bytes,
    )


_INITIAL_V0_OPERATION = "initial-decision-v0-admission"
_INITIAL_V0_MAX_BYTES = 4 * 1024 * 1024


def _initial_v0_fail(suffix: str, message: str) -> LifecycleError:
    return LifecycleError(f"WI-DECISION-V0-ADMISSION-{suffix}", message)


def _initial_v0_json(value: dict) -> bytes:
    data = (json.dumps(value, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    if len(data) > _INITIAL_V0_MAX_BYTES:
        raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence exceeds the owner byte envelope")
    return data


def _initial_v0_keys(value: object, keys: set[str]) -> None:
    if type(value) is not dict or set(value) != keys:
        raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence has an invalid object shape")


def _initial_v0_identity(value: object) -> None:
    _initial_v0_keys(value, {"kind", "value"})
    if (value["kind"] not in ("stat", "native-windows-file") or type(value["value"]) is not list
        or len(value["value"]) != 2 or any(type(n) is not int or n < 0 for n in value["value"])):
        raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence identity is invalid")


def _initial_v0_relative(value: object) -> str:
    if (type(value) is not str or not value or "\\" in value or ":" in value
        or value.startswith("/") or any(part in ("", ".", "..") for part in value.split("/"))):
        raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence path is not confined")
    return value


def _initial_v0_digest(value: object) -> bool:
    return type(value) is str and re.fullmatch(r"[0-9A-F]{64}", value) is not None


def _initial_v0_image(value: object, *, stage: bool = False) -> bytes:
    _initial_v0_keys(value, {"identity", "sha256", "data"} | ({"stagePath"} if stage else set()))
    _initial_v0_identity(value["identity"])
    if stage:
        _initial_v0_relative(value["stagePath"])
    if type(value["data"]) is not str or not _initial_v0_digest(value["sha256"]):
        raise _initial_v0_fail("RECOVERY-INVALID", "operation byte image is invalid")
    try:
        data = _unb64(value["data"])
    except LifecycleError as exc:
        raise _initial_v0_fail("RECOVERY-INVALID", "operation byte image is not strict base64") from exc
    if len(data) > _INITIAL_V0_MAX_BYTES or _sha256_bytes(data).upper() != value["sha256"] or _b64(data) != value["data"]:
        raise _initial_v0_fail("RECOVERY-INVALID", "operation byte image hash differs")
    return data


def _initial_v0_load(data: bytes) -> dict:
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence repeats a JSON key")
            result[key] = value
        return result
    try:
        if len(data) > _INITIAL_V0_MAX_BYTES:
            raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence exceeds the owner byte envelope")
        return json.loads(data.decode("utf-8"), object_pairs_hook=pairs)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence is not strict UTF-8 JSON") from exc


def _initial_v0_census(root: Path) -> tuple[list[dict], list[CapturedFileSnapshot]]:
    directory = root / "work-items" / "decisions"
    _lifecycle_reject_unreduced_reparse(directory, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY", message="decision census path is unsafe")
    entries, snapshots = [], []
    if not directory.exists():
        return entries, snapshots
    chain = _capture_path_parent_chain(directory / "census", "WI-LIFECYCLE-WRITE-BOUNDARY")
    # Observe every direct Markdown member; names/count/status never select admission.
    paths = sorted(directory.glob("*.md"), key=lambda path: path.name)
    for path in paths:
        snapshot = _capture_file_snapshot(path, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY")
        try:
            text = snapshot.data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise LifecycleError("WI-DECISION-SCHEMA-INVALID", "decision census member is not UTF-8") from exc
        try:
            selected = _current_decision_format(text, path.stem)
        except LifecycleError as exc:
            if exc.failure_id != "WI-DECISION-FORMAT-UNSUPPORTED":
                raise
            selected = "other"
        if selected == DECISION_FORMAT_V0:
            entries.append({"path": path.name, "sha256": _sha256_bytes(snapshot.data).upper(), "state": "admitted"})
            snapshots.append(snapshot)
    _verify_captured_parent_chain(chain, "WI-LIFECYCLE-WRITE-BOUNDARY")
    if [path.name for path in sorted(directory.glob("*.md"), key=lambda path: path.name)] != [path.name for path in paths]:
        raise _initial_v0_fail("STALE", "decision census membership changed during capture")
    return entries, snapshots


def _initial_v0_manifest(request: dict, entries: list[dict]) -> dict:
    return {"schemaVersion": DECISION_V0_MANIFEST_SCHEMA_VERSION,
            "policyDecision": request["policyDecision"], "cutoverDate": request["cutoverDate"],
            "baselineSha256": request["expectedBaselineSha256"], "entries": entries}


def _initial_v0_result(state: str, entries: list[dict], policy: dict | None, cutover: str | None,
                       manifest: dict | None, receipt: dict | None = None) -> dict:
    return {"schemaVersion": 1, "state": state, "entries": entries,
            "baselineSha256": _decision_compatibility_baseline_digest(entries) if entries else None,
            "policy": policy, "cutoverDate": cutover, "manifest": manifest, "receipt": receipt}


def _initial_v0_scope(root: Path, receipt_path: Path) -> dict:
    parents = {}
    decision_parent = root / "work-items" / "decisions"
    if not decision_parent.exists():
        decision_parent = root / "work-items"
    for path in (decision_parent / "member", receipt_path):
        chain = _capture_path_parent_chain(path, "WI-LIFECYCLE-WRITE-BOUNDARY")
        for parent, identity in chain.participants:
            if parent != root and parent.is_relative_to(root):
                parents[parent.relative_to(root).as_posix()] = {"kind": "stat", "value": list(identity)}
    return {"repositoryIdentity": {"kind": "stat", "value": list(_lifecycle_file_identity(root.lstat()))},
            "workItemsIdentity": {"kind": "stat", "value": list(_lifecycle_file_identity((root / "work-items").lstat()))},
            "parents": [{"path": path, "identity": identity} for path, identity in sorted(parents.items())]}


def _initial_v0_validate_scope(scope: dict) -> None:
    _initial_v0_keys(scope, {"repositoryIdentity", "workItemsIdentity", "parents"})
    for name in ("repositoryIdentity", "workItemsIdentity"):
        _initial_v0_identity(scope[name])
        if scope[name]["kind"] != "stat":
            raise _initial_v0_fail("RECOVERY-INVALID", "scope requires snapshot identities")
    if type(scope["parents"]) is not list or not scope["parents"]:
        raise _initial_v0_fail("RECOVERY-INVALID", "scope parent chain is missing")
    paths = []
    for row in scope["parents"]:
        _initial_v0_keys(row, {"path", "identity"})
        paths.append(_initial_v0_relative(row["path"]))
        _initial_v0_identity(row["identity"])
        if row["identity"]["kind"] != "stat":
            raise _initial_v0_fail("RECOVERY-INVALID", "parent requires snapshot identity")
    if paths != sorted(set(paths)):
        raise _initial_v0_fail("RECOVERY-INVALID", "scope parents are not sorted and unique")


def _initial_v0_validate_header(record: dict, request: dict, operation_id: str, scope: dict, *, receipt: bool) -> None:
    _initial_v0_keys(record, {"schemaVersion", "operation", "operationId", "request", "scope"}
                     | ({"entries", "participants", "readback", "settlement"} if receipt else {"inputs", "outputs"}))
    _initial_v0_keys(record["request"], set(request))
    _initial_v0_validate_scope(record["scope"])
    if type(record["schemaVersion"]) is not int or record["schemaVersion"] != 1 or record["operation"] != _INITIAL_V0_OPERATION:
        raise _initial_v0_fail("RECOVERY-INVALID", "operation evidence version/kind differs")
    if record["operationId"] != operation_id or record["request"] != request or record["scope"] != scope:
        raise _initial_v0_fail("RECOVERY-CONFLICT", "operation request or root binding differs")


def _initial_v0_validate_entries(entries: object, request: dict) -> None:
    if type(entries) is not list or not entries:
        raise _initial_v0_fail("RECOVERY-INVALID", "original admission entries are missing")
    paths = []
    for row in entries:
        _initial_v0_keys(row, {"path", "sha256", "state"})
        path = _initial_v0_relative(row["path"])
        if "/" in path or not path.endswith(".md") or not is_valid_slug(path[:-3]) or row["state"] != "admitted" or not _initial_v0_digest(row["sha256"]):
            raise _initial_v0_fail("RECOVERY-INVALID", "original admission entry is invalid")
        paths.append(path)
    if paths != sorted(set(paths)) or _decision_compatibility_baseline_digest(entries) != request["expectedBaselineSha256"]:
        raise _initial_v0_fail("RECOVERY-INVALID", "original admission baseline differs")


def _initial_v0_validate_receipt(record: dict, request: dict, operation_id: str, scope: dict) -> list[dict]:
    _initial_v0_validate_header(record, request, operation_id, scope, receipt=True)
    entries = record["entries"]
    _initial_v0_validate_entries(entries, request)
    _initial_v0_keys(record["readback"], {"manifestVerified", "legacyBytesUnchanged", "policyUnchanged"})
    if any(value is not True for value in record["readback"].values()) or record["settlement"] not in ("initial", "recovered"):
        raise _initial_v0_fail("RECOVERY-INVALID", "settlement observation is invalid")
    manifest = _initial_v0_json(_initial_v0_manifest(request, entries))
    expected = [{"path": f"work-items/decisions/{row['path']}", "beforeSha256": row["sha256"], "afterSha256": row["sha256"]} for row in entries]
    expected += [{"path": f"work-items/decisions/{request['policyDecision']}.md", "beforeSha256": request["expectedPolicySha256"], "afterSha256": request["expectedPolicySha256"]},
                 {"path": f"work-items/{DECISION_V0_MANIFEST}", "beforeSha256": None, "afterSha256": _sha256_bytes(manifest).upper()}]
    if record["participants"] != sorted(expected, key=lambda row: row["path"]):
        raise _initial_v0_fail("RECOVERY-INVALID", "settlement participant bindings differ")
    return entries


def _initial_v0_validate_pending(record: dict, request: dict, operation_id: str, scope: dict) -> list[dict]:
    _initial_v0_validate_header(record, request, operation_id, scope, receipt=False)
    if type(record["inputs"]) is not list or type(record["outputs"]) is not list:
        raise _initial_v0_fail("RECOVERY-INVALID", "operation images are missing")
    paths, entries = [], []
    policy_path = f"work-items/decisions/{request['policyDecision']}.md"
    policy_seen = False
    for row in record["inputs"]:
        _initial_v0_keys(row, {"path", "identity", "sha256", "data"})
        path = _initial_v0_relative(row["path"])
        paths.append(path)
        data = _initial_v0_image({key: row[key] for key in ("identity", "sha256", "data")})
        if row["identity"]["kind"] != "stat" or Path(path).parent.as_posix() != "work-items/decisions" or not is_valid_slug(Path(path).stem):
            raise _initial_v0_fail("RECOVERY-INVALID", "input is outside the original decision census")
        try:
            selected = _current_decision_format(data.decode("utf-8"), Path(path).stem)
        except (UnicodeDecodeError, LifecycleError) as exc:
            raise _initial_v0_fail("RECOVERY-INVALID", "original input is not a decision") from exc
        if path == policy_path:
            if selected != DECISION_FORMAT_V1 or row["sha256"] != request["expectedPolicySha256"]:
                raise _initial_v0_fail("RECOVERY-INVALID", "original policy image differs")
            policy_seen = True
        elif selected == DECISION_FORMAT_V0:
            entries.append({"path": Path(path).name, "sha256": row["sha256"], "state": "admitted"})
        else:
            raise _initial_v0_fail("RECOVERY-INVALID", "unexpected original input format")
    if paths != sorted(set(paths)) or not policy_seen:
        raise _initial_v0_fail("RECOVERY-INVALID", "original input set is invalid")
    _initial_v0_validate_entries(entries, request)
    expected_paths = sorted([f"work-items/{DECISION_V0_MANIFEST}", request["receiptPath"]])
    if len(record["outputs"]) != 2:
        raise _initial_v0_fail("RECOVERY-INVALID", "output set is invalid")
    for row, path in zip(record["outputs"], expected_paths):
        _initial_v0_keys(row, {"path", "before", "ownedAfter"})
        if row["path"] != path or row["before"] is not None:
            raise _initial_v0_fail("RECOVERY-INVALID", "output preimage differs")
        image = row["ownedAfter"]
        if image is not None:
            data = _initial_v0_image(image, stage=True)
            stage_path = Path(image["stagePath"])
            if stage_path.parent != Path(path).parent or re.fullmatch(r"\." + re.escape(Path(path).name) + r"\.[0-9a-f]{32}\.tmp", stage_path.name) is None:
                raise _initial_v0_fail("RECOVERY-INVALID", "output stage path differs")
            if path == f"work-items/{DECISION_V0_MANIFEST}":
                if data != _initial_v0_json(_initial_v0_manifest(request, entries)):
                    raise _initial_v0_fail("RECOVERY-INVALID", "manifest stage differs from original candidate")
            else:
                _initial_v0_validate_receipt(_initial_v0_load(data), request, operation_id, scope)
    if next(row for row in record["outputs"] if row["path"] == f"work-items/{DECISION_V0_MANIFEST}")["ownedAfter"] is None:
        raise _initial_v0_fail("RECOVERY-INCOMPLETE", "manifest stage evidence is missing")
    return entries


def _initial_v0_original_subjects(root: Path, pending: dict, entries: list[dict]) -> None:
    fresh_entries, _snapshots = _initial_v0_census(root)
    if fresh_entries != entries:
        raise _initial_v0_fail("RECOVERY-CONFLICT", "complete original V0 membership or bytes changed")
    for row in pending["inputs"]:
        snapshot = _capture_file_snapshot(root / row["path"], failure_id="WI-DECISION-V0-ADMISSION-RECOVERY-CONFLICT")
        if list(snapshot.identity) != row["identity"]["value"] or snapshot.data != _unb64(row["data"]):
            raise _initial_v0_fail("RECOVERY-CONFLICT", f"original input changed: {row['path']}")
    if _initial_v0_scope(root, root / pending["request"]["receiptPath"]) != pending["scope"]:
        raise _initial_v0_fail("RECOVERY-CONFLICT", "original root/parent scope changed")


def _initial_v0_original_inputs(root: Path, pending: dict, entries: list[dict]) -> None:
    _initial_v0_original_subjects(root, pending, entries)
    _CURRENT_LIFECYCLE_TRANSACTION.get().verify()


def _initial_v0_stage(root: Path, target: LifecycleWriteTarget, data: bytes) -> dict:
    image = target.stage_create(data)
    image["stagePath"] = Path(image["stagePath"]).relative_to(root).as_posix()
    return image


def _initial_v0_promote(root: Path, target: LifecycleWriteTarget, image: dict) -> None:
    try:
        target.promote_create({**image, "stagePath": str(root / image["stagePath"])})
    except OSError as exc:
        raise _initial_v0_fail("CONFLICT", f"create-only promotion refused: {target.path.relative_to(root).as_posix()}") from exc


def _initial_v0_owned(target: LifecycleWriteTarget, image: dict, leaf: str | None = None) -> bool:
    actual = target.owned_image(leaf)
    return _initial_v0_image_matches(actual, image)


def _initial_v0_image_matches(actual: dict | None, image: dict) -> bool:
    return actual is not None and actual == {key: image[key] for key in ("identity", "sha256", "data")}


def _initial_v0_check_manifest(target: LifecycleWriteTarget, image: dict) -> None:
    if not _initial_v0_owned(target, image):
        raise _initial_v0_fail("RECOVERY-CONFLICT", "manifest output ownership changed during settlement")


def _initial_v0_cleanup(root: Path, pending: dict, targets: dict[str, LifecycleWriteTarget],
                        pending_target: LifecycleWriteTarget, pending_image: dict, *, rollback: bool, entries: list[dict]) -> None:
    _initial_v0_original_subjects(root, pending, entries)
    _CURRENT_LIFECYCLE_TRANSACTION.get()._verify_compensation()
    # Check every affected final/stage before removing any retained evidence.
    # A missing recorded stage is expected only when its exact final output exists.
    for row in pending["outputs"]:
        target, image = targets[row["path"]], row["ownedAfter"]
        actual = target.owned_image()
        stage = target.owned_image(Path(image["stagePath"]).name) if image is not None else None
        if stage is not None and not _initial_v0_image_matches(stage, image):
            raise _initial_v0_fail("RECOVERY-CONFLICT", f"cleanup stage changed: {image['stagePath']}")
        if image is not None and stage is None and actual is None:
            raise _initial_v0_fail("RECOVERY-INCOMPLETE", f"cleanup recorded effect is missing: {row['path']}")
        if rollback and actual is not None and (image is None or not _initial_v0_image_matches(actual, image)):
            raise _initial_v0_fail("RECOVERY-CONFLICT", f"rollback output changed: {row['path']}")
    if pending_target.owned_image() != pending_image:
        raise _initial_v0_fail("RECOVERY-CONFLICT", "pending evidence changed before cleanup")
    for row in pending["outputs"]:
        target, image = targets[row["path"]], row["ownedAfter"]
        if image is None:
            continue
        stage_leaf = Path(image["stagePath"]).name
        if target.owned_image(stage_leaf) is not None:
            if not _initial_v0_owned(target, image, stage_leaf):
                raise _initial_v0_fail("RECOVERY-CONFLICT", f"stage ownership changed: {image['stagePath']}")
            target.remove_owned(stage_leaf, image)
        if rollback and target.owned_image() is not None:
            target.remove_owned(target.leaf, image)
    pending_target.remove_owned(pending_target.leaf, pending_image)


@dataclass
class _InitialV0Operation:
    transaction: object
    root: Path
    request: dict
    operation_id: str
    paths: tuple
    phase: str = "request-bound"
    pending: object = None
    scope: object = None
    entries: object = None
    targets: object = None
    pending_image: object = None
    receipt_image: object = None
    pending_target: object = None
    published_receipt: bool = False
    unrecorded_stages: list = field(default_factory=list)

    def admit(self, pending, scope, entries):
        if pending is None and self.receipt_image is None:
            raise LifecycleError("WI-DECISION-V0-ADMISSION-CONFLICT", "operation lacks admitted evidence")
        if pending is not None and (pending["request"] != self.request or pending["operationId"] != self.operation_id):
            raise LifecycleError("WI-DECISION-V0-ADMISSION-CONFLICT", "request-bound operation differs")
        self.pending, self.scope, self.entries = pending, scope, entries
        self.phase = "domain-admitted"
        self.transaction.bind_operation(self)


def admit_current_decision_v0(root: Path, *, policy_decision: str | None = None,
                              cutover_date: str | None = None, expected_baseline_sha256: str | None = None,
                              expected_policy_sha256: str | None = None, operation_id: str | None = None,
                              receipt: str | None = None, apply: bool = False) -> dict:
    """Capture without authority, or create/settle the first bound V0 admission."""
    if type(apply) is not bool:
        raise _initial_v0_fail("INPUT", "apply must be an exact Boolean")
    if policy_decision is not None and (type(policy_decision) is not str or not is_valid_slug(policy_decision)):
        raise _initial_v0_fail("INPUT", "policy decision must be a valid bare slug")
    if cutover_date is not None:
        try:
            if type(cutover_date) is not str or not DECISION_DATE_RE.fullmatch(cutover_date) or datetime.strptime(cutover_date, "%Y-%m-%d").strftime("%Y-%m-%d") != cutover_date:
                raise ValueError("noncanonical date")
        except ValueError as exc:
            raise _initial_v0_fail("INPUT", "cutover date must be a valid YYYY-MM-DD") from exc
    for expected in (expected_baseline_sha256, expected_policy_sha256):
        if expected is not None and not _initial_v0_digest(expected):
            raise _initial_v0_fail("INPUT", "expected SHA-256 must be uppercase64hex")
    if apply and any(value is None for value in (policy_decision, cutover_date, expected_baseline_sha256, expected_policy_sha256, operation_id, receipt)):
        raise _initial_v0_fail("INPUT", "explicit apply requires policy, cutover, both expected hashes, operation id and scratch receipt")
    policy_path = root / "work-items" / "decisions" / f"{policy_decision}.md" if policy_decision else None
    if not apply:
        entries, _snapshots = _initial_v0_census(root)
        baseline = _decision_compatibility_baseline_digest(entries) if entries else None
        if expected_baseline_sha256 is not None and expected_baseline_sha256 != baseline:
            raise _initial_v0_fail("STALE", "captured baseline differs")
        policy = None
        if policy_path is not None:
            _lifecycle_reject_unreduced_reparse(policy_path, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY", message="policy path is unsafe")
            snapshot = _capture_file_snapshot(policy_path, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY") if policy_path.exists() else None
            policy = {"path": policy_path.relative_to(root).as_posix(), "sha256": _sha256_bytes(snapshot.data).upper() if snapshot else None}
            if expected_policy_sha256 is not None and policy["sha256"] != expected_policy_sha256:
                raise _initial_v0_fail("STALE", "captured policy differs")
        elif expected_policy_sha256 is not None:
            raise _initial_v0_fail("INPUT", "policy expectation requires a policy identity")
        candidate = _initial_v0_manifest({"policyDecision": policy_decision, "cutoverDate": cutover_date, "expectedBaselineSha256": baseline}, entries) if policy_decision and cutover_date else None
        return _initial_v0_result("prepared" if candidate is not None else "captured", entries, policy, cutover_date, candidate)
    if type(operation_id) is not str or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}", operation_id, re.ASCII) is None:
        raise _initial_v0_fail("INPUT", "operation id is invalid")
    try:
        _initial_v0_relative(receipt)
    except LifecycleError as exc:
        raise _initial_v0_fail("INPUT", "receipt must be a repository-relative scratch path") from exc
    if not receipt.startswith(".scratch/") or len(Path(receipt).parts) < 2 or Path(receipt).name == "work-items-lifecycle-owner.lock":
        raise _initial_v0_fail("INPUT", "receipt must select an ordinary scratch file")
    request = {"policyDecision": policy_decision, "cutoverDate": cutover_date, "expectedBaselineSha256": expected_baseline_sha256,
               "expectedPolicySha256": expected_policy_sha256, "receiptPath": receipt}
    manifest_relative = f"work-items/{DECISION_V0_MANIFEST}"
    receipt_path, pending_path = root / receipt, root / (receipt + ".pending")
    operation = _InitialV0Operation(_CURRENT_LIFECYCLE_TRANSACTION.get(), root, request, operation_id,
                                    (root / manifest_relative, receipt_path, pending_path))
    with contextlib.ExitStack() as stack:
        targets = {path: stack.enter_context(_admit_lifecycle_write_target(root / path, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY", _operation_owner=operation)) for path in (manifest_relative, receipt)}
        operation.targets = targets
        pending_target = stack.enter_context(_admit_lifecycle_write_target(pending_path, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY", _operation_owner=operation))
        operation.pending_target = pending_target
        scope = _initial_v0_scope(root, receipt_path)
        receipt_image, pending_image = targets[receipt].owned_image(), pending_target.owned_image()
        pending = _initial_v0_load(_unb64(pending_image["data"])) if pending_image is not None else None
        if pending_image is not None:
            # Physical presence, not the decoded value, selects mandatory validation.
            pending_entries = _initial_v0_validate_pending(pending, request, operation_id, scope)
        if receipt_image is not None:
            operation.receipt_image = receipt_image
            settled = _initial_v0_load(_unb64(receipt_image["data"]))
            entries = _initial_v0_validate_receipt(settled, request, operation_id, scope)
            # Historical receipt stays immutable; present strict-reader failures remain distinct.
            _preflight_current_decision_v0(root)
            operation.admit(pending, scope, entries)
            if pending_image is not None:
                receipt_after = next(row for row in pending["outputs"] if row["path"] == receipt)["ownedAfter"]
                if receipt_after is None or not _initial_v0_owned(targets[receipt], receipt_after):
                    raise _initial_v0_fail("RECOVERY-CONFLICT", "published receipt differs from recorded stage")
                _initial_v0_cleanup(root, pending, targets, pending_target, pending_image, rollback=False, entries=entries)
            return _initial_v0_result("replayed", entries, {"path": policy_path.relative_to(root).as_posix(), "sha256": expected_policy_sha256}, cutover_date,
                                      _initial_v0_manifest(request, entries), {"path": receipt, "sha256": receipt_image["sha256"]})
        if pending_image is not None:
            entries = pending_entries
            _initial_v0_original_inputs(root, pending, entries)
            settlement = "recovered"
        else:
            if targets[manifest_relative].owned_image() is not None:
                raise _initial_v0_fail("CONFLICT", "initial manifest already exists without matching operation evidence")
            entries, snapshots = _initial_v0_census(root)
            if not entries:
                raise _initial_v0_fail("EMPTY", "first admission requires a nonempty current V0 set")
            if _decision_compatibility_baseline_digest(entries) != expected_baseline_sha256:
                raise _initial_v0_fail("STALE", "fresh complete V0 baseline differs")
            policy_snapshot = _capture_file_snapshot(policy_path, failure_id="WI-DECISION-V0-ADMISSION-STALE")
            if _sha256_bytes(policy_snapshot.data).upper() != expected_policy_sha256:
                raise _initial_v0_fail("STALE", "current policy bytes differ")
            _preflight_current_decision_v0(root, manifest_bytes=_initial_v0_json(_initial_v0_manifest(request, entries)))
            inputs = [{"path": snapshot.path.relative_to(root).as_posix(), "identity": {"kind": "stat", "value": list(snapshot.identity)},
                       "sha256": _sha256_bytes(snapshot.data).upper(), "data": _b64(snapshot.data)} for snapshot in [*snapshots, policy_snapshot]]
            pending = {"schemaVersion": 1, "operation": _INITIAL_V0_OPERATION, "operationId": operation_id, "request": request, "scope": scope,
                       "inputs": sorted(inputs, key=lambda row: row["path"]), "outputs": [{"path": path, "before": None, "ownedAfter": None} for path in sorted(targets)]}
            settlement = "initial"
        operation.admit(pending, scope, entries)
        manifest_row = next(row for row in pending["outputs"] if row["path"] == manifest_relative)
        receipt_row = next(row for row in pending["outputs"] if row["path"] == receipt)
        published_receipt = False
        operation.published_receipt = published_receipt
        unrecorded_stages = operation.unrecorded_stages
        try:
            candidate_data = _initial_v0_json(_initial_v0_manifest(request, entries))
            _initial_v0_original_inputs(root, pending, entries)
            _preflight_current_decision_v0(root, manifest_bytes=candidate_data)
            if pending_image is None:
                manifest_row["ownedAfter"] = _initial_v0_stage(root, targets[manifest_relative], candidate_data)
                unrecorded_stages.append((targets[manifest_relative], manifest_row["ownedAfter"]))
                pending_data = _initial_v0_json(pending)
                _initial_v0_validate_pending(pending, request, operation_id, scope)
                stage = _initial_v0_stage(root, pending_target, pending_data)
                unrecorded_stages.append((pending_target, stage))
                _initial_v0_promote(root, pending_target, stage)
                pending_image = pending_target.owned_image()
                operation.pending_image = pending_image
                unrecorded_stages.clear()
            manifest_image = targets[manifest_relative].owned_image()
            if manifest_image is None:
                image = manifest_row["ownedAfter"]
                stage_image = targets[manifest_relative].owned_image(Path(image["stagePath"]).name)
                if stage_image is None:
                    # Only exactly original absence can release a lost-stage pending record.
                    if all(target.owned_image() is None for target in targets.values()) and receipt_row["ownedAfter"] is None:
                        pending_target.remove_owned(pending_target.leaf, pending_image)
                        pending_image = None
                        operation.pending_image = pending_image
                    raise _initial_v0_fail("RECOVERY-INCOMPLETE", "actual owned manifest stage is missing")
                if not _initial_v0_image_matches(stage_image, image):
                    raise _initial_v0_fail("RECOVERY-CONFLICT", "recorded manifest stage has foreign bytes or identity")
                _initial_v0_promote(root, targets[manifest_relative], image)
            _initial_v0_check_manifest(targets[manifest_relative], manifest_row["ownedAfter"])
            _preflight_current_decision_v0(root)
            _initial_v0_original_inputs(root, pending, entries)
            if receipt_row["ownedAfter"] is not None:
                old_stage = receipt_row["ownedAfter"]
                leaf = Path(old_stage["stagePath"]).name
                if not _initial_v0_owned(targets[receipt], old_stage, leaf):
                    raise _initial_v0_fail("RECOVERY-INCOMPLETE", "recorded receipt stage is missing or changed")
                targets[receipt].remove_owned(leaf, old_stage)
                receipt_row["ownedAfter"] = None
            participants = [{"path": row["path"], "beforeSha256": row["sha256"], "afterSha256": row["sha256"]} for row in pending["inputs"]]
            participants.append({"path": manifest_relative, "beforeSha256": None, "afterSha256": _sha256_bytes(candidate_data).upper()})
            settled = {"schemaVersion": 1, "operation": _INITIAL_V0_OPERATION, "operationId": operation_id, "request": request, "scope": scope,
                       "entries": entries, "participants": sorted(participants, key=lambda row: row["path"]),
                       "readback": {"manifestVerified": True, "legacyBytesUnchanged": True, "policyUnchanged": True}, "settlement": settlement}
            receipt_data = _initial_v0_json(settled)
            _initial_v0_validate_receipt(settled, request, operation_id, scope)
            receipt_row["ownedAfter"] = _initial_v0_stage(root, targets[receipt], receipt_data)
            unrecorded_stages.append((targets[receipt], receipt_row["ownedAfter"]))
            _initial_v0_check_manifest(targets[manifest_relative], manifest_row["ownedAfter"])
            if pending_target.owned_image() != pending_image:
                raise _initial_v0_fail("RECOVERY-CONFLICT", "pending evidence changed before update")
            pending_target.publish(_initial_v0_json(pending))
            pending_image = pending_target.owned_image()
            operation.pending_image = pending_image
            unrecorded_stages.clear()
            _initial_v0_validate_pending(_initial_v0_load(_unb64(pending_image["data"])), request, operation_id, scope)
            _initial_v0_original_inputs(root, pending, entries)
            _initial_v0_check_manifest(targets[manifest_relative], manifest_row["ownedAfter"])
            _initial_v0_promote(root, targets[receipt], receipt_row["ownedAfter"])
            published_receipt = True
            operation.published_receipt = published_receipt
            actual_receipt = targets[receipt].owned_image()
            if actual_receipt is None or _unb64(actual_receipt["data"]) != receipt_data:
                raise _initial_v0_fail("READBACK", "settled receipt readback differs")
            _initial_v0_validate_receipt(_initial_v0_load(_unb64(actual_receipt["data"])), request, operation_id, scope)
            _preflight_current_decision_v0(root)
            _initial_v0_original_inputs(root, pending, entries)
            _initial_v0_check_manifest(targets[manifest_relative], manifest_row["ownedAfter"])
            _initial_v0_cleanup(root, pending, targets, pending_target, pending_image, rollback=False, entries=entries)
            return _initial_v0_result("applied" if settlement == "initial" else "recovered", entries,
                                      {"path": policy_path.relative_to(root).as_posix(), "sha256": expected_policy_sha256}, cutover_date,
                                      _initial_v0_manifest(request, entries), {"path": receipt, "sha256": actual_receipt["sha256"]})
        except BaseException as primary:
            try:
                # Reacquire actual effects; error labels confer no cleanup authority.
                receipt_after = receipt_row["ownedAfter"]
                if receipt_after is not None and _initial_v0_owned(targets[receipt], receipt_after):
                    published_receipt = True
                    operation.published_receipt = published_receipt
                if published_receipt:
                    actual_receipt = targets[receipt].owned_image()
                    _initial_v0_validate_receipt(_initial_v0_load(_unb64(actual_receipt["data"])), request, operation_id, scope)
                    _initial_v0_check_manifest(targets[manifest_relative], manifest_row["ownedAfter"])
                    if pending_image is not None and pending_target.owned_image() is not None:
                        durable = _initial_v0_load(_unb64(pending_image["data"]))
                        _initial_v0_validate_pending(durable, request, operation_id, scope)
                        _initial_v0_cleanup(root, durable, targets, pending_target, pending_image, rollback=False, entries=entries)
                else:
                    if pending_image is None:
                        # Promotion may have completed before its readback failed.
                        for target, image in unrecorded_stages:
                            if target is pending_target and _initial_v0_owned(target, image):
                                pending_image = target.owned_image()
                                operation.pending_image = pending_image
                                break
                    # Dispose only current-invocation effects not referenced by the
                    # actual durable pending image, preserving usable recovery evidence.
                    durable = _initial_v0_load(_unb64(pending_image["data"])) if pending_image is not None else None
                    for target, image in unrecorded_stages:
                        if durable is not None and any(row["ownedAfter"] == image for row in durable["outputs"]):
                            continue
                        leaf = Path(image["stagePath"]).name
                        if target.owned_image(leaf) is not None:
                            target.remove_owned(leaf, image)
                    if pending_image is not None:
                        # Use the durable images for rollback. Unrecorded receipt
                        # stages may already have been disposed independently above.
                        _initial_v0_validate_pending(durable, request, operation_id, scope)
                        _initial_v0_cleanup(root, durable, targets, pending_target, pending_image, rollback=True, entries=entries)
            except BaseException as cleanup:
                composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
                composer.set_rollback("incomplete")
                composer.record_write_cleanup(phase="write-temp-cleanup", failure_id="WI-LIFECYCLE-WRITE-BOUNDARY", resource=receipt + ".pending",
                                               diagnostic="initial admission compensation incomplete; retained operation evidence", cause=cleanup)
            raise primary


def _preflight_current_decision_h1(
    root: Path,
    *,
    manifest_bytes: bytes | None = None,
    acquired_input=None,
) -> dict[str, CurrentDecisionRecord]:
    return _verify_current_decision_compatibility_manifest(
        root,
        DecisionCompatibilityProfile(
            label="H1",
            format=DECISION_FORMAT_H1,
            manifest_name=DECISION_H1_MANIFEST,
            manifest_schema_version=DECISION_H1_MANIFEST_SCHEMA_VERSION,
            anchor_manifest_field="h1-manifest",
            anchor_baseline_field="h1-baseline-sha256",
            anchor_cutover_field="h1-cutover-date",
            manifest_missing_failure_id="WI-DECISION-H1-MANIFEST-MISSING",
            manifest_invalid_failure_id="WI-DECISION-H1-MANIFEST-INVALID",
            unadmitted_failure_id="WI-DECISION-H1-UNADMITTED",
            manifest_stale_failure_id="WI-DECISION-H1-MANIFEST-STALE",
            hash_mismatch_failure_id="WI-DECISION-H1-HASH-MISMATCH",
            retired_reappeared_failure_id="WI-DECISION-H1-RETIRED-REAPPEARED",
            validate_record=_validate_current_decision_h1_manifest_record,
        ),
        manifest_bytes=manifest_bytes,
     acquired_input=acquired_input)


def _validate_canonical_candidate_header(data: bytes) -> None:
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID",
            "canonical candidate header must be UTF-8",
        ) from exc

    lines = text.splitlines()
    if lines and lines[0].strip() == "---":
        closing = next(
            (index for index, line in enumerate(lines[1:], start=2) if line.strip() == "---"),
            None,
        )
        if closing is None:
            raise LifecycleError(
                "WI-CATEGORY-STATUS-INVALID",
                "canonical candidate frontmatter is unterminated",
            )
        header_start, header_end = 2, closing - 1
        malformed_header_end = header_end
    else:
        header_start, header_end = 1, 0
        for line_number, line in enumerate(lines, start=1):
            if not FIELD_RE.fullmatch(line):
                break
            header_end = line_number
        malformed_header_end = 0
        for line_number, line in enumerate(lines, start=1):
            if not line.strip():
                break
            malformed_header_end = line_number

    occurrences = _authoritative_field_occurrences(text)
    statuses = [
        (line_number, value)
        for line_number, name, value, _line in occurrences
        if name == "status"
    ]
    malformed_status = any(
        re.match(
            r"^\s*(?:-\s*)?(?:\*\*)?status(?:\*\*)?(?:\s|$)",
            line,
            re.IGNORECASE,
        )
        and not FIELD_RE.fullmatch(line)
        for line_number, line in _authoritative_markdown_lines(text)
        if header_start <= line_number <= malformed_header_end
    )
    if (
        malformed_status
        or len(statuses) != 1
        or not (header_start <= statuses[0][0] <= header_end)
        or statuses[0][1] != "candidate"
    ):
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID",
            "canonical candidate header requires exactly one 'status: candidate' field",
        )


def _terminalization_authoritative_field_occurrences(
    text: str, utc_field: str = "Terminal-at"
) -> tuple[str, ...]:
    authoritative = {utc_field.casefold(), "v1-migration-evidence"}
    occurrences: list[str] = []
    for _line_number, line in _authoritative_markdown_lines(text):
        match = FIELD_RE.fullmatch(line)
        if match:
            name = match.group(1).strip().casefold()
            if name in authoritative:
                occurrences.append(name)
    return tuple(occurrences)


def _schema_marker_occurrences(data: bytes, member: str) -> tuple[tuple[str, str, str], ...]:
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-CATEGORY-SCHEMA-INVALID",
            f"{member} schema marker source must be UTF-8",
        ) from exc
    occurrences: list[tuple[str, str, str]] = []
    for _line_number, line in _authoritative_markdown_lines(text):
        match = WORK_ITEM_SCHEMA_OCCURRENCE_RE.fullmatch(line)
        if match:
            occurrences.append((line, match.group(1), match.group(2)))
    return tuple(occurrences)


def _require_canonical_schema_marker(
    occurrences: tuple[tuple[str, str, str], ...],
    member: str,
) -> None:
    if len(occurrences) != 1 or occurrences[0] != (
        WORK_ITEM_SCHEMA_MARKER,
        WORK_ITEM_SCHEMA_KEY,
        WORK_ITEM_SCHEMA_VALUE,
    ):
        raise LifecycleError(
            "WI-CATEGORY-SCHEMA-INVALID",
            f"{member} must contain exactly one canonical {WORK_ITEM_SCHEMA_MARKER!r}",
        )


def _stamp_schema_marker(data: bytes, member: str) -> bytes:
    occurrences = _schema_marker_occurrences(data, member)
    if occurrences:
        _require_canonical_schema_marker(occurrences, member)
        return data
    separator = b"" if data.endswith(b"\n") else b"\n"
    return data + separator + WORK_ITEM_SCHEMA_MARKER.encode("utf-8") + b"\n"


def _optional_relation_values(
    value: str | None,
    *,
    comma_separated: bool,
) -> tuple[str, ...]:
    if value is None:
        return ()
    normalized = value.strip()
    if (
        not normalized
        or normalized in OPTIONAL_RELATION_ABSENCE_MARKERS
    ):
        return ()
    if comma_separated:
        return tuple(part.strip() for part in normalized.split(","))
    return (normalized,)


def _strict_utc(value: str) -> datetime:
    if not UTC_INSTANT_RE.fullmatch(value):
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            f"terminal instant must be strict UTC YYYY-MM-DDTHH:MM:SSZ: {value!r}",
        )
    try:
        parsed = datetime.strptime(value, "%Y-%m-%dT%H:%M:%SZ")
    except ValueError as exc:
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            f"invalid terminal instant: {value!r}",
        ) from exc
    if parsed.strftime("%Y-%m-%dT%H:%M:%SZ") != value:
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            f"non-canonical terminal instant: {value!r}",
        )
    return parsed


def archive_month(terminal_instant: str) -> str:
    return _strict_utc(terminal_instant).strftime("%Y-%m")


_NATIVE_CREATION_OWNER = object()


@dataclass(init=False)
class _OwnedNativeCreation:
    """One actual native acquisition, its creator custody and finite closeout."""
    owner: object
    preparation: object
    locator: Path
    parent: object
    directory: bool
    role: str
    scope: CapturedPathParentChain
    seal: object
    operation_owner: object = None
    handle: object = None
    creator: bool = False
    acquired: bool = False
    native_result: object = None
    identity: object = None
    holder: str = "unacquired"
    directory_owner: object = None
    directory_index: object = None
    phase: str = "prepared"
    creation_published: bool = False
    placement: object = None
    deletion_accepted: bool = False
    disposal_proof: object = None
    release_attempted: bool = False
    release_complete: bool = False
    projection_complete: bool = False
    finished: bool = False
    raw_failure: object = None
    primary: object = None
    secondary: tuple = ()


class LifecycleWriteTarget:
    """One process-local ordinary-parent capability for a lifecycle file effect."""

    def __init__(self, path: Path, *, failure_id: str, _operation_owner=None, inverse=None):
        self.path = _lifecycle_unresolved_absolute(path)
        self.leaf = self.path.name
        self.failure_id = failure_id
        self._directories = []
        self._parent = None
        self._open = False
        self._native = None
        self._operation_owner = _operation_owner
        self._inverse = inverse
        self._creations: list[_OwnedNativeCreation] = []
        self._creation_observation_active = False
        self._creation_process = None
        self._creation_thread = None
        self._source_observation = None

    def _operation_transaction(self):
        """Resolve this actual binding without letting ambient state replace it."""
        ambient = _CURRENT_LIFECYCLE_TRANSACTION.get()
        operation = self._operation_owner
        explicit = operation if isinstance(operation, LifecycleTransaction) else getattr(operation, "transaction", None)
        if isinstance(explicit, LifecycleTransaction):
            if ambient is not None and ambient is not explicit:
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "observation operation context differs")
            return explicit
        return ambient

    def _assert_creation_settlement(self):
        transaction = self._operation_transaction()
        movement = transaction._active_relocation if transaction is not None else None
        if (movement is not None and movement._creation_observation_active
                and any(self is participant for participant in
                        (movement.source_owner, movement.target_owner, movement.observation_owner))):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "operation capability is borrowed by an active observation")
        if self._creation_observation_active:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creator is borrowed by an active observation")
        if self._creation_process is not None and (self._creation_process != os.getpid()
                or self._creation_thread is not threading.current_thread()):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creator process or thread differs")
        return transaction

    def _borrow_directory(self, path, parent=None):
        """Qualify existing creation custody; return its record, never close authority."""
        transaction = self._operation_transaction()
        movement = transaction._active_relocation if transaction is not None else None
        active = self._creation_observation_active or (movement is not None and movement._creation_observation_active)
        if not active or (self._creation_process is not None and
                (self._creation_process != os.getpid() or self._creation_thread is not threading.current_thread())):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation lacks its synchronous owner")
        removal = self._source_observation
        if removal is not None and path == removal.source:
            if (type(removal) is not _PreparedLifecycleEffect or removal.owner is not self
                    or removal.transaction is not transaction or not transaction._locked
                    or self._operation_owner is not transaction or removal.source_owner is not self
                    or removal.destination is not None or not removal.directory or removal.handle is None
                    or not removal.current_pair_is_bound()):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "removal observation lacks its actual custodian")
            self._verify_owned()
            info = path.lstat()
            expected = _lifecycle_file_identity(removal.before[path][0])
            identity = self._identity(removal.handle)
            _lifecycle_reject_unreduced_reparse(path, failure_id="WI-LIFECYCLE-EFFECT", message="removed directory path is unsafe")
            parent_identity = _lifecycle_file_identity(path.parent.lstat())
            if (not stat.S_ISDIR(info.st_mode) or identity != expected
                    or _lifecycle_file_identity(info) != identity
                    or not any(p == path.parent and i == parent_identity and self._identity(h) == i
                               for p, h, i in self._directories)
                    or (parent is not None and self._identity(parent) != parent_identity)):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "removal observation native source or parent differs")
            return removal
        if movement is not None and movement.directory and path in (movement.source, movement.destination):
            source_owner, target_owner = movement.source_owner, movement.target_owner
            if (movement.transaction is not transaction or not transaction._locked
                    or source_owner is None or target_owner is None or movement.handle is None
                    or source_owner._operation_owner is not transaction or target_owner._operation_owner is not transaction):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "relocation observation lacks its actual custodians")
            source_owner._verify_owned(); target_owner._verify_owned()
            info = path.lstat()
            expected = _lifecycle_file_identity(movement.before[movement.source][0])
            identity = source_owner._identity(movement.handle)
            _lifecycle_reject_unreduced_reparse(path, failure_id="WI-LIFECYCLE-EFFECT", message="relocated directory path is unsafe")
            if not stat.S_ISDIR(info.st_mode) or identity != expected or _lifecycle_file_identity(info) != identity:
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "relocation observation native source differs")
            parent_identity = _lifecycle_file_identity(path.parent.lstat())
            participants = source_owner._directories + target_owner._directories
            if not any(p == path.parent and i == parent_identity and source_owner._identity(h) == i for p, h, i in participants):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "relocation observation parent lacks custody")
            if parent is not None and self._identity(parent) != parent_identity:
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "relocation observation reader parent differs")
            return movement
        if any(type(record) is not _OwnedNativeCreation for record in self._creations):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation custody is malformed")
        matches = [record for record in self._creations if record.locator == path and record.directory]
        if not matches:
            return None
        if len(matches) != 1:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation has ambiguous custody")
        record = matches[0]
        if (self._creation_process is None or record.seal is not _NATIVE_CREATION_OWNER
                or record.owner is not self or not record.creator or not record.acquired
                or record.handle is None or record.finished or record.release_attempted or record.release_complete
                or record.deletion_accepted or record.holder not in {"outer", "directory-owner"}
                or record.role not in {"constructed-parent", "legacy-directory"}
                or record.phase not in {"acquired", "creation-view-published", "creation-checked", "retained"}
                or (record.native_result != 2 if os.name == "nt" else record.native_result != "mkdir-created")):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation custody is unavailable")
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if record.preparation is None:
            if transaction is not None or record.operation_owner is not self._operation_owner:
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation operation changed")
        else:
            prepared = record.preparation
            if (type(prepared) is not _PreparedLifecycleEffect or prepared.owner is not self
                    or transaction is not prepared.transaction or not transaction._locked
                    or record.operation_owner is not transaction._operation_owner
                    or prepared.source is not None or prepared.destination != path or not prepared.directory
                    or path not in prepared.before or prepared.before[path] is not None):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation acquisition differs")
            if record.creation_published:
                current = transaction._retained_observations.get(path)
                if not isinstance(current, CapturedDirectorySnapshotV1) or _lifecycle_file_identity(current.metadata) != self._identity(record.handle):
                    raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation current epoch differs")
            elif (not prepared.current_pair_is_bound()
                    or ((transaction._binding_evidence is prepared.evidence)
                        != (transaction._retained_observations is prepared.observation_reference))):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation preparation is stale")
        if record.directory_owner is not None:
            index = record.directory_index
            if (record.directory_owner is not self._directories or type(index) is not int
                    or not 0 <= index < len(self._directories)
                    or self._directories[index][0] != path or self._directories[index][1] != record.handle):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation close custody differs")
        elif record.directory_index is not None or record.holder != "outer":
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation holder differs")
        self._verify_owned(_creation=record)
        _verify_captured_parent_chain(record.scope, "WI-LIFECYCLE-EFFECT")
        _lifecycle_reject_unreduced_reparse(path, failure_id="WI-LIFECYCLE-EFFECT", message="borrowed directory path is unsafe")
        metadata, parent_metadata = path.lstat(), path.parent.lstat()
        identity = self._identity(record.handle)
        if (not stat.S_ISDIR(metadata.st_mode) or _lifecycle_file_identity(metadata) != identity
                or (record.identity is not None and record.identity != identity)
                or self._identity(record.parent) != _lifecycle_file_identity(parent_metadata)
                or (parent is not None and self._identity(parent) != self._identity(record.parent))):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "borrowed directory native or parent identity differs")
        return record

    def _new_creation(self, path, preparation, parent, *, directory=False, role="temporary"):
        self._assert_creation_settlement()
        if self._creation_process is None:
            self._creation_process, self._creation_thread = os.getpid(), threading.current_thread()
        path = _lifecycle_unresolved_absolute(path)
        if os.path.lexists(path):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation requires its original absence")
        scope = _capture_path_parent_chain(path, "WI-LIFECYCLE-EFFECT")
        record = object.__new__(_OwnedNativeCreation)
        record.owner, record.preparation, record.locator = self, preparation, path
        record.parent, record.directory, record.role = parent, directory, role
        record.scope, record.seal = scope, _NATIVE_CREATION_OWNER
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        record.operation_owner = transaction._operation_owner if transaction is not None else self._operation_owner
        self._creations.append(record)
        return record

    def _creation_secondary(self, record, primary, phase, cause):
        if record is not None:
            record.secondary += ((phase, cause),)
        composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
        if composer is not None:
            composer.record_write_cleanup(phase=phase, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY",
                resource=record.locator.name if record is not None else self.leaf,
                diagnostic="owned native creation closeout incomplete", cause=cause)
            return
        if primary is not None:
            BaseException.add_note(primary, f"WI-LIFECYCLE-WRITE-BOUNDARY secondary {phase}: {type(cause).__name__[:80]}")
            return
        return cause

    def _release_creation(self, record, primary):
        self._assert_creation_settlement()
        if record.handle is None or record.release_attempted:
            return
        record.release_attempted = True
        try:
            self._close(record.handle)
        except BaseException as cause:
            record.holder = "uncertain"
            self._creation_secondary(record, primary, "write-target-release", cause)
            if primary is None:
                selected = cause if isinstance(cause, LifecycleError) or not isinstance(cause, Exception) else self._failure("handle release", cause)
                self._select_creation_primary(record, selected)
                if selected is cause:
                    raise
                raise selected from cause
        else:
            record.release_complete = True
            record.holder = "released"

    def _finish_creation(self, record, primary, *, abort):
        self._assert_creation_settlement()
        if record.finished:
            return
        record.primary = primary
        removal = None
        cleanup_failed = False
        try:
            if abort and record.creator and record.phase not in {"promoted", "final-placed", "retained"}:
                if record.creation_published:
                    try:
                        removal = self._prepare_effect(record.locator, None, directory=record.directory)
                    except BaseException as cause:
                        cleanup_failed = True
                        self._creation_secondary(record, primary, "write-temp-cleanup", cause)
                try:
                    if record.handle is None or record.holder == "released":
                        raise LifecycleError("WI-LIFECYCLE-EFFECT", "creator capability is unavailable")
                    if os.name == "nt":
                        self._windows_delete(record.handle)
                        record.disposal_proof = "windows-creator-handle"
                    else:
                        actual = os.stat(record.locator.name, dir_fd=record.parent, follow_symlinks=False)
                        creator = os.fstat(record.handle)
                        if _lifecycle_file_identity(actual) != _lifecycle_file_identity(creator):
                            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creator locator now names a foreign object")
                        record.identity = _lifecycle_file_identity(creator)
                        if record.directory:
                            os.rmdir(record.locator.name, dir_fd=record.parent)
                        else:
                            os.unlink(record.locator.name, dir_fd=record.parent)
                        record.disposal_proof = "posix-parent-descriptor"
                    record.deletion_accepted = True
                    record.phase = "disposal-pending"
                except BaseException as cause:
                    cleanup_failed = True
                    self._creation_secondary(record, primary, "write-temp-cleanup", cause)
        finally:
            try:
                self._release_creation(record, primary)
                if record.deletion_accepted and record.release_complete:
                    record.phase = "disposed"
                    try:
                        if os.path.lexists(record.locator):
                            raise LifecycleError("WI-LIFECYCLE-EFFECT", "disposed creator locator is not absent")
                        _verify_captured_parent_chain(record.scope, "WI-LIFECYCLE-EFFECT")
                        if record.preparation is not None:
                            if record.creation_published:
                                if removal is None or cleanup_failed:
                                    raise LifecycleError("WI-LIFECYCLE-EFFECT", "settled creator removal has no complete projection proof")
                                self._publish_effect(removal, record.identity)
                            else:
                                record.preparation.transaction.publish_owned_effect(record.preparation, creator_outcome=record)
                        record.projection_complete = True
                    except BaseException as cause:
                        self._creation_secondary(record, primary, "write-temp-cleanup", cause)
                elif abort and record.creator and record.phase not in {"promoted", "final-placed", "retained"}:
                    record.phase = "unsettled"
            finally:
                record.finished = True

    def _select_creation_primary(self, record, primary):
        record.primary = primary
        composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
        if composer is not None:
            composer.capture_primary(primary)

    def _prepare_effect(self, source, destination, **relation):
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        return None if transaction is None else transaction.prepare_owned_effect(self, source, destination, inverse=self._inverse, **relation)

    def _publish_effect(self, prepared, identity):
        if prepared is not None:
            prepared.transaction.publish_owned_effect(prepared, native_identity=identity)

    @classmethod
    def make_directories(cls, path, transaction, *, created=None, failure_id="WI-LIFECYCLE-EFFECT"):
        """Publish structural directories under the explicit held domain owner.

        Returned records retain actual creator identity after their handles close.
        They license only the caller's explicit same-invocation empty rollback.
        """
        path = _lifecycle_unresolved_absolute(path)
        if (not isinstance(transaction, LifecycleTransaction) or not transaction._locked
                or _CURRENT_LIFECYCLE_TRANSACTION.get() is not transaction
                or not path.is_relative_to(transaction.repository_root)):
            raise LifecycleError(failure_id, "structural directory requires its held repository owner")
        transaction.verify()
        records = [] if created is None else created
        first = len(records)
        missing = []
        cursor = path
        while not os.path.lexists(cursor):
            missing.append(cursor)
            cursor = cursor.parent
        for directory in reversed(missing):
            owner = cls(directory, failure_id=failure_id, _operation_owner=transaction)
            primary = None
            record = None
            try:
                owner._acquire_existing_parents()
                preparation = transaction.prepare_owned_effect(owner, None, directory, directory=True)
                record = owner._new_creation(directory, preparation, owner._parent,
                    directory=True, role="constructed-parent")
                records.append(record)
                if os.name == "nt":
                    child = owner._windows_child(owner._parent, directory.name, directory=True,
                        create=True, exclusive=True, delete=True, _creation=record)
                else:
                    # Preserve the existing mkdirat/openat contract; this does
                    # not claim atomic creator exclusion across these calls.
                    os.mkdir(directory.name, mode=0o777, dir_fd=owner._parent)
                    record.creator, record.acquired, record.phase = True, True, "acquired"
                    record.native_result = "mkdir-created"
                    child = os.open(directory.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                        dir_fd=owner._parent)
                    record.handle, record.holder = child, "outer"
                    os.set_inheritable(child, False)
                record.identity = owner._identity(child)
                owner._verify_owned()
                owner._publish_effect(preparation, record.identity)
                record.creation_published = True
                record.phase = "retained"
            except BaseException as exc:
                primary = exc
                if record is not None:
                    if record.raw_failure is None:
                        record.raw_failure = exc
                    owner._select_creation_primary(record, exc)
                raise
            finally:
                owner.__exit__(type(primary) if primary is not None else None, primary,
                    primary.__traceback__ if primary is not None else None)
        # Existing hierarchy is acquired as current structure, never adopted as
        # a creator. All delete-capable creator handles are closed before this.
        snapshot = _capture_owned_directory_snapshot(path, failure_id=failure_id)
        transaction.observe_retained_inputs((snapshot,))
        transaction.verify()
        return tuple(records[first:])

    @classmethod
    def remove_created_directory(cls, record, transaction, *, failure_id="WI-LIFECYCLE-EFFECT"):
        """Remove this invocation's published empty creator object, never a path substitute."""
        if (type(record) is not _OwnedNativeCreation or record.seal is not _NATIVE_CREATION_OWNER
                or not isinstance(transaction, LifecycleTransaction) or not transaction._locked
                or _CURRENT_LIFECYCLE_TRANSACTION.get() is not transaction
                or record.preparation is None or record.preparation.transaction is not transaction
                or record.owner._operation_owner is not transaction
                or not any(value is record for value in record.owner._creations)
                or not record.directory or not record.creator or not record.acquired
                or not record.creation_published or record.phase != "retained"
                or not record.finished or not record.release_complete or record.identity is None):
            raise LifecycleError(failure_id, "empty directory rollback lacks its actual creator record")
        path = record.locator
        snapshot = transaction._retained_observations.get(path)
        if (not isinstance(snapshot, CapturedDirectorySnapshotV1)
                or _lifecycle_file_identity(snapshot.metadata) != record.identity or snapshot.members):
            raise LifecycleError(failure_id, "created directory has no matching empty current proof")
        _verify_captured_parent_chain(record.scope, failure_id)
        _verify_owned_directory_snapshot(snapshot, failure_id)
        owner = cls(path, failure_id=failure_id, _operation_owner=transaction)
        primary = None
        handle = None
        identity = record.identity
        try:
            owner._acquire_existing_parents()
            removal = transaction.prepare_owned_effect(owner, path, None, directory=True)
            if os.name == "nt":
                handle = owner._windows_child(owner._parent, path.name, directory=True, delete=True)
            else:
                handle = os.open(path.name, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW,
                    dir_fd=owner._parent)
            if owner._identity(handle) != identity:
                raise LifecycleError(failure_id, "created directory now names a foreign object")
            owner._verify_effect_source(removal, handle)
            owner._verify_owned()
            object.__setattr__(removal, "source_owner", owner)
            object.__setattr__(removal, "handle", handle)
            owner._source_observation = removal
            _verify_owned_directory_snapshot(snapshot, failure_id, creation_owner=owner)
            if os.name == "nt":
                owner._windows_delete(handle)
            else:
                if _lifecycle_file_identity(os.stat(path.name, dir_fd=owner._parent,
                        follow_symlinks=False)) != identity:
                    raise LifecycleError(failure_id, "created directory identity changed before removal")
                os.rmdir(path.name, dir_fd=owner._parent)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            try:
                owner._source_observation = None
                if handle is not None:
                    owner._release_handle(handle, primary)
            finally:
                owner.__exit__(type(primary) if primary is not None else None, primary,
                    primary.__traceback__ if primary is not None else None)
        owner._publish_effect(removal, identity)

    def _receive_placement(self, record, data):
        """Receive this creator's actual promotion before domain progress or release."""
        self._assert_creation_settlement()
        if (type(record) is not _OwnedNativeCreation or record.seal is not _NATIVE_CREATION_OWNER
                or record.owner is not self or not any(value is record for value in self._creations)
                or not record.creator or not record.acquired or record.finished or record.release_attempted
                or record.handle is None or record.holder != "outer" or record.directory
                or record.phase not in {"creation-view-published", "creation-checked", "promoted", "final-placed"}):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "placement lacks its actual creator custody")
        self._verify_owned()
        _lifecycle_reject_unreduced_reparse(self.path, failure_id="WI-LIFECYCLE-EFFECT", message="placement path is unsafe")
        metadata = self.path.lstat()
        if (not stat.S_ISREG(metadata.st_mode) or _lifecycle_file_identity(metadata) != record.identity
                or self._identity(record.handle) != record.identity
                or self._read_handle(record.handle, len(data)) != data):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "owned placement identity or bytes changed")
        placement = record.placement
        if placement is not None and (placement.owner is not self or placement.destination != self.path
                or placement.source != record.preparation.destination or placement.data != data):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "placement differs from its prepared creator relation")
        self._publish_effect(placement, record.identity)
        if placement is not None:
            current = placement.transaction._retained_observations.get(self.path)
            if (not placement.current_pair_is_bound() or not isinstance(current, CapturedFileSnapshot)
                    or current.identity != record.identity or current.data != data):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "placement has no received current proof")
            _verify_captured_file(current, "WI-LIFECYCLE-EFFECT")
        record.locator, record.phase = self.path, "final-placed"

    def _verify_effect_source(self, prepared, handle):
        if prepared is None or prepared.source is None:
            return
        info, snapshot = prepared.before[prepared.source]
        if self._identity(handle) != _lifecycle_file_identity(info):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "prepared source changed before native effect")
        if isinstance(snapshot, CapturedFileSnapshot) and self._read_handle(handle, len(snapshot.data)) != snapshot.data:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "prepared source bytes changed before native effect")

    def _failure(self, stage: str, cause: BaseException) -> LifecycleError:
        return LifecycleError("WI-LIFECYCLE-WRITE-BOUNDARY", f"{stage}: {cause}")

    def _acquire_existing_parents(self, *, creation_owner=None, borrowed=None):
        """Acquire the directory reader's native chain without namespace effects.

        The read consumer owns finally-close, including partial acquisition.
        Ordinary constructive __enter__ remains the separate write operation.
        """
        if self._open or self._directories:
            raise self._failure("existing-parent acquisition", OSError("native owner is already active"))
        if creation_owner is not None and borrowed is None:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation observation lacks borrowed ancestry")
        if self._creation_process is None:
            self._creation_process, self._creation_thread = os.getpid(), threading.current_thread()
        if os.name == "nt":
            self._initialize_windows()
            handle = self._windows_root(self.path.anchor)
        else:
            handle = os.open(self.path.anchor, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
        cursor = Path(self.path.anchor)
        self._retain_directory(cursor, handle)
        ancestry = [(cursor, self._identity(handle))]
        for part in self.path.parent.parts[1:]:
            cursor /= part
            record = creation_owner._borrow_directory(cursor, handle) if creation_owner is not None else None
            if record is not None:
                child = record.handle
                identity = creation_owner._identity(child)
                borrowed.append((record, cursor, identity))
            elif os.name == "nt":
                child = self._windows_child(handle, part, directory=True, create=False)
            else:
                child = os.open(part, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=handle)
            if record is None:
                self._retain_directory(cursor, child)
            ancestry.append((cursor, self._identity(child)))
            handle = child
        self._parent, self._open = handle, True
        self._verify_owned()
        return CapturedPathParentChain(tuple(ancestry))

    def _admit_mutation(self):
        transaction = self._operation_transaction()
        if transaction is not None and self._inverse is not None:
            transaction._admit_inverse_mutation(self._inverse)
            if self.path not in (self._inverse.source, self._inverse.destination):
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "native target differs from admitted inverse")
        return transaction

    def _admit_write(self, data):
        self._admit_mutation()
        if self._inverse is not None and (self._inverse.directory
                or self._inverse.destination != self.path or self._inverse.data is None
                or not isinstance(data, bytes) or data != self._inverse.data):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "native write differs from admitted inverse meaning")

    def __enter__(self):
        self._admit_mutation()
        if self._inverse is not None and (self._inverse.directory
                or self._inverse.destination != self.path or self._inverse.data is None):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "constructive target is not the admitted inverse write")
        if self._open or self._directories or any(record.holder == "uncertain" or record.phase in {"unsettled", "promoted"}
                or (record.phase == "disposed" and not record.projection_complete) for record in self._creations):
            raise LifecycleError("WI-LIFECYCLE-WRITE-BOUNDARY", "native target has unsettled ownership")
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if transaction is not None:
            transaction.verify(inverse=self._inverse)
        try:
            if not self.leaf or self.leaf in {".", ".."}:
                raise OSError(errno.EINVAL, "destination has no simple leaf")
            if os.name == "nt":
                self._initialize_windows()
                handle = self._windows_root(self.path.anchor)
            else:
                if not getattr(os, "O_NOFOLLOW", 0) or not getattr(os, "O_DIRECTORY", 0) or not all(
                    function in os.supports_dir_fd for function in (os.open, os.stat, os.mkdir, os.unlink, os.rename)
                ):
                    raise OSError(errno.ENOTSUP, "handle-relative no-follow writes unavailable")
                handle = os.open(self.path.anchor, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
            current = Path(self.path.anchor)
            self._retain_directory(current, handle)
            if os.name != "nt":
                os.set_inheritable(handle, False)
            for component in self.path.parent.parts[1:]:
                current = current / component
                missing = not os.path.lexists(current)
                effect = (self._prepare_effect(None, current, directory=True, replace_existing=True)
                          if missing and transaction is not None and current.is_relative_to(transaction.repository_root) else None)
                record = self._new_creation(current, effect, handle, directory=True, role="constructed-parent") if missing else None
                if os.name == "nt":
                    child = self._windows_child(handle, component, directory=True, create=missing, exclusive=missing, _creation=record)
                else:
                    if missing:
                        os.mkdir(component, mode=0o777, dir_fd=handle)
                        record.creator, record.acquired, record.phase = True, True, "acquired"
                        record.native_result = "mkdir-created"
                    child = os.open(component, os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW, dir_fd=handle)
                    if record is not None:
                        record.handle, record.holder = child, "outer"
                self._retain_directory(current, child, _creation=record)
                if os.name != "nt":
                    os.set_inheritable(child, False)
                if record is not None:
                    record.identity = self._identity(child)
                    self._publish_effect(effect, record.identity)
                    record.creation_published = effect is not None
                    record.phase, record.holder = "creation-view-published" if record.creation_published else "creation-checked", "directory-owner"
                handle = child
            self._parent = handle
            self._open = True
            self.verify()
            try:
                observed = self._file(self.leaf)
            except FileNotFoundError:
                observed = None
            if observed is not None:
                self._release_handle(observed)
            self.verify()
            for record in self._creations:
                if record.holder == "directory-owner":
                    record.phase = "retained"
            return self
        except BaseException as exc:
            primary = exc if isinstance(exc, LifecycleError) else LifecycleError(self.failure_id, f"write target admission: {exc}")
            for record in self._creations:
                if not record.finished or record.raw_failure is exc or record.directory_owner is self._directories:
                    if record.raw_failure is None:
                        record.raw_failure = exc
                    self._select_creation_primary(record, primary)
            self.__exit__(type(primary), primary, primary.__traceback__)
            if primary is exc:
                raise
            raise primary from exc

    def __exit__(self, kind, primary, traceback):
        self._assert_creation_settlement()
        failures = []
        for record in reversed(self._creations):
            if not record.finished and record.directory_owner is not self._directories:
                try:
                    self._finish_creation(record, primary, abort=primary is not None)
                except BaseException as cause:
                    failures.append((record, cause))
        for index in reversed(range(len(self._directories))):
            _path, handle, _identity = self._directories[index]
            record = next((value for value in reversed(self._creations)
                           if value.directory_owner is self._directories and value.directory_index == index), None)
            try:
                if record is not None:
                    self._finish_creation(record, primary, abort=primary is not None and record.phase != "retained")
                else:
                    self._close(handle)
            except BaseException as cause:
                failures.append((record, cause))
        self._directories = []
        self._parent = None
        self._open = False
        if failures:
            operation = self._operation_owner
            transaction = operation if isinstance(operation, LifecycleTransaction) else getattr(operation, "transaction", None)
            movement = transaction._active_relocation if isinstance(transaction, LifecycleTransaction) else None
            if movement is not None and (self is movement.source_owner or self is movement.target_owner
                    or isinstance(operation, _PendingLegacyCompletionPlan)):
                identity = _lifecycle_file_identity(movement.before[movement.source][0])
                transaction._unsettled_relocations += (UnsettledLifecycleRelocation(movement.source, movement.destination, identity),)
            composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
            if composer is not None:
                for record, cause in failures:
                    if record is not None and record.primary is cause:
                        continue  # The creation owner already recorded this actual release failure.
                    composer.record_write_cleanup(phase="write-target-release", failure_id="WI-LIFECYCLE-WRITE-BOUNDARY",
                        resource=self.leaf, diagnostic="write target handle release failed", cause=cause)
            elif primary is not None:
                for _record, cause in failures:
                    BaseException.add_note(primary, f"WI-LIFECYCLE-WRITE-BOUNDARY secondary write-target-release: {type(cause).__name__[:80]}")
            else:
                first = failures[0][1]
                selected = first if isinstance(first, LifecycleError) or not isinstance(first, Exception) else self._failure("handle release", first)
                for _record, cause in failures[1:]:
                    BaseException.add_note(selected, f"WI-LIFECYCLE-WRITE-BOUNDARY secondary write-target-release: {type(cause).__name__[:80]}")
                if selected is first:
                    raise selected
                raise selected from first
        return False

    def _retain_directory(self, path: Path, handle, *, _creation=None) -> None:
        self._assert_creation_settlement()
        index = len(self._directories)
        self._directories.append((path, handle, None))
        if _creation is not None:
            _creation.directory_owner, _creation.directory_index = self._directories, index
        self._directories[index] = (path, handle, self._identity(handle))

    def _check_leaf(self, leaf: str) -> None:
        if not isinstance(leaf, str) or not leaf or leaf in {".", ".."} or "/" in leaf or "\\" in leaf:
            raise OSError(errno.EINVAL, "not a simple child leaf")
        if os.name == "nt" and ":" in leaf:
            raise OSError(errno.EINVAL, "alternate streams are not ordinary child leaves")

    def verify(self) -> None:
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if transaction is not None:
            transaction.verify(creation_owner=self, inverse=self._inverse)
        if any(record.finished and (record.holder == "uncertain" or record.phase in {"unsettled", "promoted"}
                or (record.phase == "disposed" and not record.projection_complete)) for record in self._creations):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "native creator current evidence is unsettled")
        self._verify_owned()

    def _verify_owned(self, *, _creation=None) -> None:
        if not self._open and (_creation is None or not any(record is _creation for record in self._creations)
                or _creation.directory_owner is not self._directories or not _creation.acquired):
            raise self._failure("currentness", OSError("write target is closed"))
        try:
            for path, handle, identity in self._directories:
                observed = path.lstat()
                if not stat.S_ISDIR(observed.st_mode) or _lifecycle_path_has_reparse(path):
                    raise OSError("admitted directory path changed kind")
                if self._identity(handle) != identity or _lifecycle_file_identity(observed) != identity:
                    raise OSError("admitted directory identity changed")
        except OSError as exc:
            raise self._failure("currentness", exc) from exc

    def _file(self, leaf: str, *, create: bool = False, delete: bool = False, _creation=None):
        self._check_leaf(leaf)
        if create and _creation is None:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "native creator custody must precede acquisition")
        if _creation is not None and (type(_creation) is not _OwnedNativeCreation or _creation.seal is not _NATIVE_CREATION_OWNER
                or not create or _creation.owner is not self
                or _creation.parent != self._parent or _creation.locator.name != leaf):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation custody differs from native request")
        if os.name == "nt":
            return self._windows_child(self._parent, leaf, create=create, exclusive=create, delete=delete, write=create, _creation=_creation)
        flags = os.O_RDWR | os.O_CREAT | os.O_EXCL if create else os.O_RDONLY
        descriptor = os.open(leaf, flags | os.O_NOFOLLOW | getattr(os, "O_NONBLOCK", 0), 0o600, dir_fd=self._parent)
        try:
            if _creation is not None:
                _creation.handle, _creation.acquired, _creation.creator = descriptor, True, True
                _creation.native_result = "exclusive-open"
                _creation.holder, _creation.phase = "inner", "acquired"
            os.set_inheritable(descriptor, False)
            if not stat.S_ISREG(os.fstat(descriptor).st_mode):
                raise OSError("child is not an ordinary file")
            if _creation is not None:
                _creation.holder = "outer"
            return descriptor
        except BaseException as primary:
            if _creation is not None:
                _creation.raw_failure = primary
                self._finish_creation(_creation, primary, abort=True)
            else:
                self._release_handle(descriptor, primary)
            raise

    def read(self, leaf: str | None = None, *, maximum_bytes: int = 4 * 1024 * 1024) -> bytes | None:
        self.verify()
        leaf = self.leaf if leaf is None else leaf
        try:
            handle = self._file(leaf)
        except FileNotFoundError:
            self.verify()
            return None
        primary = None
        try:
            return self._read_handle(handle, maximum_bytes)
        except OSError as exc:
            primary = self._failure("child read", exc)
            raise primary from exc
        except BaseException as exc:
            primary = exc
            raise
        finally:
            self._release_handle(handle, primary)

    def _read_handle(self, handle, maximum_bytes: int) -> bytes:
        """Read a bounded whole image on this handle; success leaves its cursor at EOF."""
        if os.name == "nt":
            c, w, k, _nt, _types = self._native
            if not k.SetFilePointerEx(w.HANDLE(handle), c.c_longlong(0), None, 0):
                raise OSError(c.get_last_error(), "native child positioning failed")
            return self._windows_read(handle, maximum_bytes)
        if os.fstat(handle).st_size > maximum_bytes:
            raise OSError("child exceeds its admitted byte envelope")
        os.lseek(handle, 0, os.SEEK_SET)
        chunks = []
        total = 0
        while True:
            part = os.read(handle, min(65536, maximum_bytes + 1 - total))
            if not part:
                break
            chunks.append(part); total += len(part)
            if total > maximum_bytes:
                raise OSError("child exceeds its admitted byte envelope")
        return b"".join(chunks)

    def quarantine(self, current: bytes) -> None:
        self._admit_mutation()
        if self._inverse is not None:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "quarantine is not an admitted inverse meaning")
        leaf = f"{self.leaf}.conflict-{_sha256_bytes(current)[:16]}"
        existing = self.read(leaf)
        if existing is not None and existing != current:
            raise LifecycleError(self.failure_id, "receipt quarantine conflicts")
        if existing is not None:
            return
        self.verify()
        movement = self._prepare_effect(self.path, self.path.parent / leaf, data=current)
        handle = self._file(self.leaf, delete=True)
        primary = None
        try:
            if self._read_handle(handle, len(current)) != current:
                raise self._failure("quarantine", OSError("receipt changed before quarantine"))
            self.verify()
            self._verify_effect_source(movement, handle)
            if os.name == "nt":
                self._windows_rename(handle, leaf, replace=False)
            else:
                # Exclusive destination link then owned-source unlink cannot overwrite a collision.
                os.link(self.leaf, leaf, src_dir_fd=self._parent, dst_dir_fd=self._parent, follow_symlinks=False)
                if os.stat(self.leaf, dir_fd=self._parent, follow_symlinks=False).st_ino != os.fstat(handle).st_ino:
                    raise OSError("quarantine source identity changed")
                os.unlink(self.leaf, dir_fd=self._parent)
            self._publish_effect(movement, self._identity(handle))
            self.verify()
        except BaseException as exc:
            primary = exc
            raise
        finally:
            self._release_handle(handle, primary)

    def publish(self, data: bytes) -> None:
        self._admit_write(data)
        self.verify()
        leaf = f".{self.leaf}.{uuid.uuid4().hex}.tmp"
        record = None
        primary = None
        try:
            creation = self._prepare_effect(None, self.path.parent / leaf, data=data)
            record = self._new_creation(self.path.parent / leaf, creation, self._parent)
            handle = self._file(leaf, create=True, delete=True, _creation=record)
            record.identity = self._identity(handle)
            self._write_handle(handle, data)
            self._publish_effect(creation, record.identity)
            record.creation_published = creation is not None
            record.phase = "creation-view-published" if record.creation_published else "creation-checked"
            promotion = self._prepare_effect(record.locator, self.path, data=data, replace_existing=True)
            record.placement = promotion
            self.verify()
            self._verify_effect_source(promotion, handle)
            if os.name == "nt":
                self._windows_rename(handle, self.leaf, replace=True)
            else:
                if _lifecycle_file_identity(os.stat(leaf, dir_fd=self._parent, follow_symlinks=False)) != record.identity:
                    raise OSError("owned temporary identity changed")
                os.replace(leaf, self.leaf, src_dir_fd=self._parent, dst_dir_fd=self._parent)
            record.locator, record.phase = self.path, "promoted"
            self._receive_placement(record, data)
            if os.name != "nt":
                self._release_creation(record, None)
            if self.read(maximum_bytes=len(data)) != data:
                raise LifecycleError("WI-ATOMIC-BYTE-CHECK", f"byte check failed: {self.leaf}")
            self.verify()
        except BaseException as exc:
            primary = exc if isinstance(exc, LifecycleError) else self._failure("publication", exc)
            if record is not None:
                if record.raw_failure is None:
                    record.raw_failure = exc
                self._select_creation_primary(record, primary)
            if primary is exc:
                raise
            raise primary from exc
        finally:
            if record is not None:
                transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
                movement = transaction._active_relocation if transaction is not None else None
                held_progress = (isinstance(self._operation_owner, _PendingLegacyCompletionPlan)
                    and movement is not None and movement.progress_before is not None
                    and getattr(self, "_admitted_progress", (None,))[0] is self._operation_owner)
                if not held_progress:
                    self._finish_creation(record, primary, abort=primary is not None)

    def owned_image(self, leaf: str | None = None, *, maximum_bytes: int = 4 * 1024 * 1024) -> dict | None:
        """Acquire bytes and identity through the same native child owner."""
        self._verify_owned()
        leaf = self.leaf if leaf is None else leaf
        try:
            handle = self._file(leaf)
        except FileNotFoundError:
            return None
        except OSError as exc:
            raise self._failure("bounded owned image acquisition", exc) from exc
        primary = None
        try:
            identity = self._identity(handle)
            data = self._read_handle(handle, maximum_bytes)
            if self._identity(handle) != identity:
                raise self._failure("owned image", OSError("child identity changed"))
            observed = self._file(leaf)
            observed_primary = None
            try:
                if self._identity(observed) != identity or self._read_handle(observed, maximum_bytes) != data:
                    raise self._failure("owned image", OSError("child path or bytes changed during readback"))
            except BaseException as exc:
                observed_primary = exc
                raise
            finally:
                self._release_handle(observed, observed_primary)
            self._verify_owned()
            return {"identity": {"kind": "native-windows-file" if os.name == "nt" else "stat",
                                 "value": list(identity)}, "sha256": _sha256_bytes(data).upper(), "data": _b64(data)}
        except OSError as exc:
            primary = self._failure("bounded owned image acquisition", exc)
            raise primary from exc
        except BaseException as exc:
            primary = exc
            raise
        finally:
            self._release_handle(handle, primary)

    def stage_create(self, data: bytes) -> dict:
        """Flush a create-only stage and retain its actual read-back identity."""
        self._admit_write(data)
        self.verify()
        leaf = f".{self.leaf}.{uuid.uuid4().hex}.tmp"
        creation = self._prepare_effect(None, self.path.parent / leaf, data=data)
        record = self._new_creation(self.path.parent / leaf, creation, self._parent)
        primary = None
        try:
            handle = self._file(leaf, create=True, delete=True, _creation=record)
            record.identity = self._identity(handle)
            self._write_handle(handle, data)
            image = self.owned_image(leaf, maximum_bytes=len(data))
            if image is None or image["identity"]["value"] != list(record.identity) or _unb64(image["data"]) != data:
                raise LifecycleError("WI-ATOMIC-BYTE-CHECK", "create-only stage readback differs")
            self._publish_effect(creation, record.identity)
            record.creation_published = creation is not None
            record.phase = "retained"
            return {"stagePath": str(record.locator), **image}
        except BaseException as exc:
            primary = exc
            if record.raw_failure is None:
                record.raw_failure = exc
            self._select_creation_primary(record, primary)
            raise
        finally:
            self._finish_creation(record, primary, abort=primary is not None)

    def remove_owned(self, leaf: str, image: dict) -> None:
        """Delete only the exact native identity and bytes retained by this owner."""
        self._admit_mutation()
        self._verify_owned()
        removal = self._prepare_effect(self.path.parent / leaf, None)
        handle = self._file(leaf, delete=True)
        primary = None
        try:
            expected_kind = "native-windows-file" if os.name == "nt" else "stat"
            if (image["identity"]["kind"] != expected_kind
                or list(self._identity(handle)) != image["identity"]["value"]
                or self._read_handle(handle, 4 * 1024 * 1024) != _unb64(image["data"])):
                raise self._failure("owned removal", OSError("child ownership changed"))
            self._verify_owned()
            self._verify_effect_source(removal, handle)
            if os.name == "nt":
                self._windows_delete(handle)
            else:
                if _lifecycle_file_identity(os.stat(leaf, dir_fd=self._parent, follow_symlinks=False)) != self._identity(handle):
                    raise OSError("owned removal identity changed")
                os.unlink(leaf, dir_fd=self._parent)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            self._release_handle(handle, primary)
        self._publish_effect(removal, image["identity"]["value"])

    def promote_create(self, image: dict) -> None:
        """Promote an observed stage without replacing any destination."""
        self._admit_mutation()
        stage = Path(image["stagePath"])
        if stage.parent != self.path.parent:
            raise self._failure("create-only promotion", OSError("stage parent differs"))
        current = self.owned_image(stage.name)
        if current is None or current != {key: image[key] for key in ("identity", "sha256", "data")}:
            raise self._failure("create-only promotion", OSError("stage ownership changed"))
        handle = None
        primary = None
        try:
            handle = self._file(stage.name, delete=True)
            promotion = self._prepare_effect(stage, self.path, data=_unb64(image["data"]))
            if list(self._identity(handle)) != image["identity"]["value"]:
                raise OSError("stage identity changed")
            if self._read_handle(handle, 4 * 1024 * 1024) != _unb64(image["data"]):
                raise OSError("stage bytes changed before promotion")
            self.verify()
            self._verify_effect_source(promotion, handle)
            if os.name == "nt":
                self._windows_rename(handle, self.leaf, replace=False)
            else:
                os.link(stage.name, self.leaf, src_dir_fd=self._parent, dst_dir_fd=self._parent, follow_symlinks=False)
                if _lifecycle_file_identity(os.stat(stage.name, dir_fd=self._parent, follow_symlinks=False)) != self._identity(handle):
                    raise OSError("stage identity changed before unlink")
                os.unlink(stage.name, dir_fd=self._parent)
        except BaseException as exc:
            primary = exc
            raise
        finally:
            if handle is not None:
                self._release_handle(handle, primary)
        self._publish_effect(promotion, image["identity"]["value"])
        if self.owned_image() != current:
            raise LifecycleError("WI-ATOMIC-BYTE-CHECK", "create-only publication readback differs")

    def _identity(self, handle):
        if os.name != "nt":
            return _lifecycle_file_identity(os.fstat(handle))
        c, w, k, _nt, _types = self._native
        class Identity(c.Structure):
            _fields_ = [("volume", c.c_ulonglong), ("file", c.c_ubyte * 16)]
        value = Identity()
        if not k.GetFileInformationByHandleEx(handle, 18, c.byref(value), c.sizeof(value)):
            raise OSError(c.get_last_error(), "native file identity unavailable")
        return int(value.volume), int.from_bytes(value.file, "little")

    def _release_handle(self, handle, primary: BaseException | None = None) -> None:
        operation = self._operation_owner
        transaction = operation if isinstance(operation, LifecycleTransaction) else getattr(operation, "transaction", None)
        if not isinstance(transaction, LifecycleTransaction):
            transaction = None
        try:
            transaction = self._operation_transaction()
            self._close(handle)
        except BaseException as cause:
            movement = transaction._active_relocation if transaction is not None else None
            if movement is not None and self is movement.source_owner and handle == movement.handle:
                identity = _lifecycle_file_identity(movement.before[movement.source][0])
                transaction._unsettled_relocations += (UnsettledLifecycleRelocation(movement.source, movement.destination, identity),)
            composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
            if composer is not None:
                composer.record_write_cleanup(phase="write-target-release", failure_id="WI-LIFECYCLE-WRITE-BOUNDARY",
                    resource=self.leaf, diagnostic="owned write handle release failed", cause=cause)
            elif primary is not None:
                BaseException.add_note(primary, f"WI-LIFECYCLE-WRITE-BOUNDARY secondary write-target-release: {type(cause).__name__[:80]}")
            else:
                if isinstance(cause, LifecycleError) or not isinstance(cause, Exception):
                    raise
                raise self._failure("handle release", cause) from cause

    def _close(self, handle):
        transaction = self._assert_creation_settlement()
        movement = transaction._active_relocation if transaction is not None else None
        if movement is not None and handle == movement.handle and self is not movement.source_owner:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "borrowed relocation capability has no close authority")
        if os.name != "nt":
            os.close(handle)
        else:
            c, _w, k, _nt, _types = self._native
            if not k.CloseHandle(handle):
                raise OSError(c.get_last_error(), "native handle close failed")

    def _initialize_windows(self):
        import ctypes as c
        from ctypes import wintypes as w
        class Unicode(c.Structure):
            _fields_ = [("Length", w.USHORT), ("MaximumLength", w.USHORT), ("Buffer", c.c_void_p)]
        class Attributes(c.Structure):
            _fields_ = [("Length", w.ULONG), ("RootDirectory", w.HANDLE), ("ObjectName", c.POINTER(Unicode)),
                        ("Attributes", w.ULONG), ("SecurityDescriptor", c.c_void_p), ("SecurityQualityOfService", c.c_void_p)]
        class Status(c.Structure):
            _fields_ = [("Status", c.c_void_p), ("Information", c.c_size_t)]
        k = c.WinDLL("kernel32", use_last_error=True); nt = c.WinDLL("ntdll")
        k.CreateFileW.argtypes = [w.LPCWSTR, w.DWORD, w.DWORD, c.c_void_p, w.DWORD, w.DWORD, w.HANDLE]; k.CreateFileW.restype = w.HANDLE
        k.CloseHandle.argtypes = [w.HANDLE]; k.CloseHandle.restype = w.BOOL
        k.SetHandleInformation.argtypes = [w.HANDLE, w.DWORD, w.DWORD]; k.SetHandleInformation.restype = w.BOOL
        k.GetFileInformationByHandleEx.argtypes = [w.HANDLE, c.c_int, c.c_void_p, w.DWORD]; k.GetFileInformationByHandleEx.restype = w.BOOL
        k.SetFilePointerEx.argtypes = [w.HANDLE, c.c_longlong, c.POINTER(c.c_longlong), w.DWORD]; k.SetFilePointerEx.restype = w.BOOL
        k.ReadFile.argtypes = [w.HANDLE, c.c_void_p, w.DWORD, c.POINTER(w.DWORD), c.c_void_p]; k.ReadFile.restype = w.BOOL
        k.WriteFile.argtypes = k.ReadFile.argtypes; k.WriteFile.restype = w.BOOL
        k.FlushFileBuffers.argtypes = [w.HANDLE]; k.FlushFileBuffers.restype = w.BOOL
        nt.NtCreateFile.argtypes = [c.POINTER(w.HANDLE), w.ULONG, c.POINTER(Attributes), c.POINTER(Status), c.c_void_p,
                                  w.ULONG, w.ULONG, w.ULONG, w.ULONG, c.c_void_p, w.ULONG]; nt.NtCreateFile.restype = w.LONG
        nt.NtSetInformationFile.argtypes = [w.HANDLE, c.POINTER(Status), c.c_void_p, w.ULONG, c.c_int]; nt.NtSetInformationFile.restype = w.LONG
        nt.RtlNtStatusToDosError.argtypes = [w.LONG]; nt.RtlNtStatusToDosError.restype = w.ULONG
        self._native = c, w, k, nt, (Unicode, Attributes, Status)

    def _windows_status(self, status, stage):
        if status < 0:
            c, _w, _k, nt, _types = self._native
            code = nt.RtlNtStatusToDosError(status)
            if code in {2, 3}:
                raise FileNotFoundError(code, stage)
            raise OSError(code, f"{stage} NTSTATUS=0x{status & 0xffffffff:08x}")

    def _windows_check(self, handle, *, directory):
        c, w, k, _nt, _types = self._native
        class Tag(c.Structure):
            _fields_ = [("Attributes", w.DWORD), ("Tag", w.DWORD)]
        value = Tag()
        if not k.GetFileInformationByHandleEx(handle, 9, c.byref(value), c.sizeof(value)):
            raise OSError(c.get_last_error(), "native child attributes unavailable")
        if value.Attributes & 0x400 or bool(value.Attributes & 0x10) != directory:
            raise OSError("child is not the admitted ordinary kind")
        if not k.SetHandleInformation(handle, 1, 0):
            raise OSError(c.get_last_error(), "cannot make native handle non-inheritable")

    def _windows_root(self, anchor):
        c, w, k, _nt, _types = self._native
        handle = k.CreateFileW(anchor, 0x1000a0, 3, None, 3, 0x02200000, None)
        if handle == w.HANDLE(-1).value:
            raise OSError(c.get_last_error(), "native volume directory open failed")
        try:
            self._windows_check(handle, directory=True)
            return handle
        except BaseException as primary:
            self._release_handle(handle, primary); raise

    def _windows_child(self, parent, leaf, *, directory=False, create=False, exclusive=False, delete=False, write=False, _creation=None):
        self._check_leaf(leaf)
        if (create or exclusive) and _creation is None:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "native creator custody must precede acquisition")
        if _creation is not None and (type(_creation) is not _OwnedNativeCreation or _creation.seal is not _NATIVE_CREATION_OWNER
                or not create or _creation.owner is not self
                or _creation.parent != parent or _creation.locator.name != leaf):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "creation custody differs from native request")
        c, w, _k, nt, types = self._native; Unicode, Attributes, Status = types
        text = c.create_unicode_buffer(leaf); length = len(leaf.encode("utf-16-le"))
        if length > 65532:
            raise OSError("native child name exceeds Unicode descriptor")
        name = Unicode(length, length + 2, c.cast(text, c.c_void_p))
        attributes = Attributes(c.sizeof(Attributes), parent, c.pointer(name), 0x40, None, None)
        output = w.HANDLE(); status = Status()
        access = (0x1000a0 | (0x10000 if delete else 0)) if directory else 0x100081 | (2 if write else 0) | (0x10000 if delete else 0)
        disposition = 2 if exclusive else 3 if create else 1
        options = 0x200020 | (1 if directory else 0x40)
        result = nt.NtCreateFile(c.byref(output), access, c.byref(attributes), c.byref(status), None, 0x80,
                                 3 if directory or create else 7, disposition, options, None, 0)
        try:
            self._windows_status(result, "relative child open")
            if _creation is not None:
                _creation.handle, _creation.acquired = output.value, True
                # Windows SDK winternl.h: FILE_CREATED=2; FILE_OPENED never grants disposal.
                _creation.native_result = int(status.Information)
                _creation.creator = _creation.native_result == 2
                _creation.holder, _creation.phase = "inner", "acquired" if _creation.creator else "opened"
            if _creation is not None and not _creation.creator:
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "native request did not create the admitted object")
            self._windows_check(output.value, directory=directory)
            if _creation is not None:
                _creation.holder = "outer"
            return output.value
        except BaseException as primary:
            if result < 0:
                raise
            if _creation is not None:
                _creation.raw_failure = primary
                self._finish_creation(_creation, primary, abort=True)
                raise
            cleanup = None
            if exclusive and delete:
                try:
                    self._windows_delete(output.value)
                except BaseException as cause:
                    cleanup = cause
            try:
                self._close(output.value)
            except BaseException as cause:
                cleanup = cause if cleanup is None else OSError(f"{cleanup}; {cause}")
            if cleanup is not None:
                composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
                if composer is not None:
                    composer.record_write_cleanup(phase="write-child-acquisition", failure_id="WI-LIFECYCLE-WRITE-BOUNDARY",
                                            resource=leaf, diagnostic="owned child acquisition cleanup failed", cause=cleanup)
                else:
                    BaseException.add_note(primary, f"WI-LIFECYCLE-WRITE-BOUNDARY secondary write-child-acquisition: {type(cleanup).__name__[:80]}")
            raise

    def _windows_read(self, handle, maximum_bytes):
        c, w, k, _nt, _types = self._native
        chunks = []; total = 0
        while True:
            buffer = c.create_string_buffer(min(65536, maximum_bytes + 1 - total)); count = w.DWORD()
            if not k.ReadFile(handle, buffer, len(buffer), c.byref(count), None):
                raise OSError(c.get_last_error(), "native child read failed")
            if not count.value:
                break
            chunks.append(buffer.raw[:count.value]); total += count.value
            if total > maximum_bytes:
                raise OSError("native child exceeds admitted byte envelope")
        return b"".join(chunks)

    def _write_handle(self, handle, data):
        if os.name != "nt":
            offset = 0
            while offset < len(data):
                count = os.write(handle, data[offset:]);
                if not count:
                    raise OSError("write made no progress")
                offset += count
            os.fsync(handle)
            return
        c, w, k, _nt, _types = self._native; offset = 0
        while offset < len(data):
            part = data[offset:offset + 65536]; buffer = c.create_string_buffer(part); count = w.DWORD()
            if not k.WriteFile(handle, buffer, len(part), c.byref(count), None) or not count.value:
                raise OSError(c.get_last_error(), "native child write failed")
            offset += count.value
        if not k.FlushFileBuffers(handle):
            raise OSError(c.get_last_error(), "native child flush failed")

    def _windows_rename(self, handle, leaf, *, replace):
        transaction = self._assert_creation_settlement()
        self._check_leaf(leaf)
        movement = transaction._active_relocation if transaction is not None else None
        if movement is not None and handle == movement.handle:
            if self is not movement.source_owner and self is not movement.target_owner:
                raise LifecycleError("WI-LIFECYCLE-EFFECT", "borrowed relocation capability has no rename authority")
            expected = _lifecycle_file_identity(movement.before[movement.source][0])
            current = [path for path in (movement.source, movement.destination)
                       if os.path.lexists(path) and _lifecycle_file_identity(path.lstat()) == expected]
            if len(current) != 1 or self._identity(handle) != expected:
                raise LifecycleError("WI-LIFECYCLE-RELOCATION", "native relocation locator or capability differs")
            self._verify_owned()
            if not movement.directory:
                snapshot = movement.before[movement.source][1]
                if self._read_handle(handle, snapshot.length) != snapshot.data:
                    raise LifecycleError("WI-LIFECYCLE-RELOCATION", "native relocation bytes differ")
        c, w, _k, nt, types = self._native; Status = types[2]
        class Rename(c.Structure):
            _fields_ = [("ReplaceIfExists", c.c_ubyte), ("RootDirectory", w.HANDLE),
                        ("FileNameLength", w.ULONG), ("FileName", w.WCHAR * 1)]
        name = leaf.encode("utf-16-le"); buffer = c.create_string_buffer(max(c.sizeof(Rename), Rename.FileName.offset + len(name)))
        value = Rename.from_buffer(buffer); value.ReplaceIfExists = bool(replace)
        value.RootDirectory = self._parent; value.FileNameLength = len(name)
        c.memmove(c.addressof(buffer) + Rename.FileName.offset, name, len(name)); status = Status()
        self._windows_status(nt.NtSetInformationFile(handle, c.byref(status), buffer, len(buffer), 10), "relative child rename")

    def _windows_delete(self, handle):
        transaction = self._assert_creation_settlement()
        movement = transaction._active_relocation if transaction is not None else None
        if movement is not None and handle == movement.handle:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "relocation acquisition has no creator disposition authority")
        c, _w, _k, nt, types = self._native; value = c.c_ubyte(1); status = types[2]()
        self._windows_status(nt.NtSetInformationFile(handle, c.byref(status), c.byref(value), 1, 13), "owned temporary disposition")


def _admit_lifecycle_write_target(path: Path, *, failure_id: str, _operation_owner=None, inverse=None) -> LifecycleWriteTarget:
    return LifecycleWriteTarget(path, failure_id=failure_id, _operation_owner=_operation_owner, inverse=inverse)


def _atomic_write(path: Path, data: bytes, *, target: LifecycleWriteTarget | None = None, inverse=None) -> None:
    if inverse is not None:
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if not isinstance(transaction, LifecycleTransaction):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "inverse write requires its held transaction")
        transaction._admit_inverse_mutation(inverse)
        if (inverse.directory or inverse.destination != _lifecycle_unresolved_absolute(path)
                or inverse.data is None or not isinstance(data, bytes) or data != inverse.data
                or (target is not None and target._inverse is not inverse)):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "write arguments differ from admitted inverse meaning")
    if target is None:
        with _admit_lifecycle_write_target(path, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY", inverse=inverse) as acquired:
            acquired.publish(data)
    else:
        if type(target) is not LifecycleWriteTarget or target.path != _lifecycle_unresolved_absolute(path) or not target._open:
            raise LifecycleError("WI-LIFECYCLE-WRITE-BOUNDARY", "supplied write target does not bind destination")
        target.publish(data)


def _canonical_category(reference: str) -> tuple[Category, str]:
    if reference.count(":") != 1:
        raise LifecycleError(
            "WI-REFERENCE-INVALID",
            f"reference must be category-qualified as <category>:<bare-slug>: {reference!r}",
        )
    category_name, slug = reference.split(":", 1)
    category_name = CATEGORY_ALIASES.get(category_name, category_name)
    category = CATEGORIES.get(category_name)
    if category is None:
        raise LifecycleError("WI-REFERENCE-INVALID", f"unknown category: {category_name!r}")
    _validate_slug(slug)
    return category, slug


def _archive_entity_rows_at(work_items: Path) -> tuple:
    archive = work_items / "archive"
    evidence = []
    if _observe_project_path_at(archive, "directory", evidence, "WI-ARCHIVE-ENTITY-UNBOUND") is None:
        return (), (), archive, tuple(evidence)
    owned_inputs = {
        "status.md", "closure.md", LEGACY_RETIREMENT_FILE,
        BUG_DISPOSITIONS_MANIFEST, BUG_DISPOSITIONS_RECEIPT,
        LEGACY_COMPLETION_METADATA, "legacy-source",
    }
    directories = []
    rows = []

    def children(path: Path, *, lexical_only: bool = False) -> tuple[Path, ...]:
        chain = _capture_path_parent_chain(path / ".inventory-observation", "WI-ARCHIVE-ENTITY-UNBOUND")
        try:
            result = tuple(sorted(path.iterdir(), key=lambda child: child.name))
            for child in (() if lexical_only else result):
                info = child.lstat()
                if stat.S_ISLNK(info.st_mode) or bool(getattr(info, "st_file_attributes", 0)
                        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)):
                    raise OSError("archive contains a linked entry")
                if not (stat.S_ISDIR(info.st_mode) or stat.S_ISREG(info.st_mode)):
                    raise OSError("archive contains an unsupported entry")
        except OSError as exc:
            raise LifecycleError("WI-ARCHIVE-ENTITY-UNBOUND", f"archive acquisition unavailable: {path}") from exc
        directories.append((path, chain, tuple(child.name for child in result)))
        evidence.extend((("chain", chain), ("membership", (path, tuple(child.name for child in result)))))
        return result

    for container in children(archive):
        if not container.is_dir():
            evidence.append(("node", _capture_structural_node(container, "WI-ARCHIVE-ENTITY-UNBOUND")))
            rows.append((container, "archive-metadata", None, (container,)))
            continue
        try:
            month = datetime.strptime(container.name, "%Y-%m")
        except ValueError:
            canonical_month = False
        else:
            canonical_month = month.strftime("%Y-%m") == container.name
        for item in children(container):
            if not item.is_dir():
                if canonical_month:
                    evidence.append(("node", _capture_structural_node(item, "WI-ARCHIVE-ENTITY-UNBOUND")))
                    rows.append((item, "archive-metadata", None, (item,)))
                continue
            leaves = children(item, lexical_only=not canonical_month)
            owned = owned_inputs.intersection(path.name for path in leaves)
            if _legacy_completion_recognized(item):
                owned.add(LEGACY_COMPLETION_METADATA)
            if not canonical_month and not owned:
                continue
            if owned or not leaves and canonical_month:
                kind = "work-item" if {"closure.md", LEGACY_RETIREMENT_FILE}.intersection(owned) else "invalid-work-item"
                rows.append((item, kind, f"work-item:{item.name}", ()))
            elif leaves:
                if any(not path.is_file() for path in leaves):
                    raise LifecycleError("WI-ARCHIVE-ENTITY-UNBOUND", f"unsupported mixed archive collection: {item}")
                for path in leaves:
                    evidence.append(("node", _capture_structural_node(path, "WI-ARCHIVE-ENTITY-UNBOUND")))
                rows.append((item, "unbound-flat-container", None, leaves))
    _verify_project_binding_evidence(tuple(evidence), "WI-ARCHIVE-ENTITY-UNBOUND")
    return tuple(rows), tuple(directories), None, tuple(evidence)


def _archive_entity_inventory_at(work_items: Path) -> ArchiveEntityInventory:
    rows, directories, absent, evidence = _archive_entity_rows_at(work_items)
    entities = tuple(ArchiveEntity(path, kind, reference,
        tuple(_capture_file_snapshot(leaf, failure_id="WI-ARCHIVE-ENTITY-UNBOUND", maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP)
              for leaf in leaves)) for path, kind, reference, leaves in rows)
    inventory = ArchiveEntityInventory(entities, True,
        not any(kind == "unbound-flat-container" for _path, kind, _reference, _leaves in rows), directories, absent)
    _verify_project_binding_evidence(evidence, "WI-ARCHIVE-ENTITY-UNBOUND")
    inventory.verify()
    return inventory


def _archive_entity_inventory(root: Path) -> ArchiveEntityInventory:
    return _archive_entity_inventory_at(_work_items_root(root))


def archive_entity_inventory(root: Path, *, input_role: str = "caller-root") -> ArchiveEntityInventory:
    """Acquire the physical archive model without a writer transaction."""
    _repository, work_items = _resolve_project_root_identity(
        root, input_role=input_role, failure_id=ROOT_CONTRACT_FAILURE,
    )
    _read_project_topology_at(work_items)
    return _archive_entity_inventory_at(work_items)


def _archived_work_item_candidates(
    archive: Path, *, slug: str | None = None, reverse: bool = False,
) -> tuple[Path, ...]:
    inventory = archive_entity_inventory(archive.parent.parent, input_role="repository-root")
    return tuple(sorted((path for path in inventory.logical_work_item_paths
                         if slug is None or path.name == slug), reverse=reverse))


def _archive_row_matches_unbound(row: tuple, *, slug: str | None = None, path: Path | None = None) -> bool:
    container, kind, _reference, leaves = row
    if kind != "unbound-flat-container":
        return False
    return (slug is not None and (container.name == slug or any(p.stem == slug for p in leaves))) or (path is not None and path in (container, *leaves))


def _inventory_archive_rows(inventory: ArchiveEntityInventory) -> tuple:
    return tuple((entity.path, entity.kind, entity.logical_reference,
                  tuple(snapshot.path for snapshot in entity.snapshots)) for entity in inventory.entities)


def _reject_unbound_archive_selection(inventory: ArchiveEntityInventory, *, slug: str | None = None, path: Path | None = None) -> None:
    for row in _inventory_archive_rows(inventory):
        if _archive_row_matches_unbound(row, slug=slug, path=path):
            raise LifecycleError("WI-ARCHIVE-ENTITY-UNBOUND", f"selected identity has unresolved archive data: {row[0]}")


def _category_locations_at(work_items: Path, category: Category, slug: str, *,
    archive_inventory: ArchiveEntityInventory | None = None, archive_rows: tuple | None = None,
    binding_evidence: list | None = None) -> list[Path]:
    if archive_inventory is not None and archive_rows is not None:
        raise TypeError("archive inventory and structural rows are mutually exclusive")
    locations = []
    evidence = [] if binding_evidence is None else binding_evidence
    failure_id = "WI-ARCHIVE-ENTITY-UNBOUND"
    if category.current_kind == "work-item":
        if archive_rows is None:
            inventory = archive_inventory if archive_inventory is not None else _archive_entity_inventory_at(work_items)
            archive_rows = _inventory_archive_rows(inventory)
            if binding_evidence is not None:
                evidence.append(("archive", inventory))
        for row in archive_rows:
            if _archive_row_matches_unbound(row, slug=slug):
                raise LifecycleError(failure_id, f"selected identity has unresolved archive data: {row[0]}")
        for candidate, kind in ((work_items / "backlog" / f"{slug}.md", "file"), (work_items / "active" / slug, "directory")):
            if _observe_project_path_at(candidate, kind, evidence, failure_id) is not None:
                locations.append(candidate)
        for path, _kind, reference, _leaves in archive_rows:
            if reference == f"work-item:{slug}":
                _observe_project_path_at(path, "directory", evidence, failure_id)
                if _legacy_completion_recognized(path):
                    _require_legacy_terminal(work_items.parent, path)
                locations.append(path)
    else:
        current = work_items / category.current_root / f"{slug}.md"
        if _observe_project_path_at(current, "file", evidence, failure_id) is not None:
            locations.append(current)
        archive = work_items / category.current_root / "archive"
        for month in _project_identity_children_at(archive, evidence, failure_id):
            _lifecycle_reject_unreduced_reparse(month, failure_id=failure_id, message="selected category archive is unsafe")
            if month.is_dir():
                candidate = month / f"{slug}.md"
                if _observe_project_path_at(candidate, "file", evidence, failure_id) is not None:
                    locations.append(candidate)
    if binding_evidence is not None:
        _verify_project_binding_evidence(tuple(evidence), failure_id)
    return locations


def _category_locations(root: Path, category: Category, slug: str) -> list[Path]:
    return _category_locations_at(_work_items_root(root), category, slug)


@functools.partial(_lifecycle_participant, subject_parameters=('category-reference', 'reference'))
def resolve_category(root: Path, reference: str, *, _prepared_category=None) -> Path:
    return _resolve_category_read_model(root, reference, prepared_category=_prepared_category)


def _resolve_category_read_model(root: Path, reference: str, *, prepared_category=None) -> Path:
    category, slug = _canonical_category(reference) if prepared_category is None else prepared_category
    locations = _category_locations(root, category, slug)
    if len(locations) > 1:
        raise LifecycleError(
            "WI-CATEGORY-DUAL-LOCATION",
            f"{reference} has {len(locations)} physical locations",
        )
    if not locations:
        raise LifecycleError("WI-REFERENCE-MISSING", f"no physical location for {reference}")
    return locations[0].resolve()


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def work_item_dependency_state(root: Path, slug: str) -> str:
    """Resolve one dependency through the lifecycle owner.

    Physical location owns the state: backlog and active records are open,
    while only a dated archive record is done. Missing and duplicate identities
    retain ``resolve_category``'s stable fail-closed errors.
    """
    location = resolve_category(root, f"work-item:{slug}")
    archive = (_work_items_root(root) / "archive").resolve()
    return "done" if archive in location.parents else "open"


def resolve_legacy_path(root: Path, legacy_path: str) -> Path:
    candidate = Path(legacy_path)
    if candidate.is_absolute():
        raise LifecycleError("WI-REFERENCE-INVALID", "legacy path must be relative")
    repo_root = _work_items_root(root).parent.resolve()
    resolved = _lifecycle_unresolved_absolute(repo_root / candidate)
    if resolved != repo_root and repo_root not in resolved.parents:
        raise LifecycleError("WI-REFERENCE-INVALID", "legacy path escapes repository")
    inventory = _archive_entity_inventory(root)
    for item in inventory.logical_work_item_paths:
        if resolved.is_relative_to(item) and _legacy_completion_recognized(item):
            _require_legacy_terminal(repo_root, item)
    if not resolved.exists():
        selected = []
        for item in inventory.logical_work_item_paths:
            if not _legacy_completion_recognized(item):
                continue
            if candidate.parts[:2] == ("work-items", "backlog") and candidate.stem == item.name:
                observation = _require_legacy_terminal(repo_root, item)
            else:
                metadata = _capture_file_snapshot(item / LEGACY_COMPLETION_METADATA, failure_id="WI-LEGACY-COMPLETION-CUSTODY")
                payload = json.loads(metadata.data)
                if not any(row.get("originalPath") == candidate.as_posix() for row in payload["custodyMap"]):
                    continue
                observation = _require_legacy_terminal(repo_root, item)
            port = observation.acquired_input
            if resolved in port.files:
                selected.append(port.current_snapshot(resolved).path)
        if len(selected) == 1:
            return selected[0]
        if len(selected) > 1:
            raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "original reference has multiple exact retained owners")
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            f"legacy path is absent and has no incoming-link inventory: {legacy_path}",
        )
    _reject_unbound_archive_selection(inventory, path=resolved)
    return resolved


def _relative_link(work_items: Path, path: Path) -> str:
    return Path(os.path.relpath(path, work_items)).as_posix()


def _current_readme_status_error(fields: dict[str, str], location: str, source: Path) -> LifecycleError | None:
    status = fields.get("status", "")
    if location == "backlog":
        if not status or status == "candidate":
            return None
        failure = (
            "WI-CATEGORY-TERMINAL-IN-CURRENT"
            if status in CATEGORIES["work-item"].terminal_statuses
            else "WI-CATEGORY-STATUS-INVALID"
        )
        return LifecycleError(failure, f"backlog work-item has invalid current status {status!r}: {source.stem}")
    if location == "active":
        if status in CATEGORIES["work-item"].terminal_statuses:
            return LifecycleError("WI-CATEGORY-TERMINAL-IN-CURRENT", f"terminal work-item remains active: {source.parent.name}")
        if status not in CATEGORIES["work-item"].current_statuses - {"candidate"}:
            return LifecycleError("WI-CATEGORY-STATUS-INVALID", f"active work-item has invalid status {status!r}: {source.parent}")
        return None
    if location == "roadmap":
        if fields.get("format") != "roadmap-v1" or status in CATEGORIES["roadmap"].current_statuses:
            return None
        return LifecycleError("WI-CATEGORY-TERMINAL-IN-CURRENT", f"terminal V1 roadmap remains current: {source.stem}")
    raise ValueError(f"unsupported current read-model location: {location}")


def _project_current_readme_status(
    entry: ReadmeEntry, fields: dict[str, str], data: bytes, location: str,
    *, diagnostic: bool,
) -> ReadmeEntry:
    failure = _current_readme_status_error(fields, location, entry.link)
    if failure is not None:
        if not diagnostic:
            raise failure
        entry.section = "Blockers"
        entry.checked = False
        entry.classification = (
            f"{failure.failure_id}: status={json.dumps(fields.get('status'), ensure_ascii=False)}"
            f"; source sha256:{_sha256_bytes(data)}"
        )
    return entry


def _status_entry(root: Path, item: Path, *, diagnostic_status: bool = False) -> ReadmeEntry:
    status_path = item / "status.md"
    if not status_path.is_file():
        raise LifecycleError("WI-CATEGORY-STATUS-MISSING", f"missing status.md: {item}")
    data = _capture_file_snapshot(
        status_path,
        failure_id="WI-README-STALE",
        maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
    ).data
    fields = _parse_fields(data.decode("utf-8"))
    status = fields.get("status", "")
    section = "Blockers" if status == "blocked" or fields.get("blocker") else "Current focus"
    label = fields.get("task") or item.name
    detail = fields.get("blocker", "") if section == "Blockers" else fields.get("current step", "")
    entry = ReadmeEntry(
        section,
        f"work-item:{item.name}",
        label,
        status_path,
        False,
        detail,
        [status_path],
    )
    _project_current_readme_status(entry, fields, data, "active", diagnostic=diagnostic_status)
    progressive: list[str] = []
    for field_name, category in (("roadmap", "roadmap"), ("epic", "epic")):
        related_values = _optional_relation_values(
            fields.get(field_name),
            comma_separated=False,
        )
        if not related_values:
            continue
        related_slug = related_values[0]
        _validate_slug(related_slug)
        related = _resolve_category_read_model(root, f"{category}:{related_slug}")
        entry.source_paths.append(related)
        progressive.append(
            f"[{field_name}]({_relative_link(_work_items_root(root), related)})"
        )
    progressive.append(f"[work item]({_relative_link(_work_items_root(root), status_path)})")
    suffix = " → ".join(progressive)
    entry.detail = " — ".join(part for part in (entry.detail, suffix) if part)
    return entry


def _legacy_retirement_entry(item: Path, metadata: Path,
    *,
    acquired_input=None,
) -> ReadmeEntry:
    try:
        payload = json.loads(_input_text(metadata, acquired_input, encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID",
            f"invalid legacy retirement metadata: {metadata}",
        ) from exc
    expected_scalars = {
        "schemaVersion": LEGACY_RETIREMENT_SCHEMA_VERSION,
        "owner": LEGACY_RETIREMENT_OWNER,
        "kind": "legacy-backlog-retirement",
        "slug": item.name,
        "status": "rejected-before-admission",
        "admissionHistory": "never-admitted",
    }
    if not isinstance(payload, dict) or any(
        payload.get(key) != value for key, value in expected_scalars.items()
    ):
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID",
            f"legacy retirement identity differs: {item}",
        )
    terminal_at = payload.get("terminalAt")
    if not isinstance(terminal_at, str):
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID", f"missing terminalAt: {metadata}"
        )
    _strict_utc(terminal_at)
    if archive_month(terminal_at) != item.parent.name:
        raise LifecycleError(
            "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH",
            f"{item.name} belongs in archive/{archive_month(terminal_at)}",
        )
    disposition = payload.get("productDisposition")
    if not isinstance(disposition, str) or not disposition.strip():
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID",
            f"missing product disposition: {metadata}",
        )
    if payload.get("syntheticTransitions") != []:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID",
            f"legacy retirement must not synthesize lifecycle transitions: {metadata}",
        )
    incoming = payload.get("incomingLinks")
    try:
        _validate_incoming_link_snapshot(f"work-item:{item.name}", incoming, label="stored")
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID",
            f"invalid incoming-link inventory: {metadata}",
        ) from exc
    rows = payload.get("sourceFiles")
    if not isinstance(rows, list) or not rows:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID", f"missing source file inventory: {metadata}"
        )
    sources: list[Path] = [metadata]
    seen: set[str] = set()
    for row in rows:
        if not isinstance(row, dict):
            raise LifecycleError(
                "WI-LEGACY-RETIREMENT-INVALID", f"invalid source row: {metadata}"
            )
        relative = row.get("path")
        if not isinstance(relative, str) or relative in seen:
            raise LifecycleError(
                "WI-LEGACY-RETIREMENT-INVALID", f"duplicate source path: {metadata}"
            )
        candidate = Path(relative)
        if candidate.is_absolute() or ".." in candidate.parts or relative == LEGACY_RETIREMENT_FILE:
            raise LifecycleError(
                "WI-LEGACY-RETIREMENT-INVALID", f"unsafe source path: {relative!r}"
            )
        source = item / candidate
        if (source.is_symlink() if acquired_input is None else _input_exists(source, acquired_input)
                and stat.S_ISLNK(_input_metadata(source, acquired_input).st_mode)) or not _input_is_file(source, acquired_input):
            raise LifecycleError(
                "WI-LEGACY-RETIREMENT-INVALID", f"missing source payload: {relative}"
            )
        data = _input_bytes(source, acquired_input)
        if (
            row.get("byteLength") != len(data)
            or row.get("sha256") != hashlib.sha256(data).hexdigest()
        ):
            raise LifecycleError(
                "WI-LEGACY-RETIREMENT-INVALID", f"source digest differs: {relative}"
            )
        seen.add(relative)
        sources.append(source)
    actual = {
        path.relative_to(item).as_posix()
        for path in _input_descendants(item, acquired_input)
        if _input_is_file(path, acquired_input) and path != metadata
    }
    if actual != seen:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID",
            f"source inventory does not cover the retirement payload: {item}",
        )
    # Retirement is immutable, but its former backlog paths must not remain in
    # mutable records.  The stored inventory is evidence from the transition;
    # this fresh owner-level scan catches a later plain-text citation that the
    # original Markdown/link scanner could not see.  Archived consumers are
    # historical evidence and intentionally do not participate.
    work_items = item.parents[2]
    current_incoming = _incoming_link_result(
        work_items.parent,
        sources,
        f"work-item:{item.name}",
        literal_path_references=(
            f"{work_items.name}/backlog/{item.name}/{relative}"
            for relative in seen
        ),
        mutable_consumers_only=True,
        scan_markdown_links=False,
        acquired_input=acquired_input,
    )
    try:
        _validate_incoming_link_snapshot(
            f"work-item:{item.name}", current_incoming, label="current"
        )
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID",
            f"mutable record retains a retired backlog path: {item}",
        ) from exc
    return ReadmeEntry(
        "Recently completed",
        f"work-item:{item.name}",
        f"Rejected before admission: {item.name}",
        metadata,
        True,
        disposition.strip().splitlines()[0],
        sources,
        "WI-LEGACY-RETIRED-BEFORE-ADMISSION",
    )


def _archived_work_item_entry(item: Path,
    *,
    acquired_input=None,
) -> ReadmeEntry:
    if acquired_input is None and _legacy_completion_recognized(item):
        observation = _require_legacy_terminal(item.parent.parent.parent.parent, item)
        port = observation.acquired_input
        closure_data = next(snapshot.data for snapshot in port._current_files if snapshot.path == item / "closure.md")
        return _legacy_terminal_entry(item, port.metadata, closure_data)
    retirement = item / LEGACY_RETIREMENT_FILE
    if _input_is_file(retirement, acquired_input):
        if (_input_exists(item / "status.md", acquired_input) if acquired_input is not None else (item / "status.md").exists()) or (_input_exists(item / "closure.md", acquired_input) if acquired_input is not None else (item / "closure.md").exists()):
            raise LifecycleError(
                "WI-LEGACY-RETIREMENT-INVALID",
                f"direct legacy retirement must not carry active/closure history: {item}",
            )
        return _legacy_retirement_entry(item, retirement, acquired_input=acquired_input)
    closure = item / "closure.md"
    if not _input_is_file(closure, acquired_input):
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            f"archived work-item lacks closure.md: {item}",
        )
    status = item / "status.md"
    closure_data = _capture_file_snapshot(
        closure,
        failure_id="WI-README-STALE",
        maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
     acquired_input=acquired_input).data
    status_data = _capture_file_snapshot(
        status,
        failure_id="WI-README-STALE",
        maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
     acquired_input=acquired_input).data if _input_is_file(status, acquired_input) else b""
    closure_markers = _schema_marker_occurrences(closure_data, "closure.md")
    status_markers = _schema_marker_occurrences(status_data, "status.md")
    fields = _parse_fields(closure_data.decode("utf-8"))
    sources = [closure]
    if _input_is_file(status, acquired_input):
        sources.append(status)

    if not closure_markers and not status_markers:
        return ReadmeEntry(
            "Recently completed",
            f"work-item:{item.name}",
            fields.get("outcome") or item.name,
            closure,
            True,
            fields.get("residual risk", ""),
            sources,
            LEGACY_READ_CLASSIFICATION,
        )

    _require_canonical_schema_marker(status_markers, "status.md")
    _require_canonical_schema_marker(closure_markers, "closure.md")
    closed = fields.get("closed", "")
    _validate_closure(closure_data, closed)
    expected_month = archive_month(closed)
    if expected_month != item.parent.name:
        raise LifecycleError(
            "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH",
            f"{item.name} belongs in archive/{expected_month}, not {item.parent.name}",
        )
    status_fields = _parse_fields(status_data.decode("utf-8"))
    status_value = status_fields.get("status", "")
    if status_value in CATEGORIES["work-item"].current_statuses:
        raise LifecycleError(
            "WI-CATEGORY-CURRENT-IN-ARCHIVE",
            f"work-item:{item.name} has current status in archive",
        )
    if status_value not in CATEGORIES["work-item"].terminal_statuses:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID",
            f"work-item:{item.name} has invalid archived V1 status {status_value!r}",
        )
    return ReadmeEntry(
        "Recently completed",
        f"work-item:{item.name}",
        fields.get("outcome") or item.name,
        closure,
        True,
        fields.get("residual risk", ""),
        sources,
    )


def collect_readme_entries(root: Path) -> list[ReadmeEntry]:
    return _collect_readme_entries(root)


def _collect_readme_entries(root: Path, *, archive_inventory: ArchiveEntityInventory | None = None,
                            prepared_terminal=None) -> list[ReadmeEntry]:
    work_items = _work_items_root(root)
    inventory = archive_inventory if archive_inventory is not None else _archive_entity_inventory(root)
    entries: list[ReadmeEntry] = []

    backlog = work_items / "backlog"
    if backlog.is_dir():
        for path in sorted(backlog.glob("*.md")):
            if prepared_terminal is not None and path == prepared_terminal.source:
                continue
            data = _capture_file_snapshot(
                path,
                failure_id="WI-README-STALE",
                maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
            ).data
            fields = _parse_fields(data.decode("utf-8"))
            entries.append(
                _project_current_readme_status(ReadmeEntry(
                    "Next actions",
                    f"work-item:{path.stem}",
                    fields.get("task") or path.stem,
                    path,
                    False,
                    fields.get("next action", ""),
                    [path],
                ), fields, data, "backlog", diagnostic=True)
            )

    active = work_items / "active"
    if active.is_dir():
        for item in sorted(path for path in active.iterdir() if path.is_dir()):
            entries.append(_status_entry(root, item, diagnostic_status=True))

    roadmaps = work_items / "roadmaps"
    if roadmaps.is_dir():
        for path in sorted(roadmaps.glob("*.md")):
            data = _capture_file_snapshot(
                path,
                failure_id="WI-README-STALE",
                maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
            ).data
            fields = _parse_fields(data.decode("utf-8"))
            if fields.get("format") != "roadmap-v1":
                continue
            entries.append(
                _project_current_readme_status(ReadmeEntry(
                    "Roadmap and milestones",
                    f"roadmap:{path.stem}",
                    fields.get("milestones-or-horizon") or path.stem,
                    path,
                    False,
                    fields.get("order", ""),
                    [path],
                ), fields, data, "roadmap", diagnostic=True)
            )

    for entity in inventory.entities:
        if prepared_terminal is not None and entity.path == prepared_terminal.archive:
            continue
        if entity.kind in {"work-item", "invalid-work-item"}:
            entries.append(_archived_work_item_entry(entity.path))
        elif entity.kind == "archive-metadata":
            relative = _relative_link(work_items, entity.path)
            entries.append(ReadmeEntry("Archive metadata", f"archive-observation:{relative}", relative,
                entity.path, False, "Non-authorizing archive data; sha256:" + _sha256_bytes(entity.snapshots[0].data),
                [entity.path], "WI-ARCHIVE-METADATA"))
        elif entity.kind == "unbound-flat-container":
            for path in (entity.path, *(snapshot.path for snapshot in entity.snapshots)):
                relative = _relative_link(work_items, path)
                entries.append(ReadmeEntry("Blockers", f"archive-observation:{relative}", relative,
                    path, False, "Identify the creator and format, then use its existing owner.",
                    [] if path == entity.path else [path], "WI-ARCHIVE-ENTITY-UNBOUND"))
    inventory.verify()
    if prepared_terminal is not None:
        metadata = json.loads(prepared_terminal.images[prepared_terminal.archive / LEGACY_COMPLETION_METADATA])
        entries.append(_legacy_terminal_entry(prepared_terminal.archive, metadata,
                                             prepared_terminal.images[prepared_terminal.archive / "closure.md"]))

    seen: set[str] = set()
    for entry in entries:
        if entry.logical_reference in seen:
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION",
                f"duplicate README logical reference: {entry.logical_reference}",
            )
        seen.add(entry.logical_reference)
    order = {section: index for index, section in enumerate(README_SECTIONS)}
    order["Archive metadata"] = len(order)
    return sorted(entries, key=lambda entry: (order[entry.section], entry.logical_reference))


def _input_digest(entries: Iterable[ReadmeEntry], work_items: Path, *, prepared_terminal=None) -> str:
    inputs: dict[str, Path] = {}
    for entry in entries:
        for path in entry.source_paths:
            logical_path = _relative_link(work_items, path)
            inputs[logical_path] = path
    digest = hashlib.sha256()
    for logical_path, path in sorted(inputs.items()):
        data = (prepared_terminal.images[path] if prepared_terminal is not None and path in prepared_terminal.images else _capture_file_snapshot(
            path,
            failure_id="WI-README-STALE",
            maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
        ).data)
        encoded = logical_path.encode("utf-8")
        digest.update(len(encoded).to_bytes(8, "big"))
        digest.update(encoded)
        digest.update(len(data).to_bytes(8, "big"))
        digest.update(data)
    return digest.hexdigest()


def _canonical_timestamp(entries: Iterable[ReadmeEntry], *, prepared_terminal=None) -> str:
    instants: list[str] = []
    for entry in entries:
        if entry.classification == LEGACY_COMPLETION_KIND:
            path = entry.link.parent / LEGACY_COMPLETION_METADATA
            raw = prepared_terminal.images[path] if prepared_terminal is not None and path in prepared_terminal.images else _capture_file_snapshot(
                path, failure_id="WI-README-STALE").data
            instant = json.loads(raw)["terminalInstant"]
            _strict_utc(instant); instants.append(instant)
            continue
        if entry.classification in {"WI-ARCHIVE-ENTITY-UNBOUND", "WI-ARCHIVE-METADATA"}:
            continue
        for path in entry.source_paths:
            if path.name == LEGACY_RETIREMENT_FILE:
                try:
                    value = json.loads(_capture_file_snapshot(
                        path,
                        failure_id="WI-README-STALE",
                        maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
                    ).data.decode("utf-8")).get("terminalAt")
                except (OSError, ValueError, RecursionError, AttributeError) as exc:
                    raise LifecycleError(
                        "WI-LEGACY-RETIREMENT-INVALID",
                        f"cannot read terminal instant: {path}",
                    ) from exc
                if isinstance(value, str) and UTC_INSTANT_RE.fullmatch(value):
                    _strict_utc(value)
                    instants.append(value)
                continue
            fields = _parse_fields(_capture_file_snapshot(
                path,
                failure_id="WI-README-STALE",
                maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
            ).data.decode("utf-8"))
            for key in ("updated", "closed", "terminal-at"):
                value = fields.get(key)
                if value and UTC_INSTANT_RE.fullmatch(value):
                    _strict_utc(value)
                    instants.append(value)
    return max(instants, default="none")


def _default_static_guide() -> str:
    return (
        "# Work items\n\n"
        "Read this page for current delivery status. Make lifecycle changes through "
        "`scripts/mutate-work-item.py`, then follow the generated links for detail.\n\n"
    )


def _static_guide(readme: Path, *, allow_marker_bootstrap: bool = False) -> str:
    if not readme.exists():
        return _default_static_guide()
    snapshot = _capture_file_snapshot(
        readme,
        failure_id="WI-README-STALE",
        maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
    )
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        if (_lifecycle_unresolved_absolute(readme) != transaction.work_items_root / "README.md"
                or not transaction._locked):
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "README capture differs from its held root owner")
        transaction.observe_retained_inputs((snapshot,))
    text = snapshot.data.decode("utf-8")
    begin_count = text.count(README_BEGIN)
    end_count = text.count(README_END)
    if allow_marker_bootstrap and begin_count == 0 and end_count == 0:
        return _default_static_guide()
    if begin_count != 1 or end_count != 1 or text.index(README_BEGIN) > text.index(README_END):
        raise LifecycleError(
            "WI-README-MARKERS",
            "existing README must contain exactly one ordered generated marker pair",
        )
    return text[: text.index(README_BEGIN)].rstrip() + "\n\n"


def render_readme_bytes(
    root: Path,
    *,
    allow_marker_bootstrap: bool = False,
    static_guide_override: str | None = None,
) -> bytes:
    return _render_readme_bytes(root, allow_marker_bootstrap=allow_marker_bootstrap,
                                static_guide_override=static_guide_override)


def _render_readme_bytes(
    root: Path, *, allow_marker_bootstrap: bool = False,
    static_guide_override: str | None = None, input_digest_out: list[str] | None = None,
    archive_inventory_out: list[dict] | None = None,
    archive_inventory_witness_out: list[ArchiveEntityInventory] | None = None,
    prepared_terminal=None,
) -> bytes:
    if prepared_terminal is not None:
        if type(prepared_terminal) is not PreparedWorkItemTerminal:
            raise LifecycleError("WI-LEGACY-COMPLETION-PREPARED", "unsupported prepared terminal type")
        prepared_terminal.verify(root)
    work_items = _work_items_root(root)
    inventory = _archive_entity_inventory(root)
    entries = _collect_readme_entries(root, archive_inventory=inventory, prepared_terminal=prepared_terminal)
    canonical_timestamp = _canonical_timestamp(entries, prepared_terminal=prepared_terminal)
    input_digest = _input_digest(entries, work_items, prepared_terminal=prepared_terminal)
    if input_digest_out is not None:
        input_digest_out.append(input_digest)
    lines = [
        README_BEGIN,
        "Read-model: work-items-readme-v1",
        "Ordered sources: backlog|active|roadmaps|archive",
        f"Canonical changes through: {canonical_timestamp}",
        f"Canonical input digest: sha256:{input_digest}",
        "",
    ]
    sections = README_SECTIONS + (("Archive metadata",) if any(
        entry.section == "Archive metadata" for entry in entries) else ())
    by_section = {section: [] for section in sections}
    for entry in entries:
        by_section[entry.section].append(entry)
    for section in sections:
        lines.extend((f"## {section}", ""))
        for entry in by_section[section]:
            marker = "x" if entry.checked else " "
            link = _relative_link(work_items, entry.link)
            if entry.section == "Recently completed" and entry.link.name == "closure.md":
                label = entry.logical_reference.removeprefix("work-item:")
                detail_parts = [entry.classification] if entry.classification else []
            else:
                label = entry.label
                detail_parts = [
                    part for part in (entry.detail, entry.classification) if part
                ]
            detail = f" — {' — '.join(detail_parts)}" if detail_parts else ""
            if section == "Archive metadata":
                lines.append(f"- [{label}]({link}){detail}")
            else:
                lines.append(f"- [{marker}] [{label}]({link}){detail}")
        lines.append("")
    lines.append(README_END)
    static_guide = (
        static_guide_override
        if static_guide_override is not None
        else _static_guide(
            work_items / "README.md",
            allow_marker_bootstrap=allow_marker_bootstrap,
        )
    )
    rendered = (
        static_guide
        + "\n".join(lines)
        + "\n"
    ).encode("utf-8")
    inventory.verify()
    if archive_inventory_out is not None:
        archive_inventory_out.append(inventory.observation(work_items))
    if archive_inventory_witness_out is not None:
        archive_inventory_witness_out.append(inventory)
    return rendered


def observe_readme(root: Path) -> dict:
    """Observe acquired README/input hashes without entering a writer transaction."""
    readme = _work_items_root(root) / "README.md"
    snapshot = None
    try:
        readme.lstat()
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise LifecycleError("WI-README-STALE", "README entry cannot be inspected") from exc
    else:
        snapshot = _capture_file_snapshot(readme, failure_id="WI-README-STALE")
    digests: list[str] = []
    inventories: list[dict] = []
    witnesses: list[ArchiveEntityInventory] = []
    expected = _render_readme_bytes(root, input_digest_out=digests, archive_inventory_out=inventories,
                                  archive_inventory_witness_out=witnesses)
    if snapshot is not None:
        _verify_captured_file(snapshot, "WI-README-STALE")
    elif _ledger_location_lexically_exists(readme):
        raise LifecycleError("WI-README-STALE", "README appeared during observation")
    repeated_digests: list[str] = []
    repeated_inventories: list[dict] = []
    repeated = _render_readme_bytes(root, input_digest_out=repeated_digests, archive_inventory_out=repeated_inventories)
    witnesses[0].verify()
    if repeated != expected or digests != repeated_digests or inventories != repeated_inventories:
        raise LifecycleError("WI-README-STALE", "README inputs drifted during observation")
    if snapshot is not None:
        _verify_captured_file(snapshot, "WI-README-STALE")
    elif _ledger_location_lexically_exists(readme):
        raise LifecycleError("WI-README-STALE", "README appeared during repeated observation")
    return {"matches": snapshot is not None and snapshot.data == expected,
            "observedSha256": _sha256_bytes(snapshot.data) if snapshot is not None else None,
            "expectedSha256": _sha256_bytes(expected), "inputDigest": digests[0],
            "archiveInventory": inventories[0]}


def refresh_readme(root: Path, *, allow_marker_bootstrap: bool = False,
                   archive_inventory_out: list[dict] | None = None) -> str:
    work_items = _work_items_root(root)
    inventories: list[dict] = []
    expected = _render_readme_bytes(
        root,
        allow_marker_bootstrap=allow_marker_bootstrap,
        archive_inventory_out=inventories,
    )
    readme = work_items / "README.md"
    _atomic_write(readme, expected)
    repeated_inventories: list[dict] = []
    observed = _render_readme_bytes(root, archive_inventory_out=repeated_inventories)
    if observed != expected or inventories != repeated_inventories or _capture_file_snapshot(
        readme,
        failure_id="WI-README-STALE",
        maximum_bytes=len(expected),
    ).data != expected:
        raise LifecycleError("WI-README-STALE", "README byte verification failed")
    if archive_inventory_out is not None:
        archive_inventory_out.append(inventories[0])
    return hashlib.sha256(expected).hexdigest()


def reset_readme_static_guide(root: Path, expected_readme_sha256: str, *,
                            archive_inventory_out: list[dict] | None = None) -> str:
    if not re.fullmatch(r"[0-9A-Fa-f]{64}", expected_readme_sha256):
        raise LifecycleError(
            "WI-README-REPAIR-TARGET-MISMATCH",
            "expected README SHA-256 must be exactly 64 hexadecimal characters",
        )
    work_items = _work_items_root(root)
    readme = work_items / "README.md"
    if not readme.is_file():
        raise LifecycleError(
            "WI-README-MARKERS",
            "static-guide repair requires an existing marker-owned README",
        )
    _static_guide(readme, allow_marker_bootstrap=True)
    current = readme.read_bytes()
    inventories: list[dict] = []
    desired = _render_readme_bytes(
        root,
        static_guide_override=_default_static_guide(),
        archive_inventory_out=inventories,
    )
    current_hash = hashlib.sha256(current).hexdigest()
    expected_hash = expected_readme_sha256.casefold()
    if current_hash != expected_hash and current != desired:
        raise LifecycleError(
            "WI-README-REPAIR-TARGET-MISMATCH",
            "README bytes differ from the explicitly targeted repair input",
        )
    if current != desired:
        _atomic_write(readme, desired)
    repeated_inventories: list[dict] = []
    observed = _render_readme_bytes(root, archive_inventory_out=repeated_inventories)
    if observed != desired or inventories != repeated_inventories or readme.read_bytes() != desired:
        raise LifecycleError(
            "WI-README-STALE",
            "README static-guide repair failed complete-byte verification",
        )
    if archive_inventory_out is not None:
        archive_inventory_out.append(inventories[0])
    return hashlib.sha256(desired).hexdigest()


def check_readme(root: Path) -> None:
    readme = _work_items_root(root) / "README.md"
    if not readme.is_file() or readme.read_bytes() != render_readme_bytes(root):
        raise LifecycleError("WI-README-STALE", "README does not match canonical inputs")


def _preflight_readme(root: Path) -> None:
    """Validate current canonical inputs and README marker ownership before mutation."""

    render_readme_bytes(root)


def _preflight_readme_markers(root: Path) -> None:
    """Validate README ownership when the current tree is intentionally terminal."""

    _static_guide(_work_items_root(root) / "README.md")


def _runtime_lexical_path(path: Path) -> str:
    return os.path.normcase(os.path.abspath(os.path.normpath(os.fspath(path))))


def _assert_runtime_source_authority(authority, failure_id: str) -> None:
    if authority is not None:
        try:
            authority.assert_current()
        except Exception as exc:
            raise LifecycleError(failure_id, "runtime source authority changed") from exc


def _declared_runtime_source_authority():
    try:
        home = Path.home()
    except (OSError, RuntimeError):
        return None
    if not home.is_absolute():
        return None
    roots = (home / ".agents" / "skills" / "lead", home / ".claude" / "agents")
    matches = [root for root in roots if _runtime_lexical_path(Path(__file__)) ==
               _runtime_lexical_path(root / "scripts" / "mutate-work-item.py")]
    if len(matches) != 1:
        return None
    path = matches[0] / "scripts" / "linked_runtime_subroots.py"
    try:
        spec = importlib.util.spec_from_file_location("work_item_runtime_source_authority", path)
        if spec is None or spec.loader is None:
            raise ValueError("runtime authority dependency is unavailable")
        module = importlib.util.module_from_spec(spec)
        sys.modules[spec.name] = module
        spec.loader.exec_module(module)
        return module.LinkedRuntimeSubrootAuthority.bind(
            matches[0], scope="global", trusted_global_roots=roots, allow_linked_ancestors=True,
        )
    except Exception as exc:
        raise LifecycleError("WI-VALIDATOR-LOAD", "runtime source authority cannot be acquired") from exc


_RUNTIME_SOURCE_INPUTS = (Path("scripts/mutate-work-item.py"), Path("scripts/validate-work-item-state.py"),
                          Path("shared/schemas/agent-runs.schema.json"))


def _capture_runtime_source(relative: Path, *, failure_id: str, authority=None):
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        transaction._assert_source_admission()
        authority = transaction._runtime_source_authority
    if relative not in _RUNTIME_SOURCE_INPUTS:
        raise LifecycleError(failure_id, "runtime source input is not controlled")
    if transaction is None and authority is None:
        authority = _declared_runtime_source_authority()
    try:
        _assert_runtime_source_authority(authority, failure_id)
        path = authority.ordinary_file(relative) if authority is not None else Path(__file__).parent.parent / relative
        snapshot = _capture_file_snapshot(path, failure_id=failure_id)
        _assert_runtime_source_authority(authority, failure_id)
        if transaction is not None:
            transaction._assert_source_admission()
        return snapshot
    except LifecycleError as exc:
        if transaction is not None:
            transaction._retain_source_failure(exc)
        raise
    except Exception as exc:
        failure = LifecycleError(failure_id, "runtime source cannot be acquired")
        if transaction is not None:
            transaction._retain_source_failure(failure)
        raise failure from exc
    except BaseException as exc:
        if transaction is not None:
            transaction._retain_source_failure(exc)
        raise


def _validator_module():
    path = Path(__file__).with_name("validate-work-item-state.py")
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()

    def actual_lifecycle_owner():
        owner = _LIFECYCLE_MODULE_ORIGIN
        if not isinstance(owner, ModuleType) or owner.__dict__ is not globals():
            raise LifecycleError("WI-VALIDATOR-LOAD", "executing lifecycle owner is unavailable")
        return owner

    def bind_actual_lifecycle_owner(validator, owner):
        if not isinstance(validator, ModuleType):
            raise LifecycleError("WI-VALIDATOR-LOAD", "validator loader did not return a module")
        if "_LIFECYCLE_OWNER" not in validator.__dict__ or validator.__dict__["_LIFECYCLE_OWNER"] is not None:
            raise LifecycleError("WI-VALIDATOR-LOAD", "validator lifecycle owner slot is unavailable")
        validator.__dict__["_LIFECYCLE_OWNER"] = owner

    def verify_cached_lifecycle_owner(validator, owner):
        if (
            not isinstance(validator, ModuleType)
            or "_LIFECYCLE_OWNER" not in validator.__dict__
            or validator.__dict__["_LIFECYCLE_OWNER"] is not owner
        ):
            raise LifecycleError("WI-VALIDATOR-LOAD", "cached validator owner differs from the executing lifecycle module")

    if transaction is not None:
        transaction.verify()
        if transaction._validator_reuse is not None:
            try:
                verify_cached_lifecycle_owner(transaction._validator_reuse, actual_lifecycle_owner())
            except BaseException as failure:
                transaction._retain_source_failure(failure)
                raise
            return transaction._validator_reuse
    if transaction is None:
        owner = actual_lifecycle_owner()
        spec = importlib.util.spec_from_file_location("work_item_state_validator", path)
        if spec is None or spec.loader is None:
            raise LifecycleError("WI-VALIDATOR-LOAD", f"cannot load validator: {path}")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        bind_actual_lifecycle_owner(module, owner)
        return module
    # Execute the native-acquired source, preserving the existing spec/name/file
    # context. V continues to own its schema path and dependency loaders.
    try:
        spec = importlib.util.spec_from_file_location("work_item_state_validator", path)
        if spec is None or spec.loader is None:
            raise LifecycleError("WI-VALIDATOR-LOAD", f"cannot load validator: {path}")
        module = importlib.util.module_from_spec(spec)
        source = _capture_runtime_source(Path("scripts/validate-work-item-state.py"), failure_id="WI-VALIDATOR-LOAD")
        transaction._assert_source_admission()
        exec(compile(source.data, str(path), "exec", dont_inherit=True), module.__dict__)
        transaction._assert_source_admission()
        schema = _capture_runtime_source(Path("shared/schemas/agent-runs.schema.json"), failure_id="WI-VALIDATOR-LOAD")
        if _runtime_lexical_path(module.AGENT_RUN_SCHEMA_PATH) != _runtime_lexical_path(schema.path):
            raise LifecycleError("WI-VALIDATOR-LOAD", "validator schema origin differs from runtime source")
        if json.loads(schema.data.decode("utf-8")) != module.AGENT_RUN_SCHEMA:
            raise LifecycleError("WI-VALIDATOR-LOAD", "loaded validator schema differs from the acquired configuration")
        _verify_captured_file(source, "WI-VALIDATOR-LOAD")
        _verify_captured_file(schema, "WI-VALIDATOR-LOAD")
        transaction.observe_retained_inputs((source, schema))
        owner = actual_lifecycle_owner()
        bind_actual_lifecycle_owner(module, owner)
    except BaseException as failure:
        transaction._retain_source_failure(failure)
        raise
    transaction.verify()
    transaction._validator_reuse = module
    return module


def _scratch_classifier_module():
    path = Path(__file__).with_name("maintenance") / "cleanup.py"
    spec = importlib.util.spec_from_file_location("scratch_evidence_classifier", path)
    if spec is None or spec.loader is None:
        raise LifecycleError("WI-SCRATCH-CLASSIFIER-LOAD", f"cannot load classifier: {path}")
    module = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = module
    spec.loader.exec_module(module)
    return module


def _agent_run_ledger_module():
    path = Path(__file__).with_name("agent-run-ledger.py")
    try:
        spec = importlib.util.spec_from_file_location("agent_run_ledger", path)
        if spec is None or spec.loader is None:
            raise ImportError(f"no import specification or loader for {path}")
        module = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(module)
        return module
    except Exception as exc:
        raise LifecycleError(
            "WI-LEDGER-BOOTSTRAP-INVALID",
            f"cannot load ledger helper {path}: {exc}",
        ) from exc


def _staged_admission_ledger_bytes(slug: str, status_data: bytes) -> bytes:
    """Build the settled Lead admission event from the already-validated status."""

    started_at = _parse_fields(status_data.decode("utf-8"))["started"]
    ledger = _agent_run_ledger_module()
    args = argparse.Namespace(
        work_item=Path(slug),
        run_id=f"{slug}-lifecycle-start",
        work_item_name=slug,
        role="lead",
        execution_role="main",
        assigned_role=None,
        provider=None,
        model=None,
        status="completed",
        gate="none",
        scope=["candidate -> active lifecycle admission"],
        prompt_file=None,
        artifact=None,
        evidence=None,
        evidence_json=None,
        started_at=started_at,
        updated_at=started_at,
        notes=None,
        event_kind="standalone",
        launch_run_id=None,
        closes=None,
        artifact_revision=None,
        lane=None,
        effort=None,
        finding_class=None,
    )
    try:
        event = ledger.build_event(args)
        return (ledger.serialize_event(event) + "\n").encode("utf-8")
    except (TypeError, ValueError, json.JSONDecodeError) as exc:
        raise LifecycleError("WI-LEDGER-BOOTSTRAP-INVALID", str(exc)) from exc


def _validate_active_status_bytes(data: bytes) -> None:
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError("WI-CATEGORY-STATUS-INVALID", "status must be UTF-8") from exc
    fields = _parse_fields(text)
    if _current_readme_status_error(fields, "active", Path("status.md")) is not None:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID", "active status must be active or blocked"
        )
    template = fields.get("template")
    if template == "quick-fix":
        errors: list[str] = []
        _validator_module().validate_quick_fix_status(text, errors)
        if errors:
            raise LifecycleError("WI-CATEGORY-STATUS-INVALID", "; ".join(errors))
        return
    if template != "staged":
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID", "V1 status template must be quick-fix or staged"
        )
    required = {
        "started",
        "updated",
        "task",
        "current step",
        "last result",
        "next action",
        "scope boundary",
        "owner",
        "integration owner",
        "evidence gate",
    }
    missing = sorted(required - set(fields))
    if missing:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID", f"staged status missing fields: {', '.join(missing)}"
        )
    for slug in _optional_relation_values(
        fields.get("depends-on"),
        comma_separated=True,
    ):
        if ":" in slug:
            raise LifecycleError(
                "WI-DEPENDENCY-NON-WORK-ITEM",
                "Depends-on accepts bare work-item slugs only",
            )
        _validate_slug(slug)


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def create_candidate(root: Path, slug: str, data: bytes, *, inject_readme_failure: bool = False) -> Path:
    work_items = _work_items_root(root)
    if _category_locations(root, CATEGORIES["work-item"], slug):
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", f"slug already exists: {slug}")
    _preflight_readme(root)
    target = work_items / "backlog" / f"{slug}.md"
    failure = _current_readme_status_error(_parse_fields(data.decode("utf-8")), "backlog", target)
    if failure is not None:
        raise LifecycleError("WI-README-STALE", str(failure)) from failure
    _atomic_write(target, data)
    if inject_readme_failure:
        raise LifecycleError("WI-README-STALE", "injected failure after canonical success")
    try:
        refresh_readme(root)
    except LifecycleError as exc:
        if exc.failure_id == "WI-README-STALE":
            raise
        raise LifecycleError("WI-README-STALE", str(exc)) from exc
    return target


def _legacy_backlog_source_at(work_items: Path, slug: str, *, binding_evidence: list | None = None) -> Path | None:
    evidence = [] if binding_evidence is None else binding_evidence
    source = work_items / "backlog" / slug
    if _observe_project_path_at(source, "directory", evidence, "WI-INVALID-TARGET") is None:
        return None
    return source


def _legacy_backlog_source(root: Path, slug: str) -> Path:
    _validate_slug(slug)
    locations = _category_locations(root, CATEGORIES["work-item"], slug)
    if locations:
        raise LifecycleError(
            "WI-CATEGORY-DUAL-LOCATION", f"canonical work-item identity already exists: {slug}"
        )
    source = _legacy_backlog_source_at(_work_items_root(root), slug)
    if source is None:
        raise LifecycleError(
            "WI-INVALID-TARGET", f"legacy backlog folder is missing: {slug}"
        )
    return source


def _legacy_source_rows(source: Path) -> list[tuple[str, bytes, str]]:
    rows: list[tuple[str, bytes, str]] = []
    for path in sorted(source.rglob("*"), key=lambda item: item.relative_to(source).as_posix()):
        if path.is_symlink():
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD", f"symbolic-link source is not admitted: {path}"
            )
        if path.is_dir():
            continue
        if not path.is_file():
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD", f"unsupported legacy source: {path}"
            )
        relative = path.relative_to(source).as_posix()
        if relative == LEGACY_RETIREMENT_FILE:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD",
                f"legacy source uses reserved owner metadata name: {relative}",
            )
        data = path.read_bytes()
        try:
            text = data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD", f"legacy source is not UTF-8 text: {path}"
            ) from exc
        rows.append((relative, data, text))
    if not rows:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-PAYLOAD", f"legacy backlog folder is empty: {source}"
        )
    return rows


def _candidate_with_legacy_appendices(
    candidate_data: bytes,
    rows: Iterable[tuple[str, bytes, str]],
) -> bytes:
    try:
        candidate_data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-PAYLOAD", "candidate input must be UTF-8 text"
        ) from exc
    result = bytearray(candidate_data)
    if not result.endswith(b"\n"):
        result.extend(b"\n")
    result.extend(b"\n## Preserved legacy source appendices\n")
    for relative, data, text in rows:
        longest = max((len(match.group(0)) for match in re.finditer(r"`+", text)), default=0)
        fence = "`" * max(3, longest + 1)
        header = (
            f"\n### `{relative}`\n\n"
            f"Source SHA-256: `{hashlib.sha256(data).hexdigest()}`\n\n"
            f"Source byte length: `{len(data)}`\n\n"
            f"{fence}markdown\n"
        ).encode("utf-8")
        result.extend(header)
        result.extend(data)
        if not data.endswith(b"\n"):
            result.extend(b"\n")
        result.extend(f"{fence}\n".encode("utf-8"))
    return bytes(result)


def _restore_readme_snapshot(readme: Path, before: bytes | None) -> None:
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        transaction.restore_owned_file(readme, before)
    elif before is None:
        readme.unlink(missing_ok=True)
    else:
        _atomic_write(readme, before)


def _preflight_legacy_transition_admission(
    root: Path,
    source: Path,
    reference: str,
) -> dict:
    """Reject a legacy transition before it can orphan a physical consumer."""
    incoming = _incoming_link_result(root, {source}, reference)
    _validate_incoming_link_snapshot(reference, incoming, label="legacy transition")
    return incoming


def _legacy_cleanup_metadata(
    slug: str,
    target: Path,
    transaction: Path,
    converted: bytes,
    rows: Iterable[tuple[str, bytes, str]],
) -> bytes:
    payload = {
        "schemaVersion": LEGACY_CLEANUP_SCHEMA_VERSION,
        "owner": LEGACY_CLEANUP_OWNER,
        "slug": slug,
        "transactionId": transaction.name,
        "canonicalTarget": f"{target.parent.name}/{target.name}",
        "candidateSha256": hashlib.sha256(converted).hexdigest(),
        "sourceFiles": [
            {
                "path": relative,
                "byteLength": len(data),
                "sha256": hashlib.sha256(data).hexdigest(),
            }
            for relative, data, _text in rows
        ],
    }
    return (json.dumps(payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")


def _legacy_cleanup_sidecar(backlog: Path, transaction_id: str) -> Path:
    return backlog / f".legacy-candidate-cleanup.{transaction_id.removeprefix('.')}.json"


def _validated_legacy_cleanup_residue(
    backlog: Path, slug: str, target: Path
) -> tuple[Path | None, Path, str]:
    prefix = f".{slug}.legacy-candidate."
    parent = backlog.resolve()
    residues = sorted(path for path in backlog.glob(f"{prefix}*") if path.name.startswith(prefix))
    if len(residues) > 1:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"committed cleanup requires exactly one owned residue for {slug}, found {len(residues)}",
        )
    residue = residues[0] if residues else None
    if residue is not None and (
        residue.is_symlink() or not residue.is_dir() or residue.resolve().parent != parent
    ):
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"unsafe committed-cleanup residue for {slug}: {residue}",
        )
    sidecar_prefix = f".legacy-candidate-cleanup.{slug}.legacy-candidate."
    sidecars = sorted(backlog.glob(f"{sidecar_prefix}*.json"))
    markers = list(sidecars)
    if residue is not None:
        embedded_marker = residue / LEGACY_CLEANUP_FILE
        if embedded_marker.exists() or embedded_marker.is_symlink():
            markers.append(embedded_marker)
    if len(markers) != 1:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"committed cleanup requires exactly one owner marker for {slug}, found {len(markers)}",
        )
    marker = markers[0]
    if marker.is_symlink() or not marker.is_file() or marker.resolve().parent not in {parent, residue}:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"unsafe owner cleanup marker for {slug}: {marker}",
        )
    if marker.parent == backlog:
        transaction_id = "." + marker.name.removeprefix(".legacy-candidate-cleanup.").removesuffix(
            ".json"
        )
    elif residue is not None and marker.parent == residue:
        transaction_id = residue.name
    else:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"owner cleanup marker has no transaction parent for {slug}: {marker}",
        )
    if not transaction_id.startswith(prefix) or (residue is not None and transaction_id != residue.name):
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"owner cleanup marker transaction differs from residue for {slug}: {marker}",
        )
    try:
        payload = json.loads(marker.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"invalid owner cleanup marker for {slug}: {marker}",
        ) from exc
    expected = {
        "schemaVersion": LEGACY_CLEANUP_SCHEMA_VERSION,
        "owner": LEGACY_CLEANUP_OWNER,
        "slug": slug,
        "transactionId": transaction_id,
        "canonicalTarget": f"{target.parent.name}/{target.name}",
        "candidateSha256": hashlib.sha256(target.read_bytes()).hexdigest(),
    }
    if not isinstance(payload, dict) or any(payload.get(key) != value for key, value in expected.items()):
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"owner cleanup marker differs from committed candidate for {slug}",
        )
    candidate_text = target.read_text(encoding="utf-8")
    rows = payload.get("sourceFiles")
    if not isinstance(rows, list) or not rows:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"owner cleanup marker has no source inventory for {slug}",
        )
    expected_files: dict[str, tuple[int, str]] = {}
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get("path"), str):
            raise LifecycleError(
                "WI-LEGACY-CLEANUP-REPLAY-INVALID",
                f"owner cleanup marker has invalid source row for {slug}",
            )
        relative = row["path"]
        candidate = Path(relative)
        byte_length = row.get("byteLength")
        digest = row.get("sha256")
        if (
            candidate.is_absolute()
            or ".." in candidate.parts
            or not relative
            or relative in expected_files
            or not isinstance(byte_length, int)
            or byte_length < 0
            or not isinstance(digest, str)
            or not re.fullmatch(r"[0-9a-f]{64}", digest)
        ):
            raise LifecycleError(
                "WI-LEGACY-CLEANUP-REPLAY-INVALID",
                f"owner cleanup marker source inventory is invalid for {slug}",
            )
        expected_files[relative] = (byte_length, digest)
        source_identity = (
            f"### `{relative}`\n\n"
            f"Source SHA-256: `{digest}`\n\n"
            f"Source byte length: `{byte_length}`\n\n"
        )
        if source_identity not in candidate_text:
            raise LifecycleError(
                "WI-LEGACY-CLEANUP-REPLAY-INVALID",
                f"owner cleanup marker source identity is not committed for {slug}: {relative}",
            )
    source_root = residue / "source" if residue is not None else None
    actual_files: set[str] = set()
    if residue is not None:
        for path in residue.rglob("*"):
            if path.is_symlink() or not (path.is_dir() or path.is_file()):
                raise LifecycleError(
                    "WI-LEGACY-CLEANUP-REPLAY-INVALID",
                    f"owner cleanup residue contains unsafe path for {slug}: {path}",
                )
            if path == marker:
                continue
            try:
                relative = path.relative_to(source_root).as_posix()
            except ValueError as exc:
                raise LifecycleError(
                    "WI-LEGACY-CLEANUP-REPLAY-INVALID",
                    f"owner cleanup residue contains unowned path for {slug}: {path}",
                ) from exc
            if path.is_dir():
                continue
            expected_file = expected_files.get(relative)
            data = path.read_bytes()
            if expected_file is None or expected_file != (len(data), hashlib.sha256(data).hexdigest()):
                raise LifecycleError(
                    "WI-LEGACY-CLEANUP-REPLAY-INVALID",
                    f"owner cleanup residue source differs for {slug}: {relative}",
                )
            actual_files.add(relative)
    if not actual_files <= expected_files.keys():
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"owner cleanup residue has unowned files for {slug}",
        )
    return residue, marker, transaction_id


def _finish_committed_legacy_cleanup(
    backlog: Path,
    residue: Path | None,
    marker: Path,
    transaction_id: str,
) -> None:
    if residue is not None:
        source = residue / "source"
        if source.exists():
            shutil.rmtree(source)
        sidecar = _legacy_cleanup_sidecar(backlog, transaction_id)
        if marker.parent == residue:
            _replace_lifecycle_directory(marker, sidecar, directory=False)
            marker = sidecar
        residue.rmdir()
    marker.unlink()


def _committed_cleanup_failure(target: Path, residue: Path, cause: BaseException) -> LifecycleError:
    return LifecycleError(
        "WI-LEGACY-CLEANUP-AFTER-COMMIT",
        f"state=committed target={target} residue={residue}: {cause}",
    )


def _replay_legacy_candidate_cleanup(root: Path, slug: str, candidate_data: bytes) -> Path | None:
    """Remove exactly one safe residue without replaying a committed conversion."""

    work_items = _work_items_root(root)
    backlog = work_items / "backlog"
    source = backlog / slug
    target = backlog / f"{slug}.md"
    if source.exists() or not target.is_file():
        return None
    canonical = _category_locations(root, CATEGORIES["work-item"], slug)
    if canonical != [target]:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"committed cleanup has ambiguous canonical identity for {slug}",
        )
    candidate_prefix = candidate_data if candidate_data.endswith(b"\n") else candidate_data + b"\n"
    if not target.read_bytes().startswith(candidate_prefix + b"\n## Preserved legacy source appendices\n"):
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"committed cleanup target does not match requested conversion input: {target}",
        )
    check_readme(root)
    residue, marker, transaction_id = _validated_legacy_cleanup_residue(backlog, slug, target)
    target_before = target.read_bytes()
    readme = work_items / "README.md"
    readme_before = readme.read_bytes()
    try:
        _finish_committed_legacy_cleanup(backlog, residue, marker, transaction_id)
    except OSError as exc:
        raise _committed_cleanup_failure(target, residue, exc) from exc
    if (residue is not None and residue.exists()) or marker.exists() or target.read_bytes() != target_before or readme.read_bytes() != readme_before:
        raise LifecycleError(
            "WI-LEGACY-CLEANUP-REPLAY-INVALID",
            f"committed cleanup replay changed canonical state for {slug}",
        )
    return target


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def convert_legacy_candidate(
    root: Path,
    slug: str,
    candidate_data: bytes,
    *,
    inject_readme_failure: bool = False,
) -> Path:
    replay = _replay_legacy_candidate_cleanup(root, slug, candidate_data)
    if replay is not None:
        return replay
    source = _legacy_backlog_source(root, slug)
    _preflight_legacy_transition_admission(root, source, f"work-item:{slug}")
    rows = _legacy_source_rows(source)
    _validate_canonical_candidate_header(candidate_data)
    converted = _candidate_with_legacy_appendices(candidate_data, rows)
    _preflight_readme(root)
    work_items = _work_items_root(root)
    readme = work_items / "README.md"
    readme_before = readme.read_bytes() if readme.is_file() else None
    target = work_items / "backlog" / f"{slug}.md"
    transaction = Path(tempfile.mkdtemp(prefix=f".{slug}.legacy-candidate.", dir=target.parent))
    staged_source = transaction / "source"
    staged_candidate = transaction / target.name
    cleanup_marker = transaction / LEGACY_CLEANUP_FILE
    committed = False
    try:
        _atomic_write(staged_candidate, converted)
        _atomic_write(
            cleanup_marker,
            _legacy_cleanup_metadata(slug, target, transaction, converted, rows),
        )
        _replace_lifecycle_directory(source, staged_source)
        _replace_lifecycle_directory(staged_candidate, target, directory=False)
        if inject_readme_failure:
            raise LifecycleError("WI-README-STALE", "injected legacy conversion failure")
        refresh_readme(root)
        if source.exists() or target.read_bytes() != converted:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD", "legacy candidate byte verification failed"
            )
        check_readme(root)
        # The flat candidate, regenerated read-model, and byte check form the
        # irreversible commit point. Its appendices carry every staged legacy
        # byte, so disposal of the no-longer-authoritative transaction copy
        # cannot roll this committed transition back.
        committed = True
        try:
            _finish_committed_legacy_cleanup(target.parent, transaction, cleanup_marker, transaction.name)
        except OSError as exc:
            raise _committed_cleanup_failure(target, transaction, exc) from exc
    except BaseException as primary:
        composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
        composer.capture_primary(primary)
        held = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if not committed:
            incomplete = False
            def attempt(label, action, *paths):
                nonlocal incomplete
                if held.cleanup_intersects_unsettled(paths):
                    incomplete = True
                    return
                try:
                    action()
                except BaseException as cleanup:
                    incomplete = True
                    composer.record_rollback_action(
                        failure_id=cleanup.failure_id if isinstance(cleanup, LifecycleError) else "WI-CATEGORY-MIGRATION-PAYLOAD",
                        resource=paths[0].relative_to(root).as_posix() if paths else None,
                        diagnostic=label, cause=cleanup)
            attempt("remove owned candidate", lambda: held.restore_owned_file(target, None), target)
            if os.path.lexists(staged_source):
                attempt("restore staged original source",
                    lambda: held.restore_owned_movement(staged_source, source), staged_source, source)
            attempt("restore README", lambda: _restore_readme_snapshot(readme, readme_before), readme)
            attempt("remove staged candidate", lambda: held.restore_owned_file(staged_candidate, None), staged_candidate)
            attempt("remove owned cleanup marker", lambda: held.restore_owned_file(cleanup_marker, None), cleanup_marker)
            # This final action depends on actual emptiness; rmdir cannot erase
            # an original-bearing, foreign or unsettled stage.
            attempt("remove empty conversion stage", transaction.rmdir, transaction)
            if incomplete:
                composer.set_rollback("incomplete")
        raise
    return target


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def retire_legacy_backlog(
    root: Path,
    slug: str,
    disposition_data: bytes,
    terminal_instant: str,
    *,
    inject_readme_failure: bool = False,
) -> Path:
    source = _legacy_backlog_source(root, slug)
    reference = f"work-item:{slug}"
    incoming = _preflight_legacy_transition_admission(root, source, reference)
    rows = _legacy_source_rows(source)
    try:
        disposition = disposition_data.decode("utf-8").strip()
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID", "product disposition must be UTF-8 text"
        ) from exc
    if not disposition:
        raise LifecycleError(
            "WI-LEGACY-RETIREMENT-INVALID", "product disposition must not be empty"
        )
    month = archive_month(terminal_instant)
    _preflight_readme(root)
    work_items = _work_items_root(root)
    metadata_payload = {
        "schemaVersion": LEGACY_RETIREMENT_SCHEMA_VERSION,
        "owner": LEGACY_RETIREMENT_OWNER,
        "kind": "legacy-backlog-retirement",
        "slug": slug,
        "status": "rejected-before-admission",
        "terminalAt": terminal_instant,
        "productDisposition": disposition,
        "admissionHistory": "never-admitted",
        "syntheticTransitions": [],
        "sourceFiles": [
            {
                "path": relative,
                "byteLength": len(data),
                "sha256": hashlib.sha256(data).hexdigest(),
            }
            for relative, data, _text in rows
        ],
        "incomingLinks": incoming,
    }
    metadata_data = (
        json.dumps(metadata_payload, ensure_ascii=False, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    readme = work_items / "README.md"
    readme_before = readme.read_bytes() if readme.is_file() else None
    archive = work_items / "archive"
    month_dir = archive / month
    target = month_dir / slug
    if target.exists():
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", f"archive target exists: {target}")
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    original_source = _capture_owned_directory_snapshot(source, failure_id="WI-LEGACY-RETIREMENT-INVALID")
    transaction.observe_retained_inputs((original_source,))
    stage = source.parent / f".{slug}.legacy-retire.{uuid.uuid4().hex}"
    staged_source = stage / "source"
    stage_creations: list[_OwnedNativeCreation] = []
    created_directories: list[_OwnedNativeCreation] = []
    composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
    compensation_required = False
    try:
        LifecycleWriteTarget.make_directories(stage, transaction, created=stage_creations)
        if len(stage_creations) != 1 or stage_creations[0].locator != stage:
            raise LifecycleError("WI-LEGACY-RETIREMENT-INVALID", "retirement stage was not created by this invocation")
        _replace_lifecycle_directory(source, staged_source)
        _atomic_write(staged_source / LEGACY_RETIREMENT_FILE, metadata_data)
        LifecycleWriteTarget.make_directories(month_dir, _CURRENT_LIFECYCLE_TRANSACTION.get(), created=created_directories)
        _replace_lifecycle_directory(staged_source, target)
        if inject_readme_failure:
            raise LifecycleError("WI-README-STALE", "injected legacy retirement failure")
        refresh_readme(root)
        _legacy_retirement_entry(target, target / LEGACY_RETIREMENT_FILE)
    except BaseException as primary:
        composer.capture_primary(primary)
        compensation_required = any(record.creator and record.acquired
                                    for record in (*stage_creations, *created_directories))
        incomplete = False
        action, resource = "restore original source custody", staged_source
        if compensation_required:
            try:
                if _lifecycle_cleanup_intersects_unsettled(target, staged_source, source):
                    incomplete = True
                else:
                    if target.exists() and not staged_source.exists():
                        action, resource = "restore archive to actual stage", target
                        transaction.restore_owned_movement(target, staged_source)
                    if staged_source.exists():
                        action, resource = "remove owned retirement metadata", staged_source / LEGACY_RETIREMENT_FILE
                        transaction.restore_owned_file(resource, None)
                        if source.exists():
                            incomplete = True
                            composer.record_rollback_action(failure_id="WI-LEGACY-RETIREMENT-INVALID",
                                resource=staged_source.relative_to(root).as_posix(),
                                diagnostic="original source restoration target is occupied; staged custody preserved")
                        else:
                            action, resource = "restore staged original source", staged_source
                            transaction.restore_owned_movement(staged_source, source)
            except BaseException as cleanup:
                incomplete = True
                composer.record_rollback_action(
                    failure_id=cleanup.failure_id if isinstance(cleanup, LifecycleError) else "WI-LEGACY-RETIREMENT-INVALID",
                    resource=resource.relative_to(root).as_posix(), diagnostic=action, cause=cleanup)
            try:
                if _lifecycle_cleanup_intersects_unsettled(readme):
                    incomplete = True
                else:
                    _restore_readme_snapshot(readme, readme_before)
            except BaseException as cleanup:
                incomplete = True
                composer.record_rollback_action(
                    failure_id=cleanup.failure_id if isinstance(cleanup, LifecycleError) else "WI-README-STALE",
                    resource=readme.relative_to(root).as_posix(), diagnostic="restore README", cause=cleanup)
            current_source = transaction.current_observation(original_source)
            if isinstance(current_source, CapturedDirectorySnapshotV1) and current_source.path == source:
                for record in reversed(created_directories):
                    if not record.creation_published:
                        continue
                    if _lifecycle_cleanup_intersects_unsettled(record.locator):
                        incomplete = True
                        continue
                    try:
                        LifecycleWriteTarget.remove_created_directory(record, transaction,
                            failure_id="WI-LEGACY-RETIREMENT-INVALID")
                    except BaseException as cleanup:
                        incomplete = True
                        composer.record_rollback_action(
                            failure_id=cleanup.failure_id if isinstance(cleanup, LifecycleError) else "WI-LEGACY-RETIREMENT-INVALID",
                            resource=record.locator.relative_to(root).as_posix(), diagnostic="remove created archive directory", cause=cleanup)
            else:
                incomplete = True
            composer.set_rollback("incomplete" if incomplete else "completed")
        raise
    finally:
        for record in reversed(stage_creations):
            if not record.creation_published:
                continue  # An unpublished acquisition retains its native creator abort owner.
            current_source = transaction.current_observation(original_source)
            if (not isinstance(current_source, CapturedDirectorySnapshotV1)
                    or current_source.path not in (source, target)
                    or _lifecycle_cleanup_intersects_unsettled(stage, source, target)):
                composer.set_rollback("incomplete")
                continue  # Preserve original/uncertain custody; never recurse into the stage.
            try:
                _verify_owned_directory_snapshot(current_source, "WI-LEGACY-RETIREMENT-INVALID")
                LifecycleWriteTarget.remove_created_directory(record, transaction,
                    failure_id="WI-LEGACY-RETIREMENT-INVALID")
            except BaseException as cleanup:
                composer.record_rollback_action(
                    failure_id=cleanup.failure_id if isinstance(cleanup, LifecycleError) else "WI-LEGACY-RETIREMENT-INVALID",
                    resource=record.locator.relative_to(root).as_posix(), diagnostic="release empty native retirement stage", cause=cleanup)
                if compensation_required:
                    composer.set_rollback("incomplete")
    return target


def _postcommit_readme_stale(operation: str) -> LifecycleError:
    return LifecycleError(
        "WI-README-STALE",
        f"{operation} committed canonical state; README refresh required; "
        f"do not retry {operation}; run refresh, then verify the target.",
    )


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def start_item(root: Path, slug: str, status_data: bytes, *, inject_readme_failure: bool = False) -> Path:
    _validate_active_status_bytes(status_data)
    is_staged = _parse_fields(status_data.decode("utf-8")).get("template") == "staged"
    admission_ledger = _staged_admission_ledger_bytes(slug, status_data) if is_staged else None
    work_items = _work_items_root(root)
    locations = _category_locations(root, CATEGORIES["work-item"], slug)
    backlog = work_items / "backlog" / f"{slug}.md"
    if locations != [backlog]:
        failure = "WI-CATEGORY-DUAL-LOCATION" if len(locations) > 1 else "WI-INVALID-TARGET"
        raise LifecycleError(failure, f"start requires exactly one backlog candidate: {slug}")
    failure = _current_readme_status_error(
        _parse_fields(backlog.read_text(encoding="utf-8")), "backlog", backlog,
    )
    if failure is not None:
        raise failure
    transfer_relation = _validate_started_transfer_relation(backlog.read_bytes(), status_data)
    _validate_obligation_transfer_ownership(root)
    _preflight_readme(root)
    active_parent = work_items / "active"
    active_parent.mkdir(parents=True, exist_ok=True)
    target = active_parent / slug
    temp = Path(tempfile.mkdtemp(prefix=f".{slug}.", dir=active_parent))
    moved_candidate = temp / "admission.md"
    committed = False
    try:
        _replace_lifecycle_directory(backlog, moved_candidate, directory=False)
        _atomic_write(temp / "status.md", status_data)
        if admission_ledger is not None:
            _atomic_write(temp / "agent-runs.jsonl", admission_ledger)
            errors = _validator_module().validate_work_item(
                temp, strict_revise=transfer_relation is None
            )
            if errors:
                raise LifecycleError("WI-LEDGER-BOOTSTRAP-INVALID", "; ".join(errors))
        _replace_lifecycle_directory(temp, target)
        committed = True
    finally:
        if not committed:
            if moved_candidate.exists() and not backlog.exists() and not _lifecycle_cleanup_intersects_unsettled(moved_candidate, backlog):
                backlog.parent.mkdir(parents=True, exist_ok=True)
                _replace_lifecycle_directory(moved_candidate, backlog, directory=False)
            if not _lifecycle_cleanup_intersects_unsettled(temp):
                shutil.rmtree(temp, ignore_errors=True)
    if inject_readme_failure:
        raise _postcommit_readme_stale("start")
    try:
        refresh_readme(root)
    except LifecycleError as exc:
        raise _postcommit_readme_stale("start") from exc
    return target


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def update_status(root: Path, slug: str, status_data: bytes, *, inject_readme_failure: bool = False) -> Path:
    _validate_active_status_bytes(status_data)
    target = resolve_category(root, f"work-item:{slug}")
    if target.parent.name != "active" or not target.is_dir():
        raise LifecycleError("WI-INVALID-TARGET", "status update requires an active work-item")
    _status_entry(root, target)
    _preflight_readme(root)
    status = target / "status.md"
    _atomic_write(status, status_data)
    if inject_readme_failure:
        raise _postcommit_readme_stale("update")
    try:
        refresh_readme(root)
    except LifecycleError as exc:
        raise _postcommit_readme_stale("update") from exc
    return status


def _validate_closure(data: bytes, terminal_instant: str) -> None:
    try:
        fields = _parse_fields(data.decode("utf-8"))
    except UnicodeDecodeError as exc:
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "closure must be UTF-8") from exc
    required = {"closed", "outcome", "evidence", "residual risk"}
    missing = sorted(key for key in required if not fields.get(key))
    if missing:
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            f"closure missing fields: {', '.join(missing)}",
        )
    if fields["closed"] != terminal_instant:
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            "closure Closed does not match requested terminal instant",
        )
    _strict_utc(fields["closed"])


def _terminalize_status(data: bytes) -> bytes:
    if _schema_marker_occurrences(data, "status.md"):
        raise LifecycleError(
            "WI-CATEGORY-SCHEMA-INVALID",
            "active status must not contain a lifecycle schema marker",
        )
    text = data.decode("utf-8")
    replaced, count = re.subn(
        r"(?im)^(\s*status\s*:\s*)(active|blocked)\s*$",
        r"\1completed",
        text,
        count=1,
    )
    if count != 1:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID",
            "active V1 status has no single active/blocked status field",
        )
    return _stamp_schema_marker(replaced.encode("utf-8"), "status.md")


SCRATCH_REGENERATION_MARKER = (
    "Scratch evidence: regeneration-only; all load-bearing observations retained."
)


def _scratch_tombstone(original: Path, slug: str, run_id: str, entry_id: str) -> Path:
    name = _validator_module().scratch_tombstone_name(slug, run_id, entry_id)
    return original.with_name(name)


def _classify_scratch_entry(classifier, path: Path, root: Path):
    try:
        return classifier.classify_owned_tree(path, root)
    except classifier.OwnedTreeClassificationError as exc:
        failure = {
            "SCRATCH-INVENTORY-UNSAFE": "WI-SCRATCH-UNSAFE-ENTRY",
            "SCRATCH-INVENTORY-DRIFT": "WI-SCRATCH-IDENTITY-DRIFT",
        }.get(exc.failure_id, "WI-SCRATCH-PROOF-FAILED")
        raise LifecycleError(failure, str(exc)) from exc


def _verify_scratch_proof(
    snapshot,
    proof: dict,
    canonical_pointer: Path,
) -> None:
    kind = proof["kind"]
    if kind == "git-object-set":
        if not snapshot.git_check_complete or not snapshot.all_git_recoverable:
            raise LifecycleError(
                "WI-SCRATCH-PROOF-FAILED",
                "scratch bytes are not completely recoverable from the repository object store",
            )
        return
    if kind != "accepted-artifact":
        raise LifecycleError("WI-SCRATCH-PROOF-FAILED", f"unsupported proof kind: {kind!r}")
    try:
        artifact = canonical_pointer.read_bytes()
    except OSError as exc:
        raise LifecycleError(
            "WI-SCRATCH-PROOF-FAILED", "accepted artifact is unreadable"
        ) from exc
    if hashlib.sha256(artifact).hexdigest() != proof["artifactSha256"]:
        raise LifecycleError("WI-SCRATCH-PROOF-FAILED", "accepted artifact digest differs")
    try:
        text = artifact.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-SCRATCH-PROOF-FAILED", "accepted artifact is not UTF-8"
        ) from exc
    if SCRATCH_REGENERATION_MARKER not in text:
        raise LifecycleError(
            "WI-SCRATCH-PROOF-FAILED", "accepted artifact lacks the regeneration marker"
        )


def _relocate_scratch_pointer(root: Path, pointer: Path) -> Path:
    if pointer.is_file():
        return pointer
    try:
        relative = pointer.relative_to(root)
    except ValueError:
        return pointer
    parts = relative.parts
    if len(parts) < 4 or parts[:2] != ("work-items", "active"):
        return pointer
    locations = _category_locations(root, CATEGORIES["work-item"], parts[2])
    archived = [path for path in locations if "archive" in path.parts]
    return archived[0].joinpath(*parts[3:]) if len(archived) == 1 else pointer


def _scratch_namespace_entries(owner_root: Path) -> tuple[set[Path], set[Path]]:
    """Return present original/tombstone leaf roots without following links."""

    classifier = _scratch_classifier_module()
    try:
        inspection = classifier.inspect_owned_namespace(owner_root)
    except LifecycleError:
        raise
    except (OSError, classifier.OwnedTreeClassificationError) as exc:
        raise LifecycleError("WI-SCRATCH-UNSAFE-ENTRY", str(exc)) from exc
    return set(inspection.originals), set(inspection.tombstones)


def _release_receipt_path(item: Path, run_id: str, entry_id: str) -> Path:
    identity = _sha256_bytes(f"{run_id}\0{entry_id}".encode("utf-8"))
    return item / "retained-scratch-releases" / f"{identity}.json"


def _release_event_binding(
    item: Path, run_id: str, entry_id: str, *, event_out: list[dict] | None = None,
) -> tuple[str, dict]:
    matches: list[tuple[str, dict]] = []
    ledger_bytes = (
        _capture_file_snapshot(
            item / "agent-runs.jsonl", failure_id="WI-SCRATCH-RECONCILIATION-IDENTITY",
            maximum_bytes=_validator_module().MAX_TRANSFER_LEDGER_BYTES, require_single_link=True,
        ).data
        if event_out is not None else (item / "agent-runs.jsonl").read_bytes()
    )
    for raw_line in ledger_bytes.splitlines():
        try:
            event = json.loads(raw_line)
        except (ValueError, TypeError) as exc:
            raise LifecycleError("WI-LEDGER-UNSETTLED", "archived ledger is malformed") from exc
        if isinstance(event, dict) and event.get("runId") == run_id:
            matches.append((_sha256_bytes(raw_line), event))
    if len(matches) != 1 or matches[0][1].get("eventKind") != "terminal":
        raise LifecycleError("WI-SCRATCH-RELEASE-IDENTITY", "one exact terminal event is required")
    entries = matches[0][1].get("scratchEvidence", [])
    selected = [entry for entry in entries if isinstance(entry, dict) and entry.get("entryId") == entry_id]
    if len(selected) != 1 or selected[0].get("disposition") != "retain":
        raise LifecycleError("WI-SCRATCH-RELEASE-IDENTITY", "one exact retained entry is required")
    if event_out is not None:
        event_out.append(matches[0][1])
    return matches[0][0], selected[0]


def _release_artifact_snapshot(
    item: Path, artifact: str, *, retained_inputs: list[CapturedFileSnapshot] | None = None,
) -> str:
    relative = PurePosixPath(artifact)
    if (
        not artifact or relative.is_absolute() or Path(artifact).drive or "\\" in artifact
        or any(part in {"", ".", ".."} for part in relative.parts)
        or relative.parts[0] == "retained-scratch-releases"
    ):
        raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "canonical artifact path is unsafe")
    path = item.joinpath(*relative.parts)
    _lifecycle_reject_unreduced_reparse(
        path, failure_id="WI-SCRATCH-RELEASE-EVIDENCE",
        message="canonical artifact crosses a link or reparse point",
    )
    if not path.is_file():
        raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "canonical artifact is missing")
    snapshot = _capture_file_snapshot(
        path, failure_id="WI-SCRATCH-RELEASE-EVIDENCE", require_single_link=True,
    )
    if retained_inputs is not None:
        retained_inputs.append(snapshot)
    return _sha256_bytes(snapshot.data)


_PRIOR_DISPOSAL_MODE = "accepted-prior-disposal"
_PRIOR_DISPOSAL_SUBJECT_FIELDS = frozenset({
    "runId", "entryId", "eventSha256", "sourcePath", "canonicalPointer",
    "canonicalPointerSha256", "actionEvidence", "admissionEvidence", "rationale",
})
_PRIOR_DISPOSAL_RECEIPT_FIELDS = _PRIOR_DISPOSAL_SUBJECT_FIELDS | {
    "schemaVersion", "mode", "workItem", "entrySha256", "recordedAt",
    "evidenceScope", "rawRecovery",
}


def _prior_disposal_absence(root: Path, item: Path, receipt: dict) -> None:
    original = root / Path(receipt["sourcePath"])
    tombstone = _scratch_tombstone(original, item.name, receipt["runId"], receipt["entryId"])
    classifier = _scratch_classifier_module()
    for candidate in (original, tombstone):
        _lifecycle_reject_unreduced_reparse(
            candidate, failure_id="WI-SCRATCH-RECONCILIATION-DRIFT",
            message="completed disposal crosses a link or reparse point",
        )
        try:
            observed = classifier.inspect_root_no_follow(candidate)
        except classifier.OwnedTreeClassificationError as exc:
            raise LifecycleError("WI-SCRATCH-RECONCILIATION-DRIFT", str(exc)) from exc
        if observed.exists:
            raise LifecycleError(
                "WI-SCRATCH-RECONCILIATION-DRIFT",
                "completed-disposal original or tombstone is present",
            )


def _validate_prior_disposal_receipt(
    root: Path, item: Path, run_id: str, entry_id: str, entry: dict, receipt: dict,
    *, retained_inputs: list[CapturedFileSnapshot] | None = None,
) -> None:
    """Bind reviewed caller data, not the semantic truth of arbitrary Markdown."""
    validator = _validator_module()
    if (
        type(receipt) is not dict or set(receipt) != _PRIOR_DISPOSAL_RECEIPT_FIELDS
        or type(receipt["schemaVersion"]) is not int or receipt["schemaVersion"] != 2
        or receipt["mode"] != _PRIOR_DISPOSAL_MODE or receipt["workItem"] != item.name
        or receipt["runId"] != run_id or receipt["entryId"] != entry_id
        or receipt["evidenceScope"] != "canonical-observations"
        or receipt["rawRecovery"] != "not-certified"
    ):
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-RECEIPT", "completed-disposal receipt shape differs")
    events: list[dict] = []
    event_hash, bound_entry = _release_event_binding(item, run_id, entry_id, event_out=events)
    event = events[0]
    errors: list[str] = []
    artifact_path = item / event["artifact"] if isinstance(event.get("artifact"), str) else None
    validator.validate_scratch_evidence(event, item, artifact_path, run_id, errors)
    if errors:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-IDENTITY", "; ".join(errors))
    entry_hash = _sha256_bytes(json.dumps(bound_entry, sort_keys=True, separators=(",", ":")).encode("utf-8"))
    if (
        bound_entry != entry or receipt["eventSha256"] != event_hash
        or receipt["entrySha256"] != entry_hash or receipt["sourcePath"] != entry["path"]
        or receipt["sourcePath"] != f".scratch/work-items/{item.name}/{run_id}/{entry_id}"
        or receipt["canonicalPointer"] != entry["canonicalPointer"]
    ):
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-IDENTITY", "completed-disposal subject differs")
    for name in ("eventSha256", "entrySha256", "canonicalPointerSha256"):
        if not isinstance(receipt[name], str) or SHA256_RE.fullmatch(receipt[name]) is None:
            raise LifecycleError("WI-SCRATCH-RECONCILIATION-RECEIPT", "completed-disposal digest is invalid")
    rationale = receipt["rationale"]
    if not isinstance(rationale, str) or not rationale.strip() or len(rationale) > validator.MAX_SCRATCH_REASON_LENGTH:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-EVIDENCE", "reviewed disposition rationale is required")
    try:
        recorded = _strict_utc(receipt["recordedAt"])
    except (LifecycleError, TypeError) as exc:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-EVIDENCE", "recording time is invalid") from exc
    actions = receipt["actionEvidence"]
    admission = receipt["admissionEvidence"]
    if (
        type(actions) is not list or not actions or len(actions) > validator.MAX_SCRATCH_EVIDENCE_ENTRIES
        or any(type(row) is not dict or set(row) != {"artifact", "sha256", "actionFrom", "actionThrough"} for row in actions)
        or type(admission) is not dict or set(admission) != {"artifact", "sha256"}
    ):
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-EVIDENCE", "reviewed action and admission references are required")
    references = [(receipt["canonicalPointer"], receipt["canonicalPointerSha256"])]
    for row in (*actions, admission):
        if (
            not isinstance(row["artifact"], str) or not row["artifact"]
            or len(row["artifact"]) > validator.MAX_SCRATCH_POINTER_LENGTH
            or not isinstance(row["sha256"], str) or SHA256_RE.fullmatch(row["sha256"]) is None
        ):
            raise LifecycleError("WI-SCRATCH-RECONCILIATION-EVIDENCE", "evidence reference is invalid")
        references.append((row["artifact"], row["sha256"]))
    for row in actions:
        try:
            action_from = _strict_utc(row["actionFrom"])
            action_through = _strict_utc(row["actionThrough"])
        except (LifecycleError, TypeError) as exc:
            raise LifecycleError("WI-SCRATCH-RECONCILIATION-EVIDENCE", "past action time is invalid") from exc
        if not action_from <= action_through < recorded:
            raise LifecycleError("WI-SCRATCH-RECONCILIATION-EVIDENCE", "recording time must follow the completed action")
    for artifact, expected_hash in references:
        if _release_artifact_snapshot(item, artifact, retained_inputs=retained_inputs) != expected_hash:
            raise LifecycleError("WI-SCRATCH-RECONCILIATION-EVIDENCE", "reviewed evidence bytes differ")
    _prior_disposal_absence(root, item, receipt)


def _release_inventory(
    root: Path, source: Path, original: Path, *, verify_link_targets: bool,
) -> tuple[dict[str, str], ...]:
    classifier = _scratch_classifier_module()
    try:
        return classifier.snapshot_release_tree(
            Path(os.path.abspath(source)), Path(os.path.abspath(root)),
            original_root=Path(os.path.abspath(original)),
            verify_link_targets=verify_link_targets,
        )
    except (OSError, classifier.OwnedTreeClassificationError) as exc:
        raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", str(exc)) from exc


def _assign_release_target_custody(
    root: Path, item: Path, rows: tuple[dict, ...], artifact_sha256: str,
) -> tuple[dict, ...]:
    assigned: list[dict] = []
    for row in rows:
        bound = dict(row)
        if row["kind"] == "symlink":
            if row["targetKind"] == "absent":
                bound["targetCustody"] = "no-content"
            elif row["targetClass"] == "inside-root":
                bound["targetCustody"] = "accepted-rationale"
            else:
                target = root / Path(row["targetPath"])
                if item in target.parents:
                    bound["targetCustody"] = "archive-target"
                elif row["targetKind"] == "file" and row["targetSha256"] == artifact_sha256:
                    bound["targetCustody"] = "artifact"
                else:
                    raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "repository link target lacks durable custody")
        assigned.append(bound)
    return tuple(assigned)


def _verify_release_targets(
    root: Path, item: Path, source: Path, rows: tuple[dict, ...], artifact_sha256: str,
    *, surviving_root: Path | None = None,
) -> None:
    classifier = _scratch_classifier_module()
    saved = {row["path"]: row for row in rows}
    for row in rows:
        if row["kind"] != "symlink":
            continue
        target = root / Path(row["targetPath"])
        inside = target == source or source in target.parents
        if ("inside-root" if inside else "repository") != row["targetClass"]:
            raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "link target class differs from source root")
        if row["targetKind"] == "absent":
            if row["targetCustody"] != "no-content" or "targetSha256" in row:
                raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "absent target custody differs")
            if inside and target.relative_to(source).as_posix() in saved:
                raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "absent target contradicts release inventory")
            targets = [target]
            if inside and surviving_root is not None:
                targets.append(surviving_root / target.relative_to(source))
            try:
                if not all(classifier.release_target_absent(candidate, root) for candidate in targets):
                    raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "absent link target became live")
            except (OSError, classifier.OwnedTreeClassificationError) as exc:
                raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "absent link target cannot be proven") from exc
            continue
        if inside:
            if row["targetCustody"] != "accepted-rationale":
                raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "inside-root target custody differs")
            relative = target.relative_to(source).as_posix()
            target_row = saved.get(relative)
            if target_row is None or target_row["kind"] != row["targetKind"]:
                raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "inside-root target is absent from release inventory")
            if row["targetKind"] == "file":
                digest = target_row["sha256"]
            else:
                prefix = "" if relative == "." else f"{relative}/"
                subtree = []
                for candidate in rows:
                    path = candidate["path"]
                    if path == relative or (prefix and path.startswith(prefix)) or relative == ".":
                        if candidate["kind"] == "symlink":
                            raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "inside-root target directory contains a link")
                        subtree.append({
                            **candidate,
                            "path": "." if path == relative else path[len(prefix):],
                        })
                digest = _sha256_bytes(json.dumps(
                    sorted(subtree, key=lambda candidate: candidate["path"]),
                    sort_keys=True, separators=(",", ":"),
                ).encode("utf-8"))
            if digest != row["targetSha256"]:
                raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "inside-root target digest differs from release inventory")
            continue
        if row["targetCustody"] == "artifact":
            if row["targetKind"] != "file" or row["targetSha256"] != artifact_sha256:
                raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "promoted target differs from artifact")
            continue
        if row["targetCustody"] != "archive-target" or target == item or item not in target.parents:
            raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "repository link target lacks archive custody")
        _lifecycle_reject_unreduced_reparse(
            target, failure_id="WI-SCRATCH-RELEASE-EVIDENCE",
            message="repository link target crosses a link or reparse point",
        )
        try:
            kind, digest = classifier.release_target_digest(target, root)
        except (OSError, classifier.OwnedTreeClassificationError) as exc:
            raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "retained repository target is unsafe") from exc
        if kind != row["targetKind"] or digest != row["targetSha256"]:
            raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "retained repository target changed")


def _valid_release_inventory_rows(rows: object) -> bool:
    if not isinstance(rows, list) or not rows or len(rows) > _scratch_classifier_module().MAX_OWNED_TREE_ENTRIES:
        return False
    seen: set[str] = set()
    kinds: dict[str, str] = {}
    for row in rows:
        if not isinstance(row, dict) or not isinstance(row.get("path"), str):
            return False
        path = row["path"]
        parts = PurePosixPath(path).parts
        if (
            path in seen or "\\" in path or Path(path).drive or (path != "." and (
                not parts or PurePosixPath(path).is_absolute()
                or PurePosixPath(path).as_posix() != path
                or any(part in {"", ".", ".."} for part in parts)
            ))
        ):
            return False
        seen.add(path)
        kind = row.get("kind")
        if kind == "directory":
            if set(row) != {"path", "kind"}:
                return False
        elif kind == "file":
            if set(row) != {"path", "kind", "sha256"} or not isinstance(row.get("sha256"), str) or SHA256_RE.fullmatch(row["sha256"]) is None:
                return False
        elif kind == "symlink":
            absent = row.get("targetKind") == "absent"
            expected_keys = {"path", "kind", "rawTargetSha256", "targetPath", "targetClass", "targetKind", "targetCustody"}
            if not absent:
                expected_keys.add("targetSha256")
            if (
                path == "." or set(row) != expected_keys
                or any(not isinstance(row.get(key), str) or SHA256_RE.fullmatch(row[key]) is None for key in (("rawTargetSha256",) if absent else ("rawTargetSha256", "targetSha256")))
                or row.get("targetClass") not in {"inside-root", "repository"}
                or row.get("targetKind") not in {"file", "directory", "absent"}
                or row.get("targetCustody") not in ({"no-content"} if absent else {"accepted-rationale", "archive-target", "artifact"})
                or not isinstance(row.get("targetPath"), str)
            ):
                return False
            target_path = PurePosixPath(row["targetPath"])
            if (
                not target_path.parts or target_path.is_absolute() or Path(row["targetPath"]).drive
                or "\\" in row["targetPath"]
                or target_path.as_posix() != row["targetPath"]
                or any(part in {"", ".", ".."} for part in target_path.parts)
            ):
                return False
        else:
            return False
        kinds[path] = kind
    if rows[0]["path"] != "." or kinds["."] not in {"file", "directory"}:
        return False
    if kinds["."] == "file" and len(rows) != 1:
        return False
    return all(path == "." or kinds.get(str(PurePosixPath(path).parent)) == "directory" or (
        PurePosixPath(path).parent == PurePosixPath(".") and kinds["."] == "directory"
    ) for path in seen)


def _release_receipt(
    root: Path, item: Path, run_id: str, entry_id: str, entry: dict,
) -> dict | None:
    path = _release_receipt_path(item, run_id, entry_id)
    _lifecycle_reject_unreduced_reparse(
        path, failure_id="WI-SCRATCH-RELEASE-RECEIPT",
        message="release receipt crosses a link or reparse point",
    )
    if not path.exists():
        return None
    stage_prefix = f".{path.name}."
    try:
        with os.scandir(path.parent) as entries:
            stages = sorted(
                (Path(candidate.path) for candidate in entries
                 if candidate.name.startswith(stage_prefix) and candidate.name.endswith(".tmp")),
                key=lambda candidate: candidate.name,
            )
    except OSError as exc:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt staging cannot be inspected") from exc
    reconciliation_stage: Path | None = None
    if stages:
        if len(stages) != 1:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt has ambiguous staging")
        reconciliation_stage = stages[0]
        _lifecycle_reject_unreduced_reparse(
            reconciliation_stage, failure_id="WI-SCRATCH-RELEASE-RECEIPT",
            message="release receipt staging path is unsafe",
        )
        try:
            final_info = path.lstat()
            stage_info = reconciliation_stage.lstat()
        except OSError as exc:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt pair cannot be inspected") from exc
        if not (
            stat.S_ISREG(final_info.st_mode) and stat.S_ISREG(stage_info.st_mode)
            and final_info.st_nlink == stage_info.st_nlink == 2
            and (final_info.st_dev, final_info.st_ino)
            == (stage_info.st_dev, stage_info.st_ino)
        ):
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt stage is not its sole hard link")
        raw = _capture_file_snapshot(
            path, failure_id="WI-SCRATCH-RELEASE-RECEIPT",
        ).data
        if _capture_file_snapshot(
            reconciliation_stage, failure_id="WI-SCRATCH-RELEASE-RECEIPT",
        ).data != raw:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt stage bytes differ")
    else:
        raw = _capture_file_snapshot(
            path, failure_id="WI-SCRATCH-RELEASE-RECEIPT", require_single_link=True,
        ).data
    try:
        receipt = json.loads(raw)
    except (TypeError, ValueError) as exc:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt is malformed") from exc
    if isinstance(receipt, dict) and receipt.get("schemaVersion") == 2:
        try:
            receipt = _validator_module().decode_json_object(raw.decode("utf-8"), source="completed-disposal receipt")
        except ValueError as exc:
            raise LifecycleError("WI-SCRATCH-RECONCILIATION-RECEIPT", "completed-disposal receipt is malformed") from exc
        _validate_prior_disposal_receipt(root, item, run_id, entry_id, entry, receipt)
    else:
        event_hash, bound_entry = _release_event_binding(item, run_id, entry_id)
        expected_keys = {
            "schemaVersion", "archive", "runId", "entryId", "eventSha256", "entrySha256",
            "sourcePath", "artifact", "artifactSha256", "rationale", "inventory", "inventorySha256",
        }
        if not isinstance(receipt, dict) or set(receipt) != expected_keys:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt shape differs")
        rows = receipt["inventory"]
        try:
            valid_rows = _valid_release_inventory_rows(rows)
            digest = _sha256_bytes(json.dumps(rows, sort_keys=True, separators=(",", ":")).encode("utf-8")) if valid_rows else ""
        except (TypeError, ValueError, KeyError):
            valid_rows, digest = False, ""
        if not valid_rows or digest != receipt["inventorySha256"]:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release inventory is malformed")
        archive_relative = item.relative_to(root).as_posix()
        entry_hash = _sha256_bytes(json.dumps(bound_entry, sort_keys=True, separators=(",", ":")).encode("utf-8"))
        if (
            item.parent.parent != _work_items_root(root) / "archive"
            or receipt["schemaVersion"] != 1 or receipt["archive"] != archive_relative
            or receipt["runId"] != run_id or receipt["entryId"] != entry_id
            or receipt["eventSha256"] != event_hash or receipt["entrySha256"] != entry_hash
            or receipt["sourcePath"] != entry["path"]
            or not isinstance(receipt["rationale"], str) or not receipt["rationale"].strip()
            or not isinstance(receipt["artifact"], str)
            or receipt["artifactSha256"] != _release_artifact_snapshot(item, receipt["artifact"])
        ):
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release identity or evidence differs")
        _verify_release_targets(root, item, root / Path(entry["path"]), tuple(rows), receipt["artifactSha256"])
    if reconciliation_stage is not None:
        try:
            rebound_final = path.lstat()
            rebound_stage = reconciliation_stage.lstat()
            if not (
                rebound_final.st_nlink == rebound_stage.st_nlink == 2
                and (rebound_final.st_dev, rebound_final.st_ino)
                == (rebound_stage.st_dev, rebound_stage.st_ino)
                == (final_info.st_dev, final_info.st_ino)
            ):
                raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt pair changed before settlement")
            reconciliation_stage.unlink()
        except OSError as exc:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt stage cannot be settled") from exc
        if _capture_file_snapshot(
            path, failure_id="WI-SCRATCH-RELEASE-RECEIPT", require_single_link=True,
        ).data != raw:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt changed after stage settlement")
    return receipt


def _release_rows_match(actual: tuple[dict, ...], expected: tuple[dict, ...], *, subset: bool) -> bool:
    original = {row["path"]: row for row in expected}
    if not subset and len(actual) != len(expected):
        return False
    for row in actual:
        reference = original.get(row["path"])
        if reference is None:
            return False
        if row["kind"] == "symlink":
            reference = {key: value for key, value in reference.items() if key not in {"targetSha256", "targetKind", "targetCustody"}}
        if row != reference:
            return False
    return True


def _scratch_ledger_entries(item: Path) -> list[tuple[str, dict]]:
    validator = _validator_module()
    errors: list[str] = []
    raw_metadata: list[dict[str, object]] = []
    events = validator.load_jsonl(item / "agent-runs.jsonl", errors, raw_metadata)
    effective_events, _migration_counts, projection_errors = validator.project_legacy_obligation_migrations(
        events, raw_metadata, item
    )
    errors.extend(projection_errors)
    for event in effective_events:
        entries = event.get("scratchEvidence")
        if entries is not None and (
            not isinstance(entries, list) or any(not isinstance(entry, dict) for entry in entries)
        ):
            errors.append(f"{event.get('runId')}: scratchEvidence must be a list of objects")
    validator.validate_scratch_ownership(effective_events, item, errors)
    if errors:
        raise LifecycleError("WI-LEDGER-UNSETTLED", "; ".join(errors))
    return [(event["runId"], entry) for event in effective_events for entry in event.get("scratchEvidence", [])]


def _scratch_disposition_plan(
    root: Path,
    item: Path,
    *,
    archived: bool,
    retention_paths: frozenset[Path] = frozenset(),
) -> tuple[ScratchDisposition, ...]:
    root = Path(os.path.abspath(root))
    ledger = item / "agent-runs.jsonl"
    owner_root = root / ".scratch" / "work-items" / item.name
    classifier = _scratch_classifier_module()
    try:
        owner_inspection = classifier.inspect_root_no_follow(owner_root)
    except classifier.OwnedTreeClassificationError as exc:
        raise LifecycleError("WI-SCRATCH-UNSAFE-ENTRY", str(exc)) from exc
    if not ledger.exists():
        if archived and retention_paths:
            return ()
        originals, tombstones = _scratch_namespace_entries(owner_root)
        if owner_inspection.exists and (set(originals) != set(retention_paths) or tombstones):
            raise LifecycleError(
                "WI-SCRATCH-OWNERSHIP-INCOMPLETE",
                "canonical scratch namespace exists without a terminal owner declaration",
            )
        return ()

    validator = _validator_module()
    recorded = _scratch_ledger_entries(item)
    if not recorded:
        originals, tombstones = _scratch_namespace_entries(owner_root)
        if owner_inspection.exists and (set(originals) != set(retention_paths) or tombstones):
            raise LifecycleError(
                "WI-SCRATCH-OWNERSHIP-INCOMPLETE",
                "canonical scratch namespace exists without a terminal owner declaration",
            )
        return ()

    originals_present, tombstones_present = _scratch_namespace_entries(owner_root)
    expected_originals: set[Path] = set()
    expected_tombstones: set[Path] = set()
    plans: list[ScratchDisposition] = []
    for run_id, entry in recorded:
        original = root / Path(entry["path"])
        tombstone = _scratch_tombstone(original, item.name, run_id, entry["entryId"])
        expected_originals.add(original)
        expected_tombstones.add(tombstone)
        original_exists = original in originals_present
        tombstone_exists = tombstone in tombstones_present
        if original_exists and tombstone_exists:
            raise LifecycleError(
                "WI-SCRATCH-DISPOSITION-CONFLICT",
                f"both original and tombstone exist for {entry['path']}",
            )
        release_receipt = (
            _release_receipt(root, item, run_id, entry["entryId"], entry)
            if entry["disposition"] == "retain" else None
        )
        if entry["disposition"] == "retain" and release_receipt is None and (tombstone_exists or not original_exists):
            raise LifecycleError(
                "WI-SCRATCH-RETAINED-EVIDENCE-MISSING",
                f"retained scratch evidence is missing or tombstoned: {entry['path']}",
            )
        if not original_exists and not tombstone_exists:
            if not archived and release_receipt is None:
                raise LifecycleError(
                    "WI-SCRATCH-OWNERSHIP-INCOMPLETE",
                    f"declared scratch evidence is missing: {entry['path']}",
                )
            if entry["disposition"] == "delete":
                continue
        pointer_errors: list[str] = []
        pointer = validator.resolve_scratch_pointer(
            item,
            entry["canonicalPointer"],
            "scratchEvidence.canonicalPointer",
            run_id,
            pointer_errors,
        )
        if pointer is None or pointer_errors:
            raise LifecycleError(
                "WI-SCRATCH-POINTER-OUTSIDE-ITEM",
                "; ".join(pointer_errors) or "missing canonical pointer",
            )
        if release_receipt is not None:
            if release_receipt["schemaVersion"] == 1:
                expected_rows = tuple(release_receipt["inventory"])
                if original_exists or tombstone_exists:
                    source = tombstone if tombstone_exists else original
                    actual_rows = _release_inventory(root, source, original, verify_link_targets=False)
                    if not _release_rows_match(actual_rows, expected_rows, subset=tombstone_exists):
                        raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "release source differs from bound inventory")
            snapshot = None
            proof = None
        elif entry["disposition"] == "retain":
            try:
                retained = classifier.inspect_root_no_follow(original)
            except classifier.OwnedTreeClassificationError as exc:
                raise LifecycleError("WI-SCRATCH-RETAINED-EVIDENCE-MISSING", str(exc)) from exc
            if (
                not retained.exists
                or retained.is_link_or_reparse
                or not (retained.is_directory or retained.is_regular_file)
            ):
                raise LifecycleError(
                    "WI-SCRATCH-RETAINED-EVIDENCE-MISSING",
                    f"retained scratch root is unavailable: {entry['path']}",
                )
            snapshot = None
            proof = None
        else:
            source = tombstone if tombstone_exists else original
            snapshot = _classify_scratch_entry(classifier, source, root)
            proof = entry["proof"]
            _verify_scratch_proof(snapshot, proof, pointer)
        plans.append(
            ScratchDisposition(
                original=original,
                tombstone=tombstone,
                disposition=(
                    "completed-disposal" if release_receipt is not None and release_receipt["schemaVersion"] == 2
                    else "release" if release_receipt is not None else entry["disposition"]
                ),
                proof=proof,
                canonical_pointer=pointer,
                snapshot=snapshot,
                release_receipt=release_receipt,
            )
        )

    if retention_paths & expected_originals:
        raise LifecycleError(
            "WI-SCRATCH-OWNERSHIP-INCOMPLETE",
            "declared scratch evidence cannot also be retained by close",
        )
    if (
        originals_present - expected_originals - set(retention_paths)
        or tombstones_present - expected_tombstones
    ):
        raise LifecycleError(
            "WI-SCRATCH-OWNERSHIP-INCOMPLETE",
            "scratch namespace contains an undeclared evidence root",
        )
    return tuple(plans)


def _unlink_owned_scratch_file(path: Path) -> None:
    """Unlink an owned leaf; retry only a proven Windows ReadOnly failure."""
    before = path.lstat()
    readonly = getattr(stat, "FILE_ATTRIBUTE_READONLY", 1)
    eligible = (
        os.name == "nt" and stat.S_ISREG(before.st_mode) and before.st_nlink == 1
        and bool(getattr(before, "st_file_attributes", 0) & readonly)
        and not bool(getattr(before, "st_file_attributes", 0) & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400))
    )
    snapshot = _capture_file_snapshot(
        path, failure_id="WI-SCRATCH-DISPOSITION-PENDING", require_single_link=True,
        maximum_bytes=_scratch_classifier_module().MAX_OWNED_TREE_BYTES,
    ) if eligible else None
    try:
        path.unlink()
    except PermissionError as denied:
        if snapshot is None:
            raise
        current = _capture_file_snapshot(
            path, failure_id="WI-SCRATCH-DISPOSITION-PENDING", require_single_link=True,
            maximum_bytes=snapshot.length,
        )
        if current != snapshot or _lifecycle_file_snapshot_key(path.lstat()) != _lifecycle_file_snapshot_key(before):
            raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "ReadOnly leaf changed before retry") from denied
        path.chmod(before.st_mode | stat.S_IWRITE, follow_symlinks=False)
        try:
            current = _capture_file_snapshot(
                path, failure_id="WI-SCRATCH-DISPOSITION-PENDING", require_single_link=True,
                maximum_bytes=snapshot.length,
            )
            after = path.lstat()
            if (
                current != snapshot or after.st_mtime_ns != before.st_mtime_ns
                or after.st_file_attributes != (before.st_file_attributes & ~readonly)
            ):
                raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "ReadOnly leaf changed after attribute update")
            path.unlink()
        except (OSError, LifecycleError) as retry_failure:
            try:
                current = _capture_file_snapshot(
                    path, failure_id="WI-SCRATCH-DISPOSITION-PENDING", require_single_link=True,
                    maximum_bytes=snapshot.length,
                )
                restoring = path.lstat()
                if (
                    current != snapshot or restoring.st_mtime_ns != before.st_mtime_ns
                    or (restoring.st_file_attributes & ~readonly) != (before.st_file_attributes & ~readonly)
                ):
                    raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "ReadOnly leaf changed before restoration")
                path.chmod(before.st_mode, follow_symlinks=False)
                _verify_captured_file(snapshot, "WI-SCRATCH-DISPOSITION-PENDING")
                if path.lstat().st_file_attributes != before.st_file_attributes:
                    raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "ReadOnly attribute restoration differs")
            except (OSError, LifecycleError) as restore_failure:
                raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", f"ReadOnly restoration refused: {restore_failure}") from retry_failure
            raise retry_failure from denied


def _remove_scratch_tree(tree_root: Path) -> None:
    """Remove one already-proven tree without following links or reparses."""

    classifier = _scratch_classifier_module()
    directories: list[Path] = []
    stack = [tree_root]
    while stack:
        directory = stack.pop()
        inspection = classifier.inspect_root_no_follow(directory)
        if not inspection.exists or inspection.is_link_or_reparse or not inspection.is_directory:
            raise OSError(f"unsafe directory during removal: {directory.name}")
        directories.append(directory)
        with os.scandir(directory) as entries:
            children = list(entries)
        for entry in children:
            child = classifier.inspect_root_no_follow(Path(entry.path))
            if child.is_link_or_reparse:
                raise OSError(f"unsafe link or reparse during removal: {entry.name}")
            if child.is_directory:
                stack.append(Path(entry.path))
            elif child.exists and stat.S_ISREG(os.lstat(entry.path).st_mode):
                _unlink_owned_scratch_file(Path(entry.path))
            else:
                raise OSError(f"unsafe non-regular entry during removal: {entry.name}")
    for directory in reversed(directories):
        directory.rmdir()


def _settle_released_scratch(
    root: Path, plan: ScratchDisposition, *, inject_failure_at: str | None = None,
) -> None:
    """Resume one receipt-bound removal; never walk a symbolic-link target."""
    root = Path(os.path.abspath(root))
    receipt = plan.release_receipt
    assert receipt is not None
    item = root / Path(receipt["archive"])
    _event_hash, entry = _release_event_binding(item, receipt["runId"], receipt["entryId"])
    checked = _release_receipt(root, item, receipt["runId"], receipt["entryId"], entry)
    if checked != receipt:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt changed after preflight")
    classifier = _scratch_classifier_module()
    original = classifier.inspect_root_no_follow(plan.original)
    tombstone = classifier.inspect_root_no_follow(plan.tombstone)
    if original.exists and tombstone.exists:
        raise LifecycleError("WI-SCRATCH-DISPOSITION-CONFLICT", "both release source and tombstone exist")
    if not original.exists and not tombstone.exists:
        return
    expected = tuple(receipt["inventory"])
    source = plan.tombstone if tombstone.exists else plan.original
    actual = _release_inventory(root, source, plan.original, verify_link_targets=False)
    if not _release_rows_match(actual, expected, subset=tombstone.exists):
        raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "release source differs before removal")
    if original.exists:
        rebound = classifier.inspect_root_no_follow(plan.original)
        if rebound != original or rebound.is_link_or_reparse:
            raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "release root identity changed before rename")
        (_replace_lifecycle_directory(plan.original, plan.tombstone) if rebound.is_directory else _replace_lifecycle_directory(plan.original, plan.tombstone, directory=False))
        if inject_failure_at == "after-rename":
            raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "injected after-rename")
    actual = _release_inventory(root, plan.tombstone, plan.original, verify_link_targets=False)
    if not _release_rows_match(actual, expected, subset=True):
        raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "release tombstone differs after rename")
    remaining = {row["path"] for row in actual}
    file_unlinked = False
    link_unlinked = False
    for row in sorted(expected, key=lambda candidate: (candidate["kind"] != "symlink", -len(PurePosixPath(candidate["path"]).parts), candidate["path"])):
        relative = row["path"]
        if relative not in remaining or row["kind"] == "directory":
            continue
        target = plan.tombstone if relative == "." else plan.tombstone / Path(relative)
        logical = plan.original if relative == "." else plan.original / Path(relative)
        _lifecycle_reject_unreduced_reparse(
            target.parent, failure_id="WI-SCRATCH-RELEASE-DRIFT",
            message="release descendant parent became a link or reparse point",
        )
        before = classifier.inspect_root_no_follow(target)
        current = _release_inventory(root, target, logical, verify_link_targets=False)
        expected_leaf = {key: value for key, value in row.items() if key not in {"targetSha256", "targetClass", "targetKind", "targetCustody"}}
        expected_leaf["path"] = "."
        if len(current) != 1 or {
            key: value for key, value in current[0].items() if key != "targetClass"
        } != expected_leaf:
            raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "release descendant changed before unlink")
        after = classifier.inspect_root_no_follow(target)
        if after != before or (row["kind"] == "symlink") != after.is_link_or_reparse:
            raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "release descendant identity changed before unlink")
        if row["kind"] == "symlink":
            if row["targetKind"] == "absent":
                _verify_release_targets(
                    root, item, plan.original, (row,), receipt["artifactSha256"],
                    surviving_root=plan.tombstone,
                )
            target.unlink()
        else:
            _unlink_owned_scratch_file(target)
        if row["kind"] == "symlink" and not link_unlinked:
            link_unlinked = True
            if inject_failure_at == "after-first-link-unlink":
                raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "injected after-first-link-unlink")
        if row["kind"] == "file" and not file_unlinked:
            file_unlinked = True
            if inject_failure_at == "after-first-file-unlink":
                raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "injected after-first-file-unlink")
    for row in sorted(expected, key=lambda candidate: (-len(PurePosixPath(candidate["path"]).parts), candidate["path"])):
        if row["kind"] != "directory" or row["path"] not in remaining:
            continue
        target = plan.tombstone if row["path"] == "." else plan.tombstone / Path(row["path"])
        inspection = classifier.inspect_root_no_follow(target)
        if not inspection.exists or inspection.is_link_or_reparse or not inspection.is_directory:
            raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "release directory changed before removal")
        target.rmdir()
    if inject_failure_at == "after-final-removal":
        raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "injected after-final-removal")


def _recheck_completed_disposal(root: Path, plan: ScratchDisposition) -> None:
    receipt = plan.release_receipt
    if receipt is None or receipt.get("schemaVersion") != 2:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-RECEIPT", "completed-disposal plan has no V2 receipt")
    locations = _category_locations(root, CATEGORIES["work-item"], receipt["workItem"])
    if len(locations) != 1:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-IDENTITY", "completed-disposal item is not unique")
    item = locations[0]
    _event_hash, entry = _release_event_binding(item, receipt["runId"], receipt["entryId"])
    if _release_receipt(root, item, receipt["runId"], receipt["entryId"], entry) != receipt:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-DRIFT", "completed-disposal receipt changed after preflight")


def _settle_scratch_dispositions(root: Path, plans: tuple[ScratchDisposition, ...]) -> None:
    classifier = _scratch_classifier_module()
    for plan in plans:
        if plan.disposition == "retain":
            continue
        if plan.disposition == "completed-disposal":
            _recheck_completed_disposal(root, plan)
            continue
        if plan.disposition == "release":
            try:
                _settle_released_scratch(root, plan)
            except LifecycleError:
                raise
            except (OSError, classifier.OwnedTreeClassificationError) as exc:
                raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", str(exc)) from exc
            continue
        try:
            original_state = classifier.inspect_root_no_follow(plan.original)
            tombstone_state = classifier.inspect_root_no_follow(plan.tombstone)
        except classifier.OwnedTreeClassificationError as exc:
            raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", str(exc)) from exc
        if original_state.exists and tombstone_state.exists:
            raise LifecycleError(
                "WI-SCRATCH-DISPOSITION-CONFLICT", "both original and tombstone exist"
            )
        source = plan.tombstone if tombstone_state.exists else plan.original
        source_state = tombstone_state if tombstone_state.exists else original_state
        if not source_state.exists:
            continue
        if source_state.is_link_or_reparse or not source_state.is_directory:
            raise LifecycleError(
                "WI-SCRATCH-DISPOSITION-PENDING",
                "scratch root changed to an unsafe identity after preflight",
            )
        try:
            snapshot = classifier.classify_owned_tree(source, root)
            if plan.snapshot is None or not classifier.identity_matches(snapshot, plan.snapshot):
                raise LifecycleError(
                    "WI-SCRATCH-DISPOSITION-PENDING", "scratch identity drifted after preflight"
                )
            canonical_pointer = _relocate_scratch_pointer(root, plan.canonical_pointer)
            assert plan.proof is not None
            _verify_scratch_proof(snapshot, plan.proof, canonical_pointer)
            if source == plan.original:
                _replace_lifecycle_directory(plan.original, plan.tombstone)
            tombstone_snapshot = classifier.classify_owned_tree(plan.tombstone, root)
            if not classifier.identity_matches(tombstone_snapshot, plan.snapshot):
                raise LifecycleError(
                    "WI-SCRATCH-DISPOSITION-PENDING", "scratch identity drifted after tombstone"
                )
            _verify_scratch_proof(tombstone_snapshot, plan.proof, canonical_pointer)
            _remove_scratch_tree(plan.tombstone)
        except LifecycleError:
            raise
        except (OSError, classifier.OwnedTreeClassificationError) as exc:
            raise LifecycleError(
                "WI-SCRATCH-DISPOSITION-PENDING",
                f"archived item retains retryable scratch disposition: {exc}",
            ) from exc


def _publish_release_receipt(
    path: Path, receipt_bytes: bytes,
    *, owned: list[tuple[Path, tuple[int, int], bytes]] | None = None,
) -> None:
    """Existing create-once metadata publication, shared by both receipt modes."""
    _lifecycle_reject_unreduced_reparse(
        path.parent, failure_id="WI-SCRATCH-RELEASE-RECEIPT",
        message="release receipt parent crosses a link or reparse point",
    )
    path.parent.mkdir(exist_ok=True)
    stage_prefix = f".{path.name}."
    try:
        with os.scandir(path.parent) as entries:
            prior_stages = sorted(
                (Path(entry.path) for entry in entries
                 if entry.name.startswith(stage_prefix) and entry.name.endswith(".tmp")),
                key=lambda candidate: candidate.name,
            )
        for stage in prior_stages:
            _lifecycle_reject_unreduced_reparse(
                stage, failure_id="WI-SCRATCH-RELEASE-RECEIPT",
                message="release receipt staging path is unsafe",
            )
            staged = _capture_file_snapshot(
                stage, failure_id="WI-SCRATCH-RELEASE-RECEIPT", require_single_link=True,
            ).data
            if staged != receipt_bytes:
                raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "unsettled release receipt staging bytes require review")
            stage.unlink()
    except OSError as exc:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt staging cannot be settled") from exc
    temporary: Path | None = None
    try:
        descriptor, name = tempfile.mkstemp(prefix=stage_prefix, suffix=".tmp", dir=path.parent)
        temporary = Path(name)
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(receipt_bytes)
            stream.flush()
            os.fsync(stream.fileno())
        identity = _lifecycle_file_identity(temporary.lstat())
        os.link(temporary, path)
        if owned is not None:
            owned.append((path, identity, receipt_bytes))
    except FileExistsError as exc:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt already exists") from exc
    except OSError as exc:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "atomic create-once release receipt is unavailable") from exc
    finally:
        if temporary is not None:
            try:
                temporary.unlink(missing_ok=True)
            except OSError as exc:
                raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt staging residue remains") from exc
    if _capture_file_snapshot(path, failure_id="WI-SCRATCH-RELEASE-RECEIPT", require_single_link=True).data != receipt_bytes:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt readback differs")


def reconcile_retained_scratch(
    root: Path, slug: str, request_file: Path, *, apply: bool = False,
) -> tuple[Path, ...]:
    """Record the trusted operator's reviewed past disposal; never remove payloads."""
    if not apply:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-APPLY-REQUIRED", "reconciliation requires explicit apply")
    _validate_slug(slug)
    return _reconcile_retained_scratch_transaction(root, slug, Path(request_file))


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def _reconcile_retained_scratch_transaction(root: Path, slug: str, request_file: Path) -> tuple[Path, ...]:
    root = Path(os.path.abspath(root))
    locations = _category_locations(root, CATEGORIES["work-item"], slug)
    work_items = _work_items_root(root)
    if (
        len(locations) != 1 or not locations[0].is_dir()
        or not (locations[0].parent == work_items / "active" or locations[0].parent.parent == work_items / "archive")
    ):
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-IDENTITY", "one unique active or archived item is required")
    item = locations[0]
    _lifecycle_reject_unreduced_reparse(item, failure_id="WI-SCRATCH-RECONCILIATION-IDENTITY", message="item path is unsafe")
    validator = _validator_module()
    ledger_owner = _agent_run_ledger_module()
    try:
        with ledger_owner.ledger_write_lock(item):
            request_snapshot = _capture_file_snapshot(
                Path(os.path.abspath(request_file)), failure_id="WI-SCRATCH-RECONCILIATION-REQUEST",
                maximum_bytes=validator.MAX_LEDGER_LINE_BYTES, require_single_link=True,
            )
            try:
                request = validator.decode_json_object(
                    request_snapshot.data.decode("utf-8"), source="retained scratch reconciliation request",
                    maximum_bytes=validator.MAX_LEDGER_LINE_BYTES,
                )
            except ValueError as exc:
                raise LifecycleError("WI-SCRATCH-RECONCILIATION-REQUEST", "request is not bounded strict UTF-8 JSON") from exc
            if (
                set(request) != {"schemaVersion", "mode", "workItem", "recordedAt", "subjects"}
                or type(request["schemaVersion"]) is not int or request["schemaVersion"] != 1
                or request["mode"] != _PRIOR_DISPOSAL_MODE or request["workItem"] != slug
                or type(request["subjects"]) is not list or not request["subjects"]
                or len(request["subjects"]) > validator.MAX_SCRATCH_EVIDENCE_ENTRIES
            ):
                raise LifecycleError("WI-SCRATCH-RECONCILIATION-REQUEST", "request shape differs")
            _capture_file_snapshot(
                item / "agent-runs.jsonl", failure_id="WI-SCRATCH-RECONCILIATION-IDENTITY",
                maximum_bytes=validator.MAX_TRANSFER_LEDGER_BYTES, require_single_link=True,
            )
            entries = {(run_id, entry["entryId"]): entry for run_id, entry in _scratch_ledger_entries(item)}
            retained_inputs = [request_snapshot]
            prepared: list[tuple[Path, dict, dict, bytes, bool]] = []
            selected: set[tuple[str, str]] = set()
            for subject in request["subjects"]:
                if type(subject) is not dict or set(subject) != _PRIOR_DISPOSAL_SUBJECT_FIELDS:
                    raise LifecycleError("WI-SCRATCH-RECONCILIATION-REQUEST", "subject shape differs")
                run_id, entry_id = subject["runId"], subject["entryId"]
                if (
                    not isinstance(run_id, str) or not isinstance(entry_id, str)
                    or len(run_id) > 128 or len(entry_id) > validator.MAX_SCRATCH_ENTRY_ID_LENGTH
                    or validator.SCRATCH_IDENTIFIER_RE.fullmatch(run_id) is None
                    or validator.SCRATCH_IDENTIFIER_RE.fullmatch(entry_id) is None
                    or (run_id.casefold(), entry_id.casefold()) in selected
                    or (run_id, entry_id) not in entries
                ):
                    raise LifecycleError("WI-SCRATCH-RECONCILIATION-IDENTITY", "subject selector is invalid, duplicate or unbound")
                selected.add((run_id.casefold(), entry_id.casefold()))
                entry = entries[(run_id, entry_id)]
                _event_hash, bound_entry = _release_event_binding(item, run_id, entry_id)
                receipt = {
                    **subject, "schemaVersion": 2, "mode": _PRIOR_DISPOSAL_MODE, "workItem": slug,
                    "entrySha256": _sha256_bytes(json.dumps(bound_entry, sort_keys=True, separators=(",", ":")).encode("utf-8")),
                    "recordedAt": request["recordedAt"], "evidenceScope": "canonical-observations",
                    "rawRecovery": "not-certified",
                }
                for name in ("eventSha256", "canonicalPointerSha256"):
                    receipt[name] = _normalize_sha256_input(receipt[name])
                if isinstance(receipt["actionEvidence"], list):
                    receipt["actionEvidence"] = [
                        {**row, "sha256": _normalize_sha256_input(row.get("sha256"))} if isinstance(row, dict) else row
                        for row in receipt["actionEvidence"]
                    ]
                if isinstance(receipt["admissionEvidence"], dict):
                    receipt["admissionEvidence"] = {
                        **receipt["admissionEvidence"], "sha256": _normalize_sha256_input(receipt["admissionEvidence"].get("sha256")),
                    }
                _validate_prior_disposal_receipt(root, item, run_id, entry_id, entry, receipt, retained_inputs=retained_inputs)
                path = _release_receipt_path(item, run_id, entry_id)
                existing = _release_receipt(root, item, run_id, entry_id, entry)
                if existing is not None and existing != receipt:
                    raise LifecycleError("WI-SCRATCH-RECONCILIATION-RECEIPT", "replay request differs from existing receipt")
                encoded = (json.dumps(receipt, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
                prepared.append((path, entry, receipt, encoded, existing is None))
            _verify_captured_file(request_snapshot, "WI-SCRATCH-RECONCILIATION-DRIFT")
            transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
            transaction.observe_retained_inputs(retained_inputs)
            transaction.verify()
            owned: list[tuple[Path, tuple[int, int], bytes]] = []
            parent = item / "retained-scratch-releases"
            created_parent = False
            try:
                if not parent.exists():
                    _lifecycle_reject_unreduced_reparse(parent, failure_id="WI-SCRATCH-RECONCILIATION-RECEIPT", message="receipt parent is unsafe")
                    parent.mkdir()
                    created_parent = True
                for path, entry, receipt, encoded, create in prepared:
                    _validate_prior_disposal_receipt(root, item, receipt["runId"], receipt["entryId"], entry, receipt)
                    if create:
                        _publish_release_receipt(path, encoded, owned=owned)
                for path, entry, receipt, _encoded, _create in prepared:
                    if _release_receipt(root, item, receipt["runId"], receipt["entryId"], entry) != receipt:
                        raise LifecycleError("WI-SCRATCH-RECONCILIATION-DRIFT", "published receipt readback differs")
                _verify_captured_file(request_snapshot, "WI-SCRATCH-RECONCILIATION-DRIFT")
                transaction.verify()
            except BaseException as primary:
                failures: list[str] = []
                for path, identity, encoded in reversed(owned):
                    try:
                        snapshot = _capture_file_snapshot(path, failure_id="WI-SCRATCH-RECONCILIATION-ROLLBACK")
                        if snapshot.identity != identity or snapshot.data != encoded:
                            raise LifecycleError("WI-SCRATCH-RECONCILIATION-ROLLBACK", "owned receipt changed")
                        path.unlink()
                    except (LifecycleError, OSError) as exc:
                        failures.append(str(exc))
                if created_parent:
                    try:
                        parent.rmdir()
                    except OSError as exc:
                        failures.append(str(exc))
                if failures:
                    raise LifecycleError("WI-SCRATCH-RECONCILIATION-ROLLBACK", "; ".join(failures)) from primary
                raise
            return tuple(row[0] for row in prepared)
    except ledger_owner.LedgerWriteLockError as exc:
        raise LifecycleError("WI-SCRATCH-RECONCILIATION-LOCK", "selected ledger lock is unavailable") from exc


def release_retained_scratch(
    root: Path,
    slug: str,
    *,
    terminal_run_id: str,
    expected_event_sha256: str,
    entry_id: str,
    artifact: str,
    rationale: str,
    apply: bool = False,
    inject_failure_at: str | None = None,
) -> Path:
    """Opt-in post-close release of one exact ledger-declared retained root."""
    if not apply:
        raise LifecycleError("WI-SCRATCH-RELEASE-APPLY-REQUIRED", "release requires explicit apply")
    _validate_slug(slug)
    return _release_retained_scratch_transaction(
        root, slug, terminal_run_id=terminal_run_id, expected_event_sha256=expected_event_sha256,
        entry_id=entry_id, artifact=artifact, rationale=rationale, inject_failure_at=inject_failure_at,
    )


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def _release_retained_scratch_transaction(
    root: Path, slug: str, *, terminal_run_id: str, expected_event_sha256: str,
    entry_id: str, artifact: str, rationale: str, inject_failure_at: str | None = None,
) -> Path:
    root = Path(os.path.abspath(root))
    locations = _category_locations(root, CATEGORIES["work-item"], slug)
    if len(locations) != 1 or "archive" not in locations[0].parts:
        raise LifecycleError("WI-SCRATCH-RELEASE-IDENTITY", "one exact archived item is required")
    item = locations[0]
    _archived_work_item_entry(item)
    event_hash, entry = _release_event_binding(item, terminal_run_id, entry_id)
    if expected_event_sha256 != event_hash:
        raise LifecycleError("WI-SCRATCH-RELEASE-IDENTITY", "terminal event digest differs")
    if not isinstance(rationale, str) or not rationale.strip():
        raise LifecycleError("WI-SCRATCH-RELEASE-EVIDENCE", "accepted-evidence rationale is required")
    artifact_hash = _release_artifact_snapshot(item, artifact)
    path = _release_receipt_path(item, terminal_run_id, entry_id)
    existing = _release_receipt(root, item, terminal_run_id, entry_id, entry)
    if existing is not None and existing["schemaVersion"] != 1:
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "live-inventory release requires a Version 1 receipt")
    if existing is None:
        plans = _scratch_disposition_plan(root, item, archived=True)
        selected = [plan for plan in plans if plan.original == root / Path(entry["path"])]
        if len(selected) != 1 or selected[0].disposition != "retain":
            raise LifecycleError("WI-SCRATCH-RELEASE-IDENTITY", "selected retained root is unavailable")
        source = selected[0].original
        inspection = _scratch_classifier_module().inspect_root_no_follow(source)
        if not inspection.exists or inspection.is_link_or_reparse or not (
            inspection.is_directory or inspection.is_regular_file
        ):
            raise LifecycleError("WI-SCRATCH-RELEASE-DRIFT", "selected root is not ordinary")
        rows = _assign_release_target_custody(
            root, item, _release_inventory(root, source, source, verify_link_targets=True), artifact_hash,
        )
        _verify_release_targets(root, item, source, rows, artifact_hash)
        entry_hash = _sha256_bytes(json.dumps(entry, sort_keys=True, separators=(",", ":")).encode("utf-8"))
        inventory = list(rows)
        receipt = {
            "schemaVersion": 1,
            "archive": item.relative_to(root).as_posix(),
            "runId": terminal_run_id,
            "entryId": entry_id,
            "eventSha256": event_hash,
            "entrySha256": entry_hash,
            "sourcePath": entry["path"],
            "artifact": artifact,
            "artifactSha256": artifact_hash,
            "rationale": rationale,
            "inventory": inventory,
            "inventorySha256": _sha256_bytes(json.dumps(inventory, sort_keys=True, separators=(",", ":")).encode("utf-8")),
        }
        try:
            receipt_bytes = (
                json.dumps(receipt, sort_keys=True, separators=(",", ":")) + "\n"
            ).encode("utf-8")
        except (OSError, TypeError, ValueError, UnicodeError) as exc:
            raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "release receipt cannot be serialized") from exc
        _publish_release_receipt(path, receipt_bytes)
        existing = _release_receipt(root, item, terminal_run_id, entry_id, entry)
    elif (
        existing["artifact"] != artifact or existing["artifactSha256"] != artifact_hash
        or existing["rationale"] != rationale
    ):
        raise LifecycleError("WI-SCRATCH-RELEASE-RECEIPT", "replay request differs from release receipt")
    if inject_failure_at == "after-receipt":
        raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", "injected after-receipt")
    plans = _scratch_disposition_plan(root, item, archived=True)
    selected = [plan for plan in plans if plan.original == root / Path(entry["path"])]
    if len(selected) != 1 or selected[0].disposition != "release":
        raise LifecycleError("WI-SCRATCH-RELEASE-IDENTITY", "selected receipt did not bind one root")
    try:
        _settle_released_scratch(root, selected[0], inject_failure_at=inject_failure_at)
    except LifecycleError:
        raise
    except (OSError, _scratch_classifier_module().OwnedTreeClassificationError) as exc:
        raise LifecycleError("WI-SCRATCH-DISPOSITION-PENDING", str(exc)) from exc
    return path


def _validate_item_before_close(item: Path) -> None:
    validator = _validator_module()
    ledger = item / "agent-runs.jsonl"
    status_text = (item / "status.md").read_text(encoding="utf-8")
    v1_staged = _parse_fields(status_text).get("template") == "staged"
    if ledger.exists():
        errors = validator.validate_work_item(
            item,
            validate_status_file=not v1_staged,
        )
        if v1_staged:
            _validate_active_status_bytes(status_text.encode("utf-8"))
    else:
        errors = []
        validator.validate_status(item, [], errors)
        if v1_staged:
            errors = []
            _validate_active_status_bytes(status_text.encode("utf-8"))
    if errors:
        raise LifecycleError("WI-LEDGER-UNSETTLED", "; ".join(errors))
    failure = _current_readme_status_error(_parse_fields(status_text), "active", item / "status.md")
    if failure is not None:
        raise failure


def _bug_disposition_fail(failure_id: str, message: str) -> LifecycleError:
    return LifecycleError(failure_id, message)


def _single_line_manifest_text(row: dict, key: str) -> str:
    value = row.get(key)
    if (
        not isinstance(value, str)
        or not value.strip()
        or len(value) > BUG_DISPOSITION_TEXT_LIMIT
        or "\n" in value
        or "\r" in value
    ):
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID",
            f"bug disposition {key} must be one non-empty bounded line",
        )
    return value.strip()


def _load_bug_disposition_manifest(
    item: Path,
    slug: str,
    terminal_instant: str,
    *, manifest_snapshot=None,
) -> tuple[Path, bytes, dict]:
    manifest = manifest_snapshot.path if manifest_snapshot is not None else item / BUG_DISPOSITIONS_MANIFEST
    if manifest.is_symlink() or not manifest.is_file():
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-MISSING",
            f"active work-item requires {BUG_DISPOSITIONS_MANIFEST}: {slug}",
        )
    try:
        if manifest_snapshot is not None:
            _verify_captured_file(manifest_snapshot, "WI-BUG-DISPOSITIONS-DRIFT")
        data = manifest_snapshot.data if manifest_snapshot is not None else manifest.read_bytes()
        payload = json.loads(data.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID",
            f"invalid {BUG_DISPOSITIONS_MANIFEST}: {slug}",
        ) from exc
    schema_version = payload.get("schemaVersion") if isinstance(payload, dict) else None
    expected_keys = {"schemaVersion", "workItem", "closedAt", "bugs"}
    if schema_version == 3:
        expected_keys.add("evidenceRetention")
    if (
        not isinstance(payload, dict)
        or set(payload) != expected_keys
        or schema_version not in BUG_DISPOSITIONS_SCHEMA_VERSIONS
        or payload.get("workItem") != slug
        or payload.get("closedAt") != terminal_instant
        or not isinstance(payload.get("bugs"), list)
        or (schema_version == 3 and (not isinstance(payload.get("evidenceRetention"), list) or not payload["evidenceRetention"]))
    ):
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID",
            f"bug disposition manifest header differs: {slug}",
        )
    return manifest, data, payload


def _prepare_evidence_retention(
    root: Path,
    item: Path,
    manifest: dict,
) -> tuple[EvidenceRetentionPlan, ...]:
    if manifest["schemaVersion"] != 3:
        return ()
    owner_root = root / ".scratch" / "work-items" / item.name
    classifier = _scratch_classifier_module()
    limits = PayloadDigestLimits(
        max_files=classifier.MAX_OWNED_TREE_FILES,
        max_entries=classifier.MAX_OWNED_TREE_ENTRIES,
        max_bytes=classifier.MAX_OWNED_TREE_BYTES,
    )
    try:
        originals, tombstones = _scratch_namespace_entries(owner_root)
    except classifier.OwnedTreeClassificationError as exc:
        raise LifecycleError("WI-SCRATCH-UNSAFE-ENTRY", str(exc)) from exc
    rows = manifest["evidenceRetention"]
    plans: list[EvidenceRetentionPlan] = []
    seen: set[Path] = set()
    for row in rows:
        if (
            not isinstance(row, dict)
            or set(row) != {"path", "disposition", "treeSha256", "canonicalPointer", "canonicalPointerSha256"}
            or row.get("disposition") != "retain"
            or not isinstance(row.get("path"), str)
            or not isinstance(row.get("canonicalPointer"), str)
            or not isinstance(row.get("treeSha256"), str)
            or not isinstance(row.get("canonicalPointerSha256"), str)
            or SHA256_RE.fullmatch(row["treeSha256"]) is None
            or SHA256_RE.fullmatch(row["canonicalPointerSha256"]) is None
        ):
            raise LifecycleError("WI-BUG-DISPOSITIONS-INVALID", "invalid evidenceRetention row")
        relative = Path(row["path"])
        candidate = root / relative
        if (
            relative.is_absolute()
            or any(part in {"", ".", ".."} for part in relative.parts)
            or relative.parts[:3] != (".scratch", "work-items", item.name)
            or len(relative.parts) != 5
            or candidate not in originals
            or candidate in seen
        ):
            raise LifecycleError("WI-BUG-DISPOSITIONS-INVALID", "evidenceRetention path is not one unmatched scratch root")
        pointer_relative = Path(row["canonicalPointer"])
        pointer = item / pointer_relative
        if (
            pointer_relative.is_absolute()
            or any(part in {"", ".", ".."} for part in pointer_relative.parts)
        ):
            raise LifecycleError("WI-BUG-DISPOSITIONS-INVALID", "evidenceRetention canonical pointer is unsafe")
        try:
            _lifecycle_reject_unreduced_reparse(
                pointer,
                failure_id="WI-BUG-DISPOSITIONS-INVALID",
                message="evidenceRetention canonical pointer crosses a link or reparse point",
            )
            resolved_item = item.resolve(strict=True)
            resolved_pointer = pointer.resolve(strict=True)
        except (LifecycleError, OSError) as exc:
            raise LifecycleError(
                "WI-BUG-DISPOSITIONS-INVALID", "evidenceRetention canonical pointer is unsafe"
            ) from exc
        if (
            not resolved_pointer.is_relative_to(resolved_item)
            or not pointer.is_file()
        ):
            raise LifecycleError("WI-BUG-DISPOSITIONS-INVALID", "evidenceRetention canonical pointer is unsafe")
        try:
            pointer_snapshot = _capture_file_snapshot(
                pointer, failure_id="WI-BUG-DISPOSITIONS-INVALID"
            )
            pointer_bytes = pointer_snapshot.data
            pointer_text = pointer_bytes.decode("utf-8", errors="strict")
        except (LifecycleError, UnicodeDecodeError) as exc:
            raise LifecycleError(
                "WI-BUG-DISPOSITIONS-INVALID", "evidenceRetention canonical pointer is unsafe"
            ) from exc
        if (
            hashlib.sha256(pointer_bytes).hexdigest() != row["canonicalPointerSha256"]
            or not _pointer_names_retained_root(
                pointer_text, candidate.name, relative.as_posix()
            )
        ):
            raise LifecycleError("WI-BUG-DISPOSITIONS-DRIFT", "evidenceRetention canonical pointer differs")
        try:
            inspection = classifier.inspect_root_no_follow(candidate)
        except classifier.OwnedTreeClassificationError as exc:
            raise LifecycleError("WI-SCRATCH-UNSAFE-ENTRY", str(exc)) from exc
        if (
            inspection.is_link_or_reparse
            or not (inspection.is_directory or inspection.is_regular_file)
        ):
            raise LifecycleError(
                "WI-BUG-DISPOSITIONS-INVALID",
                "evidenceRetention root is not an ordinary file or directory",
            )
        try:
            digest = _payload_digest(candidate, limits=limits)[1]
        except LifecycleError as exc:
            raise LifecycleError(
                "WI-SCRATCH-UNSAFE-ENTRY", "retained scratch evidence is unreadable"
            ) from exc
        if digest != row["treeSha256"]:
            raise LifecycleError("WI-BUG-DISPOSITIONS-DRIFT", "evidenceRetention tree hash differs")
        seen.add(candidate)
        plans.append(
            EvidenceRetentionPlan(
                candidate,
                digest,
                pointer,
                row["canonicalPointerSha256"],
                limits,
            )
        )
    return tuple(plans)


def _context_bug_files(root: Path, slug: str) -> dict[str, Path]:
    bug_root = _work_items_root(root) / CATEGORIES["bug"].current_root
    result: dict[str, Path] = {}
    if not bug_root.is_dir():
        return result
    for path in sorted(bug_root.glob("*.md")):
        if path.is_symlink() or not path.is_file():
            continue
        try:
            text = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-INVALID",
                f"current bug record is not readable UTF-8: {path.name}",
            ) from exc
        fields = _parse_fields(text)
        if fields.get("context") != slug:
            continue
        _validate_slug(path.stem)
        if path.stem in result:
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-INCOMPLETE",
                f"duplicate context-linked bug identity: {path.stem}",
            )
        result[path.stem] = path
    return result


def _terminal_bug_bytes(
    before: bytes,
    *,
    current_status: str,
    terminal_status: str,
    terminal_instant: str,
    resolution: str,
    evidence: str,
    successor: str | None = None,
    context_before: str | None = None,
    context_after: str | None = None,
) -> bytes:
    try:
        text = before.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID", "bug record is not UTF-8"
        ) from exc
    fields = _parse_fields(text)
    if fields.get("status") != current_status:
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-DRIFT", "bug status changed after preflight"
        )
    if (context_before is None) != (context_after is None):
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID",
            "bug context transition must provide both before and after values",
        )
    if context_before is not None and fields.get("context") != context_before:
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-DRIFT", "bug context changed after preflight"
        )
    if any(
        fields.get(key)
        for key in ("terminal-at", "resolution", "evidence", "successor")
    ):
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID",
            "current bug already carries terminal evidence",
        )
    replaced, count = re.subn(
        r"(?im)^(\s*(?:-\s*)?status\s*:\s*)[^\r\n]+(?=\r?$)",
        rf"\g<1>{terminal_status}",
        text,
        count=1,
    )
    if count != 1:
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID", "bug requires one status field"
        )
    if context_before is not None:
        replaced, context_count = re.subn(
            r"(?im)^(\s*(?:-\s*)?context\s*:\s*)[^\r\n]+(?=\r?$)",
            rf"\g<1>{context_after}",
            replaced,
            count=1,
        )
        if context_count != 1:
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-INVALID", "bug requires one context field"
            )
    newline = "\r\n" if "\r\n" in text and text.count("\n") == text.count("\r\n") else "\n"
    separator = "" if replaced.endswith("\n") else newline
    return (
        replaced
        + separator
        + newline
        + f"Terminal-at: {terminal_instant}{newline}"
        + f"Resolution: {resolution}{newline}"
        + f"Evidence: {evidence}{newline}"
        + (f"Successor: {successor}{newline}" if successor is not None else "")
    ).encode("utf-8")


def _bug_disposition_before_status_eligible(action: object, status: object) -> bool:
    """Preservation retains known states; terminalization mutates current states."""
    if not isinstance(status, str):
        return False
    category = CATEGORIES["bug"]
    if action == "preserve-current":
        return status in category.current_statuses | category.terminal_statuses
    return action == "terminalize" and status in category.current_statuses


def _prepare_bug_dispositions(
    root: Path,
    item: Path,
    slug: str,
    terminal_instant: str,
    *,
    allow_placeholder_context: bool = False,
    manifest_snapshot=None,
) -> tuple[Path, bytes, tuple[BugDispositionPlan, ...]]:
    manifest, manifest_data, payload = _load_bug_disposition_manifest(
        item, slug, terminal_instant, manifest_snapshot=manifest_snapshot
    )
    schema_version = payload["schemaVersion"]
    if schema_version == 2 and not allow_placeholder_context:
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID",
            "bug disposition schema version 2 is admitted only by close_item",
        )
    linked = _context_bug_files(root, slug)
    rows = payload["bugs"]
    ids = [row.get("id") for row in rows if isinstance(row, dict)]
    if (
        len(ids) != len(rows)
        or any(not isinstance(value, str) or not is_valid_slug(value) for value in ids)
        or len(set(ids)) != len(ids)
    ):
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INVALID",
            "bug disposition ids must be unique canonical slugs",
        )
    selected = dict(linked)
    if schema_version == 2:
        bug_root = _work_items_root(root) / CATEGORIES["bug"].current_root
        for bug_id in set(ids) - set(linked):
            source = bug_root / f"{bug_id}.md"
            if source.is_symlink() or not source.is_file():
                continue
            try:
                fields = _parse_fields(source.read_text(encoding="utf-8"))
            except (OSError, UnicodeError) as exc:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID",
                    f"selected placeholder bug is not readable UTF-8: {bug_id}",
                ) from exc
            if fields.get("context") in BUG_DISPOSITION_PLACEHOLDER_CONTEXTS:
                selected[bug_id] = source
    if set(ids) != set(selected):
        missing = sorted(set(linked) - set(ids))
        extra = sorted(set(ids) - set(selected))
        raise _bug_disposition_fail(
            "WI-BUG-DISPOSITIONS-INCOMPLETE",
            f"bug disposition set differs (missing={missing}, extra={extra})",
        )
    plans: list[BugDispositionPlan] = []
    bug_category = CATEGORIES["bug"]
    for row in rows:
        assert isinstance(row, dict)
        bug_id = row["id"]
        action = row.get("action")
        if action not in BUG_DISPOSITION_ACTIONS:
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-INVALID", f"invalid bug action: {action!r}"
            )
        expected_fields = (
            {"id", "action", "inputSha256", "status", "resolution", "evidence"}
            if action == "terminalize"
            else {"id", "action", "inputSha256", "status", "reason", "evidence"}
        )
        if schema_version == 2:
            expected_fields |= {"contextBefore", "contextAfter"}
        if set(row) != expected_fields:
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-INVALID",
                f"bug disposition fields differ: {bug_id}",
            )
        source = selected[bug_id]
        before = source.read_bytes()
        digest = row.get("inputSha256")
        if not isinstance(digest, str) or not SHA256_RE.fullmatch(digest):
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-INVALID", f"invalid inputSha256: {bug_id}"
            )
        if hashlib.sha256(before).hexdigest() != digest:
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-DRIFT", f"bug bytes changed: {bug_id}"
            )
        occurrences = [] if schema_version == 2 or action == "preserve-current" else None
        try:
            fields = _parse_fields(before.decode("utf-8"), occurrences_out=occurrences)
        except UnicodeDecodeError as exc:
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-INVALID",
                f"current bug record is not UTF-8: {bug_id}",
            ) from exc
        current_status = fields.get("status", "")
        if not _bug_disposition_before_status_eligible(action, current_status):
            raise _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-DRIFT",
                f"bug is not current: {bug_id} ({current_status!r})",
            )
        if action == "preserve-current" and current_status in bug_category.terminal_statuses:
            assert occurrences is not None
            owned_fields: dict[str, list[str]] = {}
            for _line, name, value, _raw in occurrences:
                owned_fields.setdefault(name, []).append(value)
            if (
                owned_fields.get("status") != [current_status]
                or len(owned_fields.get("context", [])) != 1
                or ("id" in owned_fields and owned_fields["id"] != [bug_id])
                or any(len(owned_fields.get(name, [])) > 1 for name in (
                    "terminal-at", "resolution", "evidence", "successor",
                ))
            ):
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID", f"terminal preservation record is ambiguous: {bug_id}",
                )
            if _category_locations(root, bug_category, bug_id) != [source]:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-DRIFT", f"preserved bug is not uniquely current: {bug_id}",
                )
        context_before: str | None = None
        context_after: str | None = None
        if schema_version == 2:
            assert occurrences is not None
            statuses = [
                value for _line, name, value, _raw in occurrences if name == "status"
            ]
            contexts = [
                value for _line, name, value, _raw in occurrences if name == "context"
            ]
            if statuses != [current_status] or len(contexts) != 1:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID",
                    f"bug requires exactly one current status and context: {bug_id}",
                )
            current_context = contexts[0]
            context_before = row.get("contextBefore")
            context_after = row.get("contextAfter")
            if (
                not isinstance(context_before, str)
                or context_before != current_context
            ):
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-DRIFT",
                    f"bug context before-image differs: {bug_id}",
                )
            if context_after != slug:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID",
                    f"bug context after-image must equal the closing work item: {bug_id}",
                )
            if (
                current_context in BUG_DISPOSITION_PLACEHOLDER_CONTEXTS
                and action != "terminalize"
            ):
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID",
                    f"placeholder-context bug must be terminalized: {bug_id}",
                )
            if action == "terminalize" and any(
                fields.get(key)
                for key in ("terminal-at", "resolution", "evidence", "successor")
            ):
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID",
                    f"current bug already carries terminal evidence: {bug_id}",
                )
        desired_status = row.get("status")
        _single_line_manifest_text(row, "evidence")
        if action == "preserve-current":
            if desired_status != current_status:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID",
                    f"preserve-current status differs: {bug_id}",
                )
            _single_line_manifest_text(row, "reason")
            target = None
            after = before
        else:
            if desired_status not in bug_category.terminal_statuses:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-INVALID",
                    f"terminal bug status is invalid: {bug_id}",
                )
            resolution = _single_line_manifest_text(row, "resolution")
            evidence = _single_line_manifest_text(row, "evidence")
            after = _terminal_bug_bytes(
                before,
                current_status=current_status,
                terminal_status=desired_status,
                terminal_instant=terminal_instant,
                resolution=resolution,
                evidence=evidence,
                context_before=context_before,
                context_after=context_after,
            )
            _validate_flat_terminal(bug_category, after)
            target = (
                _work_items_root(root)
                / bug_category.current_root
                / "archive"
                / archive_month(terminal_instant)
                / source.name
            )
            if target.exists():
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-DRIFT",
                    f"bug archive target already exists: {bug_id}",
                )
        plans.append(
            BugDispositionPlan(
                bug_id=bug_id,
                action=action,
                source=source,
                target=target,
                before=before,
                after=after,
                status_before=current_status,
                status_after=desired_status,
                context_before=context_before,
                context_after=context_after,
            )
        )
    return manifest, manifest_data, tuple(sorted(plans, key=lambda plan: plan.bug_id))


def _close_link_uri_changes(before: bytes, after: bytes) -> list[dict[str, str]]:
    """Assert a URI-only delta using the existing closed Markdown spans."""
    old, new = before.decode("utf-8"), after.decode("utf-8")
    old_links, new_links = list(_markdown_local_links(old)), list(_markdown_local_links(new))
    def outside_hrefs(text: str, links: list[MarkdownLocalLink]) -> str:
        for link in reversed(links):
            text = text[:link.href_start] + text[link.href_end:]
        return text
    if len(old_links) != len(new_links) or outside_hrefs(old, old_links) != outside_hrefs(new, new_links):
        raise LifecycleError("WI-CLOSE-LINK-VERIFY", "link upkeep changed non-URI bytes")
    old_fields, new_fields = _parse_fields(old), _parse_fields(new)
    if any(old_fields.get(key) != new_fields.get(key) for key in ("id", "context", "status")):
        raise LifecycleError("WI-CLOSE-LINK-VERIFY", "link upkeep changed record identity or lifecycle fields")
    return [{"from": left.href, "to": right.href} for left, right in zip(old_links, new_links)
            if left.href != right.href]


def _close_link_consumer_descriptor(relative: str) -> tuple[str, str, Category | None] | None:
    """Describe a normalized current URI consumer without consulting live state."""
    if (not isinstance(relative, str) or not relative or "\\" in relative
        or PurePosixPath(relative).is_absolute()
        or any(part in {"", ".", "..", "archive"} for part in relative.split("/"))
        or re.match(r"^[A-Za-z]:", relative)):
        return None
    parts = relative.split("/")
    if len(parts) == 2 and parts[1].endswith(".md") and is_valid_slug(parts[1][:-3]):
        category = next((item for item in CATEGORIES.values()
                         if item.current_kind == "flat" and item.current_root == parts[0]), None)
        if category is not None:
            return "registry", relative, category
    if (len(parts) >= 3 and parts[0] == "active" and is_valid_slug(parts[1])
        and parts[2] not in {"inputs", "review-artifact-custody"}
        and parts[-1].lower().endswith(".md")):
        return "active-document", "/".join(parts[:2]), None
    return None


def _close_link_active_owner_evidence(root: Path, path: Path, before: bytes,
                                      owner_relative: str) -> tuple:
    work_items = _work_items_root(root)
    owner = work_items / owner_relative
    evidence: list = []
    locations = _category_locations_at(work_items, CATEGORIES["work-item"], owner.name,
                                       binding_evidence=evidence)
    if locations != [owner]:
        raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"consumer has no unique current owner: {path}")
    status = _capture_file_snapshot(owner / "status.md", failure_id="WI-CATEGORY-STATUS-INVALID")
    if path == status.path and before != status.data:
        raise LifecycleError("WI-CLOSE-LINK-DRIFT", "status consumer differs from owner capture")
    _validate_active_status_bytes(status.data)
    evidence.append(("file", status))
    return tuple(evidence)


def _close_link_authority(root: Path, path: Path, before: bytes,
                          image: BugDispositionPlan | None, allow_protected: bool,
                          schema_version: int) -> str:
    if image is not None:
        if image.action == "terminalize":
            return "selected-terminalize"
        protected = True
    else:
        protected = False
    work_items = _work_items_root(root)
    label = path.relative_to(work_items).as_posix()
    descriptor = _close_link_consumer_descriptor(label)
    if descriptor is None:
        raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"affected consumer has no admitted metadata owner: {label}")
    kind, owner_relative, category = descriptor
    if kind == "active-document" and _incoming_attachment_kind(before) is not None:
        raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"affected consumer has opaque content: {label}")
    try:
        text = before.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"consumer must be UTF-8: {label}") from exc
    if kind == "registry":
        assert category is not None
        if _category_locations(root, category, path.stem) != [path]:
            raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"consumer has no unique current owner: {label}")
        if category.name == "decision":
            decision = _parse_decision_record_text(text, path.stem)
            if decision.legacy_read_only:
                raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"decision consumer format is read-only: {label}")
            status = decision.raw_status
        else:
            fields = _parse_fields(text)
            status = fields.get("status")
        if category.name == "bug":
            if not _bug_disposition_before_status_eligible("preserve-current", status):
                raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"bug consumer has no admitted status: {label}")
            protected |= (schema_version == 2 and image is None
                          and fields.get("context") in BUG_DISPOSITION_PLACEHOLDER_CONTEXTS)
        elif status not in category.current_statuses | category.terminal_statuses:
            raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"consumer has no admitted current status: {label}")
    elif kind == "active-document":
        _close_link_active_owner_evidence(root, path, before, owner_relative)
    else:
        raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", f"affected consumer has no admitted metadata owner: {label}")
    if protected:
        if not allow_protected:
            raise LifecycleError("WI-CLOSE-LINK-PRESERVATION", f"protected consumer requires positive URI-upkeep authority: {label}")
        return "protected-uri-maintenance"
    return "current-metadata"


def _verify_close_link_maintenance(work_items: Path, slug: str, instant: str,
                                  value: object, results: dict) -> dict[str, dict]:
    """Verify close-time assertions; never freeze later current consumer bytes."""
    failure = "WI-IMMUTABLE-ARCHIVE"
    def reject() -> None:
        raise LifecycleError(failure, "ordinary-close link receipt binding differs")
    expected_source = f"active/{slug}"
    expected_target = f"archive/{archive_month(instant)}/{slug}"
    legacy_metadata = work_items / expected_target / LEGACY_COMPLETION_METADATA
    legacy = os.path.lexists(legacy_metadata)
    if legacy:
        metadata = json.loads(_capture_file_snapshot(legacy_metadata, failure_id=failure).data)
        expected_source = metadata["source"]["originalPath"].removeprefix("work-items/")
        expected_target += "/" + metadata["source"]["preservedPath"]
    if (not isinstance(value, dict) or set(value) != {
        "version", "source", "target", "allowProtectedUriUpdates", "consumers"
    } or type(value["version"]) is not int or value["version"] != 1
        or value["source"] != expected_source
        or value["target"] != expected_target
        or type(value["allowProtectedUriUpdates"]) is not bool
        or not isinstance(value["consumers"], list) or not value["consumers"]):
        reject()
    by_source: dict[str, dict] = {}
    for row in value["consumers"]:
        if (not isinstance(row, dict) or set(row) != {
            "source", "target", "beforeSha256", "afterSha256", "authority", "uriChanges"
        } or any(not isinstance(row.get(key), str) or not SHA256_RE.fullmatch(row[key])
                 for key in ("beforeSha256", "afterSha256"))
            or row["beforeSha256"] == row["afterSha256"]
            or not isinstance(row["uriChanges"], list) or not row["uriChanges"]):
            reject()
        for key in ("source", "target"):
            path = row.get(key)
            if (not isinstance(path, str) or not path or "\\" in path
                or PurePosixPath(path).is_absolute() or any(part in {"", ".", ".."} for part in path.split("/"))):
                reject()
            if legacy:
                _legacy_relative("work-items/" + path)
            else:
                _terminalization_bound_path(work_items, path, label="close link receipt")
        if row["source"] in by_source or "archive" in PurePosixPath(row["source"]).parts:
            reject()
        authority = row["authority"]
        result = next((item for item in results.values() if item.get("source") == row["source"]), None)
        if authority == "selected-terminalize":
            if (result is None or result.get("action") != "terminalize" or any(
                result.get(key) != row[key] for key in ("source", "target", "beforeSha256", "afterSha256")
            )):
                reject()
        elif authority in {"current-metadata", "protected-uri-maintenance"}:
            if row["target"] != row["source"]:
                reject()
            descriptor = _close_link_consumer_descriptor(row["source"])
            if descriptor is None:
                reject()
            if authority == "protected-uri-maintenance" and not value["allowProtectedUriUpdates"]:
                reject()
            if authority == "protected-uri-maintenance" and (
                descriptor[0] != "registry" or descriptor[2].name != "bug"):
                reject()
            if result is not None and (authority != "protected-uri-maintenance"
                or result.get("action") != "preserve-current"
                or result.get("beforeSha256") != row["beforeSha256"]
                or result.get("afterSha256") != row["afterSha256"]
                or result.get("statusBefore") != result.get("statusAfter")):
                reject()
        else:
            reject()
        for change in row["uriChanges"]:
            if (not isinstance(change, dict) or set(change) != {"from", "to"}
                or any(not isinstance(change[key], str) for key in ("from", "to"))):
                reject()
            old, new = _local_markdown_href_parts(change["from"]), _local_markdown_href_parts(change["to"])
            if old is None or new is None or old[1] != new[1]:
                reject()
            original = Path(os.path.abspath(work_items / row["source"])).parent / old[0]
            original = Path(os.path.abspath(original))
            source = work_items / value["source"]
            if original != source and source not in original.parents:
                reject()
            expected = work_items / value["target"] / original.relative_to(source)
            actual = Path(os.path.abspath((work_items / row["target"]).parent / new[0]))
            if actual != expected:
                reject()
        by_source[row["source"]] = row
    if list(by_source) != sorted(by_source):
        reject()
    return by_source


def _bug_disposition_receipt_bytes(
    root: Path,
    slug: str,
    terminal_instant: str,
    manifest_data: bytes,
    closure_data: bytes,
    plans: tuple[BugDispositionPlan, ...],
    readme_sha256: str,
    evidence_retention: tuple[EvidenceRetentionPlan, ...] = (),
    *,
    link_maintenance: dict | None = None,
) -> bytes:
    manifest = json.loads(manifest_data.decode("utf-8"))
    schema_version = manifest["schemaVersion"]
    payload = {
        "schemaVersion": schema_version,
        "owner": BUG_DISPOSITIONS_OWNER,
        "workItem": slug,
        "closedAt": terminal_instant,
        "manifestSha256": hashlib.sha256(manifest_data).hexdigest(),
        "closureSha256": hashlib.sha256(closure_data).hexdigest(),
        "readmeSha256": readme_sha256,
        "bugs": [
            {
                "id": plan.bug_id,
                "action": plan.action,
                "statusBefore": plan.status_before,
                "statusAfter": plan.status_after,
                "beforeSha256": hashlib.sha256(plan.before).hexdigest(),
                "afterSha256": hashlib.sha256(plan.after).hexdigest(),
                "source": plan.source.relative_to(_work_items_root(root)).as_posix(),
                "target": (
                    plan.target.relative_to(_work_items_root(root)).as_posix()
                    if plan.target is not None
                    else None
                ),
                **(
                    {
                        "contextBefore": plan.context_before,
                        "contextAfter": plan.context_after,
                    }
                    if schema_version == 2
                    else {}
                ),
            }
            for plan in plans
        ],
        **(
            {
                "evidenceRetention": [
                    {
                        "path": plan.path.relative_to(root).as_posix(),
                        "disposition": "retain",
                        "treeSha256": plan.tree_sha256,
                        "canonicalPointer": plan.canonical_pointer.relative_to(
                            _work_items_root(root) / "active" / slug
                        ).as_posix(),
                        "canonicalPointerSha256": plan.canonical_pointer_sha256,
                    }
                    for plan in evidence_retention
                ]
            }
            if schema_version == 3
            else {}
        ),
    }
    if link_maintenance is not None:
        payload["linkMaintenance"] = link_maintenance
    return (json.dumps(payload, indent=2, sort_keys=True) + "\n").encode("utf-8")


def _verify_archived_bug_dispositions(
    root: Path,
    archived: Path,
    closure_data: bytes,
    terminal_instant: str,
) -> None:
    slug = archived.name
    try:
        _manifest, manifest_data, manifest = _load_bug_disposition_manifest(
            archived, slug, terminal_instant
        )
    except LifecycleError as exc:
        raise _bug_disposition_fail(
            "WI-IMMUTABLE-ARCHIVE",
            f"archived bug disposition manifest differs: {slug}",
        ) from exc
    schema_version = manifest["schemaVersion"]
    receipt_path = archived / BUG_DISPOSITIONS_RECEIPT
    if receipt_path.is_symlink() or not receipt_path.is_file():
        raise _bug_disposition_fail(
            "WI-IMMUTABLE-ARCHIVE",
            f"archived work-item lacks {BUG_DISPOSITIONS_RECEIPT}: {slug}",
        )
    try:
        receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise _bug_disposition_fail(
            "WI-IMMUTABLE-ARCHIVE", f"invalid bug disposition receipt: {slug}"
        ) from exc
    expected_keys = {
        "schemaVersion",
        "owner",
        "workItem",
        "closedAt",
        "manifestSha256",
        "closureSha256",
        "readmeSha256",
        "bugs",
    }
    if schema_version == 3:
        expected_keys.add("evidenceRetention")
    if isinstance(receipt, dict) and "linkMaintenance" in receipt:
        expected_keys.add("linkMaintenance")
    if (
        not isinstance(receipt, dict)
        or set(receipt) != expected_keys
        or receipt.get("schemaVersion") != schema_version
        or receipt.get("owner") != BUG_DISPOSITIONS_OWNER
        or receipt.get("workItem") != slug
        or receipt.get("closedAt") != terminal_instant
        or receipt.get("manifestSha256") != hashlib.sha256(manifest_data).hexdigest()
        or receipt.get("closureSha256") != hashlib.sha256(closure_data).hexdigest()
        or not isinstance(receipt.get("readmeSha256"), str)
        or not SHA256_RE.fullmatch(receipt["readmeSha256"])
        or not isinstance(receipt.get("bugs"), list)
        or (schema_version == 3 and not isinstance(receipt.get("evidenceRetention"), list))
    ):
        raise _bug_disposition_fail(
            "WI-IMMUTABLE-ARCHIVE", f"bug disposition receipt binding differs: {slug}"
        )
    rows = manifest["bugs"]
    if len(receipt["bugs"]) != len(rows):
        raise _bug_disposition_fail(
            "WI-IMMUTABLE-ARCHIVE", f"bug disposition receipt count differs: {slug}"
        )
    by_id = {
        row.get("id"): row for row in receipt["bugs"] if isinstance(row, dict)
    }
    if set(by_id) != {row.get("id") for row in rows if isinstance(row, dict)}:
        raise _bug_disposition_fail(
            "WI-IMMUTABLE-ARCHIVE", f"bug disposition receipt ids differ: {slug}"
        )
    link_consumers = {}
    if "linkMaintenance" in receipt:
        try:
            link_consumers = _verify_close_link_maintenance(
                _work_items_root(root), slug, terminal_instant, receipt["linkMaintenance"], by_id
            )
        except LifecycleError as exc:
            raise _bug_disposition_fail(
                "WI-IMMUTABLE-ARCHIVE", "ordinary-close link receipt binding differs"
            ) from exc
    if schema_version == 3:
        manifest_retention = manifest["evidenceRetention"]
        receipt_retention = receipt["evidenceRetention"]
        if (
            len(receipt_retention) != len(manifest_retention)
            or any(not isinstance(row, dict) for row in receipt_retention)
            or receipt_retention != manifest_retention
        ):
            raise _bug_disposition_fail(
                "WI-IMMUTABLE-ARCHIVE", f"retained scratch receipt differs: {slug}"
            )
    work_items = _work_items_root(root)
    for decision in rows:
        if not isinstance(decision, dict):
            raise _bug_disposition_fail(
                "WI-IMMUTABLE-ARCHIVE", f"invalid archived decision row: {slug}"
            )
        action = decision.get("action")
        required_decision_keys = (
            {"id", "action", "inputSha256", "status", "resolution", "evidence"}
            if action == "terminalize"
            else {"id", "action", "inputSha256", "status", "reason", "evidence"}
        )
        if schema_version == 2:
            required_decision_keys |= {"contextBefore", "contextAfter"}
        if action not in BUG_DISPOSITION_ACTIONS or set(decision) != required_decision_keys:
            raise _bug_disposition_fail(
                "WI-IMMUTABLE-ARCHIVE",
                f"archived bug disposition decision differs: {decision.get('id')}",
            )
        result = by_id[decision["id"]]
        required_result_keys = {
            "id",
            "action",
            "statusBefore",
            "statusAfter",
            "beforeSha256",
            "afterSha256",
            "source",
            "target",
        }
        if schema_version == 2:
            required_result_keys |= {"contextBefore", "contextAfter"}
        if (
            set(result) != required_result_keys
            or result.get("id") != decision["id"]
            or result.get("action") != decision["action"]
            or result.get("beforeSha256") != decision["inputSha256"]
            or result.get("statusAfter") != decision["status"]
            or not _bug_disposition_before_status_eligible(action, result.get("statusBefore"))
            or result.get("source") != f"bugs/{decision['id']}.md"
            or not isinstance(result.get("afterSha256"), str)
            or not SHA256_RE.fullmatch(result["afterSha256"])
            or (
                schema_version == 2
                and (
                    result.get("contextBefore") != decision.get("contextBefore")
                    or result.get("contextAfter") != decision.get("contextAfter")
                    or decision.get("contextAfter") != slug
                    or decision.get("contextBefore")
                    not in ({slug} | BUG_DISPOSITION_PLACEHOLDER_CONTEXTS)
                )
            )
        ):
            raise _bug_disposition_fail(
                "WI-IMMUTABLE-ARCHIVE",
                f"archived bug disposition row differs: {decision['id']}",
            )
        if decision["action"] == "terminalize":
            target_relative = result.get("target")
            expected_target = (
                f"bugs/archive/{archive_month(terminal_instant)}/{decision['id']}.md"
            )
            if target_relative != expected_target:
                raise _bug_disposition_fail(
                    "WI-IMMUTABLE-ARCHIVE",
                    f"terminal bug target differs: {decision['id']}",
                )
            assert isinstance(target_relative, str)
            target = _terminalization_bound_path(
                work_items, target_relative, label="archived bug disposition target"
            )
            current = work_items / CATEGORIES["bug"].current_root / f"{decision['id']}.md"
            if (
                not target.is_file()
                or current.exists()
                or hashlib.sha256(target.read_bytes()).hexdigest()
                != result["afterSha256"]
            ):
                raise _bug_disposition_fail(
                    "WI-IMMUTABLE-ARCHIVE",
                    f"terminal bug archive differs: {decision['id']}",
                )
            _validate_flat_terminal(CATEGORIES["bug"], target.read_bytes())
            if (
                schema_version == 2
                and _parse_fields(target.read_text(encoding="utf-8")).get("context")
                != decision.get("contextAfter")
            ):
                raise _bug_disposition_fail(
                    "WI-IMMUTABLE-ARCHIVE",
                    f"terminal bug context differs: {decision['id']}",
                )
        elif (
            result.get("target") is not None
            or result.get("statusBefore") != decision["status"]
            or result.get("afterSha256") != (
                link_consumers[result["source"]]["afterSha256"]
                if result["source"] in link_consumers else decision["inputSha256"]
            )
            or (
                schema_version == 2
                and (
                    decision.get("contextBefore") != slug
                    or decision.get("contextAfter") != slug
                )
            )
        ):
            raise _bug_disposition_fail(
                "WI-IMMUTABLE-ARCHIVE",
                f"preserved bug receipt differs: {decision['id']}",
            )


def _mkdir_parents_tracked(path: Path, created: list[Path]) -> None:
    missing: list[Path] = []
    cursor = path
    while not cursor.exists():
        missing.append(cursor)
        cursor = cursor.parent
    for directory in reversed(missing):
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        prepared = None if transaction is None else transaction.prepare_owned_effect(transaction, None, directory, directory=True)
        directory.mkdir()
        created.append(directory)
        if prepared is not None:
            transaction.publish_owned_effect(prepared, native_identity=_lifecycle_file_identity(directory.lstat()))


def _plan_parent_archive_links(
    root: Path, source: Path, target: Path, *,
    bug_plans: tuple[BugDispositionPlan, ...] = (),
    bug_manifest: dict | None = None,
    target_after_images: Mapping[Path, bytes] | None = None,
    allow_protected_uri_updates: bool = False,
) -> dict:
    """Capture one parent relocation's authorized consumer and target images."""
    work_items = _work_items_root(root)
    target_after_images = target_after_images or {}
    incoming = _incoming_link_result(
        root, {source}, f"work-item:{source.name}",
        mutable_consumers_only=True, strict_consumer_reads=True,
    )
    images = {plan.source: plan for plan in bug_plans}
    links = _physical_archive_link_plans(
        root, source, target, incoming["references"],
        failure_id="WI-CLOSE-LINK-INVENTORY", include_descendants=True,
        consumer_images=images,
    )
    link_rows = []
    consumer_captures = {}
    owner_evidence = []
    target_images = {}
    target_directory_identities = {}
    for row in links:
        consumer = row["path"]
        image = images.get(consumer)
        snapshot = _capture_file_snapshot(consumer, failure_id="WI-CLOSE-LINK-DRIFT")
        if snapshot.data != row["before"]:
            raise LifecycleError("WI-CLOSE-LINK-DRIFT", "consumer changed after link preflight")
        consumer_captures[consumer] = snapshot
        authority = _close_link_authority(
            root, consumer, row["before"], image, allow_protected_uri_updates,
            bug_manifest["schemaVersion"] if bug_manifest is not None else 1,
        )
        descriptor = _close_link_consumer_descriptor(consumer.relative_to(work_items).as_posix())
        if descriptor is not None and descriptor[0] == "active-document":
            owner_evidence.extend(_close_link_active_owner_evidence(root, consumer, row["before"], descriptor[1]))
        changes = _close_link_uri_changes(image.after if image is not None else row["before"], row["after"])
        final = (image.target or image.source) if image is not None else consumer
        link_rows.append({
            "source": consumer.relative_to(work_items).as_posix(),
            "target": final.relative_to(work_items).as_posix(),
            "beforeSha256": row["beforeSha256"], "afterSha256": row["afterSha256"],
            "authority": authority, "uriChanges": changes,
        })
        for change in changes:
            parts = _local_markdown_href_parts(change["from"])
            assert parts is not None
            old_target = (consumer.parent / parts[0]).resolve()
            if old_target in target_images:
                continue
            if old_target.is_file():
                captured = _capture_file_snapshot(old_target, failure_id="WI-CLOSE-LINK-INVENTORY")
                data = captured.data
                data = target_after_images.get(old_target, data)
                target_images[old_target] = (target / old_target.relative_to(source), captured, data)
            elif old_target.is_dir():
                target_images[old_target] = (target / old_target.relative_to(source), None, None)
                target_directory_identities[old_target] = _lifecycle_file_identity(old_target.lstat())
            elif old_target in target_after_images:
                _require_lifecycle_mutation_path(root, old_target, failure_id="WI-CLOSE-LINK-INVENTORY")
                target_images[old_target] = (target / old_target.relative_to(source), None, target_after_images[old_target])
            else:
                raise LifecycleError("WI-CLOSE-LINK-INVENTORY", "incoming URI target is unavailable")
        if image is not None:
            images[consumer] = replace(image, after=row["after"])
    bug_plans = tuple(images[plan.source] for plan in bug_plans)
    link_maintenance = {
        "version": 1, "source": source.relative_to(work_items).as_posix(), "target": target.relative_to(work_items).as_posix(),
        "allowProtectedUriUpdates": allow_protected_uri_updates, "consumers": link_rows,
    } if link_rows else None
    return {"bugs": bug_plans, "links": links,
            "consumerCaptures": consumer_captures, "ownerEvidence": tuple(owner_evidence),
            "targetImages": target_images,
            "targetDirectoryIdentities": target_directory_identities,
            "maintenance": link_maintenance}


def _verify_parent_archive_link_targets(plan: dict, *, archived: bool,
                                        failure_id: str) -> None:
    for original, (final, captured, data) in plan["targetImages"].items():
        path = final if archived else original
        if not archived and captured is not None:
            _verify_captured_file(captured, failure_id)
        elif data is None:
            _lifecycle_reject_unreduced_reparse(path, failure_id=failure_id,
                message="URI directory target crosses a link or reparse point")
            if not path.is_dir() or _lifecycle_file_identity(path.lstat()) != plan["targetDirectoryIdentities"][original]:
                raise LifecycleError(failure_id, "URI directory target differs")
        elif archived:
            if _capture_file_snapshot(path, failure_id=failure_id).data != data:
                raise LifecycleError(failure_id, "URI target bytes differ")
        elif path.exists():
            raise LifecycleError(failure_id, "declared absent URI target appeared")


def close_item(root, slug, closure_data, terminal_instant, *, inject_readme_failure=False,
               inject_bug_failure_after=None, allow_protected_uri_updates=False,
               legacy_evidence_data=None, apply=False, inject_failure_at=None):
    if legacy_evidence_data is not None:
        return _close_legacy_flat_entry(root, slug, closure_data, terminal_instant, legacy_evidence_data,
            apply=apply, authority=allow_protected_uri_updates,
            inject_failure_at=inject_failure_at or ("after-board" if inject_readme_failure else None))
    return _close_item_directory(root, slug, closure_data, terminal_instant,
        inject_readme_failure=inject_readme_failure, inject_bug_failure_after=inject_bug_failure_after,
        allow_protected_uri_updates=allow_protected_uri_updates, apply=apply, inject_failure_at=inject_failure_at)


@_lifecycle_participant
def _close_legacy_flat_entry(root, slug, closure_data, instant, evidence_data, *, apply, authority, inject_failure_at=None):
    return _close_legacy_flat(root, slug, closure_data, instant, evidence_data,
                             apply=apply, authority=authority, inject_failure_at=inject_failure_at)


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def _close_item_directory(
    root: Path,
    slug: str,
    closure_data: bytes,
    terminal_instant: str,
    *,
    inject_readme_failure: bool = False,
    inject_bug_failure_after: int | None = None,
    allow_protected_uri_updates: bool = False,
    legacy_evidence_data: bytes | None = None,
    apply: bool = False,
    inject_failure_at: str | None = None,
) -> Path:
    if legacy_evidence_data is not None:
        return _close_legacy_flat(root, slug, closure_data, terminal_instant, legacy_evidence_data,
            apply=apply, authority=allow_protected_uri_updates, inject_failure_at=inject_failure_at)
    if apply or inject_failure_at is not None:
        raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", "legacy apply/fault arguments require explicit legacy evidence")
    if type(allow_protected_uri_updates) is not bool:
        raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", "URI-upkeep authority must be boolean")
    _validate_slug(slug)
    month = archive_month(terminal_instant)
    _validate_closure(closure_data, terminal_instant)
    archived_closure_data = _stamp_schema_marker(closure_data, "closure.md")
    root = Path(os.path.abspath(root))
    work_items = _work_items_root(root)
    locations = _category_locations(root, CATEGORIES["work-item"], slug)
    if len(locations) > 1:
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", f"duplicate slug: {slug}")
    if len(locations) == 1 and "archive" in locations[0].parts:
        archived = locations[0]
        _archived_work_item_entry(archived)
        existing = archived / "closure.md"
        if (
            not existing.is_file()
            or existing.read_bytes() != archived_closure_data
            or archived.parent.name != month
        ):
            raise LifecycleError("WI-IMMUTABLE-ARCHIVE", f"archived identity differs: {slug}")
        manifest_present = (archived / BUG_DISPOSITIONS_MANIFEST).exists()
        receipt_present = (archived / BUG_DISPOSITIONS_RECEIPT).exists()
        if manifest_present or receipt_present:
            _verify_archived_bug_dispositions(
                root, archived, archived_closure_data, terminal_instant
            )
        archived_retention_paths = frozenset()
        if manifest_present:
            _manifest_path, _manifest_data, archived_manifest = _load_bug_disposition_manifest(
                archived, slug, terminal_instant
            )
            if archived_manifest["schemaVersion"] == 3:
                archived_retention_paths = frozenset(
                    root / Path(row["path"])
                    for row in archived_manifest["evidenceRetention"]
                    if isinstance(row, dict) and isinstance(row.get("path"), str)
                )
        scratch_plan = _scratch_disposition_plan(
            root, archived, archived=True, retention_paths=archived_retention_paths
        )
        if inject_readme_failure:
            raise LifecycleError("WI-README-STALE", "injected failure after canonical success")
        refresh_readme(root)
        _settle_scratch_dispositions(root, scratch_plan)
        return archived
    active = work_items / "active" / slug
    if locations != [active]:
        raise LifecycleError("WI-INVALID-TARGET", f"close requires one active item: {slug}")
    _validate_item_before_close(active)
    _manifest_path, _manifest_preview, manifest_preview = _load_bug_disposition_manifest(
        active, slug, terminal_instant
    )
    evidence_retention = _prepare_evidence_retention(root, active, manifest_preview)
    scratch_plan = _scratch_disposition_plan(
        root,
        active,
        archived=False,
        retention_paths=frozenset(plan.path for plan in evidence_retention),
    )
    _manifest, manifest_data, bug_plans = _prepare_bug_dispositions(
        root,
        active,
        slug,
        terminal_instant,
        allow_placeholder_context=True,
    )
    _preflight_readme(root)
    closure_path = active / "closure.md"
    held = _CURRENT_LIFECYCLE_TRANSACTION.get()
    prior_closure = None
    if closure_path.exists():
        closure_capture = _capture_file_snapshot(
            closure_path, failure_id="WI-CLOSE-LINK-DRIFT",
            maximum_bytes=max(1, closure_path.lstat().st_size),
        )
        held.observe_retained_inputs((closure_capture,))
        prior_closure = closure_capture.data
    status_path = active / "status.md"
    status_capture = _capture_file_snapshot(
        status_path, failure_id="WI-CLOSE-LINK-DRIFT",
        maximum_bytes=max(1, status_path.lstat().st_size),
    )
    held.observe_retained_inputs((status_capture,))
    prior_status = status_capture.data
    target = work_items / "archive" / month / slug
    link_plan = _plan_parent_archive_links(
        root, active, target, bug_plans=bug_plans, bug_manifest=manifest_preview,
        target_after_images={status_path: _terminalize_status(prior_status),
                             closure_path: archived_closure_data},
        allow_protected_uri_updates=allow_protected_uri_updates,
    )
    bug_plans = link_plan["bugs"]
    images = {plan.source: plan for plan in bug_plans}
    links = link_plan["links"]
    consumer_captures = link_plan["consumerCaptures"]
    link_maintenance = link_plan["maintenance"]
    readme = work_items / "README.md"
    readme_existed = readme.is_file()
    readme_before = readme.read_bytes() if readme_existed else b""
    created_dirs: list[_OwnedNativeCreation] = []
    touched_bugs: list[BugDispositionPlan] = []
    touched_links: list[dict] = []
    written_link_captures = {}
    item_moved = False
    receipt_path = target / BUG_DISPOSITIONS_RECEIPT
    receipt_capture = None
    _verify_project_binding_evidence(link_plan["ownerEvidence"], "WI-CLOSE-LINK-DRIFT")
    for scratch in scratch_plan:
        if scratch.disposition == "completed-disposal":
            _recheck_completed_disposal(root, scratch)
    try:
        for index, plan in enumerate(bug_plans, start=1):
            if plan.action != "terminalize":
                continue
            if plan.source in consumer_captures:
                _verify_captured_file(consumer_captures[plan.source], "WI-CLOSE-LINK-DRIFT")
            if plan.source.read_bytes() != plan.before or plan.target is None:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-DRIFT",
                    f"bug changed after preflight: {plan.bug_id}",
                )
            touched_bugs.append(plan)
            transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
            transaction.bind_operation(plan)
            with _admit_lifecycle_write_target(plan.source, failure_id="WI-LIFECYCLE-WRITE-BOUNDARY", _operation_owner=plan) as write_target:
                _atomic_write(plan.source, plan.after, target=write_target)
            if plan.source in consumer_captures:
                captured_after = _capture_file_snapshot(plan.source, failure_id="WI-CLOSE-LINK-DRIFT")
                if captured_after.data != plan.after:
                    raise LifecycleError("WI-CLOSE-LINK-DRIFT", "URI bug postimage differs")
                written_link_captures[plan.source] = captured_after
            LifecycleWriteTarget.make_directories(plan.target.parent, transaction, created=created_dirs)
            movement = transaction.prepare_owned_effect(plan, plan.source, plan.target, data=plan.after)
            os.replace(plan.source, plan.target)
            transaction.publish_owned_effect(movement, native_identity=_lifecycle_file_identity(plan.target.lstat()))
            if plan.source in consumer_captures:
                captured_after = _capture_file_snapshot(
                    plan.target, failure_id="WI-CLOSE-LINK-DRIFT"
                )
                if captured_after.data != plan.after:
                    raise LifecycleError("WI-CLOSE-LINK-DRIFT", "moved URI bug postimage differs")
                written_link_captures[plan.source] = captured_after
            if inject_bug_failure_after == index:
                raise _bug_disposition_fail(
                    "WI-BUG-DISPOSITIONS-DRIFT",
                    f"injected bug disposition failure after row {index}",
                )
        for row in links:
            image = images.get(row["path"])
            if image is not None and image.action == "terminalize":
                continue
            _verify_captured_file(consumer_captures[row["path"]], "WI-CLOSE-LINK-DRIFT")
            touched_links.append(row)
            _atomic_write(row["path"], row["after"])
            captured_after = _capture_file_snapshot(
                row["path"], failure_id="WI-CLOSE-LINK-DRIFT"
            )
            if captured_after.data != row["after"]:
                raise LifecycleError("WI-CLOSE-LINK-DRIFT", "URI consumer postimage differs")
            written_link_captures[row["path"]] = captured_after
        _verify_parent_archive_link_targets(link_plan, archived=False, failure_id="WI-CLOSE-LINK-DRIFT")
        _atomic_write(closure_path, archived_closure_data)
        _atomic_write(status_path, _terminalize_status(prior_status))
        LifecycleWriteTarget.make_directories(target.parent, _CURRENT_LIFECYCLE_TRANSACTION.get(), created=created_dirs)
        _replace_lifecycle_directory(active, target)
        item_moved = True
        if inject_readme_failure:
            raise LifecycleError("WI-README-STALE", "injected failure after canonical success")
        readme_sha256 = refresh_readme(root)
        for retention in evidence_retention:
            try:
                observed_retention_digest = _payload_digest(
                    retention.path, limits=retention.limits
                )[1]
            except LifecycleError as exc:
                raise LifecycleError(
                    "WI-SCRATCH-UNSAFE-ENTRY",
                    "retained scratch evidence is unreadable after preflight",
                ) from exc
            if observed_retention_digest != retention.tree_sha256:
                raise LifecycleError("WI-BUG-DISPOSITIONS-DRIFT", "retained scratch evidence changed after preflight")
        receipt_data = _bug_disposition_receipt_bytes(
            root,
            slug,
            terminal_instant,
            manifest_data,
            archived_closure_data,
            bug_plans,
            readme_sha256,
            evidence_retention,
            link_maintenance=link_maintenance,
        )
        _atomic_write(receipt_path, receipt_data)
        if link_maintenance is not None:
            captured_receipt = _capture_file_snapshot(receipt_path, failure_id="WI-CLOSE-LINK-VERIFY")
            if captured_receipt.data != receipt_data:
                raise LifecycleError("WI-CLOSE-LINK-VERIFY", "URI receipt postimage differs")
            receipt_capture = captured_receipt
        _verify_archived_bug_dispositions(
            root, target, archived_closure_data, terminal_instant
        )
        for row in links:
            image = images.get(row["path"])
            final = (image.target or image.source) if image is not None else row["path"]
            if _capture_file_snapshot(final, failure_id="WI-CLOSE-LINK-VERIFY").data != row["after"]:
                raise LifecycleError("WI-CLOSE-LINK-VERIFY", "URI consumer final image differs")
        _verify_parent_archive_link_targets(link_plan, archived=True, failure_id="WI-CLOSE-LINK-VERIFY")
    except BaseException as exc:
        composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
        composer.capture_primary(exc)
        held = _CURRENT_LIFECYCLE_TRANSACTION.get()
        first_rollback_action = len(composer.rollback_actions)
        rollback_incomplete = False

        def attempt(label: str, action, *paths: Path) -> None:
            nonlocal rollback_incomplete
            if _lifecycle_cleanup_intersects_unsettled(*paths):
                rollback_incomplete = True
                return
            try:
                action()
            except BaseException as rollback_exc:
                rollback_incomplete = True
                composer.record_rollback_action(
                    failure_id=rollback_exc.failure_id if isinstance(rollback_exc, LifecycleError) else "WI-BUG-DISPOSITIONS-ROLLBACK",
                    resource=paths[0].relative_to(root).as_posix() if paths else None,
                    diagnostic=label, cause=rollback_exc)

        if receipt_path.exists():
            def remove_receipt():
                if link_maintenance is not None:
                    if receipt_capture is None:
                        raise LifecycleError("WI-CLOSE-LINK-DRIFT", "owned URI receipt image unavailable")
                    _verify_captured_file(receipt_capture, "WI-CLOSE-LINK-DRIFT")
                held.restore_owned_file(receipt_path, None)
            attempt("remove receipt", remove_receipt, receipt_path)
        if item_moved and target.exists() and not active.exists():
            attempt("restore active item", lambda: held.restore_owned_movement(target, active), target, active)
        if active.is_dir():
            restored_closure = active / "closure.md"
            restored_status = active / "status.md"
            if prior_closure is None:
                if restored_closure.exists():
                    attempt("remove closure", lambda: held.restore_owned_file(restored_closure, None), restored_closure)
            else:
                attempt(
                    "restore closure",
                    lambda: held.restore_owned_file(restored_closure, prior_closure),
                    restored_closure,
                )
            attempt("restore status", lambda: held.restore_owned_file(restored_status, prior_status), restored_status)
        elif not _lifecycle_cleanup_intersects_unsettled(active):
            rollback_incomplete = True
            composer.record_rollback_action(failure_id="WI-BUG-DISPOSITIONS-ROLLBACK",
                resource=active.relative_to(root).as_posix(),
                diagnostic="restore active item: active directory is unavailable")
        else:
            rollback_incomplete = True
        for plan in reversed(touched_bugs):
            assert plan.target is not None
            def restore_bug(plan=plan):
                failure_id = "WI-BUG-DISPOSITIONS-ROLLBACK"
                source_image = _read_lifecycle_image(
                    plan.source, plan.before, plan.after, failure_id=failure_id,
                )
                target_image = _read_lifecycle_image(
                    plan.target, plan.after, failure_id=failure_id,
                )
                if target_image is not None:
                    if source_image is not None or target_image != plan.after:
                        raise LifecycleError(failure_id, "bug rollback locations contain unowned images")
                    target_capture = _capture_file_snapshot(plan.target, failure_id=failure_id)
                    if target_capture.data != plan.after:
                        raise LifecycleError(failure_id, "bug rollback target differs")
                    if plan.source in written_link_captures:
                        _verify_captured_file(written_link_captures[plan.source], failure_id)
                    _verify_captured_file(target_capture, failure_id)
                    if _read_lifecycle_image(plan.source, plan.before, plan.after,
                                             failure_id=failure_id) is not None:
                        raise LifecycleError(failure_id, "bug rollback source is occupied")
                    held.restore_owned_movement(plan.target, plan.source)
                    source_capture = _capture_file_snapshot(plan.source, failure_id=failure_id)
                    if source_capture.identity != target_capture.identity:
                        raise LifecycleError(failure_id, "restored bug identity differs")
                else:
                    if source_image == plan.before:
                        return  # No published postimage, or already restored.
                    if source_image != plan.after:
                        raise LifecycleError(failure_id, "bug rollback source is not the owned postimage")
                    source_capture = _capture_file_snapshot(plan.source, failure_id=failure_id)
                    if plan.source in written_link_captures:
                        _verify_captured_file(written_link_captures[plan.source], failure_id)
                if source_capture.data != plan.after:
                    raise LifecycleError(failure_id, "bug rollback source changed")
                _verify_captured_file(source_capture, failure_id)
                held.restore_owned_file(plan.source, plan.before)
            attempt(f"restore bug {plan.bug_id}", restore_bug, plan.source, plan.target)
        for row in reversed(touched_links):
            def restore_link(row=row):
                capture = written_link_captures.get(row["path"])
                if capture is None:
                    if _read_lifecycle_image(row["path"], row["before"], row["after"],
                                             failure_id="WI-CLOSE-LINK-DRIFT") == row["before"]:
                        return
                    raise LifecycleError("WI-CLOSE-LINK-DRIFT", "owned URI image unavailable")
                _verify_captured_file(capture, "WI-CLOSE-LINK-DRIFT")
                held.restore_owned_file(row["path"], row["before"])
            attempt(f"restore URI consumer {row['pathRelative']}", restore_link, row["path"])
        if readme_existed:
            attempt("restore README", lambda: held.restore_owned_file(readme, readme_before), readme)
        elif readme.exists():
            def remove_generated_readme():
                transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
                expected = transaction._retained_observations.get(readme)
                if not isinstance(expected, CapturedFileSnapshot):
                    raise LifecycleError("WI-BUG-DISPOSITIONS-ROLLBACK", "generated README has no retained native proof")
                held.restore_owned_file(readme, None)
            attempt("remove generated README", remove_generated_readme, readme)
        for record in reversed(created_dirs):
            directory = record.locator
            if _lifecycle_cleanup_intersects_unsettled(directory):
                rollback_incomplete = True
                continue
            if not record.creation_published:
                continue  # The native creator already owns unpublished abort.
            def remove_created_directory(record=record):
                LifecycleWriteTarget.remove_created_directory(record, _CURRENT_LIFECYCLE_TRANSACTION.get(),
                    failure_id="WI-BUG-DISPOSITIONS-ROLLBACK")
            attempt("remove created directory", remove_created_directory, directory)
        composer.set_rollback("incomplete" if rollback_incomplete else "completed")
        if len(composer.rollback_actions) != first_rollback_action:
            outward = _bug_disposition_fail(
                "WI-BUG-DISPOSITIONS-ROLLBACK",
                "bug disposition rollback failed: " + composer.rollback_message(first_rollback_action),
            )
            outward.__cause__ = exc
            composer.designate_outward_failure(outward)
            raise outward from exc
        raise
    _settle_scratch_dispositions(root, scratch_plan)
    return target


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'archived_slug'))
def reopen_item(
    root: Path,
    archived_slug: str,
    successor_slug: str,
    status_data: bytes,
    *,
    inject_readme_failure: bool = False,
) -> Path:
    archived = resolve_category(root, f"work-item:{archived_slug}")
    if "archive" not in archived.parts:
        raise LifecycleError("WI-INVALID-TARGET", "reopen source must be archived")
    _validate_slug(successor_slug)
    _validate_active_status_bytes(status_data)
    fields = _parse_fields(status_data.decode("utf-8"))
    if fields.get("reopens") != archived_slug:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID",
            f"successor must declare Reopens: {archived_slug}",
        )
    if _category_locations(root, CATEGORIES["work-item"], successor_slug):
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "successor slug already exists")
    _preflight_readme(root)
    active_parent = _work_items_root(root) / "active"
    active_parent.mkdir(parents=True, exist_ok=True)
    target = active_parent / successor_slug
    temp = Path(tempfile.mkdtemp(prefix=f".{successor_slug}.", dir=active_parent))
    committed = False
    try:
        _atomic_write(temp / "status.md", status_data)
        _replace_lifecycle_directory(temp, target)
        committed = True
    finally:
        if not committed:
            if not _lifecycle_cleanup_intersects_unsettled(temp):
                shutil.rmtree(temp, ignore_errors=True)
    if inject_readme_failure:
        raise _postcommit_readme_stale("reopen")
    try:
        refresh_readme(root)
    except LifecycleError as exc:
        raise _postcommit_readme_stale("reopen") from exc
    return target


def audit_categories(root: Path) -> tuple[str, ...]:
    topology = _resolve_project_topology(root).with_read_model_roots()
    work_items = topology.work_items
    archive_inventory = _archive_entity_inventory(root)
    unbound = archive_inventory.observation(work_items)["unbound"]
    if unbound:
        raise LifecycleError("WI-ARCHIVE-ENTITY-UNBOUND", "unresolved archive entities: " +
                             ", ".join(row["path"] for row in unbound))
    if not topology.root_contract_present:
        topology.assert_known_top_level_roots()
    decision_v0_records = _preflight_current_decision_v0(root)
    decision_h1_records = _preflight_current_decision_h1(root)
    legacy_read_compatible: list[str] = []
    for category in CATEGORIES.values():
        slugs: set[str] = set()
        if category.current_kind == "work-item":
            slugs.update(path.stem for path in (work_items / "backlog").glob("*.md"))
            slugs.update(path.name for path in (work_items / "active").glob("*") if path.is_dir())
            archive = work_items / "archive"
        else:
            current = work_items / category.current_root
            slugs.update(path.stem for path in current.glob("*.md"))
            archive = current / "archive"
        if category.current_kind == "work-item":
            slugs.update(path.name for path in _archived_work_item_candidates(archive))
        elif archive.is_dir():
            for month in archive.iterdir():
                if not month.is_dir():
                    continue
                slugs.update(path.stem for path in month.glob("*.md"))
        for slug in sorted(slugs):
            locations = _category_locations(root, category, slug)
            if len(locations) > 1:
                raise LifecycleError(
                    "WI-CATEGORY-DUAL-LOCATION",
                    f"{category.name}:{slug} has {len(locations)} locations",
                )
            if not is_valid_slug(slug):
                if len(locations) != 1 or "archive" not in locations[0].parts:
                    _validate_slug(slug)
                legacy = locations[0]
                if category.name == "work-item":
                    entry = _archived_work_item_entry(legacy)
                    if entry.classification == LEGACY_READ_CLASSIFICATION:
                        fields = _parse_fields((legacy / "closure.md").read_text(encoding="utf-8"))
                        closed = fields.get("closed", "")
                        if not closed or not fields.get("outcome"):
                            raise LifecycleError(
                                "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
                                f"legacy archive lacks terminal evidence: {legacy}",
                            )
                        if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", closed) or closed[:7] != legacy.parent.name:
                            raise LifecycleError(
                                "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH",
                                f"{category.name}:{slug} does not match archive month",
                            )
                else:
                    instant = _validate_flat_terminal(category, legacy.read_bytes())
                    if legacy.parent.name != archive_month(instant):
                        raise LifecycleError(
                            "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH",
                            f"{category.name}:{slug} belongs in archive/{archive_month(instant)}",
                        )
                legacy_read_compatible.append(
                    legacy.relative_to(work_items).as_posix()
                )
                continue
            if category.current_kind == "work-item" and locations and locations[0].parent == work_items / "backlog":
                source = locations[0]
                failure = _current_readme_status_error(_parse_fields(source.read_text(encoding="utf-8")), "backlog", source)
                if failure is not None:
                    raise failure
            if category.current_kind == "flat" and locations:
                path = locations[0]
                archived = "archive" in path.parts
                decision_v0 = (
                    decision_v0_records.get(path.name)
                    if category.name == "decision" and not archived
                    else None
                )
                decision_h1 = (
                    decision_h1_records.get(path.name)
                    if category.name == "decision" and not archived
                    else None
                )
                if decision_v0 is not None:
                    status = decision_v0.raw_status
                elif decision_h1 is not None:
                    status = decision_h1.admitted_current_status or ""
                else:
                    fields = _parse_fields(path.read_text(encoding="utf-8"))
                    status = fields.get("status", "")
                if archived and status in category.current_statuses:
                    raise LifecycleError(
                        "WI-CATEGORY-CURRENT-IN-ARCHIVE",
                        f"{category.name}:{slug} has current status in archive",
                    )
                if not archived and status in category.terminal_statuses:
                    raise LifecycleError(
                        "WI-CATEGORY-TERMINAL-IN-CURRENT",
                        f"{category.name}:{slug} has terminal status in current root",
                    )
                if category.name == "roadmap" and not archived:
                    failure = _current_readme_status_error(fields, "roadmap", path)
                    if failure is not None:
                        raise failure
                if (
                    category.name == "decision"
                    and not archived
                    and status in category.current_statuses
                ):
                    decision = decision_v0 or decision_h1 or _validate_current_decision_record(path, slug)
                    if decision.format in {DECISION_FORMAT_V0, DECISION_FORMAT_H1}:
                        legacy_read_compatible.append(
                            path.relative_to(work_items).as_posix()
                        )

    active = work_items / "active"
    if active.is_dir():
        for item in sorted(path for path in active.iterdir() if path.is_dir()):
            if (item / BUG_DISPOSITIONS_MANIFEST).exists():
                raise LifecycleError(
                    "WI-BUG-DISPOSITIONS-PENDING",
                    f"work-item:{item.name} has an unapplied bug disposition manifest",
                )
            fields = _parse_fields((item / "status.md").read_text(encoding="utf-8"))
            failure = _current_readme_status_error(fields, "active", item / "status.md")
            if failure is not None:
                raise failure
    for item in _archived_work_item_candidates(work_items / "archive"):
        manifest = item / BUG_DISPOSITIONS_MANIFEST
        receipt = item / BUG_DISPOSITIONS_RECEIPT
        if not manifest.exists() and not receipt.exists():
            continue
        closure = item / "closure.md"
        if not closure.is_file():
            raise LifecycleError(
                "WI-IMMUTABLE-ARCHIVE",
                f"archived disposition owner lacks closure: {item.name}",
            )
        closure_data = closure.read_bytes()
        fields = _parse_fields(closure_data.decode("utf-8"))
        _verify_archived_bug_dispositions(
            root, item, closure_data, fields.get("closed", "")
        )
    return tuple(sorted(legacy_read_compatible))


def _validate_obligation_transfer_ownership(root: Path) -> None:
    transfer_errors = _validator_module().validate_obligation_transfer_ownership(
        Path(root).resolve()
    )
    if transfer_errors:
        failure_id = transfer_errors[0].split(":", 1)[0]
        if failure_id not in {
            "WI-OBLIGATION-TRANSFER-COVERAGE",
            "WI-OBLIGATION-TRANSFER-OWNER",
            "WI-OBLIGATION-TRANSFER-DRIFT",
        }:
            failure_id = "WI-OBLIGATION-TRANSFER-OWNER"
        raise LifecycleError(failure_id, "; ".join(transfer_errors))


def _transition_intent_operation_id(root: Path, intent_path: Path, *, intent: dict | None = None) -> str:
    intent = _load_transition_intent(root, intent_path) if intent is None else intent
    operation_id = intent.get("operationId")
    if not isinstance(operation_id, str):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "transition intent operation id is absent",
        )
    expected_path = _transition_intent_path(root, operation_id)
    if expected_path.absolute() != intent_path.absolute():
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "transition intent path differs from its operation id",
        )
    return operation_id


def audit(root: Path) -> tuple[str, ...]:
    pending_operations: list[str] = []
    for intent_path in _iter_transition_intents(root):
        pending_operations.append(
            _transition_intent_operation_id(root, intent_path)
        )
    if pending_operations:
        commands = "; ".join(
            "recover-transition --root <repo> "
            f"--operation-id {operation_id} --apply"
            for operation_id in pending_operations
        )
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-RECOVERY-REQUIRED",
            "pending lifecycle transition(s): "
            f"{', '.join(pending_operations)}; run: {commands}",
        )
    legacy_read_compatible = audit_categories(root)
    _validate_obligation_transfer_ownership(root)
    check_readme(root)
    return legacy_read_compatible


def retain_historical_pass_custody(
    root: Path, slug: str, run_id: str, raw_line_ordinal: int,
    expected_raw_line_sha256: str, expected_ledger_sha256: str,
    source_artifact: str, expected_original_sha256: str, *, apply: bool = False,
) -> Path:
    """Retain independently admitted original PASS bytes without rewriting its ledger.

    Missing apply refuses before acquiring a lifecycle transaction. Exact replay
    retains the original request's prefix digest even after later ledger appends.
    Matching readers must be deployed before the original artifact is removed.
    """
    if apply is not True:
        raise LifecycleError("WI-LEDGER-CUSTODY-APPLY-REQUIRED", "retain-pass-artifact requires explicit --apply")
    return _retain_historical_pass_custody(
        root, slug, run_id, raw_line_ordinal, expected_raw_line_sha256,
        expected_ledger_sha256, source_artifact, expected_original_sha256,
    )


@functools.partial(_lifecycle_participant, subject_parameters=("category-slug", "work-item", "slug"))
def _retain_historical_pass_custody(
    root: Path, slug: str, run_id: str, raw_line_ordinal: int,
    expected_raw_line_sha256: str, expected_ledger_sha256: str,
    source_artifact: str, expected_original_sha256: str,
) -> Path:
    stale = "WI-LEDGER-CUSTODY-STALE-TARGET"
    source_drift = "WI-LEDGER-CUSTODY-SOURCE-DRIFT"
    mismatch = "WI-LEDGER-CUSTODY-SNAPSHOT-MISMATCH"
    item = _active_migration_item(root, slug)
    ledger = _load_agent_run_ledger()
    validator = ledger.load_validator()
    if (
        type(raw_line_ordinal) is not int or raw_line_ordinal < 1
        or not isinstance(run_id, str) or not run_id
        or any(not isinstance(value, str) or validator.SHA256_RE.fullmatch(value) is None
               for value in (expected_raw_line_sha256, expected_ledger_sha256, expected_original_sha256))
    ):
        raise LifecycleError(stale, "request raw identity or lowercase SHA-256 is invalid")
    if (
        not isinstance(source_artifact, str) or not validator._safe_repo_relative(source_artifact)
        or source_artifact in {"", "."}
    ):
        raise LifecycleError(source_drift, "source artifact must be repository-relative")
    association_key = f"review-artifact-custody/historical-pass/{expected_raw_line_sha256}.json"
    association = _require_lifecycle_mutation_path(root, item / association_key, failure_id=stale)
    repository = _repository_root_for_item(item)
    with ledger.ledger_write_lock(item):
        captured = _capture_file_snapshot(
            item / "agent-runs.jsonl", failure_id=stale,
            maximum_bytes=validator.MAX_LEDGER_EVENTS * validator.MAX_LEDGER_LINE_BYTES,
        )
        raw = captured.data
        errors: list[str] = []
        metadata: list[dict[str, object]] = []
        events = validator.load_jsonl(captured.path, errors, metadata, raw)
        targets = [
            event for event, identity in zip(events, metadata)
            if identity["line"] == raw_line_ordinal
            and identity["sha256"] == expected_raw_line_sha256
            and event.get("runId") == run_id
        ]
        if errors or len(targets) != 1:
            raise LifecycleError(stale, "captured raw target differs")
        target = targets[0]
        if association.exists():
            existing = _capture_file_snapshot(association, failure_id=stale)
            try:
                envelope = validator.decode_json_object(existing.data, source=association_key)
            except ValueError as exc:
                raise LifecycleError(stale, "existing association is invalid") from exc
            if (
                envelope.get("sourcePrefixSha256") != expected_ledger_sha256
                or envelope.get("rawLineOrdinal") != raw_line_ordinal
                or envelope.get("rawLineSha256") != expected_raw_line_sha256
                or envelope.get("runId") != run_id
                or envelope.get("originalArtifact") != target.get("artifact")
                or envelope.get("snapshotSha256") != expected_original_sha256
            ):
                raise LifecycleError(stale, "replay request conflicts with immutable association")
            _, replay_errors = validator.resolve_historical_pass_custody(item, raw, events, metadata)
            if replay_errors:
                raise LifecycleError(replay_errors[0].split(":", 1)[0], "; ".join(replay_errors))
            _verify_captured_file(captured, stale)
            _verify_captured_file(existing, stale)
            return association
        if hashlib.sha256(raw).hexdigest() != expected_ledger_sha256:
            raise LifecycleError(stale, "complete captured ledger digest changed")
        try:
            original_bytes = ledger._ordinary_custody_source(repository, source_artifact)
        except ValueError as exc:
            raise LifecycleError(source_drift, str(exc)) from exc
        if hashlib.sha256(original_bytes).hexdigest() != expected_original_sha256:
            raise LifecycleError(source_drift, "independently admitted original digest differs")
        snapshot_key = f"review-artifact-custody/{expected_original_sha256}"
        envelope = _historical_pass_association(raw, target, raw_line_ordinal, expected_raw_line_sha256, expected_original_sha256)
        envelope_bytes = validator._canonical_projection_bytes(envelope)
        candidates = {association_key: envelope_bytes, snapshot_key: original_bytes}
        errors = validator.validate_work_item(
            item, strict_revise=False, historical_pass_custody_blobs=candidates,
            selected_ledger_bytes=raw,
        )
        if errors:
            failure_id = errors[0].split(":", 1)[0] if errors[0].startswith("WI-LEDGER-CUSTODY-") else stale
            raise LifecycleError(failure_id, "; ".join(errors))
        _verify_captured_file(captured, stale)
        owned: dict[str, Path] = {}
        owned_identities: dict[str, tuple[int, int]] = {}
        owned_snapshot = None
        created_directories: list[Path] = []
        published = False
        try:
            for directory in (item / "review-artifact-custody", association.parent):
                if not directory.exists():
                    directory.mkdir()
                    created_directories.append(directory)
            try:
                snapshot = ledger._acquire_custody_snapshot(
                    item, original_bytes, expected_original_sha256, validator, owned,
                    owned_identities=owned_identities,
                )
            except ValueError as exc:
                raise LifecycleError(mismatch, str(exc)) from exc
            if "snapshot" in owned:
                owned_snapshot = _capture_file_snapshot(snapshot, failure_id=mismatch, maximum_bytes=len(original_bytes))
            _verify_captured_file(captured, stale)
            if association.exists() or association.is_symlink():
                raise LifecycleError(stale, "association appeared before publication")
            _atomic_write(association, envelope_bytes)
            published = True
            return association
        finally:
            if not published:
                if owned_snapshot is None and "snapshot" in owned:
                    owned_snapshot = _capture_file_snapshot(
                        owned["snapshot"], failure_id=mismatch, maximum_bytes=len(original_bytes),
                    )
                    if (
                        owned_snapshot.identity != owned_identities.get("snapshot")
                        or not original_bytes.startswith(owned_snapshot.data)
                    ):
                        raise LifecycleError(mismatch, "unpublished snapshot ownership or bytes changed; preserved")
                if owned_snapshot is not None:
                    _verify_captured_file(owned_snapshot, mismatch)
                    owned_snapshot.path.unlink()
                for directory in reversed(created_directories):
                    if not any(directory.iterdir()):
                        directory.rmdir()


def _active_migration_item(root: Path, slug: str, *, input_role: str = "caller-root") -> Path:
    _validate_slug(slug)
    item = _work_items_root(root, input_role=input_role) / "active" / slug
    if not item.is_dir() or _lifecycle_path_has_reparse(item):
        raise LifecycleError("WI-INVALID-TARGET", f"active work item is missing or unsafe: {slug}")
    return item


def _repository_root_for_item(item: Path) -> Path:
    for parent in (item, *item.parents):
        if parent.name == "work-items":
            return parent.parent
    raise LifecycleError("WI-INVALID-TARGET", "path is not owned by a work-items root")


def _require_lifecycle_mutation_path(root: Path, path: Path, *, failure_id: str,
    acquired_input=None,
) -> Path:
    path = _lifecycle_unresolved_absolute(path)
    _input_reject_reparse(
        path, failure_id=failure_id, message="lifecycle mutation path contains a link or reparse point"
    , acquired_input=acquired_input)
    repository = _lifecycle_unresolved_absolute(Path(root))
    _input_reject_reparse(
        repository, failure_id=failure_id, message="repository root contains a link or reparse point"
    , acquired_input=acquired_input)
    repository = _input_resolve(repository, acquired_input)
    candidate = _input_resolve(path, acquired_input, strict=False)
    try:
        candidate.relative_to(repository)
    except ValueError as exc:
        raise LifecycleError(failure_id, "lifecycle mutation path escapes repository") from exc
    return path


def _migration_receipt_bytes(facts: dict) -> bytes:
    return (json.dumps(facts, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8")


def _migration_receipt_current(target: LifecycleWriteTarget, wanted: bytes) -> bytes | None:
    current = target.read()
    if current is not None and current != wanted:
        quarantine = f"{target.leaf}.conflict-{_sha256_bytes(current)[:16]}"
        prior = target.read(quarantine)
        if prior is not None and prior != current:
            raise LifecycleError("WI-LEDGER-MIGRATION-RECEIPT-MISMATCH", "receipt quarantine conflicts")
    return current


def _reconcile_migration_receipt(item: Path, facts: dict, *, target: LifecycleWriteTarget | None = None) -> None:
    root = _repository_root_for_item(item)
    receipt = _require_lifecycle_mutation_path(
        root, item / "ledger-migration-receipts" / f"{facts['operationId']}.json",
        failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
    )
    if target is None:
        with _admit_lifecycle_write_target(receipt, failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH") as acquired:
            _reconcile_migration_receipt(item, facts, target=acquired)
        return
    if type(target) is not LifecycleWriteTarget or target.path != receipt or not target._open:
        raise LifecycleError("WI-LIFECYCLE-WRITE-BOUNDARY", "receipt target does not bind destination")
    wanted = _migration_receipt_bytes(facts)
    current = _migration_receipt_current(target, wanted)
    if current == wanted:
        target.verify()
        return
    if current is not None:
        target.quarantine(current)
    _atomic_write(receipt, wanted, target=target)
    if target.read(maximum_bytes=len(wanted)) != wanted:
        raise LifecycleError("WI-LEDGER-MIGRATION-RECEIPT-MISMATCH", "receipt readback differs")
    target.verify()


def _committed_migration_facts(
    item: Path,
    *,
    target_run_id: str,
    target_event_sha256: str,
    expected_before_sha256: str,
    operation_id: str,
    normalization_kind: str,
) -> dict | None:
    ledger_owner = _load_agent_run_ledger()
    ledger_path = item / "agent-runs.jsonl"
    root = _repository_root_for_item(item)
    ledger_path = _require_lifecycle_mutation_path(
        root, ledger_path, failure_id="WI-LEDGER-MIGRATION-TOPOLOGY"
    )
    data = ledger_path.read_bytes()
    raw_lines = data.splitlines(keepends=True)
    validator = ledger_owner.load_validator()
    parse_errors: list[str] = []
    metadata: list[dict[str, object]] = []
    events = validator.load_jsonl(ledger_path, parse_errors, metadata)
    if parse_errors:
        raise LifecycleError("WI-LEDGER-MIGRATION-TOPOLOGY", "; ".join(parse_errors))
    _effective, _counters, projection_errors = validator.project_legacy_obligation_migrations(
        events, metadata, item
    )
    if projection_errors:
        raise LifecycleError("WI-LEDGER-MIGRATION-TOPOLOGY", "; ".join(projection_errors))
    for index, raw in enumerate(raw_lines):
        text = raw.rstrip(b"\r\n")
        try:
            event = json.loads(text.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError):
            continue
        if event.get("runId") != f"ledger-migration-{operation_id}":
            continue
        control_errors: list[str] = []
        validator.validate_event(event, item, set(), control_errors)
        if control_errors:
            raise LifecycleError("WI-LEDGER-MIGRATION-TOPOLOGY", "; ".join(control_errors))
        if (
            event.get("eventKind") != "legacy-obligation-migration"
            or event.get("migrationAction") != "apply"
            or event.get("normalizationKind", "invalid-finding-class") != normalization_kind
            or event.get("migratesRunId") != target_run_id
            or event.get("migratesEventSha256") != target_event_sha256
        ):
            raise LifecycleError("WI-LEDGER-MIGRATION-TOPOLOGY", "operation id is bound to different inputs")
        before = b"".join(raw_lines[:index])
        if _sha256_bytes(before) != expected_before_sha256:
            raise LifecycleError("WI-LEDGER-MIGRATION-TOPOLOGY", "committed operation has a different before digest")
        replacement = event.get("replacementEvent")
        if not isinstance(replacement, dict):
            raise LifecycleError("WI-LEDGER-MIGRATION-TOPOLOGY", "committed anchor replacement is missing")
        target = next(
            (
                candidate for candidate, candidate_metadata in zip(events[:index], metadata[:index])
                if candidate.get("runId") == target_run_id
                and candidate_metadata.get("sha256") == target_event_sha256
            ),
            None,
        )
        if target is None:
            raise LifecycleError("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "committed target no longer resolves")
        finding_class = target.get("findingClass") if normalization_kind == "remove-string-scratch-evidence" else "legacy-unclassified"
        diagnostic_id = (
            validator.LEDGER_EVENT_SCRATCH_EVIDENCE_INVALID
            if normalization_kind == "remove-string-scratch-evidence"
            else "LEDGER-EVENT-FINDING-CLASS-INVALID"
        )
        committed_after = b"".join(raw_lines[: index + 1])
        facts = {
            "schemaVersion": 1,
            "status": "committed",
            "operationId": operation_id,
            "targetRunId": target_run_id,
            "targetEventSha256": target_event_sha256,
            "anchorRunId": event["runId"],
            "anchorEventSha256": _sha256_bytes(text),
            "beforeLedgerBytes": len(before),
            "beforeLedgerSha256": _sha256_bytes(before),
            "afterLedgerBytes": len(committed_after),
            "afterLedgerSha256": _sha256_bytes(committed_after),
            "replacementEventSha256": _sha256_bytes(ledger_owner.serialize_event(replacement).encode("utf-8")),
            "normalizationKind": normalization_kind,
            "diagnosticId": diagnostic_id,
            "sourcePath": f"work-items/active/{item.name}/agent-runs.jsonl",
            "receiptPath": f"work-items/active/{item.name}/ledger-migration-receipts/{operation_id}.json",
            "recordedAt": event["startedAt"],
        }
        if finding_class is not None:
            facts["findingClass"] = finding_class
        return facts
    return None


def _migrate_legacy_ledger_obligation_locked(
    root: Path,
    slug: str,
    target_run_id: str,
    target_event_sha256: str,
    expected_ledger_sha256: str,
    operation_id: str,
    recorded_at: str,
    normalization_kind: str,
    *,
    inject_failure: str | None = None,
) -> dict:
    item = _active_migration_item(root, slug)
    committed = _committed_migration_facts(
        item,
        target_run_id=target_run_id,
        target_event_sha256=target_event_sha256,
        expected_before_sha256=expected_ledger_sha256,
        operation_id=operation_id,
        normalization_kind=normalization_kind,
    )
    if committed is not None:
        _reconcile_migration_receipt(item, committed)
        return committed
    ledger_owner = _load_agent_run_ledger()
    try:
        staged = ledger_owner.stage_legacy_obligation_migration(
            item,
            target_run_id,
            target_event_sha256,
            expected_ledger_sha256,
            operation_id,
            recorded_at,
            normalization_kind,
        )
    except ledger_owner.LedgerMigrationError as exc:
        raise LifecycleError(exc.failure_id, str(exc)) from exc
    ledger_path = item / "agent-runs.jsonl"
    ledger_path = _require_lifecycle_mutation_path(
        root, ledger_path, failure_id="WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE"
    )
    receipt_path = _require_lifecycle_mutation_path(
        root, item / "ledger-migration-receipts" / f"{staged.receipt_facts['operationId']}.json",
        failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
    )
    with _admit_lifecycle_write_target(receipt_path, failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH") as receipt_target:
        _migration_receipt_current(receipt_target, _migration_receipt_bytes(staged.receipt_facts))
        _atomic_write(ledger_path, staged.staged_bytes)
        if inject_failure == "post-replace-corrupt":
            ledger_path.write_bytes(staged.staged_bytes + b"corrupt")
        try:
            actual = ledger_path.read_bytes()
        except OSError as exc:
            raise LifecycleError("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "ledger readback failed") from exc
        if _sha256_bytes(actual) != staged.receipt_facts["afterLedgerSha256"]:
            raise LifecycleError("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "ledger is neither exact before nor exact after")
        if inject_failure == "after-anchor":
            raise LifecycleError("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "injected crash after anchor")
        _reconcile_migration_receipt(item, staged.receipt_facts, target=receipt_target)
        return staged.receipt_facts


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def migrate_legacy_ledger_obligation(
    root: Path,
    slug: str,
    target_run_id: str,
    target_event_sha256: str,
    expected_ledger_sha256: str,
    operation_id: str,
    recorded_at: str,
    *,
    normalization_kind: str = "invalid-finding-class",
    inject_failure: str | None = None,
) -> dict:
    item = _active_migration_item(root, slug)
    ledger_owner = _load_agent_run_ledger()
    try:
        with ledger_owner.ledger_write_lock(item):
            return _migrate_legacy_ledger_obligation_locked(
                root, slug, target_run_id, target_event_sha256,
                expected_ledger_sha256, operation_id, recorded_at,
                normalization_kind,
                inject_failure=inject_failure,
            )
    except ledger_owner.LedgerWriteLockError as exc:
        raise LifecycleError("WI-LIFECYCLE-LOCK-HELD", str(exc)) from exc


def _revoke_legacy_ledger_obligation_locked(
    root: Path,
    slug: str,
    apply_run_id: str,
    apply_event_sha256: str,
    expected_ledger_sha256: str,
    operation_id: str,
    recorded_at: str,
) -> dict:
    item = _active_migration_item(root, slug)
    if (item / "lifecycle-transition-receipt.json").exists() or any(
        item.glob("lifecycle-transition-*.json")
    ):
        raise LifecycleError("WI-LEDGER-MIGRATION-REVOCATION-FROZEN", "physical transition has started")
    ledger_owner = _load_agent_run_ledger()
    ledger_owner._strict_migration_inputs(operation_id, recorded_at)
    ledger_path = item / "agent-runs.jsonl"
    ledger_path = _require_lifecycle_mutation_path(
        root, ledger_path, failure_id="WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE"
    )
    before = ledger_path.read_bytes()
    if _sha256_bytes(before) != expected_ledger_sha256:
        raise LifecycleError("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "ledger digest changed")
    validator = ledger_owner.load_validator()
    errors: list[str] = []
    metadata: list[dict[str, object]] = []
    events = validator.load_jsonl(ledger_path, errors, metadata)
    positions = [i for i, event in enumerate(events) if event.get("runId") == apply_run_id]
    if len(positions) != 1:
        raise LifecycleError("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "apply anchor is missing or non-unique")
    pos = positions[0]
    apply_event = events[pos]
    if (
        apply_event.get("eventKind") != "legacy-obligation-migration"
        or apply_event.get("migrationAction") != "apply"
        or metadata[pos].get("sha256") != apply_event_sha256
    ):
        raise LifecycleError("WI-LEDGER-MIGRATION-TARGET-DIGEST", "apply anchor digest changed")
    if any(event.get("eventKind") == "legacy-obligation-migration" and event.get("migrationAction") == "revoke" and event.get("revokesMigrationRunId") == apply_run_id for event in events):
        raise LifecycleError("WI-LEDGER-MIGRATION-TOPOLOGY", "apply already revoked")
    normalization_kind = apply_event.get("normalizationKind", "invalid-finding-class")
    row = validator.LEGACY_MIGRATION_NORMALIZATIONS.get(normalization_kind)
    if row is None:
        raise LifecycleError("WI-LEDGER-MIGRATION-NORMALIZATION-KIND", "apply normalization kind is not closed")
    revoke = {
        "schemaVersion": 2,
        "runId": f"ledger-migration-{operation_id}",
        "workItem": apply_event["workItem"],
        "role": "lead",
        "executionRole": "main",
        "status": "completed",
        "gate": "none",
        "scope": row["scope"],
        "eventKind": "legacy-obligation-migration",
        "migrationAction": "revoke",
        "revokesMigrationRunId": apply_run_id,
        "revokesMigrationEventSha256": apply_event_sha256,
        "evidence": [{"kind": "manual-check", "ref": f"revoke {apply_run_id} {apply_event_sha256}"}],
        "startedAt": recorded_at,
        "updatedAt": recorded_at,
    }
    line = ledger_owner.serialize_event(revoke).encode("utf-8") + b"\n"
    candidate = before + (b"" if before.endswith(b"\n") else b"\n") + line
    temporary = item / ".ledger-revoke-candidate.jsonl"
    try:
        temporary.write_bytes(candidate)
        parse_errors: list[str] = []
        candidate_metadata: list[dict[str, object]] = []
        candidate_events = validator.load_jsonl(temporary, parse_errors, candidate_metadata)
        control_errors: list[str] = []
        validator.validate_event(revoke, item, {str(event.get("runId", "")).casefold() for event in events}, control_errors)
        _effective, _counters, projection_errors = validator.project_legacy_obligation_migrations(
            candidate_events, candidate_metadata, item
        )
        candidate_errors = parse_errors + control_errors + projection_errors
    finally:
        temporary.unlink(missing_ok=True)
    if candidate_errors:
        raise LifecycleError("WI-LEDGER-MIGRATION-CANDIDATE-INVALID", "; ".join(candidate_errors))
    _atomic_write(ledger_path, candidate)
    return {
        "schemaVersion": 1,
        "status": "revoked",
        "operationId": operation_id,
        "applyRunId": apply_run_id,
        "applyEventSha256": apply_event_sha256,
        "afterLedgerSha256": _sha256_bytes(candidate),
        "recordedAt": recorded_at,
    }


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def revoke_legacy_ledger_obligation(
    root: Path,
    slug: str,
    apply_run_id: str,
    apply_event_sha256: str,
    expected_ledger_sha256: str,
    operation_id: str,
    recorded_at: str,
) -> dict:
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
    )
    transition_root = repository / ".scratch" / "work-items-lifecycle-transitions"
    if transition_root.is_dir():
        _lifecycle_reject_unreduced_reparse(
            transition_root,
            failure_id="WI-LEDGER-MIGRATION-REVOCATION-FROZEN",
            message="transition staging root is a link or reparse point",
        )
        for intent_path in _bounded_transition_intent_inventory(
            transition_root,
            failure_id="WI-LEDGER-MIGRATION-REVOCATION-FROZEN",
            unreadable="transition staging root is unreadable",
        ):
            intent = _load_transition_intent(root, intent_path)
            if intent.get("slug") == slug:
                raise LifecycleError(
                    "WI-LEDGER-MIGRATION-REVOCATION-FROZEN",
                    "physical transition intent already exists",
                )
    locations = _category_locations(root, CATEGORIES["work-item"], slug)
    if any("archive" in path.parts for path in locations):
        raise LifecycleError(
            "WI-LEDGER-MIGRATION-REVOCATION-FROZEN",
            "work item is already archived",
        )
    item = _active_migration_item(root, slug)
    ledger_owner = _load_agent_run_ledger()
    try:
        with ledger_owner.ledger_write_lock(item):
            return _revoke_legacy_ledger_obligation_locked(
                root, slug, apply_run_id, apply_event_sha256,
                expected_ledger_sha256, operation_id, recorded_at,
            )
    except ledger_owner.LedgerWriteLockError as exc:
        raise LifecycleError("WI-LIFECYCLE-LOCK-HELD", str(exc)) from exc


