def _bounded_transition_intent_inventory(
    directory: Path, *, failure_id: str, unreadable: str,
    acquired_input=None,
) -> list[Path]:
    """Inventory transition intents within finite count and byte budgets."""
    candidates: list[Path] = []
    total_bytes = 0
    json_suffix = os.path.normcase(".json")
    try:
        with _input_directory_inventory(directory, acquired_input) as entries:
            for entry_count, path in enumerate(entries, start=1):
                if entry_count > TRANSITION_INTENT_INVENTORY_MAX_ENTRIES:
                    raise LifecycleError(
                        failure_id, "transition intent inventory limit exceeded"
                    )
                if not os.path.normcase(path.name).endswith(json_suffix):
                    continue
                metadata = _input_metadata(path, acquired_input)
                if (
                    not stat.S_ISREG(metadata.st_mode)
                    or stat.S_ISLNK(metadata.st_mode)
                    or metadata.st_nlink != 1
                    or bool(
                        getattr(metadata, "st_file_attributes", 0)
                        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
                    )
                ):
                    raise LifecycleError(
                        failure_id, "transition intent is not an owned regular file"
                    )
                if metadata.st_size > TRANSITION_INTENT_FILE_BYTE_CAP:
                    raise LifecycleError(
                        failure_id, "transition intent byte limit exceeded"
                    )
                total_bytes += metadata.st_size
                if total_bytes > TRANSITION_INTENT_INVENTORY_BYTE_CAP:
                    raise LifecycleError(
                        failure_id, "transition intent cumulative byte limit exceeded"
                    )
                candidates.append(path)
    except LifecycleError:
        raise
    except OSError as exc:
        raise LifecycleError(failure_id, unreadable) from exc
    return sorted(candidates)


def _validate_transfer_migration_receipt_bindings(
    root: Path,
    archive_path: object,
    value: object,
    *,
    failure_id: str,
    acquired_input=None,
) -> tuple[dict[str, str], ...]:
    if not isinstance(archive_path, str) or not isinstance(value, list):
        raise LifecycleError(failure_id, "migration receipt binding list differs")
    expected_parent = PurePosixPath(archive_path) / "ledger-migration-receipts"
    rows: list[dict[str, str]] = []
    paths: list[str] = []
    for row in value:
        if (
            not isinstance(row, dict)
            or set(row) != MIGRATION_RECEIPT_BINDING_FIELDS
            or not isinstance(row.get("path"), str)
            or not isinstance(row.get("sha256"), str)
            or SHA256_RE.fullmatch(row["sha256"]) is None
        ):
            raise LifecycleError(failure_id, "migration receipt binding row differs")
        path = row["path"]
        _intent_path(root, path, acquired_input=acquired_input)
        pure = PurePosixPath(path)
        if pure.parent != expected_parent or pure.suffix != ".json":
            raise LifecycleError(failure_id, "migration receipt binding path differs")
        paths.append(path)
        rows.append({"path": path, "sha256": row["sha256"]})
    if paths != sorted(paths, key=lambda item: item.encode("utf-8")) or len(
        paths
    ) != len(set(paths)):
        raise LifecycleError(
            failure_id, "migration receipt binding paths are not sorted and unique"
        )
    return tuple(rows)


@dataclass(frozen=True)
class WorkItemLedgerLocationV1:
    logical_work_item: str
    logical_ledger_path: str
    physical_work_item: str
    physical_ledger_path: str
    phase: Literal["active", "active-intent", "moved-intent", "settled-archive"]
    ledger_sha256: str
    operation_id: str | None
    provenance_path: str | None
    provenance_sha256: str | None


def _validate_successor_transfer_fields(
    successor_data: bytes, source_slug: str, operation_id: str
) -> None:
    try:
        text = successor_data.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-COVERAGE", "successor transfer fields require UTF-8"
        ) from exc
    occurrences = _authoritative_field_occurrences(text)
    expected = {"continues": source_slug, "obligation-transfer": operation_id}
    for field, value in expected.items():
        matches = [observed for _line, name, observed, _raw in occurrences if name == field]
        if matches != [value]:
            raise LifecycleError(
                "WI-OBLIGATION-TRANSFER-COVERAGE",
                f"successor requires exactly one {field} field bound to {value}",
            )


def _transfer_relation_fields(data: bytes, *, required: bool) -> tuple[str, str] | None:
    try:
        text = data.decode("utf-8", errors="strict")
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-OWNER", "transfer relation fields require UTF-8"
        ) from exc
    occurrences = _authoritative_field_occurrences(text)
    values = {
        name: [value for _line, observed, value, _raw in occurrences if observed == name]
        for name in ("continues", "obligation-transfer")
    }
    if not any(values.values()) and not required:
        return None
    if any(len(values[name]) != 1 or not values[name][0] for name in values):
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-OWNER",
            "transfer owner requires exactly one Continues and Obligation-transfer field",
        )
    return values["continues"][0], values["obligation-transfer"][0]


def _validate_started_transfer_relation(
    backlog_data: bytes, status_data: bytes
) -> tuple[str, str] | None:
    backlog_relation = _transfer_relation_fields(backlog_data, required=False)
    status_relation = _transfer_relation_fields(status_data, required=False)
    if backlog_relation != status_relation:
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-OWNER",
            "active status must preserve the backlog transfer owner fields exactly",
        )
    return backlog_relation


def _inspect_transfer_obligations(root: Path, item: Path) -> tuple[object, ...]:
    validator = _validator_module()
    status_text = (item / "status.md").read_text(encoding="utf-8")
    v1_staged = _parse_fields(status_text).get("template") == "staged"
    states: list[object] = []
    errors = validator.validate_work_item(
        item,
        strict_revise=False,
        validate_status_file=not v1_staged,
        obligation_state_out=states,
    )
    if v1_staged:
        _validate_active_status_bytes(status_text.encode("utf-8"))
    if errors:
        raise LifecycleError("WI-LEDGER-UNSETTLED", "; ".join(errors))
    if len(states) != 1:
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-COVERAGE", "validator did not return one obligation state"
        )
    state = states[0]
    if state.unresolved_history:
        history_errors: list[str] = []
        validator._history_hold_errors(state.unresolved_history, history_errors)
        raise LifecycleError("WI-LEDGER-HISTORY-UNRESOLVED", "; ".join(history_errors))
    if state.open_launches:
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-COVERAGE", "running launches cannot be transferred"
        )
    return state.open_revise


def _prepare_obligation_transfer(
    root: Path,
    active: Path,
    archive: Path,
    slug: str,
    successor_slug: str,
    successor_data: bytes,
    operation_id: str,
    expected_ledger_sha256: str,
    transfer_data: bytes,
) -> tuple[dict, list[dict], str, tuple[CapturedFileSnapshot, ...]]:
    validator = _validator_module()
    try:
        payload = validator.decode_json_object(
            transfer_data,
            source="obligation transfer input",
            maximum_bytes=max(1, len(transfer_data)),
        )
    except ValueError as exc:
        raise LifecycleError("WI-OBLIGATION-TRANSFER-COVERAGE", str(exc)) from exc
    required = {
        "schemaVersion", "sourceWorkItem", "successorWorkItem",
        "expectedSourceLedgerSha256", "obligations",
    }
    if (
        set(payload) != required
        or payload.get("schemaVersion") != 1
        or payload.get("sourceWorkItem") != slug
        or payload.get("successorWorkItem") != successor_slug
        or payload.get("expectedSourceLedgerSha256") != expected_ledger_sha256
        or not isinstance(payload.get("obligations"), list)
    ):
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-COVERAGE", "obligation transfer input shape or owner binding differs"
        )
    _validate_successor_transfer_fields(successor_data, slug, operation_id)
    open_rows = _inspect_transfer_obligations(root, active)
    row_fields = {
        "runId", "rawLineOrdinal", "rawLineSha256", "rawEventSha256",
        "projectedEventSha256",
    }
    declared: dict[tuple[str, int, str, str, str], dict] = {}
    declared_run_ids: set[str] = set()
    for row in payload["obligations"]:
        if not isinstance(row, dict) or set(row) != row_fields:
            raise LifecycleError(
                "WI-OBLIGATION-TRANSFER-COVERAGE", "obligation row shape differs"
            )
        identity = (
            row.get("runId"), row.get("rawLineOrdinal"), row.get("rawLineSha256"),
            row.get("rawEventSha256"), row.get("projectedEventSha256"),
        )
        if (
            not isinstance(identity[0], str)
            or type(identity[1]) is not int
            or identity[1] < 1
            or any(not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None for value in identity[2:])
            or identity in declared
            or identity[0] in declared_run_ids
        ):
            raise LifecycleError(
                "WI-OBLIGATION-TRANSFER-COVERAGE", "duplicate or invalid obligation identity"
            )
        declared[identity] = row
        declared_run_ids.add(identity[0])
    observed = {
        (
            row.run_id, row.raw_line_ordinal, row.raw_line_sha256,
            row.raw_event_sha256, row.projected_event_sha256,
        ): row
        for row in open_rows
    }
    declared_positions = {(identity[0], identity[1]) for identity in declared}
    observed_positions = {(identity[0], identity[1]) for identity in observed}
    if declared_positions != observed_positions or len(observed) != len(open_rows):
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-COVERAGE", "declared obligations do not exactly cover open REVISE rows"
        )
    if set(declared) != set(observed):
        raise LifecycleError(
            "WI-OBLIGATION-TRANSFER-DRIFT", "declared obligation evidence bindings differ"
        )
    archive_relative = archive.relative_to(Path(root).resolve()).as_posix()
    archive_identity = validator.archived_ledger_identity(
        archive_relative, expected_ledger_sha256
    )
    obligations = []
    for identity in sorted(observed, key=lambda value: (value[1], value[0].encode("utf-8"))):
        row = observed[identity]
        obligations.append({
            **declared[identity],
            "obligationId": (
                row.obligation_id
                if row.obligation_id is not None
                else validator.obligation_transfer_id(
                    archive_identity,
                    row.raw_line_ordinal,
                    row.raw_line_sha256,
                    row.raw_event_sha256,
                    row.run_id,
                )
            ),
            "predecessorOperationId": row.predecessor_operation_id,
        })
    migration_receipts = sorted(
        (active / "ledger-migration-receipts").glob("*.json"),
        key=lambda path: path.relative_to(active).as_posix().encode("utf-8"),
    )
    ledger_owner = _load_agent_run_ledger()
    migrated_rows = {
        (
            row.run_id,
            _sha256_bytes(
                ledger_owner.serialize_event(dict(row.event)).encode("utf-8")
            ),
        ): row
        for row in open_rows
        if row.source_kind == "migration-replaced"
    }
    if len(migrated_rows) != sum(
        row.source_kind == "migration-replaced" for row in open_rows
    ) or len(migration_receipts) != len(migrated_rows):
        raise LifecycleError(
            "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
            "transfer requires the exact migration receipt set",
        )
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
    )
    snapshots: dict[tuple[str, str], CapturedFileSnapshot] = {}
    for migration_receipt in migration_receipts:
        snapshot = _capture_file_snapshot(
            migration_receipt,
            failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
        )
        try:
            facts = validator.decode_json_object(
                snapshot.data,
                source=str(migration_receipt),
                maximum_bytes=max(1, len(snapshot.data)),
            )
        except ValueError as exc:
            raise LifecycleError(
                "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
                "migration receipt is not one strict JSON object",
            ) from exc
        required_strings = (
            "operationId",
            "targetRunId",
            "targetEventSha256",
            "beforeLedgerSha256",
            "replacementEventSha256",
            "normalizationKind",
        )
        if any(not isinstance(facts.get(key), str) for key in required_strings):
            raise LifecycleError(
                "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
                "migration receipt identity fields differ",
            )
        try:
            canonical_facts = _committed_migration_facts(
                active,
                target_run_id=facts["targetRunId"],
                target_event_sha256=facts["targetEventSha256"],
                expected_before_sha256=facts["beforeLedgerSha256"],
                operation_id=facts["operationId"],
                normalization_kind=facts["normalizationKind"],
            )
        except LifecycleError as exc:
            raise LifecycleError(
                "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
                "migration receipt does not reconstruct from the source ledger",
            ) from exc
        actual_path = migration_receipt.relative_to(repository).as_posix()
        identity = (facts["targetRunId"], facts["replacementEventSha256"])
        if (
            canonical_facts is None
            or canonical_facts != facts
            or facts.get("receiptPath") != actual_path
            or identity not in migrated_rows
            or identity in snapshots
        ):
            raise LifecycleError(
                "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
                "migration receipt set does not match migrated open obligations",
            )
        snapshots[identity] = snapshot
    if set(snapshots) != set(migrated_rows):
        raise LifecycleError(
            "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
            "migration receipt set does not exactly cover migrated open obligations",
        )
    return (
        payload,
        obligations,
        archive_identity,
        tuple(
            sorted(
                snapshots.values(),
                key=lambda snapshot: snapshot.path.relative_to(repository)
                .as_posix()
                .encode("utf-8"),
            )
        ),
    )


def _b64(data: bytes | None) -> str | None:
    return None if data is None else base64.b64encode(data).decode("ascii")


def _unb64(value: str | None) -> bytes | None:
    if value is None:
        return None
    try:
        return base64.b64decode(value, validate=True)
    except (ValueError, TypeError) as exc:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "invalid intent byte image") from exc


def _bug_successor_binding_fail(message: str) -> LifecycleError:
    return LifecycleError("WI-BUG-SUCCESSOR-BINDING", message)


def _bug_successor_json_pairs(pairs: list[tuple[str, object]]) -> dict:
    value: dict[str, object] = {}
    for key, item in pairs:
        if key in value:
            raise _bug_successor_binding_fail(f"successor binding repeats JSON key: {key}")
        value[key] = item
    return value


def _bug_successor_single_line(payload: dict, key: str) -> str:
    value = payload.get(key)
    if (
        not isinstance(value, str)
        or not value.strip()
        or len(value) > BUG_DISPOSITION_TEXT_LIMIT
        or "\n" in value
        or "\r" in value
    ):
        raise _bug_successor_binding_fail(
            f"successor binding {key} must be one non-empty bounded line"
        )
    return value


def _parse_bug_successor_binding_data(
    slug: str,
    binding_data: bytes | None,
    operation_id: str,
) -> dict:
    if binding_data is None:
        raise _bug_successor_binding_fail("successor binding is required")
    try:
        payload = json.loads(
            binding_data.decode("utf-8"), object_pairs_hook=_bug_successor_json_pairs
        )
    except LifecycleError:
        raise
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise _bug_successor_binding_fail("successor binding is not strict UTF-8 JSON") from exc
    if (
        not isinstance(payload, dict)
        or set(payload) != BUG_SUCCESSOR_BINDING_FIELDS
        or payload.get("schemaVersion") != 1
    ):
        raise _bug_successor_binding_fail("successor binding shape differs")
    for key in (
        "operationId",
        "sourceReference",
        "registryReference",
        "recordReference",
        "recordSha256",
        "acceptedBy",
        "acceptedAt",
        "acceptanceEvidence",
    ):
        _bug_successor_single_line(payload, key)
    if (
        payload["operationId"] != operation_id
        or payload["sourceReference"] != f"bug:{slug}"
        or not SHA256_RE.fullmatch(payload["recordSha256"])
    ):
        raise _bug_successor_binding_fail("successor binding identity differs")
    try:
        _strict_utc(payload["acceptedAt"])
    except LifecycleError as exc:
        raise _bug_successor_binding_fail("successor acceptance time differs") from exc
    return payload


def _parse_bug_successor_binding(
    slug: str,
    successor_record: Path,
    binding_data: bytes | None,
    operation_id: str,
) -> tuple[dict, CapturedFileSnapshot]:
    payload = _parse_bug_successor_binding_data(slug, binding_data, operation_id)
    try:
        successor = _capture_file_snapshot(
            Path(successor_record), failure_id="WI-BUG-SUCCESSOR-BINDING"
        )
    except LifecycleError as exc:
        raise _bug_successor_binding_fail("successor record identity differs") from exc
    if _sha256_bytes(successor.data) != payload["recordSha256"]:
        raise _bug_successor_binding_fail("successor record hash differs")
    return payload, successor


def _bug_supersession_inventory_pairs(pairs: list[tuple[str, object]]) -> dict:
    value: dict[str, object] = {}
    for key, item in pairs:
        if key in value:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY",
                f"bug successor inventory repeats JSON key: {key}",
            )
        value[key] = item
    return value


def _parse_bug_supersession_inventory(data: bytes) -> dict:
    try:
        payload = json.loads(
            data.decode("utf-8"), object_pairs_hook=_bug_supersession_inventory_pairs
        )
    except LifecycleError:
        raise
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "bug successor inventory is not strict UTF-8 JSON",
        ) from exc
    if (
        not isinstance(payload, dict)
        or set(payload) != BUG_SUPERSESSION_INVENTORY_FIELDS
        or payload.get("schemaVersion") != 1
        or payload.get("owner") != BUG_SUPERSESSION_OWNER
        or not isinstance(payload.get("links"), list)
    ):
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "bug successor inventory shape differs",
        )
    paths: list[str] = []
    for row in payload["links"]:
        if (
            not isinstance(row, dict)
            or set(row) != BUG_SUPERSESSION_INVENTORY_LINK_FIELDS
            or not isinstance(row.get("path"), str)
            or not row["path"]
            or not isinstance(row.get("beforeSha256"), str)
            or not SHA256_RE.fullmatch(row["beforeSha256"])
            or not isinstance(row.get("afterSha256"), str)
            or not SHA256_RE.fullmatch(row["afterSha256"])
            or not isinstance(row.get("afterBytesBase64"), str)
        ):
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY",
                "bug successor inventory link row differs",
            )
        paths.append(row["path"])
    if paths != sorted(paths) or len(paths) != len(set(paths)):
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "bug successor inventory paths are not sorted and unique",
        )
    return payload


def _bug_successor_link_after(
    consumer: Path,
    source: Path,
    before: bytes,
    source_reference: str,
    successor_reference: str,
) -> bytes:
    try:
        text = before.decode("utf-8")
    except UnicodeError as exc:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            f"bug successor link consumer is not UTF-8: {consumer}",
        ) from exc
    replacements = [
        (link.href_start, link.href_end)
        for link in _markdown_local_links(text)
        if _markdown_href_resolves(consumer.parent, link.href, source)
    ]
    for start, end in reversed(replacements):
        text = text[:start] + successor_reference + text[end:]
    text = text.replace(source_reference, successor_reference)
    return text.encode("utf-8")


def _prepare_bug_supersession_links(
    root: Path,
    source: Path,
    source_reference: str,
    successor_reference: str,
    inventory: dict,
) -> list[dict]:
    current = _incoming_link_result(
        root,
        {source},
        source_reference,
        mutable_consumers_only=True,
        strict_consumer_reads=True,
    )
    repository = _work_items_root(root).parent
    expected_paths = sorted(
        {
            (repository / "work-items" / row["consumer"]).relative_to(repository).as_posix()
            for row in current["references"]
        }
    )
    supplied_paths = [row["path"] for row in inventory["links"]]
    if supplied_paths != expected_paths:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "bug successor inventory does not exactly cover live incoming links",
        )
    plans: list[dict] = []
    for row in inventory["links"]:
        path = _intent_path(root, row["path"])
        try:
            snapshot = _capture_file_snapshot(
                path, failure_id="WI-CATEGORY-MIGRATION-INVENTORY"
            )
            after = base64.b64decode(row["afterBytesBase64"], validate=True)
        except (LifecycleError, ValueError, TypeError) as exc:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY",
                f"bug successor link image cannot be captured: {row['path']}",
            ) from exc
        expected_after = _bug_successor_link_after(
            path, source, snapshot.data, source_reference, successor_reference
        )
        if (
            _sha256_bytes(snapshot.data) != row["beforeSha256"]
            or _sha256_bytes(after) != row["afterSha256"]
            or after != expected_after
            or after == snapshot.data
        ):
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY",
                f"bug successor link image differs: {row['path']}",
            )
        plans.append(
            {
                "path": path,
                "pathRelative": row["path"],
                "before": snapshot.data,
                "after": after,
                "beforeSha256": row["beforeSha256"],
                "afterSha256": row["afterSha256"],
            }
        )
    return plans


def _precompute_single_bug_readme_sha256(
    root: Path,
    source: Path,
    archive: Path,
    source_after: bytes,
    links: list[dict],
) -> str:
    work_items = _work_items_root(root)
    repository = work_items.parent
    static_guide = _static_guide(work_items / "README.md")
    transaction_token = _CURRENT_LIFECYCLE_TRANSACTION.set(None)
    composer_token = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.set(None)
    try:
        with tempfile.TemporaryDirectory(prefix="single-bug-readme-") as directory:
            shadow_root = Path(directory)
            shadow_work_items = shadow_root / "work-items"
            shutil.copytree(work_items, shadow_work_items, symlinks=True)

            def shadow(path: Path) -> Path:
                return shadow_root / path.relative_to(repository)

            for plan in links:
                _atomic_write(shadow(plan["path"]), plan["after"])
            shadow_source = shadow(source)
            shadow_archive = shadow(archive)
            _atomic_write(shadow_source, source_after)
            shadow_archive.parent.mkdir(parents=True, exist_ok=True)
            os.replace(shadow_source, shadow_archive)
            rendered = render_readme_bytes(
                shadow_root, static_guide_override=static_guide
            )
        return _sha256_bytes(rendered)
    finally:
        _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.reset(composer_token)
        _CURRENT_LIFECYCLE_TRANSACTION.reset(transaction_token)


def _bug_supersession_receipt_payload(
    *,
    operation_id: str,
    terminal_instant: str,
    source_reference: str,
    source_path: str,
    archive_path: str,
    archived_bug_sha256: str,
    binding_data: bytes,
    binding: dict,
    inventory_data: bytes,
    links: list[dict],
    readme_sha256: str,
    expected_bug_sha256: str,
    expected_readme_sha256: str,
) -> dict:
    return {
        "schemaVersion": 1,
        "owner": BUG_SUPERSESSION_OWNER,
        "kind": BUG_SUPERSESSION_KIND,
        "status": "settled",
        "operationId": operation_id,
        "terminalInstant": terminal_instant,
        "sourceReference": source_reference,
        "sourcePath": source_path,
        "archivePath": archive_path,
        "archivedBugSha256": archived_bug_sha256,
        "successorBindingSha256": _sha256_bytes(binding_data),
        "successorRegistryReference": binding["registryReference"],
        "successorRecordReference": binding["recordReference"],
        "successorRecordSha256": binding["recordSha256"],
        "acceptedBy": binding["acceptedBy"],
        "acceptedAt": binding["acceptedAt"],
        "acceptanceEvidence": binding["acceptanceEvidence"],
        "incomingLinksInventorySha256": _sha256_bytes(inventory_data),
        "links": [
            {
                "path": row["pathRelative"] if "pathRelative" in row else row["path"],
                "beforeSha256": row["beforeSha256"],
                "afterSha256": row["afterSha256"],
            }
            for row in links
        ],
        "readmeSha256": readme_sha256,
        "requestExpectedBugSha256": expected_bug_sha256,
        "requestExpectedReadmeSha256": expected_readme_sha256,
    }


def _bug_supersession_replay(
    root: Path,
    slug: str,
    receipt_path: Path,
    successor_binding_data: bytes | None,
    incoming_links_inventory_data: bytes,
    terminal_instant: str,
    expected_bug_sha256: str,
    expected_readme_sha256: str,
    operation_id: str,
) -> dict:
    try:
        binding = _parse_bug_successor_binding_data(
            slug, successor_binding_data, operation_id
        )
        inventory = _parse_bug_supersession_inventory(
            incoming_links_inventory_data
        )
        receipt = _verify_bug_supersession_settlement(root, receipt_path)
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "bug supersession replay evidence differs",
        ) from exc
    inventory_links = [
        {
            "path": row["path"],
            "beforeSha256": row["beforeSha256"],
            "afterSha256": row["afterSha256"],
        }
        for row in inventory["links"]
    ]
    if (
        receipt["operationId"] != operation_id
        or receipt["terminalInstant"] != terminal_instant
        or receipt["sourceReference"] != f"bug:{slug}"
        or receipt["successorBindingSha256"]
        != _sha256_bytes(successor_binding_data or b"")
        or receipt["successorRegistryReference"] != binding["registryReference"]
        or receipt["successorRecordReference"] != binding["recordReference"]
        or receipt["successorRecordSha256"] != binding["recordSha256"]
        or receipt["acceptedBy"] != binding["acceptedBy"]
        or receipt["acceptedAt"] != binding["acceptedAt"]
        or receipt["acceptanceEvidence"] != binding["acceptanceEvidence"]
        or receipt["incomingLinksInventorySha256"]
        != _sha256_bytes(incoming_links_inventory_data)
        or receipt["links"] != inventory_links
        or receipt["requestExpectedBugSha256"] != expected_bug_sha256
        or receipt["requestExpectedReadmeSha256"] != expected_readme_sha256
        or inventory["operationId"] != operation_id
        or inventory["sourceReference"] != f"bug:{slug}"
        or inventory["sourceBugSha256"] != expected_bug_sha256
        or inventory["successorBindingSha256"]
        != _sha256_bytes(successor_binding_data or b"")
    ):
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "bug supersession replay inputs differ",
        )
    return receipt


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'bug', 'slug'))
def supersede_current_bug(
    root: Path,
    slug: str,
    successor_record: Path,
    successor_binding_data: bytes | None,
    terminal_instant: str,
    incoming_links_inventory_data: bytes,
    expected_bug_sha256: str,
    expected_readme_sha256: str,
    operation_id: str,
    *,
    inject_failure_at: str | None = None,
) -> dict:
    month = archive_month(terminal_instant)
    intent_path = _transition_intent_path(root, operation_id)
    work_items = _work_items_root(root)
    repository = work_items.parent
    source_reference = f"bug:{slug}"
    source = work_items / "bugs" / f"{slug}.md"
    archive = work_items / "bugs" / "archive" / month / f"{slug}.md"
    receipt = archive.with_name(f"{slug}.supersession-receipt.json")
    _recover_all_transitions(root)
    if receipt.is_file():
        return _bug_supersession_replay(
            root,
            slug,
            receipt,
            successor_binding_data,
            incoming_links_inventory_data,
            terminal_instant,
            expected_bug_sha256,
            expected_readme_sha256,
            operation_id,
        )
    binding, successor_snapshot = _parse_bug_successor_binding(
        slug, successor_record, successor_binding_data, operation_id
    )
    if (
        not isinstance(expected_bug_sha256, str)
        or not SHA256_RE.fullmatch(expected_bug_sha256)
        or not isinstance(expected_readme_sha256, str)
        or not SHA256_RE.fullmatch(expected_readme_sha256)
    ):
        raise LifecycleError(
            "WI-BUG-DISPOSITIONS-DRIFT", "bug supersession request hash differs"
        )
    locations = _category_locations(root, CATEGORIES["bug"], slug)
    if locations != [source]:
        failure_id = "WI-CATEGORY-DUAL-LOCATION" if locations else "WI-REFERENCE-MISSING"
        raise LifecycleError(failure_id, "bug supersession source is not uniquely current")
    if archive.exists() or receipt.exists():
        raise LifecycleError(
            "WI-CATEGORY-DUAL-LOCATION", "bug supersession archive or receipt already exists"
        )
    source_snapshot = _capture_file_snapshot(
        source, failure_id="WI-BUG-DISPOSITIONS-DRIFT"
    )
    if _sha256_bytes(source_snapshot.data) != expected_bug_sha256:
        raise LifecycleError(
            "WI-BUG-DISPOSITIONS-DRIFT", "bug supersession source hash differs"
        )
    fields = _parse_fields(source_snapshot.data.decode("utf-8"))
    current_status = fields.get("status", "")
    if current_status not in CATEGORIES["bug"].current_statuses:
        raise LifecycleError(
            "WI-BUG-DISPOSITIONS-DRIFT", "bug supersession source is not current"
        )
    readme = work_items / "README.md"
    readme_snapshot = _capture_file_snapshot(
        readme, failure_id="WI-README-STALE"
    )
    if _sha256_bytes(readme_snapshot.data) != expected_readme_sha256:
        raise LifecycleError("WI-README-STALE", "bug supersession README hash differs")
    binding_data = successor_binding_data or b""
    inventory = _parse_bug_supersession_inventory(incoming_links_inventory_data)
    if (
        inventory["operationId"] != operation_id
        or inventory["sourceReference"] != source_reference
        or inventory["sourceBugSha256"] != expected_bug_sha256
        or inventory["successorBindingSha256"] != _sha256_bytes(binding_data)
    ):
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "bug successor inventory binding differs",
        )
    successor_reference = (
        f"{binding['registryReference']}#{binding['recordReference']}"
    )
    links = _prepare_bug_supersession_links(
        root,
        source,
        source_reference,
        successor_reference,
        inventory,
    )
    source_after = _terminal_bug_bytes(
        source_snapshot.data,
        current_status=current_status,
        terminal_status="superseded",
        terminal_instant=terminal_instant,
        resolution=f"Superseded by {successor_reference}.",
        evidence=binding["acceptanceEvidence"],
        successor=successor_reference,
    )
    _validate_flat_terminal(CATEGORIES["bug"], source_after)
    final_readme_sha256 = _precompute_single_bug_readme_sha256(
        root, source, archive, source_after, links
    )
    source_path = source.relative_to(repository).as_posix()
    archive_path = archive.relative_to(repository).as_posix()
    receipt_path = receipt.relative_to(repository).as_posix()
    receipt_payload = _bug_supersession_receipt_payload(
        operation_id=operation_id,
        terminal_instant=terminal_instant,
        source_reference=source_reference,
        source_path=source_path,
        archive_path=archive_path,
        archived_bug_sha256=_sha256_bytes(source_after),
        binding_data=binding_data,
        binding=binding,
        inventory_data=incoming_links_inventory_data,
        links=links,
        readme_sha256=final_readme_sha256,
        expected_bug_sha256=expected_bug_sha256,
        expected_readme_sha256=expected_readme_sha256,
    )
    receipt_after = _migration_receipt_bytes(receipt_payload)
    intent = {
        "schemaVersion": 1,
        "owner": BUG_SUPERSESSION_OWNER,
        "kind": BUG_SUPERSESSION_KIND,
        "status": "intent",
        "operationId": operation_id,
        "terminalInstant": terminal_instant,
        "sourcePath": source_path,
        "archivePath": archive_path,
        "receiptPath": receipt_path,
        "expectedReadmeSha256": expected_readme_sha256,
        "finalReadmeSha256": final_readme_sha256,
        "sourceBefore": _b64(source_snapshot.data),
        "sourceAfter": _b64(source_after),
        "receiptBefore": None,
        "receiptAfter": _b64(receipt_after),
        "successorBindingSha256": _sha256_bytes(binding_data),
        "successorRegistryReference": binding["registryReference"],
        "successorRecordReference": binding["recordReference"],
        "successorRecordSha256": binding["recordSha256"],
        "acceptedBy": binding["acceptedBy"],
        "acceptedAt": binding["acceptedAt"],
        "acceptanceEvidence": binding["acceptanceEvidence"],
        "incomingLinksInventorySha256": _sha256_bytes(
            incoming_links_inventory_data
        ),
        "links": [
            {
                "path": row["pathRelative"],
                "before": _b64(row["before"]),
                "after": _b64(row["after"]),
                "beforeSha256": row["beforeSha256"],
                "afterSha256": row["afterSha256"],
            }
            for row in links
        ],
    }
    _verify_captured_file(successor_snapshot, "WI-BUG-SUCCESSOR-BINDING")
    return _apply_single_bug_transition(
        root, source_snapshot, readme_snapshot, source, archive, source_after,
        links, intent_path, intent, inject_failure_at=inject_failure_at,
    )


def _single_bug_failure_id(intent: dict, phase: str) -> str:
    prefix = (
        "WI-FIXED-BUG" if intent["kind"] == FIXED_BUG_ARCHIVE_KIND
        else "WI-BUG-SUPERSESSION"
    )
    return f"{prefix}-{phase}-INDETERMINATE"


def _single_bug_transition_label(intent: dict) -> str:
    return "fixed-bug archive" if intent["kind"] == FIXED_BUG_ARCHIVE_KIND else "bug supersession"


def _apply_single_bug_transition(
    root: Path,
    source_snapshot: CapturedFileSnapshot,
    readme_snapshot: CapturedFileSnapshot,
    source: Path,
    archive: Path,
    source_after: bytes,
    links: list[dict],
    intent_path: Path,
    intent: dict,
    *,
    inject_failure_at: str | None,
) -> dict:
    rollback_id = _single_bug_failure_id(intent, "ROLLBACK")
    forward_id = _single_bug_failure_id(intent, "ROLLFORWARD")
    failpoint = "F" if intent["kind"] == FIXED_BUG_ARCHIVE_KIND else "B"
    preflight_id = (
        "WI-BUG-DISPOSITIONS-DRIFT" if intent["kind"] == BUG_SUPERSESSION_KIND
        else "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING"
    )
    readme_preflight_id = (
        "WI-BUG-DISPOSITIONS-DRIFT" if intent["kind"] == BUG_SUPERSESSION_KIND
        else "WI-README-STALE"
    )
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        transaction.verify()
    _verify_captured_file(source_snapshot, preflight_id)
    _verify_captured_file(readme_snapshot, readme_preflight_id)
    for row in links:
        if _read_lifecycle_image(row["path"], row["before"], failure_id=rollback_id) != row["before"]:
            raise LifecycleError(rollback_id, f"bug link drifted: {row['pathRelative']}")
    _atomic_write(intent_path, _migration_receipt_bytes(intent))
    _transition_fsync_directory(intent_path.parent)
    if inject_failure_at == f"{failpoint}0":
        raise LifecycleError(rollback_id, f"injected {failpoint}0")
    for row in links:
        if _read_lifecycle_image(row["path"], row["before"], failure_id=rollback_id) != row["before"]:
            raise LifecycleError(rollback_id, f"bug link drifted: {row['pathRelative']}")
        _atomic_write(row["path"], row["after"])
    if inject_failure_at == f"{failpoint}1":
        raise LifecycleError(rollback_id, f"injected {failpoint}1")
    _verify_captured_file(source_snapshot, rollback_id)
    _atomic_write(source, source_after)
    if inject_failure_at == f"{failpoint}2":
        raise LifecycleError(rollback_id, f"injected {failpoint}2")
    if transaction is not None:
        transaction.verify()
    LifecycleWriteTarget.make_directories(archive.parent, transaction)
    _replace_lifecycle_directory(source, archive, directory=False)
    if inject_failure_at == f"{failpoint}3":
        raise LifecycleError(forward_id, f"injected {failpoint}3")
    return _recover_single_bug_transition(
        root, intent_path, intent, inject_failure_at=inject_failure_at,
    )


def _fixed_bug_terminal_image(
    source: bytes, slug: str, terminal_instant: str, resolution: str, evidence: str,
    root: Path,
) -> bytes:
    for label, value in (("resolution", resolution), ("evidence", evidence)):
        if not value or len(value) > 4096 or any(character in value for character in "\r\n\x00"):
            raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", f"{label} must be one bounded line")
    try:
        text = source.decode("utf-8")
    except UnicodeError as exc:
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "bug record must be UTF-8") from exc
    occurrences = _authoritative_field_occurrences(text)
    by_name: dict[str, list[str]] = {}
    for _line, name, value, _raw in occurrences:
        by_name.setdefault(name, []).append(value)
    for name in ("id", "context", "status", "terminal-at", "resolution", "evidence"):
        if len(by_name.get(name, [])) > 1:
            raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", f"duplicate bug {name} field")
    if by_name.get("id") != [slug] or by_name.get("status") != ["fixed"]:
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "bug identity or fixed status differs")
    context = by_name.get("context", [""])[0]
    if not SLUG_RE.fullmatch(context):
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "bug context is not a work-item slug")
    work_items = _work_items_root(root)
    parent = resolve_category(root, f"work-item:{context}")
    if parent == (work_items / "active" / context).resolve():
        pass  # preserve existing active-parent admission
    elif parent.is_dir() and parent.parent.parent == (work_items / "archive").resolve():
        _archived_work_item_entry(parent)
    else:
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "bug parent is not active or archived")
    required = {"terminal-at": terminal_instant, "resolution": resolution, "evidence": evidence}
    for name, value in required.items():
        if name in by_name and by_name[name] != [value]:
            raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", f"bug {name} conflicts with request")
    additions = [f"- {name}: {value}\n" for name, value in required.items() if name not in by_name]
    after = source + ((b"\n" if source and not source.endswith(b"\n") else b"") + "".join(additions).encode("utf-8") if additions else b"")
    if _validate_flat_terminal(CATEGORIES["bug"], after) != terminal_instant:
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "bug terminal instant differs")
    return after


def _physical_archive_link_plans(
    root: Path, source: Path, archive: Path, references: list[dict],
    *, failure_id: str,
    include_descendants: bool = False,
    consumer_images: Mapping[Path, BugDispositionPlan] | None = None,
) -> list[dict]:
    repository = _work_items_root(root).parent
    physical_paths: set[str] = set()
    for row in references:
        if row["kind"] != "physical":
            continue
        if "archive" in PurePosixPath(row["consumer"]).parts:
            raise LifecycleError(failure_id, "immutable archived consumer has a physical link")
        physical_paths.add(row["consumer"])
    referenced_paths = set(physical_paths)
    referenced_hrefs = {(row["consumer"], row["value"]) for row in references if row["kind"] == "physical"}
    source_resolved = source.resolve()
    if consumer_images is not None:
        physical_paths.update(
            path.relative_to(_work_items_root(root)).as_posix()
            for path in consumer_images
        )
    plans: list[dict] = []
    for relative in sorted(physical_paths):
        consumer = _work_items_root(root) / relative
        snapshot = _capture_file_snapshot(consumer, failure_id=failure_id)
        image = consumer_images.get(consumer) if consumer_images is not None else None
        if image is not None and (image.source != consumer or snapshot.data != image.before):
            raise LifecycleError(failure_id, f"consumer image changed: {relative}")
        final_consumer = (image.target or image.source) if image is not None else consumer
        try:
            text = (image.after if image is not None else snapshot.data).decode("utf-8")
        except UnicodeError as exc:
            raise LifecycleError(failure_id, f"consumer is not UTF-8: {relative}") from exc
        replacements: list[tuple[int, int, str]] = []
        for link in _markdown_local_links(text):
            parts = _local_markdown_href_parts(link.href)
            if parts is None:
                continue
            candidate = consumer.parent / parts[0]
            if include_descendants:
                lexical = Path(os.path.abspath(candidate))
                if (relative, link.href) not in referenced_hrefs and not (
                    lexical == source_resolved or source_resolved in lexical.parents
                ):
                    continue
                _lifecycle_reject_unreduced_reparse(
                    candidate, failure_id=failure_id,
                    message=f"link target crosses a link or reparse point: {relative}",
                )
            candidate = candidate.resolve()
            if candidate == source_resolved or (include_descendants and source_resolved in candidate.parents):
                destination = archive / candidate.relative_to(source_resolved)
                href = os.path.relpath(destination, final_consumer.parent).replace(os.sep, "/") + parts[1]
                replacements.append((link.href_start, link.href_end, href))
        literal_changes = []
        for reference in references:
            if reference["consumer"] != relative or reference["kind"] != "physical":
                continue
            value = reference["value"].replace("\\", "/")
            if value in {source.relative_to(repository).as_posix(), source.relative_to(_work_items_root(root)).as_posix()}:
                if not any(link.href == reference["value"] and (consumer.parent / (_local_markdown_href_parts(link.href) or ("",))[0]).resolve() == source_resolved
                           for link in _markdown_local_links(text)):
                    pattern = _incoming_literal_pattern(value)
                    if pattern.search(text):
                        literal_changes.append((pattern, archive.relative_to(repository).as_posix()))
        if not replacements and not literal_changes:
            if image is not None and relative not in referenced_paths:
                continue
            raise LifecycleError(failure_id, f"physical link has no safe rewrite: {relative}")
        for start, end, href in reversed(replacements):
            text = text[:start] + href + text[end:]
        for pattern, replacement in literal_changes:
            text = pattern.sub(lambda _match: replacement, text)
        after = text.encode("utf-8")
        plans.append({
            "path": consumer,
            "pathRelative": consumer.relative_to(repository).as_posix(),
            "before": snapshot.data,
            "after": after,
            "beforeSha256": _sha256_bytes(snapshot.data),
            "afterSha256": _sha256_bytes(after),
        })
    return plans


def _fixed_bug_link_plans(root: Path, source: Path, archive: Path, slug: str) -> list[dict]:
    references = _incoming_link_result(
        root, {source}, f"bug:{slug}", strict_consumer_reads=True,
    )["references"]
    return _physical_archive_link_plans(
        root, source, archive, references, failure_id="WI-FIXED-BUG-LINK-INVENTORY"
    )


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'bug', 'slug'))
def archive_fixed_bug(
    root: Path, slug: str, terminal_instant: str, resolution: str, evidence: str,
    *, inject_failure_at: str | None = None,
) -> dict:
    month = archive_month(terminal_instant)
    work_items = _work_items_root(root)
    repository = work_items.parent
    source = work_items / "bugs" / f"{slug}.md"
    archive = work_items / "bugs" / "archive" / month / f"{slug}.md"
    receipt = archive.with_name(f"{slug}.fixed-archive-receipt.json")
    _recover_all_transitions(root)
    locations = _category_locations(root, CATEGORIES["bug"], slug)
    if locations == [archive] and receipt.is_file():
        settled = _verify_fixed_bug_archive_settlement(root, receipt)
        fields = _parse_fields(archive.read_text(encoding="utf-8"))
        if (settled["terminalInstant"], fields.get("resolution"), fields.get("evidence")) != (
            terminal_instant, resolution, evidence,
        ):
            raise LifecycleError("WI-FIXED-BUG-SETTLEMENT-MISMATCH", "fixed bug replay request differs")
        return settled
    if locations != [source] or archive.exists() or receipt.exists():
        failure_id = "WI-CATEGORY-DUAL-LOCATION" if locations else "WI-REFERENCE-MISSING"
        raise LifecycleError(failure_id, "fixed bug source is not uniquely current")
    source_snapshot = _capture_file_snapshot(source, failure_id="WI-CATEGORY-TERMINAL-EVIDENCE-MISSING")
    source_after = _fixed_bug_terminal_image(
        source_snapshot.data, slug, terminal_instant, resolution, evidence, root,
    )
    links = _fixed_bug_link_plans(root, source, archive, slug)
    readme_snapshot = _capture_file_snapshot(work_items / "README.md", failure_id="WI-README-STALE")
    final_readme_sha256 = _precompute_single_bug_readme_sha256(
        root, source, archive, source_after, links,
    )
    operation_id = f"fixed-bug-{uuid.uuid4().hex}"
    intent_path = _transition_intent_path(root, operation_id)
    if os.path.lexists(intent_path):
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "fixed bug intent identity collides")
    source_path = source.relative_to(repository).as_posix()
    archive_path = archive.relative_to(repository).as_posix()
    receipt_path = receipt.relative_to(repository).as_posix()
    receipt_payload = {
        "schemaVersion": 1, "owner": FIXED_BUG_ARCHIVE_OWNER,
        "kind": FIXED_BUG_ARCHIVE_KIND, "status": "settled",
        "operationId": operation_id, "sourceReference": f"bug:{slug}",
        "sourcePath": source_path, "archivePath": archive_path,
        "terminalInstant": terminal_instant,
        "sourceBeforeSha256": _sha256_bytes(source_snapshot.data),
        "archivedBugSha256": _sha256_bytes(source_after),
        "links": [
            {"path": row["pathRelative"], "beforeSha256": row["beforeSha256"],
             "afterSha256": row["afterSha256"]}
            for row in links
        ],
        "readmeSha256": final_readme_sha256,
    }
    intent = {
        "schemaVersion": 1, "owner": FIXED_BUG_ARCHIVE_OWNER,
        "kind": FIXED_BUG_ARCHIVE_KIND, "status": "intent",
        "operationId": operation_id, "terminalInstant": terminal_instant,
        "sourcePath": source_path, "archivePath": archive_path,
        "receiptPath": receipt_path,
        "expectedReadmeSha256": _sha256_bytes(readme_snapshot.data),
        "finalReadmeSha256": final_readme_sha256,
        "sourceBefore": _b64(source_snapshot.data), "sourceAfter": _b64(source_after),
        "receiptBefore": None,
        "receiptAfter": _b64(_migration_receipt_bytes(receipt_payload)),
        "links": [
            {"path": row["pathRelative"], "before": _b64(row["before"]),
             "after": _b64(row["after"]), "beforeSha256": row["beforeSha256"],
             "afterSha256": row["afterSha256"]}
            for row in links
        ],
    }
    return _apply_single_bug_transition(
        root, source_snapshot, readme_snapshot, source, archive, source_after,
        links, intent_path, intent, inject_failure_at=inject_failure_at,
    )


def _validate_transition_operation_id(operation_id: str) -> None:
    if re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}", operation_id, re.ASCII) is None:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "invalid transition operation id")


def _transition_intent_path(root: Path, operation_id: str,
    *,
    acquired_input=None,
) -> Path:
    _validate_transition_operation_id(operation_id)
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
     acquired_input=acquired_input)
    return repository / ".scratch" / "work-items-lifecycle-transitions" / f"{operation_id}.json"


def _transition_fsync_directory(path: Path) -> None:
    descriptor = None
    native_handle = None
    try:
        if os.name == "nt":
            import ctypes
            import ctypes.wintypes
            import msvcrt

            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            create_file = kernel32.CreateFileW
            create_file.argtypes = [
                ctypes.wintypes.LPCWSTR, ctypes.wintypes.DWORD, ctypes.wintypes.DWORD,
                ctypes.wintypes.LPVOID, ctypes.wintypes.DWORD, ctypes.wintypes.DWORD,
                ctypes.wintypes.HANDLE,
            ]
            create_file.restype = ctypes.wintypes.HANDLE
            native_handle = create_file(
                str(path), 0x40000000, 0x00000001 | 0x00000002 | 0x00000004,
                None, 3, 0x02000000 | 0x00200000, None,
            )
            if native_handle == ctypes.wintypes.HANDLE(-1).value:
                native_handle = None
                raise OSError(ctypes.get_last_error(), "cannot open transition directory")
            descriptor = msvcrt.open_osfhandle(native_handle, os.O_RDWR)
            native_handle = None
        else:
            descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0) | getattr(os, "O_NOFOLLOW", 0))
        if not stat.S_ISDIR(os.fstat(descriptor).st_mode):
            raise OSError(errno.ENOTDIR, "transition parent is not a directory")
        os.fsync(descriptor)
    except OSError as exc:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "transition directory cannot be durably synced") from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)
        elif native_handle is not None:
            import ctypes
            ctypes.WinDLL("kernel32", use_last_error=True).CloseHandle(native_handle)


def _intent_path(root: Path, relative: str,
    *,
    acquired_input=None,
) -> Path:
    pure = Path(relative)
    if pure.is_absolute() or ".." in pure.parts:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "intent path is not repository-relative")
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
     acquired_input=acquired_input)
    path = repository.joinpath(*pure.parts)
    return _require_lifecycle_mutation_path(
        repository, path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID"
    , acquired_input=acquired_input)



def _verify_bug_supersession_settlement(
    root: Path,
    receipt_path: Path,
    expected_bytes: bytes | None = None,
) -> dict:
    receipt_path = _require_lifecycle_mutation_path(
        root,
        receipt_path,
        failure_id="WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
    )
    payload, receipt_bytes = _ledger_location_proof_object(
        receipt_path,
        failure_id="WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
        unreadable="bug supersession receipt is unreadable",
    )
    if (
        not isinstance(payload, dict)
        or set(payload) != BUG_SUPERSESSION_RECEIPT_FIELDS
        or payload.get("schemaVersion") != 1
        or payload.get("owner") != BUG_SUPERSESSION_OWNER
        or payload.get("kind") != BUG_SUPERSESSION_KIND
        or payload.get("status") != "settled"
        or not isinstance(payload.get("links"), list)
        or any(
            not isinstance(payload.get(key), str)
            for key in BUG_SUPERSESSION_RECEIPT_FIELDS - {"schemaVersion", "links"}
        )
    ):
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "bug supersession receipt shape differs",
        )
    try:
        category, slug = _canonical_category(payload["sourceReference"])
        month = archive_month(payload["terminalInstant"])
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "bug supersession receipt identity differs",
        ) from exc
    repository = _work_items_root(root).parent
    expected_source = repository / "work-items" / "bugs" / f"{slug}.md"
    expected_archive = (
        repository
        / "work-items"
        / "bugs"
        / "archive"
        / month
        / f"{slug}.md"
    )
    expected_receipt = expected_archive.with_name(
        f"{slug}.supersession-receipt.json"
    )
    if (
        category.name != "bug"
        or payload["sourcePath"] != expected_source.relative_to(repository).as_posix()
        or payload["archivePath"] != expected_archive.relative_to(repository).as_posix()
        or receipt_path.resolve() != expected_receipt.resolve()
        or expected_source.exists()
        or not SHA256_RE.fullmatch(payload["archivedBugSha256"])
        or not SHA256_RE.fullmatch(payload["successorBindingSha256"])
        or not SHA256_RE.fullmatch(payload["successorRecordSha256"])
        or not SHA256_RE.fullmatch(payload["incomingLinksInventorySha256"])
        or not SHA256_RE.fullmatch(payload["readmeSha256"])
        or not SHA256_RE.fullmatch(payload["requestExpectedBugSha256"])
        or not SHA256_RE.fullmatch(payload["requestExpectedReadmeSha256"])
    ):
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "bug supersession receipt binding differs",
        )
    try:
        archived = _capture_file_snapshot(
            expected_archive,
            failure_id="WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
        )
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "archived bug identity differs",
        ) from exc
    try:
        fields = _parse_fields(archived.data.decode("utf-8"))
    except UnicodeError as exc:
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "archived bug is not UTF-8",
        ) from exc
    successor_reference = (
        f"{payload['successorRegistryReference']}#{payload['successorRecordReference']}"
    )
    if (
        _sha256_bytes(archived.data) != payload["archivedBugSha256"]
        or fields.get("status") != "superseded"
        or fields.get("terminal-at") != payload["terminalInstant"]
        or fields.get("successor") != successor_reference
        or fields.get("evidence") != payload["acceptanceEvidence"]
    ):
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "archived bug settlement differs",
        )
    link_paths: list[str] = []
    for row in payload["links"]:
        if (
            not isinstance(row, dict)
            or set(row) != {"path", "beforeSha256", "afterSha256"}
            or not isinstance(row.get("path"), str)
            or not isinstance(row.get("beforeSha256"), str)
            or not SHA256_RE.fullmatch(row["beforeSha256"])
            or not isinstance(row.get("afterSha256"), str)
            or not SHA256_RE.fullmatch(row["afterSha256"])
        ):
            raise LifecycleError(
                "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
                "bug supersession receipt link row differs",
            )
        link_paths.append(row["path"])
        path = _intent_path(root, row["path"])
        if _ledger_location_regular_sha256(
            path,
            failure_id="WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
        ) != row["afterSha256"]:
            raise LifecycleError(
                "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
                f"bug supersession settled link differs: {row['path']}",
            )
    readme = _work_items_root(root) / "README.md"
    if (
        link_paths != sorted(link_paths)
        or len(link_paths) != len(set(link_paths))
        or _ledger_location_regular_sha256(
            readme,
            failure_id="WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
        ) != payload["readmeSha256"]
        or (expected_bytes is not None and receipt_bytes != expected_bytes)
    ):
        raise LifecycleError(
            "WI-BUG-SUPERSESSION-SETTLEMENT-MISMATCH",
            "bug supersession settled bytes differ",
        )
    return payload


def _verify_fixed_bug_archive_settlement(
    root: Path, receipt_path: Path, expected_bytes: bytes | None = None,
) -> dict:
    failure_id = "WI-FIXED-BUG-SETTLEMENT-MISMATCH"
    receipt_path = _require_lifecycle_mutation_path(root, receipt_path, failure_id=failure_id)
    payload, receipt_bytes = _ledger_location_proof_object(
        receipt_path, failure_id=failure_id, unreadable="fixed bug receipt is unreadable",
    )
    if (
        not isinstance(payload, dict)
        or set(payload) != FIXED_BUG_ARCHIVE_RECEIPT_FIELDS
        or payload.get("schemaVersion") != 1
        or payload.get("owner") != FIXED_BUG_ARCHIVE_OWNER
        or payload.get("kind") != FIXED_BUG_ARCHIVE_KIND
        or payload.get("status") != "settled"
        or not isinstance(payload.get("links"), list)
        or any(not isinstance(payload.get(key), str)
               for key in FIXED_BUG_ARCHIVE_RECEIPT_FIELDS - {"schemaVersion", "links"})
    ):
        raise LifecycleError(failure_id, "fixed bug receipt shape differs")
    try:
        category, slug = _canonical_category(payload["sourceReference"])
        month = archive_month(payload["terminalInstant"])
    except LifecycleError as exc:
        raise LifecycleError(failure_id, "fixed bug receipt identity differs") from exc
    repository = _work_items_root(root).parent
    source = repository / "work-items" / "bugs" / f"{slug}.md"
    archive = repository / "work-items" / "bugs" / "archive" / month / f"{slug}.md"
    receipt = archive.with_name(f"{slug}.fixed-archive-receipt.json")
    if (
        category.name != "bug"
        or payload["sourcePath"] != source.relative_to(repository).as_posix()
        or payload["archivePath"] != archive.relative_to(repository).as_posix()
        or receipt_path.resolve() != receipt.resolve()
        or _category_locations(root, CATEGORIES["bug"], slug) != [archive]
        or any(not SHA256_RE.fullmatch(payload[key]) for key in (
            "sourceBeforeSha256", "archivedBugSha256", "readmeSha256"
        ))
    ):
        raise LifecycleError(failure_id, "fixed bug receipt binding differs")
    archived = _capture_file_snapshot(archive, failure_id=failure_id)
    try:
        fields = _parse_fields(archived.data.decode("utf-8"))
    except UnicodeError as exc:
        raise LifecycleError(failure_id, "archived bug is not UTF-8") from exc
    if (
        _sha256_bytes(archived.data) != payload["archivedBugSha256"]
        or fields.get("id") != slug
        or fields.get("status") != "fixed"
        or fields.get("terminal-at") != payload["terminalInstant"]
        or not fields.get("context")
        or not fields.get("resolution")
        or not fields.get("evidence")
    ):
        raise LifecycleError(failure_id, "archived fixed bug differs")
    paths: list[str] = []
    for row in payload["links"]:
        if (
            not isinstance(row, dict)
            or set(row) != {"path", "beforeSha256", "afterSha256"}
            or not isinstance(row.get("path"), str)
            or not isinstance(row.get("beforeSha256"), str)
            or not isinstance(row.get("afterSha256"), str)
            or not SHA256_RE.fullmatch(row["beforeSha256"])
            or not SHA256_RE.fullmatch(row["afterSha256"])
        ):
            raise LifecycleError(failure_id, "fixed bug receipt link row differs")
        paths.append(row["path"])
        consumer = _intent_path(root, row["path"])
        if _ledger_location_regular_sha256(consumer, failure_id=failure_id) != row["afterSha256"]:
            raise LifecycleError(failure_id, f"fixed bug settled link differs: {row['path']}")
    if (
        paths != sorted(paths) or len(paths) != len(set(paths))
        or _ledger_location_regular_sha256(
            _work_items_root(root) / "README.md", failure_id=failure_id,
        ) != payload["readmeSha256"]
        or (expected_bytes is not None and receipt_bytes != expected_bytes)
    ):
        raise LifecycleError(failure_id, "fixed bug settled bytes differ")
    return payload


def _bug_supersession_intent_links(root: Path, intent: dict) -> list[dict]:
    result: list[dict] = []
    for row in intent["links"]:
        before = _unb64(row["before"])
        after = _unb64(row["after"])
        if before is None or after is None:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                f"{_single_bug_transition_label(intent)} intent link image is absent",
            )
        result.append(
            {
                "path": _intent_path(root, row["path"]),
                "pathRelative": row["path"],
                "before": before,
                "after": after,
                "beforeSha256": row["beforeSha256"],
                "afterSha256": row["afterSha256"],
            }
        )
    return result


def _recover_single_bug_transition(
    root: Path,
    intent_path: Path,
    intent: dict,
    *,
    inject_failure_at: str | None = None,
) -> dict | None:
    label = _single_bug_transition_label(intent)
    source = _intent_path(root, intent["sourcePath"])
    archive = _intent_path(root, intent["archivePath"])
    receipt = _intent_path(root, intent["receiptPath"])
    source_before = _unb64(intent["sourceBefore"])
    source_after = _unb64(intent["sourceAfter"])
    receipt_before = _unb64(intent["receiptBefore"])
    receipt_after = _unb64(intent["receiptAfter"])
    if source_before is None or source_after is None or receipt_after is None:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            f"{label} intent image is absent",
        )
    links = _bug_supersession_intent_links(root, intent)
    rollback_id = _single_bug_failure_id(intent, "ROLLBACK")
    forward_id = _single_bug_failure_id(intent, "ROLLFORWARD")
    failpoint = "F" if intent["kind"] == FIXED_BUG_ARCHIVE_KIND else "B"
    failure_id = rollback_id
    current_source = _read_lifecycle_image(
        source,
        source_before,
        source_after,
        failure_id=failure_id,
    retain=True)
    source_exists = current_source is not None
    archive_exists = archive.is_file()
    if source_exists:
        if archive_exists or current_source not in {source_before, source_after}:
            raise LifecycleError(
                rollback_id,
                f"{label} rollback identity differs",
            )
        for row in links:
            if _read_lifecycle_image(
                row["path"],
                row["before"],
                row["after"],
                failure_id=failure_id,
            retain=True) not in {
                row["before"], row["after"]
            }:
                raise LifecycleError(
                    rollback_id,
                    f"{label} rollback link differs: {row['pathRelative']}",
                )
        current_receipt = _read_lifecycle_image(
            receipt,
            receipt_before,
            receipt_after,
            failure_id=failure_id,
            require_single_link=True,
        retain=True)
        if current_receipt not in {receipt_before, receipt_after}:
            raise LifecycleError(
                rollback_id,
                f"{label} rollback receipt differs",
            )
        for row in links:
            _atomic_write(row["path"], row["before"])
        _atomic_write(source, source_before)
        if receipt_before is None:
            _remove_lifecycle_file(receipt, failure_id=rollback_id, missing_ok=True)
        else:
            _atomic_write(receipt, receipt_before)
        _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
        return None
    failure_id = forward_id
    if not archive_exists:
        raise LifecycleError(
            forward_id,
            f"{label} commit identity is absent",
        )
    if _read_lifecycle_image(archive, source_after, failure_id=failure_id, retain=True) != source_after:
        raise LifecycleError(
            forward_id,
            f"{label} archive image differs",
        )
    for row in links:
        if _read_lifecycle_image(row["path"], row["after"], failure_id=failure_id, retain=True) != row["after"]:
            raise LifecycleError(
                forward_id,
                f"{label} roll-forward link differs: {row['pathRelative']}",
            )
    current_receipt = _read_lifecycle_image(
        receipt,
        receipt_before,
        receipt_after,
        failure_id=failure_id,
        require_single_link=True,
    retain=True)
    if current_receipt not in {receipt_before, receipt_after}:
        raise LifecycleError(
                forward_id,
            f"{label} roll-forward receipt differs",
        )
    try:
        readme_sha256 = _safe_refresh_readme(root)
    except (LifecycleError, OSError) as exc:
        if intent["kind"] == FIXED_BUG_ARCHIVE_KIND:
            raise LifecycleError(forward_id, "fixed bug README refresh failed") from exc
        raise
    if readme_sha256 != intent["finalReadmeSha256"]:
        raise LifecycleError(
            forward_id,
            f"{label} README afterimage differs",
        )
    if inject_failure_at == f"{failpoint}4":
        raise LifecycleError(
            forward_id, f"injected {failpoint}4"
        )
    if current_receipt is None:
        _atomic_write(receipt, receipt_after)
        _transition_fsync_directory(receipt.parent)
    if inject_failure_at == f"{failpoint}5":
        raise LifecycleError(
            forward_id, f"injected {failpoint}5"
        )
    if intent["kind"] == FIXED_BUG_ARCHIVE_KIND:
        settled = _verify_fixed_bug_archive_settlement(root, receipt, receipt_after)
    else:
        settled = _verify_bug_supersession_settlement(root, receipt, receipt_after)
    if inject_failure_at == f"{failpoint}6":
        raise LifecycleError(
            forward_id, f"injected {failpoint}6"
        )
    _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
    if inject_failure_at == f"{failpoint}7":
        raise LifecycleError(
            forward_id, f"injected {failpoint}7"
        )
    return settled


def _parent_archive_uri_intent_fields(root: Path, plan: dict) -> dict:
    if plan["maintenance"] is None:
        return {}
    relative = lambda path: path.relative_to(Path(root).resolve()).as_posix()
    selected = {bug.source for bug in plan["bugs"]}
    consumers = [{"source": relative(row["path"]), "target": relative(row["path"]),
        "before": _b64(row["before"]), "after": _b64(row["after"]),
        "beforeSha256": row["beforeSha256"], "afterSha256": row["afterSha256"]}
        for row in plan["links"] if row["path"] not in selected]
    targets = []
    for original, (final, captured, data) in plan["targetImages"].items():
        row = {"source": relative(original), "target": relative(final)}
        if data is None:
            row.update(kind="directory", identity=[str(v) for v in plan["targetDirectoryIdentities"][original]])
        else:
            row.update(kind="file", beforeSha256=_sha256_bytes(captured.data) if captured is not None else None,
                       afterSha256=_sha256_bytes(data))
        targets.append(row)
    return {"uriConsumers": {"version": 1, "allowProtectedUriUpdates": plan["maintenance"]["allowProtectedUriUpdates"],
                              "rows": sorted(consumers, key=lambda row: row["source"])},
            "uriTargetBindings": {"version": 1, "rows": sorted(targets, key=lambda row: row["source"])}}


def _transition_parent_uri_images(root: Path, intent: dict) -> list[dict]:
    """Validate every component of a URI-bearing intent; never downgrade omission."""
    failure = "WI-LIFECYCLE-TRANSITION-INTENT-INVALID"
    def reject() -> None:
        raise LifecycleError(failure, "parent URI intent bindings differ")
    try:
        receipt = json.loads((_unb64(intent["bugReceiptAfter"]) or b"").decode("utf-8", errors="strict"))
    except (UnicodeError, ValueError, TypeError):
        reject()
    if not isinstance(receipt, dict):
        reject()
    if not any(key in intent for key in ("uriConsumers", "uriTargetBindings")) and "linkMaintenance" not in receipt:
        return []
    if any(key not in intent for key in ("uriConsumers", "uriTargetBindings")) or "linkMaintenance" not in receipt:
        reject()
    value, targets = intent["uriConsumers"], intent["uriTargetBindings"]
    if (not isinstance(value, dict) or set(value) != {"version", "allowProtectedUriUpdates", "rows"}
        or type(value["version"]) is not int or value["version"] != 1
        or type(value["allowProtectedUriUpdates"]) is not bool or not isinstance(value["rows"], list)
        or not isinstance(targets, dict) or set(targets) != {"version", "rows"}
        or type(targets["version"]) is not int or targets["version"] != 1
        or not isinstance(targets["rows"], list) or not targets["rows"]):
        reject()
    results = receipt.get("bugs")
    if not isinstance(results, list) or any(not isinstance(row, dict) for row in results):
        reject()
    maintenance = receipt["linkMaintenance"]
    consumers = _verify_close_link_maintenance(_work_items_root(root), intent["slug"], intent["terminalInstant"],
                                             maintenance, {row.get("id"): row for row in results})
    if value["allowProtectedUriUpdates"] != maintenance["allowProtectedUriUpdates"]:
        reject()
    def path(relative: object) -> Path:
        if (not isinstance(relative, str) or not relative or "\\" in relative
            or any(part in {"", ".", ".."} for part in relative.split("/"))):
            reject()
        return _intent_path(root, relative)
    def digest(value: object) -> bool:
        return isinstance(value, str) and bool(SHA256_RE.fullmatch(value))
    images = {}
    for row in value["rows"]:
        if (not isinstance(row, dict) or set(row) != {"source", "target", "before", "after", "beforeSha256", "afterSha256"}
            or not digest(row["beforeSha256"]) or not digest(row["afterSha256"])):
            reject()
        source, target = path(row["source"]), path(row["target"])
        before, after = _unb64(row["before"]), _unb64(row["after"])
        if before is None or after is None:
            reject()
        try:
            before.decode("utf-8", errors="strict"); after.decode("utf-8", errors="strict")
        except UnicodeError:
            reject()
        if (source in images or source != target or _sha256_bytes(before) != row["beforeSha256"]
            or _sha256_bytes(after) != row["afterSha256"]):
            reject()
        images[source] = {"path": source, "target": target, "before": before, "after": after}
    if [row["source"] for row in value["rows"]] != sorted(row["source"] for row in value["rows"]):
        reject()
    selected = {plan.source: plan for plan in _transition_bug_plans(root, intent)}
    for key, row in consumers.items():
        source, target = _work_items_root(root) / key, _work_items_root(root) / row["target"]
        if source in selected:
            if source in images:
                reject()
            plan = selected[source]
            if (target != (plan.target or source) or _sha256_bytes(plan.before) != row["beforeSha256"]
                or _sha256_bytes(plan.after) != row["afterSha256"]):
                reject()
        else:
            image = images.get(source)
            if (image is None or image["target"] != target or _sha256_bytes(image["before"]) != row["beforeSha256"]
                or _sha256_bytes(image["after"]) != row["afterSha256"]
                or _close_link_uri_changes(image["before"], image["after"]) != row["uriChanges"]):
                reject()
    if set(images) != {_work_items_root(root) / key for key in consumers} - set(selected):
        reject()
    expected_targets = set()
    active, archive = path(intent["activePath"]), path(intent["archivePath"])
    if active != _work_items_root(root) / maintenance["source"] or archive != _work_items_root(root) / maintenance["target"]:
        reject()
    for key, row in consumers.items():
        for change in row["uriChanges"]:
            href = _local_markdown_href_parts(change["from"])
            if href is None:
                reject()
            expected_targets.add(Path(os.path.abspath((_work_items_root(root) / key).parent / href[0])))
    seen = []
    for row in targets["rows"]:
        if not isinstance(row, dict):
            reject()
        source, target = path(row.get("source")), path(row.get("target"))
        if source not in expected_targets or source in seen or target != archive / source.relative_to(active):
            reject()
        seen.append(source)
        if row.get("kind") == "file":
            if set(row) != {"source", "target", "kind", "beforeSha256", "afterSha256"} or not digest(row["afterSha256"]):
                reject()
            special = {active / "status.md": (intent["statusBefore"], intent["statusAfter"]),
                       active / "closure.md": (intent["closureBefore"], intent["closureAfter"])}
            if source in special:
                before, after = map(_unb64, special[source])
                if before is None and source != active / "closure.md":
                    reject()
                if row["beforeSha256"] != (_sha256_bytes(before) if before is not None else None) or after is None or row["afterSha256"] != _sha256_bytes(after):
                    reject()
            elif not digest(row["beforeSha256"]) or row["beforeSha256"] != row["afterSha256"]:
                reject()
        elif row.get("kind") == "directory":
            identity = row.get("identity")
            if (set(row) != {"source", "target", "kind", "identity"} or not isinstance(identity, list)
                or len(identity) != 2 or any(not isinstance(v, str) or not v.isascii() or not v.isdecimal()
                                          or str(int(v)) != v for v in identity)):
                reject()
        else:
            reject()
    if set(seen) != expected_targets or [row["source"] for row in targets["rows"]] != sorted(row["source"] for row in targets["rows"]):
        reject()
    return list(images.values())


def _verify_transition_uri_targets(root: Path, intent: dict, *, archived: bool, failure_id: str) -> None:
    for row in intent.get("uriTargetBindings", {}).get("rows", []):
        path = _intent_path(root, row["target"] if archived else row["source"])
        if row["kind"] == "directory":
            _lifecycle_reject_unreduced_reparse(path, failure_id=failure_id, message="URI target crosses a link or reparse point")
            try:
                identity = _lifecycle_file_identity(path.lstat()) if path.is_dir() else None
            except OSError as exc:
                raise LifecycleError(failure_id, "URI directory target is unavailable") from exc
            if identity != tuple(int(value) for value in row["identity"]):
                raise LifecycleError(failure_id, "URI directory target identity differs")
        else:
            _lifecycle_reject_unreduced_reparse(path, failure_id=failure_id, message="URI target crosses a link or reparse point")
            try:
                path.lstat()
            except FileNotFoundError:
                if not archived and row["beforeSha256"] is None:
                    continue
                raise LifecycleError(failure_id, "URI file target is unavailable")
            except OSError as exc:
                raise LifecycleError(failure_id, "URI file target cannot be inspected") from exc
            captured = _capture_file_snapshot(path, failure_id=failure_id)
            allowed = {row["afterSha256"]} if archived else {row["beforeSha256"], row["afterSha256"]}
            if _sha256_bytes(captured.data) not in allowed:
                raise LifecycleError(failure_id, "URI file target bytes differ")


def _read_transition_intent_envelope(root: Path, path: Path) -> tuple:
    try:
        snapshot = _capture_file_snapshot(
            path,
            failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            maximum_bytes=TRANSITION_INTENT_FILE_BYTE_CAP,
            require_single_link=True,
        )
        payload = json.loads(snapshot.data.decode("utf-8", errors="strict"))
    except LifecycleError:
        raise
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "transition intent is unreadable",
        ) from exc
    is_v1 = (
        isinstance(payload, dict)
        and set(payload) in (TRANSITION_INTENT_FIELDS, TRANSITION_INTENT_FIELDS | {"uriConsumers", "uriTargetBindings"})
        and payload.get("schemaVersion") == 1
        and payload.get("owner") == TRANSITION_OWNER
    )
    is_v2 = (
        isinstance(payload, dict)
        and set(payload) in (TRANSFER_TRANSITION_INTENT_FIELDS, TRANSFER_TRANSITION_INTENT_FIELDS | {"uriConsumers", "uriTargetBindings"})
        and payload.get("schemaVersion") == 2
        and payload.get("owner") == TRANSFER_TRANSITION_OWNER
        and isinstance(payload.get("obligations"), list)
    )
    is_legacy_v2 = (
        isinstance(payload, dict)
        and set(payload) in (LEGACY_TRANSFER_TRANSITION_INTENT_FIELDS, LEGACY_TRANSFER_TRANSITION_INTENT_FIELDS | {"uriConsumers", "uriTargetBindings"})
        and payload.get("schemaVersion") == 2
        and payload.get("owner") == TRANSFER_TRANSITION_OWNER
        and isinstance(payload.get("obligations"), list)
    )
    is_bug_supersession = (
        isinstance(payload, dict)
        and set(payload) == BUG_SUPERSESSION_INTENT_FIELDS
        and payload.get("schemaVersion") == 1
        and payload.get("owner") == BUG_SUPERSESSION_OWNER
        and payload.get("kind") == BUG_SUPERSESSION_KIND
        and isinstance(payload.get("links"), list)
    )
    is_fixed_bug_archive = (
        isinstance(payload, dict)
        and set(payload) == FIXED_BUG_ARCHIVE_INTENT_FIELDS
        and payload.get("schemaVersion") == 1
        and payload.get("owner") == FIXED_BUG_ARCHIVE_OWNER
        and payload.get("kind") == FIXED_BUG_ARCHIVE_KIND
        and isinstance(payload.get("links"), list)
    )
    is_ledger_h1_relocation = (
        isinstance(payload, dict)
        and set(payload) == LEDGER_H1_RELOCATION_INTENT_FIELDS
        and payload.get("schemaVersion") == 1
        and payload.get("owner") == LEDGER_H1_RELOCATION_OWNER
        and payload.get("kind") == LEDGER_H1_RELOCATION_KIND
        and isinstance(payload.get("members"), list)
    )
    is_successor_import = (
        isinstance(payload, dict)
        and set(payload) == SUCCESSOR_IMPORT_INTENT_FIELDS
        and payload.get("schemaVersion") == 1
        and payload.get("owner") == SUCCESSOR_IMPORT_OWNER
        and payload.get("kind") == SUCCESSOR_IMPORT_KIND
    )
    is_legacy_completion = (isinstance(payload, dict) and set(payload) == LEGACY_COMPLETION_INTENT_FIELDS
        and payload.get("schemaVersion") == 1 and payload.get("owner") == LEGACY_COMPLETION_OWNER
        and payload.get("kind") == LEGACY_COMPLETION_KIND)
    if (
        not (
            is_v1
            or is_v2
            or is_legacy_v2
            or is_bug_supersession
            or is_fixed_bug_archive
            or is_ledger_h1_relocation
            or is_successor_import
            or is_legacy_completion
        )
        or payload.get("status") != "intent"
        or (
            not (is_bug_supersession or is_fixed_bug_archive or is_ledger_h1_relocation or is_successor_import or is_legacy_completion)
            and not isinstance(payload.get("bugs"), list)
        )
    ):
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "transition intent shape differs")
    _transition_intent_operation_id(root, path, intent=payload)
    return payload, snapshot, (is_v1, is_v2, is_legacy_v2, is_bug_supersession, is_fixed_bug_archive, is_ledger_h1_relocation, is_successor_import, is_legacy_completion)


def _read_selected_transition_at(repository: Path, operation_id: str) -> tuple[bool, tuple]:
    path = _transition_intent_path(repository, operation_id)
    evidence = []
    if _observe_project_path_at(path, "file", evidence, "WI-LIFECYCLE-TRANSITION-INTENT-INVALID") is None:
        return False, tuple(evidence)
    captured = _read_transition_intent_envelope(repository, path)
    evidence.append(("intent", captured))
    return True, tuple(evidence)


def _load_transition_intent(root: Path, path: Path) -> dict:
    captured = None
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        captured = transaction.current_intent(path)
    if captured is None:
        captured = _read_transition_intent_envelope(root, path)
    payload, snapshot, families = captured
    _verify_captured_file(snapshot, "WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
    if transaction is not None:
        transaction.observe_retained_inputs((snapshot,))
    is_v1, is_v2, is_legacy_v2, is_bug_supersession, is_fixed_bug_archive, is_ledger_h1_relocation, is_successor_import, is_legacy_completion = families
    if is_legacy_completion:
        _legacy_validate_intent(root, payload)
        return payload
    if is_successor_import:
        _validate_successor_import_intent(root, path, payload, snapshot.data)
        return payload
    if is_bug_supersession or is_fixed_bug_archive:
        label = _single_bug_transition_label(payload)
        for key in ("sourcePath", "archivePath", "receiptPath"):
            if not isinstance(payload[key], str):
                raise LifecycleError(
                    "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                    f"{label} intent path differs",
                )
            _intent_path(root, payload[key])
        paths: list[str] = []
        for row in payload["links"]:
            if (
                not isinstance(row, dict)
                or set(row) != BUG_SUPERSESSION_LINK_INTENT_FIELDS
                or not isinstance(row.get("path"), str)
                or not isinstance(row.get("before"), str)
                or not isinstance(row.get("after"), str)
                or not isinstance(row.get("beforeSha256"), str)
                or not SHA256_RE.fullmatch(row["beforeSha256"])
                or not isinstance(row.get("afterSha256"), str)
                or not SHA256_RE.fullmatch(row["afterSha256"])
            ):
                raise LifecycleError(
                    "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                    f"{label} intent link differs",
                )
            paths.append(row["path"])
            _intent_path(root, row["path"])
        if paths != sorted(paths) or len(paths) != len(set(paths)):
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                f"{label} intent links are not sorted and unique",
            )
        return payload
    if is_ledger_h1_relocation:
        _validate_ledger_h1_relocation_intent_shape(root, payload, path)
        return payload
    for key in ("activePath", "archivePath", "successorPath"):
        if payload[key] is not None:
            _intent_path(root, payload[key])
    if is_v2:
        _validate_transfer_migration_receipt_bindings(
            root,
            payload["archivePath"],
            payload["migrationReceipts"],
            failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
        )
    elif payload["migrationReceiptPath"] is not None:
        _intent_path(root, payload["migrationReceiptPath"])
    if is_v1 or is_v2 or is_legacy_v2:
        _transition_parent_uri_images(root, payload)
    return payload


def _read_lifecycle_image(
    path: Path,
    *known_images: bytes | None,
    failure_id: str,
    require_single_link: bool = False,
    retain: bool = False,
) -> bytes | None:
    """Capture an optional file within its known intent-image length envelope."""
    _lifecycle_reject_unreduced_reparse(
        path, failure_id=failure_id, message="lifecycle image crosses a link or reparse point"
    )
    try:
        path.lstat()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise LifecycleError(failure_id, "lifecycle image cannot be inspected") from exc
    maximum_bytes = max(
        (len(image) for image in known_images if image is not None), default=0
    )
    snapshot = _capture_file_snapshot(
        path, failure_id=failure_id, maximum_bytes=maximum_bytes,
        require_single_link=require_single_link,
    )
    if retain and snapshot.data in known_images:
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if transaction is not None:
            transaction.observe_retained_inputs((snapshot,))
    return snapshot.data


def _remove_lifecycle_file(path: Path, *, failure_id: str, missing_ok: bool = False, inverse=None) -> None:
    """Retire a domain-admitted image after one complete physical observation."""
    path = _lifecycle_unresolved_absolute(path)
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if not isinstance(transaction, LifecycleTransaction) or not transaction._locked:
        raise LifecycleError(failure_id, "owned retirement requires its held repository owner")
    if inverse is not None:
        transaction._admit_inverse_mutation(inverse)
        if (path, None, False) != (inverse.source, inverse.destination, inverse.directory):
            raise LifecycleError(failure_id, "owned retirement differs from admitted inverse")
    else:
        transaction.verify()
    if not path.is_relative_to(transaction.repository_root):
        raise LifecycleError(failure_id, "owned retirement escapes its held repository owner")
    snapshot = transaction._retained_observations.get(path)
    if snapshot is None:
        snapshot = next((value if kind == "file" else value[1]
            for kind, value in transaction.current_binding_evidence if kind in {"file", "intent"}
            and (value if kind == "file" else value[1]).path == path), None)
    if snapshot is None and missing_ok and not os.path.lexists(path):
        absence = ("absent", path)
        transaction._verify_integrity_constraint(absence,
            lambda: _verify_project_binding_evidence((absence,), failure_id))
        return
    if not isinstance(snapshot, CapturedFileSnapshot):
        raise LifecycleError(failure_id, "owned retirement lacks its admitted native image")
    owner = LifecycleWriteTarget(path, failure_id=failure_id, _operation_owner=transaction, inverse=inverse)
    primary = None
    try:
        def observe_image():
            if inverse is not None:
                transaction._observe_owned_inverse(inverse)
            else:
                _verify_captured_file(snapshot, failure_id)
            owner._acquire_existing_parents()
            image = owner.owned_image(maximum_bytes=max(1, snapshot.length))
            if (image is None or image["identity"]["value"] != list(snapshot.identity)
                    or _unb64(image["data"]) != snapshot.data):
                raise LifecycleError(failure_id, "owned retirement native image changed")
            return image
        image = transaction._verify_integrity_constraint(
            inverse if inverse is not None else snapshot, observe_image)
        owner.remove_owned(path.name, image)
    except BaseException as exc:
        primary = exc
        raise
    finally:
        owner.__exit__(type(primary) if primary is not None else None, primary,
            primary.__traceback__ if primary is not None else None)


def _ledger_location_proof_object(
    path: Path,
    *,
    failure_id: str,
    unreadable: str,
    maximum_bytes: int = LEDGER_LOCATION_PROOF_BYTE_CAP,
    acquired_input=None,
) -> tuple[dict, bytes]:
    def reject_duplicate_pairs(pairs: list[tuple[str, object]]) -> dict:
        value: dict[str, object] = {}
        for key, item in pairs:
            if key in value:
                raise LifecycleError(
                    failure_id, "ledger location proof repeats a JSON key"
                )
            value[key] = item
        return value

    try:
        raw = _capture_file_snapshot(
            path,
            failure_id=failure_id,
            maximum_bytes=maximum_bytes,
            require_single_link=True,
         acquired_input=acquired_input).data
        payload = json.loads(
            raw.decode("utf-8", errors="strict"),
            object_pairs_hook=reject_duplicate_pairs,
        )
    except LifecycleError:
        raise
    except (OSError, ValueError, RecursionError) as exc:
        raise LifecycleError(failure_id, unreadable) from exc
    if not isinstance(payload, dict):
        raise LifecycleError(
            failure_id, "ledger location proof is not one JSON object"
        )
    return payload, raw


def _ledger_location_lexically_exists(path: Path,
    *,
    acquired_input=None,
) -> bool:
    if acquired_input is not None and _settled_history_input(acquired_input) is not None:
        return _input_exists(path, acquired_input)
    try:
        _input_metadata(path, acquired_input)
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
            "ledger location identity cannot be inspected",
        ) from exc
    return True


def _ledger_location_regular_sha256(
    path: Path, *, failure_id: str, maximum_bytes: int | None = None,
    acquired_input=None,
) -> str:
    maximum_bytes = (
        LEDGER_LOCATION_PROOF_BYTE_CAP if maximum_bytes is None else maximum_bytes
    )
    if type(maximum_bytes) is not int or maximum_bytes < 0:
        raise LifecycleError(failure_id, "ledger location byte limit is invalid")
    if acquired_input is not None:
        _input_reject_reparse(path, failure_id=failure_id,
                             message="ledger location path crosses a link or reparse point", acquired_input=acquired_input)
        captured = _capture_file_snapshot(path, failure_id=failure_id,
                                          maximum_bytes=maximum_bytes, acquired_input=acquired_input)
        return _sha256_bytes(captured.data)
    _input_reject_reparse(
        path,
        failure_id=failure_id,
        message="ledger location path crosses a link or reparse point",
     acquired_input=acquired_input)
    parent_chain = _capture_path_parent_chain(path, failure_id)
    descriptor = -1
    try:
        observed = _input_metadata(path, acquired_input)
        if (
            not stat.S_ISREG(observed.st_mode)
            or observed.st_size > maximum_bytes
            or _input_has_reparse(path, acquired_input)
        ):
            raise OSError("ledger location is not a bounded regular file")
        descriptor = _open_readonly_nofollow(path)
        with os.fdopen(descriptor, "rb", closefd=True) as stream:
            descriptor = -1  # The stream now owns the descriptor, including failure exits.
            before = os.fstat(stream.fileno())
            before_key = _lifecycle_file_snapshot_key(before)
            if before_key[:5] != _lifecycle_file_snapshot_key(observed)[:5]:
                raise OSError("ledger location descriptor differs from its pathname")
            digests = []
            # Match snapshot capture's content check without retaining either image.
            for pass_index in range(2):
                if pass_index:
                    stream.seek(0)
                digest = hashlib.sha256()
                total = 0
                while True:
                    chunk = stream.read(min(64 * 1024, maximum_bytes - total + 1))
                    if not chunk:
                        break
                    total += len(chunk)
                    if total > maximum_bytes:
                        raise OSError("ledger location exceeds its byte limit")
                    digest.update(chunk)
                if (
                    total != before.st_size
                    or _lifecycle_file_snapshot_key(os.fstat(stream.fileno()))
                    != before_key
                ):
                    raise OSError("ledger location changed while hashing")
                digests.append(digest.hexdigest())
        current = _input_metadata(path, acquired_input)
        if (
            digests[0] != digests[1]
            or _lifecycle_file_snapshot_key(observed)
            != _lifecycle_file_snapshot_key(current)
            or _input_has_reparse(path, acquired_input)
        ):
            raise OSError("ledger location identity or content changed")
    except OSError as exc:
        raise LifecycleError(failure_id, "ledger location digest cannot be captured") from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    _verify_captured_parent_chain(parent_chain, failure_id)
    return digests[0]


def _migration_receipt_bindings_at(
    root: Path,
    archive: Path,
    *,
    failure_id: str,
    acquired_input=None,
) -> tuple[dict[str, str], ...]:
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
     acquired_input=acquired_input)
    receipt_root = archive / "ledger-migration-receipts"
    if not _ledger_location_lexically_exists(receipt_root, acquired_input=acquired_input):
        return ()
    _input_reject_reparse(
        receipt_root,
        failure_id=failure_id,
        message="migration receipt root crosses a link or reparse point",
     acquired_input=acquired_input)
    if not _input_is_dir(receipt_root, acquired_input):
        raise LifecycleError(failure_id, "migration receipt root is not a directory")
    receipts = sorted(
        _input_glob(receipt_root, "*.json", acquired_input),
        key=lambda path: path.relative_to(repository).as_posix().encode("utf-8"),
    )
    rows = tuple(
        {
            "path": receipt.relative_to(repository).as_posix(),
            "sha256": _ledger_location_regular_sha256(
                receipt,
                failure_id=failure_id,
             acquired_input=acquired_input),
        }
        for receipt in receipts
    )
    _validate_transfer_migration_receipt_bindings(
        root,
        archive.relative_to(repository).as_posix(),
        list(rows),
        failure_id=failure_id,
     acquired_input=acquired_input)
    return rows


def _ledger_location_archive_relative(slug: str, terminal_instant: object) -> str:
    if not isinstance(terminal_instant, str):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "ledger location terminal instant has the wrong type",
        )
    try:
        month = archive_month(terminal_instant)
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "ledger location terminal instant is invalid",
        ) from exc
    return f"work-items/archive/{month}/{slug}"


def _validate_ledger_location_intent(
    root: Path,
    path: Path,
    payload: dict,
    *,
    slug: str,
    logical_work_item: str,
    acquired_input=None,
) -> None:
    try:
        loaded = _load_transition_intent(root, path)
    except (LifecycleError, TypeError, ValueError) as exc:
        if isinstance(exc, LifecycleError):
            raise
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "ledger location intent value type differs",
        ) from exc
    if loaded != payload:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "ledger location intent changed while acquired",
        )
    field_set_is_valid = set(payload) == TRANSITION_INTENT_FIELDS
    if payload.get("schemaVersion") == 2:
        field_set_is_valid = set(payload) in (
            TRANSFER_TRANSITION_INTENT_FIELDS,
            LEGACY_TRANSFER_TRANSITION_INTENT_FIELDS,
        )
    valid_owner = (
        payload.get("schemaVersion") == 1
        and payload.get("owner") == TRANSITION_OWNER
    ) or (
        payload.get("schemaVersion") == 2
        and payload.get("owner") == TRANSFER_TRANSITION_OWNER
        and isinstance(payload.get("obligations"), list)
    )
    operation_id = payload.get("operationId")
    successor_slug = payload.get("successorSlug")
    archive_relative = _ledger_location_archive_relative(
        slug, payload.get("terminalInstant")
    )
    if (
        not field_set_is_valid
        or not valid_owner
        or payload.get("status") != "intent"
        or payload.get("slug") != slug
        or payload.get("activePath") != logical_work_item
        or payload.get("archivePath") != archive_relative
        or not isinstance(successor_slug, str)
        or not is_valid_slug(successor_slug)
        or payload.get("successorPath")
        != f"work-items/backlog/{successor_slug}.md"
        or not isinstance(payload.get("expectedLedgerSha256"), str)
        or SHA256_RE.fullmatch(payload["expectedLedgerSha256"]) is None
        or not isinstance(operation_id, str)
    ):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "ledger location intent binding differs",
        )
    expected_path = _transition_intent_path(root, operation_id, acquired_input=acquired_input)
    if expected_path.absolute() != path.absolute():
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "ledger location intent path differs from its operation id",
        )


def _matching_ledger_location_intents(
    root: Path,
    repository: Path,
    *,
    slug: str,
    logical_work_item: str,
    acquired_input=None,
) -> list[tuple[dict, Path, bytes]]:
    transition_root = repository / ".scratch" / "work-items-lifecycle-transitions"
    if not _ledger_location_lexically_exists(transition_root, acquired_input=acquired_input):
        return []
    _input_reject_reparse(
        transition_root,
        failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
        message="transition staging root is a link or reparse point",
     acquired_input=acquired_input)
    if not _input_is_dir(transition_root, acquired_input):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "transition staging root is not a directory",
        )
    matches: list[tuple[dict, Path, bytes]] = []
    candidates = _bounded_transition_intent_inventory(
        transition_root,
        failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
        unreadable="transition staging root is unreadable",
     acquired_input=acquired_input)
    loaded_bytes = 0
    for path in candidates:
        payload, raw = _ledger_location_proof_object(
            path,
            failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            unreadable="transition intent is unreadable",
            maximum_bytes=TRANSITION_INTENT_FILE_BYTE_CAP,
         acquired_input=acquired_input)
        loaded_bytes += len(raw)
        if loaded_bytes > TRANSITION_INTENT_INVENTORY_BYTE_CAP:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                "transition intent cumulative byte limit exceeded",
            )
        if payload.get("slug") != slug:
            continue
        _validate_ledger_location_intent(
            root,
            path,
            payload,
            slug=slug,
            logical_work_item=logical_work_item,
         acquired_input=acquired_input)
        matches.append((payload, path, raw))
    if len(matches) > 1:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "multiple ledger location intents match one work item",
        )
    return matches


def _validate_stable_ledger_settlement(
    root: Path,
    repository: Path,
    archive: Path,
    receipt_path: Path,
    *,
    slug: str,
    acquired_input=None,
) -> tuple[dict, bytes, str]:
    payload, raw = _ledger_location_proof_object(
        receipt_path,
        failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
        unreadable="settled receipt is unreadable",
     acquired_input=acquired_input)
    schema_version = payload.get("schemaVersion")
    is_v1 = (
        schema_version == 1
        and set(payload) == TRANSITION_SETTLEMENT_FIELDS
        and payload.get("owner") == TRANSITION_OWNER
    )
    is_v2 = (
        schema_version == 2
        and set(payload) == TRANSFER_TRANSITION_SETTLEMENT_FIELDS
        and payload.get("owner") == TRANSFER_TRANSITION_OWNER
        and isinstance(payload.get("obligations"), list)
    )
    is_legacy_v2 = (
        schema_version == 2
        and set(payload) == LEGACY_TRANSFER_TRANSITION_SETTLEMENT_FIELDS
        and payload.get("owner") == TRANSFER_TRANSITION_OWNER
        and isinstance(payload.get("obligations"), list)
    )
    terminal_instant = payload.get("terminalInstant")
    try:
        archive_relative = _ledger_location_archive_relative(slug, terminal_instant)
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
            "settled receipt terminal instant is invalid",
        ) from exc
    successor_slug = payload.get("requestSuccessorSlug")
    operation_id = payload.get("operationId")
    required_sha_fields = (
        "successorSha256",
        "ledgerSha256",
        "statusSha256",
        "closureSha256",
        "bugDispositionReceiptSha256",
        "readmeSha256",
        "requestClosureSha256",
        "requestSuccessorSha256",
        "requestExpectedLedgerSha256",
        "requestExpectedReadmeSha256",
    )
    if (
        not (is_v1 or is_v2 or is_legacy_v2)
        or payload.get("status") != "settled"
        or payload.get("workItem") != slug
        or payload.get("requestTerminalInstant") != terminal_instant
        or payload.get("archivePath") != archive_relative
        or archive.relative_to(repository).as_posix() != archive_relative
        or not isinstance(successor_slug, str)
        or not is_valid_slug(successor_slug)
        or payload.get("successorPath")
        != f"work-items/backlog/{successor_slug}.md"
        or not isinstance(operation_id, str)
        or any(
            not isinstance(payload.get(key), str)
            or SHA256_RE.fullmatch(payload[key]) is None
            for key in required_sha_fields
        )
        or payload.get("ledgerSha256")
        != payload.get("requestExpectedLedgerSha256")
    ):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
            "settled receipt binding or shape differs",
        )
    try:
        _transition_intent_path(root, operation_id, acquired_input=acquired_input)
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
            "settled receipt operation id is invalid",
        ) from exc
    if schema_version == 2:
        obligations = payload["obligations"]
        obligation_fields = {
            "runId", "rawLineOrdinal", "rawLineSha256", "rawEventSha256",
            "projectedEventSha256", "obligationId", "predecessorOperationId",
        }
        if (
            not isinstance(payload.get("transferInputSha256"), str)
            or SHA256_RE.fullmatch(payload["transferInputSha256"]) is None
            or not isinstance(payload.get("archiveIdentity"), str)
            or SHA256_RE.fullmatch(payload["archiveIdentity"]) is None
            or not (
                payload.get("predecessorOperationId") is None
                or isinstance(payload.get("predecessorOperationId"), str)
            )
            or any(
                not isinstance(row, dict)
                or set(row) != obligation_fields
                or not isinstance(row.get("runId"), str)
                or type(row.get("rawLineOrdinal")) is not int
                or row["rawLineOrdinal"] < 1
                or any(
                    not isinstance(row.get(key), str)
                    or SHA256_RE.fullmatch(row[key]) is None
                    for key in (
                        "rawLineSha256", "rawEventSha256",
                        "projectedEventSha256", "obligationId",
                    )
                )
                or not (
                    row.get("predecessorOperationId") is None
                    or isinstance(row.get("predecessorOperationId"), str)
                )
                for row in obligations
            )
        ):
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                "settled transfer receipt fields differ",
            )
    physical_hashes = {
        "ledgerSha256": _ledger_location_regular_sha256(
            archive / "agent-runs.jsonl",
            failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
            maximum_bytes=_validator_module().MAX_TRANSFER_LEDGER_BYTES,
         acquired_input=acquired_input),
        "statusSha256": _ledger_location_regular_sha256(
            archive / "status.md",
            failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
         acquired_input=acquired_input),
        "closureSha256": _ledger_location_regular_sha256(
            archive / "closure.md",
            failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
         acquired_input=acquired_input),
        "bugDispositionReceiptSha256": _ledger_location_regular_sha256(
            archive / BUG_DISPOSITIONS_RECEIPT,
            failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
         acquired_input=acquired_input),
    }
    physical_migration_receipts = _migration_receipt_bindings_at(
        root,
        archive,
        failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
     acquired_input=acquired_input)
    if is_v2:
        expected_migration_receipts = _validate_transfer_migration_receipt_bindings(
            root,
            payload.get("archivePath"),
            payload.get("migrationReceipts"),
            failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
         acquired_input=acquired_input)
        if physical_migration_receipts != expected_migration_receipts:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                "migration receipt set differs",
            )
    else:
        expected_migration_sha256 = payload.get("migrationReceiptSha256")
        if expected_migration_sha256 is None:
            if physical_migration_receipts:
                raise LifecycleError(
                    "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                    "migration receipt cardinality differs",
                )
        elif (
            not isinstance(expected_migration_sha256, str)
            or SHA256_RE.fullmatch(expected_migration_sha256) is None
            or len(physical_migration_receipts) != 1
            or physical_migration_receipts[0]["sha256"]
            != expected_migration_sha256
        ):
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                "migration receipt hash differs",
            )
    if any(payload.get(key) != value for key, value in physical_hashes.items()):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
            "settled archive hashes differ",
        )
    return payload, raw, physical_hashes["ledgerSha256"]


def _ledger_settlement_agrees_with_intent(receipt: dict, intent: dict) -> bool:
    pairs = {
        "schemaVersion": "schemaVersion",
        "owner": "owner",
        "operationId": "operationId",
        "workItem": "slug",
        "terminalInstant": "terminalInstant",
        "archivePath": "archivePath",
        "successorPath": "successorPath",
        "requestClosureSha256": "closureInputSha256",
        "requestSuccessorSlug": "successorSlug",
        "requestTerminalInstant": "terminalInstant",
        "requestExpectedLedgerSha256": "expectedLedgerSha256",
        "requestExpectedReadmeSha256": "expectedReadmeSha256",
    }
    if any(receipt.get(left) != intent.get(right) for left, right in pairs.items()):
        return False
    successor_data = _unb64(intent.get("successorData"))
    if successor_data is None or receipt.get("requestSuccessorSha256") != _sha256_bytes(
        successor_data
    ):
        return False
    for receipt_key, intent_key in (
        ("statusSha256", "statusAfter"),
        ("closureSha256", "closureAfter"),
        ("bugDispositionReceiptSha256", "bugReceiptAfter"),
    ):
        image = _unb64(intent.get(intent_key))
        if image is None or receipt.get(receipt_key) != _sha256_bytes(image):
            return False
    if receipt.get("schemaVersion") == 2:
        transfer_fields_agree = all(
            receipt.get(key) == intent.get(key)
            for key in (
                "transferInputSha256", "archiveIdentity",
                "predecessorOperationId", "obligations",
            )
        )
        if not transfer_fields_agree:
            return False
        if "migrationReceipts" in intent or "migrationReceipts" in receipt:
            return (
                "migrationReceipts" in intent
                and "migrationReceipts" in receipt
                and receipt["migrationReceipts"] == intent["migrationReceipts"]
            )
        return True
    return True


def resolve_work_item_ledger_location(
    root: Path, *, logical_work_item: str, logical_ledger_path: str,
    input_role: str = "caller-root",
    acquired_input=None,
) -> WorkItemLedgerLocationV1:
    logical_parts = PurePosixPath(logical_work_item).parts
    if (
        len(logical_parts) != 3
        or logical_parts[:2] != ("work-items", "active")
        or logical_ledger_path != f"{logical_work_item}/agent-runs.jsonl"
    ):
        raise LifecycleError(
            "WI-LEDGER-COMPAT-EFFECTIVE-VIEW-BYPASS",
            "logical H1 ledger identity must be one canonical active participant",
        )
    slug = logical_parts[2]
    _validate_slug(slug)
    repository, work_items = _resolve_project_root_identity(root, input_role=input_role,
        selected_reference=("work-item", slug), acquired_input=acquired_input)
    root = repository
    active = work_items / "active" / slug
    backlog = work_items / "backlog" / f"{slug}.md"
    archive_root = work_items / "archive"
    active_exists = _ledger_location_lexically_exists(active, acquired_input=acquired_input)
    backlog_exists = _ledger_location_lexically_exists(backlog, acquired_input=acquired_input)
    archives: list[Path] = []
    if _ledger_location_lexically_exists(archive_root, acquired_input=acquired_input):
        _input_reject_reparse(
            archive_root,
            failure_id="WI-CATEGORY-DUAL-LOCATION",
            message="archive root crosses a link or reparse point",
         acquired_input=acquired_input)
        if not _input_is_dir(archive_root, acquired_input):
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION", "archive root is not a directory"
            )
        for month in sorted(_input_children(archive_root, acquired_input)):
            candidate = month / slug
            if _ledger_location_lexically_exists(candidate, acquired_input=acquired_input):
                archives.append(candidate)
    if backlog_exists or len(archives) > 1 or (active_exists and archives):
        raise LifecycleError(
            "WI-CATEGORY-DUAL-LOCATION",
            "H1 work item does not have one physical lifecycle location",
        )
    intents = _matching_ledger_location_intents(
        root,
        repository,
        slug=slug,
        logical_work_item=logical_work_item,
     acquired_input=acquired_input)
    intent, intent_path, intent_raw = intents[0] if intents else (None, None, None)
    if active_exists:
        _input_reject_reparse(
            active,
            failure_id="WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
            message="active H1 work item crosses a link or reparse point",
         acquired_input=acquired_input)
        if not _input_is_dir(active, acquired_input):
            raise LifecycleError(
                "WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
                "active H1 work item is not a directory",
            )
        ledger_sha256 = _ledger_location_regular_sha256(
            active / "agent-runs.jsonl",
            failure_id="WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
            maximum_bytes=_validator_module().MAX_TRANSFER_LEDGER_BYTES,
         acquired_input=acquired_input)
        if intent is not None and intent.get("expectedLedgerSha256") != ledger_sha256:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                "active intent ledger digest differs",
            )
        return WorkItemLedgerLocationV1(
            logical_work_item,
            logical_ledger_path,
            logical_work_item,
            logical_ledger_path,
            "active-intent" if intent is not None else "active",
            ledger_sha256,
            intent.get("operationId") if intent is not None else None,
            intent_path.relative_to(repository).as_posix() if intent_path else None,
            _sha256_bytes(intent_raw) if intent_raw is not None else None,
        )
    if len(archives) != 1:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
            "H1 work item has no owner-proven physical ledger location",
        )
    archive = archives[0]
    _input_reject_reparse(
        archive,
        failure_id="WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
        message="archived H1 work item crosses a link or reparse point",
     acquired_input=acquired_input)
    if not _input_is_dir(archive, acquired_input):
        raise LifecycleError(
            "WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
            "archived H1 work item is not a directory",
        )
    physical_work_item = archive.relative_to(repository).as_posix()
    physical_ledger_path = f"{physical_work_item}/agent-runs.jsonl"
    receipt_path = archive / "lifecycle-transition-receipt.json"
    if _ledger_location_lexically_exists(receipt_path, acquired_input=acquired_input):
        receipt, receipt_raw, ledger_sha256 = _validate_stable_ledger_settlement(
            root,
            repository,
            archive,
            receipt_path,
            slug=slug,
         acquired_input=acquired_input)
        if intent is not None and not _ledger_settlement_agrees_with_intent(
            receipt, intent
        ):
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                "settlement and durable intent disagree",
            )
        return WorkItemLedgerLocationV1(
            logical_work_item,
            logical_ledger_path,
            physical_work_item,
            physical_ledger_path,
            "settled-archive",
            ledger_sha256,
            receipt["operationId"],
            receipt_path.relative_to(repository).as_posix(),
            _sha256_bytes(receipt_raw),
        )
    if intent is None or intent_path is None or intent_raw is None:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE",
            "archived H1 ledger has no lifecycle relocation proof",
        )
    if intent.get("archivePath") != physical_work_item:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
            "moved intent archive path differs",
        )
    ledger_sha256 = _ledger_location_regular_sha256(
        archive / "agent-runs.jsonl",
        failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
        maximum_bytes=_validator_module().MAX_TRANSFER_LEDGER_BYTES,
     acquired_input=acquired_input)
    status_after = _unb64(intent.get("statusAfter"))
    closure_after = _unb64(intent.get("closureAfter"))
    if (
        status_after is None
        or closure_after is None
        or intent.get("expectedLedgerSha256") != ledger_sha256
        or _ledger_location_regular_sha256(
            archive / "status.md",
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
         acquired_input=acquired_input)
        != _sha256_bytes(status_after)
        or _ledger_location_regular_sha256(
            archive / "closure.md",
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
         acquired_input=acquired_input)
        != _sha256_bytes(closure_after)
    ):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
            "moved intent after-images or ledger digest differ",
        )
    return WorkItemLedgerLocationV1(
        logical_work_item,
        logical_ledger_path,
        physical_work_item,
        physical_ledger_path,
        "moved-intent",
        ledger_sha256,
        intent["operationId"],
        intent_path.relative_to(repository).as_posix(),
        _sha256_bytes(intent_raw),
    )


def _transition_bug_plans(root: Path, intent: dict) -> tuple[BugDispositionPlan, ...]:
    plans = []
    for row in intent["bugs"]:
        if not isinstance(row, dict) or set(row) != {
            "id", "action", "source", "target", "before", "after", "statusBefore", "statusAfter"
        }:
            raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "transition bug image differs")
        plans.append(BugDispositionPlan(
            bug_id=row["id"], action=row["action"], source=_intent_path(root, row["source"]),
            target=_intent_path(root, row["target"]) if row["target"] is not None else None,
            before=_unb64(row["before"]) or b"", after=_unb64(row["after"]) or b"",
            status_before=row["statusBefore"], status_after=row["statusAfter"],
        ))
    return tuple(plans)


def _settlement_payload(root: Path, intent: dict, readme_sha256: str) -> dict:
    failure_id = "WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE"
    archive = _intent_path(root, intent["archivePath"])
    successor = _intent_path(root, intent["successorPath"])
    bug_receipt = archive / BUG_DISPOSITIONS_RECEIPT
    migration_receipt = None
    if (
        "migrationReceiptPath" in intent
        and intent["migrationReceiptPath"] is not None
    ):
        migration_receipt = archive / "ledger-migration-receipts" / Path(intent["migrationReceiptPath"]).name
    bug_receipt = _require_lifecycle_mutation_path(
        root, bug_receipt, failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE"
    )
    if migration_receipt is not None:
        migration_receipt = _require_lifecycle_mutation_path(
            root, migration_receipt, failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE"
        )
    payload = {
        "schemaVersion": intent["schemaVersion"],
        "owner": intent["owner"],
        "status": "settled",
        "operationId": intent["operationId"],
        "workItem": intent["slug"],
        "terminalInstant": intent["terminalInstant"],
        "archivePath": intent["archivePath"],
        "successorPath": intent["successorPath"],
        "successorSha256": _ledger_location_regular_sha256(successor, failure_id=failure_id),
        "ledgerSha256": _ledger_location_regular_sha256(
            archive / "agent-runs.jsonl",
            failure_id=failure_id,
            maximum_bytes=_validator_module().MAX_TRANSFER_LEDGER_BYTES,
        ),
        "statusSha256": _ledger_location_regular_sha256(
            archive / "status.md",
            failure_id=failure_id,
        ),
        "closureSha256": _ledger_location_regular_sha256(
            archive / "closure.md",
            failure_id=failure_id,
        ),
        "bugDispositionReceiptSha256": _ledger_location_regular_sha256(
            bug_receipt,
            failure_id=failure_id,
        ),
        "readmeSha256": readme_sha256,
        "requestClosureSha256": intent["closureInputSha256"],
        "requestSuccessorSlug": intent["successorSlug"],
        "requestSuccessorSha256": _sha256_bytes(_unb64(intent["successorData"]) or b""),
        "requestTerminalInstant": intent["terminalInstant"],
        "requestExpectedLedgerSha256": intent["expectedLedgerSha256"],
        "requestExpectedReadmeSha256": intent["expectedReadmeSha256"],
    }
    if "migrationReceipts" in intent:
        expected_migration_receipts = _validate_transfer_migration_receipt_bindings(
            root,
            intent["archivePath"],
            intent["migrationReceipts"],
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
        )
        physical_migration_receipts = _migration_receipt_bindings_at(
            root,
            archive,
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
        )
        if physical_migration_receipts != expected_migration_receipts:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
                "migration receipt set differs from transition intent",
            )
        payload["migrationReceipts"] = [
            dict(row) for row in physical_migration_receipts
        ]
    else:
        payload["migrationReceiptSha256"] = (
            _ledger_location_regular_sha256(migration_receipt, failure_id=failure_id)
            if migration_receipt is not None
            else None
        )
    if intent["schemaVersion"] == 2:
        payload.update({
            "transferInputSha256": intent["transferInputSha256"],
            "archiveIdentity": intent["archiveIdentity"],
            "predecessorOperationId": intent["predecessorOperationId"],
            "obligations": intent["obligations"],
        })
    return payload


def _safe_refresh_readme(root: Path) -> str:
    readme = _work_items_root(root) / "README.md"
    _require_lifecycle_mutation_path(root, readme, failure_id="WI-README-STALE")
    digest = refresh_readme(root)
    readme = _require_lifecycle_mutation_path(root, readme, failure_id="WI-README-STALE")
    if _ledger_location_regular_sha256(readme, failure_id="WI-README-STALE") != digest:
        raise LifecycleError("WI-README-STALE", "README identity or digest changed")
    return digest


def _precompute_transition_readme_sha256(
    root: Path,
    active: Path,
    archive: Path,
    successor: Path,
    status_after: bytes,
    closure_after: bytes,
    successor_data: bytes,
    plans: tuple[BugDispositionPlan, ...],
    links: list[dict] | None = None,
) -> str:
    work_items = _work_items_root(root)
    static_guide = _static_guide(work_items / "README.md")
    transaction_token = _CURRENT_LIFECYCLE_TRANSACTION.set(None)
    composer_token = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.set(None)
    try:
        with tempfile.TemporaryDirectory(prefix="work-items-transition-readme-") as directory:
            shadow_root = Path(directory)
            shadow_work_items = shadow_root / "work-items"
            shutil.copytree(work_items, shadow_work_items, symlinks=True)

            def shadow(path: Path) -> Path:
                return shadow_work_items / path.relative_to(work_items)

            shadow_active = shadow(active)
            shadow_archive = shadow(archive)
            _atomic_write(shadow_active / "status.md", status_after)
            _atomic_write(shadow_active / "closure.md", closure_after)
            for plan in plans:
                source = shadow(plan.source)
                if plan.action == "terminalize":
                    assert plan.target is not None
                    target = shadow(plan.target)
                    _atomic_write(source, plan.after)
                    target.parent.mkdir(parents=True, exist_ok=True)
                    os.replace(source, target)
            for row in links or []:
                if row["path"] not in {plan.source for plan in plans if plan.action == "terminalize"}:
                    _atomic_write(shadow(row["path"]), row["after"])
            shadow_archive.parent.mkdir(parents=True, exist_ok=True)
            os.replace(shadow_active, shadow_archive)
            _atomic_write(shadow(successor), successor_data)
            rendered = render_readme_bytes(
                shadow_root, static_guide_override=static_guide
            )
        return _sha256_bytes(rendered)
    finally:
        _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.reset(composer_token)
        _CURRENT_LIFECYCLE_TRANSACTION.reset(transaction_token)


def _verify_settlement(root: Path, receipt: Path, expected: dict | None = None) -> dict:
    failure_id = "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH"
    receipt = _require_lifecycle_mutation_path(
        root, receipt, failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH"
    )
    payload, _ = _ledger_location_proof_object(
        receipt, failure_id=failure_id, unreadable="settled receipt is unreadable"
    )
    valid_owner = False
    if isinstance(payload, dict):
        schema_version = payload.get("schemaVersion")
        valid_owner = (
            schema_version == 1
            and payload.get("owner") == TRANSITION_OWNER
            and set(payload) == TRANSITION_SETTLEMENT_FIELDS
        ) or (
            schema_version == 2
            and payload.get("owner") == TRANSFER_TRANSITION_OWNER
            and isinstance(payload.get("obligations"), list)
            and set(payload)
            in (
                TRANSFER_TRANSITION_SETTLEMENT_FIELDS,
                LEGACY_TRANSFER_TRANSITION_SETTLEMENT_FIELDS,
            )
        )
    if not isinstance(payload, dict) or payload.get("status") != "settled" or not valid_owner:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH", "settled receipt shape differs")
    archive = _intent_path(root, payload["archivePath"])
    successor = _intent_path(root, payload["successorPath"])
    readme_path = _require_lifecycle_mutation_path(
        root, _work_items_root(root) / "README.md",
        failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
    )
    bug_receipt_path = _require_lifecycle_mutation_path(
        root, archive / BUG_DISPOSITIONS_RECEIPT,
        failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
    )
    physical = {
        "successorSha256": _ledger_location_regular_sha256(successor, failure_id=failure_id),
        "ledgerSha256": _ledger_location_regular_sha256(
            archive / "agent-runs.jsonl",
            failure_id=failure_id,
            maximum_bytes=_validator_module().MAX_TRANSFER_LEDGER_BYTES,
        ),
        "statusSha256": _ledger_location_regular_sha256(
            archive / "status.md",
            failure_id=failure_id,
        ),
        "closureSha256": _ledger_location_regular_sha256(
            archive / "closure.md",
            failure_id=failure_id,
        ),
        "bugDispositionReceiptSha256": _ledger_location_regular_sha256(
            bug_receipt_path,
            failure_id=failure_id,
        ),
        "readmeSha256": _ledger_location_regular_sha256(readme_path, failure_id=failure_id),
    }
    migration_receipts = _migration_receipt_bindings_at(
        root,
        archive,
        failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
    )
    if "migrationReceipts" in payload:
        expected_migration_receipts = _validate_transfer_migration_receipt_bindings(
            root,
            payload["archivePath"],
            payload["migrationReceipts"],
            failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
        )
        if migration_receipts != expected_migration_receipts:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                "migration receipt set differs",
            )
        physical["migrationReceipts"] = [dict(row) for row in migration_receipts]
    else:
        expected_migration_sha = payload.get("migrationReceiptSha256")
        expected_migration_count = 0 if expected_migration_sha is None else 1
        if len(migration_receipts) != expected_migration_count:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                "migration receipt cardinality differs",
            )
        physical["migrationReceiptSha256"] = (
            migration_receipts[0]["sha256"] if migration_receipts else None
        )
    if any(payload.get(key) != value for key, value in physical.items()):
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH", "settled receipt hashes differ")
    bug_receipt, _ = _ledger_location_proof_object(bug_receipt_path, failure_id=failure_id, unreadable="bug receipt is unreadable")
    if isinstance(bug_receipt, dict) and "linkMaintenance" in bug_receipt:
        rows = bug_receipt.get("bugs")
        if not isinstance(rows, list) or any(not isinstance(row, dict) for row in rows):
            raise LifecycleError(failure_id, "bug receipt rows differ")
        _verify_close_link_maintenance(_work_items_root(root), payload["workItem"], payload["terminalInstant"],
            bug_receipt["linkMaintenance"], {row.get("id"): row for row in rows})
    if payload.get("schemaVersion") == 2:
        coverage_errors = _validator_module().validate_transfer_receipt_obligation_coverage(
            Path(root).resolve(), payload, archive
        )
        if coverage_errors:
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
                "; ".join(coverage_errors),
            )
    if expected is not None and payload != expected:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH", "settled receipt content differs")
    return payload


def _recover_transition(root: Path, intent_path: Path, *, inject_failure_at: str | None = None,
                        expected_request: dict | None = None) -> dict | None:
    intent = _load_transition_intent(root, intent_path)
    if intent.get("kind") == LEGACY_COMPLETION_KIND:
        return _recover_legacy_completion(root, intent_path, intent, inject_failure_at=inject_failure_at)
    if expected_request is not None:
        path_fields = {"activePath", "archivePath", "successorPath"}
        if any(
            (_intent_path(root, intent[key]) != value if key in path_fields
             else intent.get(key) != value)
            for key, value in expected_request.items()
        ):
            raise LifecycleError("WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH", "resume inputs differ")
    if intent.get("kind") == LEDGER_H1_RELOCATION_KIND:
        return _recover_ledger_h1_artifact_set_relocation(
            root,
            intent_path,
            intent,
        )
    if intent.get("kind") == SUCCESSOR_IMPORT_KIND:
        return _recover_successor_import(root, intent_path, intent)
    if intent.get("kind") in {BUG_SUPERSESSION_KIND, FIXED_BUG_ARCHIVE_KIND}:
        return _recover_single_bug_transition(
            root,
            intent_path,
            intent,
            inject_failure_at=inject_failure_at,
        )
    rollback_failure_id = "WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE"
    forward_failure_id = "WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE"
    active = _intent_path(root, intent["activePath"])
    archive = _intent_path(root, intent["archivePath"])
    successor = _intent_path(root, intent["successorPath"])
    status_before = _unb64(intent["statusBefore"]) or b""
    status_after = _unb64(intent["statusAfter"]) or b""
    closure_before = _unb64(intent["closureBefore"])
    closure_after = _unb64(intent["closureAfter"]) or b""
    bug_receipt_before = _unb64(intent["bugReceiptBefore"])
    bug_receipt_after = _unb64(intent["bugReceiptAfter"]) or b""
    successor_data = _unb64(intent["successorData"]) or b""
    plans = _transition_bug_plans(root, intent)
    uri_images = _transition_parent_uri_images(root, intent)
    if active.is_dir():
        _verify_transition_uri_targets(root, intent, archived=False, failure_id=rollback_failure_id)
        for row in uri_images:
            if _read_lifecycle_image(row["path"], row["before"], row["after"], failure_id=rollback_failure_id, retain=True) not in {row["before"], row["after"]}:
                raise LifecycleError(rollback_failure_id, "URI consumer rollback image differs")
        status = _require_lifecycle_mutation_path(
            root, active / "status.md",
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
        )
        closure = _require_lifecycle_mutation_path(
            root, active / "closure.md",
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
        )
        bug_receipt = _require_lifecycle_mutation_path(
            root, active / BUG_DISPOSITIONS_RECEIPT,
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
        )
        current_status = _read_lifecycle_image(
            status,
            status_before,
            status_after,
            failure_id=rollback_failure_id,
        retain=True)
        current_closure = _read_lifecycle_image(
            closure,
            closure_before,
            closure_after,
            failure_id=rollback_failure_id,
        retain=True)
        if current_status not in {status_before, status_after} or current_closure not in {closure_before, closure_after}:
            raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", "active before-image cannot be proven")
        for plan in plans:
            source_image = _read_lifecycle_image(
                plan.source,
                plan.before,
                plan.after,
                failure_id=rollback_failure_id,
            retain=True)
            target_image = _read_lifecycle_image(
                plan.target, plan.after, failure_id=rollback_failure_id,
            retain=True) if plan.target is not None else None
            if source_image is not None:
                if target_image is not None or source_image not in {plan.before, plan.after}:
                    raise LifecycleError(rollback_failure_id, f"bug rollback locations differ: {plan.bug_id}")
            elif target_image != plan.after or plan.target is None:
                raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", f"bug before-image differs: {plan.bug_id}")
            if source_image == plan.before:
                continue  # Exact restored/preserved bytes need no write.
            if target_image is not None:
                LifecycleWriteTarget.make_directories(plan.source.parent, _CURRENT_LIFECYCLE_TRANSACTION.get())
                _replace_lifecycle_directory(plan.target, plan.source, directory=False)
            if _read_lifecycle_image(plan.source, plan.before, plan.after,
                                     failure_id=rollback_failure_id, retain=True) not in {plan.before, plan.after}:
                raise LifecycleError(rollback_failure_id, f"bug rollback source changed: {plan.bug_id}")
            _atomic_write(plan.source, plan.before)
        for row in uri_images:
            observed = _read_lifecycle_image(row["path"], row["before"], row["after"], failure_id=rollback_failure_id, retain=True)
            if observed not in {row["before"], row["after"]}:
                raise LifecycleError(rollback_failure_id, "URI consumer changed before rollback")
            if observed == row["after"]:
                _atomic_write(row["path"], row["before"])
        current_bug_receipt = _read_lifecycle_image(
            bug_receipt,
            bug_receipt_before,
            bug_receipt_after,
            failure_id=rollback_failure_id,
            require_single_link=True,
        retain=True)
        if current_bug_receipt not in {bug_receipt_before, bug_receipt_after}:
            raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", "bug receipt before-image differs")
        _atomic_write(status, status_before)
        if closure_before is None:
            _require_lifecycle_mutation_path(
                root, closure, failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE"
            )
            _remove_lifecycle_file(closure, failure_id=rollback_failure_id, missing_ok=True)
        else:
            _atomic_write(closure, closure_before)
        if bug_receipt_before is None:
            _require_lifecycle_mutation_path(
                root, bug_receipt, failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE"
            )
            _remove_lifecycle_file(bug_receipt, failure_id=rollback_failure_id, missing_ok=True)
        else:
            _atomic_write(bug_receipt, bug_receipt_before)
        if successor.exists():
            if _read_lifecycle_image(
                successor,
                successor_data,
                failure_id=rollback_failure_id,
            retain=True) != successor_data:
                raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", "unexpected successor bytes")
            _remove_lifecycle_file(successor, failure_id=rollback_failure_id)
        _require_lifecycle_mutation_path(
            root, intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID"
        )
        _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
        return None
    if not archive.is_dir():
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "intent has neither active nor archive identity")
    if _read_lifecycle_image(
        archive / "status.md",
        status_after,
        failure_id=forward_failure_id,
    retain=True) != status_after or _read_lifecycle_image(
        archive / "closure.md",
        closure_after,
        failure_id=forward_failure_id,
    retain=True) != closure_after:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", "archive identity differs")
    archived_bug_receipt = archive / BUG_DISPOSITIONS_RECEIPT
    archived_bug_receipt = _require_lifecycle_mutation_path(
        root, archived_bug_receipt,
        failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
    )
    if _read_lifecycle_image(
        archived_bug_receipt,
        bug_receipt_after,
        failure_id=forward_failure_id,
        require_single_link=True,
    retain=True) != bug_receipt_after:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
            "pre-archive bug receipt is missing or changed",
        )
    _verify_transition_uri_targets(root, intent, archived=True, failure_id=forward_failure_id)
    maintenance = json.loads(bug_receipt_after.decode("utf-8")).get("linkMaintenance")
    uri_selected = {_work_items_root(root) / row["source"] for row in maintenance["consumers"]} if maintenance is not None else set()
    for plan in plans:
        if plan.source not in uri_selected:
            continue
        source_image = _read_lifecycle_image(plan.source, plan.before, plan.after, failure_id=forward_failure_id, retain=True)
        target_image = _read_lifecycle_image(plan.target, plan.after, failure_id=forward_failure_id, retain=True) if plan.target is not None else None
        if plan.target is not None:
            if source_image is not None:
                if target_image is not None or source_image not in {plan.before, plan.after}:
                    raise LifecycleError(forward_failure_id, "URI bug forward locations differ")
                if source_image == plan.before:
                    _atomic_write(plan.source, plan.after)
                LifecycleWriteTarget.make_directories(plan.target.parent, _CURRENT_LIFECYCLE_TRANSACTION.get())
                _replace_lifecycle_directory(plan.source, plan.target, directory=False)
            elif target_image != plan.after:
                raise LifecycleError(forward_failure_id, "URI bug forward target differs")
        else:
            if source_image not in {plan.before, plan.after}:
                raise LifecycleError(forward_failure_id, "URI bug forward image differs")
            if source_image == plan.before:
                _atomic_write(plan.source, plan.after)
    for row in uri_images:
        observed = _read_lifecycle_image(row["target"], row["before"], row["after"], failure_id=forward_failure_id, retain=True)
        if observed not in {row["before"], row["after"]}:
            raise LifecycleError(forward_failure_id, "URI consumer forward image differs")
        if observed == row["before"]:
            _atomic_write(row["target"], row["after"])
    if successor.exists():
        if _read_lifecycle_image(
            successor,
            successor_data,
            failure_id=forward_failure_id,
        retain=True) != successor_data:
            raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", "successor bytes differ")
    else:
        _atomic_write(successor, successor_data)
    if inject_failure_at == "T4":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", "injected T4")
    _verify_transition_uri_targets(root, intent, archived=True, failure_id=forward_failure_id)
    for row in uri_images:
        if _read_lifecycle_image(row["target"], row["after"], failure_id=forward_failure_id, retain=True) != row["after"]:
            raise LifecycleError(forward_failure_id, "URI consumer readback differs")
    readme_sha = _safe_refresh_readme(root)
    if readme_sha != intent["finalReadmeSha256"]:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
            "precomputed README digest differs after roll-forward",
        )
    if inject_failure_at == "T5":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", "injected T5")
    _verify_transition_uri_targets(root, intent, archived=True, failure_id=forward_failure_id)
    settlement = _settlement_payload(root, intent, readme_sha)
    receipt_path = archive / "lifecycle-transition-receipt.json"
    receipt_bytes = _migration_receipt_bytes(settlement)
    current_receipt = _read_lifecycle_image(
        receipt_path,
        receipt_bytes,
        failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH",
        require_single_link=True,
    retain=True)
    if current_receipt not in {None, receipt_bytes}:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH", "settled receipt differs")
    receipt_path = _require_lifecycle_mutation_path(
        root, receipt_path,
        failure_id="WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE",
    )
    _atomic_write(receipt_path, receipt_bytes)
    _transition_fsync_directory(receipt_path.parent)
    if inject_failure_at == "T6":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", "injected T6")
    _verify_transition_uri_targets(root, intent, archived=True, failure_id=forward_failure_id)
    _verify_settlement(root, receipt_path, settlement)
    if inject_failure_at == "T7":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", "injected T7")
    _require_lifecycle_mutation_path(
        root, intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID"
    )
    _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
    if inject_failure_at in {"T8", "T9"}:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", f"injected {inject_failure_at}")
    return settlement


def _iter_transition_intents(root: Path) -> Iterable[Path]:
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
    )
    directory = repository / ".scratch" / "work-items-lifecycle-transitions"
    if not directory.exists():
        return
    if not directory.is_dir() or _lifecycle_path_has_reparse(directory):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "transition staging root is unsafe",
        )
    yield from _bounded_transition_intent_inventory(
        directory,
        failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
        unreadable="transition staging root is unreadable",
    )


def _recover_all_transitions(root: Path) -> None:
    for intent_path in _iter_transition_intents(root):
        _recover_transition(root, intent_path)


@functools.partial(_lifecycle_participant, subject_parameters=('transition', 'operation_id'))
def recover_transition(root: Path, operation_id: str) -> dict | None:
    """Recover one pending transition under the ordinary lifecycle participant."""
    _lifecycle_reject_unreduced_reparse(
        root, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
        message="transition recovery root contains a link or reparse point",
    )
    intent_path = _transition_intent_path(root, operation_id)
    if not intent_path.is_file():
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-RECOVERY-REQUIRED",
            f"no pending transition for operation: {operation_id}",
        )
    _transition_intent_operation_id(root, intent_path)
    return _recover_transition(root, intent_path)


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'slug'))
def archive_with_successor(
    root: Path,
    slug: str,
    closure_data: bytes,
    terminal_instant: str,
    successor_slug: str,
    successor_data: bytes,
    operation_id: str,
    expected_ledger_sha256: str,
    expected_readme_sha256: str,
    *,
    obligation_transfer_data: bytes | None = None,
    inject_failure_at: str | None = None,
    allow_protected_uri_updates: bool = False,
) -> dict:
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    _validate_slug(successor_slug)
    expected_ledger_sha256 = _normalize_sha256_input(expected_ledger_sha256)
    expected_readme_sha256 = _normalize_sha256_input(expected_readme_sha256)
    month = archive_month(terminal_instant)
    _validate_closure(closure_data, terminal_instant)
    work_items = _work_items_root(root)
    archive = work_items / "archive" / month / slug
    settled_path = archive / "lifecycle-transition-receipt.json"
    settled_path = _require_lifecycle_mutation_path(
        root, settled_path, failure_id="WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH"
    )
    payload = None
    if settled_path.is_file():
        payload = _verify_settlement(root, settled_path)
        if (
            payload.get("operationId") != operation_id
            or payload.get("workItem") != slug
            or payload.get("requestClosureSha256") != _sha256_bytes(closure_data)
            or payload.get("requestSuccessorSlug") != successor_slug
            or payload.get("requestSuccessorSha256") != _sha256_bytes(successor_data)
            or payload.get("requestTerminalInstant") != terminal_instant
            or payload.get("requestExpectedLedgerSha256") != expected_ledger_sha256
            or payload.get("requestExpectedReadmeSha256") != expected_readme_sha256
            or payload.get("transferInputSha256") != (
                _sha256_bytes(obligation_transfer_data)
                if obligation_transfer_data is not None else None
            )
        ):
            raise LifecycleError("WI-LIFECYCLE-TRANSITION-SETTLEMENT-MISMATCH", "replay inputs differ")
    intent_path = _transition_intent_path(root, operation_id)
    if intent_path.exists():
        recovered = _recover_transition(
            root, intent_path, inject_failure_at=inject_failure_at,
            expected_request={
                "operationId": operation_id, "slug": slug,
                "closureInputSha256": _sha256_bytes(closure_data),
                "successorSlug": successor_slug, "successorData": _b64(successor_data),
                "terminalInstant": terminal_instant,
                "expectedLedgerSha256": expected_ledger_sha256,
                "expectedReadmeSha256": expected_readme_sha256,
                "transferInputSha256": (_sha256_bytes(obligation_transfer_data)
                                        if obligation_transfer_data is not None else None),
                "activePath": work_items / "active" / slug,
                "archivePath": archive,
                "successorPath": work_items / "backlog" / f"{successor_slug}.md",
            },
        )
        if recovered is not None:
            return recovered
    elif payload is not None:
        return payload
    active = _active_migration_item(root, slug)
    ledger = active / "agent-runs.jsonl"
    if _ledger_location_regular_sha256(
        ledger,
        failure_id="WI-LEDGER-MIGRATION-LEDGER-DRIFT",
        maximum_bytes=_validator_module().MAX_TRANSFER_LEDGER_BYTES,
    ) != expected_ledger_sha256:
        raise LifecycleError("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "transition ledger digest changed")
    readme = work_items / "README.md"
    readme = _require_lifecycle_mutation_path(root, readme, failure_id="WI-README-STALE")
    if _ledger_location_regular_sha256(
        readme,
        failure_id="WI-README-STALE",
    ) != expected_readme_sha256:
        raise LifecycleError("WI-README-STALE", "transition README digest changed")
    archive = _require_lifecycle_mutation_path(
        root, archive, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID"
    )
    successor_preflight = _require_lifecycle_mutation_path(
        root, work_items / "backlog" / f"{successor_slug}.md",
        failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
    )
    if archive.exists() or successor_preflight.exists():
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "archive or successor already exists")
    transfer_obligations: list[dict] | None = None
    archive_identity: str | None = None
    migration_receipt: Path | None = None
    transfer_migration_receipts: tuple[CapturedFileSnapshot, ...] = ()
    if obligation_transfer_data is None:
        _validate_item_before_close(active)
    else:
        (
            _transfer_payload,
            transfer_obligations,
            archive_identity,
            transfer_migration_receipts,
        ) = _prepare_obligation_transfer(
            root,
            active,
            archive,
            slug,
            successor_slug,
            successor_data,
            operation_id,
            expected_ledger_sha256,
            obligation_transfer_data,
        )
    _manifest, manifest_data, bug_plans = _prepare_bug_dispositions(root, active, slug, terminal_instant)
    if obligation_transfer_data is None:
        migration_receipts = sorted((active / "ledger-migration-receipts").glob("*.json"))
        if len(migration_receipts) != 1:
            raise LifecycleError("WI-LEDGER-MIGRATION-RECEIPT-MISMATCH", "one migration receipt is required")
        migration_receipt = _require_lifecycle_mutation_path(
            root, migration_receipts[0], failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH"
        )
    archived_closure = _stamp_schema_marker(closure_data, "closure.md")
    status = active / "status.md"
    prior_status = status.read_bytes()
    status_after = _terminalize_status(prior_status)
    prior_closure = (active / "closure.md").read_bytes() if (active / "closure.md").exists() else None
    manifest = json.loads(manifest_data.decode("utf-8"))
    link_plan = _plan_parent_archive_links(
        root, active, archive, bug_plans=bug_plans, bug_manifest=manifest,
        target_after_images={status: status_after, active / "closure.md": archived_closure},
        allow_protected_uri_updates=allow_protected_uri_updates,
    )
    bug_plans = link_plan["bugs"]
    relative = lambda path: path.relative_to(Path(root).resolve()).as_posix()
    successor_path = work_items / "backlog" / f"{successor_slug}.md"
    final_readme_sha = _precompute_transition_readme_sha256(
        root, active, archive, successor_path, status_after, archived_closure,
        successor_data, bug_plans, link_plan["links"],
    )
    bug_receipt_path = active / BUG_DISPOSITIONS_RECEIPT
    bug_receipt_path = _require_lifecycle_mutation_path(
        root, bug_receipt_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID"
    )
    if bug_receipt_path.exists():
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "active bug receipt already exists")
    bug_receipt_after = _bug_disposition_receipt_bytes(
        root, slug, terminal_instant, manifest_data, archived_closure, bug_plans, final_readme_sha, link_maintenance=link_plan["maintenance"]
    )
    intent = {
        "schemaVersion": 2 if obligation_transfer_data is not None else 1,
        "owner": TRANSFER_TRANSITION_OWNER if obligation_transfer_data is not None else TRANSITION_OWNER,
        "status": "intent",
        "operationId": operation_id, "slug": slug, "terminalInstant": terminal_instant,
        "activePath": relative(active), "archivePath": relative(archive),
        "successorPath": relative(successor_path),
        "expectedLedgerSha256": expected_ledger_sha256, "expectedReadmeSha256": expected_readme_sha256,
        "statusBefore": _b64(prior_status), "statusAfter": _b64(status_after),
        "closureBefore": _b64(prior_closure), "closureAfter": _b64(archived_closure),
        "successorData": _b64(successor_data), "manifestData": _b64(manifest_data),
        "closureInputSha256": _sha256_bytes(closure_data),
        "successorSlug": successor_slug,
        "finalReadmeSha256": final_readme_sha,
        "bugReceiptBefore": None,
        "bugReceiptAfter": _b64(bug_receipt_after),
        "bugs": [{
            "id": plan.bug_id, "action": plan.action, "source": relative(plan.source),
            "target": relative(plan.target) if plan.target is not None else None,
            "before": _b64(plan.before), "after": _b64(plan.after),
            "statusBefore": plan.status_before, "statusAfter": plan.status_after,
        } for plan in bug_plans],
    }
    if obligation_transfer_data is None:
        intent["migrationReceiptPath"] = (
            relative(migration_receipt) if migration_receipt is not None else None
        )
    else:
        predecessor_ids = {
            row["predecessorOperationId"] for row in (transfer_obligations or [])
            if row["predecessorOperationId"] is not None
        }
        migration_receipt_bindings = [
            {
                "path": relative(
                    archive
                    / "ledger-migration-receipts"
                    / snapshot.path.name
                ),
                "sha256": _sha256_bytes(snapshot.data),
            }
            for snapshot in transfer_migration_receipts
        ]
        migration_receipt_bindings.sort(
            key=lambda row: row["path"].encode("utf-8")
        )
        intent.update({
            "migrationReceipts": migration_receipt_bindings,
            "transferInputSha256": _sha256_bytes(obligation_transfer_data),
            "archiveIdentity": archive_identity,
            "predecessorOperationId": (
                next(iter(predecessor_ids)) if len(predecessor_ids) == 1 else None
            ),
            "obligations": transfer_obligations,
        })
    intent.update(_parent_archive_uri_intent_fields(root, link_plan))
    _transition_parent_uri_images(root, intent)
    intent_bytes = _migration_receipt_bytes(intent)
    if len(intent_bytes) > TRANSITION_INTENT_FILE_BYTE_CAP:
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-INTENT-INVALID", "transition intent exceeds its byte limit")
    intent_path = _require_lifecycle_mutation_path(
        root, intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID"
    )
    for snapshot in transfer_migration_receipts:
        _verify_captured_file(
            snapshot,
            "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH",
        )
    _verify_project_binding_evidence(link_plan["ownerEvidence"], "WI-CLOSE-LINK-DRIFT")
    _atomic_write(intent_path, intent_bytes)
    _transition_fsync_directory(intent_path.parent)
    if inject_failure_at == "T0":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", "injected T0")
    _verify_project_binding_evidence(link_plan["ownerEvidence"], "WI-CLOSE-LINK-DRIFT")
    for captured in link_plan["consumerCaptures"].values():
        _verify_captured_file(captured, "WI-CLOSE-LINK-DRIFT")
    _verify_parent_archive_link_targets(link_plan, archived=False, failure_id="WI-CLOSE-LINK-DRIFT")
    for plan in bug_plans:
        plan_source = _require_lifecycle_mutation_path(
            root, plan.source,
            failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
        )
        plan_target = None
        if plan.target is not None:
            plan_target = _require_lifecycle_mutation_path(
                root, plan.target,
                failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
            )
        if plan.action == "terminalize":
            _atomic_write(plan_source, plan.after)
            assert plan_target is not None
            LifecycleWriteTarget.make_directories(plan_target.parent, transaction)
            _replace_lifecycle_directory(plan_source, plan_target, directory=False)
    terminalized = {plan.source for plan in bug_plans if plan.action == "terminalize"}
    for row in link_plan["links"]:
        if row["path"] not in terminalized:
            _verify_captured_file(link_plan["consumerCaptures"][row["path"]], "WI-CLOSE-LINK-DRIFT")
            _atomic_write(row["path"], row["after"])
    closure_path = _require_lifecycle_mutation_path(
        root, active / "closure.md",
        failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
    )
    _atomic_write(closure_path, archived_closure)
    _atomic_write(status, status_after)
    if inject_failure_at == "T1":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", "injected T1")
    _atomic_write(bug_receipt_path, bug_receipt_after)
    _transition_fsync_directory(bug_receipt_path.parent)
    if inject_failure_at == "T2":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", "injected T2")
    LifecycleWriteTarget.make_directories(archive.parent, transaction)
    _replace_lifecycle_directory(active, archive)
    if inject_failure_at == "T3":
        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLFORWARD-INDETERMINATE", "injected T3")
    return _recover_transition(root, intent_path, inject_failure_at=inject_failure_at)


def _validate_flat_terminal(category: Category, data: bytes) -> str:
    try:
        fields = _parse_fields(data.decode("utf-8"))
    except UnicodeDecodeError as exc:
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "terminal record must be UTF-8"
        ) from exc
    status = fields.get("status", "")
    if status not in category.terminal_statuses:
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            f"{category.name} status {status!r} is not terminal",
        )
    admission = _admission_for(category.name)
    utc_field = admission.utc_field.casefold()
    evidence_fields = (
        admission.detail_field.casefold(),
        admission.evidence_field.casefold(),
    )
    missing = [name for name in (utc_field, *evidence_fields) if not fields.get(name)]
    if missing:
        raise LifecycleError(
            "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
            f"{category.name} terminal record missing: {', '.join(missing)}",
        )
    _strict_utc(fields[utc_field])
    return fields[utc_field]


def _normalization_fail(failure_id: str, message: str) -> LifecycleError:
    return LifecycleError(failure_id, message)


def _normalization_bound_source(
    root: Path, category: Category, relative: str, *, must_exist: bool = True
) -> Path:
    work_items = _work_items_root(
        root,
        root_failure_id="WI-IDENTITY-NORMALIZE-SOURCE",
    )
    relative_path = Path(relative)
    if (
        relative_path.is_absolute()
        or len(relative_path.parts) < 2
        or relative_path.parts[0] != "work-items"
    ):
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-SOURCE",
            "normalization source must be repository-relative under work-items",
        )
    within_work_items = Path(*relative_path.parts[1:]).as_posix()
    requested = work_items.resolve() / Path(within_work_items)
    try:
        resolved = _terminalization_bound_path(
            work_items, within_work_items, label="normalization source"
        )
    except LifecycleError as exc:
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-SOURCE", str(exc)) from exc
    source = requested
    expected_parent = (work_items / category.current_root).resolve()
    if (
        category.current_kind != "flat"
        or source.parent.resolve() != expected_parent
        or source.resolve() != resolved
        or source.suffix != ".md"
        or (must_exist and not source.is_file())
    ):
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-SOURCE",
            "normalization source must be one mutable flat record in its category current root",
        )
    return source


def _normalization_scratch_path(root: Path, path: Path, *, label: str) -> Path:
    try:
        return _bound_repository_scratch_path(root, path, label=label, allow_absolute=True)
    except LifecycleError as exc:
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-INVENTORY", str(exc)) from exc


def _normalization_exact_file(path: Path) -> bool:
    return path.parent.is_dir() and any(
        child.name == path.name and child.is_file() for child in path.parent.iterdir()
    )


def _normalization_current_files(work_items: Path) -> list[Path]:
    files: set[Path] = set((work_items / "backlog").glob("*.md"))
    files.update(path / "status.md" for path in (work_items / "active").glob("*") if path.is_dir())
    for category in CATEGORIES.values():
        if category.current_kind == "flat":
            files.update((work_items / category.current_root).glob("*.md"))
    return sorted(path for path in files if path.is_file())


def _normalization_authoritative_line_numbers(text: str) -> frozenset[int]:
    return frozenset(
        line_number for line_number, _line in _authoritative_markdown_lines(text)
    )


def _normalization_replace_id(text: str, old_slug: str, new_slug: str) -> tuple[str, int]:
    authoritative = _normalization_authoritative_line_numbers(text)
    lines = text.splitlines(keepends=True)
    count = 0
    for index, line in enumerate(lines, start=1):
        if index not in authoritative:
            continue
        body = line.rstrip("\r\n")
        ending = line[len(body) :]
        match = FIELD_RE.fullmatch(body)
        if not (
            match
            and match.group(1).strip().casefold() == "id"
            and match.group(2).strip() == old_slug
        ):
            continue
        value_start, value_end = match.span(2)
        raw_value = match.group(2)
        leading = len(raw_value) - len(raw_value.lstrip())
        trailing = len(raw_value) - len(raw_value.rstrip())
        replacement = raw_value[:leading] + new_slug
        if trailing:
            replacement += raw_value[len(raw_value) - trailing :]
        lines[index - 1] = body[:value_start] + replacement + body[value_end:] + ending
        count += 1
    return "".join(lines), count


def _normalization_replace_live_mentions(
    text: str, old_slug: str, new_slug: str
) -> tuple[str, int]:
    """Rewrite live current-record mentions but preserve fenced evidence bytes."""
    authoritative = _normalization_authoritative_line_numbers(text)
    lines = text.splitlines(keepends=True)
    count = 0
    for index, line in enumerate(lines, start=1):
        if index not in authoritative:
            continue
        count += line.count(old_slug)
        lines[index - 1] = line.replace(old_slug, new_slug)
    return "".join(lines), count


def _normalization_authoritative_markdown_links(
    text: str,
) -> Iterable[MarkdownLocalLink]:
    """Yield normalization links only from lifecycle-authoritative Markdown lines."""
    authoritative = _normalization_authoritative_line_numbers(text)
    for link in _markdown_local_links(text):
        line_number = text.count("\n", 0, link.href_start) + 1
        if line_number in authoritative:
            yield link


def _normalization_snapshot(
    root: Path,
    category: Category,
    source: Path,
    target_slug: str,
) -> tuple[dict, dict[Path, bytes]]:
    work_items = _work_items_root(root)
    old_slug = source.stem
    target = work_items / category.current_root / f"{target_slug}.md"
    planned: dict[Path, bytes] = {}
    kinds: dict[Path, set[str]] = {}

    current_files = frozenset(_normalization_current_files(work_items))
    markdown_files = sorted(
        path for path in work_items.rglob("*.md") if path.name != "README.md"
    )
    for path in markdown_files:
        try:
            before = path.read_bytes()
            text = before.decode("utf-8")
        except (OSError, UnicodeError) as exc:
            raise _normalization_fail(
                "WI-IDENTITY-NORMALIZE-INVENTORY",
                f"cannot classify Markdown consumer: {path}",
            ) from exc

        physical_replacements: list[tuple[int, int, str]] = []
        for link in _normalization_authoritative_markdown_links(text):
            href_parts = _local_markdown_href_parts(link.href)
            if href_parts is None:
                continue
            filesystem_href, suffix = href_parts
            if (path.parent / filesystem_href).resolve() != source.resolve():
                continue
            if path not in current_files:
                raise _normalization_fail(
                    "WI-IDENTITY-NORMALIZE-INVENTORY",
                    f"physical consumer is not mutable current state: {path}",
                )
            new_href = Path(os.path.relpath(target, path.parent)).as_posix() + suffix
            physical_replacements.append((link.href_start, link.href_end, new_href))
        if physical_replacements:
            for start, end, value in reversed(physical_replacements):
                text = text[:start] + value + text[end:]
            kinds.setdefault(path, set()).add("physical-link")

        if path not in current_files:
            continue
        after = text
        if path == source:
            after, count = _normalization_replace_id(after, old_slug, target_slug)
            if count != 1:
                raise _normalization_fail(
                    "WI-IDENTITY-NORMALIZE-INVENTORY",
                    "source must contain exactly one authoritative id matching its physical slug",
                )
            kinds.setdefault(path, set()).add("authoritative-id")
        after, live_count = _normalization_replace_live_mentions(
            after, old_slug, target_slug
        )
        if live_count:
            kinds.setdefault(path, set()).add("live-reference")
        if after.encode("utf-8") != before:
            planned[path] = after.encode("utf-8")

    if source not in planned:
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-INVENTORY", "normalization source produced no identity change"
        )
    rows = []
    for path in sorted(planned):
        before = path.read_bytes()
        after = planned[path]
        rows.append(
            {
                "path": path.relative_to(work_items).as_posix(),
                "kinds": sorted(kinds[path]),
                "beforeSha256": hashlib.sha256(before).hexdigest(),
                "afterSha256": hashlib.sha256(after).hexdigest(),
            }
        )
    inventory = {
        "schemaVersion": CURRENT_IDENTITY_NORMALIZATION_SCHEMA_VERSION,
        "owner": CURRENT_IDENTITY_NORMALIZATION_OWNER,
        "workItemsRoot": str(work_items.resolve()),
        "category": category.name,
        "source": source.relative_to(work_items.parent).as_posix(),
        "targetSlug": target_slug,
        "oldIdentity": f"{category.name}:{old_slug}",
        "newIdentity": f"{category.name}:{target_slug}",
        "rows": rows,
    }
    return inventory, planned


def write_current_identity_normalization_inventory(
    root: Path,
    category_name: str,
    source_relative: str,
    target_slug: str,
    inventory_path: Path,
) -> dict:
    category = CATEGORIES.get(CATEGORY_ALIASES.get(category_name, category_name))
    if category is None:
        raise LifecycleError("WI-REFERENCE-INVALID", f"unknown category: {category_name!r}")
    _validate_slug(target_slug)
    source = _normalization_bound_source(root, category, source_relative)
    if is_valid_slug(source.stem):
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-SOURCE", "source identity is already canonical"
        )
    fields = _parse_fields(source.read_text(encoding="utf-8"))
    if fields.get("status", "") not in category.current_statuses:
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-SOURCE", "source does not carry a current admitted status"
        )
    inventory, _planned = _normalization_snapshot(root, category, source, target_slug)
    destination = _normalization_scratch_path(root, inventory_path, label="normalization inventory")
    _atomic_write(destination, (json.dumps(inventory, indent=2, sort_keys=True) + "\n").encode())
    return inventory


def _normalization_expected_receipt_rows(
    root: Path,
    category: Category,
    inventory: object,
    source: Path,
    target: Path,
) -> list[dict[str, str]]:
    """Derive the one complete receipt row sequence from the canonical inventory."""
    work_items = _work_items_root(root)
    source_repo_relative = source.relative_to(work_items.parent).as_posix()
    source_work_items_relative = source.relative_to(work_items).as_posix()
    target_work_items_relative = target.relative_to(work_items).as_posix()
    if (
        not isinstance(inventory, dict)
        or inventory.get("schemaVersion")
        != CURRENT_IDENTITY_NORMALIZATION_SCHEMA_VERSION
        or inventory.get("owner") != CURRENT_IDENTITY_NORMALIZATION_OWNER
        or inventory.get("workItemsRoot") != str(work_items.resolve())
        or inventory.get("category") != category.name
        or inventory.get("source") != source_repo_relative
        or inventory.get("targetSlug") != target.stem
        or not isinstance(inventory.get("rows"), list)
    ):
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-RECOVERY",
            "normalization inventory binding differs during replay",
        )

    expected: list[dict[str, str]] = []
    before_paths: set[str] = set()
    after_paths: set[str] = set()
    digest_re = re.compile(r"^[0-9a-f]{64}$")
    for row in inventory["rows"]:
        if (
            not isinstance(row, dict)
            or set(row) != {"path", "kinds", "beforeSha256", "afterSha256"}
            or not isinstance(row.get("path"), str)
            or not isinstance(row.get("kinds"), list)
            or not all(isinstance(kind, str) for kind in row["kinds"])
            or not isinstance(row.get("beforeSha256"), str)
            or not digest_re.fullmatch(row["beforeSha256"])
            or not isinstance(row.get("afterSha256"), str)
            or not digest_re.fullmatch(row["afterSha256"])
        ):
            raise _normalization_fail(
                "WI-IDENTITY-NORMALIZE-RECOVERY",
                "normalization inventory row is invalid during replay",
            )
        before_path = row["path"]
        try:
            _terminalization_bound_path(
                work_items, before_path, label="normalization receipt preimage"
            )
        except LifecycleError as exc:
            raise _normalization_fail(
                "WI-IDENTITY-NORMALIZE-RECOVERY", str(exc)
            ) from exc
        after_path = (
            target_work_items_relative
            if before_path == source_work_items_relative
            else before_path
        )
        if before_path in before_paths or after_path in after_paths:
            raise _normalization_fail(
                "WI-IDENTITY-NORMALIZE-RECOVERY",
                "normalization inventory rows are duplicated or collide",
            )
        before_paths.add(before_path)
        after_paths.add(after_path)
        expected.append(
            {
                "beforePath": before_path,
                "afterPath": after_path,
                "beforeSha256": row["beforeSha256"],
                "afterSha256": row["afterSha256"],
            }
        )
    if source_work_items_relative not in before_paths:
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-RECOVERY",
            "normalization inventory omits the authoritative source row",
        )
    return expected


def _normalization_replay(
    root: Path,
    category: Category,
    inventory_bytes: bytes,
    receipt: Path,
    source: Path,
    target: Path,
) -> bool:
    if not receipt.is_file() or _normalization_exact_file(source) or not _normalization_exact_file(target):
        return False
    try:
        payload = json.loads(receipt.read_text(encoding="utf-8"))
        inventory = json.loads(inventory_bytes.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-RECOVERY", "invalid normalization receipt") from exc
    work_items = _work_items_root(root)
    if (
        not isinstance(payload, dict)
        or payload.get("schemaVersion") != CURRENT_IDENTITY_NORMALIZATION_SCHEMA_VERSION
        or payload.get("owner") != CURRENT_IDENTITY_NORMALIZATION_OWNER
        or payload.get("inventorySha256") != hashlib.sha256(inventory_bytes).hexdigest()
        or payload.get("source") != source.relative_to(work_items.parent).as_posix()
        or payload.get("target") != target.relative_to(work_items).as_posix()
        or not isinstance(payload.get("rows"), list)
    ):
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-RECOVERY", "normalization receipt binding differs")
    expected_rows = _normalization_expected_receipt_rows(
        root, category, inventory, source, target
    )
    if payload["rows"] != expected_rows:
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-RECOVERY",
            "normalization receipt row set is incomplete, duplicated, or tampered",
        )
    for row in expected_rows:
        path = _terminalization_bound_path(work_items, row["afterPath"], label="normalization replay")
        if not path.is_file() or hashlib.sha256(path.read_bytes()).hexdigest() != row.get("afterSha256"):
            raise _normalization_fail("WI-IDENTITY-NORMALIZE-RECOVERY", "normalization settled bytes differ")
    readme = work_items / "README.md"
    if not readme.is_file() or hashlib.sha256(readme.read_bytes()).hexdigest() != payload.get("readmeSha256"):
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-RECOVERY", "normalization README differs")
    return True


def normalize_current_identity(
    root: Path,
    category_name: str,
    source_relative: str,
    target_slug: str,
    inventory_path: Path,
    receipt_path: Path,
    *,
    inject_failure_at: str | None = None,
) -> tuple[Path, bool]:
    category = CATEGORIES.get(CATEGORY_ALIASES.get(category_name, category_name))
    if category is None:
        raise LifecycleError("WI-REFERENCE-INVALID", f"unknown category: {category_name!r}")
    _validate_slug(target_slug)
    work_items = _work_items_root(root)
    source = _normalization_bound_source(root, category, source_relative, must_exist=False)
    target = work_items / category.current_root / f"{target_slug}.md"
    inventory_file = _normalization_scratch_path(root, inventory_path, label="normalization inventory")
    receipt = _normalization_scratch_path(root, receipt_path, label="normalization receipt")
    try:
        inventory_bytes = inventory_file.read_bytes()
        inventory = json.loads(inventory_bytes.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-INVENTORY", "invalid normalization inventory") from exc
    if not _normalization_exact_file(source):
        if _normalization_replay(
            root, category, inventory_bytes, receipt, source, target
        ):
            return target, True
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-RECOVERY", "source is absent without a complete settled receipt"
        )
    if receipt.exists():
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-RECOVERY",
            "receipt exists while legacy source is still present",
        )
    if is_valid_slug(source.stem):
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-SOURCE", "source identity is already canonical")
    locations = _category_locations(root, category, source.stem)
    if locations != [source]:
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "source identity is not physically unique")
    fields = _parse_fields(source.read_text(encoding="utf-8"))
    if fields.get("status", "") not in category.current_statuses:
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-SOURCE", "source does not carry a current admitted status"
        )
    target_locations = _category_locations(root, category, target_slug)
    if _normalization_exact_file(target) or any(
        not (location.is_file() and os.path.samefile(location, source))
        for location in target_locations
    ):
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "normalization target already exists")
    expected, planned = _normalization_snapshot(root, category, source, target_slug)
    if inventory != expected:
        raise _normalization_fail(
            "WI-IDENTITY-NORMALIZE-INVENTORY", "inventory is incomplete, stale, or differently classified"
        )
    readme = work_items / "README.md"
    readme_before = readme.read_bytes() if readme.is_file() else None
    preimages = {path: path.read_bytes() for path in planned}
    inventory_sha = hashlib.sha256(inventory_bytes).hexdigest()
    moved = False
    move_temp: Path | None = None
    try:
        for path in sorted(planned):
            _atomic_write(path, planned[path])
        if inject_failure_at == "after-rewrites":
            raise RuntimeError("injected normalization failure after rewrites")
        temp_dir = Path(tempfile.mkdtemp(prefix=f".{target_slug}.normalize.", dir=source.parent))
        move_temp = temp_dir / source.name
        _replace_lifecycle_directory(source, move_temp, directory=False)
        _replace_lifecycle_directory(move_temp, target, directory=False)
        temp_dir.rmdir()
        move_temp = None
        moved = True
        if inject_failure_at == "after-move":
            raise RuntimeError("injected normalization failure after move")
        readme_sha = refresh_readme(root)
        if inject_failure_at == "after-readme":
            raise RuntimeError("injected normalization failure after README")
        resolved = resolve_category(root, f"{category.name}:{target_slug}")
        if resolved != target.resolve() or _normalization_exact_file(source) or not _normalization_exact_file(target):
            raise RuntimeError("normalization final identity check failed")
        for path, after in planned.items():
            final_path = target if path == source else path
            if (
                not final_path.is_file()
                or hashlib.sha256(final_path.read_bytes()).hexdigest()
                != hashlib.sha256(after).hexdigest()
            ):
                raise RuntimeError(
                    f"normalization final byte check failed: {final_path}"
                )
        audit(root)
        rows = _normalization_expected_receipt_rows(
            root, category, inventory, source, target
        )
        payload = {
            "schemaVersion": CURRENT_IDENTITY_NORMALIZATION_SCHEMA_VERSION,
            "owner": CURRENT_IDENTITY_NORMALIZATION_OWNER,
            "inventorySha256": inventory_sha,
            "source": source_relative,
            "target": target.relative_to(work_items).as_posix(),
            "readmeSha256": readme_sha,
            "rows": rows,
        }
        _atomic_write(receipt, (json.dumps(payload, indent=2, sort_keys=True) + "\n").encode())
        if not _normalization_replay(
            root, category, inventory_bytes, receipt, source, target
        ):
            raise RuntimeError("normalization settled receipt verification failed")
        return target, False
    except BaseException as exc:
        try:
            if move_temp is not None and move_temp.exists():
                _replace_lifecycle_directory(move_temp, source, directory=False)
                move_temp.parent.rmdir()
            elif moved and _normalization_exact_file(target) and not _normalization_exact_file(source):
                temp_dir = Path(tempfile.mkdtemp(prefix=f".{source.stem}.rollback.", dir=source.parent))
                rollback_temp = temp_dir / target.name
                _replace_lifecycle_directory(target, rollback_temp, directory=False)
                _replace_lifecycle_directory(rollback_temp, source, directory=False)
                temp_dir.rmdir()
            for path, before in preimages.items():
                _atomic_write(path, before)
            if readme_before is None:
                if readme.exists():
                    _restore_readme_snapshot(readme, None)
            else:
                _atomic_write(readme, readme_before)
            if receipt.exists():
                _CURRENT_LIFECYCLE_TRANSACTION.get().restore_owned_file(receipt, None)
        except BaseException as rollback_exc:
            raise _normalization_fail(
                "WI-IDENTITY-NORMALIZE-ROLLBACK", f"rollback failed: {rollback_exc}"
            ) from exc
        raise _normalization_fail("WI-IDENTITY-NORMALIZE-ROLLBACK", str(exc)) from exc


CATEGORY_ADMISSION_TABLE = (
    CategoryAdmission(
        "work-item",
        "mutate-work-item:_category_locations",
        "mutate-work-item:_validate_closure",
        "closure.md:Closed",
        "work_item_terminal_evidence_missing",
        "Closed",
        "Outcome",
        "Evidence",
    ),
    CategoryAdmission(
        "bug",
        "mutate-work-item:_category_locations",
        "mutate-work-item:_validate_flat_terminal",
        "bug:Terminal-at",
        "bug_terminal_evidence_missing",
        "Terminal-at",
        "Resolution",
        "Evidence",
    ),
    CategoryAdmission(
        "decision",
        "mutate-work-item:_category_locations",
        "mutate-work-item:_validate_flat_terminal",
        "decision:Terminal-at",
        "decision_terminal_evidence_missing",
        "Terminal-at",
        "Rationale",
        "Evidence",
    ),
    CategoryAdmission(
        "lesson",
        "mutate-work-item:_category_locations",
        "mutate-work-item:_validate_flat_terminal",
        "lesson:Terminal-at",
        "lesson_terminal_evidence_missing",
        "Terminal-at",
        "Disposition",
        "Evidence",
    ),
    CategoryAdmission(
        "roadmap",
        "mutate-work-item:_category_locations",
        "mutate-work-item:_validate_flat_terminal",
        "roadmap:Terminal-at",
        "roadmap_terminal_evidence_missing",
        "Terminal-at",
        "Disposition",
        "Evidence",
    ),
    CategoryAdmission(
        "epic",
        "mutate-work-item:_category_locations",
        "mutate-work-item:_validate_flat_terminal",
        "epic:Closed",
        "epic_terminal_evidence_missing",
        "Closed",
        "Outcome",
        "Evidence",
    ),
)


def _admission_for(category_name: str) -> CategoryAdmission:
    rows = [row for row in CATEGORY_ADMISSION_TABLE if row.category == category_name]
    if len(CATEGORY_ADMISSION_TABLE) != 6 or len(rows) != 1:
        raise LifecycleError(
            "CATEGORY-MIGRATION-ADMISSION-GATE",
            f"category admission table is incomplete or duplicated: {category_name}",
        )
    row = rows[0]
    if not all(
        (
            row.category,
            row.current_reader,
            row.terminal_validator,
            row.utc_field_owner,
            row.negative_fixture,
            row.utc_field,
            row.detail_field,
            row.evidence_field,
        )
    ):
        raise LifecycleError(
            "CATEGORY-MIGRATION-ADMISSION-GATE",
            f"category admission row has a missing cell: {category_name}",
        )
    return row


def _move_terminal_category(root: Path, reference: str, *,
                            allow_protected_uri_updates: bool = False) -> Path:
    category, slug = _canonical_category(reference)
    _admission_for(category.name)
    locations = _category_locations(root, category, slug)
    if len(locations) > 1:
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", f"duplicate slug: {reference}")
    if len(locations) != 1:
        raise LifecycleError("WI-INVALID-TARGET", f"missing category record: {reference}")
    source = locations[0]
    if category.name == "work-item":
        closure = source / "closure.md"
        if not closure.is_file():
            raise LifecycleError(
                "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "work-item lacks closure.md"
            )
        if "archive" in source.parts:
            _archived_work_item_entry(source)
            refresh_readme(root)
            return source
        fields = _parse_fields(closure.read_text(encoding="utf-8"))
        instant = fields.get("closed", "")
        closure_data = closure.read_bytes()
        _validate_closure(closure_data, instant)
        terminal_closure = _stamp_schema_marker(closure_data, "closure.md")
        target = _work_items_root(root) / "archive" / archive_month(instant) / slug
        if not source.is_dir() or source.parent.name != "active":
            raise LifecycleError("WI-INVALID-TARGET", "work-item migration requires active/")
        _validate_item_before_close(source)
        status = source / "status.md"
        terminal_status = _terminalize_status(status.read_bytes())
    else:
        instant = _validate_flat_terminal(category, source.read_bytes())
        target = (
            _work_items_root(root)
            / category.current_root
            / "archive"
            / archive_month(instant)
            / source.name
        )
        if "archive" in source.parts:
            if source != target:
                raise LifecycleError(
                    "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH",
                    f"{reference} is not in archive/{archive_month(instant)}",
                )
            refresh_readme(root)
            return source
    _preflight_readme_markers(root)
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        transaction.verify()
    if target.exists():
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", f"archive target exists: {target}")
    if category.name == "work-item":
        prior_status = status.read_bytes()
        prior_closure = closure.read_bytes()
        manifest = None
        bug_plans = ()
        manifest_path = source / BUG_DISPOSITIONS_MANIFEST
        if manifest_path.exists() or manifest_path.is_symlink():
            _path, _data, manifest = _load_bug_disposition_manifest(source, slug, instant)
            _path, _data, bug_plans = _prepare_bug_dispositions(root, source, slug, instant)
            if any(plan.action != "preserve-current" for plan in bug_plans):
                raise LifecycleError("WI-CLOSE-LINK-AUTHORITY", "legacy migration grants no bug terminalization")
        plan = _plan_parent_archive_links(
            root, source, target, bug_plans=bug_plans, bug_manifest=manifest,
            target_after_images={status: terminal_status, closure: terminal_closure},
            allow_protected_uri_updates=allow_protected_uri_updates,
        )
        readme = _work_items_root(root) / "README.md"
        readme_before = _capture_file_snapshot(readme, failure_id="WI-README-STALE")
        touched = []
        created_dirs = []
        readme_after = None
        moved = False
        _verify_project_binding_evidence(plan["ownerEvidence"], "WI-CLOSE-LINK-DRIFT")
        try:
            for row in plan["links"]:
                _verify_captured_file(plan["consumerCaptures"][row["path"]], "WI-CLOSE-LINK-DRIFT")
                touched.append(row)
                _atomic_write(row["path"], row["after"])
            _verify_parent_archive_link_targets(plan, archived=False, failure_id="WI-CLOSE-LINK-DRIFT")
            _atomic_write(status, terminal_status)
            _atomic_write(closure, terminal_closure)
            _mkdir_parents_tracked(target.parent, created_dirs)
            _replace_lifecycle_directory(source, target)
            moved = True
            readme_after = render_readme_bytes(root)
            refresh_readme(root)
            for row in plan["links"]:
                if _capture_file_snapshot(row["path"], failure_id="WI-CLOSE-LINK-VERIFY").data != row["after"]:
                    raise LifecycleError("WI-CLOSE-LINK-VERIFY", "URI consumer final image differs")
            _verify_parent_archive_link_targets(plan, archived=True, failure_id="WI-CLOSE-LINK-VERIFY")
        except BaseException as exc:
            failures = []
            try:
                if moved:
                    if source.exists() or not target.is_dir():
                        raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", "parent rollback locations differ")
                    for name, data in (("status.md", terminal_status), ("closure.md", terminal_closure)):
                        if _read_lifecycle_image(target / name, data, failure_id="WI-CLOSE-LINK-DRIFT") != data:
                            raise LifecycleError("WI-CLOSE-LINK-DRIFT", "parent rollback image differs")
                    _replace_lifecycle_directory(target, source)
                for path, before, after in ((status, prior_status, terminal_status), (closure, prior_closure, terminal_closure)):
                    if _read_lifecycle_image(path, before, after, failure_id="WI-CLOSE-LINK-DRIFT") not in {before, after}:
                        raise LifecycleError("WI-CLOSE-LINK-DRIFT", "parent rollback image differs")
                    _atomic_write(path, before)
            except BaseException as cause:
                failures.append(str(cause))
            for row in reversed(touched):
                try:
                    observed = _read_lifecycle_image(row["path"], row["before"], row["after"], failure_id="WI-CLOSE-LINK-DRIFT")
                    if observed not in {row["before"], row["after"]}:
                        raise LifecycleError("WI-CLOSE-LINK-DRIFT", "URI rollback consumer changed")
                    if observed == row["after"]:
                        _atomic_write(row["path"], row["before"])
                except BaseException as cause:
                    failures.append(str(cause))
            try:
                if readme.read_bytes() != readme_before.data:
                    if readme_after is None or readme.read_bytes() != readme_after:
                        raise LifecycleError("WI-README-STALE", "README rollback image differs")
                    _atomic_write(readme, readme_before.data)
            except BaseException as cause:
                failures.append(str(cause))
            for directory in reversed(created_dirs):
                try:
                    if directory.exists() and not any(directory.iterdir()):
                        directory.rmdir()
                except OSError as cause:
                    failures.append(str(cause))
            if failures:
                raise LifecycleError("WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE", f"{exc}; rollback incomplete: {'; '.join(failures)}") from exc
            raise
    else:
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        created_directories: list[_OwnedNativeCreation] = []
        try:
            LifecycleWriteTarget.make_directories(
                target.parent, transaction, created=created_directories,
            )
            _replace_lifecycle_directory(source, target, directory=False)
        except BaseException as exc:
            rollback_failures: list[str] = []
            for record in reversed(created_directories):
                if not record.creation_published:
                    continue  # The native creator already settled its unpublished abort.
                try:
                    LifecycleWriteTarget.remove_created_directory(
                        record, transaction,
                        failure_id="WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
                    )
                except BaseException as rollback_exc:
                    rollback_failures.append(f"directory {record.locator}: {rollback_exc}")
            if rollback_failures:
                raise LifecycleError(
                    "WI-LIFECYCLE-TRANSITION-ROLLBACK-INDETERMINATE",
                    f"category parent creation rollback failed: {exc}; " + "; ".join(rollback_failures),
                ) from exc
            raise
        try:
            refresh_readme(root)
        except LifecycleError as exc:
            raise LifecycleError("WI-README-STALE", str(exc)) from exc
    return target


def _v0_archive_manifest_row(root: Path, name: str) -> dict | None:
    """Return a validated frozen V0 row, including external archive evidence."""
    _preflight_current_decision_v0(root)
    manifest = _work_items_root(root) / DECISION_V0_MANIFEST
    if not manifest.is_file():
        return None
    payload = json.loads(manifest.read_text(encoding="utf-8"))
    return next((row for row in payload["entries"] if row["path"] == name), None)


def _v0_archive_input(inventory: dict, reference: str) -> dict:
    required = {
        "reference", "expectedSourceSha256", "archivedAt", "rationale",
        "evidence", "incomingLinks",
    }
    if set(inventory) != required or inventory["reference"] != reference:
        raise LifecycleError("WI-DECISION-V0-ARCHIVE-EVIDENCE", "V0 archive input has invalid shape")
    if (
        not isinstance(inventory["expectedSourceSha256"], str)
        or re.fullmatch(r"[0-9A-F]{64}", inventory["expectedSourceSha256"]) is None
        or not isinstance(inventory["archivedAt"], str)
        or any(
            not isinstance(inventory[field], str) or not inventory[field].strip()
            for field in ("rationale", "evidence")
        )
        or not isinstance(inventory["incomingLinks"], list)
    ):
        raise LifecycleError("WI-DECISION-V0-ARCHIVE-EVIDENCE", "V0 archive input is incomplete")
    try:
        _strict_utc(inventory["archivedAt"])
    except LifecycleError as exc:
        raise LifecycleError("WI-DECISION-V0-ARCHIVE-EVIDENCE", "V0 archive instant is invalid") from exc
    return inventory


def _migrate_v0_decision(root: Path, reference: str, inventory: dict, source: Path | None) -> Path:
    category, slug = _canonical_category(reference)
    assert category.name == "decision"
    work_items = _work_items_root(root)
    manifest = work_items / DECISION_V0_MANIFEST
    row = _v0_archive_manifest_row(root, f"{slug}.md")
    if row is None:
        raise LifecycleError("WI-DECISION-V0-UNADMITTED", "V0 archive source has no admitted manifest row")
    evidence_input = _v0_archive_input(inventory, reference)
    archive = work_items / "decisions" / "archive" / archive_month(evidence_input["archivedAt"]) / f"{slug}.md"
    if source is None:
        evidence = row.get("archiveEvidence")
        if (
            row["state"] != "retired" or not isinstance(evidence, dict)
            or evidence["archivePath"] != archive.relative_to(work_items).as_posix()
            or evidence["archivedAt"] != evidence_input["archivedAt"]
            or evidence["rationale"] != evidence_input["rationale"]
            or evidence["evidence"] != evidence_input["evidence"]
            or row["sha256"] != evidence_input["expectedSourceSha256"]
            or _category_locations(root, category, slug) != [archive]
        ):
            raise LifecycleError("WI-DECISION-V0-ARCHIVE-EVIDENCE", "V0 archive replay differs")
        return archive
    if row["state"] != "admitted":
        raise LifecycleError("WI-DECISION-V0-UNADMITTED", "V0 source is not admitted")
    current = _preflight_current_decision_v0(root).get(source.name)
    if current is None or current.raw_status not in category.terminal_statuses:
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "V0 decision is not terminal")
    source = _require_lifecycle_mutation_path(root, source, failure_id="WI-DECISION-V0-ARCHIVE-EVIDENCE")
    archive = _require_lifecycle_mutation_path(root, archive, failure_id="WI-DECISION-V0-ARCHIVE-EVIDENCE")
    manifest = _require_lifecycle_mutation_path(root, manifest, failure_id="WI-DECISION-V0-ARCHIVE-EVIDENCE")
    if _category_locations(root, category, slug) != [source] or os.path.lexists(archive):
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "V0 archive target is not uniquely absent")
    source_before = _capture_file_snapshot(source, failure_id="WI-DECISION-V0-HASH-MISMATCH").data
    if _sha256_bytes(source_before).upper() != row["sha256"] or row["sha256"] != evidence_input["expectedSourceSha256"]:
        raise LifecycleError("WI-DECISION-V0-HASH-MISMATCH", "V0 source hash differs from admission")
    manifest_before = _capture_file_snapshot(manifest, failure_id="WI-DECISION-V0-MANIFEST-INVALID").data
    payload = json.loads(manifest_before.decode("utf-8"))
    if payload["schemaVersion"] == 1 and any(
        entry["state"] == "retired" for entry in payload["entries"]
    ):
        raise LifecycleError("WI-DECISION-V0-MANIFEST-INVALID", "V1 retirement cannot be backfilled")
    references = _incoming_link_result(
        root, {source}, reference, strict_consumer_reads=True
    )["references"]
    if evidence_input["incomingLinks"] != references:
        raise LifecycleError("WI-LEGACY-LINK-UNMAPPED", "V0 incoming-link inventory is stale")
    links = _physical_archive_link_plans(
        root, source, archive, references, failure_id="WI-LEGACY-LINK-UNMAPPED"
    )
    _preflight_readme_markers(root)
    readme = work_items / "README.md"
    readme_before = readme.read_bytes() if readme.is_file() else None
    payload["schemaVersion"] = 2
    updated_row = next(entry for entry in payload["entries"] if entry["path"] == source.name)
    updated_row["state"] = "retired"
    updated_row["archiveEvidence"] = {
        "archivePath": archive.relative_to(work_items).as_posix(),
        "archivedAt": evidence_input["archivedAt"],
        "rationale": evidence_input["rationale"],
        "evidence": evidence_input["evidence"],
    }
    manifest_after = (json.dumps(payload, ensure_ascii=False, indent=2) + "\n").encode("utf-8")
    archive_parent_existed = archive.parent.is_dir()
    archive_root_existed = archive.parent.parent.is_dir()
    readme_attempted = False
    try:
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if transaction is not None:
            transaction.verify()
        archive.parent.mkdir(parents=True, exist_ok=True)
        _replace_lifecycle_directory(source, archive, directory=False)
        _atomic_write(manifest, manifest_after)
        for link in links:
            _atomic_write(link["path"], link["after"])
        readme_attempted = True
        refresh_readme(root)
        if archive.read_bytes() != source_before or manifest.read_bytes() != manifest_after:
            raise LifecycleError("WI-DECISION-V0-ARCHIVE-EVIDENCE", "V0 archive readback differs")
        if any(link["path"].read_bytes() != link["after"] for link in links):
            raise LifecycleError("WI-LEGACY-LINK-UNMAPPED", "V0 link readback differs")
        _preflight_current_decision_v0(root)
        return archive
    except Exception as exc:
        try:
            for link in reversed(links):
                observed = link["path"].read_bytes()
                if observed == link["after"]:
                    _atomic_write(link["path"], link["before"])
                elif observed != link["before"]:
                    raise ValueError("V0 link rollback preimage changed")
            observed_manifest = manifest.read_bytes()
            if observed_manifest == manifest_after:
                _atomic_write(manifest, manifest_before)
            elif observed_manifest != manifest_before:
                raise ValueError("V0 manifest rollback preimage changed")
            if readme_before is None:
                if readme_attempted and readme.exists():
                    _restore_readme_snapshot(readme, None)
            elif readme.read_bytes() != readme_before:
                _atomic_write(readme, readme_before)
            if archive.is_file() and not source.exists() and archive.read_bytes() == source_before:
                _replace_lifecycle_directory(archive, source, directory=False)
            elif archive.exists() or not source.is_file() or source.read_bytes() != source_before:
                raise ValueError("V0 source rollback location changed")
            for directory, existed in (
                (archive.parent, archive_parent_existed),
                (archive.parent.parent, archive_root_existed),
            ):
                if not existed and directory.is_dir():
                    if any(directory.iterdir()):
                        raise ValueError("new V0 archive parent gained content")
                    directory.rmdir()
        except Exception as rollback_exc:
            raise LifecycleError(
                "WI-DECISION-V0-ROLLBACK-FAILED", "V0 archive compensation failed"
            ) from rollback_exc
        raise


def migrate_legacy(
    root: Path, reference: str, *, incoming_links_inventory: Path | None,
    allow_protected_uri_updates: bool = False,
) -> Path:
    category, _slug = _canonical_category(reference)
    _admission_for(category.name)
    if incoming_links_inventory is None or not incoming_links_inventory.is_file():
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            f"legacy move requires an incoming-link inventory: {reference}",
        )
    try:
        inventory = json.loads(incoming_links_inventory.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise LifecycleError("WI-LEGACY-LINK-UNMAPPED", "invalid incoming-link inventory") from exc
    if not isinstance(inventory, dict) or inventory.get("reference") != reference:
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED", "incoming-link inventory is not target-bound"
        )
    if category.name == "decision":
        locations = _category_locations(root, category, _slug)
        if len(locations) > 1:
            raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", f"duplicate slug: {reference}")
        current = _work_items_root(root) / "decisions" / f"{_slug}.md"
        admitted = _preflight_current_decision_v0(root)
        if locations == [current] and current.name in admitted:
            return _migrate_v0_decision(root, reference, inventory, current)
        row = _v0_archive_manifest_row(root, current.name)
        if locations and row is not None and row.get("archiveEvidence") is not None:
            return _migrate_v0_decision(root, reference, inventory, None)
    return _move_terminal_category(root, reference, allow_protected_uri_updates=allow_protected_uri_updates)


@dataclass(frozen=True)
class PayloadDigestLimits:
    max_files: int
    max_entries: int
    max_bytes: int

    def __post_init__(self) -> None:
        for value in (self.max_files, self.max_entries, self.max_bytes):
            if type(value) is not int or value < 0:
                raise ValueError("payload digest limits must be non-negative integers")


_POINTER_LITERAL_IDENTIFIER_CHARS = frozenset(
    "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_.-/"
)


def _pointer_names_retained_root(
    pointer_text: str, root_name: str, manifest_path: str
) -> bool:
    """Accept only a literal retained root name or its manifest-authorized path."""

    for reference in (root_name, manifest_path):
        start = pointer_text.find(reference)
        while start >= 0:
            end = start + len(reference)
            left_is_literal = (
                start > 0 and pointer_text[start - 1] in _POINTER_LITERAL_IDENTIFIER_CHARS
            )
            right_is_literal = (
                end < len(pointer_text)
                and pointer_text[end] in _POINTER_LITERAL_IDENTIFIER_CHARS
            )
            if not left_is_literal and not right_is_literal:
                return True
            start = pointer_text.find(reference, start + 1)
    return False


def _payload_stream_regular_file(path: Path, expected: os.stat_result, digest, classifier) -> None:
    flags = os.O_RDONLY | getattr(os, "O_BINARY", 0) | getattr(os, "O_NOFOLLOW", 0)
    try:
        descriptor = os.open(path, flags)
    except OSError as exc:
        raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload file cannot be opened") from exc
    try:
        opened = os.fstat(descriptor)
        if not classifier._same_open_identity(opened, expected) or not stat.S_ISREG(opened.st_mode):
            raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload file identity changed while opening")
        while True:
            block = os.read(descriptor, 1024 * 1024)
            if not block:
                break
            digest.update(block)
        final = os.fstat(descriptor)
        if not classifier._same_open_identity(final, opened):
            raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload file identity changed while reading")
    except OSError as exc:
        raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload file cannot be read") from exc
    finally:
        os.close(descriptor)


def _payload_limited_tree_entries(path: Path, limits: PayloadDigestLimits) -> list[Path]:
    """Walk at most one entry beyond the retention ceiling without preloading directories."""

    entries: list[Path] = []
    directories = [path]
    while directories:
        directory = directories.pop()
        try:
            with os.scandir(directory) as iterator:
                for entry in iterator:
                    if len(entries) >= limits.max_entries:
                        raise LifecycleError(
                            "WI-CATEGORY-MIGRATION-PAYLOAD",
                            "payload exceeds retention entry limit",
                        )
                    candidate = Path(entry.path)
                    info = entry.stat(follow_symlinks=False)
                    if entry.is_symlink() or bool(
                        getattr(info, "st_file_attributes", 0)
                        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
                    ):
                        raise LifecycleError(
                            "WI-CATEGORY-MIGRATION-PAYLOAD",
                            "payload tree entry is not ordinary",
                        )
                    if stat.S_ISDIR(info.st_mode):
                        directories.append(candidate)
                    elif not stat.S_ISREG(info.st_mode):
                        raise LifecycleError(
                            "WI-CATEGORY-MIGRATION-PAYLOAD",
                            "unsupported tree entry",
                        )
                    entries.append(candidate)
        except OSError as exc:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD", "payload tree cannot be enumerated"
            ) from exc
    entries.sort(key=lambda item: item.relative_to(path).as_posix())
    return entries


def _payload_digest(path: Path, *, limits: PayloadDigestLimits | None = None) -> tuple[str, str]:
    if path.is_symlink():
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-PAYLOAD",
            f"symbolic-link payload is not admitted: {path}",
        )
    if path.is_file():
        if limits is None:
            return (
                MIGRATION_DIGEST_ALGORITHMS["file"],
                hashlib.sha256(path.read_bytes()).hexdigest(),
            )
        try:
            expected = path.lstat()
        except OSError as exc:
            raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload file is unavailable") from exc
        if _lifecycle_path_has_reparse(path) or not stat.S_ISREG(expected.st_mode):
            raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload file is not ordinary")
        if limits.max_entries < 1 or limits.max_files < 1 or expected.st_size > limits.max_bytes:
            raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload exceeds retention limits")
        digest = hashlib.sha256()
        _payload_stream_regular_file(path, expected, digest, _scratch_classifier_module())
        return (
            MIGRATION_DIGEST_ALGORITHMS["file"],
            digest.hexdigest(),
        )
    if not path.is_dir():
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-PAYLOAD",
            f"payload is not a file or directory: {path}",
        )
    digest = hashlib.sha256()
    digest.update(b"sha256-tree-entries-v1\0")
    if limits is None:
        entries = sorted(path.rglob("*"), key=lambda item: item.relative_to(path).as_posix())
        classifier = None
    else:
        entries = _payload_limited_tree_entries(path, limits)
        classifier = _scratch_classifier_module()
    file_count = 0
    total_bytes = 0
    for entry in entries:
        if entry.is_symlink():
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD",
                f"symbolic-link tree entry is not admitted: {entry}",
            )
        relative = entry.relative_to(path).as_posix().encode("utf-8")
        if entry.is_dir():
            if limits is not None and _lifecycle_path_has_reparse(entry):
                raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload tree entry is not ordinary")
            digest.update(b"D")
            digest.update(len(relative).to_bytes(8, "big"))
            digest.update(relative)
        elif entry.is_file():
            if limits is None:
                data = entry.read_bytes()
                size = len(data)
            else:
                try:
                    expected = entry.lstat()
                except OSError as exc:
                    raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload tree entry is unavailable") from exc
                if _lifecycle_path_has_reparse(entry) or not stat.S_ISREG(expected.st_mode):
                    raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload tree entry is not ordinary")
                file_count += 1
                total_bytes += expected.st_size
                if file_count > limits.max_files or total_bytes > limits.max_bytes:
                    raise LifecycleError("WI-CATEGORY-MIGRATION-PAYLOAD", "payload exceeds retention file or byte limit")
                data = None
                size = expected.st_size
            digest.update(b"F")
            digest.update(len(relative).to_bytes(8, "big"))
            digest.update(relative)
            digest.update(size.to_bytes(8, "big"))
            if data is None:
                assert limits is not None and classifier is not None
                _payload_stream_regular_file(entry, expected, digest, classifier)
            else:
                digest.update(data)
        else:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD",
                f"unsupported tree entry: {entry}",
            )
    return MIGRATION_DIGEST_ALGORITHMS["directory"], digest.hexdigest()


def _selected_migration_records(root: Path) -> list[tuple[Category, str, Path]]:
    work_items = _work_items_root(root)
    selected: list[tuple[Category, str, Path]] = []
    active = work_items / "active"
    if active.is_dir():
        for item in sorted(path for path in active.iterdir() if path.is_dir()):
            status = item / "status.md"
            fields = (
                _parse_fields(status.read_text(encoding="utf-8", errors="replace"))
                if status.is_file()
                else {}
            )
            if (item / "closure.md").is_file() or fields.get("status") in CATEGORIES[
                "work-item"
            ].terminal_statuses:
                selected.append((CATEGORIES["work-item"], item.name, item))
    for category in CATEGORIES.values():
        if category.current_kind != "flat":
            continue
        current = work_items / category.current_root
        if not current.is_dir():
            continue
        for path in sorted(current.glob("*.md")):
            fields = _parse_fields(path.read_text(encoding="utf-8", errors="replace"))
            if fields.get("status") in category.terminal_statuses:
                selected.append((category, path.stem, path))
    return sorted(selected, key=lambda item: (item[0].name, item[1]))


def _planned_migration_target(
    root: Path,
    category: Category,
    slug: str,
    source: Path,
) -> tuple[str, Path]:
    locations = _category_locations(root, category, slug)
    if locations != [source]:
        failure = "WI-CATEGORY-DUAL-LOCATION" if len(locations) > 1 else "WI-INVALID-TARGET"
        raise LifecycleError(
            failure,
            f"{category.name}:{slug} does not resolve to its selected source",
        )
    return _validated_migration_payload_target(root, category, slug, source)


def _validated_migration_payload_target(
    root: Path,
    category: Category,
    slug: str,
    payload: Path,
) -> tuple[str, Path]:
    inventory = _archive_entity_inventory(root)
    _reject_unbound_archive_selection(inventory, path=payload,
                                     slug=slug if category.current_kind == "work-item" else None)
    if any(entity.kind == "archive-metadata" and entity.path == payload for entity in inventory.entities):
        raise LifecycleError("WI-CATEGORY-TERMINAL-EVIDENCE-MISSING", "archive metadata supplies no category terminal authority")
    if category.name == "work-item":
        closure = payload / "closure.md"
        if not closure.is_file():
            raise LifecycleError(
                "WI-CATEGORY-TERMINAL-EVIDENCE-MISSING",
                f"work-item:{slug} lacks closure.md",
            )
        fields = _parse_fields(closure.read_text(encoding="utf-8"))
        instant = fields.get("closed", "")
        _validate_closure(closure.read_bytes(), instant)
        _validate_item_before_close(payload)
        target = _work_items_root(root) / "archive" / archive_month(instant) / slug
    else:
        instant = _validate_flat_terminal(category, payload.read_bytes())
        target = (
            _work_items_root(root)
            / category.current_root
            / "archive"
            / archive_month(instant)
            / f"{slug}.md"
        )
    return instant, target


MARKDOWN_LINK_RE = re.compile(
    r"\[(?P<label>[^\]\r\n]+)\]\(\s*(?:<(?P<angle>[^<>()\s\r\n]+)>|(?P<bare>[^()\s\r\n]+))\s*\)"
)


@dataclass(frozen=True)
class MarkdownLocalLink:
    label: str
    href: str
    href_start: int
    href_end: int


def _markdown_local_links(text: str) -> Iterable[MarkdownLocalLink]:
    """Yield only complete, closed, local Markdown link destinations."""
    for match in MARKDOWN_LINK_RE.finditer(text):
        href = match.group("angle") or match.group("bare")
        yield MarkdownLocalLink(
            label=match.group("label"),
            href=href,
            href_start=match.start("angle") if match.group("angle") is not None else match.start("bare"),
            href_end=match.end("angle") if match.group("angle") is not None else match.end("bare"),
        )


URI_SCHEME_RE = re.compile(r"^[A-Za-z][A-Za-z0-9+.-]*:")


def _local_markdown_href_parts(href: str) -> tuple[str, str] | None:
    """Split one local href into filesystem identity and preserved suffix."""
    if (
        not href
        or href.startswith(("#", "/", "\\"))
        or URI_SCHEME_RE.match(href)
    ):
        return None
    suffix_offsets = [offset for marker in ("#", "?") if (offset := href.find(marker)) >= 0]
    split_at = min(suffix_offsets) if suffix_offsets else len(href)
    filesystem_identity = href[:split_at]
    if not filesystem_identity:
        return None
    return filesystem_identity, href[split_at:]


def _markdown_href_resolves(base: Path, href: str, expected: Path) -> bool:
    parts = _local_markdown_href_parts(href)
    return parts is not None and (base / parts[0]).resolve() == expected.resolve()


def _incoming_attachment_kind(data: bytes) -> str | None:
    """Identify admitted opaque formats; never validate or project native content."""
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return "png"
    if (
        data.startswith(b"BM") and len(data) >= 18
        and int.from_bytes(data[14:18], "little") in {12, 40, 52, 56, 64, 108, 124}
    ):
        return "bitmap"
    if re.match(rb"%PDF-[12]\.[0-9](?:\s|$)", data):
        return "pdf"
    if data.startswith(b"PK\x03\x04"):
        import io
        import zipfile

        try:
            with zipfile.ZipFile(io.BytesIO(data)) as package:
                names = set(package.namelist())
        except (zipfile.BadZipFile, UnicodeError, NotImplementedError):
            return None
        if {"[Content_Types].xml", "_rels/.rels", "word/document.xml"} <= names:
            return "word-ooxml"
    return None


class _RetainedConsumerScanPreparation:
    """Invocation-owned validator and captured/decoded inputs, never admission."""
    def __init__(self, acquired_input=None) -> None:
        self._validator: object | None = None
        self.acquired_input = acquired_input
        self._items: dict[Path, tuple[CapturedFileSnapshot, list[dict], list[dict[str, object]], tuple[str, ...]] | None | Exception] = {}
        self._retained_claim_targets: dict[Path, frozenset[str] | None] = {}

    def validator(self):
        if self._validator is None:
            self._validator = _validator_module()
        return self._validator

    def item(self, item: Path):
        if item not in self._items:
            ledger_path = item / "agent-runs.jsonl"
            try:
                if (ledger_path.exists() if self.acquired_input is None else _input_exists(ledger_path, self.acquired_input)):
                    validator = self.validator()
                    carrier = _capture_file_snapshot(ledger_path, failure_id="WI-CATEGORY-MIGRATION-INVENTORY",
                                                     maximum_bytes=validator.MAX_LEDGER_EVENTS * validator.MAX_LEDGER_LINE_BYTES,
                                                     acquired_input=self.acquired_input)
                    diagnostics: list[str] = []
                    metadata: list[dict[str, object]] = []
                    events = validator.load_jsonl(ledger_path, diagnostics, metadata, carrier.data)
                    self._items[item] = (carrier, events, metadata, tuple(diagnostics))
                else:
                    # A cached None means acquisition proved the ledger absent.
                    self._items[item] = None
            except Exception as exc:
                # Preserve failed acquisition distinctly from an absent ledger.
                # A later leaf in this invocation must not turn that failure into NoClaim.
                self._items[item] = exc
                raise
        prepared = self._items[item]
        if isinstance(prepared, Exception):
            raise prepared
        return prepared

    def retained_claim_targets(self, item: Path) -> frozenset[str] | None:
        """Recognize addressed claims; the validator remains the admission authority."""
        if item not in self._retained_claim_targets:
            self._retained_claim_targets[item] = None
            prepared = self.item(item)
            if prepared is None:
                self._retained_claim_targets[item] = frozenset()
            else:
                _carrier, events, _metadata, _diagnostics = prepared
                targets: set[str] = set()
                for event in events:
                    evidence = event.get("evidence")
                    if not isinstance(evidence, list):
                        continue
                    for entry in evidence:
                        if not isinstance(entry, dict) or not isinstance(entry.get("result"), str):
                            continue
                        try:
                            profile = json.loads(entry["result"])
                        except (TypeError, ValueError):
                            continue
                        if not isinstance(profile, dict) or profile.get("kind") != "retained-preimage":
                            continue
                        ref = entry.get("ref")
                        if isinstance(ref, str):
                            targets.add(ref)
                        provenance = profile.get("provenance")
                        if isinstance(provenance, dict) and isinstance(provenance.get("snapshot"), str):
                            targets.add(provenance["snapshot"])
                self._retained_claim_targets[item] = frozenset(targets)
        return self._retained_claim_targets[item]


def _owned_work_item_input_location(
    consumer_rel: str, consumer_resolved: Path, work_items: Path, work_items_resolved: Path,
) -> tuple[Path, str] | None:
    """Resolve only canonical active/archive item input leaves to their owner."""
    try:
        resolved_rel = consumer_resolved.relative_to(work_items_resolved).as_posix()
    except ValueError:
        return None
    if resolved_rel != consumer_rel:
        return None
    parts = Path(consumer_rel).parts
    if len(parts) >= 4 and parts[0] == "active" and parts[2] == "inputs":
        owner_parts = parts[:2]
    elif (len(parts) >= 5 and parts[0] == "archive" and parts[3] == "inputs"
          and re.fullmatch(r"[0-9]{4}-(?:0[1-9]|1[0-2])", parts[1]) and parts[1][:4] != "0000"):
        owner_parts = parts[:3]
    else:
        return None
    owner = work_items.joinpath(*owner_parts)
    relative = Path(*parts[len(owner_parts):]).as_posix()
    return owner, relative


def _retained_preimage_consumer(
    consumer: Path, work_items: Path, *, scan_preparation: _RetainedConsumerScanPreparation | None = None,
) -> bool:
    """Select only one bound payload or its exact provenance snapshot."""
    parts = consumer.relative_to(work_items).parts
    item_parts = 2 if len(parts) >= 3 and parts[0] == "active" else \
        3 if len(parts) >= 4 and parts[0] == "archive" else 0
    if not item_parts:
        return False
    item = work_items.joinpath(*parts[:item_parts])
    relative = consumer.relative_to(item).as_posix()
    preparation = _RetainedConsumerScanPreparation() if scan_preparation is None else scan_preparation
    validator = preparation.validator()
    acquired_input = preparation.acquired_input
    selected_item = item if acquired_input is None else _call_acquired_input(acquired_input, "validator_path", item, validator)
    try:
        prepared = preparation.item(item)
        if prepared is None:
            return False
        carrier, events, metadata, _diagnostics = prepared
        for event, identity in zip(events, metadata):
            profile_errors: list[str] = []
            profiles = validator.retained_preimage_profiles(event, selected_item, profile_errors)
            if profile_errors:
                continue
            for entry, profile in profiles:
                if relative not in {entry["ref"], profile["provenance"]["snapshot"]}:
                    continue
                run_id = event.get("runId")
                if not isinstance(run_id, str) or sum(isinstance(row.get("runId"), str)
                    and row["runId"].casefold() == run_id.casefold() for row in events) != 1:
                    continue
                association_key = f"review-artifact-custody/historical-pass/{identity['sha256']}.json"
                association = _capture_file_snapshot(item / association_key, failure_id="WI-CATEGORY-MIGRATION-INVENTORY",
                                                     maximum_bytes=validator.MAX_LEDGER_LINE_BYTES, acquired_input=acquired_input)
                provenance = _capture_file_snapshot(item / profile["provenance"]["snapshot"],
                                                     failure_id="WI-CATEGORY-MIGRATION-INVENTORY", acquired_input=acquired_input)
                payload = validator.capture_retained_preimage_payload(selected_item, entry, profile)
                # Resolve exactly the captured association/snapshot; unrelated
                # declarations and legacy rows cannot become a new veto.
                custody, custody_errors = validator.resolve_historical_pass_custody(
                    selected_item, carrier.data, events, metadata, selected_association=association_key,
                    candidate_blobs={association_key: association.data,
                                     profile["provenance"]["snapshot"]: provenance.data},
                )
                locator = custody.get((identity["line"], identity["sha256"], run_id, event.get("artifact")))
                if custody_errors or locator != profile["provenance"]["snapshot"]:
                    continue
                record_errors: list[str] = []
                if not validator._validate_event(event, selected_item, set(), record_errors,
                    historical_pass_snapshot=locator, retained_payloads={entry["ref"]: payload}) or record_errors:
                    continue
                captures = (carrier, association, provenance, payload)
                for snapshot in captures:
                    _verify_captured_file(snapshot, "WI-CATEGORY-MIGRATION-INVENTORY", acquired_input=acquired_input)
                transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
                if transaction is not None:
                    transaction.observe_retained_inputs(captures if acquired_input is None else
                        tuple(_call_acquired_input(acquired_input, "current_capture", snapshot)
                              if _settled_history_input(acquired_input) is not None else acquired_input.files[snapshot.path].current
                              for snapshot in captures))
                return True
    except (OSError, ValueError, LifecycleError, validator.load_lifecycle_owner().LifecycleError):
        # Failed admission is not an exemption. The caller retains its existing
        # native/UTF-8/reference checks and strict refusal for unreadable input.
        return False
    return False


def _incoming_literal_pattern(literal_path):
    return re.compile(r"(?<![A-Za-z0-9_.\\/-]){}(?![A-Za-z0-9_.\\/-])".format(
        re.escape(literal_path).replace("/", r"[\\/]")))


def _incoming_link_result(
    root: Path,
    owned_paths: Iterable[Path],
    reference: str,
    *,
    literal_path_references: Iterable[str] = (),
    mutable_consumers_only: bool = False,
    scan_markdown_links: bool = True,
    strict_consumer_reads: bool = False,
    acquired_input=None,
) -> dict:
    work_items = _work_items_root(root, acquired_input=acquired_input)
    physical: list[dict[str, str]] = []
    logical: list[dict[str, str]] = []
    owned_resolved = frozenset(_input_resolve(path, acquired_input) for path in owned_paths)
    if not owned_resolved:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            f"incoming-link scan has no owned paths for {reference}",
        )
    literal_paths = tuple(sorted(set(literal_path_references)))
    if any(not path or path.startswith(("/", "\\")) for path in literal_paths):
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            f"incoming-link scan has invalid literal path for {reference}",
        )
    literal_patterns = tuple(
        (
            literal_path,
            _incoming_literal_pattern(literal_path),
        )
        for literal_path in literal_paths
    )

    def belongs_to_owned(path: Path) -> bool:
        return any(
            path == owned or owned in path.parents
            for owned in owned_resolved
        )

    preparation = _RetainedConsumerScanPreparation(acquired_input)
    work_items_resolved = _input_resolve(work_items, acquired_input)

    for consumer in sorted(path for path in _input_descendants(work_items, acquired_input) if _input_is_file(path, acquired_input)):
        if consumer.name in {"README.md", "index.md"}:
            continue
        consumer_resolved = _input_resolve(consumer, acquired_input)
        if belongs_to_owned(consumer_resolved):
            continue
        consumer_rel = consumer.relative_to(work_items).as_posix()
        if mutable_consumers_only and "archive" in Path(consumer_rel).parts:
            continue
        ordinary_input_without_claim = False
        input_location = _owned_work_item_input_location(
            consumer_rel, consumer_resolved, work_items, work_items_resolved,
        )
        if input_location is not None:
            input_item, input_ref = input_location
            try:
                claim_targets = preparation.retained_claim_targets(input_item)
            except (OSError, ValueError, LifecycleError,
                    preparation.validator().load_lifecycle_owner().LifecycleError):
                claim_targets = None
            if claim_targets is not None and input_ref not in claim_targets:
                ordinary_input_without_claim = True
        if _retained_preimage_consumer(consumer, work_items, scan_preparation=preparation):
            continue
        try:
            consumer_bytes = _input_bytes(consumer, acquired_input)
            if ordinary_input_without_claim:
                continue
            if consumer.suffix.lower() not in {".md", ".json", ".jsonl"} and _incoming_attachment_kind(consumer_bytes) is not None:
                continue
            text = consumer_bytes.decode("utf-8")
        except (OSError, UnicodeError) as exc:
            if strict_consumer_reads:
                raise LifecycleError(
                    "WI-CATEGORY-MIGRATION-INVENTORY",
                    f"cannot classify live incoming-link consumer: {consumer_rel}",
                ) from exc
            continue
        if reference in text:
            logical.append(
                {"consumer": consumer_rel, "kind": "logical", "value": reference}
            )
        if scan_markdown_links:
            for link in _markdown_local_links(text):
                raw = link.href
                href_parts = _local_markdown_href_parts(raw)
                if href_parts is None:
                    continue
                candidate = _input_resolve(consumer.parent / href_parts[0], acquired_input)
                if belongs_to_owned(candidate):
                    physical.append(
                        {
                            "consumer": consumer_rel,
                            "kind": "physical",
                            "value": raw,
                        }
                    )
        for literal_path, literal_pattern in literal_patterns:
            if literal_pattern.search(text):
                physical.append(
                    {
                        "consumer": consumer_rel,
                        "kind": "physical",
                        "value": literal_path,
                    }
                )
    references = sorted(
        {tuple(sorted(row.items())): row for row in physical + logical}.values(),
        key=lambda item: (item["consumer"], item["kind"], item["value"]),
    )
    if physical:
        result = "unmapped"
    elif logical:
        result = "logical-only"
    else:
        result = "clear"
    return {"result": result, "references": references}


def _validate_incoming_link_snapshot(reference: str, snapshot: dict, *, label: str) -> None:
    if not isinstance(snapshot, dict):
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            f"{label} incoming-link inventory is invalid for {reference}",
        )
    result = snapshot.get("result")
    links = snapshot.get("references")
    if result not in {"clear", "logical-only"} or not isinstance(links, list):
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            f"{label} incoming links are not logical-only for {reference}",
        )
    expected_result = "logical-only" if links else "clear"
    if result != expected_result:
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            f"{label} incoming-link result differs from its rows for {reference}",
        )
    seen: set[tuple[str, str, str]] = set()
    for link in links:
        if (
            not isinstance(link, dict)
            or not isinstance(link.get("consumer"), str)
            or link.get("kind") != "logical"
            or link.get("value") != reference
        ):
            raise LifecycleError(
                "WI-LEGACY-LINK-UNMAPPED",
                f"{label} incoming link is not category-qualified logical for {reference}",
            )
        identity = (link["consumer"], link["kind"], link["value"])
        if identity in seen:
            raise LifecycleError(
                "WI-LEGACY-LINK-UNMAPPED",
                f"{label} incoming-link inventory repeats a row for {reference}",
            )
        seen.add(identity)


def _validate_incoming_link_compatibility(
    root: Path,
    reference: str,
    planned: dict,
    current: dict,
    *,
    resolved_location: Path,
) -> None:
    for label, snapshot in (("planned", planned), ("current", current)):
        _validate_incoming_link_snapshot(reference, snapshot, label=label)
    try:
        resolved = resolve_category(root, reference)
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            f"logical reference does not resolve uniquely: {reference}",
        ) from exc
    if resolved != resolved_location.resolve():
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            f"logical reference resolves outside the migration payload: {reference}",
        )


def build_migration_inventory(root: Path) -> dict:
    work_items = _work_items_root(root)
    rows: list[dict] = []
    for category, slug, source in _selected_migration_records(root):
        reference = f"{category.name}:{slug}"
        algorithm, input_hash = _payload_digest(source)
        admission_row = _admission_for(category.name)
        row = {
            "reference": reference,
            "category": category.name,
            "source": source.relative_to(work_items).as_posix(),
            "target": None,
            "terminalInstant": None,
            "inputSha256": input_hash,
            "digestAlgorithm": algorithm,
            "incomingLinks": None,
            "admission": {
                "result": "admitted",
                "reader": admission_row.current_reader,
                "validator": admission_row.terminal_validator,
                "utcOwner": admission_row.utc_field_owner,
                "negativeFixture": admission_row.negative_fixture,
            },
        }
        try:
            instant, target = _planned_migration_target(
                root, category, slug, source
            )
            row["terminalInstant"] = instant
            row["target"] = target.relative_to(work_items).as_posix()
        except LifecycleError as exc:
            row["admission"] = {
                "result": "denied",
                "failureId": exc.failure_id,
                "reason": str(exc),
            }
        owned_paths = {source}
        if row["target"] is not None:
            owned_paths.add(work_items / Path(row["target"]))
        row["incomingLinks"] = _incoming_link_result(
            root,
            owned_paths,
            reference,
        )
        rows.append(row)
    return {
        "schemaVersion": MIGRATION_SCHEMA_VERSION,
        "owner": MIGRATION_OWNER,
        "workItemsRoot": str(work_items.resolve()),
        "digestAlgorithms": dict(MIGRATION_DIGEST_ALGORITHMS),
        "rows": rows,
    }


def write_migration_inventory(root: Path, output: Path) -> dict:
    _static_guide(
        _work_items_root(root) / "README.md",
        allow_marker_bootstrap=True,
    )
    inventory = build_migration_inventory(root)
    _atomic_write(
        output,
        (json.dumps(inventory, indent=2, sort_keys=True) + "\n").encode("utf-8"),
    )
    for row in inventory["rows"]:
        admission = row["admission"]
        if admission.get("result") != "admitted":
            raise LifecycleError(
                admission.get("failureId", "CATEGORY-MIGRATION-ADMISSION-GATE"),
                admission.get("reason", f"unadmitted row: {row['reference']}"),
            )
        if row["incomingLinks"].get("result") == "unmapped":
            raise LifecycleError(
                "WI-LEGACY-LINK-UNMAPPED",
                f"physical incoming links remain for {row['reference']}",
            )
    return inventory


def _reject_duplicate_json_pairs(pairs: list[tuple[str, object]]) -> dict:
    value: dict[str, object] = {}
    for key, item in pairs:
        if key in value:
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY",
                f"migration inventory repeats JSON key: {key}",
            )
        value[key] = item
    return value


def _capture_path_parent_chain(
    path: Path,
    failure_id: str,
) -> CapturedPathParentChain:
    parent = _lifecycle_unresolved_absolute(path).parent
    cursor = Path(parent.anchor)
    participants = []
    try:
        root_info = cursor.lstat()
        if stat.S_ISLNK(root_info.st_mode) or bool(
            getattr(root_info, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        ):
            raise OSError("path root is a link or reparse point")
        participants.append((cursor, _lifecycle_file_identity(root_info)))
        for part in parent.parts[1:]:
            if part in {"", "."}:
                continue
            if part == "..":
                cursor = cursor.parent
                continue
            cursor /= part
            info = cursor.lstat()
            if not stat.S_ISDIR(info.st_mode) or stat.S_ISLNK(info.st_mode) or bool(
                getattr(info, "st_file_attributes", 0)
                & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
            ):
                raise OSError("path parent is not a regular non-reparse directory")
            participants.append((cursor, _lifecycle_file_identity(info)))
    except OSError as exc:
        raise LifecycleError(failure_id, "file parent chain cannot be captured") from exc
    return CapturedPathParentChain(tuple(participants))


def _verify_captured_parent_chain(
    chain: CapturedPathParentChain,
    failure_id: str,
) -> None:
    try:
        for path, identity in chain.participants:
            info = path.lstat()
            if (
                not stat.S_ISDIR(info.st_mode)
                or stat.S_ISLNK(info.st_mode)
                or bool(
                    getattr(info, "st_file_attributes", 0)
                    & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
                )
                or _lifecycle_file_identity(info) != identity
            ):
                raise OSError("captured parent identity changed")
    except OSError as exc:
        raise LifecycleError(failure_id, "captured file parent chain changed") from exc


def _open_readonly_nofollow(path: Path) -> int:
    if os.name != "nt":
        nofollow = getattr(os, "O_NOFOLLOW", 0)
        nonblock = getattr(os, "O_NONBLOCK", 0)
        if not nofollow or not nonblock:
            raise OSError(errno.ENOTSUP, "nonblocking no-follow open is unavailable")
        # A regular pathname may become a FIFO before open; inspect without blocking.
        return os.open(path, os.O_RDONLY | nofollow | nonblock)

    import ctypes
    import ctypes.wintypes
    import msvcrt

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        ctypes.wintypes.LPCWSTR,
        ctypes.wintypes.DWORD,
        ctypes.wintypes.DWORD,
        ctypes.wintypes.LPVOID,
        ctypes.wintypes.DWORD,
        ctypes.wintypes.DWORD,
        ctypes.wintypes.HANDLE,
    ]
    create_file.restype = ctypes.wintypes.HANDLE
    native_handle = create_file(
        str(path),
        0x80000000,  # GENERIC_READ
        0x00000001 | 0x00000002 | 0x00000004,
        None,
        3,  # OPEN_EXISTING
        0x00200000,  # FILE_FLAG_OPEN_REPARSE_POINT
        None,
    )
    if native_handle == ctypes.wintypes.HANDLE(-1).value:
        raise OSError(ctypes.get_last_error(), "cannot open file without following links")
    try:
        return msvcrt.open_osfhandle(
            native_handle,
            os.O_RDONLY | getattr(os, "O_BINARY", 0),
        )
    except BaseException:
        kernel32.CloseHandle(native_handle)
        raise


def _capture_file_identity_prefix(path: Path, *, failure_id: str,
    maximum_bytes: int | None = None, require_single_link: bool = False):
    parent_chain = _capture_path_parent_chain(path, failure_id)
    descriptor = -1
    try:
        observed = path.lstat()
        if (not stat.S_ISREG(observed.st_mode) or stat.S_ISLNK(observed.st_mode)
            or (require_single_link and observed.st_nlink != 1)
            or (maximum_bytes is not None and observed.st_size > maximum_bytes)
            or bool(getattr(observed, "st_file_attributes", 0) & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0))
            or _lifecycle_path_has_reparse(path)):
            raise OSError("snapshot is not a bounded owned regular file")
        descriptor = _open_readonly_nofollow(path)
        before = os.fstat(descriptor)
        if (not stat.S_ISREG(before.st_mode) or (require_single_link and before.st_nlink != 1)
            or bool(getattr(before, "st_file_attributes", 0) & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0))
            or _lifecycle_file_snapshot_key(before)[:5] != _lifecycle_file_snapshot_key(observed)[:5]):
            raise OSError("snapshot descriptor differs from its pathname")
        return parent_chain, observed, descriptor, before
    except OSError as exc:
        if descriptor >= 0:
            os.close(descriptor)
        raise LifecycleError(failure_id, "file snapshot identity cannot be captured") from exc


def _capture_structural_node(path: Path, failure_id: str) -> tuple:
    chain, observed, descriptor, before = _capture_file_identity_prefix(path, failure_id=failure_id)
    try:
        after = os.fstat(descriptor)
        current = path.lstat()
        if (_lifecycle_file_snapshot_key(before) != _lifecycle_file_snapshot_key(after)
            or _lifecycle_file_snapshot_key(observed) != _lifecycle_file_snapshot_key(current)
            or _lifecycle_file_identity(current) != _lifecycle_file_identity(before)
            or _lifecycle_path_has_reparse(path)):
            raise LifecycleError(failure_id, "structural node changed during observation")
        _verify_captured_parent_chain(chain, failure_id)
        return path, chain, (_lifecycle_file_snapshot_key(observed), _lifecycle_file_snapshot_key(before))
    except OSError as exc:
        raise LifecycleError(failure_id, "structural node unavailable") from exc
    finally:
        os.close(descriptor)


def _verify_structural_node(node: tuple, failure_id: str) -> None:
    path, chain, key = node
    _verify_captured_parent_chain(chain, failure_id)
    current = _capture_structural_node(path, failure_id)
    if current[2] != key:
        raise LifecycleError(failure_id, "structural node identity or stat key changed")


def _capture_file_snapshot(
    path: Path,
    *,
    failure_id: str,
    maximum_bytes: int = 4 * 1024 * 1024,
    require_single_link: bool = False,
    acquired_input=None,
) -> CapturedFileSnapshot:
    if acquired_input is not None:
        return _call_acquired_input(acquired_input, "file_snapshot", path, maximum_bytes=maximum_bytes,
                                    require_single_link=require_single_link, failure_id=failure_id)
    parent_chain, observed, descriptor, before = _capture_file_identity_prefix(
        path, failure_id=failure_id, maximum_bytes=maximum_bytes, require_single_link=require_single_link)
    try:
        with os.fdopen(descriptor, "rb", closefd=True) as stream:
            descriptor = -1
            data = stream.read(before.st_size + 1)
            middle = os.fstat(stream.fileno())
            stream.seek(0)
            verified = stream.read(before.st_size + 1)
            after = os.fstat(stream.fileno())
        current = path.lstat()
    except OSError as exc:
        raise LifecycleError(
            failure_id, "file snapshot identity cannot be captured"
        ) from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    identity = _lifecycle_file_identity(before)
    before_key = _lifecycle_file_snapshot_key(before)
    if (
        len(data) > maximum_bytes
        or len(data) != before.st_size
        or data != verified
        or before_key != _lifecycle_file_snapshot_key(middle)
        or before_key != _lifecycle_file_snapshot_key(after)
        or _lifecycle_file_snapshot_key(observed)
        != _lifecycle_file_snapshot_key(current)
        or _lifecycle_file_identity(current) != identity
        or stat.S_ISLNK(current.st_mode)
        or (require_single_link and current.st_nlink != 1)
        or bool(
            getattr(current, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        )
        or _lifecycle_path_has_reparse(path)
    ):
        raise LifecycleError(failure_id, "file snapshot changed during capture")
    _verify_captured_parent_chain(parent_chain, failure_id)
    return CapturedFileSnapshot(
        path, identity, len(data), data, parent_chain, require_single_link
    )


def _verify_captured_file(snapshot: CapturedFileSnapshot, failure_id: str, *, acquired_input=None) -> None:
    if acquired_input is not None:
        if _settled_history_input(acquired_input) is not None:
            _call_acquired_input(acquired_input, "current_capture", snapshot)
            return
        actual = _capture_file_snapshot(snapshot.path, failure_id=failure_id,
            maximum_bytes=snapshot.length, require_single_link=snapshot.require_single_link,
            acquired_input=acquired_input)
        if (actual.identity != snapshot.identity or actual.length != snapshot.length
                or actual.data != snapshot.data
                or actual.parent_chain.participants != snapshot.parent_chain.participants):
            raise LifecycleError(failure_id, "captured original acquisition identity or bytes changed")
        return
    _verify_captured_parent_chain(snapshot.parent_chain, failure_id)
    descriptor = -1
    try:
        observed = snapshot.path.lstat()
        descriptor = _open_readonly_nofollow(snapshot.path)
        with os.fdopen(descriptor, "rb", closefd=True) as stream:
            descriptor = -1
            before = os.fstat(stream.fileno())
            if _lifecycle_file_snapshot_key(before)[:5] != (
                _lifecycle_file_snapshot_key(observed)[:5]
            ):
                raise OSError("captured descriptor differs from its pathname")
            data = stream.read(snapshot.length + 1)
            middle = os.fstat(stream.fileno())
            stream.seek(0)
            verified = stream.read(snapshot.length + 1)
            after = os.fstat(stream.fileno())
        current = snapshot.path.lstat()
    except OSError as exc:
        raise LifecycleError(
            failure_id, "captured file path is no longer available"
        ) from exc
    finally:
        if descriptor >= 0:
            os.close(descriptor)
    before_key = _lifecycle_file_snapshot_key(before)
    if (
        _lifecycle_path_has_reparse(snapshot.path)
        or not stat.S_ISREG(observed.st_mode)
        or not stat.S_ISREG(before.st_mode)
        or stat.S_ISLNK(observed.st_mode)
        or stat.S_ISLNK(current.st_mode)
        or (
            snapshot.require_single_link
            and any(
                info.st_nlink != 1
                for info in (observed, before, middle, after, current)
            )
        )
        or bool(
            getattr(observed, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        )
        or bool(
            getattr(current, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        )
        or bool(
            getattr(before, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        )
        or before_key != _lifecycle_file_snapshot_key(middle)
        or before_key != _lifecycle_file_snapshot_key(after)
        or _lifecycle_file_snapshot_key(observed)
        != _lifecycle_file_snapshot_key(current)
        or _lifecycle_file_identity(before) != snapshot.identity
        or _lifecycle_file_identity(current) != snapshot.identity
        or before.st_size != snapshot.length
        or data != verified
        or data != snapshot.data
    ):
        raise LifecycleError(
            failure_id, "captured file path identity or content changed"
        )


def _capture_directory_snapshot(path: Path, *, failure_id: str, inverse=None) -> CapturedDirectorySnapshotV1:
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        transaction.verify(inverse=inverse)
    snapshot = _capture_owned_directory_snapshot(path, failure_id=failure_id)
    if transaction is not None:
        transaction.verify(inverse=inverse)
    return snapshot


def _capture_owned_directory_snapshot(path: Path, *, failure_id: str, creation_owner=None) -> CapturedDirectorySnapshotV1:
    """Capture complete member/native identities using existing parent handles.

    This bypasses constructive __enter__. Reader acquisitions are closed here;
    explicitly qualified creator capabilities retain their creator's custody.
    """
    path = _lifecycle_unresolved_absolute(path)
    target = LifecycleWriteTarget(path / ".directory-acquisition", failure_id=failure_id)
    primary = None
    borrowed = []
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    ambient_transaction = transaction
    if creation_owner is not None:
        operation = creation_owner._operation_owner
        explicit = operation if isinstance(operation, LifecycleTransaction) else getattr(operation, "transaction", None)
        if isinstance(explicit, LifecycleTransaction):
            if transaction is not None and transaction is not explicit:
                raise LifecycleError(failure_id, "observation operation context differs")
            transaction = explicit
    current_pair = ((transaction._binding_evidence, transaction._retained_observations,
                     transaction._operation_owner) if transaction is not None else None)
    current_observations = (MappingProxyType(dict(transaction._retained_observations))
                            if transaction is not None else None)
    if creation_owner is not None:
        if not isinstance(creation_owner, LifecycleWriteTarget):
            raise LifecycleError(failure_id, "creation observation owner differs")
        creation_owner._assert_creation_settlement()
        movement = transaction._active_relocation if transaction is not None else None
        exclusion = movement if movement is not None else creation_owner
        if exclusion._creation_observation_active:
            raise LifecycleError(failure_id, "operation already has an active observation")
        object.__setattr__(exclusion, "_creation_observation_active", True)
        if movement is not None:
            object.__setattr__(movement, "observation_owner", creation_owner)
        operation_owner = creation_owner._operation_owner

    def verify_borrowed():
        if creation_owner is None:
            return
        if (_CURRENT_LIFECYCLE_TRANSACTION.get() is not ambient_transaction
                or creation_owner._operation_owner is not operation_owner
                or not exclusion._creation_observation_active
                or (creation_owner._creation_process is not None and
                    (creation_owner._creation_process != os.getpid()
                     or creation_owner._creation_thread is not threading.current_thread()))
                or (transaction is not None and
                    (transaction._binding_evidence is not current_pair[0]
                     or transaction._retained_observations is not current_pair[1]
                     or transaction._retained_observations != current_observations
                     or transaction._operation_owner is not current_pair[2]))):
            raise LifecycleError(failure_id, "creation observation current operation changed")
        for record, locator, identity in borrowed:
            if (creation_owner._borrow_directory(locator) is not record
                    or creation_owner._identity(record.handle) != identity):
                raise LifecycleError(failure_id, "borrowed native directory changed during observation")

    try:
        chain = target._acquire_existing_parents(creation_owner=creation_owner, borrowed=borrowed)
        handle = target._parent
        before = path.lstat()

        def inventory():
            with os.scandir(path) as stream:
                entries = sorted(stream, key=lambda entry: entry.name.encode("utf-8"))
            rows = []
            for entry in entries:
                # Windows DirEntry's cached stat has zero native file identity;
                # bind the path lstat to the actual parent-relative handle.
                metadata = (path / entry.name).lstat()
                reparse = stat.S_ISLNK(metadata.st_mode) or bool(getattr(metadata, "st_file_attributes", 0)
                          & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0))
                # A reparse member is an observed fact, never a traversable
                # input. Selected owners retain their normal rejection rules.
                if not reparse and (stat.S_ISREG(metadata.st_mode) or stat.S_ISDIR(metadata.st_mode)):
                    record = (creation_owner._borrow_directory(path / entry.name, handle)
                              if creation_owner is not None and stat.S_ISDIR(metadata.st_mode) else None)
                    if record is not None:
                        member = record.handle
                        borrowed.append((record, path / entry.name, creation_owner._identity(member)))
                    elif os.name == "nt":
                        member = target._windows_child(handle, entry.name,
                            directory=stat.S_ISDIR(metadata.st_mode), create=False)
                    else:
                        flags = os.O_RDONLY | os.O_NOFOLLOW | getattr(os, "O_NONBLOCK", 0)
                        if stat.S_ISDIR(metadata.st_mode):
                            flags |= os.O_DIRECTORY
                        member = os.open(entry.name, flags, dir_fd=handle)
                    member_primary = None
                    try:
                        if target._identity(member) != _lifecycle_file_identity(metadata):
                            raise LifecycleError(failure_id, "directory member differs from its captured parent handle")
                    except BaseException as exc:
                        member_primary = exc
                        raise
                    finally:
                        if record is None:
                            target._release_handle(member, member_primary)
                rows.append((entry.name, metadata))
            target._verify_owned()
            verify_borrowed()
            return tuple(rows)

        members, repeated = inventory(), inventory()
        after = path.lstat()
        if (_lifecycle_file_snapshot_key(before) != _lifecycle_file_snapshot_key(after)
                or tuple((name, _lifecycle_file_snapshot_key(meta)) for name, meta in members)
                != tuple((name, _lifecycle_file_snapshot_key(meta)) for name, meta in repeated)):
            raise LifecycleError(failure_id, "complete directory membership changed during capture")
        verify_borrowed()
        snapshot = CapturedDirectorySnapshotV1(path, chain, before, members)
        return replace(snapshot, capture_binding=_directory_capture_binding(snapshot))
    except OSError as exc:
        primary = LifecycleError(failure_id, "native directory acquisition failed")
        raise primary from exc
    except BaseException as exc:
        primary = exc
        raise
    finally:
        try:
            target.__exit__(type(primary) if primary is not None else None, primary,
                            primary.__traceback__ if primary is not None else None)
            if primary is None:
                verify_borrowed()
        finally:
            borrowed.clear()
            handle = member = record = None
            if creation_owner is not None:
                object.__setattr__(exclusion, "_creation_observation_active", False)
                if movement is not None:
                    object.__setattr__(movement, "observation_owner", None)


def _verify_captured_directory(snapshot: CapturedDirectorySnapshotV1, failure_id: str, *, inverse=None):
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is not None:
        transaction.verify(inverse=inverse)
    _verify_owned_directory_snapshot(snapshot, failure_id)
    if transaction is not None:
        transaction.verify(inverse=inverse)


def _verify_owned_directory_snapshot(snapshot: CapturedDirectorySnapshotV1, failure_id: str, *, creation_owner=None):
    if snapshot.capture_binding != _directory_capture_binding(snapshot):
        raise LifecycleError(failure_id, "directory observation was not minted intact by the native owner")
    _verify_captured_parent_chain(snapshot.parent_chain, failure_id)
    current = _capture_owned_directory_snapshot(snapshot.path, failure_id=failure_id,
        **({"creation_owner": creation_owner} if creation_owner is not None else {}))
    if (_lifecycle_file_snapshot_key(current.metadata) != _lifecycle_file_snapshot_key(snapshot.metadata)
            or tuple((name, _lifecycle_file_snapshot_key(meta)) for name, meta in current.members)
            != tuple((name, _lifecycle_file_snapshot_key(meta)) for name, meta in snapshot.members)):
        raise LifecycleError(failure_id, "captured native directory identity/membership changed")


def _parse_migration_inventory_bytes(
    root: Path,
    snapshot: bytes,
    *,
    strict_shape: bool = False,
) -> dict:
    try:
        inventory = json.loads(
            snapshot.decode("utf-8"),
            object_pairs_hook=_reject_duplicate_json_pairs,
        )
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "migration inventory is not strict UTF-8 JSON",
        ) from exc
    work_items = _work_items_root(root)
    if (
        not isinstance(inventory, dict)
        or (
            strict_shape
            and set(inventory)
            != {
                "digestAlgorithms",
                "owner",
                "rows",
                "schemaVersion",
                "workItemsRoot",
            }
        )
        or inventory.get("schemaVersion") != MIGRATION_SCHEMA_VERSION
        or inventory.get("owner") != MIGRATION_OWNER
        or inventory.get("workItemsRoot") != str(work_items.resolve())
        or inventory.get("digestAlgorithms") != MIGRATION_DIGEST_ALGORITHMS
        or not isinstance(inventory.get("rows"), list)
    ):
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "migration inventory schema or target binding differs",
        )
    allowed_row_fields = {
        "admission",
        "category",
        "digestAlgorithm",
        "incomingLinks",
        "inputSha256",
        "reference",
        "source",
        "target",
        "terminalInstant",
    }
    allowed_admission_fields = {
        "negativeFixture",
        "reader",
        "result",
        "utcOwner",
        "validator",
    }
    if strict_shape:
        for row in inventory["rows"]:
            if (
                not isinstance(row, dict)
                or set(row) != allowed_row_fields
                or not isinstance(row.get("admission"), dict)
                or set(row["admission"]) != allowed_admission_fields
                or not isinstance(row.get("incomingLinks"), dict)
                or not set(row["incomingLinks"]).issubset(
                    {"physicalRelocation", "references", "result"}
                )
            ):
                raise LifecycleError(
                    "WI-CATEGORY-MIGRATION-INVENTORY",
                    "migration inventory row shape differs",
                )
    return inventory


def _load_migration_inventory(root: Path, inventory_path: Path) -> dict:
    snapshot = _capture_file_snapshot(
        inventory_path,
        failure_id="WI-CATEGORY-MIGRATION-INVENTORY",
    )
    return _parse_migration_inventory_bytes(root, snapshot.data)


def _terminalization_fail(message: str) -> LifecycleError:
    return LifecycleError(V1_TERMINALIZATION_FAILURE, message)


def _terminalization_has_reparse(path: Path) -> bool:
    try:
        attributes = getattr(path.lstat(), "st_file_attributes", 0)
    except OSError as exc:
        raise _terminalization_fail(f"cannot inspect terminalization path: {path}") from exc
    return path.is_symlink() or bool(
        attributes & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
    )


def _terminalization_bound_path(
    work_items: Path,
    relative: str,
    *,
    label: str,
) -> Path:
    if not isinstance(relative, str) or not relative:
        raise _terminalization_fail(f"{label} path is missing")
    relative_path = Path(relative)
    if relative_path.is_absolute() or ".." in relative_path.parts:
        raise _terminalization_fail(f"{label} path escapes work-items: {relative!r}")
    root = work_items.resolve()
    cursor = work_items
    if _terminalization_has_reparse(cursor):
        raise _terminalization_fail(f"work-items root is a link or reparse point: {cursor}")
    for part in relative_path.parts:
        cursor = cursor / part
        if cursor.exists() or cursor.is_symlink():
            if _terminalization_has_reparse(cursor):
                raise _terminalization_fail(
                    f"{label} path contains a link or reparse point: {cursor}"
                )
    resolved = cursor.resolve()
    if resolved != root and root not in resolved.parents:
        raise _terminalization_fail(f"{label} path escapes work-items: {relative!r}")
    return resolved


def _bound_repository_scratch_path(
    root: Path,
    path: str | Path,
    *,
    label: str,
    allow_absolute: bool,
) -> Path:
    candidate = Path(path) if isinstance(path, (str, Path)) else Path()
    if not candidate.parts or ".." in candidate.parts:
        raise _terminalization_fail(f"{label} path is unsafe")
    repo_root = _work_items_root(root).parent.resolve()
    if candidate.is_absolute():
        if not allow_absolute:
            raise _terminalization_fail(f"{label} path must be repository-relative")
        try:
            relative = candidate.relative_to(repo_root)
        except ValueError as exc:
            raise _terminalization_fail(f"{label} path escapes the repository") from exc
    else:
        relative = candidate
    if len(relative.parts) < 2 or relative.parts[0] != ".scratch":
        raise _terminalization_fail(f"{label} must be a file under repository .scratch")
    if _terminalization_has_reparse(repo_root):
        raise _terminalization_fail(f"repository root is a link or reparse point: {repo_root}")
    cursor = repo_root
    for part in relative.parts:
        cursor = cursor / part
        if (cursor.exists() or cursor.is_symlink()) and _terminalization_has_reparse(cursor):
            raise _terminalization_fail(
                f"{label} path contains a link or reparse point: {cursor}"
            )
    resolved = cursor.resolve()
    scratch = (repo_root / ".scratch").resolve()
    if resolved == scratch or scratch not in resolved.parents:
        raise _terminalization_fail(f"{label} escapes repository .scratch")
    return resolved


def _bound_physical_receipt(root: Path, relative: str) -> Path:
    return _bound_repository_scratch_path(
        root,
        relative,
        label="physical-relocation receipt",
        allow_absolute=False,
    )


def _physical_relocation_admission(
    root: Path,
    reference: str,
    incoming: object,
    *,
    receipt_path: Path | None = None,
) -> tuple[list[dict], dict | None]:
    if not isinstance(incoming, dict) or not isinstance(incoming.get("references"), list):
        raise _terminalization_fail(f"incoming-link inventory is invalid for {reference}")
    links = incoming["references"]
    physical: list[dict] = []
    logical: list[dict] = []
    for link in links:
        if (
            not isinstance(link, dict)
            or not isinstance(link.get("consumer"), str)
            or not isinstance(link.get("value"), str)
        ):
            raise _terminalization_fail(f"incoming-link row is invalid for {reference}")
        if link.get("kind") == "physical":
            physical.append(link)
        elif link.get("kind") == "logical" and link["value"] == reference:
            logical.append(link)
        else:
            raise _terminalization_fail(f"incoming-link kind or identity differs for {reference}")
    if not physical:
        expected_result = "logical-only" if logical else "clear"
        if incoming.get("result") != expected_result or "physicalRelocation" in incoming:
            raise _terminalization_fail(
                f"incoming-link result differs from its rows for {reference}"
            )
        return links, None
    if len(physical) != 1 or logical or incoming.get("result") != "physical-relocation":
        raise _terminalization_fail(
            f"physical relocation requires one exact incoming link for {reference}"
        )
    admission = incoming.get("physicalRelocation")
    required = {
        "source",
        "label",
        "href",
        "expectedIdentity",
        "sourceSha256",
        "targetSha256",
        "receipt",
    }
    if not isinstance(admission, dict) or set(admission) != required:
        raise _terminalization_fail(
            f"physical-relocation admission shape differs for {reference}"
        )
    source_relative = admission.get("source")
    source_parts = Path(source_relative).parts if isinstance(source_relative, str) else ()
    if (
        source_relative != physical[0]["consumer"]
        or admission.get("href") != physical[0]["value"]
        or admission.get("expectedIdentity") != reference
        or not isinstance(admission.get("label"), str)
        or not admission["label"]
        or not re.fullmatch(r"[0-9a-f]{64}", str(admission.get("sourceSha256", "")))
        or not re.fullmatch(r"[0-9a-f]{64}", str(admission.get("targetSha256", "")))
        or len(source_parts) < 4
        or source_parts[-3] != "archive"
        or not re.fullmatch(r"\d{4}-\d{2}", source_parts[-2])
    ):
        raise _terminalization_fail(
            f"physical-relocation tuple differs for {reference}"
        )
    bound_receipt = _bound_physical_receipt(root, admission["receipt"])
    if receipt_path is not None and bound_receipt != receipt_path.resolve():
        raise _terminalization_fail(
            f"physical-relocation receipt binding differs for {reference}"
        )
    return links, admission


def _plan_v1_link_relocations(
    root: Path,
    planned: list[dict],
    terminal_at: str,
    receipt_path: Path,
) -> tuple[list[dict], list[dict]]:
    work_items = _work_items_root(root)
    admissions: list[tuple[dict, dict]] = []
    for item in planned:
        _links, admission = _physical_relocation_admission(
            root,
            item["reference"],
            item["incomingLinks"],
            receipt_path=receipt_path,
        )
        if admission is not None:
            admissions.append((item, admission))
    if len(admissions) > 1:
        raise _terminalization_fail("only one exact physical relocation is admitted")
    consumer_plans: list[dict] = []
    receipt_links: list[dict] = []
    for item, admission in admissions:
        consumer_relative = admission["source"]
        consumer = _terminalization_bound_path(
            work_items, consumer_relative, label="physical-link consumer"
        )
        if consumer.suffix.casefold() != ".md" or not consumer.is_file():
            raise _terminalization_fail(
                f"physical-link consumer is not a Markdown file: {consumer_relative}"
            )
        if consumer == item["source"]:
            raise _terminalization_fail(
                f"physical-link consumer is also moving: {consumer_relative}"
            )
        before = consumer.read_bytes()
        before_sha256 = hashlib.sha256(before).hexdigest()
        if admission["sourceSha256"] != before_sha256:
            raise _terminalization_fail(
                f"physical-link consumer hash changed: {consumer_relative}"
            )
        if admission["targetSha256"] != item["beforeSha256"]:
            raise _terminalization_fail(
                f"physical-link target hash changed: {item['reference']}"
            )
        try:
            text = before.decode("utf-8")
        except UnicodeError as exc:
            raise _terminalization_fail(
                f"physical-link consumer is not UTF-8 Markdown: {consumer_relative}"
            ) from exc

        matches = [
            link
            for link in _markdown_local_links(text)
            if link.label == admission["label"] and link.href == admission["href"]
        ]
        if len(matches) != 1:
            raise _terminalization_fail(
                f"physical Markdown tuple is missing or duplicated: {consumer_relative}"
            )
        href_parts = _local_markdown_href_parts(admission["href"])
        if href_parts is None or not _markdown_href_resolves(
            consumer.parent, admission["href"], item["source"]
        ):
            raise _terminalization_fail(
                f"physical Markdown href resolves outside expected identity: {consumer_relative}"
            )
        new_path = Path(os.path.relpath(item["target"], consumer.parent)).as_posix()
        new_href = new_path + href_parts[1]
        if not _markdown_href_resolves(consumer.parent, new_href, item["target"]):
            raise _terminalization_fail(
                f"relocated href does not resolve to target: {consumer_relative}"
            )
        after_text = (
            text[:matches[0].href_start]
            + new_href
            + text[matches[0].href_end:]
        )
        after = after_text.encode("utf-8")
        after_sha256 = hashlib.sha256(after).hexdigest()
        consumer_plans.append(
            {
                "consumer": consumer,
                "consumerRelative": consumer_relative,
                "before": before,
                "beforeSha256": before_sha256,
                "after": after,
                "afterSha256": after_sha256,
            }
        )
        receipt_links.append(
            {
                "source": consumer_relative,
                "label": admission["label"],
                "oldHref": admission["href"],
                "newHref": new_href,
                "expectedIdentity": item["reference"],
                "finalTarget": item["targetRelative"],
                "sourceBeforeSha256": before_sha256,
                "sourceAfterSha256": None,
                "targetBeforeSha256": item["afterSha256"],
                "targetAfterSha256": None,
                "terminalAt": terminal_at,
            }
        )
    return consumer_plans, receipt_links


def _expected_physical_relocation_receipt(
    root: Path,
    reference: str,
    admission: dict,
    source: Path,
    target: Path,
    target_before_sha256: str,
    terminal_at: str,
    *,
    settled: bool,
) -> dict:
    """Derive the one receipt relation allowed by an admitted physical link."""
    work_items = _work_items_root(root)
    consumer_relative = admission["source"]
    consumer = _terminalization_bound_path(
        work_items, consumer_relative, label="physical-link consumer"
    )
    if not consumer.is_file():
        raise _terminalization_fail(
            f"physical-link consumer is missing: {consumer_relative}"
        )
    href_parts = _local_markdown_href_parts(admission["href"])
    if href_parts is None:
        raise _terminalization_fail(
            f"physical Markdown href is not local: {consumer_relative}"
        )
    expected_href = Path(os.path.relpath(target, consumer.parent)).as_posix() + href_parts[1]
    current_href = expected_href if settled else admission["href"]
    resolved_target = target if settled else source
    try:
        current = consumer.read_bytes()
        text = current.decode("utf-8")
    except (OSError, UnicodeError) as exc:
        raise _terminalization_fail(
            f"physical-link consumer is not UTF-8 Markdown: {consumer_relative}"
        ) from exc
    matches = [
        link
        for link in _markdown_local_links(text)
        if link.label == admission["label"]
        and link.href == current_href
        and _markdown_href_resolves(consumer.parent, link.href, resolved_target)
    ]
    if len(matches) != 1:
        raise _terminalization_fail(
            f"physical Markdown tuple is missing or duplicated: {consumer_relative}"
        )
    if settled:
        link = matches[0]
        source_before = hashlib.sha256(
            (
                text[:link.href_start]
                + admission["href"]
                + text[link.href_end:]
            ).encode("utf-8")
        ).hexdigest()
        source_after: str | None = hashlib.sha256(current).hexdigest()
        target_after: str | None = hashlib.sha256(target.read_bytes()).hexdigest()
    else:
        source_before = hashlib.sha256(current).hexdigest()
        source_after = None
        target_after = None
    payload = target if settled else source
    if (
        source_before != admission["sourceSha256"]
        or hashlib.sha256(payload.read_bytes()).hexdigest() != target_before_sha256
        or (settled and target_after != target_before_sha256)
    ):
        raise _terminalization_fail(
            f"physical-relocation evidence differs for {reference}"
        )
    return {
        "source": consumer_relative,
        "label": admission["label"],
        "oldHref": admission["href"],
        "newHref": expected_href,
        "expectedIdentity": reference,
        "finalTarget": target.relative_to(work_items).as_posix(),
        "sourceBeforeSha256": source_before,
        "sourceAfterSha256": source_after,
        "targetBeforeSha256": target_before_sha256,
        "targetAfterSha256": target_after,
        "terminalAt": terminal_at,
    }


def _terminalization_receipt_path(root: Path, path: Path) -> Path:
    return _bound_repository_scratch_path(
        root,
        path,
        label="terminalization receipt",
        allow_absolute=True,
    )


def _terminalization_replay(
    root: Path,
    inventory: dict,
    inventory_sha256: str,
    terminal_at: str,
    authorization_marker: str,
    receipt_path: Path,
) -> tuple[int, bool] | None:
    if not receipt_path.exists():
        return None
    if not receipt_path.is_file():
        raise _terminalization_fail(
            f"terminalization receipt is not a file: {receipt_path}"
        )
    try:
        receipt = json.loads(receipt_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise _terminalization_fail(
            f"existing terminalization receipt is invalid: {receipt_path}"
        ) from exc
    work_items = _work_items_root(root)
    expected_header = {
        "schemaVersion": V1_TERMINALIZATION_SCHEMA_VERSION,
        "owner": V1_TERMINALIZATION_OWNER,
        "workItemsRoot": str(work_items.resolve()),
        "inventorySha256": inventory_sha256,
        "terminalAt": terminal_at,
        "authorizationMarker": authorization_marker,
        "rowCount": len(inventory["rows"]),
        "linkCount": sum(
            1
            for inventory_row in inventory["rows"]
            if isinstance(inventory_row, dict)
            for link in (inventory_row.get("incomingLinks") or {}).get("references", [])
            if isinstance(link, dict) and link.get("kind") == "physical"
        ),
    }
    if not isinstance(receipt, dict) or any(
        receipt.get(key) != value for key, value in expected_header.items()
    ):
        raise _terminalization_fail(
            "existing terminalization receipt does not match this exact operation"
        )
    receipt_rows = receipt.get("rows")
    if not isinstance(receipt_rows, list) or len(receipt_rows) != len(
        inventory["rows"]
    ):
        raise _terminalization_fail(
            "existing terminalization receipt row set differs"
        )
    inventory_references = sorted(
        row.get("reference") for row in inventory["rows"] if isinstance(row, dict)
    )
    receipt_references = sorted(
        row.get("reference") for row in receipt_rows if isinstance(row, dict)
    )
    if inventory_references != receipt_references:
        raise _terminalization_fail(
            "existing terminalization receipt references differ"
        )
    inventory_by_reference = {
        row.get("reference"): row for row in inventory["rows"] if isinstance(row, dict)
    }
    receipt_pairs: set[tuple[str, str]] = set()
    for row in receipt_rows:
        if not isinstance(row, dict):
            raise _terminalization_fail(
                "existing terminalization receipt contains an invalid row"
            )
        inventory_row = inventory_by_reference.get(row.get("reference"))
        if not isinstance(inventory_row, dict):
            raise _terminalization_fail(
                f"terminalization receipt has no inventory row: {row.get('reference')}"
            )
        source = _terminalization_bound_path(
            work_items, row.get("source"), label="receipt source"
        )
        target = _terminalization_bound_path(
            work_items, row.get("target"), label="receipt target"
        )
        category, slug = _canonical_category(row["reference"])
        expected_target = (
            work_items
            / category.current_root
            / "archive"
            / archive_month(terminal_at)
            / f"{slug}.md"
        ).resolve()
        source_exists = source.is_file()
        target_exists = target.is_file()
        payload = source if source_exists else target
        if (
            row.get("source") != inventory_row.get("source")
            or row.get("beforeSha256") != inventory_row.get("inputSha256")
            or source_exists == target_exists
            or target != expected_target
            or row.get("afterSha256")
            != hashlib.sha256(payload.read_bytes()).hexdigest()
            or _category_locations(root, category, slug) != [payload]
        ):
            raise _terminalization_fail(
                f"terminalized payload differs from receipt: {row.get('reference')}"
            )
        receipt_pairs.add((row["source"], row["target"]))
    receipt_link_rows = [
        (receipt_row, receipt_row["physicalRelocation"])
        for receipt_row in receipt_rows
        if isinstance(receipt_row, dict)
        and isinstance(receipt_row.get("physicalRelocation"), dict)
    ]
    if len(receipt_link_rows) != expected_header["linkCount"]:
        raise _terminalization_fail("existing terminalization receipt link set differs")
    seen_link_rows: set[tuple[str, str, str, str]] = set()
    for owner_row, link in receipt_link_rows:
        if not isinstance(link, dict) or link.get("terminalAt") != terminal_at:
            raise _terminalization_fail("existing terminalization receipt link row is invalid")
        consumer = _terminalization_bound_path(
            work_items, link.get("source"), label="receipt link consumer"
        )
        new_target = _terminalization_bound_path(
            work_items, link.get("finalTarget"), label="receipt new target"
        )
        before_sha256 = link.get("sourceBeforeSha256")
        after_sha256 = link.get("sourceAfterSha256")
        target_before_sha256 = link.get("targetBeforeSha256")
        target_after_sha256 = link.get("targetAfterSha256")
        old_href = link.get("oldHref")
        new_href = link.get("newHref")
        label = link.get("label")
        identity = link.get("expectedIdentity")
        old_target_relative = next(
            (
                old
                for old, new in receipt_pairs
                if new == link.get("finalTarget")
            ),
            None,
        )
        old_target = (
            _terminalization_bound_path(
                work_items, old_target_relative, label="receipt old target"
            )
            if old_target_relative is not None
            else None
        )
        pending = old_target is not None and old_target.is_file() and not new_target.exists()
        settled = old_target is not None and not old_target.exists() and new_target.is_file()
        if (
            old_target is None
            or not isinstance(before_sha256, str)
            or not re.fullmatch(r"[0-9a-f]{64}", before_sha256)
            or not isinstance(target_before_sha256, str)
            or not re.fullmatch(r"[0-9a-f]{64}", target_before_sha256)
            or (pending and (after_sha256 is not None or target_after_sha256 is not None))
            or (
                settled
                and (
                    not isinstance(after_sha256, str)
                    or not re.fullmatch(r"[0-9a-f]{64}", after_sha256)
                    or not isinstance(target_after_sha256, str)
                    or not re.fullmatch(r"[0-9a-f]{64}", target_after_sha256)
                    or hashlib.sha256(new_target.read_bytes()).hexdigest()
                    != target_after_sha256
                )
            )
            or not isinstance(old_href, str)
            or not isinstance(new_href, str)
            or not isinstance(label, str)
            or not isinstance(identity, str)
            or not (pending or settled)
            or not consumer.is_file()
            or hashlib.sha256(consumer.read_bytes()).hexdigest()
            != (before_sha256 if pending else after_sha256)
        ):
            raise _terminalization_fail(
                f"terminalized link differs from receipt: {link.get('source')}"
            )
        key = (link["source"], old_href, new_href, link["finalTarget"])
        if key in seen_link_rows:
            raise _terminalization_fail("terminalization receipt repeats a physical link")
        seen_link_rows.add(key)
        try:
            text = consumer.read_text(encoding="utf-8")
        except (OSError, UnicodeError) as exc:
            raise _terminalization_fail(
                f"terminalized link consumer is unreadable: {link.get('source')}"
            ) from exc
        expected_href = old_href if pending else new_href
        expected_target = old_target if pending else new_target
        resolved_matches = [
            link
            for link in _markdown_local_links(text)
            if link.label == label
            and link.href == expected_href
            and _markdown_href_resolves(consumer.parent, link.href, expected_target)
        ]
        if len(resolved_matches) != 1:
            raise _terminalization_fail(
                f"terminalized Markdown href is missing: {link.get('source')}"
            )
        owner_reference = owner_row["reference"]
        owner_inventory_row = inventory_by_reference[owner_reference]
        _links, admission = _physical_relocation_admission(
            root,
            owner_reference,
            owner_inventory_row.get("incomingLinks"),
            receipt_path=receipt_path,
        )
        if admission is None or link != _expected_physical_relocation_receipt(
            root,
            owner_reference,
            admission,
            old_target,
            new_target,
            owner_row["afterSha256"],
            terminal_at,
            settled=settled,
        ):
            raise _terminalization_fail(
                f"terminalized physical-relocation receipt differs: {link.get('source')}"
            )
    return len(receipt_rows), True


def _preflight_v1_terminalization_rows(
    root: Path,
    inventory: dict,
    terminal_at: str,
    receipt_path: Path,
) -> tuple[list[dict], list[dict], list[dict]]:
    _strict_utc(terminal_at)
    work_items = _work_items_root(root)
    planned: list[dict] = []
    seen_sources: set[Path] = set()
    seen_targets: set[Path] = set()
    for row in inventory["rows"]:
        if not isinstance(row, dict):
            raise _terminalization_fail("terminalization inventory row is not an object")
        category_name = row.get("category")
        try:
            category, slug = _canonical_category(row.get("reference", ""))
        except LifecycleError as exc:
            raise _terminalization_fail(str(exc)) from exc
        if category.current_kind != "flat":
            raise _terminalization_fail(
                f"unsupported V1 terminalization category: {category_name!r}"
            )
        admission_row = _admission_for(category.name)
        if category.name != category_name:
            raise _terminalization_fail(
                f"category tuple differs for {row.get('reference')}"
            )
        admission = row.get("admission")
        if (
            not isinstance(admission, dict)
            or admission.get("result") != "denied"
            or admission.get("failureId") != V1_TERMINALIZATION_FAILURE
        ):
            raise _terminalization_fail(
                f"row is not denied solely for missing terminal evidence: "
                f"{row.get('reference')}"
            )
        incoming = row.get("incomingLinks")
        _incoming_rows, physical_relocation = _physical_relocation_admission(
            root,
            row["reference"],
            incoming,
            receipt_path=receipt_path,
        )
        if row.get("target") is not None or row.get("terminalInstant") is not None:
            raise _terminalization_fail(
                f"denied row already has a target or terminal instant: "
                f"{row.get('reference')}"
            )
        source = _terminalization_bound_path(
            work_items, row.get("source"), label="terminalization source"
        )
        expected_source = (
            work_items / category.current_root / f"{slug}.md"
        ).resolve()
        if source != expected_source or source in seen_sources:
            raise _terminalization_fail(
                f"source binding is ambiguous for {row.get('reference')}"
            )
        seen_sources.add(source)
        try:
            locations = _category_locations(root, category, slug)
        except OSError as exc:
            raise _terminalization_fail(
                f"cannot resolve locations for {row.get('reference')}"
            ) from exc
        if locations != [source] or not source.is_file():
            raise _terminalization_fail(
                f"current location is ambiguous for {row.get('reference')}"
            )
        target_relative = (
            Path(category.current_root)
            / "archive"
            / archive_month(terminal_at)
            / source.name
        ).as_posix()
        target = _terminalization_bound_path(
            work_items, target_relative, label="terminalization target"
        )
        if target in seen_targets or target.exists():
            raise _terminalization_fail(
                f"terminalization target is ambiguous for {row.get('reference')}"
            )
        seen_targets.add(target)
        if row.get("digestAlgorithm") != MIGRATION_DIGEST_ALGORITHMS["file"]:
            raise _terminalization_fail(
                f"unsupported digest algorithm for {row.get('reference')}"
            )
        before = source.read_bytes()
        before_sha256 = hashlib.sha256(before).hexdigest()
        if row.get("inputSha256") != before_sha256:
            raise _terminalization_fail(
                f"input payload hash changed for {row.get('reference')}"
            )
        try:
            text = before.decode("utf-8")
        except UnicodeError as exc:
            raise _terminalization_fail(
                f"terminal record is not UTF-8: {row.get('reference')}"
            ) from exc
        fields = _parse_fields(text)
        status = fields.get("status", "")
        if status not in category.terminal_statuses:
            raise _terminalization_fail(
                f"current status is not terminal for {row.get('reference')}: "
                f"{status!r}"
            )
        detail_field = admission_row.detail_field
        conflicting = tuple(
            dict.fromkeys(
                _terminalization_authoritative_field_occurrences(
                    text, admission_row.utc_field
                )
            )
        )
        if conflicting:
            raise _terminalization_fail(
                f"authoritative terminal field already exists for "
                f"{row.get('reference')}: {', '.join(conflicting)}"
            )
        current_links = _incoming_link_result(
            root,
            {source},
            row["reference"],
        )
        expected_current_links = (
            {
                "result": "unmapped",
                "references": incoming["references"],
            }
            if physical_relocation is not None
            else incoming
        )
        if current_links != expected_current_links:
            raise _terminalization_fail(
                f"incoming-link inventory changed for {row.get('reference')}"
            )
        separator = b"\n" if before.endswith(b"\n") else b"\n\n"
        proof = (
            "Historical terminal time is unknown; preserved pre-V1 input "
            f"SHA-256 `{before_sha256}`; original terminal status `{status}`; "
            "explicit operator-authorized V1 migration."
        )
        appended_lines = [f"{admission_row.utc_field}: {terminal_at}"]
        if not fields.get(detail_field.casefold()):
            appended_lines.append(
                f"{detail_field}: Pre-V1 terminal status `{status}` is preserved "
                "during operator-authorized V1 physical migration."
            )
        if not fields.get(admission_row.evidence_field.casefold()):
            appended_lines.append(f"{admission_row.evidence_field}: {proof}")
        appended_lines.append(f"V1-Migration-Evidence: {proof}")
        appended = ("\n".join(appended_lines) + "\n").encode("utf-8")
        after = before + separator + appended
        planned.append(
            {
                "reference": row["reference"],
                "sourceRelative": row["source"],
                "source": source,
                "targetRelative": target_relative,
                "target": target,
                "category": category,
                "slug": slug,
                "incomingLinks": incoming,
                "status": status,
                "before": before,
                "beforeSha256": before_sha256,
                "after": after,
                "afterSha256": hashlib.sha256(after).hexdigest(),
            }
        )
    planned = sorted(planned, key=lambda item: item["reference"])
    source_set = {item["source"] for item in planned}
    target_set = {item["target"] for item in planned}
    if source_set & target_set:
        raise _terminalization_fail("terminalization source and target sets overlap")
    consumers, receipt_links = _plan_v1_link_relocations(
        root, planned, terminal_at, receipt_path
    )
    return planned, consumers, receipt_links


def terminalize_v1_inventory(
    root: Path,
    inventory_path: Path,
    *,
    terminal_at: str,
    authorization_marker: str,
    receipt_path: Path,
    inject_failure_after: int | None = None,
) -> tuple[int, bool]:
    """Add V1 evidence and preserve exact relocation admission; never move records."""
    if authorization_marker != V1_TERMINALIZATION_AUTHORIZATION:
        raise _terminalization_fail(
            "explicit operator-authorized V1 terminalization marker is required"
        )
    _strict_utc(terminal_at)
    receipt = _terminalization_receipt_path(root, receipt_path)
    try:
        inventory_bytes = inventory_path.read_bytes()
        inventory = _load_migration_inventory(root, inventory_path)
    except LifecycleError as exc:
        raise _terminalization_fail(str(exc)) from exc
    except OSError as exc:
        raise _terminalization_fail(
            f"cannot read terminalization inventory: {inventory_path}"
        ) from exc
    inventory_sha256 = hashlib.sha256(inventory_bytes).hexdigest()
    replay = _terminalization_replay(
        root,
        inventory,
        inventory_sha256,
        terminal_at,
        authorization_marker,
        receipt,
    )
    if replay is not None:
        return replay
    planned, consumers, receipt_links = _preflight_v1_terminalization_rows(
        root, inventory, terminal_at, receipt
    )
    links_by_identity = {
        link["expectedIdentity"]: link for link in receipt_links
    }
    receipt_payload = {
        "schemaVersion": V1_TERMINALIZATION_SCHEMA_VERSION,
        "owner": V1_TERMINALIZATION_OWNER,
        "workItemsRoot": str(_work_items_root(root).resolve()),
        "inventorySha256": inventory_sha256,
        "terminalAt": terminal_at,
        "authorizationMarker": authorization_marker,
        "rowCount": len(planned),
        "linkCount": len(receipt_links),
        "rows": [
            {
                "reference": item["reference"],
                "source": item["sourceRelative"],
                "target": item["targetRelative"],
                "terminalAt": terminal_at,
                "originalStatus": item["status"],
                "beforeSha256": item["beforeSha256"],
                "afterSha256": item["afterSha256"],
                **(
                    {"physicalRelocation": links_by_identity[item["reference"]]}
                    if item["reference"] in links_by_identity
                    else {}
                ),
            }
            for item in planned
        ],
    }
    receipt_bytes = (
        json.dumps(receipt_payload, indent=2, sort_keys=True) + "\n"
    ).encode("utf-8")
    mutated_items: list[dict] = []
    try:
        for index, item in enumerate(planned, start=1):
            if item["source"].read_bytes() != item["before"]:
                raise _terminalization_fail(
                    f"payload changed after preflight: {item['reference']}"
                )
            _atomic_write(item["source"], item["after"])
            mutated_items.append(item)
            if inject_failure_after == index:
                raise _terminalization_fail(
                    f"injected terminalization failure after row {index}"
                )
        _atomic_write(receipt, receipt_bytes)
        for consumer in consumers:
            if consumer["consumer"].read_bytes() != consumer["before"]:
                raise _terminalization_fail(
                    f"terminalization rewrote consumer: {consumer['consumerRelative']}"
                )
        for item in planned:
            if (
                not item["source"].is_file()
                or item["target"].exists()
                or item["source"].read_bytes() != item["after"]
                or _category_locations(root, item["category"], item["slug"])
                != [item["source"]]
            ):
                raise _terminalization_fail(
                    f"terminalization identity check failed: {item['reference']}"
                )
    except Exception as exc:
        rollback_failures: list[str] = []
        for item in reversed(mutated_items):
            try:
                _atomic_write(item["source"], item["before"])
            except Exception as rollback_exc:
                rollback_failures.append(
                    f"{item['reference']}: {rollback_exc}"
                )
        if receipt.exists():
            try:
                _CURRENT_LIFECYCLE_TRANSACTION.get().restore_owned_file(receipt, None)
            except (OSError, LifecycleError) as rollback_exc:
                rollback_failures.append(f"receipt: {rollback_exc}")
        if rollback_failures:
            raise _terminalization_fail(
                "terminalization rollback failed: " + "; ".join(rollback_failures)
            ) from exc
        if isinstance(exc, LifecycleError):
            raise
        raise _terminalization_fail(
            f"terminalization transaction failed: {exc}"
        ) from exc
    return len(planned), False


def _bound_inventory_path(work_items: Path, relative: str) -> Path:
    if not isinstance(relative, str) or not relative:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY", "inventory path is missing"
        )
    unresolved_root = _lifecycle_unresolved_absolute(work_items)
    unresolved_path = unresolved_root / Path(relative)
    _lifecycle_reject_unreduced_reparse(
        unresolved_root,
        failure_id="WI-CATEGORY-MIGRATION-INVENTORY",
        message="work-items root or parent contains a link or reparse point",
    )
    _lifecycle_reject_unreduced_reparse(
        unresolved_path,
        failure_id="WI-CATEGORY-MIGRATION-INVENTORY",
        message=f"inventory path contains a link or reparse point: {relative}",
    )
    root = Path(os.path.abspath(unresolved_root))
    path = Path(os.path.abspath(unresolved_path))
    if path != root and root not in path.parents:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            f"inventory path escapes work-items: {relative}",
        )
    return path


def _terminalization_receipt_for_migration(
    root: Path,
    inventory_path: Path,
    inventory: dict,
) -> tuple[Path, bytes, dict]:
    admissions = [
        row["incomingLinks"]["physicalRelocation"]
        for row in inventory["rows"]
        if isinstance(row, dict)
        and isinstance(row.get("incomingLinks"), dict)
        and isinstance(row["incomingLinks"].get("physicalRelocation"), dict)
    ]
    if len(admissions) != 1:
        raise LifecycleError(
            "WI-LEGACY-LINK-UNMAPPED",
            "migration requires exactly one physical-relocation admission",
        )
    receipt_path = _bound_physical_receipt(root, admissions[0].get("receipt"))
    try:
        receipt_bytes = receipt_path.read_bytes()
        receipt = json.loads(receipt_bytes.decode("utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            f"physical-relocation receipt is invalid: {receipt_path}",
        ) from exc
    inventory_sha256 = hashlib.sha256(inventory_path.read_bytes()).hexdigest()
    work_items = _work_items_root(root)
    if (
        not isinstance(receipt, dict)
        or receipt.get("schemaVersion") != V1_TERMINALIZATION_SCHEMA_VERSION
        or receipt.get("owner") != V1_TERMINALIZATION_OWNER
        or receipt.get("workItemsRoot") != str(work_items.resolve())
        or receipt.get("inventorySha256") != inventory_sha256
        or receipt.get("authorizationMarker") != V1_TERMINALIZATION_AUTHORIZATION
        or receipt.get("rowCount") != len(inventory["rows"])
        or receipt.get("linkCount") != 1
        or not isinstance(receipt.get("rows"), list)
        or len(receipt["rows"]) != len(inventory["rows"])
        or not isinstance(receipt.get("terminalAt"), str)
    ):
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY",
            "physical-relocation receipt binding differs",
        )
    _strict_utc(receipt["terminalAt"])
    return receipt_path, receipt_bytes, receipt


def _preflight_terminalized_inventory_rows(
    root: Path,
    inventory_path: Path,
    inventory: dict,
) -> tuple[list[dict], list[dict], Path, bytes, dict]:
    work_items = _work_items_root(root)
    receipt_path, receipt_bytes, receipt = _terminalization_receipt_for_migration(
        root, inventory_path, inventory
    )
    replay = _terminalization_replay(
        root,
        inventory,
        hashlib.sha256(inventory_path.read_bytes()).hexdigest(),
        receipt["terminalAt"],
        V1_TERMINALIZATION_AUTHORIZATION,
        receipt_path,
    )
    if replay is None:
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY", "terminalization receipt is missing"
        )
    receipt_rows = {row.get("reference"): row for row in receipt["rows"] if isinstance(row, dict)}
    if len(receipt_rows) != len(inventory["rows"]):
        raise LifecycleError(
            "WI-CATEGORY-MIGRATION-INVENTORY", "terminalization receipt repeats a row"
        )
    plans: list[dict] = []
    consumers: list[dict] = []
    seen_sources: set[Path] = set()
    seen_targets: set[Path] = set()
    for row in inventory["rows"]:
        reference = row.get("reference") if isinstance(row, dict) else None
        receipt_row = receipt_rows.get(reference)
        admission = row.get("admission") if isinstance(row, dict) else None
        if (
            not isinstance(row, dict)
            or not isinstance(receipt_row, dict)
            or not isinstance(admission, dict)
            or admission.get("result") != "denied"
            or admission.get("failureId") != V1_TERMINALIZATION_FAILURE
        ):
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY",
                f"terminalized inventory row is invalid: {reference}",
            )
        category, slug = _canonical_category(reference)
        if row.get("category") != category.name:
            raise LifecycleError(
                "CATEGORY-MIGRATION-ADMISSION-GATE",
                f"category tuple differs for {reference}",
            )
        source = _bound_inventory_path(work_items, row.get("source"))
        target = _bound_inventory_path(work_items, receipt_row.get("target"))
        if source in seen_sources or target in seen_targets:
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION", "terminalized inventory repeats a source or target"
            )
        seen_sources.add(source)
        seen_targets.add(target)
        source_exists = source.is_file()
        target_exists = target.is_file()
        if source_exists == target_exists:
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION", f"terminalized location differs for {reference}"
            )
        payload = source if source_exists else target
        payload_sha256 = hashlib.sha256(payload.read_bytes()).hexdigest()
        if (
            receipt_row.get("source") != row.get("source")
            or receipt_row.get("beforeSha256") != row.get("inputSha256")
            or receipt_row.get("afterSha256") != payload_sha256
            or receipt_row.get("terminalAt") != receipt["terminalAt"]
        ):
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD", f"terminalized payload changed for {reference}"
            )
        instant, expected_target = _validated_migration_payload_target(
            root, category, slug, payload
        )
        if instant != receipt["terminalAt"] or target != expected_target.resolve():
            raise LifecycleError(
                "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH", f"terminalized target differs for {reference}"
            )
        if _category_locations(root, category, slug) != [payload]:
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION", f"terminalized identity differs for {reference}"
            )
        incoming = row.get("incomingLinks")
        _links, physical = _physical_relocation_admission(
            root, reference, incoming, receipt_path=receipt_path
        )
        plan = {
            "row": row,
            "reference": reference,
            "category": category,
            "slug": slug,
            "source": source,
            "target": target,
            "pending": source_exists,
            "beforeSha256": receipt_row["afterSha256"],
            "receiptRow": receipt_row,
        }
        if physical is None:
            current_links = _incoming_link_result(root, {source, target}, reference)
            _validate_incoming_link_compatibility(
                root,
                reference,
                incoming,
                current_links,
                resolved_location=payload,
            )
        elif source_exists:
            planned_consumers, planned_links = _plan_v1_link_relocations(
                root,
                [
                    {
                        "reference": reference,
                        "sourceRelative": row["source"],
                        "source": source,
                        "targetRelative": receipt_row["target"],
                        "target": target,
                        "incomingLinks": incoming,
                        "beforeSha256": row["inputSha256"],
                        "afterSha256": receipt_row["afterSha256"],
                    }
                ],
                receipt["terminalAt"],
                receipt_path,
            )
            if planned_links != [receipt_row.get("physicalRelocation")]:
                raise LifecycleError(
                    "WI-LEGACY-LINK-UNMAPPED",
                    f"physical-relocation receipt differs for {reference}",
                )
            consumers.extend(planned_consumers)
        plans.append(plan)
    source_set = {plan["source"] for plan in plans}
    target_set = {plan["target"] for plan in plans}
    if source_set & target_set:
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "source and target sets overlap")
    return sorted(plans, key=lambda plan: plan["reference"]), consumers, receipt_path, receipt_bytes, receipt


def _preflight_inventory_rows(
    root: Path,
    inventory: dict,
) -> list[tuple[dict, Path, Path, bool]]:
    work_items = _work_items_root(root)
    planned: list[tuple[dict, Path, Path, bool]] = []
    seen_sources: set[Path] = set()
    seen_targets: set[Path] = set()
    for row in inventory["rows"]:
        if not isinstance(row, dict):
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY", "inventory row is not an object"
            )
        admission = row.get("admission")
        if not isinstance(admission, dict) or admission.get("result") != "admitted":
            raise LifecycleError(
                (admission or {}).get(
                    "failureId", "CATEGORY-MIGRATION-ADMISSION-GATE"
                ),
                (admission or {}).get("reason", "inventory row is not admitted"),
            )
        incoming = row.get("incomingLinks")
        if not isinstance(incoming, dict) or incoming.get("result") not in {
            "clear",
            "logical-only",
        }:
            raise LifecycleError(
                "WI-LEGACY-LINK-UNMAPPED",
                f"incoming links are not mapped for {row.get('reference')}",
            )
        category, slug = _canonical_category(row.get("reference", ""))
        if row.get("category") != category.name:
            raise LifecycleError(
                "CATEGORY-MIGRATION-ADMISSION-GATE",
                f"category tuple differs for {row.get('reference')}",
            )
        source = _bound_inventory_path(work_items, row.get("source"))
        target = _bound_inventory_path(work_items, row.get("target"))
        if source in seen_sources or target in seen_targets:
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION", "inventory repeats a source or target"
            )
        seen_sources.add(source)
        seen_targets.add(target)
        source_exists = source.exists()
        target_exists = target.exists()
        if source_exists == target_exists:
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION",
                f"pre-migration location differs for {row.get('reference')}",
            )
        payload = source if source_exists else target
        locations = _category_locations(root, category, slug)
        if locations != [payload]:
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION",
                f"resolved location differs for {row.get('reference')}",
            )
        algorithm, digest = _payload_digest(payload)
        if (
            row.get("digestAlgorithm") != algorithm
            or row.get("inputSha256") != digest
        ):
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD",
                f"migration payload changed for {row.get('reference')}",
            )
        instant, expected_target = _validated_migration_payload_target(
            root, category, slug, payload
        )
        if (
            row.get("terminalInstant") != instant
            or target != expected_target.resolve()
        ):
            raise LifecycleError(
                "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH",
                f"planned target differs for {row.get('reference')}",
            )
        current_links = _incoming_link_result(
            root,
            {source, target},
            row["reference"],
        )
        _validate_incoming_link_compatibility(
            root,
            row["reference"],
            incoming,
            current_links,
            resolved_location=payload,
        )
        planned.append((row, source, target, source_exists))
    source_set = {source for _row, source, _target, _pending in planned}
    target_set = {target for _row, _source, target, _pending in planned}
    if source_set & target_set:
        raise LifecycleError(
            "WI-CATEGORY-DUAL-LOCATION", "source and target sets overlap"
        )
    return sorted(planned, key=lambda item: item[0]["reference"])


def apply_migration_inventory(
    root: Path,
    inventory_path: Path,
    *,
    render_readme: bool,
    byte_check: bool,
) -> tuple[int, str | None]:
    inventory = _load_migration_inventory(root, inventory_path)
    has_physical_relocation = any(
        isinstance(row, dict)
        and isinstance(row.get("incomingLinks"), dict)
        and isinstance(row["incomingLinks"].get("physicalRelocation"), dict)
        for row in inventory["rows"]
    )
    if has_physical_relocation:
        plans, consumers, receipt_path, receipt_before, receipt_payload = (
            _preflight_terminalized_inventory_rows(root, inventory_path, inventory)
        )
        work_items = _work_items_root(root)
        readme = work_items / "README.md"
        readme_before = readme.read_bytes() if readme.is_file() else None
        written_consumers: list[dict] = []
        moved: list[dict] = []
        created_directories: list[_OwnedNativeCreation] = []
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if transaction is None:
            raise LifecycleError("WI-LIFECYCLE-EFFECT", "inventory migration requires its held lifecycle owner")
        try:
            for consumer in consumers:
                if consumer["consumer"].read_bytes() != consumer["before"]:
                    raise LifecycleError(
                        "WI-LEGACY-LINK-UNMAPPED",
                        f"consumer changed after preflight: {consumer['consumerRelative']}",
                    )
                _atomic_write(consumer["consumer"], consumer["after"])
                written_consumers.append(consumer)
            for plan in plans:
                if not plan["pending"]:
                    continue
                if (
                    not plan["source"].is_file()
                    or plan["target"].exists()
                    or hashlib.sha256(plan["source"].read_bytes()).hexdigest()
                    != plan["beforeSha256"]
                ):
                    raise LifecycleError(
                        "WI-CATEGORY-MIGRATION-PAYLOAD",
                        f"payload changed after preflight: {plan['reference']}",
                    )
                LifecycleWriteTarget.make_directories(
                    plan["target"].parent, transaction, created=created_directories,
                )
                _replace_lifecycle_directory(plan["source"], plan["target"], directory=False)
                moved.append(plan)
            readme_hash: str | None = None
            if render_readme:
                readme_hash = refresh_readme(root, allow_marker_bootstrap=True)
            if byte_check and (
                not readme.is_file() or readme.read_bytes() != render_readme_bytes(root)
            ):
                raise LifecycleError(
                    "WI-README-STALE", "README differs from an immediate fresh render"
                )
            for plan in plans:
                if (
                    plan["source"].exists()
                    or not plan["target"].is_file()
                    or hashlib.sha256(plan["target"].read_bytes()).hexdigest()
                    != plan["beforeSha256"]
                    or _category_locations(root, plan["category"], plan["slug"])
                    != [plan["target"]]
                ):
                    raise LifecycleError(
                        "WI-CATEGORY-DUAL-LOCATION",
                        f"migration identity check failed: {plan['reference']}",
                    )
            consumers_by_source = {
                consumer["consumerRelative"]: consumer for consumer in consumers
            }
            for row in receipt_payload["rows"]:
                evidence = row.get("physicalRelocation")
                if not isinstance(evidence, dict):
                    continue
                consumer = consumers_by_source.get(evidence.get("source"))
                if consumer is None:
                    if not isinstance(evidence.get("sourceAfterSha256"), str):
                        raise LifecycleError(
                            "WI-LEGACY-LINK-UNMAPPED",
                            "settled physical relocation lacks receipt evidence",
                        )
                    continue
                if (
                    consumer["consumer"].read_bytes() != consumer["after"]
                    or not _markdown_href_resolves(
                        consumer["consumer"].parent,
                        evidence["newHref"],
                        _bound_inventory_path(work_items, evidence["finalTarget"]),
                    )
                ):
                    raise LifecycleError(
                        "WI-LEGACY-LINK-UNMAPPED",
                        "migrated Markdown href does not resolve to final target",
                    )
                evidence["sourceAfterSha256"] = consumer["afterSha256"]
                final_target = _bound_inventory_path(work_items, evidence["finalTarget"])
                evidence["targetAfterSha256"] = hashlib.sha256(
                    final_target.read_bytes()
                ).hexdigest()
            _atomic_write(
                receipt_path,
                (json.dumps(receipt_payload, indent=2, sort_keys=True) + "\n").encode(
                    "utf-8"
                ),
            )
            return len(plans), readme_hash
        except BaseException as exc:
            rollback_failures: list[str] = []
            for plan in reversed(moved):
                try:
                    if plan["target"].exists() and not plan["source"].exists():
                        plan["source"].parent.mkdir(parents=True, exist_ok=True)
                        _replace_lifecycle_directory(plan["target"], plan["source"], directory=False)
                except BaseException as rollback_exc:
                    rollback_failures.append(
                        f"{plan['reference']}: {rollback_exc}"
                    )
            for consumer in reversed(written_consumers):
                try:
                    _atomic_write(consumer["consumer"], consumer["before"])
                except BaseException as rollback_exc:
                    rollback_failures.append(
                        f"{consumer['consumerRelative']}: {rollback_exc}"
                    )
            try:
                _restore_readme_snapshot(readme, readme_before)
            except BaseException as rollback_exc:
                rollback_failures.append(f"README: {rollback_exc}")
            try:
                _atomic_write(receipt_path, receipt_before)
            except BaseException as rollback_exc:
                rollback_failures.append(f"receipt: {rollback_exc}")
            for record in reversed(created_directories):
                if not record.creation_published:
                    continue  # The native creator already settled its unpublished abort.
                try:
                    LifecycleWriteTarget.remove_created_directory(
                        record, transaction, failure_id="WI-CATEGORY-MIGRATION-INVENTORY",
                    )
                except BaseException as rollback_exc:
                    rollback_failures.append(f"directory {record.locator}: {rollback_exc}")
            if rollback_failures:
                raise LifecycleError(
                    "WI-CATEGORY-MIGRATION-INVENTORY",
                    "physical-relocation rollback failed: " + "; ".join(rollback_failures),
                ) from exc
            if not isinstance(exc, Exception):
                raise
            if isinstance(exc, LifecycleError):
                raise
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-INVENTORY",
                f"physical-relocation transaction failed: {exc}",
            ) from exc
    planned = _preflight_inventory_rows(root, inventory)
    created_directories: list[_OwnedNativeCreation] = []
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is None:
        raise LifecycleError("WI-LIFECYCLE-EFFECT", "inventory migration requires its held lifecycle owner")
    for _row, source, target, pending in planned:
        if not pending:
            continue
        transaction.verify()
        created_before = len(created_directories)
        try:
            LifecycleWriteTarget.make_directories(
                target.parent, transaction, created=created_directories,
            )
            (_replace_lifecycle_directory(source, target) if source.is_dir()
             else _replace_lifecycle_directory(source, target, directory=False))
        except BaseException as exc:
            rollback_failures: list[str] = []
            for record in reversed(created_directories[created_before:]):
                if not record.creation_published:
                    continue  # The native creator already settled its unpublished abort.
                try:
                    LifecycleWriteTarget.remove_created_directory(
                        record, transaction, failure_id="WI-CATEGORY-MIGRATION-INVENTORY",
                    )
                except BaseException as rollback_exc:
                    rollback_failures.append(f"directory {record.locator}: {rollback_exc}")
            if rollback_failures:
                raise LifecycleError(
                    "WI-CATEGORY-MIGRATION-INVENTORY",
                    f"migration parent creation rollback failed: {exc}; " + "; ".join(rollback_failures),
                ) from exc
            raise
    readme_hash: str | None = None
    if render_readme:
        readme_hash = refresh_readme(root, allow_marker_bootstrap=True)
    if byte_check:
        readme = _work_items_root(root) / "README.md"
        if not readme.is_file() or readme.read_bytes() != render_readme_bytes(root):
            raise LifecycleError(
                "WI-README-STALE", "README differs from an immediate fresh render"
            )
    for _row, source, target, _pending in planned:
        if source.exists() or not target.exists():
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION",
                "source-target disjointness failed after migration",
            )
    return len(planned), readme_hash


def _partial_recovery_fail(failure_id: str, message: str) -> LifecycleError:
    return LifecycleError(failure_id, f"partial-migration-recovery: {message}")


def _partial_recovery_sha256(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest().upper()


def _partial_recovery_bound_scratch_file(
    root: Path,
    path: Path,
    *,
    label: str,
) -> Path:
    unresolved_root = _lifecycle_unresolved_absolute(root)
    _lifecycle_reject_unreduced_reparse(
        unresolved_root,
        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
        message=f"{label} root or parent contains a link or reparse point",
    )
    repository_root, _work_items = _resolve_project_root_identity(
        unresolved_root, input_role="repository-root",
    )
    candidate = path if path.is_absolute() else repository_root / path
    _lifecycle_reject_unreduced_reparse(
        repository_root / "work-items",
        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
        message=f"{label} work-items root contains a link or reparse point",
    )
    _lifecycle_reject_unreduced_reparse(
        candidate,
        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
        message=f"{label} contains a link or reparse point",
    )
    repository_root = Path(os.path.abspath(repository_root))
    candidate = Path(os.path.abspath(candidate))
    try:
        relative = candidate.relative_to(repository_root)
    except ValueError as exc:
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
            f"{label} escapes the repository",
        ) from exc
    if len(relative.parts) < 2 or relative.parts[0] != ".scratch":
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
            f"{label} must be a file under repository .scratch",
        )
    return repository_root / relative


def _partial_recovery_expected_paths(
    work_items: Path,
    reference: str,
) -> tuple[str, str, Path, Path]:
    category, slug = _canonical_category(reference)
    if category.name == "work-item":
        source_relative = f"active/{slug}"
        target_relative = f"archive/2026-08/{slug}"
    elif category.name == "bug":
        source_relative = f"bugs/{slug}.md"
        target_relative = f"bugs/archive/2026-08/{slug}.md"
    else:
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
            f"unsupported incident reference: {reference}",
        )
    return (
        source_relative,
        target_relative,
        _bound_inventory_path(work_items, source_relative),
        _bound_inventory_path(work_items, target_relative),
    )


def _partial_recovery_validate_target_path(path: Path, failure_id: str) -> None:
    cursor = path
    while True:
        if (cursor.exists() or cursor.is_symlink()) and _lifecycle_path_has_reparse(cursor):
            raise _partial_recovery_fail(failure_id, "target path contains a reparse point")
        if cursor.parent == cursor:
            break
        cursor = cursor.parent


def _partial_recovery_preflight(
    root: Path,
    inventory: dict,
) -> tuple[list[dict], list[dict]]:
    work_items = _work_items_root(root)
    rows = inventory["rows"]
    expected_references = set(PARTIAL_MIGRATION_RECOVERY_TARGETS) | set(
        PARTIAL_MIGRATION_RECOVERY_UNCHANGED_ROWS
    )
    references = [row.get("reference") for row in rows]
    if len(rows) != 4 or len(set(references)) != 4 or set(references) != expected_references:
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
            "inventory candidate set is not the exact admitted four-row incident",
        )
    status_plans: list[dict] = []
    unchanged_plans: list[dict] = []
    for row in sorted(rows, key=lambda item: item["reference"]):
        reference = row["reference"]
        source_relative, target_relative, source, target = (
            _partial_recovery_expected_paths(work_items, reference)
        )
        category, _slug = _canonical_category(reference)
        expected_digest = (
            PARTIAL_MIGRATION_RECOVERY_TARGETS[reference].inventory_tree_preimage
            if reference in PARTIAL_MIGRATION_RECOVERY_TARGETS
            else PARTIAL_MIGRATION_RECOVERY_UNCHANGED_ROWS[reference]
        )
        if (
            row.get("category") != category.name
            or row.get("source") != source_relative
            or row.get("target") != target_relative
            or str(row.get("inputSha256", "")).upper() != expected_digest.upper()
            or row.get("admission", {}).get("result") != "admitted"
            or not isinstance(row.get("terminalInstant"), str)
            or archive_month(row["terminalInstant"]) != "2026-08"
            or source.exists()
            or not target.exists()
        ):
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
                f"inventory row or source/target relation differs: {reference}",
            )
        _partial_recovery_validate_target_path(
            target,
            "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
        )
        algorithm, current_digest = _payload_digest(target)
        if algorithm != row.get("digestAlgorithm"):
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
                f"target digest algorithm differs: {reference}",
            )
        if reference not in PARTIAL_MIGRATION_RECOVERY_TARGETS:
            if current_digest.upper() != expected_digest.upper():
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
                    f"unchanged target bytes differ: {reference}",
                )
            _validate_flat_terminal(category, target.read_bytes())
            unchanged_plans.append(
                {
                    "reference": reference,
                    "row": row,
                    "source": source,
                    "target": target,
                    "digest": current_digest.upper(),
                }
            )
            continue
        contract = PARTIAL_MIGRATION_RECOVERY_TARGETS[reference]
        status_path = target / "status.md"
        closure_path = target / "closure.md"
        if not status_path.is_file() or not closure_path.is_file():
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
                f"status or closure is missing: {reference}",
            )
        _partial_recovery_validate_target_path(
            status_path,
            "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
        )
        _partial_recovery_validate_target_path(
            closure_path,
            "WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
        )
        status_snapshot = _capture_file_snapshot(
            status_path,
            failure_id="WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
        )
        closure_snapshot = _capture_file_snapshot(
            closure_path,
            failure_id="WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
        )
        status_before = status_snapshot.data
        closure_before = closure_snapshot.data
        if _partial_recovery_sha256(closure_before) != contract.closure_sha256.upper():
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
                f"closure hash differs: {reference}",
            )
        occurrences = _schema_marker_occurrences(closure_before, "closure.md")
        if len(occurrences) != 1 or occurrences[0] != (
            WORK_ITEM_SCHEMA_MARKER,
            WORK_ITEM_SCHEMA_KEY,
            WORK_ITEM_SCHEMA_VALUE,
        ):
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
                f"closure lifecycle marker differs: {reference}",
            )
        _validate_closure(closure_before, row["terminalInstant"])
        status_digest = _partial_recovery_sha256(status_before)
        if status_digest == contract.status_preimage.upper():
            if current_digest.upper() != contract.inventory_tree_preimage.upper():
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
                    f"target tree preimage differs: {reference}",
                )
            status_after = _terminalize_status(status_before)
            if _partial_recovery_sha256(status_after) != contract.status_afterimage.upper():
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
                    f"canonical status projection differs: {reference}",
                )
            pending = True
        elif status_digest == contract.status_afterimage.upper():
            if current_digest.upper() != contract.projected_tree_afterimage.upper():
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
                    f"target tree afterimage differs: {reference}",
                )
            _require_canonical_schema_marker(
                _schema_marker_occurrences(status_before, "status.md"),
                "status.md",
            )
            status_after = status_before
            pending = False
        else:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
                f"status is neither admitted preimage nor deterministic afterimage: {reference}",
            )
        status_plans.append(
            {
                "reference": reference,
                "row": row,
                "source": source,
                "target": target,
                "status": status_path,
                "closure": closure_path,
                "status_before": status_before,
                "status_after": status_after,
                "closure_before": closure_before,
                "status_snapshot": status_snapshot,
                "closure_snapshot": closure_snapshot,
                "pending": pending,
                "contract": contract,
            }
        )
    return status_plans, unchanged_plans


def _partial_recovery_receipt_bytes(
    inventory_sha256: str,
    readme_before_sha256: str,
    readme_after_sha256: str,
    status_plans: list[dict],
    unchanged_plans: list[dict],
) -> bytes:
    rows = []
    for plan in sorted(status_plans, key=lambda item: item["reference"]):
        contract = plan["contract"]
        rows.append(
            {
                "action": "terminalize-status",
                "closureSha256": contract.closure_sha256.upper(),
                "finalTreeSha256": contract.projected_tree_afterimage.upper(),
                "inputTreeSha256": contract.inventory_tree_preimage.upper(),
                "reference": plan["reference"],
                "source": plan["row"]["source"],
                "statusAfterSha256": contract.status_afterimage.upper(),
                "statusBeforeSha256": contract.status_preimage.upper(),
                "target": plan["row"]["target"],
            }
        )
    for plan in sorted(unchanged_plans, key=lambda item: item["reference"]):
        rows.append(
            {
                "action": "none",
                "finalTreeSha256": plan["digest"].upper(),
                "inputTreeSha256": plan["digest"].upper(),
                "reference": plan["reference"],
                "source": plan["row"]["source"],
                "target": plan["row"]["target"],
            }
        )
    payload = {
        "audit": "PASS",
        "inventoryRowCount": 4,
        "inventorySha256": inventory_sha256.upper(),
        "operationId": "recover-partial-migration-v1:909A56",
        "owner": "work-items-lifecycle-v1-partial-migration-recovery",
        "readmeAfterSha256": readme_after_sha256.upper(),
        "readmeBeforeSha256": readme_before_sha256.upper(),
        "rows": sorted(rows, key=lambda row: row["reference"]),
        "schemaVersion": 1,
    }
    return (json.dumps(payload, indent=2, sort_keys=True) + "\n").encode("utf-8")


def _partial_recovery_fsync_directory(path: Path) -> None:
    _lifecycle_reject_unreduced_reparse(
        path,
        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CREATE-UNSUPPORTED",
        message="recovery receipt parent contains a link or reparse point",
    )
    descriptor = None
    native_handle = None
    try:
        if os.name == "nt":
            import ctypes
            import ctypes.wintypes
            import msvcrt

            kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
            create_file = kernel32.CreateFileW
            create_file.argtypes = [
                ctypes.wintypes.LPCWSTR,
                ctypes.wintypes.DWORD,
                ctypes.wintypes.DWORD,
                ctypes.wintypes.LPVOID,
                ctypes.wintypes.DWORD,
                ctypes.wintypes.DWORD,
                ctypes.wintypes.HANDLE,
            ]
            create_file.restype = ctypes.wintypes.HANDLE
            native_handle = create_file(
                str(path),
                0x40000000,  # GENERIC_WRITE
                0x00000001 | 0x00000002 | 0x00000004,
                None,
                3,  # OPEN_EXISTING
                0x02000000 | 0x00200000,
                None,
            )
            if native_handle == ctypes.wintypes.HANDLE(-1).value:
                native_handle = None
                raise OSError(ctypes.get_last_error(), "cannot open receipt directory")
            descriptor = msvcrt.open_osfhandle(native_handle, os.O_RDWR)
            native_handle = None
        else:
            flags = os.O_RDONLY
            flags |= getattr(os, "O_DIRECTORY", 0)
            flags |= getattr(os, "O_NOFOLLOW", 0)
            descriptor = os.open(path, flags)
        if not stat.S_ISDIR(os.fstat(descriptor).st_mode):
            raise OSError(errno.ENOTDIR, "receipt parent is not a directory")
        os.fsync(descriptor)
    except OSError as exc:
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CREATE-UNSUPPORTED",
            "filesystem cannot durably settle the recovery receipt directory",
        ) from exc
    finally:
        if descriptor is not None:
            os.close(descriptor)
        elif native_handle is not None:
            import ctypes

            ctypes.WinDLL("kernel32", use_last_error=True).CloseHandle(native_handle)


def _partial_recovery_exact_receipt_snapshot(
    path: Path,
    data: bytes,
) -> CapturedFileSnapshot | None:
    failure_id = "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT"
    try:
        info = path.lstat()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise _partial_recovery_fail(
            failure_id,
            "final recovery receipt identity is ambiguous",
        ) from exc
    if (
        not stat.S_ISREG(info.st_mode)
        or stat.S_ISLNK(info.st_mode)
        or bool(
            getattr(info, "st_file_attributes", 0)
            & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
        )
    ):
        raise _partial_recovery_fail(
            failure_id,
            "final recovery receipt is a link, reparse point, or non-regular file",
        )
    try:
        snapshot = _capture_file_snapshot(path, failure_id=failure_id)
    except LifecycleError as exc:
        raise _partial_recovery_fail(
            failure_id,
            "final recovery receipt identity cannot be proven",
        ) from exc
    if snapshot.data != data:
        raise _partial_recovery_fail(failure_id, "final recovery receipt differs")
    return snapshot


def _partial_recovery_settle_receipt(path: Path, data: bytes) -> bool:
    if _partial_recovery_exact_receipt_snapshot(path, data) is not None:
        return False
    pending = path.with_name(f".{path.name}.pending-v1")
    pending_created = False
    linked_here = False
    linked_identity = None
    if pending.exists():
        pending_snapshot = _capture_file_snapshot(
            pending,
            failure_id="WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
        )
        if pending_snapshot.data == data:
            pass
        elif (
            pending_snapshot.length < len(data)
            and data.startswith(pending_snapshot.data)
        ):
            _verify_captured_file(
                pending_snapshot,
                "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
            )
            pending.unlink()
            _atomic_write(pending, data)
            pending_created = True
        else:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
                "pending recovery receipt differs",
            )
    else:
        _atomic_write(pending, data)
        pending_created = True
    pending_snapshot = _capture_file_snapshot(
        pending,
        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
    )
    if pending_snapshot.data != data:
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
            "prepared pending recovery receipt differs",
        )
    final_snapshot = None
    try:
        try:
            os.link(pending, path)
            linked_here = True
            final_snapshot = _partial_recovery_exact_receipt_snapshot(path, data)
            if final_snapshot is None or final_snapshot.identity != pending_snapshot.identity:
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
                    "created final recovery receipt identity differs from pending",
                )
            linked_identity = final_snapshot.identity
        except FileExistsError:
            final_snapshot = _partial_recovery_exact_receipt_snapshot(path, data)
            if final_snapshot is None:
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
                    "concurrent final recovery receipt disappeared",
                )
        except OSError as exc:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CREATE-UNSUPPORTED",
                "filesystem cannot atomically create the final receipt",
            ) from exc
        _partial_recovery_fsync_directory(path.parent)
        verified_final = _partial_recovery_exact_receipt_snapshot(path, data)
        if (
            final_snapshot is None
            or verified_final is None
            or verified_final.identity != final_snapshot.identity
        ):
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
                "final recovery receipt reread identity differs",
            )
        try:
            pending.unlink()
        except FileNotFoundError:
            pass
        return True
    except BaseException as exc:
        composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
        if composer is not None:
            composer.capture_primary(exc)
        if linked_here:
            try:
                current = path.lstat()
                if (
                    linked_identity is None
                    or _lifecycle_file_identity(current) != linked_identity
                    or stat.S_ISLNK(current.st_mode)
                    or bool(
                        getattr(current, "st_file_attributes", 0)
                        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
                    )
                    or _capture_file_snapshot(
                        path,
                        failure_id=(
                            "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT"
                        ),
                    ).data
                    != data
                ):
                    raise OSError("final recovery receipt identity changed")
            except (OSError, LifecycleError) as cleanup_exc:
                if composer is not None:
                    composer.record_cleanup(
                        phase="receipt-final",
                        failure_id=(
                            "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT"
                        ),
                        resource=f".scratch/{path.name}",
                        diagnostic="final receipt ownership changed during cleanup",
                        cause=cleanup_exc,
                    )
        if pending_created:
            try:
                current_pending = pending.lstat()
                if (
                    _lifecycle_file_identity(current_pending)
                    != pending_snapshot.identity
                    or stat.S_ISLNK(current_pending.st_mode)
                    or bool(
                        getattr(current_pending, "st_file_attributes", 0)
                        & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
                    )
                    or pending.read_bytes() != data
                ):
                    raise OSError("pending recovery receipt identity changed")
                pending.unlink()
            except FileNotFoundError:
                pass
            except OSError as cleanup_exc:
                if composer is not None:
                    composer.record_cleanup(
                        phase="receipt-pending",
                        failure_id=(
                            "WI-PARTIAL-MIGRATION-RECOVERY-CLEANUP-FAILED"
                        ),
                        resource=f".scratch/{pending.name}",
                        diagnostic="pending receipt cleanup failed",
                        cause=cleanup_exc,
                    )
        raise


def _partial_recovery_verify_owned_parent_chains(
    status_plans: list[dict],
    readme_snapshot: CapturedFileSnapshot,
) -> None:
    failure_id = "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT"
    for plan in status_plans:
        _verify_captured_parent_chain(plan["status_snapshot"].parent_chain, failure_id)
        _verify_captured_parent_chain(plan["closure_snapshot"].parent_chain, failure_id)
    _verify_captured_parent_chain(readme_snapshot.parent_chain, failure_id)


def recover_partial_migration_v1(
    root: Path,
    inventory_path: Path,
    *,
    expected_inventory_sha256: str,
    expected_readme_sha256: str,
    target_status_preimages: dict[str, str],
    receipt_path: Path,
    apply_admitted: bool,
    render_readme: bool,
    byte_check: bool,
    inject_failure_at: str | None = None,
) -> PartialRecoveryResult:
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is None:
        raise _partial_recovery_fail(
            "WI-LIFECYCLE-LOCK-IDENTITY",
            "recovery core requires the common lifecycle transaction",
        )
    if not (apply_admitted and render_readme and byte_check):
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
            "recovery requires --apply-admitted, --render-readme, and --byte-check",
        )
    expected_statuses = {
        reference: contract.status_preimage.upper()
        for reference, contract in PARTIAL_MIGRATION_RECOVERY_TARGETS.items()
    }
    supplied_statuses = {
        str(reference): str(digest).upper()
        for reference, digest in target_status_preimages.items()
    }
    if (
        expected_inventory_sha256.upper()
        != PARTIAL_MIGRATION_RECOVERY_INVENTORY_SHA256.upper()
        or expected_readme_sha256.upper()
        != PARTIAL_MIGRATION_RECOVERY_README_PREIMAGE_SHA256.upper()
        or supplied_statuses != expected_statuses
    ):
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
            "CLI bindings differ from the exact admitted incident",
        )
    inventory_path = _partial_recovery_bound_scratch_file(
        root,
        inventory_path,
        label="inventory",
    )
    receipt_path = _partial_recovery_bound_scratch_file(
        root,
        receipt_path,
        label="receipt",
    )
    transaction.verify()
    captured_inventory = _capture_file_snapshot(
        inventory_path,
        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
    )
    inventory_sha256 = _partial_recovery_sha256(captured_inventory.data)
    if inventory_sha256 != PARTIAL_MIGRATION_RECOVERY_INVENTORY_SHA256.upper():
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
            "captured inventory SHA-256 differs",
        )
    inventory = _parse_migration_inventory_bytes(
        root,
        captured_inventory.data,
        strict_shape=True,
    )
    status_plans, unchanged_plans = _partial_recovery_preflight(root, inventory)
    readme = _work_items_root(root) / "README.md"
    if not readme.is_file() or _lifecycle_path_has_reparse(readme):
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-README-PREIMAGE",
            "README is missing or noncanonical",
        )
    readme_snapshot = _capture_file_snapshot(
        readme,
        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-README-PREIMAGE",
    )
    readme_before = readme_snapshot.data
    readme_before_sha256 = _partial_recovery_sha256(readme_before)
    any_pending = any(plan["pending"] for plan in status_plans)
    if any_pending and readme_before_sha256 != expected_readme_sha256.upper():
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-README-PREIMAGE",
            "README does not equal the explicit preimage",
        )
    if any_pending:
        try:
            receipt_path.lstat()
        except FileNotFoundError:
            pass
        except OSError as exc:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
                "final receipt identity is ambiguous while status rows remain pending",
            ) from exc
        else:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
                "a final receipt exists while status rows remain pending",
            )

    written_statuses: list[dict] = []
    readme_written = False
    final_receipt_created = False
    receipt_bytes: bytes | None = None
    try:
        _partial_recovery_verify_owned_parent_chains(status_plans, readme_snapshot)
        for index, plan in enumerate(status_plans, start=1):
            if not plan["pending"]:
                continue
            transaction.verify()
            _verify_captured_file(
                captured_inventory,
                "WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
            )
            _verify_captured_file(
                plan["status_snapshot"],
                "WI-PARTIAL-MIGRATION-RECOVERY-PREIMAGE",
            )
            _verify_captured_file(
                plan["closure_snapshot"],
                "WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
            )
            current_status = plan["status"].read_bytes()
            current_closure = plan["closure"].read_bytes()
            _algorithm, current_tree = _payload_digest(plan["target"])
            if (
                current_status != plan["status_before"]
                or current_closure != plan["closure_before"]
                or current_tree.upper()
                != plan["contract"].inventory_tree_preimage.upper()
            ):
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
                    f"target changed after preflight: {plan['reference']}",
                )
            _verify_captured_parent_chain(
                plan["status_snapshot"].parent_chain,
                "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
            )
            _verify_captured_parent_chain(
                plan["closure_snapshot"].parent_chain,
                "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
            )
            _atomic_write(plan["status"], plan["status_after"])
            written_statuses.append(plan)
            _verify_captured_file(
                plan["closure_snapshot"],
                "WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
            )
            _algorithm, after_tree = _payload_digest(plan["target"])
            if (
                plan["status"].read_bytes() != plan["status_after"]
                or plan["closure"].read_bytes() != plan["closure_before"]
                or after_tree.upper()
                != plan["contract"].projected_tree_afterimage.upper()
            ):
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
                    f"target afterimage differs: {plan['reference']}",
                )
            if inject_failure_at == f"after-status-{index}":
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-TEST-FAILPOINT",
                    inject_failure_at,
                )

        transaction.verify()
        _verify_captured_file(
            captured_inventory,
            "WI-PARTIAL-MIGRATION-RECOVERY-INVENTORY",
        )
        _verify_captured_file(
            readme_snapshot,
            "WI-PARTIAL-MIGRATION-RECOVERY-README-PREIMAGE",
        )
        final_readme = render_readme_bytes(root)
        final_readme_sha256 = _partial_recovery_sha256(final_readme)
        current_readme = readme.read_bytes()
        if current_readme != final_readme and current_readme == readme_before:
            _partial_recovery_verify_owned_parent_chains(status_plans, readme_snapshot)
            _atomic_write(readme, final_readme)
            readme_written = True
        elif current_readme != final_readme:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
                "README changed after preflight",
            )
        if readme.read_bytes() != render_readme_bytes(root):
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
                "README differs from a fresh render",
            )
        if inject_failure_at == "after-readme":
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-TEST-FAILPOINT",
                inject_failure_at,
            )
        _partial_recovery_verify_owned_parent_chains(status_plans, readme_snapshot)
        for plan in status_plans:
            _verify_captured_file(
                plan["closure_snapshot"],
                "WI-PARTIAL-MIGRATION-RECOVERY-CLOSURE",
            )
            _algorithm, digest = _payload_digest(plan["target"])
            if (
                _partial_recovery_sha256(plan["status"].read_bytes())
                != plan["contract"].status_afterimage.upper()
                or _partial_recovery_sha256(plan["closure"].read_bytes())
                != plan["contract"].closure_sha256.upper()
                or digest.upper()
                != plan["contract"].projected_tree_afterimage.upper()
            ):
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
                    f"final target verification differs: {plan['reference']}",
                )
        for plan in unchanged_plans:
            _algorithm, digest = _payload_digest(plan["target"])
            if digest.upper() != plan["digest"].upper():
                raise _partial_recovery_fail(
                    "WI-PARTIAL-MIGRATION-RECOVERY-CONCURRENT-DRIFT",
                    f"unchanged target drifted: {plan['reference']}",
                )
        audit(root)
        receipt_bytes = _partial_recovery_receipt_bytes(
            inventory_sha256,
            expected_readme_sha256,
            final_readme_sha256,
            status_plans,
            unchanged_plans,
        )
        _partial_recovery_exact_receipt_snapshot(receipt_path, receipt_bytes)
        transaction.verify()
        final_receipt_created = _partial_recovery_settle_receipt(
            receipt_path,
            receipt_bytes,
        )
        transaction.verify()
        committed_receipt = _partial_recovery_exact_receipt_snapshot(
            receipt_path,
            receipt_bytes,
        )
        if committed_receipt is None:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-RECEIPT-CONFLICT",
                "committed receipt is absent",
            )
        _partial_recovery_verify_owned_parent_chains(status_plans, readme_snapshot)
        return PartialRecoveryCommittedCandidate(
            PartialRecoveryResult(
                receipt_sha256=_partial_recovery_sha256(receipt_bytes),
                audit="PASS",
                replay=not any_pending and not final_receipt_created,
            )
        )
    except BaseException as exc:
        composer = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.get()
        if composer is not None:
            composer.capture_primary(exc)
        exact_final_receipt = False
        if receipt_bytes is not None:
            try:
                exact_final_receipt = (
                    _partial_recovery_exact_receipt_snapshot(
                        receipt_path,
                        receipt_bytes,
                    )
                    is not None
                )
            except LifecycleError:
                exact_final_receipt = False
        if final_receipt_created or exact_final_receipt:
            raise
        rollback_failed = False
        rollback_parents_valid = True
        if written_statuses or readme_written:
            try:
                _partial_recovery_verify_owned_parent_chains(
                    status_plans,
                    readme_snapshot,
                )
            except BaseException as rollback_exc:
                rollback_parents_valid = False
                rollback_failed = True
                if composer is not None:
                    composer.record_cleanup(
                        phase="rollback-parent-chain",
                        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                        resource="work-items",
                        diagnostic="rollback parent-chain verification failed",
                        cause=rollback_exc,
                    )
        if readme_written and rollback_parents_valid:
            try:
                _verify_captured_parent_chain(
                    readme_snapshot.parent_chain,
                    "WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                )
                if readme.read_bytes() == final_readme:
                    _verify_captured_parent_chain(
                        readme_snapshot.parent_chain,
                        "WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                    )
                    _atomic_write(readme, readme_before)
                else:
                    raise OSError("README afterimage changed")
            except BaseException as rollback_exc:
                rollback_failed = True
                if composer is not None:
                    composer.record_cleanup(
                        phase="rollback-readme",
                        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                        resource="work-items/README.md",
                        diagnostic="README rollback failed",
                        cause=rollback_exc,
                    )
        for plan in reversed(written_statuses) if rollback_parents_valid else ():
            try:
                _verify_captured_parent_chain(
                    plan["status_snapshot"].parent_chain,
                    "WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                )
                _verify_captured_parent_chain(
                    plan["closure_snapshot"].parent_chain,
                    "WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                )
                if plan["status"].read_bytes() == plan["status_after"]:
                    _verify_captured_parent_chain(
                        plan["status_snapshot"].parent_chain,
                        "WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                    )
                    _atomic_write(plan["status"], plan["status_before"])
                else:
                    raise OSError("status afterimage changed")
            except BaseException as rollback_exc:
                rollback_failed = True
                if composer is not None:
                    composer.record_cleanup(
                        phase=f"rollback-status:{plan['reference']}",
                        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                        resource=str(plan["row"]["target"]) + "/status.md",
                        diagnostic=f"status rollback failed for {plan['reference']}",
                        cause=rollback_exc,
                    )
        if rollback_parents_valid and (written_statuses or readme_written):
            try:
                _partial_recovery_verify_owned_parent_chains(
                    status_plans,
                    readme_snapshot,
                )
            except BaseException as rollback_exc:
                rollback_failed = True
                if composer is not None:
                    composer.record_cleanup(
                        phase="rollback-postcheck",
                        failure_id="WI-PARTIAL-MIGRATION-RECOVERY-ROLLBACK-FAILED",
                        resource="work-items",
                        diagnostic="rollback postcheck failed",
                        cause=rollback_exc,
                    )
        if composer is not None and (written_statuses or readme_written):
            composer.set_rollback("incomplete" if rollback_failed else "completed")
        raise


def verify_migration_inventory(root: Path, inventory_path: Path) -> int:
    inventory = _load_migration_inventory(root, inventory_path)
    work_items = _work_items_root(root)
    if any(
        isinstance(row, dict)
        and isinstance(row.get("incomingLinks"), dict)
        and isinstance(row["incomingLinks"].get("physicalRelocation"), dict)
        for row in inventory["rows"]
    ):
        plans, _consumers, _receipt_path, _receipt_bytes, _receipt = (
            _preflight_terminalized_inventory_rows(root, inventory_path, inventory)
        )
        for plan in plans:
            if (
                plan["pending"]
                or not plan["target"].is_file()
                or plan["source"].exists()
                or hashlib.sha256(plan["target"].read_bytes()).hexdigest()
                != plan["beforeSha256"]
                or _category_locations(root, plan["category"], plan["slug"])
                != [plan["target"]]
            ):
                raise LifecycleError(
                    "WI-CATEGORY-DUAL-LOCATION",
                    f"settled physical relocation differs for {plan['reference']}",
                )
        check_readme(root)
        return len(plans)
    for row in inventory["rows"]:
        source = _bound_inventory_path(work_items, row.get("source"))
        target = _bound_inventory_path(work_items, row.get("target"))
        if source.exists() or not target.exists():
            raise LifecycleError(
                "WI-CATEGORY-DUAL-LOCATION",
                f"source/target state differs for {row.get('reference')}",
            )
        algorithm, digest = _payload_digest(target)
        if (
            algorithm != row.get("digestAlgorithm")
            or digest != row.get("inputSha256")
        ):
            raise LifecycleError(
                "WI-CATEGORY-MIGRATION-PAYLOAD",
                f"target payload hash differs for {row.get('reference')}",
            )
        category, _slug = _canonical_category(row.get("reference", ""))
        if row.get("category") != category.name:
            raise LifecycleError(
                "CATEGORY-MIGRATION-ADMISSION-GATE",
                f"category tuple differs for {row.get('reference')}",
            )
        instant = row.get("terminalInstant")
        if target.parent.name != archive_month(instant):
            raise LifecycleError(
                "WI-CATEGORY-ARCHIVE-MONTH-MISMATCH",
                f"target month differs for {row.get('reference')}",
            )
        if resolve_category(root, row["reference"]) != target:
            raise LifecycleError(
                "WI-LEGACY-LINK-UNMAPPED",
                f"logical reference does not resolve to target: {row['reference']}",
            )
        current_links = _incoming_link_result(
            root,
            {source, target},
            row["reference"],
        )
        _validate_incoming_link_compatibility(
            root,
            row["reference"],
            row.get("incomingLinks"),
            current_links,
            resolved_location=target,
        )
    check_readme(root)
    return len(inventory["rows"])


@functools.partial(_lifecycle_participant, subject_parameters=('category-reference', 'archived_reference'))
def reopen_category_record(
    root: Path,
    archived_reference: str,
    successor_slug: str,
    current_data: bytes,
    *, _prepared_category=None,
) -> Path:
    category, archived_slug = _canonical_category(archived_reference) if _prepared_category is None else _prepared_category
    _admission_for(category.name)
    if category.name == "work-item":
        return reopen_item(root, archived_slug, successor_slug, current_data)
    archived = resolve_category(root, archived_reference)
    if "archive" not in archived.parts:
        raise LifecycleError("WI-INVALID-TARGET", "reopen source must be archived")
    evidenced_v0 = False
    if category.name == "decision":
        row = _v0_archive_manifest_row(root, archived.name)
        evidence = row.get("archiveEvidence") if row is not None else None
        if isinstance(evidence, dict):
            expected = _work_items_root(root) / Path(evidence["archivePath"])
            if archived != expected.resolve():
                raise LifecycleError("WI-DECISION-V0-ARCHIVE-EVIDENCE", "V0 reopen archive path differs")
            record = _validate_current_decision_record(archived, archived_slug)
            if record.format != DECISION_FORMAT_V0 or record.raw_status not in category.terminal_statuses:
                raise LifecycleError("WI-DECISION-V0-ARCHIVE-EVIDENCE", "V0 reopen source is not terminal")
            evidenced_v0 = True
    if not evidenced_v0:
        _validate_flat_terminal(category, archived.read_bytes())
    _validate_slug(successor_slug)
    if _category_locations(root, category, successor_slug):
        raise LifecycleError("WI-CATEGORY-DUAL-LOCATION", "successor slug already exists")
    try:
        text = current_data.decode("utf-8")
    except UnicodeDecodeError as exc:
        raise LifecycleError("WI-CATEGORY-STATUS-INVALID", "successor must be UTF-8") from exc
    fields = _parse_fields(text)
    if fields.get("status") not in category.current_statuses:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID",
            f"{category.name} successor status must be current",
        )
    if fields.get("reopens") != archived_slug:
        raise LifecycleError(
            "WI-CATEGORY-STATUS-INVALID",
            f"successor must declare Reopens: {archived_slug}",
        )
    _preflight_readme(root)
    target = _work_items_root(root) / category.current_root / f"{successor_slug}.md"
    _atomic_write(target, current_data)
    try:
        refresh_readme(root)
    except LifecycleError as exc:
        raise LifecycleError("WI-README-STALE", str(exc)) from exc
    return target


def _fixture_status(item: dict) -> str:
    return (
        "---\n"
        "template: staged\n"
        f"status: {item['status']}\n"
        "started: 2026-07-31T00:00:00Z\n"
        f"updated: {item['updated']}\n"
        "---\n\n"
        f"Task: {item['task']}\n"
        f"Current step: {item.get('currentStep', 'Continue.')}\n"
        "Last result: Fixture materialized.\n"
        f"Next action: {item.get('nextAction', 'Continue.')}\n"
        "Scope boundary: Trial fixture only.\n"
        "Owner: toolchain-engineer\n"
        "Integration owner: toolchain-engineer\n"
        "Evidence gate: five-item trial\n"
        + (f"Blocker: {item['blocker']}\n" if item.get("blocker") else "")
        + (f"Roadmap: {item['roadmap']}\n" if item.get("roadmap") else "")
        + (f"Epic: {item['epic']}\n" if item.get("epic") else "")
    )


def _trial_expected_files(fixture: dict) -> set[str]:
    expected = {
        "work-items/README.md",
    }
    supporting_epics = fixture.get("supportingEpics", [])
    if not isinstance(supporting_epics, list):
        raise LifecycleError("WI-TRIAL-FIXTURE", "supportingEpics must be a list")
    for epic in supporting_epics:
        if not isinstance(epic, dict) or not isinstance(epic.get("slug"), str):
            raise LifecycleError("WI-TRIAL-FIXTURE", "supporting epic requires a slug")
        _validate_slug(epic["slug"])
        expected.add(f"work-items/epics/{epic['slug']}.md")

    items = fixture.get("items")
    if not isinstance(items, list) or len(items) != 5:
        raise LifecycleError("WI-TRIAL-FIXTURE", "fixture must contain exactly five items")
    for item in items:
        if not isinstance(item, dict) or not isinstance(item.get("slug"), str):
            raise LifecycleError("WI-TRIAL-FIXTURE", "trial item requires a slug")
        slug = item["slug"]
        _validate_slug(slug)
        kind = item.get("kind")
        if kind in {"active", "blocked"}:
            expected.add(f"work-items/active/{slug}/status.md")
        elif kind == "backlog":
            expected.add(f"work-items/backlog/{slug}.md")
        elif kind == "roadmap":
            expected.add(f"work-items/roadmaps/{slug}.md")
        elif kind == "archived":
            closed = item.get("closed")
            if not isinstance(closed, str):
                raise LifecycleError("WI-TRIAL-FIXTURE", "archived item requires Closed")
            expected.add(
                f"work-items/archive/{archive_month(closed)}/{slug}/closure.md"
            )
        else:
            raise LifecycleError("WI-TRIAL-FIXTURE", f"unknown trial kind: {kind}")
    return expected


def _trial_expected_directories(files: set[str]) -> set[str]:
    directories: set[str] = set()
    for value in files:
        parent = Path(value).parent
        while parent != Path("."):
            directories.add(parent.as_posix())
            parent = parent.parent
    return directories


def _trial_tree(root: Path) -> tuple[dict[str, str], set[str]]:
    files: dict[str, str] = {}
    directories: set[str] = set()
    for path in root.rglob("*"):
        relative = path.relative_to(root).as_posix()
        if relative in {".scratch", LIFECYCLE_LOCK_RELATIVE.as_posix()}:
            continue
        if path.is_symlink():
            raise LifecycleError(
                "WI-TRIAL-NOT-OWNED",
                f"trial root contains an unowned symbolic link: {relative}",
            )
        if path.is_dir():
            directories.add(relative)
        elif path.is_file():
            if relative == TRIAL_MARKER:
                continue
            files[relative] = hashlib.sha256(path.read_bytes()).hexdigest()
        else:
            raise LifecycleError(
                "WI-TRIAL-NOT-OWNED",
                f"trial root contains an unsupported entry: {relative}",
            )
    return files, directories


def _trial_root_has_payload(root: Path) -> bool:
    if not root.exists():
        return False
    for path in root.iterdir():
        if path.name != ".scratch":
            return True
        if _lifecycle_path_has_reparse(path) or not path.is_dir():
            return True
        for child in path.iterdir():
            if child.name != LIFECYCLE_LOCK_RELATIVE.name:
                return True
    return False


def _prove_completed_trial(
    root: Path,
    fixture_bytes: bytes,
    expected_files: set[str],
) -> None:
    marker_path = root / TRIAL_MARKER
    try:
        marker = json.loads(marker_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-TRIAL-NOT-OWNED",
            f"non-empty trial root lacks a valid ownership receipt: {root}",
        ) from exc
    expected_keys = {
        "schemaVersion",
        "owner",
        "fixtureSha256",
        "files",
        "directories",
    }
    if not isinstance(marker, dict) or set(marker) != expected_keys:
        raise LifecycleError("WI-TRIAL-NOT-OWNED", "trial ownership receipt shape differs")
    fixture_hash = hashlib.sha256(fixture_bytes).hexdigest()
    expected_directories = _trial_expected_directories(expected_files)
    if (
        marker.get("schemaVersion") != 1
        or marker.get("owner") != TRIAL_OWNER
        or marker.get("fixtureSha256") != fixture_hash
        or set(marker.get("files", {})) != expected_files
        or set(marker.get("directories", [])) != expected_directories
    ):
        raise LifecycleError(
            "WI-TRIAL-NOT-OWNED",
            "trial ownership receipt is not target-bound to this exact fixture/output",
        )
    actual_files, actual_directories = _trial_tree(root)
    if actual_files != marker["files"] or actual_directories != expected_directories:
        raise LifecycleError(
            "WI-TRIAL-NOT-OWNED",
            "trial root bytes or membership differ from the completed ownership receipt",
        )


def _write_trial_receipt(
    root: Path,
    fixture_bytes: bytes,
    expected_files: set[str],
) -> None:
    actual_files, actual_directories = _trial_tree(root)
    expected_directories = _trial_expected_directories(expected_files)
    if set(actual_files) != expected_files or actual_directories != expected_directories:
        raise LifecycleError(
            "WI-TRIAL-OUTPUT",
            "trial output membership differs from the owned five-item manifest",
        )
    receipt = {
        "schemaVersion": 1,
        "owner": TRIAL_OWNER,
        "fixtureSha256": hashlib.sha256(fixture_bytes).hexdigest(),
        "files": actual_files,
        "directories": sorted(actual_directories),
    }
    _atomic_write(
        root / TRIAL_MARKER,
        (json.dumps(receipt, indent=2, sort_keys=True) + "\n").encode("utf-8"),
    )


def run_trial(root: Path, fixture_path: Path) -> tuple[str, str]:
    fixture_bytes = fixture_path.read_bytes()
    fixture = json.loads(fixture_bytes.decode("utf-8"))
    if not isinstance(fixture, dict):
        raise LifecycleError("WI-TRIAL-FIXTURE", "fixture must be an object")
    expected_files = _trial_expected_files(fixture)
    if _trial_root_has_payload(root):
        _prove_completed_trial(root, fixture_bytes, expected_files)
    root.mkdir(parents=True, exist_ok=True)
    items = fixture.get("items")
    assert isinstance(items, list)
    work_items = _work_items_root(root)
    for epic in fixture.get("supportingEpics", []):
        _atomic_write(
            work_items / "epics" / f"{epic['slug']}.md",
            (
                "---\n"
                "status: active\n"
                f"updated: {epic['updated']}\n"
                "---\n\n"
                f"# {epic['title']}\n"
            ).encode("utf-8"),
        )
    for item in items:
        kind = item["kind"]
        slug = item["slug"]
        _validate_slug(slug)
        if kind in {"active", "blocked"}:
            _atomic_write(
                work_items / "active" / slug / "status.md",
                _fixture_status(item).encode("utf-8"),
            )
        elif kind == "backlog":
            _atomic_write(
                work_items / "backlog" / f"{slug}.md",
                (
                    f"Task: {item['task']}\n"
                    f"Next action: {item['nextAction']}\n"
                    f"updated: {item['updated']}\n"
                ).encode("utf-8"),
            )
        elif kind == "roadmap":
            _atomic_write(
                work_items / "roadmaps" / f"{slug}.md",
                (
                    "format: roadmap-v1\n"
                    "status: active\n"
                    "owner: product-manager\n"
                    f"outcomes: {item['outcomes']}\n"
                    f"order: {item['order']}\n"
                    f"milestones-or-horizon: {item['milestone']}\n"
                    "review-trigger: trial completion\n"
                    "retention: archive monthly\n"
                    f"updated: {item['updated']}\n"
                ).encode("utf-8"),
            )
        elif kind == "archived":
            _atomic_write(
                work_items
                / "archive"
                / archive_month(item["closed"])
                / slug
                / "closure.md",
                (
                    f"Closed: {item['closed']}\n"
                    f"Outcome: {item['outcome']}\n"
                    "Evidence: five-item trial\n"
                    f"Residual risk: {item['residualRisk']}\n"
                ).encode("utf-8"),
            )
        else:
            raise LifecycleError("WI-TRIAL-FIXTURE", f"unknown trial kind: {kind}")
    first = refresh_readme(root)
    first_bytes = (work_items / "README.md").read_bytes()
    second = refresh_readme(root)
    second_bytes = (work_items / "README.md").read_bytes()
    if first != second or first_bytes != second_bytes:
        raise LifecycleError("WI-README-NONDETERMINISTIC", "repeat render differs")
    text = second_bytes.decode("utf-8")
    checkbox_lines = [line for line in text.splitlines() if line.startswith("- [")]
    if len(checkbox_lines) != 5 or any(
        not (line.startswith("- [ ]") or line.startswith("- [x]")) for line in checkbox_lines
    ):
        raise LifecycleError("WI-TRIAL-COUNT", "trial did not render five canonical checkboxes")
    positions = [text.index(f"## {section}") for section in README_SECTIONS]
    if positions != sorted(positions):
        raise LifecycleError("WI-TRIAL-SECTIONS", "README section order differs")
    if not all(token in text for token in ("[roadmap](", "[epic](", "[work item](")):
        raise LifecycleError("WI-TRIAL-LINKS", "progressive links are incomplete")
    _write_trial_receipt(root, fixture_bytes, expected_files)
    return first, second


LEGACY_PROJECTION_MANIFEST_DIR = "legacy-ledger-projection-manifests"
LEGACY_PROJECTION_REGISTRY = "legacy-ledger-projections.jsonl"
LEGACY_PROJECTION_RECEIPTS = "legacy-ledger-projection-receipts"
LEDGER_H1_ARTIFACT_BASE = "ledger-h1-compatibility"
LEDGER_H1_RELOCATION_OWNER = "mutate-work-item:ledger-h1-artifact-set-relocation-v1"
LEDGER_H1_RELOCATION_KIND = "ledger-h1-artifact-set-relocation-v1"
LEDGER_H1_RELOCATION_EVENT = "WI-LEDGER-H1-ARTIFACT-SET-RELOCATED"
LEDGER_H1_RELOCATION_MEMBERS = (
    (DECISION_H1_MANIFEST, "file"),
    (LEGACY_PROJECTION_MANIFEST_DIR, "directory"),
    (LEGACY_PROJECTION_REGISTRY, "file"),
    (LEGACY_PROJECTION_RECEIPTS, "directory"),
)
LEDGER_H1_RELOCATION_INTENT_FIELDS = {
    "schemaVersion", "owner", "kind", "status", "operationId", "recordedAt",
    "archiveOwner", "artifactBase", "receiptPath",
    "expectedArtifactSetSha256", "expectedRootContractSha256",
    "targetBaseBefore", "members", "rootContractBefore", "rootContractAfter",
    "receiptAfter",
}
LEDGER_H1_RELOCATION_MEMBER_FIELDS = {
    "logicalPath", "sourcePath", "targetPath", "kind", "byteLength", "sha256",
}
LEDGER_H1_RELOCATION_RECEIPT_FIELDS = {
    "schemaVersion", "status", "operationId", "archiveOwner", "artifactBase",
    "artifactSetSha256", "rootContractBeforeSha256", "rootContractAfterSha256",
    "recordedAt",
}
LEDGER_H1_RELOCATION_FAILURE_BOUNDARIES = frozenset(
    {
        "after-intent",
        "after-member-1",
        "after-member-2",
        "after-member-3",
        "after-member-4",
        "after-root-contract",
        "after-receipt",
    }
)
_PROJECTION_OPERATION_RE = re.compile(r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}", re.ASCII)


def _projection_fail(failure_id: str, message: str) -> None:
    raise LifecycleError(failure_id, message)


def _projection_object(data: bytes, label: str) -> dict:
    try:
        value = json.loads(
            data.decode("utf-8"),
            object_pairs_hook=_decision_compatibility_json_object,
        )
    except (
        UnicodeDecodeError,
        json.JSONDecodeError,
        _DecisionCompatibilityManifestDuplicateKey,
    ) as exc:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", f"{label} is not one JSON object")
        raise AssertionError from exc
    if not isinstance(value, dict):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", f"{label} is not one JSON object")
    return value


def _projection_json(data: dict) -> bytes:
    return json.dumps(data, ensure_ascii=False, separators=(",", ":"), sort_keys=True).encode("utf-8")


def _projection_operation(operation_id: str, recorded_at: str) -> None:
    if _PROJECTION_OPERATION_RE.fullmatch(operation_id) is None:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "projection operation id is not bounded")
    _load_agent_run_ledger()._strict_migration_inputs(operation_id, recorded_at)


def _projection_paths(root: Path, *, input_role: str = "caller-root") -> tuple[Path, Path, Path]:
    work_items = _work_items_root(root, input_role=input_role)
    repository = work_items.parent
    manifests = _require_lifecycle_mutation_path(repository, work_items / LEGACY_PROJECTION_MANIFEST_DIR, failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID")
    registry = _require_lifecycle_mutation_path(repository, work_items / LEGACY_PROJECTION_REGISTRY, failure_id="WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE")
    receipts = _require_lifecycle_mutation_path(repository, work_items / LEGACY_PROJECTION_RECEIPTS, failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH")
    return manifests, registry, receipts


def _historical_disposition_path(root: Path, validator: object) -> Path:
    """Resolve the validator-owned historical storage only for writer operations."""
    try:
        identity = validator.historical_artifact_disposition_storage_identity()
        identity = validator.confine_legacy_projection_identifier(
            identity, failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID"
        )
    except (AttributeError, TypeError, ValueError) as exc:
        _projection_fail(
            "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
            "historical disposition storage identity is unavailable or invalid",
        )
        raise AssertionError from exc
    work_items = _work_items_root(root)
    return _require_lifecycle_mutation_path(
        work_items.parent, work_items / identity,
        failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID",
    )


def _projection_manifest_blobs(root: Path, manifests: Path, manifest_id: str, supplied: bytes) -> dict[str, bytes]:
    blobs: dict[str, bytes] = {}
    validator = _load_agent_run_ledger().load_validator()
    try:
        manifest_id = validator.confine_legacy_projection_identifier(
            manifest_id, failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID"
        )
    except ValueError as exc:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", f"projection manifest id is unsafe: {exc}")
        raise AssertionError from exc
    if manifests.exists():
        if not manifests.is_dir() or _lifecycle_path_has_reparse(manifests):
            _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "projection manifest directory is unsafe")
        for path in manifests.iterdir():
            if path.suffix != ".json" or _lifecycle_path_has_reparse(path):
                _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "projection manifest directory has unsafe member")
            try:
                safe = validator.confine_legacy_projection_path(
                    root, f"work-items/{LEGACY_PROJECTION_MANIFEST_DIR}/{path.name}",
                    prefix=("work-items", LEGACY_PROJECTION_MANIFEST_DIR), leaf_kind="file",
                    failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID",
                )
            except ValueError as exc:
                _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", f"projection manifest member is unsafe: {exc}")
                raise AssertionError from exc
            blobs[safe.name] = safe.read_bytes()
    name = f"{manifest_id}.json"
    current = blobs.get(name)
    if current is not None and current != supplied:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "create-only manifest bytes differ")
    blobs[name] = supplied
    return blobs


def _projection_registry_records(data: bytes) -> list[tuple[dict, bytes]]:
    records: list[tuple[dict, bytes]] = []
    for ordinal, line in enumerate(data.splitlines(keepends=True), start=1):
        record = _projection_object(line.rstrip(b"\r\n"), f"registry line {ordinal}")
        records.append((record, line))
    return records


def _projection_selected_entry(manifest: dict, entry_id: str, raw_ordinal: int) -> dict:
    manifest_id = manifest.get("manifestId")
    if not isinstance(manifest_id, str) or _PROJECTION_OPERATION_RE.fullmatch(manifest_id) is None:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "manifest id is invalid")
    entries = [entry for entry in manifest.get("entries", []) if isinstance(entry, dict) and entry.get("entryId") == entry_id]
    if len(entries) != 1 or not isinstance(raw_ordinal, int):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "manifest entry or raw ordinal is not unique")
    entry = entries[0]
    required = {"entryId", "profileId", "profileVersion", "workItem", "ledgerPath", "ledgerSha256", "rawLineOrdinals", "rawLineSha256", "projectedEvents", "projectedEventSha256"}
    if (
        not required <= set(entry)
        or set(entry) - (required | {"artifactSha256"})
        or not all(isinstance(entry[key], list) for key in ("rawLineOrdinals", "rawLineSha256", "projectedEvents", "projectedEventSha256"))
    ):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "manifest entry shape is incomplete")
    ordinals = entry["rawLineOrdinals"]
    raw_digests = entry["rawLineSha256"]
    projected_events = entry["projectedEvents"]
    projected_digests = entry["projectedEventSha256"]
    if (
        not ordinals
        or not (len(ordinals) == len(raw_digests) == len(projected_events) == len(projected_digests))
        or any(not isinstance(value, int) or value < 1 for value in ordinals)
        or len(set(ordinals)) != len(ordinals)
        or any(not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{64}", value) is None for value in (*raw_digests, *projected_digests))
        or any(not isinstance(value, dict) for value in projected_events)
    ):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "manifest entry bindings are not one unique parallel set")
    try:
        index = entry["rawLineOrdinals"].index(raw_ordinal)
        raw_digest = entry["rawLineSha256"][index]
        projected = entry["projectedEvents"][index]
        projected_digest = entry["projectedEventSha256"][index]
    except (ValueError, IndexError):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "raw ordinal is not bound by the manifest entry")
    if (
        not isinstance(entry.get("entryId"), str)
        or not isinstance(entry.get("profileId"), str)
        or not isinstance(entry.get("profileVersion"), int)
        or entry["profileVersion"] < 1
        or not all(isinstance(value, str) for value in (entry["workItem"], entry["ledgerPath"], entry["ledgerSha256"], raw_digest, projected_digest))
        or re.fullmatch(r"[0-9a-f]{64}", entry["ledgerSha256"]) is None
        or not isinstance(projected, dict)
    ):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "manifest entry value types are invalid")
    return entry


def _projection_entry(manifest: dict, entry_id: str, raw_ordinal: int, root: Path, *,
    candidate_ledger_bytes: bytes | None = None, selected_entry: dict | None = None) -> dict:
    entry = _projection_selected_entry(manifest, entry_id, raw_ordinal) if selected_entry is None else selected_entry
    ordinals = entry["rawLineOrdinals"]
    raw_digests = entry["rawLineSha256"]
    projected_events = entry["projectedEvents"]
    projected_digests = entry["projectedEventSha256"]
    index = ordinals.index(raw_ordinal)
    raw_digest, projected, projected_digest = raw_digests[index], projected_events[index], projected_digests[index]
    validator = _load_agent_run_ledger().load_validator()

    def controlled_path(value: str, label: str) -> Path:
        try:
            return validator.confine_legacy_projection_path(
                root, value, prefix=("work-items",), failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY"
            )
        except ValueError as exc:
            _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", f"{label} is unsafe: {exc}")
            raise AssertionError from exc

    item = controlled_path(entry["workItem"], "manifest work item")
    ledger = controlled_path(entry["ledgerPath"], "manifest ledger")
    target_errors: list[str] = []
    target = validator.classify_legacy_projection_target(
        item, ledger, target_errors, require_ledger=True
    )
    if (
        target is None
        or target_errors
        or target[0] != root
        or target[1] != entry["workItem"]
        or ledger != item / "agent-runs.jsonl"
        or not item.is_dir()
        or not ledger.is_file()
    ):
        _projection_fail(
            "WI-LEDGER-MIGRATION-TARGET-IDENTITY",
            "; ".join(target_errors) or "manifest target is not one safe active or archive work-item ledger",
        )
    snapshot = _capture_file_snapshot(ledger, failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY")
    ledger_bytes = snapshot.data if candidate_ledger_bytes is None else candidate_ledger_bytes
    lines = ledger_bytes.splitlines(keepends=True)
    if _sha256_bytes(ledger_bytes) != entry["ledgerSha256"]:
        _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "manifest ledger digest differs")
    for bound_ordinal, bound_digest, bound_projected, bound_projected_digest in zip(
        ordinals, raw_digests, projected_events, projected_digests
    ):
        if bound_ordinal > len(lines) or _sha256_bytes(lines[bound_ordinal - 1]) != bound_digest:
            _projection_fail("WI-LEDGER-MIGRATION-TARGET-DIGEST", "manifest raw line digest differs")
        if _sha256_bytes(_projection_json(bound_projected)) != bound_projected_digest:
            _projection_fail("WI-LEDGER-MIGRATION-TARGET-DIGEST", "manifest projected event digest differs")
    return {**entry, "_item": item, "_ledger": ledger, "_ledgerBytes": ledger_bytes, "_rawDigest": raw_digest, "_projected": projected, "_projectedDigest": projected_digest, "_ledgerSnapshot": snapshot}


def _projection_record(
    manifest: dict,
    manifest_bytes: bytes,
    entry_id: str,
    raw_ordinal: int,
    operation_group_id: str,
    group_member_index: int,
    group_member_count: int,
    recorded_at: str,
    root: Path,
    *,
    candidate_ledger_bytes: bytes | None = None,
    selected_entry: dict | None = None,
) -> dict:
    entry = _projection_entry(
        manifest,
        entry_id,
        raw_ordinal,
        root,
        candidate_ledger_bytes=candidate_ledger_bytes, selected_entry=selected_entry,
    )
    operation_id = _projection_group_ids(operation_group_id, group_member_count)[group_member_index - 1]
    return {
        "schemaVersion": 2, "operationId": operation_id, "operationGroupId": operation_group_id,
        "groupMemberIndex": group_member_index, "groupMemberCount": group_member_count, "state": "apply",
        "profileId": entry["profileId"], "profileVersion": entry["profileVersion"],
        "manifestId": manifest["manifestId"], "manifestSha256": _sha256_bytes(manifest_bytes),
        "manifestEntryId": entry_id, "workItem": entry["workItem"], "ledgerPath": entry["ledgerPath"],
        "ledgerSha256": entry["ledgerSha256"], "rawLineOrdinal": raw_ordinal,
        "rawLineSha256": entry["_rawDigest"], "projectedEvent": entry["_projected"],
        "projectedEventSha256": entry["_projectedDigest"], "recordedAt": recorded_at,
    }


def _projection_confine_output_sink(path: Path, failure_id: str) -> tuple[Path, bool]:
    """Return one ordinary direct-child output sink before any content probe/write.

    Pre-existing links/reparse leaves are rejected through lstat.  This is a
    deterministic preflight only; hostile same-user rename races remain outside
    the existing lifecycle-lock claim.
    """
    parent = path.parent
    parent.mkdir(parents=True, exist_ok=True)
    try:
        parent_info = parent.lstat()
    except OSError as exc:
        raise LifecycleError(failure_id, "projection output parent is unavailable") from exc
    if _lifecycle_path_has_reparse(parent) or not stat.S_ISDIR(parent_info.st_mode):
        _projection_fail(failure_id, "projection output parent is unsafe")
    if path.parent != parent or path.name in {"", ".", ".."}:
        _projection_fail(failure_id, "projection output is not one direct child")
    try:
        info = path.lstat()
    except FileNotFoundError:
        return path, False
    except OSError as exc:
        raise LifecycleError(failure_id, "projection output leaf is unavailable") from exc
    if _lifecycle_path_has_reparse(path) or not stat.S_ISREG(info.st_mode):
        _projection_fail(failure_id, "projection output leaf is unsafe")
    return path, True


def _reserve_historical_disposition_output(
    dispositions: Path, target: Path, entry_cap: int
) -> Path:
    """Reserve one create-only historical output without consuming a replay slot."""
    target, replay = _projection_confine_output_sink(
        target, "WI-LEDGER-MIGRATION-MANIFEST-INVALID"
    )
    if replay:
        return target
    from itertools import islice
    entry_count = 0
    for candidate in islice(dispositions.iterdir(), entry_cap + 1):
        try:
            candidate.lstat()
        except OSError as exc:
            raise LifecycleError(
                "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
                "historical disposition directory cannot be enumerated safely",
            ) from exc
        entry_count += 1
    if entry_count >= entry_cap:
        _projection_fail(
            "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
            "historical disposition directory exceeds resource cap",
        )
    return target


def _projection_create_or_exact(
    path: Path, data: bytes, failure_id: str,
    *, created_identities: list[tuple[int, int, int, int]] | None = None,
) -> bool:
    path, replay = _projection_confine_output_sink(path, failure_id)
    if replay:
        if path.read_bytes() != data:
            _projection_fail(failure_id, "create-only target differs after write")
        return True
    temporary: Path | None = None
    try:
        descriptor, name = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
        temporary = Path(name)
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(data)
            stream.flush()
            os.fsync(stream.fileno())
            created_identity = _load_agent_run_ledger()._noncanonical_file_identity(os.fstat(stream.fileno())) \
                if created_identities is not None else None
        try:
            os.link(temporary, path)
            if created_identities is not None and created_identity is not None:
                created_identities.append(created_identity)
        except FileExistsError:
            path, replay = _projection_confine_output_sink(path, failure_id)
            if not replay:
                _projection_fail(failure_id, "projection output disappeared during create-only write")
        except OSError as exc:
            raise LifecycleError(failure_id, "atomic create-only write is unavailable") from exc
        path, _replay = _projection_confine_output_sink(path, failure_id)
        if path.read_bytes() != data:
            _projection_fail(failure_id, "create-only target differs after write")
        return replay
    finally:
        if temporary is not None:
            temporary.unlink(missing_ok=True)


def _projection_reconcile_receipt(receipts: Path, facts: dict) -> None:
    try:
        operation_id = _load_agent_run_ledger().load_validator().confine_legacy_projection_identifier(
            facts.get("operationId"), failure_id="WI-LEDGER-MIGRATION-RECEIPT-MISMATCH"
        )
    except ValueError as exc:
        _projection_fail("WI-LEDGER-MIGRATION-RECEIPT-MISMATCH", f"projection receipt identifier is unsafe: {exc}")
        raise AssertionError from exc
    path = receipts / f"{operation_id}.json"
    _projection_create_or_exact(path, (json.dumps(facts, ensure_ascii=False, indent=2, sort_keys=True) + "\n").encode("utf-8"), "WI-LEDGER-MIGRATION-RECEIPT-MISMATCH")


def _projection_candidate_errors(entry: dict, manifests: dict[str, bytes], registry_bytes: bytes) -> list[str]:
    validator = _load_agent_run_ledger().load_validator()
    return validator.validate_work_item(
        entry["_item"], validate_status_file=False,
        projection_manifest_blobs=manifests,
        projection_registry_bytes=registry_bytes,
    )


def _projection_group_ids(operation_id: str, count: int) -> list[str]:
    if count < 1:
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "projection group count must be positive")
    values = [operation_id] if count == 1 else [
        "m:" + _sha256_bytes(
            json.dumps([operation_id, index, count], ensure_ascii=False, separators=(",", ":")).encode("utf-8")
        )
        for index in range(1, count + 1)
    ]
    if any(len(value) > 128 for value in values):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "derived projection member id exceeds its bounded grammar")
    return values


def _projection_group_facts(
    operation_id: str,
    lines: list[bytes],
    registry_before: bytes,
    registry_prefix: bytes,
) -> dict:
    record_hashes = [_sha256_bytes(line) for line in lines]
    return {
        "schemaVersion": 1,
        "operationId": operation_id,
        "recordSha256": record_hashes[0] if len(record_hashes) == 1 else record_hashes,
        "registryBeforeSha256": _sha256_bytes(registry_before),
        "registrySha256": _sha256_bytes(registry_prefix),
    }


def _projection_existing_group(
    records: list[tuple[dict, bytes]], child_ids: list[str], lines: list[bytes]
) -> tuple[bytes, bytes] | None:
    """Return exact before/after prefixes for one persisted append group.

    Receipt facts are derived from the durable prefix ending at this group, not
    from the current whole registry.  This keeps replays byte-stable after a
    later independent append.
    """
    positions: list[int] = []
    for child_id, expected_line in zip(child_ids, lines):
        matched = [index for index, (record, _physical) in enumerate(records) if record.get("operationId") == child_id]
        if len(matched) > 1:
            _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "projection operation id is duplicated")
        if not matched:
            return None
        index = matched[0]
        if records[index][1] != expected_line:
            _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "projection operation group differs from its exact inputs")
        positions.append(index)
    if positions != list(range(positions[0], positions[0] + len(positions))):
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "projection operation group is non-contiguous")
    before = b"".join(physical for _record, physical in records[:positions[0]])
    after = b"".join(physical for _record, physical in records[:positions[-1] + 1])
    return before, after


def _projection_require_replay_anchor(expected_registry_sha256: str, group_before: bytes, current_registry: bytes) -> None:
    """One replay rule for singleton and v2 groups, independent of later appends."""
    accepted = {_sha256_bytes(group_before), _sha256_bytes(current_registry)}
    if expected_registry_sha256 not in accepted:
        _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "replay expected registry digest differs from durable anchors")


def _apply_legacy_ledger_projection_locked(root: Path, manifest_bytes: bytes, entry_id: str, raw_ordinal: int, expected_registry_sha256: str, operation_id: str, recorded_at: str, *, inject_failure: str | None = None, prepared_manifest: dict | None = None, selected_entry: dict | None = None) -> dict:
    _projection_operation(operation_id, recorded_at)
    manifests_path, registry_path, receipts = _projection_paths(root)
    manifest = _projection_object(manifest_bytes, "manifest") if prepared_manifest is None else prepared_manifest
    manifest_id = manifest.get("manifestId")
    if not isinstance(manifest_id, str) or _PROJECTION_OPERATION_RE.fullmatch(manifest_id) is None:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "manifest id is required")
    manifests = _projection_manifest_blobs(Path(root).resolve(), manifests_path, manifest_id, manifest_bytes)
    before = registry_path.read_bytes() if registry_path.exists() else b""
    if registry_path.exists() and (not registry_path.is_file() or _lifecycle_path_has_reparse(registry_path)):
        _projection_fail("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "projection registry is unsafe")
    configured_entries = [row for row in manifest.get("entries", []) if isinstance(row, dict) and row.get("entryId") == entry_id]
    if len(configured_entries) != 1 or not configured_entries[0].get("rawLineOrdinals"):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "manifest entry is unavailable")
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
    )
    if _lifecycle_path_has_reparse(repository / "work-items"):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "projection writer requires one ordinary repository root")
    seed = _projection_entry(manifest, entry_id, raw_ordinal, repository, selected_entry=selected_entry)
    ordinals = seed["rawLineOrdinals"]
    child_ids = _projection_group_ids(operation_id, len(ordinals))
    records = [
        _projection_record(manifest, manifest_bytes, entry_id, ordinal, operation_id, index, len(ordinals), recorded_at, repository, selected_entry=seed)
        for index, ordinal in enumerate(ordinals, start=1)
    ]
    lines = [_projection_json(record) + b"\n" for record in records]
    registry_records = _projection_registry_records(before)
    persisted = _projection_existing_group(registry_records, child_ids, lines)
    if persisted is not None:
        persisted_before, persisted_after = persisted
        _projection_require_replay_anchor(expected_registry_sha256, persisted_before, before)
        _projection_create_or_exact(manifests_path / f"{manifest_id}.json", manifest_bytes, "WI-LEDGER-MIGRATION-MANIFEST-INVALID")
        facts = _projection_group_facts(operation_id, lines, persisted_before, persisted_after)
        _projection_reconcile_receipt(receipts, facts)
        return {**facts, "replay": True}
    existing_ids = {record.get("operationId") for record, _physical in registry_records}
    if any(child_id in existing_ids for child_id in child_ids):
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "projection operation group is partial")
    if any(
        isinstance(existing_id, str)
        and existing_id.casefold() == child_id.casefold()
        and existing_id != child_id
        for existing_id in existing_ids
        for child_id in child_ids
    ):
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "projection operation id collides case-insensitively")
    if _sha256_bytes(before) != expected_registry_sha256:
        _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "projection registry digest changed")
    candidate = before + b"".join(lines)
    errors = _projection_candidate_errors(seed, manifests, candidate)
    if errors:
        _projection_fail("WI-LEDGER-MIGRATION-CANDIDATE-INVALID", "; ".join(errors))
    if inject_failure == "before-registry":
        _projection_fail("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "injected interruption before registry commit")
    try:
        _verify_captured_file(seed["_ledgerSnapshot"], "WI-LEDGER-MIGRATION-LEDGER-DRIFT")
        _atomic_write(registry_path, candidate)
        if inject_failure == "corrupt-registry":
            registry_path.write_bytes(candidate + b"corrupt")
        actual = registry_path.read_bytes()
    except OSError as exc:
        raise LifecycleError("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "projection registry readback failed") from exc
    if actual != candidate:
        if actual == before:
            _projection_fail("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "projection registry remains exact before image")
        _projection_fail("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "projection registry is neither exact before nor after")
    if inject_failure == "after-registry":
        _projection_fail("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "injected interruption after registry commit")
    _projection_create_or_exact(manifests_path / f"{manifest_id}.json", manifest_bytes, "WI-LEDGER-MIGRATION-MANIFEST-INVALID")
    facts = _projection_group_facts(operation_id, lines, before, candidate)
    _projection_reconcile_receipt(receipts, facts)
    return {**facts, "replay": False}


_apply_legacy_ledger_projection_transaction = _lifecycle_participant(_apply_legacy_ledger_projection_locked, input_role="repository-root")


def apply_legacy_ledger_projection(root: Path, manifest_bytes: bytes, entry_id: str, raw_ordinal: int, expected_registry_sha256: str, operation_id: str, recorded_at: str, *, dry_run: bool = False, inject_failure: str | None = None) -> dict:
    manifest = _projection_object(manifest_bytes, "manifest")
    selected = _projection_selected_entry(manifest, entry_id, raw_ordinal)
    evidence = []
    repository, _work_items = _resolve_project_root_identity(
        root, failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY",
        selected_locator=(selected["workItem"], selected["ledgerPath"]), binding_evidence_out=evidence,
    )
    if dry_run:
        _projection_operation(operation_id, recorded_at)
        entry = _projection_entry(manifest, entry_id, raw_ordinal, repository, selected_entry=selected)
        _verify_project_binding_evidence(tuple(evidence), "WI-LEDGER-MIGRATION-TARGET-IDENTITY")
        child_ids = _projection_group_ids(operation_id, len(entry["rawLineOrdinals"]))
        return {"schemaVersion": 1, "dryRun": True, "byteInventory": {}, "operationIds": child_ids}
    return _apply_legacy_ledger_projection_transaction(repository, manifest_bytes, entry_id, raw_ordinal,
        expected_registry_sha256, operation_id, recorded_at, inject_failure=inject_failure,
        prepared_manifest=manifest, selected_entry=selected, _original_root=root, _binding_evidence=tuple(evidence))


_LEGACY_SETTLEMENT_PROFILES = {"identity-ledger-v1-string", "identity-record-v0"}
_LEGACY_SETTLEMENT_REQUEST_FIELDS = {
    "schemaVersion", "operationId", "recordedAt", "workItem",
    "expectedLedgerSha256", "profileId", "profileVersion", "settlements",
}
_LEGACY_SETTLEMENT_ROW_FIELDS = {"targetRunId", "disposition", "evidence"}
_LEGACY_SETTLEMENT_EVIDENCE_FIELDS = {"path", "sha256"}


def _legacy_settlement_fail(failure_id: str, message: str) -> None:
    raise LifecycleError(failure_id, message)


def _legacy_settlement_request(request_bytes: bytes) -> dict:
    request = _projection_object(request_bytes, "legacy ledger settlement request")
    if set(request) != _LEGACY_SETTLEMENT_REQUEST_FIELDS:
        _legacy_settlement_fail(
            "WI-LEDGER-LEGACY-PROFILE-UNSUPPORTED",
            "settlement request fields differ from schema version 1",
        )
    operation_id = request.get("operationId")
    recorded_at = request.get("recordedAt")
    _projection_operation(operation_id, recorded_at)
    if (
        request.get("schemaVersion") != 1
        or not isinstance(request.get("profileId"), str)
        or request["profileId"] not in _LEGACY_SETTLEMENT_PROFILES
        or request.get("profileVersion") != 1
        or not isinstance(request.get("workItem"), str)
        or SLUG_RE.fullmatch(request["workItem"]) is None
        or not isinstance(request.get("expectedLedgerSha256"), str)
        or re.fullmatch(r"[0-9a-f]{64}", request["expectedLedgerSha256"]) is None
        or not isinstance(request.get("settlements"), list)
    ):
        _legacy_settlement_fail(
            "WI-LEDGER-LEGACY-PROFILE-UNSUPPORTED",
            "settlement request identity or profile is invalid",
        )
    seen: set[str] = set()
    for row in request["settlements"]:
        if not isinstance(row, dict) or set(row) != _LEGACY_SETTLEMENT_ROW_FIELDS:
            _legacy_settlement_fail(
                "WI-LEDGER-LEGACY-SETTLEMENT-INCOMPLETE",
                "settlement row shape is invalid",
            )
        target = row.get("targetRunId")
        evidence = row.get("evidence")
        disposition = row.get("disposition")
        if (
            not isinstance(target, str)
            or len(target) < 8
            or target in seen
            or disposition not in {"satisfied-by-current-evidence", "preserve-open"}
            or not isinstance(evidence, list)
            or (disposition == "preserve-open" and evidence)
            or (disposition == "satisfied-by-current-evidence" and not evidence)
        ):
            _legacy_settlement_fail(
                "WI-LEDGER-LEGACY-SETTLEMENT-INCOMPLETE",
                "settlement targets, dispositions, and evidence must be exact and unique",
            )
        if request["profileId"] == "identity-record-v0" and disposition != "preserve-open":
            _legacy_settlement_fail(
                "WI-LEDGER-LEGACY-PROFILE-UNSUPPORTED",
                "identity-record-v0 admits preserve-open only",
            )
        seen.add(target)
        for proof in evidence:
            if (
                not isinstance(proof, dict)
                or set(proof) != _LEGACY_SETTLEMENT_EVIDENCE_FIELDS
                or not isinstance(proof.get("path"), str)
                or not proof["path"]
                or not isinstance(proof.get("sha256"), str)
                or re.fullmatch(r"[0-9a-f]{64}", proof["sha256"]) is None
            ):
                _legacy_settlement_fail(
                    "WI-LEDGER-LEGACY-EVIDENCE-DRIFT",
                    "settlement evidence binding is invalid",
                )
    return request


def _legacy_settlement_evidence(root: Path, request: dict) -> None:
    root = Path(root).resolve()
    for row in request["settlements"]:
        for proof in row["evidence"]:
            relative = PurePosixPath(proof["path"])
            if relative.is_absolute() or not relative.parts or any(
                part in {"", ".", ".."} for part in relative.parts
            ):
                _legacy_settlement_fail(
                    "WI-LEDGER-LEGACY-EVIDENCE-DRIFT",
                    "settlement evidence path is not repository-relative",
                )
            candidate = root.joinpath(*relative.parts)
            if not candidate.is_file() or any(
                _lifecycle_path_has_reparse(root.joinpath(*relative.parts[:index]))
                for index in range(1, len(relative.parts) + 1)
            ):
                _legacy_settlement_fail(
                    "WI-LEDGER-LEGACY-EVIDENCE-DRIFT",
                    f"settlement evidence is missing or unsafe: {proof['path']}",
                )
            if _sha256_bytes(candidate.read_bytes()) != proof["sha256"]:
                _legacy_settlement_fail(
                    "WI-LEDGER-LEGACY-EVIDENCE-DRIFT",
                    f"settlement evidence digest changed: {proof['path']}",
                )


def _legacy_settlement_manifest(
    root: Path,
    item: Path,
    ledger_bytes: bytes,
    request_bytes: bytes,
    request: dict,
    *,
    legacy_line_count: int | None = None,
) -> tuple[dict, bytes, str, list[dict]]:
    all_lines = ledger_bytes.splitlines(keepends=True)
    count = len(all_lines) if legacy_line_count is None else legacy_line_count
    lines = all_lines[:count]
    if (
        not lines
        or count > len(all_lines)
        or any(not line.endswith(b"\n") or not line[:-1].strip() for line in all_lines)
    ):
        _legacy_settlement_fail(
            "WI-LEDGER-LEGACY-PROFILE-UNSUPPORTED",
            "legacy ledger must contain bounded nonblank newline-terminated rows",
        )
    try:
        events = [
            _projection_object(line.rstrip(b"\r\n"), f"legacy ledger line {ordinal}")
            for ordinal, line in enumerate(lines, start=1)
        ]
    except LifecycleError as exc:
        if exc.failure_id == "WI-LEDGER-MIGRATION-MANIFEST-INVALID":
            raise LifecycleError(
                "WI-LEDGER-LEGACY-PROFILE-UNSUPPORTED",
                "legacy ledger contains a malformed row",
            ) from exc
        raise
    manifest_id = f"legacy-settlement-{_sha256_bytes(request_bytes)[:32]}"
    profile_id = request["profileId"]
    entry_id = profile_id
    entry = {
        "entryId": entry_id,
        "profileId": profile_id,
        "profileVersion": 1,
        "workItem": item.relative_to(root).as_posix(),
        "ledgerPath": (item / "agent-runs.jsonl").relative_to(root).as_posix(),
        "ledgerSha256": _sha256_bytes(ledger_bytes),
        "rawLineOrdinals": list(range(1, len(lines) + 1)),
        "rawLineSha256": [_sha256_bytes(line) for line in lines],
        "projectedEvents": events,
        "projectedEventSha256": [_sha256_bytes(_projection_json(event)) for event in events],
    }
    manifest = {
        "schemaVersion": 1,
        "manifestId": manifest_id,
        "profiles": [
            {"profileId": profile_id, "profileVersion": 1}
        ],
        "entries": [entry],
    }
    profile_errors: list[str] = []
    validator = _load_agent_run_ledger().load_validator()
    projected = validator._profile_projection(
        (profile_id, 1), events, item, entry, profile_errors
    )
    if projected is None or profile_errors:
        _raise_legacy_settlement_validation(profile_errors)
    return manifest, _projection_json(manifest), entry_id, events


def _legacy_settlement_projection_candidate(
    root: Path,
    manifest: dict,
    manifest_bytes: bytes,
    entry_id: str,
    request: dict,
    ledger_bytes: bytes,
) -> tuple[dict[str, bytes], bytes]:
    manifests_path, registry_path, _receipts = _projection_paths(root, input_role="repository-root")
    manifests = _projection_manifest_blobs(
        Path(root).resolve(), manifests_path, manifest["manifestId"], manifest_bytes
    )
    registry_before = registry_path.read_bytes() if registry_path.exists() else b""
    if registry_path.exists() and (
        not registry_path.is_file() or _lifecycle_path_has_reparse(registry_path)
    ):
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "projection registry is unsafe",
        )
    ordinals = manifest["entries"][0]["rawLineOrdinals"]
    records = [
        _projection_record(
            manifest,
            manifest_bytes,
            entry_id,
            ordinal,
            request["operationId"],
            index,
            len(ordinals),
            request["recordedAt"],
            Path(root).resolve(),
            candidate_ledger_bytes=ledger_bytes,
        )
        for index, ordinal in enumerate(ordinals, start=1)
    ]
    child_ids = _projection_group_ids(request["operationId"], len(records))
    existing_ids = {
        row.get("operationId")
        for row, _physical in _projection_registry_records(registry_before)
    }
    if any(child_id in existing_ids for child_id in child_ids):
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH",
            "settlement operation already has registry state without an exact replay receipt",
        )
    return manifests, registry_before + b"".join(
        _projection_json(record) + b"\n" for record in records
    )


def _raise_legacy_settlement_validation(errors: list[str]) -> None:
    if not errors:
        return
    preferred = next(
        (
            error for error in errors
            if error.startswith("WI-LEDGER-LEGACY-PROFILE-UNSUPPORTED:")
        ),
        errors[0],
    )
    failure_id = preferred.split(":", 1)[0]
    _legacy_settlement_fail(failure_id, "; ".join(errors))


def _legacy_settlement_target(root: Path, request_bytes: bytes) -> dict:
    root = Path(root).resolve()
    request = _legacy_settlement_request(request_bytes)
    _legacy_settlement_evidence(root, request)
    item = _work_items_root(root, input_role="repository-root") / "active" / request["workItem"]
    ledger = item / "agent-runs.jsonl"
    if not item.is_dir() or not ledger.is_file() or _lifecycle_path_has_reparse(ledger):
        _legacy_settlement_fail(
            "WI-LEDGER-MIGRATION-TARGET-IDENTITY",
            "settlement target is not one ordinary active work-item ledger",
        )
    ledger_bytes = ledger.read_bytes()
    if _sha256_bytes(ledger_bytes) != request["expectedLedgerSha256"]:
        _legacy_settlement_fail(
            "WI-LEDGER-MIGRATION-LEDGER-DRIFT",
            "settlement ledger digest changed",
        )
    manifest, manifest_bytes, entry_id, events = _legacy_settlement_manifest(
        root, item, ledger_bytes, request_bytes, request
    )
    return {
        "request": request,
        "item": item,
        "ledger": ledger,
        "ledgerBytes": ledger_bytes,
        "manifest": manifest,
        "manifestBytes": manifest_bytes,
        "entryId": entry_id,
        "events": events,
    }


def _preflight_legacy_ledger_settlement(
    root: Path, request_bytes: bytes
) -> tuple[dict, dict]:
    root = Path(root).resolve()
    plan = _legacy_settlement_target(root, request_bytes)
    request = plan["request"]
    item = plan["item"]
    ledger_bytes = plan["ledgerBytes"]
    manifest = plan["manifest"]
    manifest_bytes = plan["manifestBytes"]
    entry_id = plan["entryId"]
    events = plan["events"]
    manifests, registry_candidate = _legacy_settlement_projection_candidate(
        root, manifest, manifest_bytes, entry_id, request, ledger_bytes
    )
    validator = _load_agent_run_ledger().load_validator()
    obligations: list[object] = []
    errors = validator.validate_work_item(
        item,
        strict_revise=False,
        validate_status_file=False,
        projection_manifest_blobs=manifests,
        projection_registry_bytes=registry_candidate,
        obligation_state_out=obligations,
    )
    _raise_legacy_settlement_validation(errors)
    if len(obligations) != 1:
        _legacy_settlement_fail(
            "WI-LEDGER-LEGACY-SETTLEMENT-INCOMPLETE",
            "existing reducer did not return one obligation state",
        )
    obligation_state = obligations[0]
    open_rows = tuple(obligation_state.open_revise) + tuple(obligation_state.open_launches)
    open_ids = [row.run_id for row in open_rows]
    requested_ids = [row["targetRunId"] for row in request["settlements"]]
    if len(requested_ids) != len(set(requested_ids)) or set(requested_ids) != set(open_ids):
        _legacy_settlement_fail(
            "WI-LEDGER-LEGACY-SETTLEMENT-INCOMPLETE",
            "settlement rows must exactly cover reducer-reported obligations",
        )
    result = {
        "schemaVersion": 1,
        "operationId": request["operationId"],
        "profileId": request["profileId"],
        "profileVersion": request["profileVersion"],
        "applied": False,
        "replay": False,
        "legacyRunIds": [event["runId"] for event in events],
        "openObligations": open_ids,
        "ledgerBeforeSha256": _sha256_bytes(ledger_bytes),
    }
    return result, {
        **plan,
        "manifests": manifests,
        "registryCandidate": registry_candidate,
        "obligationRows": {row.run_id: row for row in open_rows},
    }


def _legacy_settlement_replay(root: Path, request_bytes: bytes) -> dict | None:
    root = Path(root).resolve()
    request = _legacy_settlement_request(request_bytes)
    _legacy_settlement_evidence(root, request)
    manifests_path, registry_path, receipts_path = _projection_paths(root, input_role="repository-root")
    receipt_path = receipts_path / f"{request['operationId']}.json"
    if not receipt_path.exists():
        return None
    if not receipt_path.is_file() or _lifecycle_path_has_reparse(receipt_path):
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH", "settlement receipt is unsafe"
        )
    receipt = _projection_object(receipt_path.read_bytes(), "legacy settlement receipt")
    item = _work_items_root(root, input_role="repository-root") / "active" / request["workItem"]
    ledger = item / "agent-runs.jsonl"
    manifest_path = manifests_path / receipt.get("manifestName", "")
    checks = (
        receipt.get("schemaVersion") == 1,
        receipt.get("status") == "settled",
        receipt.get("operationId") == request["operationId"],
        receipt.get("requestSha256") == _sha256_bytes(request_bytes),
        ledger.is_file(),
        isinstance(receipt.get("ledgerAfterSha256"), str),
        isinstance(receipt.get("ledgerBeforeByteLength"), int),
        registry_path.is_file(),
        manifest_path.is_file(),
    )
    if not all(checks):
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH",
            "settlement receipt identity differs from the replay request",
        )
    ledger_bytes = ledger.read_bytes()
    before_length = receipt["ledgerBeforeByteLength"]
    if (
        _sha256_bytes(ledger_bytes) != receipt["ledgerAfterSha256"]
        or _sha256_bytes(ledger_bytes[:before_length]) != receipt.get("ledgerBeforeSha256")
        or _sha256_bytes(registry_path.read_bytes()) != receipt.get("registryAfterSha256")
        or _sha256_bytes(manifest_path.read_bytes()) != receipt.get("manifestSha256")
    ):
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH",
            "settlement replay post-image differs from its receipt",
        )
    result = receipt.get("result")
    if not isinstance(result, dict):
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH",
            "settlement receipt result is unavailable",
        )
    return {**result, "applied": True, "replay": True}


def _legacy_settlement_events(plan: dict) -> list[dict]:
    request = plan["request"]
    result: list[dict] = []
    for settlement in request["settlements"]:
        if settlement["disposition"] == "preserve-open":
            continue
        target = plan["obligationRows"][settlement["targetRunId"]]
        evidence = [
            {
                "kind": "manual-check",
                "ref": f"{target.run_id} {target.raw_line_sha256} current-evidence",
            }
        ]
        evidence.extend(
            {
                "kind": "artifact",
                "ref": proof["path"],
                "result": proof["sha256"],
            }
            for proof in settlement["evidence"]
        )
        run_id = "legacy-settlement-" + _sha256_bytes(
            f"{request['operationId']}\0{target.run_id}".encode("utf-8")
        )[:32]
        result.append(
            {
                "schemaVersion": 2,
                "runId": run_id,
                "workItem": plan["item"].name,
                "role": "lead",
                "executionRole": "main",
                "status": "completed",
                "gate": "none",
                "scope": ["ledger-recovery:closure-invalidation"],
                "eventKind": "closure-invalidation",
                "invalidatesRunId": target.run_id,
                "invalidatesEventSha256": target.raw_line_sha256,
                "evidence": evidence,
                "startedAt": request["recordedAt"],
                "updatedAt": request["recordedAt"],
            }
        )
    return result


def _legacy_settlement_validate_after_image(
    root: Path,
    result: dict,
    plan: dict,
) -> tuple[bytes, dict, bytes, dict[str, bytes], bytes, list[dict]]:
    settlement_events = _legacy_settlement_events(plan)
    suffix = b"".join(_projection_json(event) + b"\n" for event in settlement_events)
    candidate_ledger = plan["ledgerBytes"] + suffix
    final_manifest, final_manifest_bytes, entry_id, _events = (
        _legacy_settlement_manifest(
            Path(root).resolve(),
            plan["item"],
            candidate_ledger,
            _projection_json(plan["request"]),
            plan["request"],
            legacy_line_count=len(result["legacyRunIds"]),
        )
    )
    manifests, registry_candidate = _legacy_settlement_projection_candidate(
        Path(root).resolve(),
        final_manifest,
        final_manifest_bytes,
        entry_id,
        plan["request"],
        candidate_ledger,
    )
    candidate_path = plan["ledger"].with_suffix(".jsonl.tmp")
    if candidate_path.exists() or _lifecycle_path_has_reparse(candidate_path):
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "settlement candidate path is not empty",
        )
    try:
        _atomic_write(candidate_path, candidate_ledger)
        validator = _load_agent_run_ledger().load_validator()
        obligations: list[object] = []
        errors = validator.validate_work_item(
            plan["item"],
            ledger_path=candidate_path,
            strict_revise=False,
            validate_status_file=False,
            projection_manifest_blobs=manifests,
            projection_registry_bytes=registry_candidate,
            obligation_state_out=obligations,
        )
        _raise_legacy_settlement_validation(errors)
        if len(obligations) != 1:
            _legacy_settlement_fail(
                "WI-LEDGER-LEGACY-SETTLEMENT-INCOMPLETE",
                "after-image reducer did not return one obligation state",
            )
        expected_open = [
            row["targetRunId"]
            for row in plan["request"]["settlements"]
            if row["disposition"] == "preserve-open"
        ]
        actual_open = [row.run_id for row in obligations[0].open_revise]
        actual_open.extend(row.run_id for row in obligations[0].open_launches)
        if set(actual_open) != set(expected_open) or len(actual_open) != len(expected_open):
            _legacy_settlement_fail(
                "WI-LEDGER-LEGACY-SETTLEMENT-INCOMPLETE",
                "after-image obligations differ from explicit dispositions",
            )
    finally:
        candidate_path.unlink(missing_ok=True)
    return (
        candidate_ledger,
        final_manifest,
        final_manifest_bytes,
        manifests,
        registry_candidate,
        settlement_events,
    )


def _restore_legacy_settlement_snapshot(
    snapshots: Mapping[Path, bytes | None], created_directories: tuple[Path, ...]
) -> None:
    for path, before in reversed(tuple(snapshots.items())):
        if before is None:
            if path.exists():
                if not path.is_file() or _lifecycle_path_has_reparse(path):
                    raise OSError(f"unsafe rollback target: {path}")
                path.unlink()
        else:
            _atomic_write(path, before)
    for directory in reversed(created_directories):
        if directory.exists() and not any(directory.iterdir()):
            directory.rmdir()


def _settle_legacy_ledger_locked(
    root: Path, request_bytes: bytes, *, inject_failure: str | None = None
) -> dict:
    if inject_failure not in {
        None, "after-manifest", "after-registry", "after-ledger", "after-receipt"
    }:
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "unknown settlement failure boundary",
        )
    replay = _legacy_settlement_replay(root, request_bytes)
    if replay is not None:
        return replay
    result, plan = _preflight_legacy_ledger_settlement(root, request_bytes)
    (
        candidate_ledger,
        final_manifest,
        final_manifest_bytes,
        _manifests,
        registry_candidate,
        settlement_events,
    ) = _legacy_settlement_validate_after_image(root, result, plan)
    manifests_path, registry_path, receipts_path = _projection_paths(root, input_role="repository-root")
    manifest_path = manifests_path / f"{final_manifest['manifestId']}.json"
    receipt_path = receipts_path / f"{plan['request']['operationId']}.json"
    participant_paths = (manifest_path, registry_path, plan["ledger"], receipt_path)
    snapshots = {
        path: path.read_bytes() if path.exists() and path.is_file() else None
        for path in participant_paths
    }
    created_directories = tuple(
        path for path in (manifests_path, receipts_path) if not path.exists()
    )
    final_result = {
        **result,
        "applied": True,
        "replay": False,
        "ledgerAfterSha256": _sha256_bytes(candidate_ledger),
        "settlementRunIds": [event["runId"] for event in settlement_events],
    }
    receipt = {
        "schemaVersion": 1,
        "status": "settled",
        "operationId": plan["request"]["operationId"],
        "recordedAt": plan["request"]["recordedAt"],
        "requestSha256": _sha256_bytes(request_bytes),
        "workItem": plan["item"].relative_to(Path(root).resolve()).as_posix(),
        "ledgerPath": plan["ledger"].relative_to(Path(root).resolve()).as_posix(),
        "ledgerBeforeSha256": _sha256_bytes(plan["ledgerBytes"]),
        "ledgerBeforeByteLength": len(plan["ledgerBytes"]),
        "ledgerAfterSha256": _sha256_bytes(candidate_ledger),
        "manifestName": manifest_path.name,
        "manifestSha256": _sha256_bytes(final_manifest_bytes),
        "registryBeforeSha256": _sha256_bytes(snapshots[registry_path] or b""),
        "registryAfterSha256": _sha256_bytes(registry_candidate),
        "settlements": plan["request"]["settlements"],
        "result": final_result,
    }
    receipt_bytes = _projection_json(receipt) + b"\n"
    try:
        _projection_create_or_exact(
            manifest_path,
            final_manifest_bytes,
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
        )
        if inject_failure == "after-manifest":
            raise OSError("injected failure after manifest")
        _atomic_write(registry_path, registry_candidate)
        if inject_failure == "after-registry":
            raise OSError("injected failure after registry")
        _atomic_write(plan["ledger"], candidate_ledger)
        if inject_failure == "after-ledger":
            raise OSError("injected failure after ledger")
        _projection_create_or_exact(
            receipt_path,
            receipt_bytes,
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH",
        )
        if inject_failure == "after-receipt":
            raise OSError("injected failure after receipt")
        if (
            plan["ledger"].read_bytes() != candidate_ledger
            or registry_path.read_bytes() != registry_candidate
            or manifest_path.read_bytes() != final_manifest_bytes
            or receipt_path.read_bytes() != receipt_bytes
        ):
            raise OSError("settlement participant readback differs")
    except BaseException as exc:
        try:
            _restore_legacy_settlement_snapshot(snapshots, created_directories)
        except BaseException as rollback_exc:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                f"settlement commit and rollback failed: {rollback_exc}",
            ) from exc
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "settlement commit failed; every participant restored to its exact preimage",
        ) from exc
    return final_result


_settle_legacy_ledger_transaction = _lifecycle_participant(
    _settle_legacy_ledger_locked, input_role="repository-root"
)


def _legacy_settlement_receipt_exists(root: Path, request_bytes: bytes) -> bool:
    request = _legacy_settlement_request(request_bytes)
    _manifests, _registry, receipts = _projection_paths(Path(root).resolve(), input_role="repository-root")
    return (receipts / f"{request['operationId']}.json").exists()


def settle_legacy_ledger(
    root: Path,
    request_bytes: bytes,
    *,
    apply_admitted: bool = False,
    inject_failure: str | None = None,
) -> dict:
    original_root = root
    request = _legacy_settlement_request(request_bytes)
    evidence = []
    root, _work_items = _resolve_project_root_identity(
        root, selected_reference=("work-item", request["workItem"]), binding_evidence_out=evidence,
    )
    if apply_admitted:
        if not _legacy_settlement_receipt_exists(root, request_bytes):
            _legacy_settlement_target(root, request_bytes)
        return _settle_legacy_ledger_transaction(
            root, request_bytes, inject_failure=inject_failure,
            _original_root=original_root, _binding_evidence=tuple(evidence),
        )
    if inject_failure is not None:
        _legacy_settlement_fail(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "failure injection is apply-only",
        )
    replay = _legacy_settlement_replay(root, request_bytes)
    if replay is not None:
        _verify_project_binding_evidence(tuple(evidence), "WI-LIFECYCLE-LOCK-IDENTITY")
        return replay
    result, _plan = _preflight_legacy_ledger_settlement(root, request_bytes)
    _verify_project_binding_evidence(tuple(evidence), "WI-LIFECYCLE-LOCK-IDENTITY")
    return result


def _mixed_recovery_fail(failure_id: str, message: str) -> None:
    raise LifecycleError(f"WI-MIXED-LEDGER-{failure_id}", message)


def _mixed_recovery_request(request_bytes: bytes) -> dict:
    if not isinstance(request_bytes, bytes) or len(request_bytes) > 1_000_000:
        _mixed_recovery_fail("REQUEST", "request is absent or exceeds the bounded size")

    def unique_object(pairs: list[tuple[str, object]]) -> dict:
        result: dict = {}
        for key, value in pairs:
            if key in result:
                raise ValueError(f"duplicate request key: {key}")
            result[key] = value
        return result

    try:
        request = json.loads(request_bytes.decode("utf-8"), object_pairs_hook=unique_object)
    except (UnicodeDecodeError, ValueError) as exc:
        _mixed_recovery_fail("REQUEST", f"request is not unique UTF-8 JSON: {exc}")
    if not isinstance(request, dict) or set(request) != {
        "schemaVersion", "operationId", "recordedAt", "workItem",
        "expectedLedgerSha256", "targets",
    } or type(request.get("schemaVersion")) is not int or request["schemaVersion"] not in {1, 2}:
        _mixed_recovery_fail("REQUEST", "request fields or version differ")
    operation_id = request.get("operationId")
    recorded_at = request.get("recordedAt")
    writer = _load_agent_run_ledger()
    try:
        writer._strict_migration_inputs(operation_id, recorded_at)
    except (writer.LedgerMigrationError, TypeError, ValueError) as exc:
        _mixed_recovery_fail("REQUEST", f"operation identity or UTC instant differs: {exc}")
    work_item = request.get("workItem")
    if not isinstance(work_item, str) or not re.fullmatch(
        r"work-items/active/[A-Za-z0-9][A-Za-z0-9._-]*", work_item, re.ASCII
    ):
        _mixed_recovery_fail("REQUEST", "workItem must name one active relative record")
    if not isinstance(request.get("expectedLedgerSha256"), str) or re.fullmatch(
        r"[0-9a-f]{64}", request["expectedLedgerSha256"], re.ASCII
    ) is None:
        _mixed_recovery_fail("REQUEST", "expectedLedgerSha256 must be lowercase SHA-256")
    targets = request.get("targets")
    if not isinstance(targets, list) or not targets or len(targets) > 10_000:
        _mixed_recovery_fail("REQUEST", "targets must be a bounded nonempty array")
    seen_ordinals: set[int] = set()
    seen_run_ids: set[str] = set()
    for target in targets:
        if not isinstance(target, dict):
            _mixed_recovery_fail("REQUEST", "target is not an object")
        action = target.get("action")
        if request["schemaVersion"] == 2 and action in {"custody-invalid-history", "dispose-history-custody"}:
            wanted = {"action", "sourcePrefixSha256", "sourcePrefixBytes", "rawLineOrdinal", "physicalLineSha256"}
            if action == "dispose-history-custody":
                wanted |= {"kind", "classificationRunId", "resolutionRunIds", "evidence"}
            if set(target) != wanted:
                _mixed_recovery_fail("REQUEST", "history target fields differ")
            ordinal = target.get("rawLineOrdinal")
            if type(ordinal) is not int or ordinal < 1 or ordinal in seen_ordinals:
                _mixed_recovery_fail("REQUEST", "history target ordinal is invalid or repeated")
            for key in ("sourcePrefixSha256", "physicalLineSha256"):
                if not isinstance(target.get(key), str) or re.fullmatch(r"[0-9a-f]{64}", target[key], re.ASCII) is None:
                    _mixed_recovery_fail("REQUEST", "history target digest differs")
            if type(target.get("sourcePrefixBytes")) is not int or target["sourcePrefixBytes"] < 1:
                _mixed_recovery_fail("REQUEST", "history source prefix size differs")
            seen_ordinals.add(ordinal)
            continue
        if request["schemaVersion"] == 2:
            _mixed_recovery_fail("REQUEST", "Version 2 requires a historical custody/disposition target")
        digest_field = {
            "migrate-invalid-finding-class": "eventBodySha256",
            "dispose-invalid-terminal": "physicalLineSha256",
        }.get(action)
        if digest_field is None or set(target) != {
            "action", "rawLineOrdinal", "runId", digest_field, "launchRunId",
        }:
            _mixed_recovery_fail("REQUEST", "target action or digest codec differs")
        ordinal = target.get("rawLineOrdinal")
        run_id = target.get("runId")
        launch_id = target.get("launchRunId")
        digest = target.get(digest_field)
        if (
            type(ordinal) is not int or ordinal < 1 or ordinal in seen_ordinals
            or not isinstance(run_id, str) or not run_id
            or run_id.casefold() in seen_run_ids
            or not isinstance(launch_id, str) or not launch_id
            or not isinstance(digest, str)
            or re.fullmatch(r"[0-9a-f]{64}", digest, re.ASCII) is None
        ):
            _mixed_recovery_fail("REQUEST", "target identity is invalid or repeated")
        seen_ordinals.add(ordinal)
        seen_run_ids.add(run_id.casefold())
    return request


def _mixed_recovery_controls(
    item: Path, original: bytes, request: dict, writer: object, validator: object,
) -> tuple[list[dict], list[dict], list[dict]]:
    """Classify each physical row once and build only existing typed controls."""

    ledger = item / "agent-runs.jsonl"
    physical = original.splitlines(keepends=True)
    if not original.endswith(b"\n") or any(not line.strip() for line in physical):
        _mixed_recovery_fail("HISTORY", "mixed recovery requires complete nonblank physical lines")
    parse_errors: list[str] = []
    metadata: list[dict[str, object]] = []
    events = validator.load_jsonl(ledger, parse_errors, metadata, original)
    if parse_errors or len(events) != len(physical) or len(metadata) != len(events):
        _mixed_recovery_fail("HISTORY", "; ".join(parse_errors) or "physical row cardinality differs")
    if any(event.get("schemaVersion") not in (1, 2) for event in events):
        _mixed_recovery_fail("HISTORY", "history is not an integer V1/V2 ledger")
    if request["schemaVersion"] == 2:
        controls, facts = [], []
        for target in sorted(request["targets"], key=lambda row: row["rawLineOrdinal"]):
            ordinal = target["rawLineOrdinal"]
            if ordinal > len(events):
                _mixed_recovery_fail("TARGET", "history target ordinal is outside captured history")
            control = {
                "schemaVersion": 2, "runId": f"mixed-recovery-{request['operationId']}-{ordinal}",
                "workItem": item.name, "role": "lead", "executionRole": "main",
                "status": "completed", "gate": "none", "startedAt": request["recordedAt"],
                "updatedAt": request["recordedAt"], "scope": ["ledger-recovery:historical-custody"],
                "eventKind": "closure-invalidation", "invalidationMode": "historical-custody",
                "custodyAction": "admit" if target["action"] == "custody-invalid-history" else "dispose", "authorizing": False,
                **{key: target[key] for key in ("sourcePrefixSha256", "sourcePrefixBytes", "rawLineOrdinal", "physicalLineSha256")},
                "evidence": [{"kind": "manual-check", "ref":
                    f"custody physical row {ordinal} {target['sourcePrefixSha256']} {target['physicalLineSha256']}"}],
            }
            if target["action"] == "dispose-history-custody":
                control["historyDisposition"] = {key: target[key] for key in
                                                  ("kind", "classificationRunId", "resolutionRunIds", "evidence")}
                control["evidence"] = target["evidence"]
            controls.append(control)
            facts.append({**target, "beforeEvent": events[ordinal - 1],
                          "afterEffectiveEvent": events[ordinal - 1],
                          "disposed": target["action"] == "dispose-history-custody"})
        return events, controls, facts
    by_target = {target["rawLineOrdinal"]: target for target in request["targets"]}
    by_run: dict[str, list[int]] = {}
    for position, event in enumerate(events):
        run_id = event.get("runId")
        if isinstance(run_id, str):
            by_run.setdefault(run_id.casefold(), []).append(position)
    run_positions = {key: tuple(value) for key, value in by_run.items()}
    seen: set[str] = set()
    invalid_ordinals: set[int] = set()
    for ordinal, event in enumerate(events, start=1):
        row_errors: list[str] = []
        validator.validate_event(event, item, seen, row_errors)
        orphan = bool(
            event.get("schemaVersion") == 2
            and event.get("eventKind") == "terminal"
            and event.get("status") == "completed"
            and not validator.terminal_has_valid_earlier_launch(
                events, ordinal - 1, item, run_positions
            )
        )
        if row_errors or orphan:
            invalid_ordinals.add(ordinal)
        if ordinal in by_target:
            target = by_target[ordinal]
            if (
                event.get("schemaVersion") != 2
                or event.get("eventKind") != "terminal"
                or event.get("runId") != target["runId"]
                or event.get("launchRunId") != target["launchRunId"]
                or any(field in event for field in (
                    "migrationAction", "migratesRunId", "invalidationMode",
                ))
            ):
                _mixed_recovery_fail("TARGET", f"target row {ordinal} is not an exact V2 terminal")
            digest_field = (
                "eventBodySha256" if target["action"] == "migrate-invalid-finding-class"
                else "physicalLineSha256"
            )
            actual_digest = (
                metadata[ordinal - 1]["sha256"] if digest_field == "eventBodySha256"
                else _sha256_bytes(physical[ordinal - 1])
            )
            if target[digest_field] != actual_digest:
                _mixed_recovery_fail("TARGET", f"target row {ordinal} {digest_field} differs")
            if not row_errors and not orphan:
                _mixed_recovery_fail("TARGET", f"target row {ordinal} has no invalid current relation")
    if invalid_ordinals != set(by_target):
        _mixed_recovery_fail("COVERAGE", "explicit targets do not cover exactly every invalid row")

    controls: list[dict] = []
    target_facts: list[dict] = []
    for target in sorted(request["targets"], key=lambda row: row["rawLineOrdinal"]):
        ordinal = target["rawLineOrdinal"]
        event = events[ordinal - 1]
        digest = target.get("eventBodySha256", target.get("physicalLineSha256"))
        common = {
            "schemaVersion": 2,
            "runId": f"mixed-recovery-{request['operationId']}-{ordinal}",
            "workItem": item.name,
            "role": "lead", "executionRole": "main", "status": "completed",
            "gate": "none", "startedAt": request["recordedAt"],
            "updatedAt": request["recordedAt"],
        }
        if target["action"] == "migrate-invalid-finding-class":
            replacement = {**event, "findingClass": "legacy-unclassified"}
            controls.append({
                **common,
                "scope": ["ledger-migration:invalid-finding-class"],
                "eventKind": "legacy-obligation-migration",
                "migrationAction": "apply", "normalizationKind": "invalid-finding-class",
                "migratesRunId": event["runId"],
                "migratesEventSha256": digest,
                "replacementEvent": replacement,
                "evidence": [{"kind": "manual-check", "ref":
                    f"invalid-finding-class {event['runId']} {digest} -> legacy-unclassified"}],
            })
            effective = replacement
        else:
            controls.append({
                **common,
                "scope": ["ledger-recovery:invalid-current-nonauthorizing"],
                "eventKind": "closure-invalidation",
                "invalidationMode": "invalid-current-nonauthorizing",
                "invalidatesRawLineOrdinal": ordinal,
                "invalidatesRunId": event["runId"],
                "invalidatesEventSha256": digest,
                "authorizing": False,
                "evidence": [{"kind": "manual-check", "ref":
                    f"approved exact target {event['runId']} {digest}"}],
            })
            effective = event
        target_facts.append({**target, "beforeEvent": event,
                             "afterEffectiveEvent": effective,
                             "disposed": target["action"] == "dispose-invalid-terminal"})
    return events, controls, target_facts


def _historical_pass_association(
    prefix: bytes, event: dict, ordinal: int, raw_line_sha256: str, artifact_sha256: str,
) -> dict:
    return {
        "kind": "historical-pass-custody", "sourcePrefixSha256": _sha256_bytes(prefix),
        "sourcePrefixBytes": len(prefix), "rawLineOrdinal": ordinal,
        "rawLineSha256": raw_line_sha256, "runId": event["runId"],
        "originalArtifact": event["artifact"], "snapshot": f"review-artifact-custody/{artifact_sha256}",
        "snapshotSha256": artifact_sha256,
    }


def _mixed_capture_history_evidence(
    root: Path, item: Path, original: bytes, events: list[dict], controls: list[dict], writer: object, validator: object,
) -> dict[str, bytes]:
    """Capture accepted proof bytes once; no preview publication or mutable re-read."""
    blobs: dict[str, bytes] = {}
    physical = original.splitlines(keepends=True)
    for control in controls:
        proof = control.get("historyDisposition")
        if proof is None:
            continue
        target = {**proof, **{key: control[key] for key in validator.HISTORY_SUBJECT_FIELDS}}
        try:
            packet = validator.history_disposition_packet(events, target, item)
        except ValueError as exc:
            _mixed_recovery_fail("EVIDENCE", str(exc))
        proof["boundEvents"] = packet["bindings"]
        for descriptor in packet["descriptors"]:
            digest = descriptor["sha256"]
            key = f"review-artifact-custody/{digest}"
            if key in blobs:
                continue
            snapshot = item / key
            if snapshot.exists() or snapshot.is_symlink():
                if not validator._ordinary_custody_snapshot(item, key, digest):
                    _mixed_recovery_fail("EVIDENCE", "retained snapshot differs")
                data = _capture_file_snapshot(snapshot, failure_id="WI-MIXED-LEDGER-EVIDENCE",
                                              maximum_bytes=validator.MAX_LEDGER_LINE_BYTES).data
            else:
                reference = descriptor["ref"]
                source = item / reference
                if not source.exists() and not source.is_symlink():
                    source = root / reference
                source = _require_lifecycle_mutation_path(root, source, failure_id="WI-MIXED-LEDGER-EVIDENCE")
                data = _capture_file_snapshot(source, failure_id="WI-MIXED-LEDGER-EVIDENCE",
                                              maximum_bytes=validator.MAX_LEDGER_LINE_BYTES).data
            if _sha256_bytes(data) != digest:
                _mixed_recovery_fail("EVIDENCE", "captured accepted report/contract digest differs")
            blobs[key] = data
        for (position, record), payload in zip(packet["records"], packet["payloads"]):
            raw_line_sha = _sha256_bytes(physical[position].rstrip(b"\r\n"))
            association = _historical_pass_association(original, record, position + 1, raw_line_sha, payload["report"]["sha256"])
            key = f"review-artifact-custody/historical-pass/{raw_line_sha}.json"
            if (item / key).exists():
                # Existing exact association owns its original prefix, not this later operation's prefix.
                existing = _capture_file_snapshot(item / key, failure_id="WI-MIXED-LEDGER-EVIDENCE").data
                try:
                    decoded = validator.decode_json_object(existing, source=key)
                except ValueError as exc:
                    _mixed_recovery_fail("EVIDENCE", str(exc))
                if any(decoded.get(field) != association[field] for field in
                       ("rawLineOrdinal", "rawLineSha256", "runId", "originalArtifact", "snapshot", "snapshotSha256")):
                    _mixed_recovery_fail("EVIDENCE", "retained raw PASS association conflicts")
                blobs[key] = existing
            else:
                blobs[key] = validator._canonical_projection_bytes(association)
    return blobs


def recover_mixed_current_ledger(
    root: Path, request_bytes: bytes, *, apply_admitted: bool = False,
    inject_failure: str | None = None,
) -> dict:
    """Lifecycle-owned exact-prefix mixed V1/V2 repair; no-apply is the default."""

    request = _mixed_recovery_request(request_bytes)
    if inject_failure not in {None, "post-history-publish", "crash-post-history"}:
        _mixed_recovery_fail("REQUEST", "unsupported injection boundary")
    if inject_failure is not None and not apply_admitted:
        _mixed_recovery_fail("REQUEST", "failure injection is apply-only")
    slug = request["workItem"].split("/")[-1]
    evidence = []
    root, _work_items = _resolve_project_root_identity(
        root, selected_reference=("work-item", slug), binding_evidence_out=evidence,
    )
    item = _active_migration_item(root, slug, input_role="repository-root")
    ledger = _require_lifecycle_mutation_path(
        root, item / "agent-runs.jsonl", failure_id="WI-MIXED-LEDGER-DRIFT"
    )
    writer = _load_agent_run_ledger()
    validator = writer.load_validator()
    before_sha = request["expectedLedgerSha256"]
    request_sha = _sha256_bytes(request_bytes)
    history_path = item / f"agent-runs.history.{before_sha}.jsonl"
    receipt_path = item / f"agent-runs.mixed.{request['operationId']}.receipt.json"
    stage_path = ledger.with_suffix(".jsonl.tmp")
    try:
        with writer.ledger_write_lock(item):
            _verify_project_binding_evidence(tuple(evidence), "WI-LIFECYCLE-LOCK-IDENTITY")
            current = writer._noncanonical_read_owned_bytes(ledger, failure_id="DRIFT")
            current_is_original = _sha256_bytes(current) == before_sha
            history = writer._read_exact_history_blob(history_path, before_sha)
            if current_is_original:
                original = current
                if history is not None and history != original:
                    _mixed_recovery_fail("HISTORY", "pre-existing history differs")
            else:
                if history is None:
                    _mixed_recovery_fail("DRIFT", "changed ledger has no exact history blob")
                original = history
            events, controls, target_facts = _mixed_recovery_controls(
                item, original, request, writer, validator
            )
            evidence_blobs = _mixed_capture_history_evidence(root, item, original, events, controls, writer, validator)
            for fact, control in zip(target_facts, controls):
                if "historyDisposition" in control:
                    fact["historyDisposition"] = control["historyDisposition"]
            suffix = b"".join(
                (writer.serialize_event(event) + "\n").encode("utf-8")
                for event in controls
            )
            candidate = original + suffix
            replay = not current_is_original
            if replay and not (current == candidate or (request["schemaVersion"] == 2 and current.startswith(candidate))):
                _mixed_recovery_fail("DRIFT", "ledger is not the exact committed suffix")
            if receipt_path.exists() and not replay:
                _mixed_recovery_fail("RECEIPT", "receipt exists without committed ledger")
            stage_preexisting = stage_path.exists()
            validation_candidate = candidate
            stage_identity = writer._write_exact_staging_file(stage_path, validation_candidate)
            obligations: list = []
            authority: list = []
            validation_errors = validator.validate_work_item(
                item, ledger_path=stage_path, strict_revise=False,
                validate_status_file=False, obligation_state_out=obligations,
                authority_state_out=authority,
                historical_pass_custody_blobs=evidence_blobs or None,
            )
            if validation_errors or len(obligations) != 1 or len(authority) != 1:
                if not stage_preexisting and not writer.remove_exact_mixed_owned_file(
                    stage_path, candidate, stage_identity
                ):
                    _mixed_recovery_fail("RESIDUE", "invalid candidate and changed owned staging")
                _mixed_recovery_fail("CANDIDATE", "; ".join(validation_errors) or "candidate reduction incomplete")
            open_revise = [row.run_id for row in obligations[0].open_revise]
            open_launches = [row.run_id for row in obligations[0].open_launches]
            before_axes = {}
            if request["schemaVersion"] == 2:
                before_context = validator._ordinary_raw_v2_effective_context(item, str(ledger), original, evidence_blobs or None)
                before_errors: list[str] = []
                _active, before_validity, before_revise, before_launches = validator._reduce_effective_current_state(
                    before_context.rows, item, before_errors, None, context=before_context
                )
                before_axes = {row.raw_line_ordinal: entry.authority
                               for row, entry in zip(before_context.rows, before_validity)}
                raw_revise = {row["runId"] for row in before_revise}
                raw_launches = {row["runId"] for row in before_launches}
            else:
                raw_revise = {str(event["runId"]) for event in events if event.get("schemaVersion") == 2 and event.get("gate") == "REVISE"}
                raw_launches = {str(event["runId"]) for event in events if event.get("eventKind") == "launch"}
            closed_revise = {
                str(closed)
                for ordinal, event in enumerate(events, start=1)
                if authority[0].get(ordinal, validator._NO_LEDGER_AUTHORITY).closer_eligible
                for closed in event.get("closesRunIds", ())
            }
            settled_launches = {
                str(event["launchRunId"])
                for ordinal, event in enumerate(events, start=1)
                if authority[0].get(ordinal, validator._NO_LEDGER_AUTHORITY).terminal_eligible
                and isinstance(event.get("launchRunId"), str)
            }
            if (
                raw_revise != (set(open_revise) | (raw_revise & closed_revise))
                or raw_launches != (set(open_launches) | (raw_launches & settled_launches))
            ):
                if not stage_preexisting and not writer.remove_exact_mixed_owned_file(stage_path, candidate, stage_identity):
                    _mixed_recovery_fail("RESIDUE", "obligation mismatch and changed owned staging")
                _mixed_recovery_fail("OBLIGATION", "raw review or launch identity was not conserved")
            axis_names = (
                "launchEligible", "terminalEligible", "reviseTargetEligible",
                "closerEligible", "artifactEvidenceEligible",
            )
            for fact in target_facts:
                mask = authority[0].get(fact["rawLineOrdinal"], validator._NO_LEDGER_AUTHORITY)
                fact["beforeAuthority"] = dict.fromkeys(axis_names, False)
                if request["schemaVersion"] == 2:
                    prior = before_axes.get(fact["rawLineOrdinal"], validator._NO_LEDGER_AUTHORITY)
                    fact["beforeAuthority"] = dict(zip(axis_names, (
                        prior.launch_eligible, prior.terminal_eligible, prior.revise_target_eligible,
                        prior.closer_eligible, prior.artifact_evidence_eligible,
                    )))
                    if mask != prior:
                        if not stage_preexisting:
                            writer.remove_exact_mixed_owned_file(stage_path, validation_candidate, stage_identity)
                        _mixed_recovery_fail("AUTHORITY", "independent preimage authority was not conserved")
                fact["afterAuthority"] = dict(zip(axis_names, (
                    mask.launch_eligible, mask.terminal_eligible,
                    mask.revise_target_eligible, mask.closer_eligible,
                    mask.artifact_evidence_eligible,
                )))
            result = {
                "applied": False, "replay": replay,
                "operationId": request["operationId"],
                "ledgerBeforeSha256": before_sha,
                "ledgerAfterSha256": _sha256_bytes(candidate),
                "historyPath": history_path.name,
                "targets": target_facts,
                "openReviseRunIds": open_revise,
                "openLaunchRunIds": open_launches,
                "settledReviseRunIds": sorted(raw_revise & closed_revise),
                "settledLaunchRunIds": sorted(raw_launches & settled_launches),
            }
            receipt = {
                "schemaVersion": request["schemaVersion"], "operationId": request["operationId"],
                "recordedAt": request["recordedAt"],
                "requestSha256": request_sha,
                "ledgerBeforeSha256": before_sha,
                "ledgerBeforeByteLength": len(original),
                "historyPath": history_path.name,
                "historySha256": before_sha,
                "ledgerAfterSha256": _sha256_bytes(candidate),
                "ledgerAfterByteLength": len(candidate),
                "targets": target_facts,
                "openReviseRunIds": open_revise,
                "openLaunchRunIds": open_launches,
                "settledReviseRunIds": result["settledReviseRunIds"],
                "settledLaunchRunIds": result["settledLaunchRunIds"],
            }
            receipt_bytes = json.dumps(receipt, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8") + b"\n"
            if request["schemaVersion"] == 2:
                for output in (result, receipt):
                    output["unresolvedHistory"] = [{
                        "sourcePrefixSha256": hold.source_prefix_sha256, "sourcePrefixBytes": hold.source_prefix_bytes,
                        "rawLineOrdinal": hold.raw_line_ordinal, "physicalLineSha256": hold.raw_line_sha256,
                        "admissionRunId": hold.admission_run_id,
                    } for hold in obligations[0].unresolved_history]
                receipt_bytes = json.dumps(receipt, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8") + b"\n"
            if replay:
                if history != original or not current.startswith(candidate):
                    _mixed_recovery_fail("REPLAY", "history or committed suffix differs")
                if current != candidate:
                    later_errors = validator.validate_work_item(
                        item, selected_ledger_bytes=current, strict_revise=False, validate_status_file=False
                    )
                    if later_errors:
                        if not stage_preexisting:
                            writer.remove_exact_mixed_owned_file(stage_path, candidate, stage_identity)
                        _mixed_recovery_fail("REPLAY", "later suffix is invalid: " + "; ".join(later_errors))
                if apply_admitted:
                    _projection_create_or_exact(receipt_path, receipt_bytes, "WI-MIXED-LEDGER-RECEIPT")
                if not stage_preexisting and not writer.remove_exact_mixed_owned_file(stage_path, validation_candidate, stage_identity):
                    _mixed_recovery_fail("RESIDUE", "replay owned staging changed")
                if not apply_admitted:
                    _verify_project_binding_evidence(tuple(evidence), "WI-LIFECYCLE-LOCK-IDENTITY")
                return {**result, "applied": apply_admitted, "replay": True}
            if not apply_admitted:
                if not stage_preexisting and not writer.remove_exact_mixed_owned_file(stage_path, candidate, stage_identity):
                    _mixed_recovery_fail("RESIDUE", "no-apply owned staging changed")
                _verify_project_binding_evidence(tuple(evidence), "WI-LIFECYCLE-LOCK-IDENTITY")
                return result
            history_created = False
            history_identity = None
            replaced = False
            owned_evidence: list[tuple[Path, bytes, tuple[int, int, int, int]]] = []
            evidence_directories: list[Path] = []
            try:
                for directory in (item / "review-artifact-custody", item / "review-artifact-custody" / "historical-pass"):
                    if evidence_blobs and not directory.exists():
                        directory.mkdir()
                        evidence_directories.append(directory)
                for key, data in evidence_blobs.items():
                    path = item / key
                    if "/historical-pass/" in key:
                        created: list[tuple[int, int, int, int]] = []
                        try:
                            _projection_create_or_exact(path, data, "WI-MIXED-LEDGER-EVIDENCE", created_identities=created)
                        finally:
                            if created:
                                owned_evidence.append((path, data, created[0]))
                    else:
                        owned: dict[str, Path] = {}
                        identities: dict[str, tuple[int, int]] = {}
                        try:
                            writer._acquire_custody_snapshot(item, data, path.name, validator, owned, owned_identities=identities)
                        finally:
                            if "snapshot" in owned:
                                info = owned["snapshot"].lstat()
                                if (info.st_dev, info.st_ino) != identities["snapshot"]:
                                    _mixed_recovery_fail("RESIDUE", "new proof snapshot creator identity changed")
                                owned_evidence.append((owned["snapshot"], data, writer._noncanonical_file_identity(info)))
                if evidence_blobs:
                    final_errors = validator.validate_work_item(item, ledger_path=stage_path, strict_revise=False,
                                                               validate_status_file=False)
                    if final_errors:
                        _mixed_recovery_fail("CANDIDATE", "; ".join(final_errors))
                published_path, history_created, history_identity = writer.publish_mixed_current_history_blob(
                    item, before_sha, original
                )
                if published_path != history_path:
                    _mixed_recovery_fail("HISTORY", "history path changed")
                if inject_failure == "crash-post-history":
                    raise KeyboardInterrupt("injected abrupt history interruption")
                if inject_failure == "post-history-publish":
                    _mixed_recovery_fail("INJECTED", "injected handled pre-append failure")
                writer._replace_exact_staging_file(stage_path, ledger, candidate, stage_identity)
                replaced = True
                if writer._noncanonical_read_owned_bytes(ledger, failure_id="READBACK-INDETERMINATE") != candidate:
                    _mixed_recovery_fail("READBACK", "committed suffix readback differs")
                _projection_create_or_exact(receipt_path, receipt_bytes, "WI-MIXED-LEDGER-RECEIPT")
                if receipt_path.read_bytes() != receipt_bytes:
                    _mixed_recovery_fail("RECEIPT", "receipt readback differs")
                return {**result, "applied": True, "replay": False}
            except Exception as exc:
                if replaced:
                    _mixed_recovery_fail("COMMIT-INDETERMINATE", f"ledger changed; exact replay required: {exc}")
                try:
                    observed = writer._noncanonical_read_owned_bytes(
                        ledger, failure_id="READBACK-INDETERMINATE"
                    )
                except writer.LedgerNoncanonicalRecoveryError:
                    _mixed_recovery_fail("COMMIT-INDETERMINATE", "ledger cannot be read; preserve history for exact replay")
                if observed != original:
                    _mixed_recovery_fail("COMMIT-INDETERMINATE", "ledger may have changed; preserve history for exact replay")
                clean = True
                if not stage_preexisting:
                    clean = writer.remove_exact_mixed_owned_file(stage_path, candidate, stage_identity) and clean
                if not clean:
                    _mixed_recovery_fail("RESIDUE", "handled failure left changed or ambiguous owned staging")
                if history_created and history_identity is not None:
                    clean = writer.remove_exact_mixed_owned_file(history_path, original, history_identity) and clean
                for path, data, identity in reversed(owned_evidence):
                    clean = writer.remove_exact_mixed_owned_file(path, data, identity) and clean
                for directory in reversed(evidence_directories):
                    if directory.exists() and not any(directory.iterdir()):
                        directory.rmdir()
                    else:
                        clean = False
                if not clean:
                    _mixed_recovery_fail("RESIDUE", "handled failure left changed or ambiguous owned residue")
                if isinstance(exc, LifecycleError):
                    raise
                _mixed_recovery_fail("COMMIT", f"pre-append publication failed: {exc}")
    except (writer.LedgerNoncanonicalRecoveryError, writer.LedgerWriteLockError) as exc:
        _mixed_recovery_fail("WRITER", str(exc))


def _projection_active_records(records: list[tuple[dict, bytes]]) -> dict[str, tuple[dict, bytes]]:
    """Reduce exact apply/revoke lines without granting the registry new authority."""
    active: dict[str, tuple[dict, bytes]] = {}
    for record, physical in records:
        operation = record.get("operationId")
        if not isinstance(operation, str):
            _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "registry operation id is invalid")
        if record.get("state") == "apply":
            if operation in active:
                _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "registry apply operation id is duplicated")
            active[operation] = (record, physical)
        elif record.get("state") == "revoke":
            target = record.get("revokeOfOperationId")
            if not isinstance(target, str) or target not in active:
                _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "registry revoke lacks one earlier active apply")
            if record.get("revokeOfRecordSha256") != _sha256_bytes(active[target][1]):
                _projection_fail("WI-LEDGER-MIGRATION-TARGET-DIGEST", "registry revoke does not bind exact apply bytes")
            active.pop(target)
        else:
            _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "registry state is not apply or revoke")
    return active


def _projection_digest_list(value: object, expected_count: int) -> list[str]:
    values = [value] if isinstance(value, str) else value
    if (
        not isinstance(values, list)
        or len(values) != expected_count
        or any(not isinstance(digest, str) or re.fullmatch(r"[0-9a-f]{64}", digest) is None for digest in values)
    ):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-DIGEST", "revoke must bind every exact apply record digest")
    return values


def _projection_cli_record_digests(value: str) -> str | list[str]:
    """Accept the scalar legacy form or one JSON array for an atomic row group."""
    if not value.startswith("["):
        return value
    try:
        parsed = json.loads(value)
    except json.JSONDecodeError:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-DIGEST", "record digest group is not valid JSON")
    if not isinstance(parsed, list):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-DIGEST", "record digest group is not an array")
    return parsed


def _revoke_legacy_ledger_projection_locked(root: Path, apply_operation_id: str, apply_record_sha256: str | list[str], expected_registry_sha256: str, operation_id: str, recorded_at: str) -> dict:
    _projection_operation(operation_id, recorded_at)
    manifests_path, registry_path, receipts = _projection_paths(root)
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
    )
    if _lifecycle_path_has_reparse(repository / "work-items"):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "projection writer requires one ordinary repository root")
    if not registry_path.is_file() or _lifecycle_path_has_reparse(registry_path):
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "projection registry is unavailable")
    before = registry_path.read_bytes()
    records = _projection_registry_records(before)
    matching = [
        (index, record, physical) for index, (record, physical) in enumerate(records)
        if record.get("operationGroupId", record.get("operationId")) == apply_operation_id
    ]
    if matching:
        target_index, target_record, _physical = matching[0]
    else:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "revoke target apply operation is unavailable")
    if target_record.get("state") != "apply":
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "revoke target is not an apply record")
    validator = _load_agent_run_ledger().load_validator()
    try:
        manifest_id = validator.confine_legacy_projection_identifier(
            target_record.get("manifestId"), failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID"
        )
        manifest_path = validator.confine_legacy_projection_path(
            repository, f"work-items/{LEGACY_PROJECTION_MANIFEST_DIR}/{manifest_id}.json",
            prefix=("work-items", LEGACY_PROJECTION_MANIFEST_DIR), leaf_kind="file",
            failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID",
        )
    except ValueError as exc:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", f"target manifest is unsafe: {exc}")
        raise AssertionError from exc
    manifest_bytes = manifest_path.read_bytes()
    manifest = _projection_object(manifest_bytes, "target manifest")
    entry = _projection_entry(manifest, target_record["manifestEntryId"], target_record["rawLineOrdinal"], repository)
    child_ids = _projection_group_ids(apply_operation_id, len(entry["rawLineOrdinals"]))
    apply_lines: list[bytes] = []
    apply_records: list[dict] = []
    apply_indices: list[int] = []
    for child_id, raw_ordinal in zip(child_ids, entry["rawLineOrdinals"]):
        matches = [(index, record, physical) for index, (record, physical) in enumerate(records) if record.get("operationId") == child_id]
        if len(matches) != 1 or matches[0][1].get("state") != "apply" or matches[0][1].get("rawLineOrdinal") != raw_ordinal:
            _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "revoke target apply group is partial or differs")
        apply_indices.append(matches[0][0])
        apply_lines.append(matches[0][2])
        apply_records.append(matches[0][1])
    if apply_indices != list(range(apply_indices[0], apply_indices[0] + len(apply_indices))):
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "revoke target apply group is non-contiguous")
    supplied_digests = _projection_digest_list(apply_record_sha256, len(apply_lines))
    if supplied_digests != [_sha256_bytes(line) for line in apply_lines]:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-DIGEST", "revoke target does not bind exact apply group bytes")
    revoke_ids = _projection_group_ids(operation_id, len(child_ids))
    revokes = []
    for member_index, (revoke_id, apply_id, apply_line, apply_record) in enumerate(zip(revoke_ids, child_ids, apply_lines, apply_records), start=1):
        revokes.append({
            **{key: apply_record[key] for key in ("schemaVersion", "profileId", "profileVersion", "manifestId", "manifestSha256", "manifestEntryId", "workItem", "ledgerPath", "ledgerSha256", "rawLineOrdinal", "rawLineSha256", "projectedEvent", "projectedEventSha256")},
            "operationGroupId": operation_id, "groupMemberIndex": member_index, "groupMemberCount": len(revoke_ids),
            "operationId": revoke_id, "state": "revoke", "recordedAt": recorded_at,
            "revokeOfOperationId": apply_id, "revokeOfOperationGroupId": apply_operation_id, "revokeOfRecordSha256": _sha256_bytes(apply_line),
        })
    revoke_lines = [_projection_json(record) + b"\n" for record in revokes]
    persisted = _projection_existing_group(records, revoke_ids, revoke_lines)
    if persisted is not None:
        persisted_before, persisted_after = persisted
        _projection_require_replay_anchor(expected_registry_sha256, persisted_before, before)
        facts = _projection_group_facts(operation_id, revoke_lines, persisted_before, persisted_after)
        _projection_reconcile_receipt(receipts, facts)
        return {**facts, "replay": True}
    active = _projection_active_records(records)
    if any(child_id not in active for child_id in child_ids):
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "apply group is already revoked or partially active")
    for later, _physical in records[apply_indices[-1] + 1:]:
        if (
            later.get("manifestId") == target_record["manifestId"]
            and later.get("manifestEntryId") == target_record["manifestEntryId"]
            and later.get("state") in {"apply", "revoke"}
        ):
            _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "revoke is blocked by a later dependent entry operation")
    existing_ids = {record.get("operationId") for record, _physical in records}
    if any(revoke_id in existing_ids for revoke_id in revoke_ids):
        _projection_fail("WI-LEDGER-MIGRATION-TOPOLOGY", "revoke operation group is partial")
    if _sha256_bytes(before) != expected_registry_sha256:
        _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "projection registry digest changed")
    candidate = before + b"".join(revoke_lines)
    manifests = _projection_manifest_blobs(repository, manifests_path, manifest["manifestId"], manifest_bytes)
    baseline = b"".join(physical for index, (_record, physical) in enumerate(records) if index not in set(apply_indices))
    baseline_errors = _projection_candidate_errors(entry, manifests, baseline)
    candidate_errors = _projection_candidate_errors(entry, manifests, candidate)
    if Counter(candidate_errors) != Counter(baseline_errors):
        _projection_fail("WI-LEDGER-MIGRATION-CANDIDATE-INVALID", "; ".join(candidate_errors))
    try:
        _atomic_write(registry_path, candidate)
        actual = registry_path.read_bytes()
    except OSError as exc:
        raise LifecycleError("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "projection revoke registry readback failed") from exc
    if actual != candidate:
        _projection_fail("WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE", "projection revoke registry readback differs")
    facts = _projection_group_facts(operation_id, revoke_lines, before, candidate)
    _projection_reconcile_receipt(receipts, facts)
    return {**facts, "replay": False}


_revoke_legacy_ledger_projection_transaction = _lifecycle_participant(_revoke_legacy_ledger_projection_locked)


def revoke_legacy_ledger_projection(root: Path, apply_operation_id: str, apply_record_sha256: str | list[str], expected_registry_sha256: str, operation_id: str, recorded_at: str) -> dict:
    return _revoke_legacy_ledger_projection_transaction(root, apply_operation_id, apply_record_sha256, expected_registry_sha256, operation_id, recorded_at)


@dataclass(frozen=True)
class SealedPrefixActivationRequestV1:
    h1_manifest_path: str
    h1_manifest_bytes: bytes
    ledger_manifest_path: str
    ledger_manifest_bytes: bytes
    expected_registry_sha256: str
    recorded_at: str


@dataclass(frozen=True)
class SealedPrefixRevokeRequestV1:
    apply_receipt_path: str
    apply_receipt_sha256: str
    expected_registry_sha256: str
    recorded_at: str


@dataclass(frozen=True)
class LedgerH1ArtifactSetRelocationRequestV1:
    archive_owner: str
    expected_artifact_set_sha256: str
    expected_root_contract_sha256: str
    operation_id: str
    recorded_at: str


@dataclass(frozen=True)
class LedgerH1ArtifactSetLocationV1:
    physical_base: str
    phase: Literal["root", "settled-archive"]
    artifact_set_sha256: str
    operation_id: str | None
    receipt_path: str | None


@dataclass(frozen=True)
class SealedPrefixActivationPlanV1:
    state: Literal["apply", "revoke"]
    operation_group_id: str
    member_operation_ids: tuple[str, str]
    receipt_id: str
    ledger_manifest_path: str
    ledger_manifest_bytes: bytes
    h1_manifest_path: str
    h1_manifest_bytes: bytes
    registry_before_sha256: str
    registry_after_bytes: bytes
    receipt_path: str
    receipt_bytes: bytes
    replay: bool


_SEALED_PREFIX_POLICY = "2026-08-28-ledger-h1-compatibility-boundary"
_SEALED_PREFIX_PROFILE = "sealed-active-prefix-v1"
_SEALED_PREFIX_REGISTRY_PATH = f"work-items/{LEGACY_PROJECTION_REGISTRY}"
_SEALED_PREFIX_FAILURE_BOUNDARIES = frozenset(
    {
        "after-ledger-manifest",
        "after-h1-manifest",
        "after-registry-readback",
        "after-receipt-create",
    }
)


def _sealed_prefix_digest(domain: str, value: object) -> str:
    return hashlib.sha256(
        domain.encode("ascii") + b"\0" + _projection_json(value)
    ).hexdigest()


def _sealed_prefix_repository(root: Path) -> tuple[Path, Path]:
    work_items = _work_items_root(root)
    repository = work_items.parent
    _lifecycle_reject_unreduced_reparse(
        repository,
        failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY",
        message="sealed-prefix repository contains a link or reparse point",
    )
    return repository, work_items


def _sealed_prefix_path(
    repository: Path,
    relative: str,
    *,
    prefix: tuple[str, ...],
    failure_id: str,
) -> Path:
    if not isinstance(relative, str) or "\\" in relative:
        _projection_fail(failure_id, "sealed-prefix path is not canonical repository-relative text")
    pure = PurePosixPath(relative)
    if (
        pure.is_absolute()
        or relative != pure.as_posix()
        or any(part in {"", ".", ".."} for part in pure.parts)
        or tuple(pure.parts[: len(prefix)]) != prefix
    ):
        _projection_fail(failure_id, "sealed-prefix path escapes its structural scope")
    return _require_lifecycle_mutation_path(
        repository,
        repository.joinpath(*pure.parts),
        failure_id=failure_id,
    )


def _sealed_prefix_existing_bytes(path: Path, failure_id: str) -> bytes | None:
    try:
        info = path.lstat()
    except FileNotFoundError:
        return None
    except OSError as exc:
        raise LifecycleError(failure_id, "sealed-prefix participant cannot be inspected") from exc
    if _lifecycle_path_has_reparse(path) or not stat.S_ISREG(info.st_mode):
        _projection_fail(failure_id, "sealed-prefix participant is not a regular non-reparse file")
    try:
        return path.read_bytes()
    except OSError as exc:
        raise LifecycleError(failure_id, "sealed-prefix participant cannot be read") from exc


def _sealed_prefix_manifest(request: SealedPrefixActivationRequestV1) -> dict:
    if type(request) is not SealedPrefixActivationRequestV1:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "activation request type is invalid")
    if (
        not isinstance(request.h1_manifest_bytes, bytes)
        or not request.h1_manifest_bytes
        or not isinstance(request.ledger_manifest_bytes, bytes)
        or not request.ledger_manifest_bytes
        or re.fullmatch(r"[0-9a-f]{64}", request.expected_registry_sha256) is None
    ):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "activation request byte/digest fields are invalid")
    try:
        _load_agent_run_ledger()._strict_migration_inputs(
            "sealed-prefix-activation",
            request.recorded_at,
        )
    except Exception as exc:
        raise LifecycleError(
            "WI-LEDGER-MIGRATION-TARGET-IDENTITY",
            "activation recorded-at is not strict UTC",
        ) from exc
    manifest = _projection_object(request.ledger_manifest_bytes, "sealed-prefix ledger manifest")
    required = {
        "schemaVersion",
        "manifestId",
        "policyDecision",
        "profiles",
        "entries",
        "openReviseIdentitySha256",
        "openReviseOracleSha256",
    }
    if set(manifest) != required or manifest.get("schemaVersion") != 2:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "sealed-prefix ledger manifest shape is invalid")
    manifest_id = manifest.get("manifestId")
    entries = manifest.get("entries")
    if (
        not isinstance(manifest_id, str)
        or _PROJECTION_OPERATION_RE.fullmatch(manifest_id) is None
        or manifest.get("policyDecision") != _SEALED_PREFIX_POLICY
        or manifest.get("profiles")
        != [{"profileId": _SEALED_PREFIX_PROFILE, "profileVersion": 1}]
        or not isinstance(entries, list)
        or len(entries) != 2
        or any(not isinstance(entry, dict) for entry in entries)
    ):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "sealed-prefix ledger manifest identity/profile is invalid")
    entry_ids = [entry.get("entryId") for entry in entries]
    ledger_paths = [entry.get("ledgerPath") for entry in entries]
    if (
        any(not isinstance(value, str) or _PROJECTION_OPERATION_RE.fullmatch(value) is None for value in entry_ids)
        or len(set(entry_ids)) != 2
        or any(not isinstance(value, str) for value in ledger_paths)
        or ledger_paths != sorted(ledger_paths, key=lambda value: value.encode("utf-8"))
        or len(set(ledger_paths)) != 2
    ):
        _projection_fail("WI-LEDGER-COMPAT-MEMBER-ORDER", "sealed-prefix manifest entries are not uniquely ordered")
    return manifest


def _sealed_prefix_apply_records(
    manifest: dict,
    request: SealedPrefixActivationRequestV1,
) -> tuple[str, tuple[str, str], tuple[bytes, bytes]]:
    entries = manifest["entries"]
    manifest_sha = _sha256_bytes(request.ledger_manifest_bytes)
    h1_sha = _sha256_bytes(request.h1_manifest_bytes)
    group_id = "g-" + _sealed_prefix_digest(
        "orchestrarium:ledger-h1:registry-group:v1",
        [
            "apply",
            _SEALED_PREFIX_POLICY,
            manifest_sha,
            h1_sha,
            [entry["entryId"] for entry in entries],
        ],
    )
    member_ids = tuple(
        "m:" + _sealed_prefix_digest(
            "orchestrarium:ledger-h1:activation-member:v1",
            [group_id, index, entry["entryId"]],
        )
        for index, entry in enumerate(entries, start=1)
    )
    records = []
    for index, (entry, operation_id) in enumerate(
        zip(entries, member_ids),
        start=1,
    ):
        records.append(
            {
                "schemaVersion": 2,
                "operationId": operation_id,
                "operationGroupId": group_id,
                "groupMemberIndex": index,
                "groupMemberCount": 2,
                "state": "apply",
                "profileId": _SEALED_PREFIX_PROFILE,
                "profileVersion": 1,
                "policyDecision": _SEALED_PREFIX_POLICY,
                "manifestId": manifest["manifestId"],
                "manifestSha256": manifest_sha,
                "manifestEntryId": entry["entryId"],
                "h1ManifestPath": request.h1_manifest_path,
                "h1ManifestSha256": h1_sha,
                "workItem": entry["workItem"],
                "ledgerPath": entry["ledgerPath"],
                "prefixLineCount": entry["prefixLineCount"],
                "prefixByteLength": entry["prefixByteLength"],
                "prefixSha256": entry["prefixSha256"],
                "projectedViewSha256": entry["projectedViewSha256"],
                "recordedAt": request.recorded_at,
            }
        )
    lines = tuple(_projection_json(record) + b"\n" for record in records)
    return group_id, member_ids, lines


def _sealed_prefix_group_position(
    registry_bytes: bytes,
    group_id: str,
    member_ids: tuple[str, str],
    lines: tuple[bytes, bytes],
) -> tuple[bytes, bool]:
    physical = registry_bytes.splitlines(keepends=True)
    parsed: list[dict] = []
    for ordinal, line in enumerate(physical, start=1):
        if not line.endswith(b"\n"):
            _projection_fail("WI-LEDGER-COMPAT-ACTIVATION-PARTIAL", f"registry line {ordinal} is not LF-terminated")
        parsed.append(_projection_object(line[:-1], f"sealed-prefix registry line {ordinal}"))
    positions = [
        index
        for index, record in enumerate(parsed)
        if record.get("operationGroupId") == group_id
        or record.get("operationId") in member_ids
    ]
    if not positions:
        return registry_bytes, False
    if positions != [len(physical) - 2, len(physical) - 1]:
        _projection_fail("WI-LEDGER-COMPAT-ACTIVATION-PARTIAL", "sealed-prefix group is partial, interleaved, or not the registry tail")
    observed = tuple(physical[index] for index in positions)
    if observed != lines:
        _projection_fail("WI-LEDGER-COMPAT-REPLAY-MISMATCH", "sealed-prefix group identity has different bytes")
    return b"".join(physical[: positions[0]]), True


def _sealed_prefix_receipt(
    *,
    state: Literal["apply", "revoke"],
    group_id: str,
    member_ids: tuple[str, str],
    member_lines: tuple[bytes, bytes],
    policy: str,
    ledger_manifest_path: str,
    ledger_manifest_bytes: bytes,
    h1_manifest_path: str,
    h1_manifest_bytes: bytes,
    registry_before: bytes,
    registry_after: bytes,
    recorded_at: str,
) -> tuple[str, str, bytes]:
    before_sha = _sha256_bytes(registry_before)
    after_sha = _sha256_bytes(registry_after)
    receipt_id = "r-" + _sealed_prefix_digest(
        "orchestrarium:ledger-h1:receipt-id:v1",
        [state, group_id, before_sha, after_sha],
    )
    receipt = {
        "schemaVersion": 2,
        "receiptId": receipt_id,
        "state": state,
        "operationGroupId": group_id,
        "policyDecision": policy,
        "ledgerManifestPath": ledger_manifest_path,
        "ledgerManifestSha256": _sha256_bytes(ledger_manifest_bytes),
        "h1ManifestPath": h1_manifest_path,
        "h1ManifestSha256": _sha256_bytes(h1_manifest_bytes),
        "memberOperationIds": list(member_ids),
        "memberRecordSha256": [_sha256_bytes(line) for line in member_lines],
        "registryBeforeSha256": before_sha,
        "registryAfterSha256": after_sha,
        "recordedAt": recorded_at,
    }
    relative = f"work-items/{LEGACY_PROJECTION_RECEIPTS}/{receipt_id}.json"
    return receipt_id, relative, _projection_json(receipt) + b"\n"


def _sealed_prefix_candidate_contexts(
    repository: Path,
    *,
    ledger_bytes_by_path: Mapping[str, bytes],
    h1_manifest_path: str,
    h1_manifest_bytes: bytes,
    ledger_manifest_path: str,
    ledger_manifest_bytes: bytes,
    registry_bytes: bytes,
    receipt_bytes_by_path: Mapping[str, bytes],
    expected_state: Literal["active", "revoked"],
) -> Mapping[str, object]:
    validator = _load_agent_run_ledger().load_validator()
    artifacts = validator.LedgerCompatibilityArtifactSetV1(
        MappingProxyType(dict(ledger_bytes_by_path)),
        h1_manifest_path,
        h1_manifest_bytes,
        ledger_manifest_path,
        ledger_manifest_bytes,
        registry_bytes,
        MappingProxyType(dict(receipt_bytes_by_path)),
    )
    contexts = validator._load_effective_ledger_group(
        repository,
        compatibility_artifacts=artifacts,
    )
    if set(contexts) != set(ledger_bytes_by_path):
        failure_ids = {
            failure
            for context in contexts.values()
            for failure in context.observation.failure_ids
        }
        failure = sorted(failure_ids)[0] if failure_ids else "WI-LEDGER-COMPAT-ACTIVATION-PARTIAL"
        diagnostics = [
            diagnostic
            for context in contexts.values()
            for diagnostic in context.observation.diagnostics
        ]
        _projection_fail(failure, "; ".join(diagnostics) or "reader rejected sealed-prefix candidate")
    values = list(contexts.values())
    if expected_state == "active":
        if (
            not values
            or any(
                context.observation.activation_state != "active"
                or context.view is None
                for context in values
            )
            or len({id(context.invocation_token) for context in values}) != 1
        ):
            _projection_fail("WI-LEDGER-COMPAT-EFFECTIVE-VIEW-BYPASS", "reader did not return one active shared-token group")
    elif (
        not values
        or any(
            context.observation.activation_state != "revoked"
            or context.view is not None
            or any(
                any(
                    (
                        row.authority.launch_eligible,
                        row.authority.terminal_eligible,
                        row.authority.revise_target_eligible,
                        row.authority.closer_eligible,
                        row.authority.artifact_evidence_eligible,
                    )
                )
                for row in context.rows
            )
            for context in values
        )
    ):
        _projection_fail("WI-LEDGER-COMPAT-EFFECTIVE-VIEW-BYPASS", "reader did not fold the revoke candidate to zero authority")
    return contexts


def _sealed_prefix_apply_preflight(
    root: Path,
    request: SealedPrefixActivationRequestV1,
) -> tuple[SealedPrefixActivationPlanV1, Mapping[str, bytes]]:
    manifest = _sealed_prefix_manifest(request)
    repository, work_items = _sealed_prefix_repository(root)
    if request.h1_manifest_path != f"work-items/{DECISION_H1_MANIFEST}":
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "H1 manifest path is not canonical")
    expected_ledger_path = (
        f"work-items/{LEGACY_PROJECTION_MANIFEST_DIR}/{manifest['manifestId']}.json"
    )
    if request.ledger_manifest_path != expected_ledger_path:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "ledger manifest path does not match manifestId")
    h1_path = _sealed_prefix_path(
        repository,
        request.h1_manifest_path,
        prefix=("work-items",),
        failure_id="WI-DECISION-H1-MANIFEST-INVALID",
    )
    ledger_manifest_path = _sealed_prefix_path(
        repository,
        request.ledger_manifest_path,
        prefix=("work-items", LEGACY_PROJECTION_MANIFEST_DIR),
        failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID",
    )
    _preflight_current_decision_h1(root, manifest_bytes=request.h1_manifest_bytes)
    h1_payload = _projection_object(request.h1_manifest_bytes, "H1 manifest")
    if h1_payload.get("policyDecision") != manifest.get("policyDecision"):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "H1 and ledger manifests name different policy decisions")

    ledger_bytes_by_path: dict[str, bytes] = {}
    for entry in manifest["entries"]:
        ledger_relative = entry.get("ledgerPath")
        work_item = entry.get("workItem")
        if (
            not isinstance(ledger_relative, str)
            or not isinstance(work_item, str)
            or ledger_relative != f"{work_item}/agent-runs.jsonl"
        ):
            _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "ledger manifest target identity is invalid")
        ledger_path = _sealed_prefix_path(
            repository,
            ledger_relative,
            prefix=("work-items", "active"),
            failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY",
        )
        raw = _sealed_prefix_existing_bytes(
            ledger_path,
            "WI-LEDGER-MIGRATION-TARGET-IDENTITY",
        )
        if raw is None:
            _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "manifest ledger is missing")
        ledger_bytes_by_path[ledger_relative] = raw

    registry_path = work_items / LEGACY_PROJECTION_REGISTRY
    registry_before_live = _sealed_prefix_existing_bytes(
        registry_path,
        "WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE",
    ) or b""
    group_id, member_ids, member_lines = _sealed_prefix_apply_records(
        manifest,
        request,
    )
    group_before, group_exists = _sealed_prefix_group_position(
        registry_before_live,
        group_id,
        member_ids,
        member_lines,
    )
    if group_exists:
        accepted_registry_hashes = {
            _sha256_bytes(group_before),
            _sha256_bytes(registry_before_live),
        }
        if request.expected_registry_sha256 not in accepted_registry_hashes:
            _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "replay registry digest differs from durable anchors")
        registry_after = registry_before_live
    else:
        if _sha256_bytes(registry_before_live) != request.expected_registry_sha256:
            _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "projection registry digest changed")
        group_before = registry_before_live
        registry_after = registry_before_live + b"".join(member_lines)
    receipt_id, receipt_relative, receipt_bytes = _sealed_prefix_receipt(
        state="apply",
        group_id=group_id,
        member_ids=member_ids,
        member_lines=member_lines,
        policy=manifest["policyDecision"],
        ledger_manifest_path=request.ledger_manifest_path,
        ledger_manifest_bytes=request.ledger_manifest_bytes,
        h1_manifest_path=request.h1_manifest_path,
        h1_manifest_bytes=request.h1_manifest_bytes,
        registry_before=group_before,
        registry_after=registry_after,
        recorded_at=request.recorded_at,
    )
    receipt_path = _sealed_prefix_path(
        repository,
        receipt_relative,
        prefix=("work-items", LEGACY_PROJECTION_RECEIPTS),
        failure_id="WI-LEDGER-COMPAT-RECEIPT-INVALID",
    )
    for path, wanted in (
        (h1_path, request.h1_manifest_bytes),
        (ledger_manifest_path, request.ledger_manifest_bytes),
    ):
        current = _sealed_prefix_existing_bytes(path, "WI-LEDGER-COMPAT-REPLAY-MISMATCH")
        if current is not None and current != wanted:
            _projection_fail("WI-LEDGER-COMPAT-REPLAY-MISMATCH", "create-only manifest bytes differ")
    current_receipt = _sealed_prefix_existing_bytes(
        receipt_path,
        "WI-LEDGER-COMPAT-RECEIPT-INVALID",
    )
    if group_exists:
        if current_receipt is None:
            _projection_fail("WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE", "complete registry group lacks its receipt")
        if current_receipt != receipt_bytes:
            _projection_fail("WI-LEDGER-COMPAT-REPLAY-MISMATCH", "activation receipt bytes differ")
    elif current_receipt is not None:
        _projection_fail("WI-LEDGER-COMPAT-REPLAY-MISMATCH", "activation receipt exists without its registry group")

    _sealed_prefix_candidate_contexts(
        repository,
        ledger_bytes_by_path=ledger_bytes_by_path,
        h1_manifest_path=request.h1_manifest_path,
        h1_manifest_bytes=request.h1_manifest_bytes,
        ledger_manifest_path=request.ledger_manifest_path,
        ledger_manifest_bytes=request.ledger_manifest_bytes,
        registry_bytes=registry_after,
        receipt_bytes_by_path={receipt_relative: receipt_bytes},
        expected_state="active",
    )
    plan = SealedPrefixActivationPlanV1(
        "apply",
        group_id,
        member_ids,
        receipt_id,
        request.ledger_manifest_path,
        request.ledger_manifest_bytes,
        request.h1_manifest_path,
        request.h1_manifest_bytes,
        _sha256_bytes(group_before),
        registry_after,
        receipt_relative,
        receipt_bytes,
        group_exists,
    )
    return plan, MappingProxyType(ledger_bytes_by_path)


def preflight_sealed_prefix_activation(
    root: Path,
    request: SealedPrefixActivationRequestV1,
) -> SealedPrefixActivationPlanV1:
    return _sealed_prefix_apply_preflight(root, request)[0]


def _sealed_prefix_inventory(
    root: Path,
    plan: SealedPrefixActivationPlanV1,
) -> dict[str, dict[str, object]]:
    if plan.replay:
        return {}
    repository, _work_items = _sealed_prefix_repository(root)
    values = {
        plan.ledger_manifest_path: plan.ledger_manifest_bytes,
        plan.h1_manifest_path: plan.h1_manifest_bytes,
        _SEALED_PREFIX_REGISTRY_PATH: plan.registry_after_bytes,
        plan.receipt_path: plan.receipt_bytes,
    }
    inventory: dict[str, dict[str, object]] = {}
    for relative, wanted in values.items():
        path = repository.joinpath(*PurePosixPath(relative).parts)
        current = _sealed_prefix_existing_bytes(
            path,
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
        )
        if current != wanted:
            inventory[relative] = {
                "byteLength": len(wanted),
                "sha256": _sha256_bytes(wanted),
            }
    return inventory


def _sealed_prefix_result(
    plan: SealedPrefixActivationPlanV1,
    *,
    dry_run: bool,
    inventory: dict[str, dict[str, object]],
) -> dict[str, object]:
    return {
        "state": plan.state,
        "readiness": "REPLAY" if plan.replay else "READY",
        "operationGroupId": plan.operation_group_id,
        "memberOperationIds": list(plan.member_operation_ids),
        "receiptId": plan.receipt_id,
        "receiptPath": plan.receipt_path,
        "receiptSha256": _sha256_bytes(plan.receipt_bytes),
        "registryBeforeSha256": plan.registry_before_sha256,
        "registryAfterSha256": _sha256_bytes(plan.registry_after_bytes),
        "byteInventory": inventory,
        "replay": plan.replay,
        "dryRun": dry_run,
    }


def _sealed_prefix_revalidate(
    root: Path,
    request: SealedPrefixActivationRequestV1,
    ledger_bytes_by_path: Mapping[str, bytes],
    registry_expected: bytes,
) -> None:
    transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
    if transaction is None:
        _projection_fail("WI-LIFECYCLE-LOCK-IDENTITY", "sealed-prefix mutation lacks lifecycle transaction")
    transaction.verify()
    _preflight_current_decision_h1(root, manifest_bytes=request.h1_manifest_bytes)
    repository, work_items = _sealed_prefix_repository(root)
    for relative, expected in ledger_bytes_by_path.items():
        path = repository.joinpath(*PurePosixPath(relative).parts)
        if _sealed_prefix_existing_bytes(path, "WI-LEDGER-MIGRATION-LEDGER-DRIFT") != expected:
            _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "manifest ledger changed during activation")
    registry = _sealed_prefix_existing_bytes(
        work_items / LEGACY_PROJECTION_REGISTRY,
        "WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE",
    ) or b""
    if registry != registry_expected:
        _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "registry changed during activation")


def _sealed_prefix_restore(
    path: Path,
    before: bytes | None,
    wanted: bytes,
    failure_id: str,
) -> None:
    current = _sealed_prefix_existing_bytes(path, failure_id)
    if before is None:
        if current is None:
            return
        if current != wanted:
            _projection_fail(failure_id, "rollback target differs from transaction-owned bytes")
        path.unlink()
        return
    if current == before:
        return
    if current != wanted:
        _projection_fail(failure_id, "rollback target is neither exact before nor owned after")
    _atomic_write(path, before)
    if path.read_bytes() != before:
        _projection_fail(failure_id, "rollback readback differs")


def _sealed_prefix_remove_empty_created_dirs(paths: Iterable[tuple[Path, bool]]) -> None:
    for path, existed in paths:
        if existed:
            continue
        try:
            path.rmdir()
        except (FileNotFoundError, OSError):
            pass


def _apply_sealed_prefix_activation_locked(
    root: Path,
    request: SealedPrefixActivationRequestV1,
    *,
    inject_failure: str | None = None,
) -> dict[str, object]:
    if inject_failure is not None and inject_failure not in _SEALED_PREFIX_FAILURE_BOUNDARIES:
        _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "unknown activation failure boundary")
    plan, ledger_bytes_by_path = _sealed_prefix_apply_preflight(root, request)
    inventory = _sealed_prefix_inventory(root, plan)
    if plan.replay:
        return _sealed_prefix_result(plan, dry_run=False, inventory={})
    repository, work_items = _sealed_prefix_repository(root)
    ledger_path = repository.joinpath(*PurePosixPath(plan.ledger_manifest_path).parts)
    h1_path = repository.joinpath(*PurePosixPath(plan.h1_manifest_path).parts)
    registry_path = work_items / LEGACY_PROJECTION_REGISTRY
    receipt_path = repository.joinpath(*PurePosixPath(plan.receipt_path).parts)
    participants = (
        (ledger_path, _sealed_prefix_existing_bytes(ledger_path, "WI-LEDGER-COMPAT-REPLAY-MISMATCH"), plan.ledger_manifest_bytes),
        (h1_path, _sealed_prefix_existing_bytes(h1_path, "WI-LEDGER-COMPAT-REPLAY-MISMATCH"), plan.h1_manifest_bytes),
        (registry_path, _sealed_prefix_existing_bytes(registry_path, "WI-LEDGER-MIGRATION-COMMIT-INDETERMINATE"), plan.registry_after_bytes),
        (receipt_path, _sealed_prefix_existing_bytes(receipt_path, "WI-LEDGER-COMPAT-RECEIPT-INVALID"), plan.receipt_bytes),
    )
    created_dirs = (
        (ledger_path.parent, ledger_path.parent.exists()),
        (receipt_path.parent, receipt_path.parent.exists()),
    )
    registry_before = participants[2][1] or b""
    receipt_committed = False
    try:
        _sealed_prefix_revalidate(root, request, ledger_bytes_by_path, registry_before)
        _projection_create_or_exact(
            ledger_path,
            plan.ledger_manifest_bytes,
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH",
        )
        if inject_failure == "after-ledger-manifest":
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "injected failure after ledger manifest")
        _sealed_prefix_revalidate(root, request, ledger_bytes_by_path, registry_before)
        _projection_create_or_exact(
            h1_path,
            plan.h1_manifest_bytes,
            "WI-LEDGER-COMPAT-REPLAY-MISMATCH",
        )
        if inject_failure == "after-h1-manifest":
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "injected failure after H1 manifest")
        _sealed_prefix_revalidate(root, request, ledger_bytes_by_path, registry_before)
        registry_path.parent.mkdir(parents=True, exist_ok=True)
        _atomic_write(registry_path, plan.registry_after_bytes)
        if registry_path.read_bytes() != plan.registry_after_bytes:
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "registry readback differs")
        if inject_failure == "after-registry-readback":
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "injected failure after registry readback")
        _sealed_prefix_revalidate(
            root,
            request,
            ledger_bytes_by_path,
            plan.registry_after_bytes,
        )
        _projection_create_or_exact(
            receipt_path,
            plan.receipt_bytes,
            "WI-LEDGER-COMPAT-RECEIPT-INVALID",
        )
        receipt_committed = receipt_path.read_bytes() == plan.receipt_bytes
        if not receipt_committed:
            _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "activation receipt readback differs")
        if inject_failure == "after-receipt-create":
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "injected failure after receipt create")
        return _sealed_prefix_result(plan, dry_run=False, inventory=inventory)
    except BaseException:
        if not receipt_committed:
            for path, before, wanted in reversed(participants):
                _sealed_prefix_restore(
                    path,
                    before,
                    wanted,
                    "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                )
            _sealed_prefix_remove_empty_created_dirs(reversed(created_dirs))
        raise


_apply_sealed_prefix_activation_transaction = _lifecycle_participant(
    _apply_sealed_prefix_activation_locked
)


def apply_sealed_prefix_activation(
    root: Path,
    request: SealedPrefixActivationRequestV1,
    *,
    dry_run: bool = False,
    inject_failure: str | None = None,
) -> dict[str, object]:
    if dry_run:
        if inject_failure is not None:
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "dry-run forbids failure injection")
        plan = preflight_sealed_prefix_activation(root, request)
        return _sealed_prefix_result(
            plan,
            dry_run=True,
            inventory=_sealed_prefix_inventory(root, plan),
        )
    return _apply_sealed_prefix_activation_transaction(
        root,
        request,
        inject_failure=inject_failure,
    )


def _sealed_prefix_revoke_preflight(
    root: Path,
    request: SealedPrefixRevokeRequestV1,
) -> tuple[SealedPrefixActivationPlanV1, Mapping[str, bytes]]:
    if type(request) is not SealedPrefixRevokeRequestV1:
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "revoke request type is invalid")
    if (
        re.fullmatch(r"[0-9a-f]{64}", request.apply_receipt_sha256) is None
        or re.fullmatch(r"[0-9a-f]{64}", request.expected_registry_sha256) is None
    ):
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "revoke request digest is invalid")
    try:
        _load_agent_run_ledger()._strict_migration_inputs(
            "sealed-prefix-revoke",
            request.recorded_at,
        )
    except Exception as exc:
        raise LifecycleError("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "revoke recorded-at is not strict UTC") from exc
    repository, work_items = _sealed_prefix_repository(root)
    apply_receipt_path = _sealed_prefix_path(
        repository,
        request.apply_receipt_path,
        prefix=("work-items", LEGACY_PROJECTION_RECEIPTS),
        failure_id="WI-LEDGER-COMPAT-RECEIPT-INVALID",
    )
    apply_receipt_bytes = _sealed_prefix_existing_bytes(
        apply_receipt_path,
        "WI-LEDGER-COMPAT-RECEIPT-INVALID",
    )
    if apply_receipt_bytes is None or _sha256_bytes(apply_receipt_bytes) != request.apply_receipt_sha256:
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "apply receipt is missing or differs")
    apply_receipt = _projection_object(apply_receipt_bytes, "apply receipt")
    if (
        apply_receipt.get("schemaVersion") != 2
        or apply_receipt.get("state") != "apply"
        or request.apply_receipt_path
        != f"work-items/{LEGACY_PROJECTION_RECEIPTS}/{apply_receipt.get('receiptId')}.json"
    ):
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "apply receipt identity is invalid")
    ledger_manifest_relative = apply_receipt.get("ledgerManifestPath")
    h1_manifest_relative = apply_receipt.get("h1ManifestPath")
    if not isinstance(ledger_manifest_relative, str) or not isinstance(h1_manifest_relative, str):
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "apply receipt manifest paths are invalid")
    ledger_manifest_path = _sealed_prefix_path(
        repository,
        ledger_manifest_relative,
        prefix=("work-items", LEGACY_PROJECTION_MANIFEST_DIR),
        failure_id="WI-LEDGER-MIGRATION-MANIFEST-INVALID",
    )
    h1_manifest_path = _sealed_prefix_path(
        repository,
        h1_manifest_relative,
        prefix=("work-items",),
        failure_id="WI-DECISION-H1-MANIFEST-INVALID",
    )
    ledger_manifest_bytes = _sealed_prefix_existing_bytes(ledger_manifest_path, "WI-LEDGER-MIGRATION-MANIFEST-INVALID")
    h1_manifest_bytes = _sealed_prefix_existing_bytes(h1_manifest_path, "WI-DECISION-H1-MANIFEST-INVALID")
    if ledger_manifest_bytes is None or h1_manifest_bytes is None:
        _projection_fail("WI-LEDGER-COMPAT-ACTIVATION-PARTIAL", "apply manifests are missing")
    if (
        _sha256_bytes(ledger_manifest_bytes) != apply_receipt.get("ledgerManifestSha256")
        or _sha256_bytes(h1_manifest_bytes) != apply_receipt.get("h1ManifestSha256")
    ):
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "apply manifest digest differs")
    manifest = _projection_object(ledger_manifest_bytes, "sealed-prefix ledger manifest")
    entries = manifest.get("entries")
    if not isinstance(entries, list) or len(entries) != 2:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "revoke manifest entries are invalid")
    ledger_bytes_by_path: dict[str, bytes] = {}
    for entry in entries:
        if not isinstance(entry, dict) or not isinstance(entry.get("ledgerPath"), str):
            _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "revoke ledger entry is invalid")
        ledger_path = _sealed_prefix_path(
            repository,
            entry["ledgerPath"],
            prefix=("work-items", "active"),
            failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY",
        )
        raw = _sealed_prefix_existing_bytes(ledger_path, "WI-LEDGER-MIGRATION-TARGET-IDENTITY")
        if raw is None:
            _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "revoke ledger is missing")
        if (
            len(raw) != entry.get("prefixByteLength")
            or _sha256_bytes(raw) != entry.get("prefixSha256")
        ):
            _projection_fail("WI-LEDGER-COMPAT-REVOKE-AFTER-SUFFIX", "revoke refuses a ledger with suffix or prefix drift")
        ledger_bytes_by_path[entry["ledgerPath"]] = raw
    registry_path = work_items / LEGACY_PROJECTION_REGISTRY
    registry_live = _sealed_prefix_existing_bytes(registry_path, "WI-LEDGER-COMPAT-ACTIVATION-PARTIAL")
    if registry_live is None:
        _projection_fail("WI-LEDGER-COMPAT-ACTIVATION-PARTIAL", "projection registry is missing")
    physical = registry_live.splitlines(keepends=True)
    parsed = [
        _projection_object(line[:-1], f"revoke registry line {index}")
        for index, line in enumerate(physical, start=1)
        if line.endswith(b"\n")
    ]
    apply_ids = apply_receipt.get("memberOperationIds")
    apply_hashes = apply_receipt.get("memberRecordSha256")
    if not isinstance(apply_ids, list) or not isinstance(apply_hashes, list) or len(apply_ids) != 2 or len(apply_hashes) != 2:
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "apply receipt member arrays are invalid")
    apply_positions = [
        next((index for index, record in enumerate(parsed) if record.get("operationId") == operation_id), -1)
        for operation_id in apply_ids
    ]
    if apply_positions[0] < 0 or apply_positions[1] != apply_positions[0] + 1:
        _projection_fail("WI-LEDGER-COMPAT-ACTIVATION-PARTIAL", "apply registry group is missing or noncontiguous")
    apply_lines = tuple(physical[index] for index in apply_positions)
    apply_records = tuple(parsed[index] for index in apply_positions)
    if [_sha256_bytes(line) for line in apply_lines] != apply_hashes:
        _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "apply registry member digest differs")
    apply_registry = b"".join(physical[: apply_positions[-1] + 1])
    _sealed_prefix_candidate_contexts(
        repository,
        ledger_bytes_by_path=ledger_bytes_by_path,
        h1_manifest_path=h1_manifest_relative,
        h1_manifest_bytes=h1_manifest_bytes,
        ledger_manifest_path=ledger_manifest_relative,
        ledger_manifest_bytes=ledger_manifest_bytes,
        registry_bytes=apply_registry,
        receipt_bytes_by_path={request.apply_receipt_path: apply_receipt_bytes},
        expected_state="active",
    )
    manifest_sha = _sha256_bytes(ledger_manifest_bytes)
    h1_sha = _sha256_bytes(h1_manifest_bytes)
    group_id = "g-" + _sealed_prefix_digest(
        "orchestrarium:ledger-h1:registry-group:v1",
        [
            "revoke",
            manifest["policyDecision"],
            manifest_sha,
            h1_sha,
            [entry["entryId"] for entry in entries],
        ],
    )
    member_ids = tuple(
        "m:" + _sealed_prefix_digest(
            "orchestrarium:ledger-h1:activation-member:v1",
            [group_id, index, entry["entryId"]],
        )
        for index, entry in enumerate(entries, start=1)
    )
    revoke_records = []
    for index, (entry, operation_id, apply_id, apply_line, apply_record) in enumerate(
        zip(entries, member_ids, apply_ids, apply_lines, apply_records),
        start=1,
    ):
        retained = {
            key: apply_record[key]
            for key in (
                "schemaVersion", "profileId", "profileVersion", "policyDecision",
                "manifestId", "manifestSha256", "manifestEntryId", "h1ManifestPath",
                "h1ManifestSha256", "workItem", "ledgerPath", "prefixLineCount",
                "prefixByteLength", "prefixSha256", "projectedViewSha256",
            )
        }
        revoke_records.append(
            {
                **retained,
                "operationId": operation_id,
                "operationGroupId": group_id,
                "groupMemberIndex": index,
                "groupMemberCount": 2,
                "state": "revoke",
                "recordedAt": request.recorded_at,
                "revokeOfOperationId": apply_id,
                "revokeOfOperationGroupId": apply_receipt["operationGroupId"],
                "revokeOfRecordSha256": _sha256_bytes(apply_line),
            }
        )
    revoke_lines = tuple(_projection_json(record) + b"\n" for record in revoke_records)
    group_before, group_exists = _sealed_prefix_group_position(
        registry_live,
        group_id,
        member_ids,
        revoke_lines,
    )
    accepted_registry_hashes = (
        {_sha256_bytes(group_before), _sha256_bytes(registry_live)}
        if group_exists
        else {_sha256_bytes(registry_live)}
    )
    if request.expected_registry_sha256 not in accepted_registry_hashes:
        _projection_fail(
            "WI-LEDGER-MIGRATION-LEDGER-DRIFT",
            "revoke registry digest differs from the current or exact replay anchor",
        )
    registry_after = registry_live if group_exists else registry_live + b"".join(revoke_lines)
    receipt_id, receipt_relative, receipt_bytes = _sealed_prefix_receipt(
        state="revoke",
        group_id=group_id,
        member_ids=member_ids,
        member_lines=revoke_lines,
        policy=manifest["policyDecision"],
        ledger_manifest_path=ledger_manifest_relative,
        ledger_manifest_bytes=ledger_manifest_bytes,
        h1_manifest_path=h1_manifest_relative,
        h1_manifest_bytes=h1_manifest_bytes,
        registry_before=group_before,
        registry_after=registry_after,
        recorded_at=request.recorded_at,
    )
    receipt_path = _sealed_prefix_path(
        repository,
        receipt_relative,
        prefix=("work-items", LEGACY_PROJECTION_RECEIPTS),
        failure_id="WI-LEDGER-COMPAT-RECEIPT-INVALID",
    )
    current_receipt = _sealed_prefix_existing_bytes(receipt_path, "WI-LEDGER-COMPAT-RECEIPT-INVALID")
    if group_exists:
        if current_receipt is None:
            _projection_fail("WI-LEDGER-COMPAT-ACTIVATION-INCOMPLETE", "complete revoke group lacks receipt")
        if current_receipt != receipt_bytes:
            _projection_fail("WI-LEDGER-COMPAT-REPLAY-MISMATCH", "revoke receipt bytes differ")
    elif current_receipt is not None:
        _projection_fail("WI-LEDGER-COMPAT-REPLAY-MISMATCH", "revoke receipt exists without group")
    _sealed_prefix_candidate_contexts(
        repository,
        ledger_bytes_by_path=ledger_bytes_by_path,
        h1_manifest_path=h1_manifest_relative,
        h1_manifest_bytes=h1_manifest_bytes,
        ledger_manifest_path=ledger_manifest_relative,
        ledger_manifest_bytes=ledger_manifest_bytes,
        registry_bytes=registry_after,
        receipt_bytes_by_path={
            request.apply_receipt_path: apply_receipt_bytes,
            receipt_relative: receipt_bytes,
        },
        expected_state="revoked",
    )
    plan = SealedPrefixActivationPlanV1(
        "revoke", group_id, member_ids, receipt_id,
        ledger_manifest_relative, ledger_manifest_bytes,
        h1_manifest_relative, h1_manifest_bytes,
        _sha256_bytes(group_before), registry_after,
        receipt_relative, receipt_bytes, group_exists,
    )
    return plan, MappingProxyType(ledger_bytes_by_path)


def preflight_sealed_prefix_revoke(
    root: Path,
    request: SealedPrefixRevokeRequestV1,
) -> SealedPrefixActivationPlanV1:
    return _sealed_prefix_revoke_preflight(root, request)[0]


def _revoke_sealed_prefix_activation_locked(
    root: Path,
    request: SealedPrefixRevokeRequestV1,
    *,
    inject_failure: str | None = None,
) -> dict[str, object]:
    if inject_failure not in {None, "after-registry-readback", "after-receipt-create"}:
        _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "unknown revoke failure boundary")
    plan, ledger_bytes = _sealed_prefix_revoke_preflight(root, request)
    inventory = _sealed_prefix_inventory(root, plan)
    if plan.replay:
        return _sealed_prefix_result(plan, dry_run=False, inventory={})
    repository, work_items = _sealed_prefix_repository(root)
    registry_path = work_items / LEGACY_PROJECTION_REGISTRY
    receipt_path = repository.joinpath(*PurePosixPath(plan.receipt_path).parts)
    registry_before = registry_path.read_bytes()
    receipt_before = _sealed_prefix_existing_bytes(receipt_path, "WI-LEDGER-COMPAT-RECEIPT-INVALID")
    receipt_dir_existed = receipt_path.parent.exists()
    receipt_committed = False
    try:
        transaction = _CURRENT_LIFECYCLE_TRANSACTION.get()
        if transaction is None:
            _projection_fail("WI-LIFECYCLE-LOCK-IDENTITY", "sealed-prefix revoke lacks lifecycle transaction")
        transaction.verify()
        for relative, expected in ledger_bytes.items():
            path = repository.joinpath(*PurePosixPath(relative).parts)
            if path.read_bytes() != expected:
                _projection_fail("WI-LEDGER-COMPAT-REVOKE-AFTER-SUFFIX", "ledger changed during revoke")
        if registry_path.read_bytes() != registry_before:
            _projection_fail("WI-LEDGER-MIGRATION-LEDGER-DRIFT", "registry changed during revoke")
        _atomic_write(registry_path, plan.registry_after_bytes)
        if registry_path.read_bytes() != plan.registry_after_bytes:
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "revoke registry readback differs")
        if inject_failure == "after-registry-readback":
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "injected failure after revoke registry")
        transaction.verify()
        for relative, expected in ledger_bytes.items():
            path = repository.joinpath(*PurePosixPath(relative).parts)
            if path.read_bytes() != expected:
                _projection_fail("WI-LEDGER-COMPAT-REVOKE-AFTER-SUFFIX", "ledger changed before revoke receipt")
        _projection_create_or_exact(receipt_path, plan.receipt_bytes, "WI-LEDGER-COMPAT-RECEIPT-INVALID")
        receipt_committed = receipt_path.read_bytes() == plan.receipt_bytes
        if not receipt_committed:
            _projection_fail("WI-LEDGER-COMPAT-RECEIPT-INVALID", "revoke receipt readback differs")
        if inject_failure == "after-receipt-create":
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "injected failure after revoke receipt")
        return _sealed_prefix_result(plan, dry_run=False, inventory=inventory)
    except BaseException:
        if not receipt_committed:
            _sealed_prefix_restore(
                registry_path,
                registry_before,
                plan.registry_after_bytes,
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            )
            _sealed_prefix_restore(
                receipt_path,
                receipt_before,
                plan.receipt_bytes,
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            )
            _sealed_prefix_remove_empty_created_dirs(((receipt_path.parent, receipt_dir_existed),))
        raise


_revoke_sealed_prefix_activation_transaction = _lifecycle_participant(
    _revoke_sealed_prefix_activation_locked
)


def revoke_sealed_prefix_activation(
    root: Path,
    request: SealedPrefixRevokeRequestV1,
    *,
    dry_run: bool = False,
    inject_failure: str | None = None,
) -> dict[str, object]:
    if dry_run:
        if inject_failure is not None:
            _projection_fail("WI-LEDGER-COMPAT-COMMIT-INDETERMINATE", "dry-run forbids failure injection")
        plan = preflight_sealed_prefix_revoke(root, request)
        return _sealed_prefix_result(
            plan,
            dry_run=True,
            inventory=_sealed_prefix_inventory(root, plan),
        )
    return _revoke_sealed_prefix_activation_transaction(
        root,
        request,
        inject_failure=inject_failure,
    )


@dataclass(frozen=True)
class _LedgerH1ArtifactSetRelocationPlanV1:
    repository: Path
    work_items: Path
    archive_owner: Path
    artifact_base: Path
    receipt_path: Path
    artifact_set_sha256: str
    root_contract_path: Path
    root_contract_before: bytes
    root_contract_after: bytes | None
    members: tuple[dict[str, object], ...]
    receipt_bytes: bytes


def _ledger_h1_relocation_fail(message: str) -> None:
    raise LifecycleError("WI-LEDGER-COMPAT-SET-TOPOLOGY", message)


def _ledger_h1_relocation_request(
    request: LedgerH1ArtifactSetRelocationRequestV1,
) -> tuple[str, str]:
    if type(request) is not LedgerH1ArtifactSetRelocationRequestV1:
        _ledger_h1_relocation_fail("H1 artifact-set relocation request type is invalid")
    expected_artifact_set_sha256 = _normalize_sha256_input(
        request.expected_artifact_set_sha256
    )
    expected_root_contract_sha256 = _normalize_sha256_input(
        request.expected_root_contract_sha256
    )
    if (
        not isinstance(request.archive_owner, str)
        or not isinstance(expected_artifact_set_sha256, str)
        or SHA256_RE.fullmatch(expected_artifact_set_sha256) is None
        or not isinstance(expected_root_contract_sha256, str)
        or SHA256_RE.fullmatch(expected_root_contract_sha256) is None
        or not isinstance(request.operation_id, str)
        or _PROJECTION_OPERATION_RE.fullmatch(request.operation_id) is None
    ):
        _ledger_h1_relocation_fail("H1 artifact-set relocation request is invalid")
    try:
        _load_agent_run_ledger()._strict_migration_inputs(
            request.operation_id,
            request.recorded_at,
        )
    except Exception as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "H1 artifact-set relocation recorded-at is not strict UTC",
        ) from exc
    return expected_artifact_set_sha256, expected_root_contract_sha256


def _ledger_h1_archive_owner(
    repository: Path,
    work_items: Path,
    relative: str,
) -> Path:
    if "\\" in relative:
        _ledger_h1_relocation_fail("archive owner is not canonical repository-relative text")
    pure = PurePosixPath(relative)
    if (
        pure.is_absolute()
        or relative != pure.as_posix()
        or len(pure.parts) != 4
        or pure.parts[:2] != ("work-items", "archive")
        or re.fullmatch(r"\d{4}-\d{2}", pure.parts[2], re.ASCII) is None
    ):
        _ledger_h1_relocation_fail(
            "archive owner must name one exact monthly archived work item"
        )
    try:
        archive_month_value = datetime.strptime(pure.parts[2], "%Y-%m")
    except ValueError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "archive owner month is not a calendar month",
        ) from exc
    if archive_month_value.strftime("%Y-%m") != pure.parts[2]:
        _ledger_h1_relocation_fail("archive owner month is not canonical")
    _validate_slug(pure.parts[3])
    archive_owner = _require_lifecycle_mutation_path(
        repository,
        repository.joinpath(*pure.parts),
        failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
    )
    if archive_owner.parent.parent != work_items / "archive":
        _ledger_h1_relocation_fail("archive owner escapes the monthly work-item archive")
    if not archive_owner.is_dir() or _lifecycle_path_has_reparse(archive_owner):
        _ledger_h1_relocation_fail("archive owner is not one ordinary archived work item")
    _archived_work_item_entry(archive_owner)
    return archive_owner


def _ledger_h1_directory_snapshot(path: Path,
    *,
    acquired_input=None,
) -> tuple[int, str]:
    rows: list[dict[str, object]] = []
    try:
        children = sorted(_input_children(path, acquired_input), key=lambda child: child.name.encode("utf-8"))
    except OSError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "H1 artifact directory is unreadable",
        ) from exc
    for child in children:
        if _input_has_reparse(child, acquired_input) or not _input_is_file(child, acquired_input):
            _ledger_h1_relocation_fail(
                "H1 artifact directories must contain only ordinary flat files"
            )
        try:
            raw = _input_bytes(child, acquired_input)
        except OSError as exc:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-SET-TOPOLOGY",
                "H1 artifact directory member is unreadable",
            ) from exc
        rows.append(
            {
                "name": child.name,
                "byteLength": len(raw),
                "sha256": _sha256_bytes(raw),
            }
        )
    directory_digest = hashlib.sha256(
        b"orchestrarium:ledger-h1-artifact-directory:v1\0"
        + _projection_json(rows)
    ).hexdigest()
    return sum(int(row["byteLength"]) for row in rows), directory_digest


def _ledger_h1_member_snapshot(
    path: Path,
    *,
    kind: str,
    acquired_input=None,
) -> tuple[int, str]:
    if _input_has_reparse(path, acquired_input):
        _ledger_h1_relocation_fail("H1 artifact-set member is a link or reparse point")
    if kind == "file":
        if not _input_is_file(path, acquired_input):
            _ledger_h1_relocation_fail("H1 artifact-set file member is missing")
        try:
            raw = _input_bytes(path, acquired_input)
        except OSError as exc:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-SET-TOPOLOGY",
                "H1 artifact-set file member is unreadable",
            ) from exc
        return len(raw), _sha256_bytes(raw)
    if kind != "directory" or not _input_is_dir(path, acquired_input):
        _ledger_h1_relocation_fail("H1 artifact-set directory member is missing")
    return _ledger_h1_directory_snapshot(path, acquired_input=acquired_input)


def _ledger_h1_artifact_set_digest_version(
    members: Iterable[Mapping[str, object]],
    *,
    version: Literal[1, 2],
) -> str:
    rows: list[dict[str, object]] = []
    for member in sorted(
        members,
        key=lambda row: str(row["logicalPath"]).encode("utf-8"),
    ):
        row = {
            "logicalPath": member["logicalPath"],
            "kind": member["kind"],
        }
        if version == 2 or member["kind"] == "file":
            row.update(
                {
                    "byteLength": member["byteLength"],
                    "sha256": member["sha256"],
                }
            )
        rows.append(row)
    return hashlib.sha256(
        f"orchestrarium:ledger-h1-artifact-set:v{version}\0".encode("ascii")
        + _projection_json(rows)
    ).hexdigest()


def _ledger_h1_artifact_set_digest_v1(
    members: Iterable[Mapping[str, object]],
) -> str:
    return _ledger_h1_artifact_set_digest_version(members, version=1)


def _ledger_h1_artifact_set_digest(
    members: Iterable[Mapping[str, object]],
) -> str:
    return _ledger_h1_artifact_set_digest_version(members, version=2)


def _ledger_h1_lexically_exists(path: Path,
    *,
    acquired_input=None,
) -> bool:
    if acquired_input is not None and _settled_history_input(acquired_input) is not None:
        return _input_exists(path, acquired_input)
    try:
        _input_metadata(path, acquired_input)
    except FileNotFoundError:
        return False
    except OSError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "H1 artifact-set path cannot be inspected",
        ) from exc
    return True


def _ledger_h1_members_at_base(
    repository: Path,
    base: Path,
    *,
    acquired_input=None,
) -> tuple[dict[str, object], ...]:
    members: list[dict[str, object]] = []
    for name, kind in LEDGER_H1_RELOCATION_MEMBERS:
        path = base / name
        byte_length, sha256 = _ledger_h1_member_snapshot(path, kind=kind, acquired_input=acquired_input)
        members.append(
            {
                "logicalPath": f"work-items/{name}",
                "sourcePath": path.relative_to(repository).as_posix(),
                "targetPath": path.relative_to(repository).as_posix(),
                "kind": kind,
                "byteLength": byte_length,
                "sha256": sha256,
            }
        )
    members.sort(key=lambda row: str(row["logicalPath"]).encode("utf-8"))
    return tuple(members)


def _ledger_h1_archive_bases(repository: Path, work_items: Path,
    *,
    acquired_input=None,
) -> tuple[Path, ...]:
    archive = work_items / "archive"
    if not _ledger_h1_lexically_exists(archive, acquired_input=acquired_input):
        return ()
    _input_reject_reparse(
        archive,
        failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
        message="H1 archive root contains a link or reparse point",
     acquired_input=acquired_input)
    if not _input_is_dir(archive, acquired_input):
        _ledger_h1_relocation_fail("H1 archive root is not a directory")
    bases: list[Path] = []
    try:
        months = sorted(_input_children(archive, acquired_input), key=lambda path: path.name.encode("utf-8"))
        for month in months:
            if not _input_is_dir(month, acquired_input):
                continue
            _input_reject_reparse(
                month,
                failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
                message="H1 archive month contains a link or reparse point",
             acquired_input=acquired_input)
            for owner in sorted(
                _input_children(month, acquired_input), key=lambda path: path.name.encode("utf-8")
            ):
                if not _input_is_dir(owner, acquired_input):
                    continue
                base = owner / LEDGER_H1_ARTIFACT_BASE
                if _ledger_h1_lexically_exists(base, acquired_input=acquired_input):
                    _input_reject_reparse(
                        base,
                        failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
                        message="H1 archived artifact base contains a link or reparse point",
                     acquired_input=acquired_input)
                    bases.append(base)
    except OSError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "H1 archive topology is unreadable",
        ) from exc
    return tuple(bases)


def _ledger_h1_root_profile_observed(work_items: Path,
    *,
    acquired_input=None,
) -> bool:
    h1 = work_items / DECISION_H1_MANIFEST
    if _ledger_h1_lexically_exists(h1, acquired_input=acquired_input):
        try:
            manifest_bytes = _capture_file_snapshot(
                h1, failure_id="WI-DECISION-H1-MANIFEST-INVALID"
            , acquired_input=acquired_input).data
            _preflight_current_decision_h1(
                work_items.parent, manifest_bytes=manifest_bytes
            , acquired_input=acquired_input)
        except (OSError, LifecycleError):
            return True
        payload = json.loads(
            manifest_bytes.decode("utf-8"),
            object_pairs_hook=_decision_compatibility_json_object,
        )
        if payload["policyDecision"] == _SEALED_PREFIX_POLICY:
            return True
    profile_marker = _SEALED_PREFIX_PROFILE.encode("ascii")
    policy_marker = _SEALED_PREFIX_POLICY.encode("ascii")
    manifests = work_items / LEGACY_PROJECTION_MANIFEST_DIR
    registry = work_items / LEGACY_PROJECTION_REGISTRY
    receipts = work_items / LEGACY_PROJECTION_RECEIPTS
    try:
        if _input_is_dir(manifests, acquired_input) and any(
            profile_marker in (raw := _input_bytes(path, acquired_input)) or policy_marker in raw
            for path in _input_children(manifests, acquired_input)
            if _input_is_file(path, acquired_input) and path.suffix == ".json"
        ):
            return True
        if _input_is_file(registry, acquired_input):
            registry_bytes = _input_bytes(registry, acquired_input)
            if profile_marker in registry_bytes or policy_marker in registry_bytes:
                return True
        if _input_is_dir(receipts, acquired_input):
            for path in _input_children(receipts, acquired_input):
                if not _input_is_file(path, acquired_input) or path.suffix != ".json":
                    continue
                raw = _input_bytes(path, acquired_input)
                if (
                    profile_marker in raw
                    or policy_marker in raw
                    or b'"ledgerManifestPath"' in raw
                    or b'"h1ManifestPath"' in raw
                    or re.search(rb'"schemaVersion"\s*:\s*2(?:\D|$)', raw)
                    is not None
                ):
                    return True
    except OSError:
        return True
    return False


def _ledger_h1_json_object(pairs: list[tuple[str, object]]) -> dict[str, object]:
    value: dict[str, object] = {}
    for key, item in pairs:
        if key in value:
            _ledger_h1_relocation_fail(f"H1 settlement repeats JSON key: {key}")
        value[key] = item
    return value


def _ledger_h1_receipt_object(path: Path,
    *,
    acquired_input=None,
) -> tuple[dict[str, object], bytes]:
    if _input_has_reparse(path, acquired_input) or not _input_is_file(path, acquired_input):
        _ledger_h1_relocation_fail("settled H1 archive lacks one ordinary receipt")
    try:
        raw = _input_bytes(path, acquired_input)
        receipt = json.loads(
            raw.decode("utf-8"),
            object_pairs_hook=_ledger_h1_json_object,
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "settled H1 archive receipt is unreadable",
        ) from exc
    if not isinstance(receipt, dict):
        _ledger_h1_relocation_fail("settled H1 archive receipt is not one object")
    return receipt, raw


def _ledger_h1_validate_receipt(
    repository: Path,
    base: Path,
    receipt: Mapping[str, object],
    artifact_set_sha256_v1: str,
    artifact_set_sha256_v2: str,
) -> None:
    base_relative = base.relative_to(repository).as_posix()
    archive_owner = base.parent.relative_to(repository).as_posix()
    root_after = receipt.get("rootContractAfterSha256")
    schema_version = receipt.get("schemaVersion")
    receipt_artifact_set_sha256 = (
        artifact_set_sha256_v1
        if schema_version == 1
        else artifact_set_sha256_v2
        if schema_version == 2
        else None
    )
    if (
        set(receipt) != LEDGER_H1_RELOCATION_RECEIPT_FIELDS
        or receipt_artifact_set_sha256 is None
        or receipt.get("status") != "settled"
        or receipt.get("archiveOwner") != archive_owner
        or receipt.get("artifactBase") != base_relative
        or receipt.get("artifactSetSha256") != receipt_artifact_set_sha256
        or not isinstance(receipt.get("operationId"), str)
        or _PROJECTION_OPERATION_RE.fullmatch(str(receipt["operationId"])) is None
        or not isinstance(receipt.get("recordedAt"), str)
        or not isinstance(receipt.get("rootContractBeforeSha256"), str)
        or SHA256_RE.fullmatch(str(receipt["rootContractBeforeSha256"])) is None
        or (
            root_after is not None
            and (
                not isinstance(root_after, str)
                or SHA256_RE.fullmatch(root_after) is None
            )
        )
    ):
        _ledger_h1_relocation_fail("settled H1 archive receipt binding differs")


def resolve_ledger_h1_artifact_set_location(
    root: Path,
    *,
    input_role: str = "caller-root",
    acquired_input=None,
) -> LedgerH1ArtifactSetLocationV1 | None:
    """Resolve one complete root set or one exact settled archived set."""

    unresolved = _lifecycle_unresolved_absolute(Path(root))
    _input_reject_reparse(
        unresolved,
        failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
        message="H1 repository root contains a link or reparse point",
     acquired_input=acquired_input)
    repository, work_items = _resolve_project_root_identity(
        unresolved, input_role=input_role, failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
     acquired_input=acquired_input)
    if not _input_is_dir(work_items, acquired_input) or _input_has_reparse(work_items, acquired_input):
        return None
    root_presence = tuple(
        _ledger_h1_lexically_exists(work_items / name, acquired_input=acquired_input)
        for name, _kind in LEDGER_H1_RELOCATION_MEMBERS
    )
    root_observed = _ledger_h1_root_profile_observed(work_items, acquired_input=acquired_input)
    archive_bases = _ledger_h1_archive_bases(repository, work_items, acquired_input=acquired_input)
    if root_observed and not all(root_presence):
        _ledger_h1_relocation_fail("root H1 artifact set is partial")
    if root_observed and all(root_presence) and archive_bases:
        _ledger_h1_relocation_fail("root and archived H1 artifact sets coexist")
    if len(archive_bases) > 1:
        _ledger_h1_relocation_fail("more than one archived H1 artifact set exists")
    if root_observed and all(root_presence):
        members = _ledger_h1_members_at_base(repository, work_items, acquired_input=acquired_input)
        return LedgerH1ArtifactSetLocationV1(
            "work-items",
            "root",
            _ledger_h1_artifact_set_digest(members),
            None,
            None,
        )
    if not archive_bases:
        return None
    base = archive_bases[0]
    if not _input_is_dir(base, acquired_input):
        _ledger_h1_relocation_fail("archived H1 artifact base is not a directory")
    try:
        _archived_work_item_entry(base.parent, acquired_input=acquired_input)
    except LifecycleError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "archived H1 artifact base has no valid work-item owner",
        ) from exc
    members = _ledger_h1_members_at_base(repository, base, acquired_input=acquired_input)
    artifact_set_sha256_v2 = _ledger_h1_artifact_set_digest(members)
    artifact_set_sha256_v1 = _ledger_h1_artifact_set_digest_v1(members)
    receipt_path = base / "relocation-receipt.json"
    receipt, _raw = _ledger_h1_receipt_object(receipt_path, acquired_input=acquired_input)
    _ledger_h1_validate_receipt(
        repository,
        base,
        receipt,
        artifact_set_sha256_v1,
        artifact_set_sha256_v2,
    )
    return LedgerH1ArtifactSetLocationV1(
        base.relative_to(repository).as_posix(),
        "settled-archive",
        artifact_set_sha256_v2,
        str(receipt["operationId"]),
        receipt_path.relative_to(repository).as_posix(),
    )


def _ledger_h1_root_contract_after(
    work_items: Path,
    expected_sha256: str,
) -> tuple[Path, bytes, bytes | None]:
    contract_path = work_items / ROOT_CONTRACT_FILE
    if _lifecycle_path_has_reparse(contract_path) or not contract_path.is_file():
        _ledger_h1_relocation_fail("root contract with both H1 declarations is required")
    try:
        before = contract_path.read_bytes()
        contract = json.loads(
            before.decode("utf-8"),
            object_pairs_hook=_root_contract_json_object,
        )
    except (OSError, UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "root contract is unreadable",
        ) from exc
    if _sha256_bytes(before) != expected_sha256:
        _ledger_h1_relocation_fail("root contract compare-and-swap digest changed")
    required = {LEGACY_PROJECTION_MANIFEST_DIR, LEGACY_PROJECTION_RECEIPTS}
    auxiliary = contract.get("auxiliaryRoots") if isinstance(contract, dict) else None
    if (
        not isinstance(auxiliary, dict)
        or not required.issubset(auxiliary)
        or any(auxiliary[name] != {"kind": "flat-json"} for name in required)
    ):
        _ledger_h1_relocation_fail("root contract lacks the two exact H1 declarations")
    after_contract = dict(contract)
    after_auxiliary = dict(auxiliary)
    for name in required:
        after_auxiliary.pop(name)
    if not after_auxiliary:
        after = None
    else:
        after_contract["auxiliaryRoots"] = after_auxiliary
        after = _migration_receipt_bytes(after_contract)
    return contract_path, before, after


def _ledger_h1_relocation_preflight(
    root: Path,
    request: LedgerH1ArtifactSetRelocationRequestV1,
) -> _LedgerH1ArtifactSetRelocationPlanV1:
    expected_artifact_set_sha256, expected_root_contract_sha256 = (
        _ledger_h1_relocation_request(request)
    )
    work_items = _work_items_root(
        root,
        root_failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
    )
    repository = work_items.parent
    archive_owner = _ledger_h1_archive_owner(
        repository,
        work_items,
        request.archive_owner,
    )
    artifact_base = _require_lifecycle_mutation_path(
        repository,
        archive_owner / LEDGER_H1_ARTIFACT_BASE,
        failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
    )
    receipt_path = artifact_base / "relocation-receipt.json"
    if artifact_base.exists():
        _ledger_h1_relocation_fail("H1 artifact-set archive target already exists")
    members: list[dict[str, object]] = []
    for name, kind in LEDGER_H1_RELOCATION_MEMBERS:
        source = work_items / name
        target = artifact_base / name
        byte_length, sha256 = _ledger_h1_member_snapshot(source, kind=kind)
        members.append(
            {
                "logicalPath": f"work-items/{name}",
                "sourcePath": source.relative_to(repository).as_posix(),
                "targetPath": target.relative_to(repository).as_posix(),
                "kind": kind,
                "byteLength": byte_length,
                "sha256": sha256,
            }
        )
    members.sort(key=lambda row: str(row["logicalPath"]).encode("utf-8"))
    artifact_set_sha256 = _ledger_h1_artifact_set_digest(members)
    if artifact_set_sha256 != expected_artifact_set_sha256:
        _ledger_h1_relocation_fail("H1 artifact-set compare-and-swap digest changed")
    root_contract_path, root_contract_before, root_contract_after = (
        _ledger_h1_root_contract_after(
            work_items,
            expected_root_contract_sha256,
        )
    )
    receipt_payload = {
        "schemaVersion": 2,
        "status": "settled",
        "operationId": request.operation_id,
        "archiveOwner": request.archive_owner,
        "artifactBase": artifact_base.relative_to(repository).as_posix(),
        "artifactSetSha256": artifact_set_sha256,
        "rootContractBeforeSha256": _sha256_bytes(root_contract_before),
        "rootContractAfterSha256": (
            _sha256_bytes(root_contract_after)
            if root_contract_after is not None
            else None
        ),
        "recordedAt": request.recorded_at,
    }
    receipt_bytes = _migration_receipt_bytes(receipt_payload)
    return _LedgerH1ArtifactSetRelocationPlanV1(
        repository,
        work_items,
        archive_owner,
        artifact_base,
        receipt_path,
        artifact_set_sha256,
        root_contract_path,
        root_contract_before,
        root_contract_after,
        tuple(members),
        receipt_bytes,
    )


def _ledger_h1_relocation_result(
    plan: _LedgerH1ArtifactSetRelocationPlanV1,
    request: LedgerH1ArtifactSetRelocationRequestV1,
    *,
    applied: bool,
    replay: bool,
) -> dict[str, object]:
    return {
        "schemaVersion": 1,
        "status": "settled" if applied else "ready",
        "operationId": request.operation_id,
        "archiveOwner": request.archive_owner,
        "artifactBase": plan.artifact_base.relative_to(plan.repository).as_posix(),
        "artifactSetSha256": plan.artifact_set_sha256,
        "applied": applied,
        "replay": replay,
        **({"event": LEDGER_H1_RELOCATION_EVENT} if applied else {}),
    }


def _ledger_h1_relocation_intent(
    plan: _LedgerH1ArtifactSetRelocationPlanV1,
    request: LedgerH1ArtifactSetRelocationRequestV1,
) -> dict[str, object]:
    return {
        "schemaVersion": 1,
        "owner": LEDGER_H1_RELOCATION_OWNER,
        "kind": LEDGER_H1_RELOCATION_KIND,
        "status": "intent",
        "operationId": request.operation_id,
        "recordedAt": request.recorded_at,
        "archiveOwner": request.archive_owner,
        "artifactBase": plan.artifact_base.relative_to(plan.repository).as_posix(),
        "receiptPath": plan.receipt_path.relative_to(plan.repository).as_posix(),
        "expectedArtifactSetSha256": plan.artifact_set_sha256,
        "expectedRootContractSha256": _sha256_bytes(plan.root_contract_before),
        "targetBaseBefore": None,
        "members": [dict(member) for member in plan.members],
        "rootContractBefore": _b64(plan.root_contract_before),
        "rootContractAfter": _b64(plan.root_contract_after),
        "receiptAfter": _b64(plan.receipt_bytes),
    }


def _validate_ledger_h1_relocation_intent_shape(
    root: Path,
    intent: Mapping[str, object],
    intent_path: Path,
) -> None:
    operation_id = intent.get("operationId")
    recorded_at = intent.get("recordedAt")
    archive_owner = intent.get("archiveOwner")
    artifact_base = intent.get("artifactBase")
    receipt_path = intent.get("receiptPath")
    members = intent.get("members")
    if (
        not isinstance(operation_id, str)
        or _PROJECTION_OPERATION_RE.fullmatch(operation_id) is None
        or not isinstance(recorded_at, str)
        or not isinstance(archive_owner, str)
        or not isinstance(artifact_base, str)
        or artifact_base != f"{archive_owner}/{LEDGER_H1_ARTIFACT_BASE}"
        or not isinstance(receipt_path, str)
        or receipt_path != f"{artifact_base}/relocation-receipt.json"
        or intent.get("targetBaseBefore") is not None
        or not isinstance(intent.get("expectedArtifactSetSha256"), str)
        or SHA256_RE.fullmatch(str(intent["expectedArtifactSetSha256"])) is None
        or not isinstance(intent.get("expectedRootContractSha256"), str)
        or SHA256_RE.fullmatch(str(intent["expectedRootContractSha256"])) is None
        or not isinstance(members, list)
        or len(members) != len(LEDGER_H1_RELOCATION_MEMBERS)
    ):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent binding differs",
        )
    try:
        _load_agent_run_ledger()._strict_migration_inputs(operation_id, recorded_at)
    except Exception as exc:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent operation or time differs",
        ) from exc
    expected_intent_path = _transition_intent_path(root, operation_id)
    if expected_intent_path.absolute() != intent_path.absolute():
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent path differs from its operation id",
        )
    for relative in (archive_owner, artifact_base, receipt_path):
        _intent_path(root, relative)
    expected_members = {
        f"work-items/{name}": (name, kind)
        for name, kind in LEDGER_H1_RELOCATION_MEMBERS
    }
    expected_logical_paths = sorted(
        expected_members,
        key=lambda value: value.encode("utf-8"),
    )
    logical_paths: list[str] = []
    for member in members:
        if (
            not isinstance(member, dict)
            or set(member) != LEDGER_H1_RELOCATION_MEMBER_FIELDS
            or not isinstance(member.get("logicalPath"), str)
            or member["logicalPath"] not in expected_members
            or not isinstance(member.get("sourcePath"), str)
            or member["sourcePath"] != member["logicalPath"]
            or not isinstance(member.get("targetPath"), str)
            or not isinstance(member.get("kind"), str)
            or type(member.get("byteLength")) is not int
            or int(member["byteLength"]) < 0
            or not isinstance(member.get("sha256"), str)
            or SHA256_RE.fullmatch(str(member["sha256"])) is None
        ):
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                "H1 relocation intent member differs",
            )
        name, kind = expected_members[str(member["logicalPath"])]
        if (
            member["kind"] != kind
            or member["targetPath"] != f"{artifact_base}/{name}"
        ):
            raise LifecycleError(
                "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
                "H1 relocation intent member binding differs",
            )
        logical_paths.append(str(member["logicalPath"]))
        _intent_path(root, str(member["sourcePath"]))
        _intent_path(root, str(member["targetPath"]))
    if logical_paths != expected_logical_paths:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent members differ from the complete sorted set",
        )
    root_before = _unb64(intent.get("rootContractBefore"))
    root_after = _unb64(intent.get("rootContractAfter"))
    receipt_after = _unb64(intent.get("receiptAfter"))
    if (
        root_before is None
        or receipt_after is None
        or _sha256_bytes(root_before) != intent["expectedRootContractSha256"]
    ):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent byte images differ",
        )
    try:
        receipt = json.loads(receipt_after.decode("utf-8"))
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent receipt after-image is invalid",
        ) from exc
    if (
        not isinstance(receipt, dict)
        or set(receipt) != LEDGER_H1_RELOCATION_RECEIPT_FIELDS
        or receipt.get("schemaVersion") != 2
        or receipt.get("operationId") != operation_id
        or receipt.get("recordedAt") != recorded_at
        or receipt.get("archiveOwner") != archive_owner
        or receipt.get("artifactBase") != artifact_base
        or receipt.get("artifactSetSha256")
        != intent["expectedArtifactSetSha256"]
        or receipt.get("rootContractBeforeSha256")
        != intent["expectedRootContractSha256"]
        or receipt.get("rootContractAfterSha256")
        != (_sha256_bytes(root_after) if root_after is not None else None)
    ):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent receipt binding differs",
        )


def _ledger_h1_exact_member_at(
    path: Path,
    member: Mapping[str, object],
    *,
    failure_id: str,
) -> None:
    try:
        byte_length, sha256 = _ledger_h1_member_snapshot(
            path,
            kind=str(member["kind"]),
        )
    except LifecycleError as exc:
        raise LifecycleError(failure_id, "H1 relocation member cannot be proven") from exc
    if byte_length != member["byteLength"] or sha256 != member["sha256"]:
        raise LifecycleError(failure_id, "H1 relocation member bytes differ")


def _ledger_h1_intent_distribution(
    root: Path,
    intent: Mapping[str, object],
) -> tuple[tuple[Mapping[str, object], Path, Path, str], ...]:
    distribution: list[tuple[Mapping[str, object], Path, Path, str]] = []
    for member in intent["members"]:
        source = _intent_path(root, str(member["sourcePath"]))
        target = _intent_path(root, str(member["targetPath"]))
        source_exists = _ledger_h1_lexically_exists(source)
        target_exists = _ledger_h1_lexically_exists(target)
        if source_exists and target_exists:
            _ledger_h1_relocation_fail("H1 relocation member exists at root and target")
        if not source_exists and not target_exists:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "H1 relocation member exists at neither owned location",
            )
        selected = source if source_exists else target
        _ledger_h1_exact_member_at(
            selected,
            member,
            failure_id="WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
        )
        distribution.append((member, source, target, "source" if source_exists else "target"))
    return tuple(distribution)


def _ledger_h1_current_contract(path: Path) -> bytes | None:
    if not _ledger_h1_lexically_exists(path):
        return None
    if _lifecycle_path_has_reparse(path) or not path.is_file():
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 root contract identity differs",
        )
    try:
        return path.read_bytes()
    except OSError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 root contract is unreadable",
        ) from exc


def _ledger_h1_apply_contract_after(
    root: Path,
    contract_path: Path,
    before: bytes,
    after: bytes | None,
) -> None:
    current = _ledger_h1_current_contract(contract_path)
    if current == after:
        return
    if current != before:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 root contract is neither exact before nor exact after",
        )
    if after is None:
        contract_path.unlink()
    else:
        _atomic_write(contract_path, after)
    _transition_fsync_directory(contract_path.parent)
    if _ledger_h1_current_contract(contract_path) != after:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 root contract after-image readback differs",
        )


def _ledger_h1_restore_before_receipt(
    root: Path,
    intent_path: Path,
    intent: Mapping[str, object],
) -> None:
    receipt_path = _intent_path(root, str(intent["receiptPath"]))
    if _ledger_h1_lexically_exists(receipt_path):
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 rollback is forbidden after receipt commit",
        )
    distribution = _ledger_h1_intent_distribution(root, intent)
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
    )
    artifact_base = _intent_path(root, str(intent["artifactBase"]))
    for member, source, target, side in reversed(distribution):
        if side == "target":
            source.parent.mkdir(parents=True, exist_ok=True)
            (_replace_lifecycle_directory(target, source) if member["kind"] == "directory" else _replace_lifecycle_directory(target, source, directory=False))
            _ledger_h1_exact_member_at(
                source,
                member,
                failure_id="WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            )
    contract_path = repository / "work-items" / ROOT_CONTRACT_FILE
    root_before = _unb64(intent.get("rootContractBefore"))
    root_after = _unb64(intent.get("rootContractAfter"))
    if root_before is None:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 rollback lacks a root contract before-image",
        )
    current = _ledger_h1_current_contract(contract_path)
    if current != root_before:
        if current != root_after:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "H1 rollback root contract cannot be proven",
            )
        _atomic_write(contract_path, root_before)
    try:
        artifact_base.rmdir()
    except FileNotFoundError:
        pass
    except OSError as exc:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 rollback target base is not empty",
        ) from exc
    _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
    _transition_fsync_directory(intent_path.parent)


def _ledger_h1_settle_receipt(
    root: Path,
    intent: Mapping[str, object],
) -> bytes:
    receipt_path = _intent_path(root, str(intent["receiptPath"]))
    wanted = _unb64(intent.get("receiptAfter"))
    if wanted is None:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 relocation receipt after-image is absent",
        )
    if _ledger_h1_lexically_exists(receipt_path):
        try:
            current = receipt_path.read_bytes()
        except OSError as exc:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "H1 relocation receipt is unreadable",
            ) from exc
        if current != wanted:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "H1 relocation receipt differs from exact after-image",
            )
    else:
        _atomic_write(receipt_path, wanted)
        _transition_fsync_directory(receipt_path.parent)
    if receipt_path.read_bytes() != wanted:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 relocation receipt readback differs",
        )
    return wanted


def _recover_ledger_h1_artifact_set_relocation(
    root: Path,
    intent_path: Path,
    intent: Mapping[str, object],
) -> dict[str, object] | None:
    _validate_ledger_h1_relocation_intent_shape(root, intent, intent_path)
    repository, _work_items = _resolve_project_root_identity(
        root, input_role="repository-root",
    )
    artifact_base = _intent_path(root, str(intent["artifactBase"]))
    archive_bases = _ledger_h1_archive_bases(
        repository,
        repository / "work-items",
    )
    if any(base != artifact_base for base in archive_bases):
        _ledger_h1_relocation_fail("a second archived H1 artifact set blocks recovery")
    distribution = _ledger_h1_intent_distribution(root, intent)
    source_count = sum(side == "source" for _member, _source, _target, side in distribution)
    receipt_path = _intent_path(root, str(intent["receiptPath"]))
    root_before = _unb64(intent.get("rootContractBefore"))
    root_after = _unb64(intent.get("rootContractAfter"))
    if root_before is None:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 recovery lacks root contract before-image",
        )
    contract_path = repository / "work-items" / ROOT_CONTRACT_FILE
    if source_count == len(distribution):
        if _ledger_h1_current_contract(contract_path) != root_before:
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "root-only H1 recovery lacks exact contract before-image",
            )
        if _ledger_h1_lexically_exists(receipt_path):
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "root-only H1 recovery unexpectedly has a receipt",
            )
        if _ledger_h1_lexically_exists(artifact_base):
            try:
                artifact_base.rmdir()
            except OSError as exc:
                raise LifecycleError(
                    "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                    "root-only H1 recovery target is not empty",
                ) from exc
        _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
        _transition_fsync_directory(intent_path.parent)
        return None
    if _ledger_h1_lexically_exists(receipt_path) and source_count:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "split H1 recovery unexpectedly has a receipt",
        )
    artifact_base.mkdir(exist_ok=True)
    for member, source, target, side in distribution:
        if side == "source":
            (_replace_lifecycle_directory(source, target) if member["kind"] == "directory" else _replace_lifecycle_directory(source, target, directory=False))
            _ledger_h1_exact_member_at(
                target,
                member,
                failure_id="WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            )
    _transition_fsync_directory(repository / "work-items")
    _transition_fsync_directory(artifact_base)
    final_distribution = _ledger_h1_intent_distribution(root, intent)
    if any(side != "target" for _member, _source, _target, side in final_distribution):
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 recovery did not converge to the target set",
        )
    _ledger_h1_apply_contract_after(
        root,
        contract_path,
        root_before,
        root_after,
    )
    _ledger_h1_settle_receipt(root, intent)
    location = resolve_ledger_h1_artifact_set_location(
        root, input_role="repository-root",
    )
    if (
        location is None
        or location.phase != "settled-archive"
        or location.artifact_set_sha256 != intent["expectedArtifactSetSha256"]
        or location.operation_id != intent["operationId"]
    ):
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 recovery settlement cannot be proven",
        )
    _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
    _transition_fsync_directory(intent_path.parent)
    return {
        "schemaVersion": 1,
        "status": "settled",
        "operationId": intent["operationId"],
        "archiveOwner": intent["archiveOwner"],
        "artifactBase": intent["artifactBase"],
        "artifactSetSha256": intent["expectedArtifactSetSha256"],
        "applied": True,
        "replay": False,
        "event": LEDGER_H1_RELOCATION_EVENT,
    }


def _ledger_h1_replay_result(
    root: Path,
    request: LedgerH1ArtifactSetRelocationRequestV1,
    *,
    applied: bool,
    input_role: str = "caller-root",
) -> dict[str, object] | None:
    expected_artifact_set_sha256, expected_root_contract_sha256 = (
        _ledger_h1_relocation_request(request)
    )
    _lifecycle_reject_unreduced_reparse(
        Path(root), failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
        message="H1 repository root contains a link or reparse point",
    )
    repository, _work_items = _resolve_project_root_identity(
        root, input_role=input_role, failure_id="WI-LEDGER-COMPAT-SET-TOPOLOGY",
    )
    location = resolve_ledger_h1_artifact_set_location(
        repository, input_role="repository-root",
    )
    if location is None or location.phase == "root":
        return None
    receipt_path = repository.joinpath(*PurePosixPath(location.receipt_path or "").parts)
    receipt, _raw = _ledger_h1_receipt_object(receipt_path)
    if (
        receipt.get("operationId") != request.operation_id
        or receipt.get("recordedAt") != request.recorded_at
        or receipt.get("archiveOwner") != request.archive_owner
        or location.artifact_set_sha256 != expected_artifact_set_sha256
        or receipt.get("rootContractBeforeSha256")
        != expected_root_contract_sha256
    ):
        _ledger_h1_relocation_fail("settled H1 replay inputs differ")
    return {
        "schemaVersion": 1,
        "status": "settled",
        "operationId": request.operation_id,
        "archiveOwner": request.archive_owner,
        "artifactBase": location.physical_base,
        "artifactSetSha256": location.artifact_set_sha256,
        "applied": applied,
        "replay": True,
        **({"event": LEDGER_H1_RELOCATION_EVENT} if applied else {}),
    }


def _relocate_ledger_h1_artifact_set_locked(
    root: Path,
    request: LedgerH1ArtifactSetRelocationRequestV1,
    *,
    inject_failure: str | None = None,
) -> dict[str, object]:
    if inject_failure not in {None, *LEDGER_H1_RELOCATION_FAILURE_BOUNDARIES}:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "unknown H1 relocation failure boundary",
        )
    _recover_all_transitions(root)
    replay = _ledger_h1_replay_result(
        root, request, applied=True, input_role="repository-root",
    )
    if replay is not None:
        return replay
    plan = _ledger_h1_relocation_preflight(root, request)
    intent = _ledger_h1_relocation_intent(plan, request)
    intent_path = _transition_intent_path(root, request.operation_id)
    if _ledger_h1_lexically_exists(intent_path):
        raise LifecycleError(
            "WI-LIFECYCLE-TRANSITION-INTENT-INVALID",
            "H1 relocation intent still exists after recovery",
        )
    intent_path.parent.mkdir(parents=True, exist_ok=True)
    _atomic_write(intent_path, _migration_receipt_bytes(intent))
    _transition_fsync_directory(intent_path.parent)
    receipt_committed = False
    try:
        if inject_failure == "after-intent":
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "injected failure after H1 relocation intent",
            )
        plan.artifact_base.mkdir()
        _transition_fsync_directory(plan.archive_owner)
        for index, member in enumerate(plan.members, start=1):
            source = plan.repository.joinpath(
                *PurePosixPath(str(member["sourcePath"])).parts
            )
            target = plan.repository.joinpath(
                *PurePosixPath(str(member["targetPath"])).parts
            )
            (_replace_lifecycle_directory(source, target) if member["kind"] == "directory" else _replace_lifecycle_directory(source, target, directory=False))
            _ledger_h1_intent_distribution(root, intent)
            if inject_failure == f"after-member-{index}":
                raise LifecycleError(
                    "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                    f"injected failure after H1 relocation member {index}",
                )
        _transition_fsync_directory(plan.work_items)
        _transition_fsync_directory(plan.artifact_base)
        if any(
            side != "target"
            for _member, _source, _target, side in _ledger_h1_intent_distribution(
                root, intent
            )
        ):
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "H1 relocation target validation is incomplete",
            )
        _ledger_h1_apply_contract_after(
            root,
            plan.root_contract_path,
            plan.root_contract_before,
            plan.root_contract_after,
        )
        if inject_failure == "after-root-contract":
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "injected failure after H1 root contract",
            )
        _ledger_h1_settle_receipt(root, intent)
        receipt_committed = True
        if inject_failure == "after-receipt":
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "injected failure after H1 relocation receipt",
            )
        location = resolve_ledger_h1_artifact_set_location(root)
        if (
            location is None
            or location.phase != "settled-archive"
            or location.artifact_set_sha256 != plan.artifact_set_sha256
        ):
            raise LifecycleError(
                "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
                "H1 relocation settlement cannot be proven",
            )
        _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
        _transition_fsync_directory(intent_path.parent)
        return _ledger_h1_relocation_result(
            plan,
            request,
            applied=True,
            replay=False,
        )
    except BaseException:
        if not receipt_committed:
            _ledger_h1_restore_before_receipt(root, intent_path, intent)
        raise


_relocate_ledger_h1_artifact_set_transaction = _lifecycle_participant(
    _relocate_ledger_h1_artifact_set_locked
)


def relocate_ledger_h1_artifact_set(
    root: Path,
    request: LedgerH1ArtifactSetRelocationRequestV1,
    *,
    apply: bool = False,
    inject_failure: str | None = None,
) -> dict[str, object]:
    if type(apply) is not bool:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-SET-TOPOLOGY",
            "H1 relocation apply must be an exact boolean",
        )
    if apply:
        return _relocate_ledger_h1_artifact_set_transaction(
            root,
            request,
            inject_failure=inject_failure,
        )
    if inject_failure is not None:
        raise LifecycleError(
            "WI-LEDGER-COMPAT-COMMIT-INDETERMINATE",
            "H1 artifact-set preflight forbids failure injection",
        )
    replay = _ledger_h1_replay_result(root, request, applied=False)
    if replay is not None:
        return replay
    plan = _ledger_h1_relocation_preflight(root, request)
    return _ledger_h1_relocation_result(
        plan,
        request,
        applied=False,
        replay=False,
    )


def _write_historical_artifact_disposition_locked(
    root: Path, disposition_bytes: bytes, *, allow_legacy: bool = False
) -> dict:
    validator = _load_agent_run_ledger().load_validator()
    dispositions = _historical_disposition_path(root, validator)
    try:
        disposition_cap, disposition_count_cap = validator.historical_artifact_disposition_resource_caps()
    except (AttributeError, TypeError, ValueError) as exc:
        _projection_fail(
            "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
            "historical disposition resource policy is unavailable or invalid",
        )
        raise AssertionError from exc
    if (
        type(disposition_cap) is not int
        or type(disposition_count_cap) is not int
        or disposition_cap < 1
        or disposition_count_cap < 1
    ):
        _projection_fail(
            "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
            "historical disposition resource policy is unavailable or invalid",
        )
    if len(disposition_bytes) > disposition_cap:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "historical disposition exceeds resource cap")
    disposition = _projection_object(disposition_bytes, "historical disposition")
    if not allow_legacy and disposition.get("schemaVersion") != 2:
        _projection_fail(
            "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
            "neutral historical disposition requires schemaVersion 2",
        )
    work_item = disposition.get("workItem")
    archive_identity = disposition.get("archiveIdentity")
    if not isinstance(work_item, str) or not isinstance(archive_identity, str):
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "historical disposition lacks exact identity")
    repository = Path(root).resolve()
    try:
        validator.confine_legacy_projection_identifier(
            archive_identity, failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY"
        )
        archive = validator.confine_legacy_projection_path(
            repository, work_item, prefix=("work-items", "archive"), leaf_kind="directory",
            failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY",
        )
    except ValueError as exc:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", f"historical artifact disposition target is unsafe: {exc}")
        raise AssertionError from exc
    if disposition.get("schemaVersion") == 2:
        ledger = archive / "agent-runs.jsonl"
        target_errors: list[str] = []
        classified = validator.classify_legacy_projection_target(
            archive, ledger, target_errors, require_ledger=True
        )
        if classified is None or target_errors:
            _projection_fail(
                "WI-LEDGER-MIGRATION-TARGET-IDENTITY",
                "; ".join(target_errors) or "archive ledger target is unsafe",
            )
        try:
            ledger_bytes = ledger.read_bytes()
        except OSError as exc:
            raise LifecycleError("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "archive ledger is unavailable") from exc
        raw_metadata: list[dict[str, object]] = []
        ledger_errors: list[str] = []
        events = validator.load_jsonl(ledger, ledger_errors, raw_metadata, ledger_bytes)
        exception, errors = validator.validate_historical_artifact_disposition_v2(
            disposition, archive, ledger_bytes, events, raw_metadata
        )
        if ledger_errors or errors or exception is None:
            _projection_fail(
                "WI-LEDGER-MIGRATION-MANIFEST-INVALID",
                "; ".join([*ledger_errors, *errors]) or "historical disposition does not authorize one missing artifact",
            )
        try:
            disposition_id = validator.confine_legacy_projection_identifier(
                disposition.get("dispositionId"), failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY"
            )
        except ValueError as exc:
            _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", f"disposition output identifier is unsafe: {exc}")
            raise AssertionError from exc
        target = _reserve_historical_disposition_output(
            dispositions, dispositions / f"{disposition_id}.json", disposition_count_cap
        )
        replay = _projection_create_or_exact(target, disposition_bytes, "WI-LEDGER-MIGRATION-MANIFEST-INVALID")
        return {"schemaVersion": 2, "dispositionId": disposition_id, "replay": replay}
    errors = validator.validate_manifest_bound_irrecoverable_disposition(disposition, archive_identity, archive)
    if errors:
        _projection_fail("WI-LEDGER-MIGRATION-MANIFEST-INVALID", "; ".join(errors))
    try:
        receipt = validator.confine_legacy_projection_path(
            repository, f"{work_item}/lifecycle-transition-receipt.json",
            prefix=("work-items", "archive"), leaf_kind="file",
            failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY",
        )
    except ValueError as exc:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", f"archive transition receipt is unsafe: {exc}")
        raise AssertionError from exc
    try:
        observed = json.loads(receipt.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise LifecycleError("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "archive identity receipt is unavailable") from exc
    if not isinstance(observed, dict) or observed.get("operationId") != archive_identity:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", "archive identity differs")
    try:
        archive_identity = validator.confine_legacy_projection_identifier(
            archive_identity, failure_id="WI-LEDGER-MIGRATION-TARGET-IDENTITY"
        )
    except ValueError as exc:
        _projection_fail("WI-LEDGER-MIGRATION-TARGET-IDENTITY", f"disposition output identifier is unsafe: {exc}")
        raise AssertionError from exc
    target = _reserve_historical_disposition_output(
        dispositions, dispositions / f"{archive_identity}.json", disposition_count_cap
    )
    replay = _projection_create_or_exact(target, disposition_bytes, "WI-LEDGER-MIGRATION-MANIFEST-INVALID")
    return {"schemaVersion": 1, "archiveIdentity": archive_identity, "replay": replay}


_write_historical_artifact_disposition_transaction = _lifecycle_participant(
    _write_historical_artifact_disposition_locked
)


def write_historical_artifact_disposition(root: Path, disposition_bytes: bytes) -> dict:
    """Write/replay one neutral V2 historical disposition."""
    return _write_historical_artifact_disposition_transaction(root, disposition_bytes)


def _write_legacy_ledger_irrecoverable_disposition_locked(root: Path, disposition_bytes: bytes) -> dict:
    """Compatibility adapter for the legacy V1/V2 command and Python surface."""
    return _write_historical_artifact_disposition_locked(
        root, disposition_bytes, allow_legacy=True
    )


_write_legacy_ledger_irrecoverable_disposition_transaction = _lifecycle_participant(
    _write_legacy_ledger_irrecoverable_disposition_locked
)


def write_legacy_ledger_irrecoverable_disposition(root: Path, disposition_bytes: bytes) -> dict:
    return _write_legacy_ledger_irrecoverable_disposition_transaction(root, disposition_bytes)


def _successor_import_tree(root: Path) -> list[tuple[str, bytes]]:
    """Capture every ordinary leaf without following a source or archive alias."""

    failure = "WI-SUCCESSOR-IMPORT-UNSAFE-INPUT"
    _lifecycle_reject_unreduced_reparse(root, failure_id=failure, message="unsafe tree root")
    try:
        if not stat.S_ISDIR(root.lstat().st_mode):
            raise OSError("tree root is not a directory")
    except OSError as exc:
        raise LifecycleError(failure, "tree root is unavailable") from exc
    pending = [root]
    files: list[tuple[str, bytes]] = []
    while pending:
        directory = pending.pop()
        try:
            with os.scandir(directory) as iterator:
                children = sorted(iterator, key=lambda entry: entry.name)
        except OSError as exc:
            raise LifecycleError(failure, "tree cannot be enumerated") from exc
        for entry in children:
            path = Path(entry.path)
            try:
                info = entry.stat(follow_symlinks=False)
                unsafe = entry.is_symlink() or bool(
                    getattr(info, "st_file_attributes", 0)
                    & getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0)
                )
            except OSError as exc:
                raise LifecycleError(failure, "tree entry cannot be inspected") from exc
            if unsafe:
                raise LifecycleError(failure, "tree contains a link or reparse entry")
            if stat.S_ISDIR(info.st_mode):
                pending.append(path)
            elif stat.S_ISREG(info.st_mode):
                snapshot = _capture_file_snapshot(
                    path, failure_id=failure,
                    maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
                    require_single_link=True,
                )
                files.append((path.relative_to(root).as_posix(), snapshot.data))
            else:
                raise LifecycleError(failure, "tree contains a nonordinary entry")
    return sorted(files)


def _successor_import_tree_digest(files: Iterable[tuple[str, bytes]]) -> str:
    digest = hashlib.sha256()
    for path, data in files:
        name = path.encode("utf-8")
        digest.update(len(name).to_bytes(8, "big"))
        digest.update(name)
        digest.update(len(data).to_bytes(8, "big"))
        digest.update(data)
    return digest.hexdigest()


def _successor_import_index(
    work_items: Path, old: str, new: str, disposition: dict,
) -> tuple[dict, bytes]:
    failure = "WI-SUCCESSOR-LINK-UNMAPPED"
    path = work_items / "index.md"
    before = _capture_file_snapshot(
        path, failure_id=failure, maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
        require_single_link=True,
    ).data
    try:
        text = before.decode("utf-8")
    except UnicodeError as exc:
        raise LifecycleError(failure, "compatibility index is not UTF-8") from exc
    row_before = disposition.get("indexRowBefore")
    row_after = disposition.get("indexRowAfter")
    if not all(isinstance(row, str) and row.endswith("\n") for row in (row_before, row_after)):
        raise LifecycleError(failure, "one complete index row disposition is required")
    rows = text.splitlines(keepends=True)
    old_status = work_items / "active" / old / "status.md"
    new_status = work_items / "active" / new / "status.md"
    old_active = work_items / "active" / old
    old_rows = [
        row for row in rows
        if any(_markdown_href_resolves(path.parent, link.href, old_status)
               for link in _markdown_local_links(row))
    ]
    if len(old_rows) != 1 or old_rows[0] != row_before or rows.count(row_before) != 1:
        raise LifecycleError(failure, "index old-active row is absent or ambiguous")
    old_root = old_active.resolve()
    old_targets = [
        target
        for row in rows for link in _markdown_local_links(row)
        if (parts := _local_markdown_href_parts(link.href)) is not None
        for target in ((path.parent / parts[0]).resolve(),)
        if target == old_root or old_root in target.parents
    ]
    if old_targets != [old_status.resolve()]:
        raise LifecycleError(failure, "index contains another old-active link")
    after_links = list(_markdown_local_links(row_after))
    visible_row = row_after
    for link in reversed(after_links):
        visible_row = visible_row[:link.href_start] + visible_row[link.href_end:]
    def names_visible_slug(slug: str) -> bool:
        return re.search(
            rf"(?<![A-Za-z0-9_.-]){re.escape(slug)}(?![A-Za-z0-9_.-])",
            visible_row,
        ) is not None

    if not names_visible_slug(new) or names_visible_slug(old) or sum(
        _markdown_href_resolves(path.parent, link.href, new_status) for link in after_links
    ) != 1 or any(
        (path.parent / parts[0]).resolve() == old_active.resolve()
        or old_active.resolve() in (path.parent / parts[0]).resolve().parents
        for link in after_links
        if (parts := _local_markdown_href_parts(link.href)) is not None
    ):
        raise LifecycleError(failure, "replacement index row does not name the successor status")
    after = text.replace(row_before, row_after, 1).encode("utf-8")
    return {
        "path": "work-items/index.md",
        "beforeSha256": _sha256_bytes(before),
        "afterSha256": _sha256_bytes(after),
        "afterBase64": _b64(after),
        "targetPath": f"work-items/active/{new}/status.md",
    }, after


def _successor_import_links(
    root: Path, work_items: Path, source: Path, new: str,
    bindings: list[dict], dispositions: dict,
) -> list[dict]:
    failure = "WI-SUCCESSOR-LINK-UNMAPPED"
    reference = f"work-item:{source.name}"
    try:
        observed = _incoming_link_result(
            root, [source], reference, strict_consumer_reads=True,
        )["references"]
    except LifecycleError as exc:
        raise LifecycleError(failure, "incoming-link scan could not classify consumers") from exc
    supplied = dispositions.get("references")
    if not isinstance(supplied, list) or any(not isinstance(row, dict) for row in supplied):
        raise LifecycleError(failure, "incoming references require an exact disposition list")
    if any(
        not all(isinstance(row.get(field), str) for field in ("consumer", "kind", "value"))
        for row in supplied
    ):
        raise LifecycleError(failure, "incoming references require string identities")
    for row in supplied:
        required = (
            {"consumer", "kind", "value", "target"}
            if row["kind"] == "physical"
            else {"consumer", "kind", "value", "meaning"}
        )
        choice = row.get("target") if row["kind"] == "physical" else row.get("meaning")
        if row["kind"] not in {"physical", "logical"} or set(row) != required or not isinstance(choice, str):
            raise LifecycleError(failure, "incoming reference disposition has invalid shape")
    def key(row: dict) -> tuple:
        return row.get("consumer"), row.get("kind"), row.get("value")
    observed_keys = [key(row) for row in observed]
    supplied_keys = [key(row) for row in supplied]
    if Counter(observed_keys) != Counter(supplied_keys) or len(set(supplied_keys)) != len(supplied_keys):
        raise LifecycleError(failure, "incoming-reference dispositions are incomplete or ambiguous")
    allowed_targets = {row["targetPath"] for row in bindings}
    allowed_targets.add(f"work-items/active/{new}/status.md")
    plans: list[dict] = []
    for consumer_name in sorted({row["consumer"] for row in supplied}):
        relative = PurePosixPath(consumer_name)
        if (not consumer_name or relative.is_absolute() or ".." in relative.parts
                or relative.parts[0] == "archive" or ":" in consumer_name
                or "\\" in consumer_name):
            raise LifecycleError(failure, "incoming consumer is not a mutable work-item file")
        consumer = work_items.joinpath(*relative.parts)
        before = _capture_file_snapshot(
            consumer, failure_id=failure,
            maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
            require_single_link=True,
        ).data
        try:
            text = before.decode("utf-8")
        except UnicodeError as exc:
            raise LifecycleError(failure, "incoming consumer is not UTF-8") from exc
        replacements: list[tuple[int, int, str]] = []
        for row in (item for item in supplied if item["consumer"] == consumer_name):
            if row["kind"] == "logical":
                if row.get("meaning") not in {"historical-predecessor", "current-successor"} or row["value"] != reference:
                    raise LifecycleError(failure, "logical reference has no reviewed meaning")
                if row["meaning"] == "current-successor":
                    if text.count(reference) != 1:
                        raise LifecycleError(failure, "current logical reference is ambiguous")
                continue
            if row["kind"] != "physical" or row.get("target") not in allowed_targets:
                raise LifecycleError(failure, "physical reference has no bound target")
            matches = [link for link in _markdown_local_links(text) if link.href == row["value"]]
            if len(matches) != 1:
                raise LifecycleError(failure, "physical reference occurrence is ambiguous")
            target = work_items.parent.joinpath(*PurePosixPath(row["target"]).parts)
            suffix = _local_markdown_href_parts(row["value"])
            if suffix is None:
                raise LifecycleError(failure, "physical reference is not local")
            new_href = _relative_link(consumer.parent, target) + suffix[1]
            replacements.append((matches[0].href_start, matches[0].href_end, new_href))
        for start, end, new_href in sorted(replacements, reverse=True):
            text = text[:start] + new_href + text[end:]
        if any(
            row["kind"] == "logical" and row["meaning"] == "current-successor"
            for row in supplied if row["consumer"] == consumer_name
        ):
            text = text.replace(reference, f"work-item:{new}", 1)
        after = text.encode("utf-8")
        plans.append({
            "consumer": f"work-items/{consumer_name}",
            "beforeSha256": _sha256_bytes(before),
            "afterSha256": _sha256_bytes(after),
            "afterBase64": _b64(after),
            "references": sorted(
                (row for row in supplied if row["consumer"] == consumer_name),
                key=lambda row: (row["kind"], row["value"]),
            ),
        })
    return plans


def _successor_import_shadow_readme(
    root: Path, work_items: Path, source: Path, new: str, status_data: bytes,
    static_guide: str, links: list[dict], index_after: bytes,
) -> tuple[bytes, list[dict]]:
    planned_inputs: dict[str, bytes] = {}
    with tempfile.TemporaryDirectory(prefix="work-items-successor-readme-") as directory:
        shadow_root = Path(directory)
        shadow_work_items = shadow_root / "work-items"
        try:
            shutil.copytree(work_items, shadow_work_items, symlinks=True)
            shutil.rmtree(shadow_work_items / source.relative_to(work_items))
            shadow_status = shadow_work_items / "active" / new / "status.md"
            shadow_status.parent.mkdir(parents=True)
            shadow_status.write_bytes(status_data)
            (shadow_work_items / "index.md").write_bytes(index_after)
            for link in links:
                relative = PurePosixPath(link["consumer"]).relative_to("work-items")
                after = base64.b64decode(link["afterBase64"], validate=True)
                shadow_work_items.joinpath(*relative.parts).write_bytes(after)
                planned_inputs[relative.as_posix()] = after
            transaction_token = _CURRENT_LIFECYCLE_TRANSACTION.set(None)
            composer_token = _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.set(None)
            try:
                rendered = render_readme_bytes(
                    shadow_root, static_guide_override=static_guide,
                )
                entries = collect_readme_entries(shadow_root)
                sources = sorted({
                    path.relative_to(shadow_work_items).as_posix()
                    for entry in entries for path in entry.source_paths
                })
            finally:
                _CURRENT_LIFECYCLE_OUTCOME_COMPOSER.reset(composer_token)
                _CURRENT_LIFECYCLE_TRANSACTION.reset(transaction_token)
        except (LifecycleError, OSError) as exc:
            raise LifecycleError(
                "WI-SUCCESSOR-READMODEL-INVALID", "unique-location shadow cannot render"
            ) from exc
    snapshot = []
    for relative in sources:
        if relative == f"active/{new}/status.md":
            data = status_data
        elif relative in planned_inputs:
            data = planned_inputs[relative]
        else:
            data = _capture_file_snapshot(
                work_items.joinpath(*PurePosixPath(relative).parts),
                failure_id="WI-SUCCESSOR-READMODEL-INVALID",
                maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
                require_single_link=True,
            ).data
        snapshot.append({"path": f"work-items/{relative}", "sha256": _sha256_bytes(data)})
    return rendered, snapshot


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'predecessor_slug'))
def preflight_import_active_successor(
    root: Path, predecessor_slug: str, successor_slug: str, status_data: bytes,
    dispositions: dict, operation_id: str,
) -> dict:
    """Bind one exceptional dual-location import; never write to the candidate."""

    _validate_slug(successor_slug)
    if predecessor_slug.casefold() == successor_slug.casefold() or not re.fullmatch(
        r"[A-Za-z0-9][A-Za-z0-9._-]{0,127}", operation_id or ""
    ):
        raise LifecycleError("WI-SUCCESSOR-IDENTITY-CONFLICT", "distinct identity and bounded operation ID required")
    if not isinstance(dispositions, dict) or set(dispositions) != {
        "indexRowBefore", "indexRowAfter", "references",
    }:
        raise LifecycleError("WI-SUCCESSOR-LINK-UNMAPPED", "link dispositions have invalid shape")
    _validate_active_status_bytes(status_data)
    occurrences = _authoritative_field_occurrences(status_data.decode("utf-8"))
    fields = _parse_fields(status_data.decode("utf-8"))
    if (fields.get("template") != "staged" or fields.get("status") != "active"
            or fields.get("reopens") != predecessor_slug
            or sum(name == "reopens" for _, name, _, _ in occurrences) != 1):
        raise LifecycleError("WI-CATEGORY-STATUS-INVALID", "successor status must be staged, active and reopen the predecessor")
    work_items = _work_items_root(root)
    predecessor = CATEGORIES["work-item"]
    locations = _category_locations(root, predecessor, predecessor_slug)
    active = work_items / "active" / predecessor_slug
    archives = [path for path in locations if path.parent.parent == work_items / "archive"]
    def occupied(path: Path) -> bool:
        try:
            path.lstat()
            return True
        except FileNotFoundError:
            return False
        except OSError as exc:
            raise LifecycleError("WI-SUCCESSOR-IDENTITY-CONFLICT", "identity location cannot be inspected") from exc

    archive_root = work_items / "archive"
    months = [path for path in archive_root.iterdir() if path.is_dir()] if archive_root.is_dir() else []
    def occupied_locations(slug: str) -> set[Path]:
        candidates = [work_items / "backlog" / f"{slug}.md", work_items / "active" / slug]
        candidates.extend(month / slug for month in months)
        return {path for path in candidates if occupied(path)}

    if (len(locations) != 2 or active not in locations or len(archives) != 1
            or occupied_locations(predecessor_slug) != {active, archives[0]}
            or occupied_locations(successor_slug)):
        raise LifecycleError("WI-SUCCESSOR-IDENTITY-CONFLICT", "predecessor dual pair or empty successor identity is absent")
    archive = archives[0]
    source_files = _successor_import_tree(active)
    archive_files = _successor_import_tree(archive)
    source_map = dict(source_files)
    archive_map = dict(archive_files)
    if (not source_files or "status.md" not in source_map
            or "agent-runs.jsonl" not in source_map
            or "agent-runs.jsonl" not in archive_map
            or "bug-dispositions-receipt.json" not in archive_map):
        raise LifecycleError("WI-SUCCESSOR-IMPORT-UNSAFE-INPUT", "source or archive lacks required leaves")
    _status_entry(root, active)
    ledger = source_map["agent-runs.jsonl"]
    archived_ledger = archive_map["agent-runs.jsonl"]
    if (not ledger or not ledger.endswith(b"\n") or not archived_ledger.startswith(ledger)):
        raise LifecycleError("WI-SUCCESSOR-LEDGER-DIVERGENCE", "source ledger is not an exact archived prefix")
    errors, _events, _runtime = _validator_module().validate_archived_ledger_obligations(archive)
    if errors:
        raise LifecycleError("WI-SUCCESSOR-LEDGER-DIVERGENCE", "; ".join(errors))
    bindings = []
    for relative, data in source_files:
        if relative == "agent-runs.jsonl":
            kind = "archive-ledger-prefix"
            target = archive / relative
        elif relative != "status.md" and relative in archive_map and archive_map[relative] == data:
            kind = "archive-equal"
            target = archive / relative
        else:
            kind = "successor-copy"
            target = work_items / "active" / successor_slug / "imported-source" / relative
        bindings.append({
            "sourceRelativePath": relative,
            "sourceSha256": _sha256_bytes(data),
            "kind": kind,
            "targetPath": f"work-items/{target.relative_to(work_items).as_posix()}",
        })
    index, index_after = _successor_import_index(
        work_items, predecessor_slug, successor_slug, dispositions,
    )
    links = _successor_import_links(
        root, work_items, active, successor_slug, bindings, dispositions,
    )
    readme_path = work_items / "README.md"
    readme_before = _capture_file_snapshot(
        readme_path, failure_id="WI-README-MARKERS",
        maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP,
        require_single_link=True,
    ).data
    static_guide = _static_guide(readme_path)
    readme_after, canonical_inputs = _successor_import_shadow_readme(
        root, work_items, active, successor_slug, status_data, static_guide,
        links, index_after,
    )
    if (readme_after.count(f"active/{successor_slug}/status.md".encode()) < 1
            or readme_after.count(f"archive/{archive.parent.name}/{predecessor_slug}/closure.md".encode()) != 1):
        raise LifecycleError("WI-SUCCESSOR-READMODEL-INVALID", "shadow does not contain one successor and predecessor archive")
    readme = {
        "path": "work-items/README.md",
        "beforeSha256": _sha256_bytes(readme_before),
        "afterSha256": _sha256_bytes(readme_after),
        "afterBase64": _b64(readme_after),
    }
    wire = {
        "schemaVersion": 1,
        "owner": "mutate-work-item:import-active-successor-preflight-v1",
        "operationId": operation_id,
        "predecessor": predecessor_slug,
        "successor": successor_slug,
        "sourceTreeSha256": _successor_import_tree_digest(source_files),
        "archiveTreeSha256": _successor_import_tree_digest(archive_files),
        "archiveReceiptSha256": _sha256_bytes(archive_map["bug-dispositions-receipt.json"]),
        "archiveFiles": [
            {"path": relative, "sha256": _sha256_bytes(data)}
            for relative, data in archive_files
        ],
        "fileBindings": bindings,
        "ledgerArchivePrefix": {
            "byteCount": len(ledger), "lineCount": len(ledger.splitlines()),
            "prefixSha256": _sha256_bytes(ledger),
            "archiveLedgerSha256": _sha256_bytes(archived_ledger),
        },
        "statusSha256": _sha256_bytes(status_data),
        "compatibilityIndex": index,
        "links": links,
        "readme": readme,
        "canonicalInputs": canonical_inputs,
    }
    canonical = (json.dumps(wire, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")
    return {
        **wire, "digest": _sha256_bytes(canonical), "canonicalBytes": canonical,
        "compatibilityIndex": {**index, "afterBytes": index_after},
        "readme": {**readme, "afterBytes": readme_after},
    }


def _successor_import_plan_bytes(plan: dict) -> bytes:
    return (json.dumps(plan, sort_keys=True, separators=(",", ":")) + "\n").encode("utf-8")


def _successor_import_stage_paths(operation_id: str) -> tuple[str, str]:
    base = f".scratch/work-items-lifecycle-successor-imports/{operation_id}"
    return f"{base}/source", f"{base}/successor"


def _validate_successor_import_intent(
    root: Path, path: Path, intent: dict, raw: bytes,
) -> None:
    failure = "WI-SUCCESSOR-IMPORT-RECOVERY"
    operation = intent.get("operationId")
    plan = intent.get("plan")
    if (
        intent.get("status") != "intent"
        or not isinstance(operation, str)
        or not isinstance(plan, dict)
        or raw != _migration_receipt_bytes(intent)
        or path.absolute() != _transition_intent_path(root, operation).absolute()
    ):
        raise LifecycleError(failure, "successor import intent shape or identity differs")
    if (
        plan.get("schemaVersion") != 1
        or set(plan) != SUCCESSOR_IMPORT_PLAN_FIELDS
        or plan.get("owner") != "mutate-work-item:import-active-successor-preflight-v1"
        or plan.get("operationId") != operation
        or not isinstance(plan.get("predecessor"), str)
        or not isinstance(plan.get("successor"), str)
        or not isinstance(intent.get("preflightDigest"), str)
        or _sha256_bytes(_successor_import_plan_bytes(plan)) != intent["preflightDigest"]
    ):
        raise LifecycleError(failure, f"operation={operation} phase=intent plan digest differs")
    old, new = plan["predecessor"], plan["successor"]
    _validate_slug(old)
    _validate_slug(new)
    hold, stage = _successor_import_stage_paths(operation)
    archive_parts = PurePosixPath(intent.get("archivePath", "")).parts
    if (
        intent.get("sourcePath") != f"work-items/active/{old}"
        or intent.get("successorPath") != f"work-items/active/{new}"
        or len(archive_parts) != 4
        or archive_parts[:2] != ("work-items", "archive")
        or not re.fullmatch(r"\d{4}-\d{2}", archive_parts[2])
        or archive_parts[3] != old
        or intent.get("sourceHoldPath") != hold
        or intent.get("successorStagePath") != stage
        or intent.get("receiptPath") != f"work-items/active/{new}/{SUCCESSOR_IMPORT_RECEIPT}"
    ):
        raise LifecycleError(failure, f"operation={operation} phase=intent paths differ")
    try:
        status_data = base64.b64decode(intent["statusData"], validate=True)
    except (KeyError, TypeError, ValueError) as exc:
        raise LifecycleError(failure, f"operation={operation} phase=intent status differs") from exc
    if _sha256_bytes(status_data) != plan.get("statusSha256"):
        raise LifecycleError(failure, f"operation={operation} phase=intent status hash differs")
    expected_images = {}
    for row in (*plan.get("links", []), plan.get("compatibilityIndex"), plan.get("readme")):
        if not isinstance(row, dict):
            raise LifecycleError(failure, f"operation={operation} phase=intent image plan differs")
        name = row.get("consumer", row.get("path"))
        if not isinstance(name, str) or name in expected_images:
            raise LifecycleError(failure, f"operation={operation} phase=intent image path differs")
        expected_images[name] = row
    images = intent.get("images")
    if not isinstance(images, list) or [row.get("path") for row in images if isinstance(row, dict)] != sorted(expected_images):
        raise LifecycleError(failure, f"operation={operation} phase=intent image set differs")
    for image in images:
        if not isinstance(image, dict) or set(image) != {
            "path", "beforeBase64", "afterBase64", "beforeSha256", "afterSha256",
        }:
            raise LifecycleError(failure, f"operation={operation} phase=intent image shape differs")
        name = image["path"]
        planned = expected_images.get(name)
        if planned is None or not name.startswith("work-items/") or "\\" in name:
            raise LifecycleError(failure, f"operation={operation} phase=intent image is outside work-items")
        physical = _intent_path(root, name)
        parts = PurePosixPath(name).parts
        if (
            ".." in parts or "archive" in parts or
            parts[:3] in {("work-items", "active", old), ("work-items", "active", new)}
        ):
            raise LifecycleError(failure, f"operation={operation} phase=intent image is immutable")
        if physical != _intent_path(root, planned.get("consumer", planned.get("path"))):
            raise LifecycleError(failure, f"operation={operation} phase=intent image target differs")
        try:
            before = base64.b64decode(image["beforeBase64"], validate=True)
            after = base64.b64decode(image["afterBase64"], validate=True)
        except (TypeError, ValueError) as exc:
            raise LifecycleError(failure, f"operation={operation} phase=intent image encoding differs") from exc
        if (
            _sha256_bytes(before) != image["beforeSha256"]
            or _sha256_bytes(after) != image["afterSha256"]
            or image["beforeSha256"] != planned.get("beforeSha256")
            or image["afterSha256"] != planned.get("afterSha256")
            or image["afterBase64"] != planned.get("afterBase64")
        ):
            raise LifecycleError(failure, f"operation={operation} phase=intent image hash differs")
    for name in (
        "sourcePath", "archivePath", "successorPath", "sourceHoldPath",
        "successorStagePath", "receiptPath",
    ):
        _intent_path(root, intent[name])


def _successor_import_source_bytes(path: Path, plan: dict, failure: str) -> dict[str, bytes]:
    try:
        files = _successor_import_tree(path)
    except LifecycleError as exc:
        raise LifecycleError(failure, "source tree cannot be captured") from exc
    expected = {row["sourceRelativePath"]: row["sourceSha256"] for row in plan["fileBindings"]}
    if (
        len(expected) != len(plan["fileBindings"])
        or {name: _sha256_bytes(data) for name, data in files} != expected
        or _successor_import_tree_digest(files) != plan["sourceTreeSha256"]
    ):
        raise LifecycleError(failure, "source tree differs from bound preflight")
    return dict(files)


def _successor_import_archive_bytes(path: Path, plan: dict, failure: str) -> dict[str, bytes]:
    try:
        files = _successor_import_tree(path)
    except LifecycleError as exc:
        raise LifecycleError(failure, "archive tree cannot be captured") from exc
    expected = {row["path"]: row["sha256"] for row in plan["archiveFiles"]}
    if (
        len(expected) != len(plan["archiveFiles"])
        or {name: _sha256_bytes(data) for name, data in files} != expected
        or _successor_import_tree_digest(files) != plan["archiveTreeSha256"]
        or _sha256_bytes(dict(files)["bug-dispositions-receipt.json"]) != plan["archiveReceiptSha256"]
    ):
        raise LifecycleError(failure, "archive tree differs from bound preflight")
    return dict(files)


def _successor_import_successor_files(
    plan: dict, status_data: bytes, source_files: dict[str, bytes],
) -> dict[str, bytes]:
    expected = {"status.md": status_data}
    for row in plan["fileBindings"]:
        if row["kind"] == "successor-copy":
            expected[f"imported-source/{row['sourceRelativePath']}"] = source_files[row["sourceRelativePath"]]
    return expected


def _successor_import_check_stage(
    path: Path, expected: dict[str, bytes], *, complete: bool,
) -> None:
    failure = "WI-SUCCESSOR-IMPORT-RECOVERY"
    if not path.exists():
        if complete:
            raise LifecycleError(failure, f"stage is absent: {path.name}")
        return
    try:
        observed = dict(_successor_import_tree(path))
    except LifecycleError as exc:
        raise LifecycleError(failure, f"stage is unsafe: {path.name}") from exc
    if any(name not in expected or data != expected[name] for name, data in observed.items()):
        raise LifecycleError(failure, f"stage bytes differ: {path.name}")
    if complete and set(observed) != set(expected):
        raise LifecycleError(failure, f"stage is incomplete: {path.name}")


def _successor_import_images(root: Path, plan: dict) -> list[dict]:
    images = []
    for row in (*plan["links"], plan["compatibilityIndex"], plan["readme"]):
        name = row.get("consumer", row.get("path"))
        path = _intent_path(root, name)
        before = _capture_file_snapshot(
            path, failure_id="WI-SUCCESSOR-IMPORT-DRIFT",
            maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP, require_single_link=True,
        ).data
        after = base64.b64decode(row["afterBase64"], validate=True)
        if _sha256_bytes(before) != row["beforeSha256"] or _sha256_bytes(after) != row["afterSha256"]:
            raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", f"bound image changed: {name}")
        images.append({
            "path": name, "beforeBase64": _b64(before), "afterBase64": _b64(after),
            "beforeSha256": row["beforeSha256"], "afterSha256": row["afterSha256"],
        })
    return sorted(images, key=lambda row: row["path"])


def _successor_import_receipt(
    plan: dict, digest: str, dispositions: dict, successor_tree_sha256: str,
) -> dict:
    return {
        **plan,
        "owner": SUCCESSOR_IMPORT_OWNER,
        "state": "committed",
        "preflightDigest": digest,
        "dispositionsSha256": _sha256_bytes(_successor_import_plan_bytes(dispositions)),
        "successorTreeSha256ExcludingReceipt": successor_tree_sha256,
        "receiptPath": f"work-items/active/{plan['successor']}/{SUCCESSOR_IMPORT_RECEIPT}",
    }


def _successor_import_reconstruct_source(root: Path, receipt: dict) -> dict[str, bytes]:
    failure = "WI-SUCCESSOR-IMPORT-RECOVERY"
    source: dict[str, bytes] = {}
    for row in receipt["fileBindings"]:
        target = _intent_path(root, row["targetPath"])
        try:
            data = _capture_file_snapshot(
                target, failure_id=failure,
                maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP, require_single_link=True,
            ).data
        except LifecycleError as exc:
            raise LifecycleError(failure, f"settled binding is absent: {row['sourceRelativePath']}") from exc
        if row["kind"] == "archive-ledger-prefix":
            byte_count = receipt["ledgerArchivePrefix"]["byteCount"]
            data = data[:byte_count]
        if _sha256_bytes(data) != row["sourceSha256"]:
            raise LifecycleError(failure, f"settled binding differs: {row['sourceRelativePath']}")
        source[row["sourceRelativePath"]] = data
    if (
        len(source) != len(receipt["fileBindings"])
        or _successor_import_tree_digest(sorted(source.items())) != receipt["sourceTreeSha256"]
    ):
        raise LifecycleError(failure, "settled source map is incomplete")
    return source


def _verify_successor_import_settlement(
    root: Path, receipt_path: Path,
    *, operation_id: str | None = None, digest: str | None = None,
    predecessor: str | None = None, successor: str | None = None,
    status_data: bytes | None = None, dispositions: dict | None = None,
) -> dict:
    failure = "WI-SUCCESSOR-IMPORT-RECOVERY"
    try:
        raw = _capture_file_snapshot(
            receipt_path, failure_id=failure,
            maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP, require_single_link=True,
        ).data
        receipt = json.loads(raw.decode("utf-8"))
    except (LifecycleError, OSError, UnicodeError, ValueError) as exc:
        raise LifecycleError(failure, "successor receipt cannot be read") from exc
    if (
        not isinstance(receipt, dict)
        or set(receipt) != SUCCESSOR_IMPORT_RECEIPT_FIELDS
        or raw != _migration_receipt_bytes(receipt)
        or receipt.get("schemaVersion") != 1
        or receipt.get("owner") != SUCCESSOR_IMPORT_OWNER
        or receipt.get("state") != "committed"
        or receipt.get("receiptPath") != receipt_path.relative_to(_work_items_root(root).parent).as_posix()
    ):
        raise LifecycleError(failure, "successor receipt shape or location differs")
    preflight_wire = {key: receipt[key] for key in SUCCESSOR_IMPORT_PLAN_FIELDS}
    preflight_wire["owner"] = "mutate-work-item:import-active-successor-preflight-v1"
    if _sha256_bytes(_successor_import_plan_bytes(preflight_wire)) != receipt["preflightDigest"]:
        raise LifecycleError(failure, "successor receipt preflight binding differs")
    if (
        (operation_id is not None and receipt.get("operationId") != operation_id)
        or (digest is not None and receipt.get("preflightDigest") != digest)
        or (predecessor is not None and receipt.get("predecessor") != predecessor)
        or (successor is not None and receipt.get("successor") != successor)
        or (status_data is not None and receipt.get("statusSha256") != _sha256_bytes(status_data))
        or (
            dispositions is not None
            and receipt.get("dispositionsSha256")
            != _sha256_bytes(_successor_import_plan_bytes(dispositions))
        )
    ):
        raise LifecycleError("WI-SUCCESSOR-IDENTITY-CONFLICT", "settled replay inputs differ")
    work_items = _work_items_root(root)
    old, new = receipt["predecessor"], receipt["successor"]
    archive = work_items / "archive"
    archives = [path for path in archive.glob(f"*/{old}") if path.is_dir()]
    if len(archives) != 1 or (work_items / "active" / old).exists():
        raise LifecycleError(failure, "settled predecessor identity differs")
    _successor_import_archive_bytes(archives[0], receipt, failure)
    active = work_items / "active" / new
    if not active.is_dir() or (active / "agent-runs.jsonl").exists():
        raise LifecycleError(failure, "settled successor identity differs")
    files = dict(_successor_import_tree(active))
    if SUCCESSOR_IMPORT_RECEIPT not in files or files[SUCCESSOR_IMPORT_RECEIPT] != raw:
        raise LifecycleError(failure, "settled successor receipt is not in its tree")
    files.pop(SUCCESSOR_IMPORT_RECEIPT)
    if _successor_import_tree_digest(sorted(files.items())) != receipt.get("successorTreeSha256ExcludingReceipt"):
        raise LifecycleError(failure, "settled successor tree differs")
    _successor_import_reconstruct_source(root, receipt)
    for row in (*receipt["links"], receipt["compatibilityIndex"], receipt["readme"]):
        path = _intent_path(root, row.get("consumer", row.get("path")))
        observed = _capture_file_snapshot(
            path, failure_id=failure,
            maximum_bytes=LEDGER_LOCATION_PROOF_BYTE_CAP, require_single_link=True,
        ).data
        if _sha256_bytes(observed) != row["afterSha256"]:
            raise LifecycleError(failure, f"settled consumer differs: {path.name}")
    index_target = _intent_path(root, receipt["compatibilityIndex"]["targetPath"])
    if not index_target.is_file() or index_target != active / "status.md":
        raise LifecycleError("WI-SUCCESSOR-LINK-UNMAPPED", "settled index target differs")
    for consumer in receipt["links"]:
        for row in consumer["references"]:
            if row["kind"] == "physical" and not _intent_path(root, row["target"]).is_file():
                raise LifecycleError("WI-SUCCESSOR-LINK-UNMAPPED", "settled physical target is absent")
    check_readme(root)
    if (
        resolve_category(root, f"work-item:{old}") != archives[0]
        or resolve_category(root, f"work-item:{new}") != active
    ):
        raise LifecycleError(failure, "settled category readback differs")
    return receipt


def _successor_import_release_stage_parent(stage_root: Path) -> None:
    parent = stage_root.parent
    if not parent.exists():
        return
    _lifecycle_reject_unreduced_reparse(
        parent, failure_id="WI-SUCCESSOR-IMPORT-RECOVERY",
        message="successor staging parent is unsafe",
    )
    try:
        parent.rmdir()
    except OSError as exc:
        if any(parent.iterdir()):
            return
        raise LifecycleError(
            "WI-SUCCESSOR-IMPORT-RECOVERY", "empty successor staging parent remains"
        ) from exc


@_lifecycle_participant
def _recover_successor_import(root: Path, intent_path: Path, intent: dict) -> dict | None:
    operation = intent["operationId"]
    failure = "WI-SUCCESSOR-IMPORT-RECOVERY"
    try:
        repository = _work_items_root(root).parent
        source = _intent_path(repository, intent["sourcePath"])
        archive = _intent_path(repository, intent["archivePath"])
        successor = _intent_path(repository, intent["successorPath"])
        hold = _intent_path(repository, intent["sourceHoldPath"])
        stage = _intent_path(repository, intent["successorStagePath"])
        stage_root = hold.parent
        receipt_path = _intent_path(repository, intent["receiptPath"])
        plan = intent["plan"]
        status_data = base64.b64decode(intent["statusData"], validate=True)
        if stage_root.exists():
            if not stage_root.is_dir() or _lifecycle_path_has_reparse(stage_root):
                raise LifecycleError(failure, "stage root is unsafe")
            with os.scandir(stage_root) as entries:
                if {entry.name for entry in entries} - {"source", "successor"}:
                    raise LifecycleError(failure, "stage root has an unowned member")
        _successor_import_archive_bytes(archive, plan, failure)
        if receipt_path.exists():
            settled = _verify_successor_import_settlement(
                repository, receipt_path,
                operation_id=operation, digest=intent["preflightDigest"],
                predecessor=plan["predecessor"], successor=plan["successor"],
                status_data=status_data,
            )
            original = _successor_import_reconstruct_source(repository, settled)
            expected_successor = _successor_import_successor_files(plan, status_data, original)
            _successor_import_check_stage(hold, original, complete=False)
            _successor_import_check_stage(stage, expected_successor, complete=False)
            if stage_root.exists():
                _remove_scratch_tree(stage_root)
            _successor_import_release_stage_parent(stage_root)
            _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
            return settled
        source_here = source.is_dir()
        hold_here = hold.is_dir()
        if source_here == hold_here:
            raise LifecycleError(failure, "source and held custody are missing or duplicated")
        source_files = _successor_import_source_bytes(
            source if source_here else hold, plan, failure,
        )
        expected_successor = _successor_import_successor_files(
            plan, status_data, source_files,
        )
        _successor_import_check_stage(stage, expected_successor, complete=False)
        if successor.exists():
            if source_here:
                raise LifecycleError(failure, "successor exists before source custody")
            _successor_import_check_stage(successor, expected_successor, complete=True)
        current_images = []
        for image in intent["images"]:
            path = _intent_path(repository, image["path"])
            before = base64.b64decode(image["beforeBase64"], validate=True)
            after = base64.b64decode(image["afterBase64"], validate=True)
            current = _read_lifecycle_image(
                path, before, after, failure_id=failure, require_single_link=True,
            )
            if current not in {before, after}:
                raise LifecycleError(failure, f"consumer image differs: {image['path']}")
            current_images.append((path, before, current))
        for path, before, current in current_images:
            if current != before:
                _atomic_write(path, before)
        if successor.exists():
            _remove_scratch_tree(successor)
        if stage.exists():
            _remove_scratch_tree(stage)
        if hold_here:
            source.parent.mkdir(parents=True, exist_ok=True)
            _replace_lifecycle_directory(hold, source)
        if stage_root.exists():
            _remove_scratch_tree(stage_root)
        _successor_import_release_stage_parent(stage_root)
        _remove_lifecycle_file(intent_path, failure_id="WI-LIFECYCLE-TRANSITION-INTENT-INVALID")
        _successor_import_source_bytes(source, plan, failure)
        return None
    except BaseException as exc:
        raise LifecycleError(
            failure,
            f"operation={operation} phase=recovery: {exc}",
        ) from exc


@functools.partial(_lifecycle_participant, subject_parameters=('category-slug', 'work-item', 'predecessor_slug'))
def apply_import_active_successor(
    root: Path, predecessor_slug: str, successor_slug: str, status_data: bytes,
    dispositions: dict, operation_id: str, preflight_digest: str,
    *, inject_failure_at: str | None = None,
) -> dict:
    """Settle one preflight-bound dual work-item identity through owner custody."""

    work_items = _work_items_root(root)
    repository = work_items.parent
    _validate_slug(predecessor_slug)
    _validate_slug(successor_slug)
    intent_path = _transition_intent_path(repository, operation_id)
    successor = work_items / "active" / successor_slug
    receipt_path = successor / SUCCESSOR_IMPORT_RECEIPT
    if intent_path.exists():
        raise LifecycleError(
            "WI-SUCCESSOR-IMPORT-RECOVERY",
            f"operation={operation_id} phase=pending-intent: recover-transition is required",
        )
    if receipt_path.exists():
        _verify_successor_import_settlement(
            repository, receipt_path,
            operation_id=operation_id, digest=preflight_digest,
            predecessor=predecessor_slug, successor=successor_slug,
            status_data=status_data, dispositions=dispositions,
        )
        return {
            "state": "committed", "alreadySettled": True,
            "receiptPath": receipt_path.relative_to(repository).as_posix(),
        }
    if successor.exists():
        raise LifecycleError("WI-SUCCESSOR-IDENTITY-CONFLICT", "successor is occupied without an exact receipt")
    if not isinstance(preflight_digest, str) or SHA256_RE.fullmatch(preflight_digest) is None:
        raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", "matching preflight digest is required")
    try:
        plan_result = preflight_import_active_successor(
            repository, predecessor_slug, successor_slug, status_data,
            dispositions, operation_id,
        )
    except LifecycleError as exc:
        if exc.failure_id == "WI-SUCCESSOR-IDENTITY-CONFLICT":
            raise
        raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", f"preflight input changed: {exc.failure_id}") from exc
    if plan_result["digest"] != preflight_digest:
        raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", "preflight digest differs")
    plan = json.loads(plan_result["canonicalBytes"])
    locations = _category_locations(repository, CATEGORIES["work-item"], predecessor_slug)
    archives = [path for path in locations if path.parent.parent == work_items / "archive"]
    if len(archives) != 1:
        raise LifecycleError("WI-SUCCESSOR-IDENTITY-CONFLICT", "archived predecessor is not unique")
    archive = archives[0]
    source = work_items / "active" / predecessor_slug
    source_files = _successor_import_source_bytes(source, plan, "WI-SUCCESSOR-IMPORT-DRIFT")
    _successor_import_archive_bytes(archive, plan, "WI-SUCCESSOR-IMPORT-DRIFT")
    expected_successor = _successor_import_successor_files(plan, status_data, source_files)
    images = _successor_import_images(repository, plan)
    hold_relative, stage_relative = _successor_import_stage_paths(operation_id)
    hold = _intent_path(repository, hold_relative)
    stage = _intent_path(repository, stage_relative)
    stage_root = hold.parent
    if stage_root.exists():
        raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "operation staging already exists")
    intent = {
        "schemaVersion": 1, "owner": SUCCESSOR_IMPORT_OWNER,
        "kind": SUCCESSOR_IMPORT_KIND, "status": "intent",
        "operationId": operation_id, "preflightDigest": preflight_digest,
        "sourcePath": source.relative_to(repository).as_posix(),
        "archivePath": archive.relative_to(repository).as_posix(),
        "successorPath": successor.relative_to(repository).as_posix(),
        "sourceHoldPath": hold_relative, "successorStagePath": stage_relative,
        "receiptPath": receipt_path.relative_to(repository).as_posix(),
        "plan": plan, "statusData": _b64(status_data), "images": images,
    }
    intent_bytes = _migration_receipt_bytes(intent)
    if len(intent_bytes) > TRANSITION_INTENT_FILE_BYTE_CAP:
        raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", "preflight plan exceeds intent byte limit")
    intent_path = _require_lifecycle_mutation_path(
        repository, intent_path, failure_id="WI-SUCCESSOR-IMPORT-RECOVERY",
    )
    _atomic_write(intent_path, intent_bytes)
    _transition_fsync_directory(intent_path.parent)
    phase = "stage-successor"
    try:
        for relative, data in sorted(expected_successor.items()):
            target = _require_lifecycle_mutation_path(
                repository, stage.joinpath(*PurePosixPath(relative).parts),
                failure_id="WI-SUCCESSOR-IMPORT-RECOVERY",
            )
            _atomic_write(target, data)
        _successor_import_check_stage(stage, expected_successor, complete=True)
        if inject_failure_at == "before-source-hold":
            raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "injected before-source-hold")
        phase = "revalidate-before-publish"
        rebound = preflight_import_active_successor(
            repository, predecessor_slug, successor_slug, status_data,
            dispositions, operation_id,
        )
        if rebound["digest"] != preflight_digest:
            raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", "bound inputs changed before publish")
        phase = "source-hold"
        _replace_lifecycle_directory(source, hold)
        if inject_failure_at == "after-source-hold":
            raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "injected after-source-hold")
        phase = "successor-publish"
        _replace_lifecycle_directory(stage, successor)
        if inject_failure_at == "after-successor-publish":
            raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "injected after-successor-publish")
        phase = "links-publish"
        for image in images:
            if image["path"] == "work-items/README.md":
                continue
            path = _intent_path(repository, image["path"])
            before = base64.b64decode(image["beforeBase64"], validate=True)
            after = base64.b64decode(image["afterBase64"], validate=True)
            if _read_lifecycle_image(path, before, failure_id="WI-SUCCESSOR-IMPORT-DRIFT") != before:
                raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", f"consumer drifted: {image['path']}")
            _atomic_write(path, after)
        if inject_failure_at == "after-links-publish":
            raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "injected after-links-publish")
        phase = "readme-publish"
        readme = next(row for row in images if row["path"] == "work-items/README.md")
        readme_path = _intent_path(repository, readme["path"])
        before = base64.b64decode(readme["beforeBase64"], validate=True)
        after = base64.b64decode(readme["afterBase64"], validate=True)
        if _read_lifecycle_image(readme_path, before, failure_id="WI-SUCCESSOR-IMPORT-DRIFT") != before:
            raise LifecycleError("WI-SUCCESSOR-IMPORT-DRIFT", "README drifted before publish")
        _atomic_write(readme_path, after)
        check_readme(repository)
        if inject_failure_at == "after-readme-publish":
            raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "injected after-readme-publish")
        phase = "receipt-publish"
        successor_tree = _successor_import_tree(successor)
        if dict(successor_tree) != expected_successor:
            raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "successor staged bytes differ")
        receipt = _successor_import_receipt(
            plan, preflight_digest, dispositions,
            _successor_import_tree_digest(successor_tree),
        )
        _atomic_write(receipt_path, _migration_receipt_bytes(receipt))
        _transition_fsync_directory(receipt_path.parent)
        if inject_failure_at == "after-receipt-publish":
            raise LifecycleError("WI-SUCCESSOR-IMPORT-RECOVERY", "injected after-receipt-publish")
        phase = "settlement-verify"
        _verify_successor_import_settlement(
            repository, receipt_path, operation_id=operation_id,
            digest=preflight_digest, predecessor=predecessor_slug,
            successor=successor_slug, status_data=status_data,
            dispositions=dispositions,
        )
        phase = "cleanup"
        _recover_successor_import(repository, intent_path, intent)
        return {
            "state": "committed", "alreadySettled": False,
            "receiptPath": receipt_path.relative_to(repository).as_posix(),
        }
    except BaseException as exc:
        if isinstance(exc, LifecycleError) and exc.failure_id in {
            "WI-SUCCESSOR-IMPORT-RECOVERY", "WI-SUCCESSOR-IMPORT-DRIFT",
            "WI-SUCCESSOR-LINK-UNMAPPED",
        }:
            if exc.failure_id == "WI-SUCCESSOR-IMPORT-RECOVERY":
                raise LifecycleError(
                    exc.failure_id,
                    f"operation={operation_id} phase={inject_failure_at or phase}: {exc}",
                ) from exc
            raise
        raise LifecycleError(
            "WI-SUCCESSOR-IMPORT-RECOVERY",
            f"operation={operation_id} phase={phase}: {exc}",
        ) from exc


def _successor_import_json_pairs(pairs: list[tuple[str, object]]) -> dict:
    result = {}
    for key, value in pairs:
        if key in result:
            raise LifecycleError("WI-SUCCESSOR-LINK-UNMAPPED", "link dispositions repeat a JSON key")
        result[key] = value
    return result


def _read_arg_file(path: str) -> bytes:
    return Path(path).read_bytes()


def _add_root(parser: argparse.ArgumentParser) -> None:
    parser.add_argument("--root", default=".", help="Repository or work-items root")


def _add_injection(parser: argparse.ArgumentParser) -> None:
    parser.add_argument(
        "--inject-readme-failure",
        choices=("after-canonical",),
        help=argparse.SUPPRESS,
    )


def _parse_partial_recovery_status_bindings(values: list[str]) -> dict[str, str]:
    bindings: dict[str, str] = {}
    for value in values:
        if value.count("=") != 1:
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
                "target status preimage must be <reference>=<sha256>",
            )
        reference, digest = value.split("=", 1)
        if (
            reference in bindings
            or reference not in PARTIAL_MIGRATION_RECOVERY_TARGETS
            or not re.fullmatch(r"[0-9A-Fa-f]{64}", digest)
        ):
            raise _partial_recovery_fail(
                "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
                "target status preimage bindings differ from the exact incident",
            )
        bindings[reference] = digest.upper()
    if set(bindings) != set(PARTIAL_MIGRATION_RECOVERY_TARGETS):
        raise _partial_recovery_fail(
            "WI-PARTIAL-MIGRATION-RECOVERY-COVERAGE",
            "both exact incident target status preimages are required",
        )
    return bindings


def build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    admit_v0 = sub.add_parser("admit-current-decision-v0", help="Capture or explicitly settle the first current V0 byte-compatibility admission")
    _add_root(admit_v0)
    for flag in ("policy-decision", "cutover-date", "expected-baseline-sha256", "expected-policy-sha256", "operation-id", "receipt"):
        admit_v0.add_argument(f"--{flag}")
    admit_v0.add_argument("--apply", action="store_true", help="Explicitly authorize create-only initial admission; omission captures only")
    pass_custody = sub.add_parser(
        "retain-pass-artifact", help="Retain exact admitted original bytes of one raw historical PASS; never append a verdict",
    )
    _add_root(pass_custody)
    for flag in ("slug", "run-id", "expected-raw-line-sha256", "expected-ledger-sha256", "source-artifact", "expected-original-sha256"):
        pass_custody.add_argument(f"--{flag}", required=True)
    pass_custody.add_argument("--raw-line-ordinal", type=int, required=True)
    pass_custody.add_argument("--apply", action="store_true", help="Explicitly authorize custody publication; omission refuses")
    for name in ("candidate", "start", "update", "close", "reopen"):
        command = sub.add_parser(name)
        _add_root(command)
        _add_injection(command)
        command.add_argument("--slug", required=True)
        if name == "candidate":
            command.add_argument("--file", required=True)
        elif name in {"start", "update"}:
            command.add_argument("--status-file", required=True)
        elif name == "close":
            command.add_argument("--closure-file", required=True)
            command.add_argument("--terminal-instant", required=True)
            command.add_argument("--allow-protected-uri-updates", action="store_true")
            command.add_argument("--legacy-evidence-file")
            command.add_argument("--apply", action="store_true",
                                 help="Apply the legacy-evidence close route only; ordinary close applies without this flag")
            command.add_argument("--inject-failure-at", choices=("after-promotion", "after-source-remove", "after-board"))
        else:
            command.add_argument("--successor-slug", required=True)
            command.add_argument("--status-file", required=True)
    convert_legacy = sub.add_parser("convert-legacy-candidate")
    _add_root(convert_legacy)
    _add_injection(convert_legacy)
    convert_legacy.add_argument("--slug", required=True)
    convert_legacy.add_argument("--file", required=True)
    retire_legacy = sub.add_parser("retire-legacy-backlog")
    _add_root(retire_legacy)
    _add_injection(retire_legacy)
    retire_legacy.add_argument("--slug", required=True)
    retire_legacy.add_argument("--disposition-file", required=True)
    retire_legacy.add_argument("--terminal-instant", required=True)
    refresh = sub.add_parser("refresh")
    _add_root(refresh)
    refresh.add_argument("--reset-static-guide", action="store_true")
    refresh.add_argument("--expected-readme-sha256")
    resolve = sub.add_parser("resolve")
    _add_root(resolve)
    target = resolve.add_mutually_exclusive_group(required=True)
    target.add_argument("--reference")
    target.add_argument("--legacy-path")
    audit_parser = sub.add_parser("audit")
    _add_root(audit_parser)
    audit_mode = audit_parser.add_mutually_exclusive_group()
    audit_mode.add_argument("--output")
    audit_mode.add_argument("--verify-migration")
    recover_transition = sub.add_parser("recover-transition")
    _add_root(recover_transition)
    recover_transition.add_argument("--operation-id", required=True)
    recover_transition.add_argument("--apply", action="store_true")
    migrate = sub.add_parser("migrate")
    _add_root(migrate)
    migrate_mode = migrate.add_mutually_exclusive_group(required=True)
    migrate_mode.add_argument("--reference")
    migrate_mode.add_argument("--inventory")
    migrate.add_argument("--incoming-links-inventory")
    migrate.add_argument("--allow-protected-uri-updates", action="store_true")
    migrate.add_argument("--apply-admitted", action="store_true")
    migrate.add_argument("--render-readme", action="store_true")
    migrate.add_argument("--byte-check", action="store_true")
    terminalize = sub.add_parser("terminalize-v1")
    _add_root(terminalize)
    terminalize.add_argument("--inventory", required=True)
    terminalize.add_argument("--terminal-at", required=True)
    terminalize.add_argument("--authorization-marker", required=True)
    terminalize.add_argument("--receipt", required=True)
    recovery = sub.add_parser("recover-partial-migration-v1")
    _add_root(recovery)
    recovery.add_argument("--inventory", required=True)
    recovery.add_argument("--expected-inventory-sha256", required=True)
    recovery.add_argument("--expected-readme-sha256", required=True)
    recovery.add_argument(
        "--target-status-preimage",
        action="append",
        required=True,
        help="Exact <reference>=<sha256> incident status preimage; repeat twice",
    )
    recovery.add_argument("--receipt", required=True)
    recovery.add_argument("--apply-admitted", action="store_true")
    recovery.add_argument("--render-readme", action="store_true")
    recovery.add_argument("--byte-check", action="store_true")
    normalize = sub.add_parser(
        "normalize-current-identity",
        help="Atomically replace one noncanonical current flat-record identity",
    )
    _add_root(normalize)
    normalize.add_argument("--category", required=True, help="Lifecycle category")
    normalize.add_argument(
        "--source",
        required=True,
        help="Repository-relative source path under work-items/",
    )
    normalize.add_argument(
        "--target-slug", required=True, help="Canonical replacement slug"
    )
    normalize.add_argument(
        "--inventory", required=True, help="Repository .scratch/ inventory path"
    )
    normalize.add_argument(
        "--receipt", help="Repository .scratch/ settled receipt path"
    )
    normalize.add_argument(
        "--prepare-only",
        action="store_true",
        help="Write the exact byte-bound inventory without mutating work-items",
    )
    normalize.add_argument(
        "--inject-failure-at",
        choices=("after-rewrites", "after-move", "after-readme"),
        help=argparse.SUPPRESS,
    )
    apply_legacy = sub.add_parser("migrate-legacy-ledger-obligation")
    _add_root(apply_legacy)
    apply_legacy.add_argument("--slug", required=True)
    apply_legacy.add_argument("--target-run-id", required=True)
    apply_legacy.add_argument("--target-event-sha256", required=True)
    apply_legacy.add_argument("--expected-ledger-sha256", required=True)
    apply_legacy.add_argument("--operation-id", required=True)
    apply_legacy.add_argument("--recorded-at", required=True)
    apply_legacy.add_argument(
        "--normalization-kind",
        choices=("invalid-finding-class", "remove-string-scratch-evidence"),
        default="invalid-finding-class",
    )
    apply_legacy.add_argument(
        "--inject-failure",
        choices=("after-anchor", "post-replace-corrupt"),
        help=argparse.SUPPRESS,
    )
    revoke_legacy = sub.add_parser("revoke-legacy-ledger-obligation")
    _add_root(revoke_legacy)
    revoke_legacy.add_argument("--slug", required=True)
    revoke_legacy.add_argument("--apply-run-id", required=True)
    revoke_legacy.add_argument("--apply-event-sha256", required=True)
    revoke_legacy.add_argument("--expected-ledger-sha256", required=True)
    revoke_legacy.add_argument("--operation-id", required=True)
    revoke_legacy.add_argument("--recorded-at", required=True)
    settle_legacy = sub.add_parser("settle-legacy-ledger")
    _add_root(settle_legacy)
